-- 自动生成：仅含中文译文与匹配指纹。来源见 SOURCES.md。
local D = TauriChineseDB
D.Strings[6930]="那些血精灵认为他们离控制这个世界只有一步之遥……"
D.Strings[6931]="看上去更像千里之外！"
D.Strings[6932]="别高兴得太早！"
D.Strings[6933]="尽力挣扎吧……"
D.Strings[6934]="你休想与命运抗争！"
D.Strings[6935]="你……不存在了。"
D.Strings[6936]="萨尔仍将是个奴隶。塔蕾莎会死去。你失败了。"
D.Strings[6937]="不！主人……不会……高兴的。"
D.Strings[6938]="我们是真正的部落！"
D.Strings[6939]="为了卡加斯！为了胜利！"
D.Strings[6940]="鲜血是我们的力量！"
D.Strings[6941]="伊利达雷是不可战胜的！"
D.Strings[6942]="这个世界是我们的！"
D.Strings[6943]="为了主人！"
D.Strings[6944]="伊利丹是世界的主宰！"
D.Strings[6945]="以纳沙塔尔的名义！"
D.Strings[6946]="我的血剧毒无比！"
D.Strings[6947]="朋友，我很荣幸来迎接你今日驾临神殿。"
D.Strings[6948]="对于我这个圣光的卑微仆从，阿达尔从来不会隐瞒任何知识。"
D.Strings[6949]="我的神圣使命要求我必须将这些真理分享给所有应该知晓它的人们。"
D.Strings[6950]="这让我得知，我们每个人的心中都有圣光……"
D.Strings[6951]="……这是一份礼物，一份赐予所有自然生灵的礼物。"
D.Strings[6952]="刚开始的时候，圣光以某种微妙的感觉昭示着它的教义。人们很容易忽视这种感觉，但是圣光依然指引着他们探索真理，并促使他们常行善事。"
D.Strings[6953]="真诚、仁慈、宽恕、奉献。这些都是圣光结出的硕果。"
D.Strings[6954]="圣光祝福那些接受感召的人们，这种赐福可能是有形的，也可能是无形的。"
D.Strings[6955]="随着个人信念的逐渐强化，他对圣光之力的驾驭就会愈发纯熟。"
D.Strings[6956]="经过时间的历练，越是服从圣光指引的人，就越能触及到圣光的声息，越能驾驭圣光的力量。"
D.Strings[6957]="圣光最忠实的追随者们拥有无上的治愈与祝福之力。"
D.Strings[6958]="悲哀的是，那些徘徊的死者蔑视圣光。"
D.Strings[6959]="圣光抛弃了那些执迷不悟的愚者，留给他们的是无尽的黑暗。"
D.Strings[6960]="在没有圣光的地方，绝望、厌恶和愤怒横行。"
D.Strings[6961]="我们出生在一个危险的时代，黑暗的力量誓要让我们走向毁灭。"
D.Strings[6962]="是在圣光之下寻找自我的时候了。"
D.Strings[6963]="聆听我的话语，感受存在于你们体内的圣光吧。"
D.Strings[6964]="%s开始发狂了，他的眼睛变得通红！"
D.Strings[6965]="你折腾得还不够吗？你非要把我从沉睡中惊醒吗？"
D.Strings[6966]="暴力就能解决一切吗？该做的事，我都做完了。我辜负了我的族人。"
D.Strings[6967]="拥抱你体内的圣光吧，我的朋友们！将所有的黑暗拒之门外……"
D.Strings[6968]="我们必须忍耐这些痛苦的时期，总有一天我们会找到属于自己的胜利。"
D.Strings[6969]="以纳鲁的名义，愿我们的愿望能够实现。"
D.Strings[6970]="愿我们的愿望能够实现。"
D.Strings[6971]="时机成熟了！古尔丹，命令你的术士们加倍努力！用不了多久，传送门就会打开，你的部落将在这个富饶而毫无防备的世界中所向披靡！"
D.Strings[6972]="你会光荣地死去的。"
D.Strings[6973]="不！我诅咒这具脆弱的躯体！"
D.Strings[6974]="勇士们！我的护盾正在减弱！"
D.Strings[6975]="我的能量必须集中在传送门上！我没有时间来增强护盾了！"
D.Strings[6976]="护盾快要消失了！我的一切努力随时都有可能付之东流！"
D.Strings[6977]="感谢你们的帮助，勇士们。古尔丹的部落将会像蝗虫一样席卷这个世界，我精心准备的计划也总算没有白费。"
D.Strings[6978]="毁灭降临了！"
D.Strings[6979]="以萨格拉斯的名义！"
D.Strings[6980]="你的末日到了！"
D.Strings[6981]="我必须这么做！"
D.Strings[6982]="燃烧军团是世界的主宰！"
D.Strings[6983]="我会得到奖赏的！"
D.Strings[6984]="一股冷风吹过你的脸颊，温和的蜂鸣声在大厅中环绕。"
D.Strings[6985]="你们为什么要帮助他？想想看吧，如果黑暗之门从未打开，如果那场战争从未爆发，有多少条生命可以避免死亡的厄运……"
D.Strings[6986]="如果你不中止这愚蠢的举动，那就去死吧！"
D.Strings[6987]="时间……在我们的掌握中。"
D.Strings[6988]="你们这是敬酒不吃吃罚酒，时间的守护者。滚开！"
D.Strings[6989]="我告诉过你这是个愚蠢的举动！"
D.Strings[6990]="这么快就要走了？"
D.Strings[6991]="你们为什么还要坚持下去？难道你们不明白这样做是毫无意义的吗？还不算太晚！你们仍然可以全身而退……"
D.Strings[6992]="那么开始吧。我已经警告过你们了。"
D.Strings[6993]="我的死亡……不值一提。"
D.Strings[6994]="时间的守护者！你们的时间之沙已经流尽了。"
D.Strings[6995]="你们早该逃走的。"
D.Strings[6996]="你们的死期到了。"
D.Strings[6997]="是时候毁灭这个秩序的世界了！让我们永远不再受到时间沙漏的制约！我警告你们：不愿迎接这一伟大时刻的蠢货，都将变成它的牺牲品！"
D.Strings[6998]="让我看看你们的命运将会如何……"
D.Strings[6999]="你的时间结束了，往日的奴隶。"
D.Strings[7000]="又少了一个障碍！"
D.Strings[7001]="没有人可以阻挡我们！没有人！"
D.Strings[7002]="什么……我变成了什么？啊……啊……"
D.Strings[7003]="寒冷的拥抱在等待……"
D.Strings[7004]="它为你而来……"
D.Strings[7005]="这不可能……"
D.Strings[7006]="这是什么骗局？我……啊……"
D.Strings[7007]="先祖们保佑着你，善良的人……"
D.Strings[7008]="加尔鲁什跟你说了些什么，$n？"
D.Strings[7009]="盖亚安祖母，加尔鲁什已经不可救药了。为了玛格汗的未来着想，我认为他已经不适合继续领导氏族了。"
D.Strings[7010]="<盖亚安祖母点了点头，接受了你的回答。>$B$B我不能再和灵魂战斗了，$n。我的时日已经不多了。我必须再次感谢你所做的一切，虽然你也许无法改变加尔鲁什，但我的很多人民已经由于你的努力而重新树立了信心。他们现在非常希望能为我们氏族的生存而战。"
D.Strings[7011]="我做了所有我能做的事情，祖母。感谢您的赞美之词。"
D.Strings[7012]="<盖亚安祖母对你笑了笑。>$B$B你让我想起了我的儿子，$n。$B$B他曾是一座雄伟的山脉，一个代表着力量和荣誉的支柱。$B$B<盖亚安的眼睛里闪烁着泪花。>$B$B他为了我们的生存牺牲了自己，为了让兽人后代们可以出生在一个没有血之诅咒……没有古尔丹和他的黑暗部落的世界。$B$B<盖亚安凝视着远方，发着呆。>$B$B杜隆坦……我多么希望你能在这里啊，你的人民需要你……"
D.Strings[7013]="盖亚安祖母，您是杜隆坦的母亲？"
D.Strings[7014]="<盖亚安祖母点了点头。>$B$B你认识我儿子？"
D.Strings[7015]="盖亚安祖母，我没有这个荣幸。杜隆坦在我出生前就去世了，但是他的英雄事迹传遍了我的世界。艾泽拉斯的兽人国家就以你儿子而命名，叫做杜隆塔尔，而且……<你停下来吸了一口气，考虑着你将要告诉盖亚安祖母的事情。>"
D.Strings[7016]="<盖亚安祖母的那双紫罗兰色的眼睛盯着你。>$B$B而且……？"
D.Strings[7017]="我们那个世界的酋长，我的同胞的领袖。他……他是杜隆坦的儿子。他是你的孙子。"
D.Strings[7018]="<盖亚安祖母泪如泉涌。>$B$B我……我……杜隆坦还有个孩子？德拉卡那孩子在他们离开前告诉我……他们最害怕的就是……让一个孩子在这样的世界中长大。那座门的对面曾是他们唯一的希望。我不敢告诉杜隆坦，但是暗地里，我祈求灵魂保佑他们——保佑他们的孩子，并赐予他们力量。$B$B我……我一定要看看我的孙子。我一定要看到他。请帮我这个忙，我太虚弱了。你必须在我离开这个世界前告诉他……"
D.Strings[7019]="我会马上回到艾泽拉斯的，祖母。"
D.Strings[7020]="真……丢人。"
D.Strings[7021]="跟苦工打交道都比这有趣！"
D.Strings[7022]="我已经有些厌倦了！"
D.Strings[7023]="你败了。"
D.Strings[7024]="啊，死吧！"
D.Strings[7025]="“虚空风暴”并非一直是现在这个样子。$B$B以前这块破碎的大陆叫做法兰伦平原，但是现在剩下来的只是很少一部分……"
D.Strings[7026]="$C，不要打了，这只是个伪装！我是沙塔斯城贫民窟的间谍。$B$B我希望你是来这里帮我的！"
D.Strings[7027]="在血精灵攻打紫罗兰之塔时，大法师瓦格斯让我逃出了那里，并把他的法杖托付给了我。我按照他的指示前往阿尔科隆，希望能在那处古老的德莱尼人的殖民地避难。$B$B然而，那里情况反而更糟，我来到了燃烧军团力量的风口浪尖。恶魔们把法杖夺走了，不过幸运的是，我留住了性命。$B$B尽管老师还不知道我的失败，但这仍然让我觉得非常羞愧。"
D.Strings[7028]="恕我直言，阿达尔派我来这里是为了调查凯尔萨斯的行动，而不是发动一次全力进攻。"
D.Strings[7029]="你瞧，甜心。我们没有人想要直接进攻风暴要塞，但要是机会就在眼前，为何不去拿下呢？"
D.Strings[7030]="闭嘴，你这混蛋！不要用那种语调和圣光的女祭司说话！"
D.Strings[7031]="我身边这些家伙都是白痴！"
D.Strings[7032]="魔导师会很高兴知道我对萨拉斯语很熟悉的。别摆出一副谦恭的模样，我不吃你这套。"
D.Strings[7033]="话过三句必跑题……我们应当把注意力放在这些法力熔炉上。我们需要知道敌人正在用它们做什么，以及为什么要这么做。"
D.Strings[7034]="真酷。"
D.Strings[7035]="嘘……"
D.Strings[7036]="我们是非常开诚布公的！你忘了我们中的许多人都曾经是凯尔萨斯最信任的手下吗？"
D.Strings[7037]="那笑话真好笑。"
D.Strings[7038]="我，好像，不太明白……"
D.Strings[7039]="……又来了！"
D.Strings[7040]="连你都必须承认你从背叛者那得来的信息是过时的，而且是不可靠的。我们应该有计划地进攻这些法力熔炉，并尽可能收集一切情报。"
D.Strings[7041]="老大终于发话了！"
D.Strings[7042]="好吧，看看虚空之风把谁吹来了。进来，坐下，休息一会。很便宜，你完全付得起。"
D.Strings[7043]="我们先杀别人吧！"
D.Strings[7044]="你急什么，白痴！"
D.Strings[7045]="你留在这里，我去杀别人！"
D.Strings[7046]="这一点都不有趣！"
D.Strings[7047]="哈哈哈。"
D.Strings[7048]="我烦了。"
D.Strings[7049]="烦了？他都快死了！"
D.Strings[7050]="他们从不休息吗？！$B$B如果我们要保障贫民窟人民的未来，我们就必须在暗影议会制造另一个白骨荒野之前解决掉他们！$B$B沙塔斯城的领导者是不会迅速决断的，所以我们贫民窟的自由民必须用自己的力量来解决这个问题。$B$B但是我们的间谍已经被发现了。当你潜入迷宫的时候，我们会拖延暗影议会的行动，希望你能发现一些什么。"
D.Strings[7051]="很久很久以前，在深不可测的宇宙维度中，一个拥有无上力量的生物诞生了——如果无上能描绘它那强大到难以置信的力量的话。在诞生的瞬间，它爆发出的能量粉碎了周围的一切事物。$B$B它就是摩摩尔，音之精华。听见它的声音就像体验湮灭的痛楚一样！"
D.Strings[7052]="不，我们不会让你活下来。"
D.Strings[7053]="嘿！"
D.Strings[7054]="你总是饿。所以我们才这么胖！"
D.Strings[7055]="我累了。你去杀下一个！"
D.Strings[7056]="这个一下子就死翘翘了。"
D.Strings[7057]="那是因为我出了好大的力气！"
D.Strings[7058]="都是……你的错！"
D.Strings[7059]="我……恨……你。"
D.Strings[7060]="哟！那是我的幸运帽。我一直在到处找它。"
D.Strings[7061]="我不能不穿披风出去。我希望它在这里……"
D.Strings[7062]="<继续读，如果你敢的话……>"
D.Strings[7063]="在这里！我发誓我上次没有把它放在这里……"
D.Strings[7064]="摩摩尔只为混乱而生，它最轻微的低语就意味着诸界的毁灭！$B$B尽管如此，这个冥顽的生物却不乏崇拜者。更荒诞的是，竟然有愚蠢的狂徒企图控制它！"
D.Strings[7065]="我不知道我在想什么，竟然没拿剑就出去了。如果我看到它在这里，我就会带上它了……"
D.Strings[7066]="没有一个好的睡前故事，我就睡不着。现在我肯定可以睡个好觉了。"
D.Strings[7067]="战斗吧，艾泽拉斯的勇士们，勇敢地战斗吧！你们的同胞会冲入这座地狱般的传送门，并很快像你们一样勇敢地对抗这些恶魔。圣光保佑你们！"
D.Strings[7068]="我的兄弟们，我的战友们！我必须去寻找部落的帮助，指引他们来到这里增援！勇敢的猎人们，顽强地战斗下去！不要被那些从黑暗之门涌出的恶魔击败！"
D.Strings[7069]="散发着霉味的书页似乎着魔一般翻动起来，你注意到法典中某个特殊的章节，上面的文字渗透出凡人难以察觉的恐怖气息。$B$B书页停止翻动，仿佛在指引你阅读摊开在你面前的这一页。你浏览着其中的内容，却发现它记载的是一段禁断的历史。"
D.Strings[7070]="瞧，所谓的强者战栗着跪拜在它面前，惟恐摩摩尔催动音波，令他们粉身碎骨。$B$B那些狂妄的家伙则假借崇拜之名组成了宗教组织，暗地里策划着如何控制他们的“神”，却不知道他们的野心注定会落空。摩摩尔对它的崇拜者毫不在意，不经意间打了个哈欠，他们就灰飞烟灭了。$B$B只有一人得以幸存，虽然这场浩劫令他神志有些错乱，但他却偶然发现了将摩摩尔召唤到这个世界的方法。"
D.Strings[7071]="这位侥幸逃生的凡人在黑暗法术上的造诣无人能及。他设计出某种灵魂装置，利用它们捕获灵魂来强化召唤仪式。$B$B这位魔法师和他的同谋们为了将摩摩尔召唤到这个世界，不惜灭绝了数个氏族文明，夺取了他们的灵魂来推进仪式的进程。"
D.Strings[7072]="他们果真召唤出了摩摩尔。$B$B魔法师企图利用强大的法术来抑制摩摩尔之音，并不断地夺取灵魂来维系法术的有效性。尽管如此，他们依然无法控制这个野蛮的生物，无法令它屈从于他们的意志。$B$B他们想出了各种方法想要制服摩摩尔，却无一例外地失败了。在试验这些方法的过程中，他们弱化了仪式的效果，意外地使摩摩尔看到了一丝自由的曙光。$B$B而这一丝曙光对摩摩尔来说已经足够了。"
D.Strings[7073]="在以后的那场大灾难中，只有这本法典得以保存下来。那些高傲而愚蠢的凡人妄图控制拥有无上力量的宇宙生物。$B$B而你呢？法典的拥有者，你会做出同样的蠢事吗？$B$B你是否已经想好了召唤摩摩尔的安全之策？这本邪恶的禁断之书还记载着其它神秘的宇宙生物，或许你对它们更感兴趣？$B$B我们等着瞧吧。"
D.Strings[7074]="嗨！很高兴可以看到新面孔——我平时没有太多的客人，而且那些技术员也不是那么健谈。$B$B我打赌你是要去52区，我说得没错吧？"
D.Strings[7075]="嗯……火红色的花瓣……嗯……"
D.Strings[7076]="……咕哝咕哝……"
D.Strings[7077]="……这上面好多刺……呃……哎唷！"
D.Strings[7078]="……正确地混合之后，也许……"
D.Strings[7079]="爆裂推进式多缸火箭航天局——简称为爆缸航天局——的指挥官弗斯拉格随时为你效劳。$B$B所有的系统都运行正常吗？！看上去X-52虚空火箭仍有很多准备工作要做！$B$B加油……我们的时间不多了！"
D.Strings[7080]="欢迎来到奥蕾莉亚要塞，$n。"
D.Strings[7081]="这是一个细活，你知道吗？做这项工作你不能操之过急，也不能判断错误。$B$B就像弗斯拉格的脑袋一样！$B$B你可能对我的机器人感到疑惑？我一直在研究麦克斯米林I型和麦克斯米林II型的脑容爆炸前所获得的智能！$B$B我决定忽略III型和IV型，直接去研究我为之骄傲和快乐的麦克斯米林V型。"
D.Strings[7082]="在废墟里面记得小心点，$c。肯瑞托之魂不会把你当作朋友的。$B$B只有我和管理员能与肯瑞瓦鬼魂沟通，即便他们已是魂灵，也会将我们视为朋友。"
D.Strings[7083]="肯瑞瓦在兽人的无数次冲击下生存了20多年，但是它并没有抵挡住凯尔萨斯的进攻。有一个叛徒，一个曾自称为肯瑞托一员的家伙，我们中除了大法师瓦格斯之外的人都被他杀害了。$B$B大法师瓦格斯从那次劫难中幸存了下来，因此凯尔萨斯把他囚禁在紫罗兰之塔内，用一种任何肯瑞托成员都无法通过的魔法屏障封印了紫罗兰之塔。"
D.Strings[7084]="请坐吧，不要拘束。"
D.Strings[7085]="嘿，你看见通缉令上的悬赏了吗？"
D.Strings[7086]="这个通缉令上写的是，他们会聘请那些所谓的冒险家来猎杀某些东西。我们不就是干这个的吗？我可不觉得我赚得够多了！"
D.Strings[7087]="这个通缉令在悬赏白骨秃鹫。你觉得我应该揭榜吗？"
D.Strings[7088]="白骨荒野！哪怕你给我再多报酬，我也不想去那个鬼地方！"
D.Strings[7089]="不如下班后去瞧瞧那份悬赏令？奖励不菲呀。"
D.Strings[7090]="不知道，我也不关心。"
D.Strings[7091]="你除了整天念叨那些悬赏令，还有点别的事情可做么？"
D.Strings[7092]="下班后我就去看看那份悬赏令。"
D.Strings[7093]="白骨秃鹫可不是好对付的。我听说它们都携带着污秽！"
D.Strings[7094]="我想赚点外快。"
D.Strings[7095]="把悬赏令的内容念给葛雷克听？$B$B葛雷克想要帮忙！"
D.Strings[7096]="谁过来给葛雷克读下这张通缉令。葛雷克不识字！"
D.Strings[7097]="你好，是什么风把你吹到这儿来的？$B$B这里的孤儿院专门收留那些在外域失去双亲、无人照看的孩子。$B$B也许你是来考虑领养的吧？"
D.Strings[7098]="啊，又一个强大的旅行者。虚空很危险，你会需要最强力的法术来任你支配。我这里有各种上好的材料，普通的和珍稀的都有。来吧，买点吧，你不会遗憾的！"
D.Strings[7099]="这个地方的生物非常强壮，旅行者。如果你想活下去的话，应该带好充足的弹药。你很幸运——我这里有大量的箭矢、子弹和投掷武器。如果你考虑一下周围的环境，我的价格还是非常合理的。"
D.Strings[7100]="一个商人，也许吧？你要补给的话只需要找我就好。我的价格十分合理，朋友。要知道，这些物品是很难搞到的，你就不要关心来源了好不好？总之，你会在这里找到你想要的。"
D.Strings[7101]="你的乐趣是什么？拉出一把椅子喝上一杯吗？$B$B我是布兹，爆缸航天局的首席调酒师和超级招待员！$B$B如果你要找乐子，就来找布兹！"
D.Strings[7102]="布兹，酒单给我。"
D.Strings[7103]="葛雷克，你想试试这些拉克妮亚做的新武器油吗？"
D.Strings[7104]="葛雷克试试！"
D.Strings[7105]="这油对葛雷克没什么用处！你觉得葛雷克看起来像什么？穿着长袍的弱者？"
D.Strings[7106]="我从未想过这个竟然是法力之油！肯定会热卖的，葛雷克！"
D.Strings[7107]="搬走它！"
D.Strings[7108]="你是加基森时报的记者吗？如果你跟着我，我会让你看看我的试验设备……$B$B<你告诉她你不是她所期盼的记者。>$B$B哦，你不是？那么好吧，如果你需要施法材料，就自己挑吧。我在等人呢。"
D.Strings[7109]="辐射？！$B$B不，你不用担心那些。天哪，这几天大家都这么认为。$B$B那么你对我们在这里的计划有什么看法？技术的巅峰，宝贝！你最好相信它。"
D.Strings[7110]="多年来我一直深信我们在银月城所做的事情是对的——为能到达外域而努力，那么我们就可以和凯尔萨斯重新会合。$B$B当我知道凯尔萨斯为我们准备了什么之后，我愿意还是待在鹰翼广场。"
D.Strings[7111]="两张醒目的悬赏单被钉在公告板上，一张是维勒老爹的悬赏，另一张是火箭主管弗斯拉格的。$B$B老爹的看上去是一个机械零件的悬赏，而火箭主管悬赏巨大的山脉巨人。$B$B两个悬赏令都是用晦涩难懂、歪歪扭扭的地精小篆书写的。"
D.Strings[7112]="在这里的公告板上钉着几张醒目的悬赏单。$B$B然而，难懂的条文很明显地告诉你，你还没有准备好。你应该以后再来看看！"
D.Strings[7113]="%s吸收了本次攻击的火焰能量。"
D.Strings[7114]="%s吸收了本次攻击的冰霜能量。"
D.Strings[7115]="%s吸收了本次攻击的自然能量。"
D.Strings[7116]="%s吸收了本次攻击的暗影能量。"
D.Strings[7117]="%s吸收了本次攻击的奥术能量。"
D.Strings[7118]="%s吸收了本次攻击的神圣能量。"
D.Strings[7119]="也许我应该召集其他人，在这次变动后向那里出发？"
D.Strings[7120]="唔，奥术歼灭者非常厉害，我怀疑维勒老爹是否知道他在悬赏什么？"
D.Strings[7121]="好消息是，我们周围都是有着多余机械部件的邻居。"
D.Strings[7122]="收割机？！它们不管用了，实在太落伍了。$B$B如果我们要制造火箭——如果我们要让X-52离开地面——我们就需要更尖端的技术！"
D.Strings[7123]="我只在一些低声的私语中听说过你的名字，法师。你是谁？"
D.Strings[7124]="我是卡德加，堕落的守护者麦迪文曾经的学徒。我相信你以前肯定听说过这个名字。$B$B是我发现麦迪文被邪恶的萨格拉斯支配，然后他就开启了这个世界和艾泽拉斯之间的黑暗之门。尽管我尊重我的主人，但我被迫消灭了他，让他痛苦的灵魂得到了解脱。"
D.Strings[7125]="我和安度因·洛萨爵士并肩战斗，把部落从我们艾泽拉斯驱逐了出去。作为麦迪文遗产的继承人，我只能这么做。$B$B当联盟最终决定远征这个阴森的世界，永久终止兽人的邪恶时，我和我的朋友图拉扬、奥蕾莉亚、达纳斯和库德兰挺身而出。"
D.Strings[7126]="我和我的伙伴们称自己为洛萨之子，以此来对我们所认识的最无私和最伟大的人表示尊敬。我们用尽全力击败耐奥祖，结束了他的疯狂。$B$B当这个被诅咒的世界在我们身边崩塌时，我们破坏了黑暗之门，以阻止更多的伤害降临到我们所深爱着的艾泽拉斯。"
D.Strings[7127]="我们被困在了这个破碎的世界，并努力生存了下来。随着时间的流逝，我们感觉到一股新的邪恶力量正在从扭曲虚空靠近我们，包围我们。那就是比黑暗的兽人更邪恶、想要占据外域的燃烧军团。"
D.Strings[7128]="当我的同伴在坚定不移地对抗逐渐逼近的黑暗时，我使用魔法进入了遥远的宇宙。在那里，我感受到了一种具有无穷圣光之力的生物……$B$B那就是阿达尔和他的纳鲁。那只能说是个……奇迹。"
D.Strings[7129]="<卡德加笑了笑。>$B$B我劝说阿达尔和他们的伙伴们和我一起回到这里。我相信只有他们的力量可以将燃烧军团赶出这个宇宙。但是,毫无疑问，就像你很快就会认识到的那样——他们的力量首先必须在我们的心中扎根。$B$B为了和黑暗进行斗争，我们必须成为他们永恒圣光的灯塔。"
D.Strings[7130]="我爱早晨虚空的味道。"
D.Strings[7131]="闻上去就像……"
D.Strings[7132]="……胜利。"
D.Strings[7133]="你想要点什么，$r？"
D.Strings[7134]="“杂学家”是什么？你应该问“杂学家”不是什么。这意味着是我研究世间万物！事实上我精通任何东西，我保证我是你所遇到过的最聪明的虚灵——否则我就把你的钱还你。$B$B对不起。那是我心灵中的商人本质在说话……"
D.Strings[7135]="我既不瘦也不黑。实话实说，这两个词都是对我的侮辱。$B$B现在，在我把法杖插到你后背上之前赶紧给我消失。"
D.Strings[7136]="啊，我注意到你是星界财团的朋友。也许你有兴趣买点东西？"
D.Strings[7137]="让我看看你都卖什么东西，“瘦子”。"
D.Strings[7138]="沙法尔真是个聪明的混蛋。他在入口装上了一些防护装置来阻止其他虚灵进入。我们正在想办法击溃他的防线，以便进去拿回属于我们的东西。我已经让最好的虚灵们在这里日以继夜地工作了。很快就可以打开它了。我的预感越来越强烈了……"
D.Strings[7139]="控制面板在轴承上转动着。"
D.Strings[7140]="<随便按下某个按钮。>"
D.Strings[7141]="不要用太多问题来麻烦阿达尔，$r。这个生物的意志是让我们的城市远离伤害的关键。"
D.Strings[7142]="跟我来，陌生人。这不会耽误你太长时间的。"
D.Strings[7143]="沙塔斯城曾经是德莱尼人在这个世界的首都。它的意思是“圣光的居所”。"
D.Strings[7144]="沙塔尔，或者说“生于圣光”，这个词是指来到外域和燃烧军团的恶魔们作战的纳鲁。"
D.Strings[7145]="永远不要低估其他虚灵的贪婪！"
D.Strings[7146]="然而好景不长，这座城市再次遭受了攻击。这次，发动进攻的是伊利丹的军队。伊利丹的同盟凯尔萨斯·逐日者派出了一大群血精灵来毁灭这座城市。"
D.Strings[7147]="血精灵们在城市守卫面前放下了武器。他们的首领，一个被称为沃雷塔尔的血精灵长者，冲进了圣光广场，要求和阿达尔对话。"
D.Strings[7148]="沃雷塔尔和他的追随者们的变节是凯尔萨斯有史以来所遭受到的最严重的损失。他们不是一群普通的血精灵，凯尔萨斯手下很多最睿智、最强大的学者和魔导师也被沃雷塔尔的影响力动摇了。"
D.Strings[7149]="奥尔多是圣光的追随者，宽恕和救赎是他们的信条。然而，他们却很难忘记血精灵在凯尔萨斯命令之下的所作所为。"
D.Strings[7150]="对沙塔斯城的进攻持续着，但是城市并没有沦陷，就像你看到的那样。相反，那个名叫克希利的纳鲁领导了一次成功的反击，一直打到了伊利丹的家门口——影月谷。"
D.Strings[7151]="卡德加应该准备好再次见你了。记住，如果你准备为沙塔尔效力，你很可能不得不与奥尔多或是占星者结盟。同样，对任何一方示好都会引起另外一方的敌意。"
D.Strings[7152]="带我们的客人去沙塔斯城里走走吧？路过贫民窟的时候小心你的钱包。"
D.Strings[7153]="当燃烧军团诱使兽人和德莱尼人反目成仇时，激烈的战斗就在这里爆发了。尽管德莱尼人浴血奋战，但最后，城市还是沦陷了。"
D.Strings[7154]="整座城市只剩下废墟和黑暗……直到沙塔尔来临。"
D.Strings[7155]="我们去贫民窟走走吧。我要提醒你，作为外域唯一的避风港，沙塔斯城吸引了成群的难民，无论是现在的战争所致，还是以往的战争所致。"
D.Strings[7156]="他们慕名来到沙塔斯城的废墟，一小群德莱尼传教士利用那里的一座废弃神庙传授着他们的教义。"
D.Strings[7157]="被称为奥尔多的那些传教士们，因为纳鲁回归和重建即将开始的传言而迅速恢复了生命力。废弃的神庙如今变成了治疗伤者的医务室。"
D.Strings[7158]="当时一大群血精灵跨过了这座桥，奥尔多的主教和守备官们筑起了人墙，保卫圣光广场。就在这时，意想不到的事情发生了。"
D.Strings[7159]="当纳鲁走近他时，沃雷塔尔跪在他的面前，说道：“我在我的梦境里看到过您，纳鲁。您是我的族群唯一的生存希望。我和我的部下愿意为您效劳。”"
D.Strings[7160]="纳鲁接受了这些叛节的血精灵，他们被称为占星者。他们住在上面的平台，只有他们的追随者才被允许踏足那里。"
D.Strings[7161]="许多传教士曾经被那些如今发誓效忠纳鲁的魔导师们杀死。他们对于和旧日的敌人同住在一座城市里面感到非常不悦。"
D.Strings[7162]="奥尔多最神圣的庙宇和它周围的小建筑坐落在上面的广场上。作为一个神圣的场所，只有他们的追随者才被允许进入那里。"
D.Strings[7163]="在奥尔多和占星者的协助下，他不断对伊利丹的军队发动着攻势。然而这两股势力并没有冰释前嫌。"
D.Strings[7164]="他们争先恐后地想要为纳鲁效劳，想要在纳鲁那里获得更多的荣耀。可是睿智的阿达尔却能让这两个氏族维系着微妙的平衡。每一天，双方的军队都聚集在这里，等待由阿达尔选择要派遣谁前往影月谷参战。"
D.Strings[7165]="祝你好运，陌生人，欢迎来到沙塔斯城。"
D.Strings[7166]="<影像的头部在环视周围时变得模糊起来。>$B$B如果你曾看到过法兰伦平原，你就不会相信眼下这个地方居然曾经是那种样子。仅仅几个月以前，这些原野看上去并不比西部荒野更糟糕。$B$B但是现在一切都不同了，这是怎么回事？到底为什么？"
D.Strings[7167]="这个地方比我想像的差多了。如果破坏以这个速度继续下去，法兰伦——呃，虚空风暴很快就会变成宇宙的尘埃。$B$B我在想，它要被破坏到何种程度才会停止？或许我应该问，“它会停止吗？”"
D.Strings[7168]="<大法师的影像似乎并没有看着你，而是注视着你的身后。>$B$B奥术能量的洪流使这个区域好像在被不可思议的力量拍打一样，这是日积月累的结果，而不是某一次灾难的产物。"
D.Strings[7169]="我要向凯尔萨斯复仇，为他对肯瑞托所做的暴行复仇！他曾经与我兄弟相称，但如今我们不再是兄弟了。$B$B我会找他算帐的。$B$B<大法师面沉似水地点了点头。>$B$B凯尔萨斯不仅仅是个无赖的法师。一旦我自由了，拉文德维尔和我会帮助任何与他为敌的人。"
D.Strings[7170]="我身后的宝珠曾经可以用来窥视艾泽拉斯正在发生的事。$B$B凯尔萨斯的诅咒改变了一切，当然，在这么多年的隔离中，很多法师通过它的影像得到了慰籍。$B$B风吹不散长恨，花染不透乡愁。"
D.Strings[7171]="如果你是来杀我的，请先去取个号，然后去排队。"
D.Strings[7172]="<大法师瓦格斯发出扭曲的笑容，对你示好。>$B$B被诅咒的紫罗兰之塔映着明月。$B$B风吹过云影似梦。"
D.Strings[7173]="在凯尔萨斯夷平村庄的那个晚上，我根本帮不上任何忙。他的魔法早已把我封印在塔中，让我只能眼睁睁地看着自己的同伴们一一惨死。$B$B他们的惨叫声至今仍在我耳边回荡，将我从午夜的噩梦中惊醒。"
D.Strings[7174]="低调！我不想让他们看到我在这里。$B$B哦，这真让我火冒三丈！这些虚灵觉得他们自己是谁？$B$B这是我的地盘！"
D.Strings[7175]="请让我一个人独自伤心流泪。"
D.Strings[7176]="小羊羔！小旅鼠！它们都在！"
D.Strings[7177]="%s变得不稳定起来，并开始瓦解！"
D.Strings[7178]="当火箭主管弗斯拉格寻求志愿者来帮助他建造X-52虚空火箭的时候，我向安全工程部门投递了简历。$B$B不幸的是，唯一剩下的职位只有主工程师了。对我来说幸运的是，有塞希罗在这里盯着我不要犯错。"
D.Strings[7179]="欢迎你，贫民窟自由民的朋友，但是不要在这里逗留太久。$B$B战斗的声音从里面传出，我的同胞需要你的帮助！"
D.Strings[7180]="如果你成为了贫民窟的朋友，也许我们可以做点生意？"
D.Strings[7181]="该好好给你上上家教课了，小$g子:姑娘;！"
D.Strings[7182]="在我数到“3”之前，滚出这里，否则小心我放狗咬你。"
D.Strings[7183]="是时候去见你的造物主了！"
D.Strings[7184]="你能相信虚灵的科技吗？！$B$B我当然愿意和他们待在这里。我会学到很多……也许还能给我自己弄一点！"
D.Strings[7185]="好吧，我们投降！不要伤害我们！"
D.Strings[7186]="跑吧，孩子。我还有事情要做……"
D.Strings[7187]="伊瑟基尔说你可能有那本书……"
D.Strings[7188]="物种：埃雷杜因"
D.Strings[7189]="所属阵营：燃烧军团"
D.Strings[7190]="职能：突击部队，执行者"
D.Strings[7191]="这些长着翅膀的畸形怪物强大而又谨慎，他们的残忍在整个宇宙中都臭名昭著。"
D.Strings[7192]="物种：艾瑞达"
D.Strings[7193]="物种：萨亚德"
D.Strings[7194]="物种：破坏魔"
D.Strings[7195]="物种：纳斯雷兹姆"
D.Strings[7196]="物种：安尼赫兰"
D.Strings[7197]="物种：莫尔葛"
D.Strings[7198]="职能：荣誉卫士"
D.Strings[7199]="职能：间谍，拷问者"
D.Strings[7200]="职能：女祭司，随军牧师"
D.Strings[7201]="职能：秘密警察，质问者"
D.Strings[7202]="职能：督军，战略家"
D.Strings[7203]="职能：将军，地面指挥官"
D.Strings[7204]="职能：修补工，机械师"
D.Strings[7205]="职能：工程师，科学家"
D.Strings[7206]="职能：普通士兵"
D.Strings[7207]="狡猾而纪律严明的愤怒卫士一直在保护着燃烧军团的艾瑞达主人们。"
D.Strings[7208]="残暴的萨亚德魅魔代表着燃烧军团的狡猾一面。"
D.Strings[7209]="这些女祭司非常虔诚，并拥有非凡的魅力，她们生存的意义就是传播萨格拉斯的意志。"
D.Strings[7210]="纳斯雷兹姆是通过吞噬普通生物以获得力量的残忍的恶魔。"
D.Strings[7211]="狡猾而强大的艾瑞达术士曾经是我们这个种族的贵族。"
D.Strings[7212]="这些庞大的毁灭者是燃烧军团的军事指挥官。"
D.Strings[7213]="这些矮小的莫尔葛是非常聪明的物种，并且经常被当作他们大个子同胞的帮手使用。"
D.Strings[7214]="尽管他们看上去很野蛮，但这些用铁缝合起来的可怕生物其实是非常聪明的工程师和铸造匠。"
D.Strings[7215]="他们是从莫尔葛种族中征募而来的战士，作为燃烧军团普通的士兵服役。"
D.Strings[7216]="感谢你的仁慈，晚饭时间快到了！"
D.Strings[7217]="我以为我死定了。"
D.Strings[7218]="我不知道是被邪兽人吃掉更糟呢，还是为拉泽克拉兹工作更糟？不管怎么样，还是谢谢你！"
D.Strings[7219]="据说，那些被奥金顿之魂保佑的人们拥有一种强大的能力，可以捕获以幽魂碎片形态出现的强大灵魂。在我的旅途中，我不经意间得到了几个幽魂碎片，但我至今还没解开它们的秘密。\n\n唯一我能洞悉的就是，它们似乎来自奥金顿的深处。如果你有机会得到这些幽魂碎片，我保证我会用让你觉得很有价值的东西来交换……"
D.Strings[7220]="借我一只双足飞龙。我要去断背岗哨！"
D.Strings[7221]="这座水晶建筑由于能量的流动不时地发出蜂鸣声。奇怪的符号在你面前闪烁，并快速地滚动着。"
D.Strings[7222]="忙啊，太忙了！事情太多，时间太少！$B$B我把那个合金扳手放哪了？我知道就在这里的某个地方……我刚才还被那东西烫了手指！"
D.Strings[7223]="这个世界的人民举行隆重的月亮庆典一点也不奇怪。我非常想去月光林地参加那个庆典。"
D.Strings[7224]="干这行，懂点魔法迟早有用。影像不能欺骗所有人，但是它们通常可以让你事半功倍。"
D.Strings[7225]="你在这里干什么？你不是应该在能量管道上工作吗？$B$B我们正在向风暴要塞传送两倍以上的能量，任何人都不能偷懒！我们不想看到这里变成另一个乌提斯。"
D.Strings[7226]="乌提斯？"
D.Strings[7227]="当然是法力熔炉：乌提斯！你以为是哪里？$B$B那个法力熔炉由于超过负荷而造成了大爆炸。事实上，它已经被完全摧毁了，而现在虚空生物正川流不息地在那里涌现，就在东北方向，到处都是。"
D.Strings[7228]="你在这儿应该很安全。法力熔炉：杜隆遭到攻击后我们便在此地增设了防御力量。"
D.Strings[7229]="谁攻击了法力熔炉：杜隆？"
D.Strings[7230]="法力熔炉：杜隆是离风暴要塞最近的设备，因此它处理着大部分的负载。$B$B你应该知道，这些法力熔炉的负载会引起管道泄露。散发出的能量吸引着讨厌的法力生物，我们在多个泄漏点遭受到法力生物的袭击，此刻法力熔炉：杜隆所遭受的攻击最为猛烈。"
D.Strings[7231]="向我讲述洛萨之子的事吧。"
D.Strings[7232]="采用这种技术进行工作让我非常头痛。所有东西都构造在一种怪异的方式上。"
D.Strings[7233]="很多年以前，我和我的部下追随着卡德加和图拉扬来到这个世界。我们唯一的目标是消灭兽人和他们卑鄙的同类。然而在战争的最后时刻，有些事情变得十分糟糕。$B$B最终，这个黑暗的世界变得支离破碎——而我亲爱的朋友们则消失在虚空中。"
D.Strings[7234]="<更多>"
D.Strings[7235]="我们，洛萨之子，从那时起就在这里坚持着，战斗……死亡……祈祷像今天这样的日子能早点到来，一个黑暗之门能够再次打开、我们的兄弟可以接我们回家的日子。$B$B虽然我们很高兴，但是职责仍然在召唤着我们。在我们离开这里享受安宁之前，仍然有很多事情要做。"
D.Strings[7236]="这项技术是从哪儿来的？"
D.Strings[7237]="他们没有教你们这些新来的家伙任何东西吗？这些法力熔炉是作为风暴要塞的一部分而建造的，用来吸取虚空中的能量。$B$B纳鲁用这个技术在旅途中给他们的飞船供给动力。有人说那技术在陆地上使用可能不安全，然而他们很快就沉默了。"
D.Strings[7238]="又一个前往荣耀堡的士兵……以库德兰的胡须之名，他们正需要你的帮助！"
D.Strings[7239]="送我到荣耀堡去！"
D.Strings[7240]="那是我的爱好，你知道。无论生死，铸造装甲都是我的最爱。请把我当作一个还活着的德莱尼人吧，陌生人。让我再次体会那种感觉吧……请让我修理你的物品。"
D.Strings[7241]="星界财团会对那些萨克希斯背叛者进行复仇的！"
D.Strings[7242]="啊，一个来帮助我们的新勇士？你说呢，$n？"
D.Strings[7243]="$n，洛萨之子曾经在这里，在地狱火半岛，战斗了整整二十年。我们被这里的兽人和燃烧军团的恶魔们困扰着，虽然我们心中仍充满激情，但年复一年的战斗让我们的人手越来越少。$B$B你，从艾泽拉斯赶来的新一代的英雄，我们欢迎你的到来！"
D.Strings[7244]="告诉我一些关于地狱火兽人的事吧。"
D.Strings[7245]="兽人。看来我一辈子都要和他们作战了。$B$B二十年以前，我们击败了部落，推倒了地狱火堡垒的城墙。我们把那些卑鄙的绿怪物逼了毁灭的边缘！在那以后，除了少数冲突以外，那些堕落的兽人们再也没有对我们构成任何威胁。$B$B直到现在。"
D.Strings[7246]="还！有！谁！"
D.Strings[7247]="你们时日不多了！"
D.Strings[7248]="你们不值一提！我只听从主人的召唤……"
D.Strings[7249]="黑暗的主宰在嘲笑你们！"
D.Strings[7250]="结束了！"
D.Strings[7251]="你完蛋了！"
D.Strings[7252]="我的主人……会毁灭你们的！"
D.Strings[7253]="快治疗我！"
D.Strings[7254]="退后，小崽子！"
D.Strings[7255]="说再见吧！"
D.Strings[7256]="太轻松了。"
D.Strings[7257]="看看这是谁？"
D.Strings[7258]="可能有点疼……"
D.Strings[7259]="我喜欢战斗……"
D.Strings[7260]="我们要战斗到最后一刻！"
D.Strings[7261]="我会让你死得痛快点的……"
D.Strings[7262]="结束了。"
D.Strings[7263]="干得……好。"
D.Strings[7264]="听从我的命令！马上把他们都杀掉！"
D.Strings[7265]="欢迎来到荣耀堡，$n。你能来真是太好了。"
D.Strings[7266]="大概二十年以前，联盟展开了对这个世界的第一次远征，希望可以永久根除兽人的威胁。那是一场……可怕的战争。很多勇敢的灵魂为保证艾泽拉斯的安全牺牲了。$B$B有些灵魂仍然……滞留在这无尽的战斗中。"
D.Strings[7267]="大概二十年以前，联盟展开了对这个世界的第一次远征，希望可以永久根除兽人的威胁。那是一场……可怕的战争。很多勇敢的灵魂为保证艾泽拉斯的安全牺牲了。$B$B谢谢你让那些灵魂安息，$n。"
D.Strings[7268]="荣耀堡的人们在这块恶魔横行的土地上浴血奋战，献出了他们的青春……而如今他们仍然激情不退！$B$B现在你和从艾泽拉斯来的军团可以帮助我们扭转局面。是你给了我们重返家乡的希望。"
D.Strings[7269]="给我讲讲你的家乡。"
D.Strings[7270]="太迷人了。这是什么，安多尔姆？"
D.Strings[7271]="一些非常非常烦人的事情。它们越来越频繁地穿越时间流了。"
D.Strings[7272]="唔，他们正在破坏时间流吗？"
D.Strings[7273]="诺萨莉，我不是在谈论某个想要通过微调过去来提升他现世地位的贪婪巫师。"
D.Strings[7274]="亲爱的，这些家伙并不是想给他们自己搞到暴风城彩票的幸运数字这么简单。"
D.Strings[7275]="我很讨厌你用那种态度和我说话。我和你在任何方面都是平等，兄弟。记住下次当你困在时间漩涡里的时候，不要哭着求我。"
D.Strings[7276]="对不起，诺萨莉，我最近有点急躁。这些生物正企图改变时间流。"
D.Strings[7277]="你还记得上次发生同样的事吗？希望主人不需要被卷入此事。"
D.Strings[7278]="我们应该这样希望吗？"
D.Strings[7279]="当然不。我们不能把自己卷入危险中去。主人不在的情况下，我们都要确保时间流完整无缺。艾泽拉斯的英雄们和冒险者们估计马上就要来了……"
D.Strings[7280]="%s点了点头。"
D.Strings[7281]="作为星界财团的代表，我一直留意生意伙伴与我们的关系。$B$B不幸的是，血精灵并没有给他们的伙伴以足够的尊重。"
D.Strings[7282]="我身边的弟弟是星界财团的后起之秀。当然，他太谦虚了，甚至要拒绝这种光荣。"
D.Strings[7283]="当他称我为“弟弟”的时候，他忘记提起我们是双胞胎了。他只不过比我早出生那么几分钟而已。$B$B不要让什么“后起之秀”蒙敝你。我永远无法成为他那样的商人。"
D.Strings[7284]="%s请求支援！"
D.Strings[7285]="你会后悔的！"
D.Strings[7286]="你好啊，$r。我在这里做的事情已经是另一个故事了。哎呀，那不是个好故事。$B$B我和我的兄弟都被困在这里，被夹在我们的时代和现在之间。我们不敢离开这里，因为我们害怕这可能会引起时间的矛盾。我们只有耐心等待青铜龙把我们送回原来的世界去。$B$B你问还要多久？我真的不知道。问问我兄弟吧。$B$B要来点奶酪吗？"
D.Strings[7287]="奶酪，嗯？那会不会是一块……陈年的奶酪了？"
D.Strings[7288]="不……好……"
D.Strings[7289]="我似乎选择了个错误的日子来戒除法力吸取……"
D.Strings[7290]="不，你没有听错。我确实是有个年轻女兽人的声音。但是你听好了，$g小子:姑娘;，时间旅行会给身体带来奇怪的反应。$B$B顺便说一句，这已经是第250年了。"
D.Strings[7291]="我需要些毒药与材料，女士。"
D.Strings[7292]="还算有两下子。"
D.Strings[7293]="嗯，从我能记事开始，我就在这里了。$B$B在我以前的生活中，我是个铁匠。也许我可以帮你修点什么？"
D.Strings[7294]="我需要修理。"
D.Strings[7295]="终于有人和我说话了！想听几首我作的诗吗？"
D.Strings[7296]="沿街！行走！绿叶纵有千片哟，也要化为泥土。"
D.Strings[7297]="这个虚灵传送台上有好几个刷着亮漆的按钮和开关，但看上去已经废弃了。"
D.Strings[7298]="瞧一瞧看一看啊，我的朋友！无论大小，无论你需要什么，哈斯辛这里应有尽有。$B$B如果你珍惜你的生命，没有补给就不要靠近法力熔炉：乌提斯。哈斯辛是你最后的机会。"
D.Strings[7299]="商人哈斯辛，你在卖些什么？"
D.Strings[7300]="%s召唤出他的座狼。"
D.Strings[7301]="我们会找到节点亲王哈拉迈德想要的东西，对此我很有信心。"
D.Strings[7302]="%s醒了过来，一脸震惊。"
D.Strings[7303]="这……这是梦吗？秘蓝岛，秘血岛，赞加沼泽，影月……甚至是祖阿曼……杰恩！杰恩你在哪里！"
D.Strings[7304]="啊，太好了。那一切只是场梦……"
D.Strings[7305]="我在这里，爸爸。你睡了一整天了。你一定是太累了！"
D.Strings[7306]="%s又去海滩玩耍了。"
D.Strings[7307]="我已经自由了！"
D.Strings[7308]="这一天来得太晚了！让开！"
D.Strings[7309]="我不再是奴隶了！"
D.Strings[7310]="布莱克摩尔要为此付出代价！"
D.Strings[7311]="是你逼我的！"
D.Strings[7312]="你不该阻拦我的！"
D.Strings[7313]="这不是我想要看到的事情！"
D.Strings[7314]="我欠你们的情，陌生人。"
D.Strings[7315]="谢谢你们，陌生人。你们给了我希望。"
D.Strings[7316]="我不会浪费这个机会的。我要找到自己真正的命运。"
D.Strings[7317]="形势不妙……"
D.Strings[7318]="我会战斗到最后一刻！"
D.Strings[7319]="塔蕾莎……"
D.Strings[7320]="结束了……"
D.Strings[7321]="我们才是真正的部落！唯一的部落！"
D.Strings[7322]="我这“刃拳”的名号可不是白来的！"
D.Strings[7323]="为了真正的部落而战！"
D.Strings[7324]="我是唯一的酋长！"
D.Strings[7325]="真正的部落……会获胜的。"
D.Strings[7326]="很好，我们出发吧！"
D.Strings[7327]="我不会再成为奴隶了！"
D.Strings[7328]="我从来没见过像虚空龙那样的生物。他们似乎继承了祖先的性格，但他们已经变得完全不同了。"
D.Strings[7329]="这里的大地依然留有鲜血的余温。啊，恶魔飞奔着穿过黑暗之门，与艾泽拉斯的英雄们杀得昏天暗地，我真想亲眼看看这一幕。那会是多么宏大的一场战斗啊！$B$B但是现在，更多更猛烈的战斗正在另一端进行着！"
D.Strings[7330]="如果你是沿着这条路出去的话，那你肯定够胆去法力熔炉：艾拉附近冒险了。$B$B在你出发前买点东西吧？"
D.Strings[7331]="你都卖些什么，图鲁曼？"
D.Strings[7332]="在这个世界上只有3种人：竞争者，顾客和雇员。竞争者会被无情地碾碎，顾客需要被满足，而雇员则应该被严格地管理。$B$B不受约束的承包者是一个神话。他们希望得到比雇员更多的回报，但是要像顾客一样对待他们。永远都不要相信自称是承包者的人。"
D.Strings[7333]="你们……等着瞧。"
D.Strings[7334]="死吧！蠢货！"
D.Strings[7335]="我胜利了！"
D.Strings[7336]="我不会被打败的！"
D.Strings[7337]="你们竟敢跟我作对？"
D.Strings[7338]="你们死定了！"
D.Strings[7339]="Achor she-ki！吞噬他们的躯体！"
D.Strings[7340]="尝试联系星界商人玛里德。"
D.Strings[7341]="迷乱你的心智。"
D.Strings[7342]="凝视你灵魂中的黑暗吧。"
D.Strings[7343]="这里……是我的归宿。"
D.Strings[7344]="你会付出生命的代价！"
D.Strings[7345]="你无路可逃了！"
D.Strings[7346]="忏悔吧！"
D.Strings[7347]="这里就是你的坟墓！"
D.Strings[7348]="永远留在这里吧。"
D.Strings[7349]="%s开始施放强大的治疗法术！"
D.Strings[7350]="多傲慢啊！多自大啊！你觉得你可以在我的门口打败我吗？"
D.Strings[7351]="你好，$n。我会带你游览时光之穴。请跟紧我。"
D.Strings[7352]="我们不知道时光之穴是否一直都允许凡人进入。确切的说，我们不可能知道这一点，因为时光之王在永远地运动着，用他认为恰当的方式来改变我们的时间流。也许你现在所看到的东西，明天就不存在了。你也可能会在昨天醒来，然后对这个地方没有丝毫的印象。"
D.Strings[7353]="这很奇怪，我知道……大部分凡人无法真正理解他们在这里看到的东西，他们所看到往往无法和他们的理解联系起来。"
D.Strings[7354]="作为时间的管理者，我们看管和照顾着诺兹多姆的领地。主人目前不在这里，这就意味着他正在尝试着剧烈地改变时间进程。主人向来不理会凡人的闲事，除了纠正其他人对时间的改变。他是非常反对这种行为的。"
D.Strings[7355]="对于普通的时间维护工作，时光守护者的力量是足够的。我们可以处理大部分普通的干扰。举个小例子来说，比如某些无赖法师们试图改变过去的一些东西来提升他们现在的身份和财富之类的事情，不在话下。"
D.Strings[7356]="你看到的这些隧道被称为时间流。它们的数量是无穷的。当前在你们的现实中存在的那个就是主人所认为的“麻烦点”。这些麻烦点也许有着完全不同的内容，但是它们通常都有着相同的原因。它们的存在是同样的时间干扰所产生的结果，当你进入其中的一个麻烦点去冒险时，要牢记这一点……"
D.Strings[7357]="时间流目前是按照“小灾难”至“大灾难”的顺序排列着的。注意它们全部都是“灾难”，这意味着任何一个时间流的毁灭都会终结你们的世界，没有区别。我们把它们这样分类，只是为了让那些被派到这里来的英雄们和冒险者们知道自己的能力适合处理哪个时间流中的事务。"
D.Strings[7358]="这个时间流目前正处于极度的混乱中！我们派了一些人在里面努力恢复秩序。我所能告诉你的一点信息就是，萨尔的自由正在危难中。一个被称为永恒之龙的邪恶组织正在尝试阻止他的逃脱。我担心如果没有来自外界的帮助，一切都将无可挽回。"
D.Strings[7359]="关于这个时间流，我们只得到了很少的一点情报。萨艾特已经被派遣进去了。从和他的通信中，我们获知的情报是永恒之龙再次尝试改变时间。很可能他们的目标是破坏黑暗之门的开启？希望不是这样……"
D.Strings[7360]="这个时间流通向海加尔山，我们只知道这些。永恒之龙不顾一切地阻止我们的介入，因此我们对其它的事情丝毫没有头绪，凡人。索莉多米正在尝试着突破时间流的防守，但是迄今都没有成功。你或许是我们突破和解决这个冲突的唯一希望。"
D.Strings[7361]="我们的时间正处在危险的边缘，$n。如果运气这种东西确实存在的话，我祝你好运。"
D.Strings[7362]="在这里只有两条真理：首先，时间是混乱的，永远在不停地变化，并且可以完全改变。第二，感觉并不代表真实。"
D.Strings[7363]="请跟着我。"
D.Strings[7364]="这个时间流在塌缩后实现了重组，回归于往昔的斯坦索姆。什么样的事件正在其中上演呢？"
D.Strings[7365]="罪有应得！"
D.Strings[7366]="你的朋友很快就会去找你了！"
D.Strings[7367]="祝你们……好运。你们会需要好运气的。"
D.Strings[7368]="你们不能让他挣脱！"
D.Strings[7369]="无知的蠢货！"
D.Strings[7370]="你们这些蠢货！他会把我们全都杀掉！"
D.Strings[7371]="我的工作不能中断！"
D.Strings[7372]="也许我可以好好利用你……"
D.Strings[7373]="愤怒……仇恨……我可以利用的工具。"
D.Strings[7374]="我们来看看你能被改造成什么样子！"
D.Strings[7375]="抵抗是没有意义的。"
D.Strings[7376]="离我……远点！"
D.Strings[7377]="深渊将会吞噬你们！"
D.Strings[7378]="迎接你们的末日吧，地面上的蠢货！"
D.Strings[7379]="你们会淹死在鲜血中！"
D.Strings[7380]="下地狱吧！"
D.Strings[7381]="为了女王和主人！"
D.Strings[7382]="我们的女王……会消灭你们的。"
D.Strings[7383]="你们有苦头吃了！"
D.Strings[7384]="等死吧，草包们！"
D.Strings[7385]="我要出手了！"
D.Strings[7386]="我要给你们一些苦头吃！"
D.Strings[7387]="你玩完了，蠢货！"
D.Strings[7388]="我比你强！"
D.Strings[7389]="去死吧，白痴！"
D.Strings[7390]="打败了我的卫兵，就以为自己已经足够强大了吗？我们的工作成果是不容你们损害的！"
D.Strings[7391]="还没完呢……"
D.Strings[7392]="你们小命不保了！"
D.Strings[7393]="我藐视你们这些低等生物！"
D.Strings[7394]="没用的东西！"
D.Strings[7395]="为了……瓦丝琪女王！"
D.Strings[7396]="我有自己的—呱嘎—宠物！"
D.Strings[7397]="嗯……该我行动了！"
D.Strings[7398]="不错的宠物，哈哈……呱呱嘎！"
D.Strings[7399]="不错的宠物，但是有武器就—嘎嘎—不太好了！"
D.Strings[7400]="对，生命是短暂的，嘎嘎呱！"
D.Strings[7401]="嗯……你自由了。呱！"
D.Strings[7402]="啊……没有了生命，没有了痛苦。嘎！"
D.Strings[7403]="小心，凡人。穿过这座大厅之后，你将面对在你的世界里从未听说过的危险。小心点……"
D.Strings[7404]="很高兴再次见到你，$n。想让我带你去主人的巢穴吗？"
D.Strings[7405]="请带我去主人的巢穴。"
D.Strings[7406]="阿拉希盆地被污染者侵占了。你会帮我们作战吗，$n？"
D.Strings[7407]="很高兴能在这个偏远的地方看到奥尔多的朋友。我恐怕自己无法再忍受这些精灵傲慢的话语了。"
D.Strings[7408]="去吧，$n，去阿拉希盆地勇敢地战斗吧！"
D.Strings[7409]="战歌峡谷的入口就在你的前面。你会和这些肮脏的联盟战斗到底吗？"
D.Strings[7410]="你好啊，$c。即使是现在，部落还在进攻战歌峡谷。你会和联盟并肩而战吗？"
D.Strings[7411]="你在这里干什么？！去奥特兰克山谷吧，那里需要你！"
D.Strings[7412]="野猪粪！为什么当我自己可以上阵杀敌的时候，却让我站在这里指引别人去奥特兰克山谷？你！你去跟联盟打过仗了吗？"
D.Strings[7413]="森林在为变革的种子而歌唱，但也还在因为痛苦而哭号。$B$B德莱尼人是我们的新朋友，他们像你一样在帮助我们。我们必须阻止那些兽人继续摧毁我的树木兄弟和姐妹。否则，灰谷将不复存在。"
D.Strings[7414]="请饶我一命！我会告诉你埃雷利恩的秘密。"
D.Strings[7415]="你要什么？我不是个喜欢闲聊的人。"
D.Strings[7416]="魔导师卡尔琳达让我来问你关于埃雷利恩的秘密。他是不是在外面跟别人幽会？"
D.Strings[7417]="如果你觉得我会这么轻易背叛我的朋友，那你就大错特错了！来吧，你这个无赖！"
D.Strings[7418]="我现在正忙着讨论一个贿赂计划。你不如晚点过来吧？"
D.Strings[7419]="我已经安排送你去法力熔炉：库鲁恩的事宜了。你准备好了吗，$n？你会降落在敌人的防守线后方，所以请确保你带了所有必需的东西。"
D.Strings[7420]="我完全准备好了。"
D.Strings[7421]="艾吉斯不会……呱嘎……不会死…"
D.Strings[7422]="死吧！嘎！别想动我的宝贝！"
D.Strings[7423]="嗯，你们想跟艾吉斯开战？呱嘎！"
D.Strings[7424]="艾吉斯杀了你们，呱嘎嘎！杀了你们！"
D.Strings[7425]="咕呱——嘎！休想逃走！"
D.Strings[7426]="呱嘎！宝贝，对，强大的宝贝！力量，无穷的力量。呱嘎嘎！宝贝中的力量！嘎嘎！"
D.Strings[7427]="我要……吞噬你的灵魂。"
D.Strings[7428]="这里……充满了活力。"
D.Strings[7429]="不要……抵抗。"
D.Strings[7430]="我……更强大了。"
D.Strings[7431]="更多……还要更多。"
D.Strings[7432]="再次……回到虚空。"
D.Strings[7433]="我必须……说再见了。"
D.Strings[7434]="恕不远送。"
D.Strings[7435]="这场战斗……很有趣。"
D.Strings[7436]="我们还没有互相作自我介绍呢。"
D.Strings[7437]="一场史诗般的战斗，多么激动人心啊！"
D.Strings[7438]="我多么渴望能有一次真正的冒险！"
D.Strings[7439]="我有一些很棒的东西要展示给你们……"
D.Strings[7440]="这是怎么回事？请原谅，但是我没有料到会有人来拜访。正如你们看到的，我们现在有别的事情要忙。不过没关系，作为一个热情的主人，我会用自己的方式招待你们……"
D.Strings[7441]="%s看着$n，开始变大！"
D.Strings[7442]="%s的力量消失了。"
D.Strings[7443]="欢迎来到风暴尖塔，$c。$B$B请不要因为我以影像的形式出现而感到厌恶。我的很多敌人都想让我死，所以这只是个防范措施。$B$B我保证你在这里会很安全的。"
D.Strings[7444]="我会让你也开始工作的，你这个废物。"
D.Strings[7445]="你想买什么东西吗？还是想卖什么东西？$B$B这就是我们出现在这里的原因，我的朋友。$B$B请告诉我你的想法吧。"
D.Strings[7446]="商人杜纳尔，我想看看你的货物。"
D.Strings[7447]="什么？！你不觉得我能成功吗？只要我拿到了我的零件……我会证明给你看的。"
D.Strings[7448]="哈哈，这真是太有趣了，不是吗？"
D.Strings[7449]="它动了！我发誓，我看到它动了！"
D.Strings[7450]="哎唷！不对。"
D.Strings[7451]="你是刚从艾泽拉斯世界到这边来的吧？你最好武装好自己，$c。这里的危险和部落之前所面对的大不一样。我是纳兹格雷尔——伟大的酋长萨尔的左右手。我很荣幸他让我负责保证这支勇敢的远征队的安全，以所有的灵魂之名，我会出色地完成任务！"
D.Strings[7452]="送我去萨尔玛！"
D.Strings[7453]="你好啊，我的$g兄弟:姐妹;！欢迎来到外域。部落需要聚集这块破碎的世界中一切可以聚集的力量。我保证，如果你是为荣耀之战而来，你必定会在这里得到满足。"
D.Strings[7454]="动作快点，$c。战斗已经在这里打响了，难道你还没注意到？"
D.Strings[7455]="永远都不要低估他们的战斗能力。"
D.Strings[7456]="她们的乐趣就是给别人造成痛苦，她们致人于死地的审问方式是非常可怕的。"
D.Strings[7457]="这些恶魔是燃烧军团远征中的驱动力量。"
D.Strings[7458]="他们利用恐怖和诡计让兄弟之间互相残杀，以他们的黑暗力量毁灭诸界。"
D.Strings[7459]="停下！不要再往前走了，凡人。你还没有做好面对永恒之龙的准备。过来，让我帮帮你。"
D.Strings[7460]="由于与生俱来的玩世不恭，他们喜欢使用自己那不成熟的科技手段。"
D.Strings[7461]="他们所制造的黑色机械在无数世界中播种了死亡。"
D.Strings[7462]="嗯，血槌啤酒！"
D.Strings[7463]="哦，还有一场表演？太好了……"
D.Strings[7464]="%s深深叹了口气，瞟了萨根一眼。"
D.Strings[7465]="那么，我的下一个戏法……"
D.Strings[7466]="给我们看看你的戏法，拉文德维尔！"
D.Strings[7467]="真是太精彩了！好吧，伙计们，我们去喝点什么吧。"
D.Strings[7468]="看，我会喷火！"
D.Strings[7469]="我会把我的朋友，萨根，变成某种令人吃惊的东西！"
D.Strings[7470]="感谢大家的观看！如果你们明天能带上一些零钱来看表演的话，我会非常感激的。"
D.Strings[7471]="一只臭鼬！啊…………！不要碰我！"
D.Strings[7472]="把它弄走！"
D.Strings[7473]="赶快来帮帮我，你们这群蠢货！"
D.Strings[7474]="可悲的凡人，你们要付出巨大的代价。"
D.Strings[7475]="终于可以解解闷了！"
D.Strings[7476]="你怕死吗？"
D.Strings[7477]="这是我最喜欢的部分……"
D.Strings[7478]="不要……得意，凡人。"
D.Strings[7479]="快来帮我！帮助你们的主人！"
D.Strings[7480]="我要用你的血当祭品！"
D.Strings[7481]="你是个绝佳的榜样！"
D.Strings[7482]="很好，一个完美的祭品！"
D.Strings[7483]="我很荣幸。"
D.Strings[7484]="你的死亡是为了更崇高的目标……"
D.Strings[7485]="我很高兴……能献出自己的生命。"
D.Strings[7486]="让我离开这里！伙计们……人呢？"
D.Strings[7487]="哦，他待你真好！"
D.Strings[7488]="你不是一直跟我们说要冷静的吗？"
D.Strings[7489]="一个简单而好笑的笑话。"
D.Strings[7490]="欢迎你，冒险者。在进入黑色沼泽之前，请先听一下我的警告。"
D.Strings[7491]="萨艾特，我遗失了我的时空道标，请再给我一个！"
D.Strings[7492]="啊，欢迎回来，英雄。你是再次回来保护麦迪文的吗？不要忘记带上一个时空道标！"
D.Strings[7493]="我需要一个时空道标，萨艾特。"
D.Strings[7494]="你好，$n。要保持警惕……"
D.Strings[7495]="将在三十秒后紧急停机。"
D.Strings[7496]="将在十秒后紧急停机。"
D.Strings[7497]="法力熔炉停机中断。恢复法力熔炉运作。"
D.Strings[7498]="工作必须继续下去！"
D.Strings[7499]="你们自找的！"
D.Strings[7500]="不要让我杀了你们！"
D.Strings[7501]="你好啊，$c。这块破碎的土地就是你想看到的吗？这里和别人所说的完全不一样，真不敢相信我的人民能在如此荒芜的地方茁壮成长。"
D.Strings[7502]="这是必须的……"
D.Strings[7503]="你不该来这里……"
D.Strings[7504]="我……罪有应得……"
D.Strings[7505]="纳兹格雷尔，向我多介绍一些这里的任务。"
D.Strings[7506]="当我们的酋长听说黑暗之门被重新打开之后，他马上召集了他的顾问来计划这次远征。尽管少数几个顾问还抱有怀疑态度，但萨尔坚信我们能开拓新的视野，并将其写入我们的历史。他相信在这个充满灾难的世界的某处隐藏着兽人真正的传说。$B$B我必须要承认，在我内心最黑暗的时候，我曾为那传说不能昭告世人而感到恐慌。"
D.Strings[7507]="<继续听下去。>"
D.Strings[7508]="部落对外域的探索太过冒险了——资源、人力，甚至是我们对本土的防御都已经很危险了。但是，萨尔相信可以在这个满目疮痍的世界中找到部落的命运归宿。这几天我们从他的眼里看到了奇怪的光芒——好像他感觉到了什么激动人心的新发现，但是我们对此一无所知。$B$B不管怎样，他是我的酋长和结拜兄弟。我愿意追随他，直到深渊之门。"
D.Strings[7509]="你好啊，$c。你肯定是新来的，你看上去冒冒失失的，好像对这块恐怖的土地一无所知。$B$B<斯古尔·碎颅者中士对着地上吐了口口水。>$B$B早晚你会改变的。"
D.Strings[7510]="紧急停机已完成。"
D.Strings[7511]="我们的远征军已经安全地穿越了黑暗之门，建立起了一座名为萨尔玛的新基地。就像你看到的那样，燃烧军团切断了我们和兄弟们之间的联系。很明显，那些恶魔希望能重新夺回黑暗之门，阻止我们从艾泽拉斯得到更多的增援。"
D.Strings[7512]="有了援助，我相信塔蕾克丝就快要有所突破了。"
D.Strings[7513]="暴风城的兄弟们告诉我不要参军……我很高兴当初没有听他们的！"
D.Strings[7514]="破碎岗哨很适合蛮锤矮人，我从来没在空中逗留过这么久！"
D.Strings[7515]="陆行鸟是种高贵的生物。你要好好对待你的陆行鸟，没有什么比一只愤怒的陆行鸟更危险了。"
D.Strings[7516]="我确信有了我们的帮助，植物学家塔蕾克丝必定可以帮我们找到解决问题的办法。"
D.Strings[7517]="我想要购买一只小动物。"
D.Strings[7518]="随着中和剂与湖水混合起来，被水晶映射的湖面开始变得清澈了。"
D.Strings[7519]="最上乘的走私货就在这里，$n。我的货物都是居家旅行杀人灭口的好东西。避开了地精的税收和纳鲁的禁令——星界财团会满足你方方面面的购物需求！"
D.Strings[7520]="我想我可以在这里看到太阳之井！"
D.Strings[7521]="你真的能从这些海螺里面听到大海的声音吗？"
D.Strings[7522]="喔！看，这个好亮啊！"
D.Strings[7523]="杰恩会喜欢这个的！"
D.Strings[7524]="%s捡起一只海螺。"
D.Strings[7525]="%s把海螺放到她的耳边。"
D.Strings[7526]="%s掸落了海螺上的泥沙。"
D.Strings[7527]="看上去该把你从笼子里放出来了。"
D.Strings[7528]="中断紧急停机！凯尔萨斯大人若是知道了，我们必定人头不保！"
D.Strings[7529]="纳鲁的紧急停机程序会让法力熔炉永久停止运转的！必须阻止它！"
D.Strings[7530]="去外域？记得拜访一下虚空风暴52区的维克斯顿。他是热砂搏击会的官方竞技场商人，他那里有许多不可思议的物品，专门卖给那些有着足够竞技场点数的家伙。"
D.Strings[7531]="现在，把中和剂放上去……"
D.Strings[7532]="送我去破碎岗哨！"
D.Strings[7533]="泰顿，你去在那些变异生物身上试用一下中和剂如何？"
D.Strings[7534]="成功了！"
D.Strings[7535]="想帮我去拆除南边那些燃烧军团营地里的迁跃门吗？"
D.Strings[7536]="这些家伙几天前就来到沙塔斯城了，而他们的争论到现在还没有停止。$B$B我很高兴你没有因此离开，我还在想他们会不会把潜在的顾客给吓走呢。"
D.Strings[7537]="我希望这些沙塔斯城的家伙们快点停止争吵，我脑袋都被吵大了。$B$B有什么我能帮你的吗？"
D.Strings[7538]="德莱尼部队和联盟友军正与部落在外域的风暴之眼交战。你会加入他们，为我们扭转战局吗？"
D.Strings[7539]="部落不会允许德莱尼人和那些爱管闲事的联盟来控制外域的魔法晶格。你会加入血精灵的部队并前往风暴之眼作战吗？"
D.Strings[7540]="去和空军指挥官布拉克谈谈，$n。他会给你配备一只武装飞龙。对了，祝你好运！"
D.Strings[7541]="你好，$c！你是要汇报飞行任务的进展吗？"
D.Strings[7542]="哈尔……"
D.Strings[7543]="什么事，纳特？"
D.Strings[7544]="昨晚我又做了那个梦……"
D.Strings[7545]="哪一个？"
D.Strings[7546]="那个梦……那个疯狂的梦。记得吗？"
D.Strings[7547]="塔伦米尔被某种疯狂的亡灵力量毁灭了，而且永远地变成了南海镇的敌人。"
D.Strings[7548]="你能想象这件事吗，哈尔？你能吗？"
D.Strings[7549]="我还梦到敦霍尔德，布莱克摩尔那个的兽人奴隶逃跑了……"
D.Strings[7550]="他最终摧毁了整个城堡，救出了所有被我们关在营地的兽人。他成为了兽人的国王……酋长之类的什么东西。"
D.Strings[7551]="太疯狂了，不是吗？"
D.Strings[7552]="然后我梦到一座长着大树的山，一群精灵们到处跑来跑去……"
D.Strings[7553]="不知道从哪里冒出来的一个300尺高的恶魔或者什么东西走了过来，开始爬树……"
D.Strings[7554]="听起来很疯狂吧？更疯狂的还在后面呢。那个巨大的恶魔被一群飘在空中的小光球给炸死了……哦，我在梦中是一个女精灵……对……"
D.Strings[7555]="在这个梦里，我是这个世界中的钓鱼大师。我搬到了一个名叫卡利姆多的地方……"
D.Strings[7556]="从世界各地来的人们走到我面前对我表示敬意……在我这里学习钓鱼。"
D.Strings[7557]="我就像什么钓鱼之神那样……"
D.Strings[7558]="我根本不能相信这个……你知道那两个大嘴巴的恶棍，弗洛尔和提古勒吗？"
D.Strings[7559]="在那个梦里，他们不知通过什么手段，发明了一种叫做冰淇淋的东西，还用草莓来调味……好吧，长话短说，他们最后变得十分富裕！"
D.Strings[7560]="还不够疯狂么？我还梦到他们退出冰淇淋生意，变成了冒险家……他们周游了全世界，随后消失在什么传送门里。我随即就醒了，出了一身冷汗……"
D.Strings[7561]="还有一个非常可怕的梦……国王的儿子，阿尔萨斯……他和乌瑟尔一起对抗邪恶……*纳特擦了擦他的额头*"
D.Strings[7562]="不幸的是，阿尔萨斯被邪恶吞噬了，最终变成了邪恶本身……"
D.Strings[7563]="他假装好意地回到了国王身边，拔出佩剑，跑向国王，对着国王就这么……你知道……咔嚓一声。"
D.Strings[7564]="纳特，这是我听过的最可笑的梦了。"
D.Strings[7565]="你那根笛子里装着什么，纳特？"
D.Strings[7566]="如果你去过赞加沼泽，你可能遇到过一个叫做丹尼斯的朋友，你记得——那个带着个奇怪的帽子，只会在你叫他“专家”的时候回应的家伙吗？$B$B当然，是我教会了他一切。$B$B不要被我华丽的服饰所迷惑。其实在我的内心里，我仍然是个盗贼。丹尼斯和我曾经在战壕里相处过很长时间，但那是在我退休前的事情了。据我所知，他仍在那里，让敌人体验地狱般的痛苦。"
D.Strings[7567]="日复一日，我们所做的就是在这座矿井里面做苦力。男性血精灵不是为体力劳动而生的！"
D.Strings[7568]="我的勇士，消灭这个怪物！"
D.Strings[7569]="莫格莱尼倒下了？你们要为此付出代价！复活吧，我的勇士！复活吧！"
D.Strings[7570]="为你而战，我的女士！"
D.Strings[7571]="小声点，赫尔库拉。周围都是陌生人……"
D.Strings[7572]="那么你真的可以教我这个……这个……"
D.Strings[7573]="通灵术。它叫通灵术。没错，我把它和我的力量结合在了一起。"
D.Strings[7574]="肯瑞托呢？他们对通灵术有什么看法？"
D.Strings[7575]="这和你无关，赫尔库拉，你既不是肯瑞托的一员也不是一个通灵师。"
D.Strings[7576]="但是老实说，我对肯瑞托的想法一点也不感兴趣！他们是群蠢货，一群沉迷在他们古老腐朽的习惯中的蠢货。"
D.Strings[7577]="那么，克尔苏加德，教我吧，把你知道的东西都教给我……"
D.Strings[7578]="时机恰当的时候，赫尔库拉……等到时机恰当的时候……"
D.Strings[7579]="$n，答应我你会把我们胜利的消息告诉加鲁斯。"
D.Strings[7580]="那是个成千上万的人们都从天上看着我们的地方……"
D.Strings[7581]="我们就像他们的傀儡——我们不管做什么都是为了让他们开心。"
D.Strings[7582]="有时候，甚至在我清醒的时候，我都觉得他们正监视着我们。也许他们现在正监视着我们……"
D.Strings[7583]="小声点。周围有陌生人……"
D.Strings[7584]="兄弟姐妹们，今天我把你们召集到这里，是为了讨论洛丹伦的命运。"
D.Strings[7585]="%s放低了他的声音。"
D.Strings[7586]="我听说发生了一些事情……一些不应该发生的事情。"
D.Strings[7587]="死者复生……亡灵，在诺森德那片冰冷的大陆。整个城市突然消失得无影无踪。我……"
D.Strings[7588]="我听说诺森德已经沦陷了……"
D.Strings[7589]="惊讶的声音传遍了整个房间。"
D.Strings[7590]="我们必须随时准备好。我曾经面对过这些亡灵。他们是残忍的杀人机器，毫无同情和怜悯。"
D.Strings[7591]="是的，我也和他们交手过。我们的王国还没有准备好抵挡这种进攻。"
D.Strings[7592]="你有什么建议吗，莫格莱尼？"
D.Strings[7593]="建议？我建议我们现在就准备起来。为亡灵可能对我们的爱人、家人和朋友展开的屠杀准备起来。"
D.Strings[7594]="就是这个……"
D.Strings[7595]="%s打开了箱子。"
D.Strings[7596]="以圣光的名义！这是什么？"
D.Strings[7597]="我得到这个东西已经有十年了。自从黑石塔……"
D.Strings[7598]="我把它从一个兽人军官……一个黑暗的施法者的遗体上拿了下来……这是从他们的家乡带来的。"
D.Strings[7599]="不要太靠近了。我曾经把手放在上面……就那么一次。那天的记忆至今仍然在我脑海里浮现。"
D.Strings[7600]="%s从他的右臂上脱下了手套，在大家面前露出了他那扭曲的手。"
D.Strings[7601]="我猜想这个东西是暗影的实体化身……黑暗的表象。它是一块虚空的领域。"
D.Strings[7602]="我不知道这个邪恶的东西会跟亡灵有什么关系。我们必须摧毁它！"
D.Strings[7603]="塔卢恩大使把我一起带过来，希望我可以向我们的新伙伴们传授关于这个世界上的元素的知识……但没人愿意听。"
D.Strings[7604]="%s摇了摇头。"
D.Strings[7605]="不，老朋友，这很有关系。"
D.Strings[7606]="让我来问你们一个问题，兄弟姐妹们：善可以离开恶而存在吗？光明可以离开黑暗而存在吗？"
D.Strings[7607]="如果答案是否定的，那么这很可能就是它存在的原因，这个东西的另一个极端是否也必然存在呢？"
D.Strings[7608]="你们能否想象圣光的实体会对亡灵造成什么样的破坏？"
D.Strings[7609]="塔卢恩大使把我一起带过来，希望我可以向我们的新伙伴们传授关于这个世界上的元素的知识……但迄今为止他们都拒绝听这些，也许你愿意听听？"
D.Strings[7610]="一派胡言，莫格莱尼！这东西必须被摧毁掉！"
D.Strings[7611]="众人震惊了片刻，随即是一片沉默。"
D.Strings[7612]="离我远点，$c。我必须要和他们一样，傻乎乎地保护银月大使欧诺·炎伤。"
D.Strings[7613]="当沙塔尔继续把他们的注意力放在影月谷和伊利丹身上时，我们同样不能无视凯尔萨斯·逐日者带来的威胁。"
D.Strings[7614]="我对保护银月大使欧诺·炎伤感到有点厌烦了，$n。你有空和我聊聊吗？或许我们能彼此学到些什么？"
D.Strings[7615]="它吞噬了圣光！"
D.Strings[7616]="这不可能！"
D.Strings[7617]="<启动紧急停机。>"
D.Strings[7618]="当你靠近控制器时，你带着的那块控制水晶开始慢慢地发出蜂鸣，光芒在水晶上面跳动。$B$B突然在你的脑海里浮现出了法力熔炉的各种能量生产标准，它的稳定性和它到不同管道的输出量。控制器正等待着你的命令。"
D.Strings[7619]="它……它在变亮？它的颜色……正在改变。"
D.Strings[7620]="以圣光的名义！真的是这样吗？这就是我们所需要的东西吗？"
D.Strings[7621]="我必须知道……我会知道的……"
D.Strings[7622]="%s伸出手去触摸光明水晶。"
D.Strings[7623]="太……太……太漂亮了。当我碰到它的时候，我感觉到……圣光在我体内流过，我觉得它……它治愈了我的灵魂。"
D.Strings[7624]="你的手！伤口愈合了！"
D.Strings[7625]="%s把水晶放回了箱子。"
D.Strings[7626]="让我们再也不要提起今天这件事情。我们有太多的敌人。他们不需要知道我们手中有这么一件宝贝。"
D.Strings[7627]="我看到了……我从这块神圣的水晶中看到了……我们会铸造一件武器。这件武器中包含着我们每个人的力量……当它面对亡灵时，它会释放出这种力量，毁灭它们。这把武器所到之处，留下的只有灰烬……"
D.Strings[7628]="灰烬使者……"
D.Strings[7629]="马上停下来！"
D.Strings[7630]="别动那张斗篷！没错，没错，我知道你也想要一件。每个人都想要一件我的斗篷。相信我，你这个卑微的家伙，总有一天我会靠出售我的斗篷赚到大钱。从铁炉堡到这里的每个人都会知道巴图罗·吉塞提的名字。吉塞提商标会成为令所有人垂涎欲滴的东西！"
D.Strings[7631]="警告！%s的紧急停机程序已经启动。停机将在两分钟内完成。"
D.Strings[7632]="将在一分钟后完成紧急停机。"
D.Strings[7633]="圣光护卫者的工作是双重的。保护传教士的安全是他们的首要任务，而消灭圣光的敌人是次要的。"
D.Strings[7634]="阿尔杜尼斯，我们要你派增援去法力熔炉：杜隆。这不是请求，而是命令。"
D.Strings[7635]="你不会是认真的吧！我们的人手已经严重不足，都快要不能维持法力熔炉的正常运作了！"
D.Strings[7636]="照我的吩咐做。法力熔炉：杜隆受到魔法生物的严重袭击，局势已然失控了。如果你们不按指示随意胡来，将受到最严厉的惩罚！"
D.Strings[7637]="以穆拉丁的胡须之名，$c，这个地方已经濒临毁灭了。我无法想象居然有人可以在第二次战争结束后一直活到现在。"
D.Strings[7638]="哦，看！血槌啤酒！唔……"
D.Strings[7639]="血槌啤酒？我的最爱！"
D.Strings[7640]="我在找人来帮我完成那个拖了很久的任务。$B$B你似乎很适合。"
D.Strings[7641]="你在法兰伦废墟的努力让我回到了日程上。我正在召集我的队伍，准备向那里出发了。$B$B谢谢你，$n。"
D.Strings[7642]="到处都是燃烧军团……把它们全都干掉！"
D.Strings[7643]="谢谢你，我们在法兰伦废墟的计划又可以顺利进行了。"
D.Strings[7644]="你对虚灵了解多少，肉乎乎的家伙？$B$B毫无疑问，你肯定觉得我们全都一样，但却忘记了不同阵营之间的冲突和竞争。$B$B该是自我介绍的时候了，我是维序派的司令官阿米尔——如果你想要解决在这个区域横行霸道的虚空生物和复仇军，我是你唯一的希望。"
D.Strings[7645]="什么是复仇军？"
D.Strings[7646]="复仇军曾经是我们的家乡卡雷什的统治阶级。悲惨的是，在虚空领主迪门修斯释放他的虚空大军，吞噬一切阻挡他的生物前，我们被迫从卡雷什逃了出来。为此，复仇军发誓要报仇。从那时起，他们一直都在追踪迪门修斯……$B$B然而，维序派成立的初衷并不是为了对抗迪门修斯，而是复仇军。"
D.Strings[7647]="我不明白。你是什么意思，阿米尔？"
D.Strings[7648]="复仇军在黑暗扭曲中成长。复仇变成了他们唯一的依靠，任何阻碍他们或者不愿意加入他们的人都会被他们认为是敌人。很多人因为看到复仇军陷入了疯狂而离开了他们。复仇军议会的几个节点亲王也离开复仇军，创立了其它一些有着不同目标的团体和阵营。星界财团就是其中之一，而维序派是另一个……"
D.Strings[7649]="那么你们的目标是……？"
D.Strings[7650]="我们感觉到复仇军就像迪门修斯一样对我们存在造成了威胁。两者都必须被终结……"
D.Strings[7651]="我想我现在明白了。有什么我可以帮你的吗？复仇军和虚空生物同样也是我们的威胁。"
D.Strings[7652]="发现敌人。通话中断。"
D.Strings[7653]="维序派传输完成。"
D.Strings[7654]="哟。我是维克斯顿，热砂港搏击会的官方竞技场商人。如果你有足够的声望，我就有让你流口水的物品。"
D.Strings[7655]="呃……我感觉不是很好。"
D.Strings[7656]="我正在执行前线指挥官金斯顿下达的轰炸任务。我需要一头武装狮鹫！"
D.Strings[7657]="如果你感到不舒服，去找匹斯特。他可能有晕船药。"
D.Strings[7658]="<学徒时不时显露出心不在焉的样子，他似乎在辨听着你无法听见的声响。>$B$B今天天气不错，挺风和日丽的……$n。请原谅我这副心烦意乱的模样，但是我正在为纳丁干活。我要在他从城镇大厅回来之前，替所有的马匹都钉上马蹄铁。我能帮你什么忙吗？"
D.Strings[7659]="你虽然赢得了这次战役，但无法赢得整个战争。"
D.Strings[7660]="燃烧军团的最终战役开始了！这个世界再一次任凭我们宰割。不要留任何活口!"
D.Strings[7661]="崩溃吧！腐烂吧！"
D.Strings[7662]="尘归尘！土归土！"
D.Strings[7663]="在死亡的严寒面前屈服吧。"
D.Strings[7664]="你的坟墓会比这更加寒冷。"
D.Strings[7665]="所有的生命都将灭亡！"
D.Strings[7666]="燃烧军团必胜！"
D.Strings[7667]="时间……仍在……流逝。"
D.Strings[7668]="你们在保卫一个注定要毁灭的世界！逃走吧，那样也许你们还能多活几天！"
D.Strings[7669]="你很疲倦了……"
D.Strings[7670]="甜蜜的梦乡。"
D.Strings[7671]="虫群将吞噬你们的躯体。"
D.Strings[7672]="天灾降临！"
D.Strings[7673]="火焰之雨从天而降！"
D.Strings[7674]="大地和天空都将烧成灰烬！"
D.Strings[7675]="你的希望破灭了！"
D.Strings[7676]="痛苦地惨叫吧。"
D.Strings[7677]="真可惜，没时间继续跟你打交道了。"
D.Strings[7678]="哭喊着求饶吧！你们毫无意义的生命就要结束了！"
D.Strings[7679]="你会死得非常痛苦。"
D.Strings[7680]="你……被我盯上了。"
D.Strings[7681]="我和代理人亚希克斯接到了维序派司令部的最高级别任务指派，要去根除乌提斯的虚空生物，这是一次战略进攻。我们返回维序派哨站之前的最后一个任务是消灭那个被肉人们养得越来越胖的虚空领主阿克努斯。$B$B不幸的是，我们晚到了一会儿。亚希克斯和我在与血肉兽的交火中走散了，现在他被敌人困在里面。"
D.Strings[7682]="放弃所有希望吧！燃烧军团要完成这许多年前就注定的使命。这一次，一切都无可挽回了!"
D.Strings[7683]="你们的日子……就要到头。"
D.Strings[7684]="阿拉克塞，呼叫……你在吗？阿拉克塞？可见度为零。扭曲风暴阻挡了我们的视线。"
D.Strings[7685]="受苦吧，你这卑劣的虫子！"
D.Strings[7686]="这只是……一点小小的教训。"
D.Strings[7687]="没有人可以挽救你。"
D.Strings[7688]="不要抵抗。"
D.Strings[7689]="我希望这个该死的东西能管用。*阿拉克塞重重地敲打了一下便携式传送器。*"
D.Strings[7690]="放弃毫无意义的反抗吧。"
D.Strings[7691]="屈服于我的意志吧。"
D.Strings[7692]="滚开，渺小的凡人！"
D.Strings[7693]="让这个世界燃烧吧！"
D.Strings[7694]="你的灵魂将陷入渴望永生的痛楚中。"
D.Strings[7695]="一切都将被吞噬。"
D.Strings[7696]="我就是末日的使者！"
D.Strings[7697]="我们已经确定了标记的位置，长官。亚希克斯和我走散了。我们需要增援。"
D.Strings[7698]="收到，阿拉克塞。增援正在赶来。守住你的位置。我重复一遍，守住你的位置。"
D.Strings[7699]="%s的机械心脏开始微弱地跳动。"
D.Strings[7700]="欢迎来到破碎岗哨，$n！我希望你能活下来！"
D.Strings[7701]="如果圣光不能指引你，我的朋友，也许我可以给你点帮助。你需要什么？"
D.Strings[7702]="这座岛真奇怪，不是吗？有什么我能帮你的吗？"
D.Strings[7703]="在找仓库？你是想去埃索达的保险箱那里吧，那么……银行职员们会很高兴帮助你的。"
D.Strings[7704]="我不能跟着追踪器走出去，沿途的血肉兽太多了。派人……跟着追踪器进来吧……亚希克斯，完毕。"
D.Strings[7705]="我有个主意。让我们把这块碎片种到地上，看看会发生什么。"
D.Strings[7706]="别忘记去拜访虚空风暴52区的维克斯顿。作为热砂港搏击会的官方竞技场商人，他出售各种不可思议的物品给那些有着足够竞技场点数的家伙。"
D.Strings[7707]="水晶碎片中散发出的邪恶光芒引来了一只巨人，快点消灭它！"
D.Strings[7708]="角鹰兽管理员"
D.Strings[7709]="到山上来，$n。"
D.Strings[7710]="角鹰兽们栖息在埃索达入口处。如果你想飞去秘血岗哨的话，你应该去那里看看。"
D.Strings[7711]="埃索达的布料储备快要消耗殆尽了，如果你以捐献布料的方式帮助我们，无疑可以提升你和在德莱尼人中的声望。"
D.Strings[7712]="弗纳姆是我们的公会注册员，他的办公室就设立在埃索达里面。沿着路走，你很快就可以找到他。"
D.Strings[7713]="我们那简陋的旅馆坐落在碧蓝岗哨的北面，谢尔兰会照顾好你的。"
D.Strings[7714]="伊斯比纳会很高兴帮助你照料动物同伴的。她在碧蓝岗哨的旅馆外面等着你。"
D.Strings[7715]="啊，你是想要训练吗？有几个导师在碧蓝岗哨那里……你想学什么？"
D.Strings[7716]="然而他们受到了萨格拉斯的邪恶诱惑——现在他们变成了我们最强大的敌人。"
D.Strings[7717]="他们非常强大而残酷，以毁灭一切为乐。"
D.Strings[7718]="德鲁伊？这里没人学习那种知识……但是我听说埃索达附近有些人很符合你的描述。好像是叫沙兰尤斯？"
D.Strings[7719]="什么？你想给银月城捐献布料吗？$B$B你只是想要只陆行鸟吧，不是吗？好吧，好吧……为这座城市捐献布料，我来负责让你声名远播。"
D.Strings[7720]="他们坚定而无畏地服从他们主人的任何命令。"
D.Strings[7721]="艾克提恩是常驻这里的追踪者。而且他还干得很不错——他穿着的皮甲就是他技术的象征。他的营地就在碧蓝岗哨的东南方。"
D.Strings[7722]="末日守卫完全效忠于他们的主人深渊领主，享受着破坏世界的乐趣。"
D.Strings[7723]="如果想要掌握奥术魔法，你只需要去找塞米德就可以了。他就在碧蓝岗哨的东边，和鲁安达在一起。"
D.Strings[7724]="图拉丝是一位高贵的女士，也是坚定的圣光卫士。她在旅店内传授着她的课程。"
D.Strings[7725]="你可以在谢尔兰的那座很小但很实用的旅店里找到牧师古安。"
D.Strings[7726]="你是个萨满祭司？嗯，你可以自行决定未来要走的道路……哪条道路都行。图伦就在碧蓝岗哨西北方某处僻静的小营地里。"
D.Strings[7727]="鲁安达在碧蓝岗哨的东部训练年轻的战士们。如果你想要提高作战技术的话，找她就对了。"
D.Strings[7728]="有几个熟练的工匠分散在秘蓝岛周围。你在找哪一个？"
D.Strings[7729]="丹达尔对配制药水的技术非常在行。他就在碧蓝岗哨的西部，和法蒂玛一起工作。"
D.Strings[7730]="在碧蓝岗哨这里，我们没有设立铁匠铺。不过，我曾看到几个年轻的铁匠从南海岸的临时营地那里过来，也许你应该去那里看看。"
D.Strings[7731]="我们没有多余的食物可以分享了，但是有点奇怪……从南方吹来的风中夹杂着诱人的香味。不如去那边看看？"
D.Strings[7732]="我们的附魔师们在埃索达研究各种课题，纳霍加可以教你一些初步的知识。"
D.Strings[7733]="这里的技师，戴罗，可以教你些基础的工程学知识。也许你可以帮助我们的技术员修理那个坏掉的通信设备！"
D.Strings[7734]="法蒂玛是我们的学者，她在照顾坠毁事故受害者的过程中起到了无法估量的作用。她就在岗哨的西边。"
D.Strings[7735]="一个热心的钓鱼者……好吧，迪泰娜就住在埃门海滩的岸边，用她的网和鱼竿让我们有源源不断的鱼可吃。我相信她需要一些帮助。"
D.Strings[7736]="自从我们降落以后，赫罗就研究起了这里的植物，他会指导你的。你可以在碧蓝岗哨的西部边缘发现他正在和丹达尔一起工作。"
D.Strings[7737]="我们的新朋友——止松要塞的熊怪们对我们找到的皮革表现出了很强烈的兴趣。他们就住在北面，不如去他们那里问问看。"
D.Strings[7738]="去找杜尔维。她在岗哨的中间传授着勘测矿藏的技能。"
D.Strings[7739]="去止松要塞看看，我的朋友。那里的熊怪非常乐于帮助我们，也许你可以在那里找到你所需要的知识。"
D.Strings[7740]="碧蓝岗哨这边没有裁缝。不过你可以去海滩旁的营地问问，他们似乎带来了一些裁缝。"
D.Strings[7741]="在找宝石工匠吗？埃索达的珠宝匠们用双手雕琢出精美的工艺品，到那边找法里谈谈吧。"
D.Strings[7742]="你要什么？！我听说英雄谷里有一个古怪的德莱尼女人。或许她知道。"
D.Strings[7743]="是那个破碎者渣滓给你这根法杖的吧？他有没有告诉你，他就是那个出卖自己同胞的家伙？无所谓，你们两个都会为此付出代价的！"
D.Strings[7744]="水流之灵遗弃了我们，族群必将毁灭。"
D.Strings[7745]="去吧，长者。为你的部族带回那些元素之灵。"
D.Strings[7746]="风不再与我们的部族交流了，$n。如果没有长者将元素之灵召回来，我们将万劫不复。"
D.Strings[7747]="$n，我被这些镣铐束缚着，不能为我的部族带回火焰之灵。失去火焰之灵的灵魂如同傀儡，无法反抗他们的主人。"
D.Strings[7748]="我自由了！我会请求火焰之灵回到族人身边去，这样我们或许就能鼓起勇气反抗主人了！谢谢你，$R。"
D.Strings[7749]="我自由了！水流之灵将回到族人身边去。在它的指引下，我们终将在这片荒芜的土地上生存下去。我欠你一个人情，$n。"
D.Strings[7750]="你给了我自由！风之灵又一次愿意与族人们交流并赐予我们力量了。谢谢你，陌生人。"
D.Strings[7751]="我听说有两名蛮锤萨满进入了矮人区。你也许可以去那里试试你的运气。$B$B一直待在英雄谷的那位德莱尼先知也去找他们了。"
D.Strings[7752]="我们不喜欢圣骑士。女精灵来到城市，在皇家区。她是圣骑士，和她说话，学习圣骑士的东西。"
D.Strings[7753]="圣骑士？你是不是吃错药了还是怎么？我听到有传言说一个精灵代表团正在幽暗城拜访黑暗女王。也许他们之中有人会知道。"
D.Strings[7754]="那么你觉得你正在干什么？你胆敢妨碍主人的实验？"
D.Strings[7755]="你喜欢我们的成果吗？也许我们应该把这种水晶撒满整个外域。"
D.Strings[7756]="我渐渐对你尝试治愈这个大地、遏制能量召唤的行为感到厌烦了。葛利安索恩，巨人之王，凯尔萨斯王子和我命令你来保卫这块水晶！"
D.Strings[7757]="我们很快就会再见面的。"
D.Strings[7758]="你的帮助是无价的，我的朋友。$B$B我敢保证塞纳里奥远征队会倾尽全力来抵抗伊利丹从天空中丢下来的任何污染水晶。"
D.Strings[7759]="孩子们，来帮助我！"
D.Strings[7760]="你救了我的命！我会把你的功绩汇报给阿米尔的。"
D.Strings[7761]="这是什么地方？"
D.Strings[7762]="麦迪文在哪里？"
D.Strings[7763]="我该朝哪个方向走？"
D.Strings[7764]="这里是卡拉赞之塔，我的主人麦迪文的住所。身为一个卑微的看门人，我没有其它的东西可以向你解释。"
D.Strings[7765]="所有关于麦迪文的事都应该直接去问这里的管家莫罗斯，我几乎完全不知道主人在干些什么。如果你想知道更多的事情的话，我想现在正有一些贵族在宴会厅里和莫罗斯会面。"
D.Strings[7766]="从门房这里，你可以向三个方向行进。我身后的楼梯通往会客间，客人们正在那里玩乐。我相信你已经闻到附近的马厩的味道，还有仆役宿舍的入口就在门房的大门旁边。"
D.Strings[7767]="谁是午夜？"
D.Strings[7768]="午夜是猎手阿图门的私人坐骑。我从未见过一匹比它更快、更强壮或者更英勇的马了。而且它的骑士更是喜怒无常！每个人都和它保持一定距离，以免被午夜踢到头，或被阿图门揍一顿。"
D.Strings[7769]="该死的蜘蛛、不断尖叫的蝙蝠、还有那些被诅咒的恶魔野兽，它们占据了仆役宿舍。那里已经很不安全了，尤其是当那些大家伙们从黑暗中跳出来的时候。"
D.Strings[7770]="帮你什么？"
D.Strings[7771]="大家伙？"
D.Strings[7772]="是的，我从未亲自见过它们，但有时候我可以从远处听到它们的声音。如果你想进去冒险的话，对它们要保持充分的警惕。"
D.Strings[7773]="我没有时间来闲聊了。我有很多人需要训练，还有一座塔需要看管。"
D.Strings[7774]="你好！看这完美的乐器，真荣幸可以为主人和他的客人们演出。去观众那里找个座位，我听说表演很快就要开始了。"
D.Strings[7775]="这个聚会毫无意义。那些愚蠢的贵族们永远都不可能看到麦迪文，他们不明白吗？我应该待在夜色镇，和我的家人在一起，而不是在这里浪费时间。"
D.Strings[7776]="我知道……在这里……某个地方。在这图书馆的某个地方有我要找的知识……"
D.Strings[7777]="这座塔完全陷入了疯狂。这不是个图书馆，只是个巨大的书堆，而我不觉得这里有我要找的东西！既然这样，我以前都在干什么？"
D.Strings[7778]="你的出现打扰了这项重要的工作，请马上离开。我刚才进展到哪里了？"
D.Strings[7779]="啊，在这么个奇怪的地方居然也有潜在的顾客！"
D.Strings[7780]="你都卖些什么？"
D.Strings[7781]="我们开始吧……掩护我，我会运送包裹的。"
D.Strings[7782]="以卡雷什的第二个太阳之名，看这个地方！我只能认为萨哈达尔正在计划着什么。加油，我们继续。"
D.Strings[7783]="看那边！萨哈达尔的管道！他一直吃得很不错嘛……"
D.Strings[7784]="好吧，在我放置这干扰器的时候好好保护我。这不会花费太长时间的。"
D.Strings[7785]="完成了！后退！后退！"
D.Strings[7786]="让这些东西离我远点！"
D.Strings[7787]="我受到攻击！重复一遍，我受到攻击！"
D.Strings[7788]="保护好那些管道！阻止入侵者！"
D.Strings[7789]="我在这里的工作大约已经完成了。去发射器那里向阿米尔的影像报告吧。"
D.Strings[7790]="准备粉身碎骨吧，爱管闲事的家伙。你们释放了一个神！"
D.Strings[7791]="你好，肉人。我是纳乌德，维序派哨站的主研究员。"
D.Strings[7792]="离开凯尔萨斯是我们一直以来所做过的最正确的事情。他的追随者们不是瞎了，就是对他太过恐惧，以致于无法认识到他正在把他们引向什么样的境地。$B$B然而，我们不是。"
D.Strings[7793]="我被攻击了！我需要援助！"
D.Strings[7794]="防线被冲破了！"
D.Strings[7795]="我……尽力了。"
D.Strings[7796]="不要放弃！坚持到底！"
D.Strings[7797]="尽全力挡住他们！"
D.Strings[7798]="我们不能退缩！"
D.Strings[7799]="守不住了！撤退！"
D.Strings[7800]="没有人可以打败我！"
D.Strings[7801]="跟我交战的代价就是死亡！"
D.Strings[7802]="我把大法师瓦格斯的法杖弄丢了。你能重新给我一根吗？"
D.Strings[7803]="有些人寻求着谎言，而先知则带来了圣光的真理。$B$B这座图书馆存在的意义，就是让每个人都成为自己命运的先知。"
D.Strings[7804]="在虚灵中，一部分会员负责处理血肉兽。他们被称为驯兽者。"
D.Strings[7805]="你来这片美丽的土地寻找什么？"
D.Strings[7806]="葛拉米就站在银月城的魔导师之门外，她管理着龙鹰。"
D.Strings[7807]="如果你想注册一个公会，我建议你去银月城里面打听打听。"
D.Strings[7808]="德兰妮尔经营着她那个设在鹰翼广场东南角的旅店。美酒佳肴，还有柔软的床……夫复何求？"
D.Strings[7809]="有些猎人们似乎无法看管好他们自己的野兽。如果你必须找个地方把野兽暂时圈养起来，阿娜索丝可以帮忙。她就在鹰翼广场的旅馆外面工作。"
D.Strings[7810]="有个自称是德鲁伊的母牛在银月城内建立了一处小营地。她现在肯定正在啃我们的植物。"
D.Strings[7811]="猎人们都在听汉诺维亚的课，他是一个站在鹰翼广场东北方建筑里的远行者。"
D.Strings[7812]="加琳黛尔在鹰翼广场内传授奥术魔法之道，你可以在旅店二楼找到她。"
D.Strings[7813]="血骑士诺尔蕾妮正在广场东北方的建筑里面等着年轻的新兵们。"
D.Strings[7814]="如果你在寻求牧师的知识，那么珀纳瑞斯就是你要找的人。他在德兰妮尔的旅店二楼。"
D.Strings[7815]="在鹰翼广场的东北部有一座建筑……你可以在里面找到塔娜莉亚，一个很擅长躲藏的女人。"
D.Strings[7816]="我们离维序派哨站不远了，$n。这边走！"
D.Strings[7817]="长官！这个肉乎乎的人救了我！"
D.Strings[7818]="%s向指挥官阿米尔敬礼。"
D.Strings[7819]="塞罗努斯是召唤恶魔的专家。他居住在鹰翼广场旅店，就在二楼。"
D.Strings[7820]="我认识一位本地的炼金师。森纳瑟林，应该是这个名字。当我最后一次看到他的时候，他正在前往萨瑟利尔庄园，毫无疑问，他是去参加一场可笑的聚会。"
D.Strings[7821]="远行者们在他们永歌森林东部的居所留下了一位铁匠。阿拉瑟尔也许能帮到你。"
D.Strings[7822]="德兰妮尔一直提供着一种被称为奎尔雷斯塔什么的美食。如果你想从她那里学手艺的话，应该去鹰翼广场旅店找她。"
D.Strings[7823]="如果你在找艾雷达妮娅的话，就应该去萨瑟利尔的庆典那里。她几天前收到了邀请。"
D.Strings[7824]="这么危险和不可预知的专业技能是不能在我们的森林里修习的。你可以去银月城，不管怎样，城墙还是足够承受住爆炸的。"
D.Strings[7825]="为了那些更喜欢用普通方法来治疗伤口的人，鹰翼广场旅店里的卡娜莉亚设立了一处整洁的急救站。"
D.Strings[7826]="如果你想以腥味、潮湿和乏味来打发这种好日子的话，我们伟大的城市里有个渔夫……"
D.Strings[7827]="谁能比植物学家塔尼安雷尔更擅长布置晚会的鲜花布景？我相信萨瑟利尔男爵会用酒来报答他的。"
D.Strings[7828]="阿米尔可能在担心复仇军有所动作，但是我仍然把注意力集中在迪门修斯那里，它才是真正的危险。"
D.Strings[7829]="珠宝加工训练师奥雷妮亚就居住在鹰翼广场那间德兰妮尔开设的旅店里。她或许正需要一名学徒。"
D.Strings[7830]="萨瑟林在永歌森林找到的山猫皮很适合他的作品。你应该和他谈谈——他就站在魔导师之门西南的玛斯雷恩旁边。"
D.Strings[7831]="你可以在银月城内找到矿工，毫无疑问他们在熔炉附近。"
D.Strings[7832]="如果你真能习惯的话，玛斯雷恩对野蛮的剥皮工作很在行。他在为萨瑟林提供皮料，你可以在魔导师之门的东南找到他们俩。"
D.Strings[7833]="最优秀的女裁缝最近去萨瑟利尔庄园了，她的针线技艺在那里更受赏识。"
D.Strings[7834]="你在找什么？说出来。"
D.Strings[7835]="如果在其它的时间和地点，我肯定只会被当作一个新人。在这里，我已经是个有经验的老兵了，随时都准备好为纳鲁的荣耀而战。$B$B我们有十个人进入法力熔炉：艾拉，其他的人都死在了燃烧军团手下。"
D.Strings[7836]="%s开始变形……"
D.Strings[7837]="是时候面对索克雷萨了，$n。你准备好了吗？"
D.Strings[7838]="是占星者派你来联系我的吗？你看上去一点也不像个占星者。"
D.Strings[7839]="快点说，我没有时间浪费在闲聊上。被遗忘者已经变成了一股不可低估的力量，但是我们仍然有很多事需要去做。这座城市可不会自己运转起来。$B$B你想要什么？"
D.Strings[7840]="你还未达到在热砂港搏击会中出场的条件，$c。不要浪费我的时间。"
D.Strings[7841]="好吧，$c。你觉得你符合参加热砂港搏击会的竞技场参与条件了吗？"
D.Strings[7842]="我想要在竞技场一展身手。"
D.Strings[7843]="你听到了金属摩擦石头的噪音……"
D.Strings[7844]="你可以在武器大厅的战略沙图周围找到战场军官们。"
D.Strings[7845]="战场军官都聚集在战士区。"
D.Strings[7846]="你可以在暴风要塞找到战场军官。"
D.Strings[7847]="%s看上去变弱了。"
D.Strings[7848]="去猎人高地吧，你可以在那里找到战场军官。"
D.Strings[7849]="战场军官就在荣誉谷的勇士大厅里。"
D.Strings[7850]="你可以去皇家区。他们都在那里，在房间里面站成一个圆圈。"
D.Strings[7851]="竞技场管理员"
D.Strings[7852]="你可以在纳鲁之座的医护中心找到他。愿圣光与你同在。"
D.Strings[7853]="来看看我的松饼吧！"
D.Strings[7854]="好吧，松饼人，给我看看你的松饼！"
D.Strings[7855]="我有松饼。到我这里来！"
D.Strings[7856]="没错，我是松饼人。你知道为什么吗？因为我卖松饼啊！"
D.Strings[7857]="喝一口啤酒，吃一口我的松饼，真是人生的一大享受啊。"
D.Strings[7858]="哈哈，多么美味啊。卖松饼啦！来这里买新鲜的松饼吧！"
D.Strings[7859]="你好，我是维序派的萨义德上尉，我身旁的这些士兵是我的复仇者部队。我们等待着摧毁虚空管道的那个肉人的命令。用那个肉人的话来说，我们要赶到迪门修斯的巢穴外，等待最后进攻的命令！$B$B等了这么多年……虚空领主很快就会面对我们的夹击了！"
D.Strings[7860]="我需要一个新的相位扰流器，教授。"
D.Strings[7861]="虚空幼龙赞许地看着你。"
D.Strings[7862]="我准备起飞了！带我飞翔吧，龙！"
D.Strings[7863]="没问题，$n。我们会听你的命令冲锋陷阵！只要你一句话，我和我的手下就会发动进攻！"
D.Strings[7864]="欢迎来到中央生态圆顶，旅行者。我提醒你，和那个地精舒利做生意时要多留意。喜欢把“朋友”这个词作为标点符号的家伙一般都不可信。"
D.Strings[7865]="奥蕾莉亚要塞被敌人重重包围，我们应该与他们一起战斗。"
D.Strings[7866]="如果你想从这里出去的话，就得自己努力，那边的巡影者什么忙都帮不上。"
D.Strings[7867]="精确的角度和速度……"
D.Strings[7868]="海加尔山战役是这条时间流里防备最严密的事件之一。一旦入侵者改变了它的结果，历史上所有的后续事件都会受到波及。$B$B做为守护者的配偶，我比其他青铜龙更熟悉时间流的动向。最近，我感觉海加尔山战役周围的时间突然出现了微妙的波动。一定有谁正在企图改变这条时间流，我们必须阻止他们。"
D.Strings[7869]="你想要什么？说出来，在你可以证明你的贡献和与你和我们的友谊之前，我不准备雷象卖给你。"
D.Strings[7870]="是痛苦的灵魂，我察觉到了。$n。他们在这里，快点过来！"
D.Strings[7871]="保护我，$n。我必须冲破他们邪恶的魔法！"
D.Strings[7872]="现在我们必须找到出口。"
D.Strings[7873]="应该不会太远了，$n。出口就在前面。"
D.Strings[7874]="谢谢你，$n。请回去转告我的兄弟，告诉他们维尔达安全了，他们在古尔丹之手附近的诅咒祭坛那里。愿大地之母保佑你……"
D.Strings[7875]="被折磨的水之魂在艾泽拉斯世界和德拉诺世界的水道中躁动……"
D.Strings[7876]="瓦丝琪女王必须为这些暴行负责。她必将得到制裁！"
D.Strings[7877]="库斯卡的纳迦对他们的战俘异常凶残。我能在水牢里活这么长时间真是个奇迹。感谢大地之母。"
D.Strings[7878]="纳迦进攻了！准备战斗！"
D.Strings[7879]="撕裂这片土地吧，古尔丹！切断我们与它之间的联系！"
D.Strings[7880]="不要忘记！是它们抛弃了我们！"
D.Strings[7881]="如果它们拒绝给予，我们就强夺！"
D.Strings[7882]="不要这么做，古尔丹！元素们永远都不会原谅我们的！"
D.Strings[7883]="住手！你必须马上住手！"
D.Strings[7884]="想想我们的后代，古尔丹！你会毁灭我们的！"
D.Strings[7885]="你诅咒了我们……我们完蛋了。"
D.Strings[7886]="安静！大地的崩溃很快就要来临了！"
D.Strings[7887]="亲眼看看黑暗主宰那势不可挡的力量吧！"
D.Strings[7888]="有了他所赐予的力量，我会夷平这片土地，并重新铸造它！"
D.Strings[7889]="看！大地在我们面前破碎了！看那些流动的能量！它会让我们的军队更加强大……"
D.Strings[7890]="我们再也不会缺乏足够的力量了！我拯救了我们的未来！享受我的荣耀吧！"
D.Strings[7891]="结……束……了……"
D.Strings[7892]="是谁胆敢妨碍我的工作？！"
D.Strings[7893]="%s低声念诵着虔诚的祷文。"
D.Strings[7894]="我正在寻找一个伙伴……"
D.Strings[7895]="是叫人帮忙的时候了。"
D.Strings[7896]="我们在活木林的工作不能受到打扰。活木林持续与健康的成长决定了我们的命运。"
D.Strings[7897]="%s仔细地读着通缉令。"
D.Strings[7898]="去问问莉娜·月泉有什么需要你帮助的事情吧。"
D.Strings[7899]="如果我听说的事情都属实的话，你已经为希尔瓦纳做了很多事。$B$B继续下去，也许我们能在这里安家了。"
D.Strings[7900]="我喜欢自己动手……"
D.Strings[7901]="让我看看你这里有什么小东西卖。"
D.Strings[7902]="去休息吧，流浪者。让我们同享这炉火。"
D.Strings[7903]="守住防线！不要退后半步!"
D.Strings[7904]="胜利或者死亡！"
D.Strings[7905]="坚守每一寸土地！"
D.Strings[7906]="完了！撤退！我们失败了……"
D.Strings[7907]="就是在这里，古尔丹切断了兽人们和元素之灵间的联系。将德莱尼人全部消灭已经不能满足他对无尽力量的渴望。为了他的战争，他要把德拉诺也夷为平地，吸取它的所有能量。$B$B现在这里所留下的一切都只是他那疯狂过后的痕迹。$B$B看那祭坛，$r——这块大地将永远死气沉沉……"
D.Strings[7908]="我为祖先们秉承着历史悠久的萨满教统而感到荣幸。我们必须铭记他们所做出的牺牲。$B$B对我们来说，作为回报，我们必须为后代的将来做出必要的牺牲。$B$B是什么把你带到我这里来的，$c？"
D.Strings[7909]="那么你做了些什么？"
D.Strings[7910]="后来呢？"
D.Strings[7911]="我还想问你一些其它的问题。"
D.Strings[7912]="不久以前，我们从周围的食人魔那里夺回了雷神要塞的控制权。$B$B你是来这里帮我们防守的吗？我知道高德雷克正在寻求帮助。"
D.Strings[7913]="靠后，$n。灵魂可能会伤害到你。"
D.Strings[7914]="为什么你要捕获我们？"
D.Strings[7915]="你希望从中得到些什么？"
D.Strings[7916]="%s鞠了一躬。"
D.Strings[7917]="我们希望能帮助你，灵魂。我们寻求你的智慧。"
D.Strings[7918]="智慧？是你的同族导致了森卢肯那无比的愤怒。"
D.Strings[7919]="为什么我们要帮助你们？这个世界已经被毁灭了，被破坏了。"
D.Strings[7920]="你是对的，灵魂。是我的同胞对你们做了这些错事，但是请让我们纠正这一切。"
D.Strings[7921]="请告诉我们：森卢肯是谁，或者说，是什么？"
D.Strings[7922]="蠢货！火焰之王森卢肯！当联系被切断的时候，森卢肯醒了，是森卢肯的泪水注满了这片遍是熔岩的大地。"
D.Strings[7923]="火……火焰之王？那不是一位元素之王吗？难怪……古尔丹，你这个该死的蠢货！"
D.Strings[7924]="他现在已经疯了，在破碎中失去了理智。元素们将永无安宁。"
D.Strings[7925]="肯定有办法解决的。"
D.Strings[7926]="是的，有一个方法：消灭森卢肯。消灭这位元素之王。"
D.Strings[7927]="不要怀疑我和我的朋友，灵魂。请告诉我们怎样才能召唤炎魔之王。我的朋友们会消灭他的。"
D.Strings[7928]="你倒是说句话啊……"
D.Strings[7929]="是的……是的……咒语。诅咒的咒语。你那黑暗的主人所诵读的咒语。"
D.Strings[7930]="是的……古尔丹……"
D.Strings[7931]="我们会找到这些咒语。我们会召唤你的主人，并把他消灭掉。"
D.Strings[7932]="交谈，更多的交谈……现在放了我们，凡人。"
D.Strings[7933]="在纳鲁之座有两个邮箱：一个在银行的附近，另一个在拍卖行的外面。"
D.Strings[7934]="你觉得战争怎么样，$n？想想我们为什么来这儿吧……这会让你更容易接受无尽的战斗和死亡。"
D.Strings[7935]="远征军岗哨是个条件艰苦的地方，但是那里对荣耀堡的防御非常关键。在这里收集的情报，还有士兵们与燃烧军团和塞斯高兽人之间的战斗，都是联盟在地狱火半岛的战役中的关键。"
D.Strings[7936]="我听说你已经在这里发挥作用了。$B$B太好了。我还担心我们得去劝你帮忙呢。"
D.Strings[7937]="现在去找回遗失的咒语吧！"
D.Strings[7938]="在骨架之间紧绷着的毛皮上写着的信息主要是召集军队以对抗西面的联盟希尔瓦纳与活木林的驻军。"
D.Strings[7939]="你好啊，我是阿兹米！我经常在这里出售新鲜的水果和水。你饿了吗，或是有点渴？"
D.Strings[7940]="呸！你看我有时间闲聊吗？$B$B有吗？$B$B快点去做你的工作。这里还有很多食人魔要杀呢！"
D.Strings[7941]="很高兴看到一个像你这样的$r。你为希尔瓦纳的安宁做出了贡献，我们在这里时间虽然短，但是却做了很多。不过，周围的敌对势力仍然威胁着我们的生命。$B$B我想听听你要说什么。说出你的想法，$c。"
D.Strings[7942]="%s的体形变大了！"
D.Strings[7943]="欢迎来到塞纳里奥庇护所，$n。我向你出售基本的供给品，你应该会需要它们的。"
D.Strings[7944]="我着火了！！"
D.Strings[7945]="我又着火了！！"
D.Strings[7946]="它烧起来了！！"
D.Strings[7947]="不要吧……"
D.Strings[7948]="为什么是我！？"
D.Strings[7949]="早上的时候会很痛的。"
D.Strings[7950]="啊！"
D.Strings[7951]="%s从空气中吸取能量……"
D.Strings[7952]="$n，准备好跟奥特兰克山谷的雷矛卫队作战了吗？"
D.Strings[7953]="作为探险者协会的代表，布隆薇和我按照联盟的要求来调查这些山脉。$B$B不过我们之间有个秘密，在希利苏斯进行了长时间的逗留后，我们需要度假。这里看上去是个不错的地方。"
D.Strings[7954]="伯格瑞姆可能是对的，也许我们确实需要休息一会儿。$B$B不过现在我们既然在这里了，我很想立刻着手研究这个地方会给我们带来什么。"
D.Strings[7955]="$n，看到你很高兴。奥特兰克山谷的矮人伙伴需要我们的援助。你会去帮助他们吗？"
D.Strings[7956]="威胁结束了！是$n解救了我们！"
D.Strings[7957]="洛萨之子所面对的是一场永无止境的战争。我很惊讶我们的武器居然还能用！"
D.Strings[7958]="即使是现在，亡灵士兵们依然在阿拉希盆地与阿拉索联军作战。你愿意帮助污染者击败人类和他们的盟军吗？"
D.Strings[7959]="你好啊，$n。战歌峡谷需要你这样的英雄。"
D.Strings[7960]="我们的盟友仍然在战歌峡谷的银翼岗哨与敌方作战。去助他们一臂之力如何？"
D.Strings[7961]="你好，旅行者。我是欧鲁诺克。请坐在我的篝火旁暖和一下吧。$B$B小心下面的破碎岩床上到处游荡的野兽！"
D.Strings[7962]="你都卖些什么，欧鲁诺克？"
D.Strings[7963]="不要忘记，$c，战斗仍然在艾泽拉斯进行着。你会回奥特兰克山谷帮助部落吗？"
D.Strings[7964]="你好啊，$c。你知道我们和银翼哨兵在战歌峡谷的战斗还没有结束吗？你的出现会帮我们大忙的……"
D.Strings[7965]="我长途跋涉到这里来，就是为了寻找可以彻底打败阿拉索联军的方法，但是那个没事总喊“赐予我力量”的蠢货亚当·希曼总是跟踪我。\n$B\n尽管如此，如果像你这样的杀手能够回到艾泽拉斯，或许我们可以再次将联盟打成渣！"
D.Strings[7966]="你还好吗？外域的感觉怎么样，准备好返回奥特兰克山谷给部落点颜色看看了吗？"
D.Strings[7967]="银翼哨兵仍然在战歌峡谷和部落战斗着，$c。不知道你是否会回到那里去帮助他们。"
D.Strings[7968]="我来到外域是希望可以找到强大的神器来帮助阿拉索联军对抗污染者……但是我只找到这根神奇的魔法腰带，一个可笑的侏儒伙伴和一个一口咬定是我偷了他那灰色头骨或是其他什么东西的亡灵。\n$B\n无论怎样，你介意在我继续搜索时加入联军的战斗吗？"
D.Strings[7969]="<有人觉得奥克会来这里只是一种愚蠢的英雄主义思想在作祟，因此不需要理会，那样只会更加鼓励他这样做。>"
D.Strings[7970]="<它是一头巨大的、全副武装的、带着鞍具的攻击型猛兽，若是它开口说话的话，就显得更傻了。>"
D.Strings[7971]="只有法师可以学习传送魔法，$c。"
D.Strings[7972]="法师……你想学习传送魔法，是吗？"
D.Strings[7973]="幽暗城的皇家药剂师协会渴望去外域帮助我们的兽人盟友。这是个加强我们之间联系的好机会，而且我们还能借此机会找到新的标本和混合物。$B$B混合物……例如毒药。"
D.Strings[7974]="%s非常虚弱。"
D.Strings[7975]="说得好听点，白沙岗哨是一个意外的耽搁。我的客户们还指望着我来运送货物，不过我有些怀疑，再有这样的耽搁的话，我是否可以及时完成任务。"
D.Strings[7976]="嘿，不要打开那些笼子，好吗？$B$B我就想让食人魔把我放在这个笼子里。"
D.Strings[7977]="有人告诉我，地狱火半岛的尘土和炎热是非常恼人的……我不知道是不是那样，但是我会相信我那些值得敬重的、而且仍然活着的盟友。"
D.Strings[7978]="遗忘元素制皮可不是说着玩的。如果你选择放弃它，你同样会忘记所有需要元素制皮专精的图样！"
D.Strings[7979]="在你向我们人民的证明了你的价值和贡献前，你是不能在这里购买陆行鸟的。$B\n\n在你被血精灵们崇拜前请不要回来。走开！"
D.Strings[7980]="这些兽人肯定非常渴望在外域扩张势力！如果我告诉你他们给了我多少银币，你一定会嫉妒地掐死我！"
D.Strings[7981]="如果你有金币，我就能教你怎么骑陆行鸟。"
D.Strings[7982]="你必须在血精灵一族中达到崇拜声望，我才能教你骑术，$C。"
D.Strings[7983]="$n，我可以开始讲诅咒密码的故事了吗？"
D.Strings[7984]="我准备好听你的故事了，欧鲁诺克。"
D.Strings[7985]="好吧。你所寻找的咒语有个名字，$n。它们被称为诅咒密码，这个咒语是古尔丹用来破坏这个世界的。这咒语切断了兽人和德拉诺的元素之间的联系。$B$B<欧鲁诺克点了点头。>$B$B是的，这正是你要修复的咒语，最终也必将由你来完整地咏唱。"
D.Strings[7986]="我要怎么才能找到密码？"
D.Strings[7987]="诅咒密码被古尔丹封存在他位于卡拉波的私人住所已经有二十年了。啊，对了，你不知道卡拉波是什么，对吗？$B$B黑暗神殿……$B$B是的，就是伊利丹·怒风现在的家。$B$B当伊利丹控制了黑暗神殿之后，密码落入了他的手中。他认识到，虽然对这个世界的破坏已经完成，但是为了日后的使用，他还是谨慎地将密码保存了下来。"
D.Strings[7988]="你是怎么知道这一切的？"
D.Strings[7989]="当你在诅咒祭坛下跪祈祷时，你只看到那些被诅咒的灵魂，却没有看到站在古尔丹身旁的我。$B$B<欧鲁诺克点了点头。>$B$B我是一个经历过许多事情的人，我告诉过你吗？其中之一就是我曾担任过古尔丹的军官。$B$B一生之中我做了很多可怕的事情。我杀死过男人、女人，甚至还有孩童。我还在无辜的德莱尼人的鲜血中跳舞……然而……$B$B<欧鲁诺克哽咽地说着。>"
D.Strings[7990]="然而什么？欧鲁诺克？"
D.Strings[7991]="我永远都不会忘记那一天，$R。永远都不会。虽然我放弃了萨满的教义转投暗影魔法已经很久了，但那仍令我感到刺痛。一种如此强烈的失落感……不能用语言来解释的失落感。$B$B当元素与我们之间的联系被切断时，所有德拉诺的兽人都改变了。如果暗影魔法之中有什么值得怀疑的东西，那也早被奔腾的熔岩洗刷殆尽了。"
D.Strings[7992]="一股厌恶直涌上我的喉头。在仪式结束后。我跑回了家，回到了我的孩子身边。我带上了可以带上的一切，和我的儿子们一起离开了。我们跑到山上躲了起来。我真的别无选择……$B$B那些日子里，刺痛从没有消失过。二十年后，元素与大地的连接才得以恢复。当元素开始治愈时，又是一个二十年过去了。"
D.Strings[7993]="密码现在怎么样了？你的孩子呢？"
D.Strings[7994]="就像我说的那样，伊利丹在占领黑暗神殿的时候发现了密码。他把密码分成了三块碎片，交给了他的随从分别保管。$B$B我的儿子……我的儿子们现在长大了。当我得知密码的下落之后，我派儿子去重新夺回碎片。$B$B你必须找到我的儿子，$n。找到他们，然后将诅咒密码重组。"
D.Strings[7995]="我会找到你的儿子们和密码的，欧鲁诺克。"
D.Strings[7996]="一个也别让他们跑了，你们这群狗！"
D.Strings[7997]="我要这些联盟和部落的蠢货们都去死！"
D.Strings[7998]="集合。向刀塔要塞行军。我要让高尔迪姆知道我的厉害！"
D.Strings[7999]="啊！我看见你了！来人啊，杀了他们！"
D.Strings[8000]="我一直在友善地询问你，鱼人。"
D.Strings[8001]="诅咒密码在哪里？我知道三块碎片中的一块就在这座村子里。"
D.Strings[8002]="你在说……什么，细皮嫩肉的家伙？"
D.Strings[8003]="纳迦……没有这个……密码……"
D.Strings[8004]="不……当然不。我在想什么？为什么你会有诅咒密码的三块碎片中的一块呢？"
D.Strings[8005]="我感觉很愚蠢。也许我应该释放你，让你自由？"
D.Strings[8006]="我真的看上去那么蠢吗，纳迦？现在轮到你感受痛苦了！"
D.Strings[8007]="啊……啊……给我自由……"
D.Strings[8008]="%s对着库斯卡纳迦吐口水。"
D.Strings[8009]="爬起来，你这堆腐臭的垃圾！在我终结你之前爬起来！"
D.Strings[8010]="不要再殴打库斯卡司令官了，兽人！我说！密码……藏在库斯卡岗哨的一只箱子里……那里的纳迦身上有钥匙……"
D.Strings[8011]="我在听……"
D.Strings[8012]="库斯卡……！"
D.Strings[8013]="欢迎来到沙塔斯城，这里是沙塔尔在外域的主要城邦。你在寻找向导吗？"
D.Strings[8014]="我来这个地方是由于我的研究涉及到了雷神氏族的文化。$B$B他们以前很弱小，不过由于屈服于力量的引诱，他们通过玛诺洛斯之血转变成了邪兽人。$B$B我读了所有有关他们的文献。在我们征服刀塔食人魔并把他们逐出要塞的时候，我们遗失了一件神器、一面鼓、一支箭和一块石板。现在我对找回它们有着独特的兴趣。"
D.Strings[8015]="阿托尔的尸体被恶魔的法术悬挂在半空中。即使他已经死去，恶魔也没有放过他。"
D.Strings[8016]="奴隶们，来帮我！"
D.Strings[8017]="我很高兴你决定加入我们的事业。作为奖励，我会将你带给我的永恒之水注入一枚戒指内。$B$B我提供给你四个不同的选择来解封它们的力量。以你的睿智来选择吧，$n。时空之沙一旦流入一个方向，就不容易改变了。"
D.Strings[8018]="我……死了。$B$B为什么我还在这里？是不是我要去的地方没有什么好的猎场？$B$B不……我必须先完成我的任务。在我可以离开这个世界前，必须找到诅咒密码的第二块碎片。"
D.Strings[8019]="哈哈！雷霆之刺是我的。受死吧！"
D.Strings[8020]="弱小的$r不能举起雷霆之刺。古尔举起它！"
D.Strings[8021]="遗忘长剑锻造技能可不是说着玩的。如果你选择放弃它，你同样会忘记所有需要长剑锻造技能的图样！"
D.Strings[8022]="我……我已经死了……我承受了这么多痛苦……被卷入了黑暗……你能看到我吗，$r？"
D.Strings[8023]="你们击败了我最强大的顾问……但是没有人能战胜鲜血之锤。出来吧，萨古纳尔男爵！"
D.Strings[8024]="卡波妮娅会很快解决你们的。"
D.Strings[8025]="干得不错。看来你们有能力挑战我的首席技师，塔隆尼库斯。"
D.Strings[8026]="让我们来看看你们如何面对亵渎者萨拉德雷！"
D.Strings[8027]="我想要遗忘护甲锻造专精！"
D.Strings[8028]="我需要另一位灵魂猎手的帮助，阿托尔。"
D.Strings[8029]="如你所愿，$n。灵魂猎人已经准备好了。"
D.Strings[8030]="我在战壕中渡过了很久，还花了很多年来训练小狗们。回家的感觉真好。无论它变成了什么样子，那始终是我的家。"
D.Strings[8031]="照看这些让我的部族免受死亡威胁的无畏野兽是一种荣誉。"
D.Strings[8032]="谢谢你，$n。现在，去完成测试吧……"
D.Strings[8033]="啊，我明白了……"
D.Strings[8034]="是的，这真不幸。"
D.Strings[8035]="$n，我已经确认了这感染恶魔力量的鲜血是噬骨氏族的兽人们留下的。我担心不管用什么方式，我现有的设备都不能更进一步钻研这个秘密了……"
D.Strings[8036]="那些食人魔，他们把我埋起来，然后忘记回来了。$B$B嗯，朋友，有趣吧，笑吧。$B$B当然，要是你想帮我出来，我是不会让你吃亏的。$B$B如果你不想帮忙，就继续笑吧。"
D.Strings[8037]="它快死了！诅咒密码的第二部分是我们的。我……"
D.Strings[8038]="我在消失……回到阿托尔……回……到……"
D.Strings[8039]="%s知道已经来不及了，他甚至没有尝试跑开。"
D.Strings[8040]="<努埃恩摇了摇头。>$B$B燃烧军团和伊利丹的随从使我们腹背受敌，我们要做好牺牲一切的准备来防御要塞，绝对不能失败！真的蛮锤矮人宁死也不会抛弃自己的家园。"
D.Strings[8041]="你们看，我的个人收藏中有许多武器……"
D.Strings[8042]="立正，士兵！现在你要听从库卡隆卫士的指挥。"
D.Strings[8043]="也许我确实低估了你们。虽然让你们同时面对我的四位顾问显得有些不公平，但是我的人民从来都没有得到过公平的待遇。我只是在以牙还牙。"
D.Strings[8044]="学会阅读是很有必要的一件事。一块面包？"
D.Strings[8045]="在我开始测试的时候拜托离我远点……"
D.Strings[8046]="真有意思……"
D.Strings[8047]="但这是什么？"
D.Strings[8048]="哦，天哪！"
D.Strings[8049]="要不是我的血早已凝固了，它现在就会因愤怒而沸腾……"
D.Strings[8050]="这片土地仍然挂着旧日的伤痕，我在想它们是否能够痊愈。"
D.Strings[8051]="你能对我施放让我可以在水下呼吸和移动的魔法吗？"
D.Strings[8052]="葛雷克醉了！"
D.Strings[8053]="居住在赞加沼泽的蛮沼部族背着带锁的篮子，你应该有兴趣去挑战一下自己的技能。"
D.Strings[8054]="撬开纳格兰的基尔索罗堡垒里的箱子对你这样的潜行者来说，是一种莫大的挑战。"
D.Strings[8055]="脚步放轻，$r。地狱就在这座桥的前方。"
D.Strings[8056]="我只有一条命令。血战到底，不许退缩。"
D.Strings[8057]="给我上，你们这帮猿人，想老不死活一辈子吗？"
D.Strings[8058]="热热枪，然后把它们轰成渣！"
D.Strings[8059]="%s把腐烂的蛋敲碎，然后在众目睽睽之下开始吮吸它腐烂的核心。"
D.Strings[8060]="真是大起大落……对不起，我走开一分钟。"
D.Strings[8061]="%s打了一个嗝，那味道和声音让你觉得没什么能比它更恶心了……"
D.Strings[8062]="那么好吧，回去工作。"
D.Strings[8063]="我知道王子殿下会非常生气，但是我……我不知道自己怎么回事，居然把它们都放出来了！主人在对我说话，你也看到了……等等，有人来了。你们不是凯尔萨斯派来的！好极了……我会告诉王子殿下，是你们放走了囚犯！"
D.Strings[8064]="纳鲁把多种宇宙中最危险的怪物关在这些牢笼里。请允许我向你们介绍下一种……"
D.Strings[8065]="很好，很好……又是一个！你的意志是我的了！"
D.Strings[8066]="看吧！又一个拥有深不可测的力量的恐怖生物！"
D.Strings[8067]="我这是在什么鬼地方？你们又是谁……啊啊啊，头好疼啊！"
D.Strings[8068]="这是什么？一个卑微的侏儒？我下次会做得更好的，主人。"
D.Strings[8069]="混乱！疯狂！啊，您真是太睿智了！是的，我明白了，当然！"
D.Strings[8070]="还剩下最后一个牢笼。好的，主人，马上！"
D.Strings[8071]="控制弱者的思想是非常容易的事情……因为我所效忠的力量不会为时间所侵蚀，亦不被命运所左右。这个世界上没有什么力量能让我们屈膝……即使是燃烧军团也不行！"
D.Strings[8072]="你们的死期到了！"
D.Strings[8073]="欢迎您，主人。我是您谦卑的奴仆。"
D.Strings[8074]="“卑微”？我不在乎你是谁，伙计。没有人敢说强大的米尔豪斯是个“卑微”的侏儒！"
D.Strings[8075]="等等，我要准备一下。你们先上，我先来做点水……"
D.Strings[8076]="好极了！接下来，还得有些保护性的法术。耶！这样就对了！"
D.Strings[8077]="当然，我得先补充法力值。你们会看到我发威的，再等一会就行了……"
D.Strings[8078]="好啦！那么是哪个蠢货准备好好挨一顿打？！"
D.Strings[8079]="托什雷的基地是最好的！外域的能量资源是极端实验的理想配置。"
D.Strings[8080]="你和我的克隆体说过话了吗——我的意思是……我的双胞胎？"
D.Strings[8081]="我不敢相信他们居然把我的传送器弄出城去了！大部分受到事故影响的侏儒在过去的几周内都恢复了正常形态，而且他们应该对参与这么一个伟大的侏儒实验计划而感到荣幸！\n\n此外，我们需要蛋！"
D.Strings[8082]="我在永望镇的兄弟扎普帮我在52区建造了一台空间内爆器。当你拥有地精工程学即时传送装置时，谁还会需要火箭呢？你现在的地精工程学技巧足够娴熟了吗？你能制作自己的内爆器航标了吗？"
D.Strings[8083]="我希望安全传送器永远都不会让你失望！我认为它是不会出故障的！但是我还是建议你最好带一件降落伞披风……"
D.Strings[8084]="我们的增援在哪里？我现在就要增援！"
D.Strings[8085]="我们上吧！"
D.Strings[8086]="谁最猛？谁最猛？没错！我们最猛！"
D.Strings[8087]="谢谢你帮我脱身。算我欠你的！"
D.Strings[8088]="现在我应该可以从这里出来了，谢谢！"
D.Strings[8089]="这个地方真疯狂！我可以在这里花上很多年来钻研这些技术！"
D.Strings[8090]="末日领主卡扎克会高兴的。你最好加快你进攻的步伐，用最快的速度消灭这些兽人和矮人的要塞。"
D.Strings[8091]="不要担心。我已经提高了死亡熔炉的产量，你会拥有足够的地狱火的。不要让我失望，约瓦安。"
D.Strings[8092]="太好了，$n，你正在受到魔法的影响。我必须马上分析它，然后我们再谈谈。"
D.Strings[8093]="一切都进展得非常顺利，我的大人。塞纳里奥树林的小型样本测试非常成功。与此同时，第二个炸弹正在下面的院子里添加燃料。还有，我已经派了个信使去图雷姆把剩余的部分带回这里了。"
D.Strings[8094]="你满意了吧？"
D.Strings[8095]="暂时可以说不错。无论如何，请将我的到来作为一个催促的信号。凯尔萨斯王子对坠星山地区的水晶实验的失败很不满意，这也是我们选择塞纳里奥的德鲁伊们作为炸弹试验地的原因之一。"
D.Strings[8096]="如果院子里的那颗魔法炸弹没有很快对目标发射，不需要我再跟你说会发生什么事情了吧？自从我们到了森林里，不管是这里，还是在图雷姆，或是南面的噬骨废墟，他们对我们行动的干扰都愈加地烦人了。"
D.Strings[8097]="我向您保证，我们不会失败，我的主人。我亲自监视着工程的每一步，而且最终的密码掌握在我自己手中。一天以内，我就会让炸弹在周围那些讨厌的家伙身边引爆的。"
D.Strings[8098]="确保这一点，沙尔斯。否则我会亲自看到你慢慢地被折磨致死。"
D.Strings[8099]="我似乎认得他们。快点解决掉这里的麻烦，沙尔斯。然后用魔法炸弹摧毁他们的城镇！"
D.Strings[8100]="大人，请问有什么事？"
D.Strings[8101]="迦拉斯，你必须立即返回黑暗神殿！我……我似乎将伊利丹大人的命令弄丢了！快！"
D.Strings[8102]="大人，您显然不是希望我离开您身边吧？如果您有个什么闪失，伊利丹大人一定会惩罚我的。"
D.Strings[8103]="迦拉斯，我独自前往日蚀岗哨是不会有事的。如果我们未能将信件按时送达，伊利丹大人一定会发怒的！快上路吧！"
D.Strings[8104]="啊，好棒的血蓟……也许是日蚀岗哨那里的某个瘾君子留下来的。"
D.Strings[8105]="他们的损失对我来说就是意外的惊喜……"
D.Strings[8106]="%s把血蓟放进了他的袍子里面。"
D.Strings[8107]="躲起来！在他们看到你之前躲起来！后退！"
D.Strings[8108]="进攻的时刻即将到来。消灭伊喀琉斯。"
D.Strings[8109]="伯拉克，我需要另一捆血蓟。"
D.Strings[8110]="给你，不要再弄丢了！"
D.Strings[8111]="啊，该死！聪明的陷阱。很可惜，你永远不能活着讲述这个故事了……"
D.Strings[8112]="确实，这不是一个要求。"
D.Strings[8113]="大人！"
D.Strings[8114]="杜隆必须得到增援！乌提斯完全是个灾难。我不允许这种错误重演！"
D.Strings[8115]="一路上我们受到了太多的挫折：地狱火堡垒、坠星山、火翼岗哨……凯尔萨斯王子不能再容忍任何延误了。除了成功，我什么都不想看到。"
D.Strings[8116]="遵命，主人。"
D.Strings[8117]="你给我确保一切正常，阿尔杜尼斯！"
D.Strings[8118]="我要返回风暴要塞了。你们最好不要让我有回来的理由！"
D.Strings[8119]="我们应该给联盟和部落一点教训。刻骨铭心的教训！"
D.Strings[8120]="唉，有些时候，有些事情，必须得亲自解决才行。Balamore shanal！"
D.Strings[8121]="%s低头看着地上的项链。女王带着悲伤的神情吟唱了一段咒语，召唤出上层精灵的灵魂。整个房间中都回响着辛多雷那久远的歌声……"
D.Strings[8122]="你有什么东西要给我，大使？"
D.Strings[8123]="只是一本我觉得你可能会喜欢的小歌集而已。里面记录了一首名叫《上层精灵的挽歌》的歌词，那是希尔瓦娜斯心中的天籁之音。"
D.Strings[8124]="%s向附近的雄羊呼救！"
D.Strings[8125]="沙塔斯城有两座银行，它们都座落在城市中心的边缘上。一座由奥尔多的德莱尼人运作着，而另一座属于血精灵占星者。"
D.Strings[8126]="奥尔多银行"
D.Strings[8127]="占星者银行"
D.Strings[8128]="奥尔多银行座落在城市中心的西北。"
D.Strings[8129]="占星者银行座落在城市中心的东南。"
D.Strings[8130]="沙塔斯城的旅店里住满了受伤的难民。尽管如此，在奥尔多高地和占星者之台还有属于奥尔多的德莱尼人和血精灵占星者自己的旅店。"
D.Strings[8131]="奥尔多旅店"
D.Strings[8132]="占星者旅店"
D.Strings[8133]="奥尔多旅店坐落在沙塔斯城高处的奥尔多高地上。在城市中心的西北方有去那里的升降梯。"
D.Strings[8134]="占星者旅店坐落在沙塔斯城的占星者平台上。在城市中心的西南方有去那里的升降梯。"
D.Strings[8135]="沙塔斯城的飞行管理员是努特拉尔。你可以在城市中心的东面方找到他。"
D.Strings[8136]="奥尔多和占星者的银行或者旅店附近都有邮箱。"
D.Strings[8137]="在奥尔多高地的德莱尼旅店和占星者平台的血精灵旅店外面都能找到兽栏管理员。"
D.Strings[8138]="奥尔多兽栏"
D.Strings[8139]="占星者兽栏"
D.Strings[8140]="沙塔斯城的军官们经常聚集在上层平台和贫民窟之间的楼梯口。联盟的军官们在一个地方，部落的在另一个地方，竞技场管理员在他们中间。"
D.Strings[8141]="联盟战场军官"
D.Strings[8142]="部落军官"
D.Strings[8143]="你通常可以在城市中心东北方的楼梯口找到联盟的军官。"
D.Strings[8144]="你通常可以在城市中心东南方的楼梯口找到部落军官。"
D.Strings[8145]="你在找什么训练师？"
D.Strings[8146]="斯克提斯流浪者，宗师级炼金师罗罗基姆和与其他鸦人一起住在贫民窟的西北。"
D.Strings[8147]="你可以在东南方的贫民区露天市场找到正在烹饪的杰克·塔博尔。"
D.Strings[8148]="天涯旅店"
D.Strings[8149]="在贫民窟的最东面可以找到天涯旅店。"
D.Strings[8150]="高阶附魔师巴尔杜兰在占星者平台的先知图书馆。他是附魔的宗师，身边环绕着他的学生：初级附魔师，中级附魔师，高级附魔师和大师级附魔师。"
D.Strings[8151]="在贫民窟东北角的医务室内可以找到米尔蕾·弗莱彻尔。"
D.Strings[8152]="德莱尼人的宗师级珠宝匠哈曼纳尔在奥尔多高地，和他的同胞们在一起。"
D.Strings[8153]="宗师级剥皮师塞莫尔就在贫民窟的露天市场里，他也是沙塔斯城最好的剥皮师。"
D.Strings[8154]="在贫民窟的露天市场可以找到宗师级制皮师达尔玛里。"
D.Strings[8155]="护甲和武器工匠克拉度·利刃和祖拉·熔怒在贫民窟的大熔炉那里工作。"
D.Strings[8156]="谁敢妨碍总指挥官？"
D.Strings[8157]="我需要另一个伪装，伯拉克。上一个被我弄丢了。"
D.Strings[8158]="你们需要什么帮助吗？"
D.Strings[8159]="我带来了伊利丹大人的口谕。"
D.Strings[8160]="把密码碎片运走，送到祖鲁希德那里去。"
D.Strings[8161]="哦？那么你当然也把相关的书面文件带来了吧？"
D.Strings[8162]="也许你耳朵不太灵光，卢斯克。我向你传达的是伊利丹大人亲自发布的命令！"
D.Strings[8163]="听我说，苦工。我们对于运送和保护密码碎片有着严格的流程。大使传达盖有伊利丹大人徽记的信件。没有信件就免谈。"
D.Strings[8164]="好吧。我会返回黑暗神殿，告诉伊利丹大人你不想让他如愿。我建议你准备后事吧，告诉你的手下，你即将离开这个世界了。"
D.Strings[8165]="<卢斯克艰难地咽了口唾沫。>$B$B我……你是什么意思？"
D.Strings[8166]="真的需要让我描述每一个残酷的细节吗？我想我们都很清楚伊利丹大人会如何处置那些违背他命令的人！现在，我必须走了！保重，卢斯克！永别了……"
D.Strings[8167]="等等，你要去哪里？你要我转移碎片，对吗？我马上就安排，行不行？是送给龙喉堡垒的祖鲁希德吗？包在我们身上了。请让伊利丹大人知道，日蚀部队一定不辱使命。$B$B我会派亵渎者鲁尔亲自运送碎片的！$B$B你都听清楚了吧，我说的是鲁尔……"
D.Strings[8168]="啊，至少你的脑子还不蠢，卢斯克。多谢，请保重。"
D.Strings[8169]="万事俱备了，战争使者。"
D.Strings[8170]="战争使者，这可能需要动用要塞中所有的地狱火，我们也许会很容易遭到反击。"
D.Strings[8171]="我不怕你们！你们想打架？那就来呀！来呀！我不用前爪都可以打败你们！"
D.Strings[8172]="我该把你怎么办？我完全不知道。"
D.Strings[8173]="我真的需要一颗心。啊，用你的行吗？"
D.Strings[8174]="谨遵教诲，战争使者。还有最后一个问题，我是否可以……"
D.Strings[8175]="箱子里有什么？"
D.Strings[8176]="箱子？我没有给你箱子啊，约瓦安。你是不是应该去关心点别的？去工作！"
D.Strings[8177]="由于得到了加基森工程师霍尔迪·水炉的帮助，我在这里托什雷的基地建造了一台威力强大的侏儒传送器！我很乐意帮助任何有技术实力的侏儒工程师来制造他们自己的传送航标。"
D.Strings[8178]="为什么你离托什雷的基地这么远？"
D.Strings[8179]="控制被召唤的水元素"
D.Strings[8180]="<水元素准备涌动了。>"
D.Strings[8181]="<骑兵自豪地站立着，蓄势待发。>"
D.Strings[8182]="控制人类骑兵"
D.Strings[8183]="你的生命走到尽头了。"
D.Strings[8184]="天空会陷入黑暗，整个世界也将沉寂。只有那时，你才能体验到死亡那甜蜜的幽静。"
D.Strings[8185]="<牧师用眼角的余光盯着你。>"
D.Strings[8186]="控制人类祭司"
D.Strings[8187]="<召唤师原地矗立，凝视着远方。>"
D.Strings[8188]="控制人类召唤师"
D.Strings[8189]="<即使只是一枚棋子，莱恩国王的力量和智慧仍闪烁着光芒。>"
D.Strings[8190]="控制莱恩国王"
D.Strings[8191]="森卢肯被唤醒了！"
D.Strings[8192]="你将尝到永恒的痛楚！"
D.Strings[8193]="森卢肯来取你们的性命了！"
D.Strings[8194]="玩火者必自焚！"
D.Strings[8195]="一个火焰漩涡显现了出来。"
D.Strings[8196]="你不是一个人在战斗，你不是一个人，$n！让我们一起放逐这地狱之火的子嗣！"
D.Strings[8197]="你准备好了我们就开战，$n。"
D.Strings[8198]="我准备好了，欧鲁诺克。让我们消灭森卢肯，解救这些元素吧！"
D.Strings[8199]="渺小的血肉之躯们，你们的愿望即将成真！你们的死期即将来临！"
D.Strings[8200]="我们会用武力把元素之灵从你的魔掌中解救出来！"
D.Strings[8201]="你准备好了我们就开战。"
D.Strings[8202]="我能流利地说两种语言：矮人语，和略带人类口音的侏儒语。但是我根本不知道你在说什么！！$B$B说大声点！齿轮的摩擦让我根本听不见你在说什么！！"
D.Strings[8203]="是的，是的……欢迎来到我的基地。$B$B那么，你觉得怎么样？你是想说我们在这里干得很漂亮是吧？$B$B不管怎样，能摆脱希尔瓦纳的那些乏味的精灵真让我感到高兴。$B$B在这里找点活干吧，那边有很多实验需要人手。"
D.Strings[8204]="荣耀属于纳鲁，$n。敌人将在圣光的照耀下湮灭！"
D.Strings[8205]="<兽人步兵的嘴里流着口水，期待着一场战斗。>"
D.Strings[8206]="%s注视着$n！"
D.Strings[8207]="<被召唤出来的恶魔抽搐着，反抗着麦迪文的游戏规则。他想要你的灵魂！>"
D.Strings[8208]="控制被召唤的恶魔"
D.Strings[8209]="这个矮人似乎是在执行侦察任务时被发现而惨遭杀害。死亡熔炉的随从们把他曝尸荒野，也许是用来警告其他的入侵者。"
D.Strings[8210]="拿走弗兰尼斯的背包。"
D.Strings[8211]="元素们说了些什么，托洛克？我什么都没听到。"
D.Strings[8212]="我听到的和你一样，兄弟。看看你身后……"
D.Strings[8213]="他们得到了救赎！那么我们胜利了？"
D.Strings[8214]="就应该是现在这样，萨满祭司。你干得不错。"
D.Strings[8215]="是的……对这里的元素来说，已经很好了，但是密码已经被别人知道了……火焰之灵正在骚动……如果不阻止这股力量，这些凡人所属的世界将会灭亡。"
D.Strings[8216]="保重，凡人……大地治愈者了解火焰之灵的感受……"
D.Strings[8217]="那么我们走了，托洛克。我只有一个要求……"
D.Strings[8218]="欧鲁诺克·裂心等人把他们的武器交给了大地治愈者托洛克。"
D.Strings[8219]="把这些武器交给英雄们，助他们一臂之力。"
D.Strings[8220]="遵命！"
D.Strings[8221]="<奥术守护者似乎面对着你，但是没有说话。>"
D.Strings[8222]="<奥术守护者指了指贫民窟的最东面。>"
D.Strings[8223]="<奥术守护者指了指城市中心东南面的一处地方。>"
D.Strings[8224]="<奥术守护者指了指平台对面的旅店。>"
D.Strings[8225]="<通灵师的黑暗魔法泛起了波纹。>"
D.Strings[8226]="控制兽人通灵师"
D.Strings[8227]="<奥术守护者指了指城市中心东面的一处地方。>"
D.Strings[8228]="<奥术守护者指了指平台对面的旅店和邮箱。>"
D.Strings[8229]="<奥术守护者指了指平台对面的旅店和外面的兽栏管理员。>"
D.Strings[8230]="<奥术守护者静静地站在那，等着你告诉它你想询问哪个战场军官。>"
D.Strings[8231]="<兽人座狼的血盆大口让你毛骨悚然。>"
D.Strings[8232]="控制兽人座狼"
D.Strings[8233]="<术士的双眼中积郁着深深的怨毒。>"
D.Strings[8234]="控制兽人术士"
D.Strings[8235]="<黑手酋长俯瞰着战场。>"
D.Strings[8236]="控制黑手酋长"
D.Strings[8237]="我是个研究时间和声音的科学家，因此我不十分确信我该怎么来思考，或是找个时间在这喧嚣里来完成什么工作。$B$B为什么这些蠢货不把他们自己炸到其他地方去呢？$B$B啊，好吧，至少我看起来不错。对了， $g小子:小姑娘;，我以前在这里见过你吗？"
D.Strings[8238]="快点放了我！不然就面对我的愤怒吧！"
D.Strings[8239]="哪个$r竟敢伤害我的手下？"
D.Strings[8240]="为了保持道路的整洁，兽人的尸体被随便地丢弃在路的两旁。"
D.Strings[8241]="在尸体上寻找卡格罗什的背包。"
D.Strings[8242]="这里有凡人？这是什么意思，你这可悲的破碎者！"
D.Strings[8243]="不要害怕，$r。继续假装下去。"
D.Strings[8244]="一点小麻烦而已，我保证！请转告主人，阿卡玛和他手下的死誓者会尽心尽职地看守囚犯。"
D.Strings[8245]="阿卡玛，别跟我耍花招。伊利丹大人要我密切注视玛维·影歌的一举一动。要是你敢对我隐瞒什么，我就亲手捏碎你！"
D.Strings[8246]="请原谅我的粗暴，我不能让背叛者知道真相。无论如何都要守住我的秘密！"
D.Strings[8247]="我的许多同胞都认为我是叛徒……是伊利丹的走狗。现在也许他们这么想才更好。"
D.Strings[8248]="如果我们期望的是同一件事，阿卡玛，那么你就放了我！如果伊利丹要死，那也要是死在我的手上！"
D.Strings[8249]="不会太久了，玛维。我花了这么多年来筹划我的行动——我不能让这个计划因为操之过急而毁于一旦。"
D.Strings[8250]="我诅咒你，阿卡玛！我不是你的棋子……我有我自己的意志。当我对伊利丹倾泻我的愤怒时，那必定和你愚蠢的阴谋没有任何关系！"
D.Strings[8251]="所有悬赏的奖励品都由战争召唤者萨尔东·图斯莱分配。$B$B张贴悬赏令不需支付金币。"
D.Strings[8252]="所有悬赏的奖励品都由战争召唤者比尔斯诺特分配。$B$B张贴悬赏令不需支付金币。"
D.Strings[8253]="有这样的奖励，他们怎么可能拒绝呢？"
D.Strings[8254]="准备好具化间，新的同盟很快就会加入我们！"
D.Strings[8255]="我们的同盟到了！打开具化间！"
D.Strings[8256]="现在，向传送器进发。铸魔营地：天罚等着你的到来！"
D.Strings[8257]="欢迎来到托什雷的基地旅店。我能为你做些什么？"
D.Strings[8258]="你对学习复杂的珠宝加工感兴趣吗？"
D.Strings[8259]="选矿是找到宝石的主要途径！你只需简单地使用选矿技能（可以在你的法术书的综合标签中找到）就可以在一组五个的矿石中找到宝石。任何非贵重的矿石都可以！\n\n更好的矿石会提供更有价值的宝石，也就是说你从铁矿石里找到的宝石比从铜矿石中找到的更好！"
D.Strings[8260]="关于珠宝加工，你想知道些什么？"
D.Strings[8261]="不要再来找我，等你掌握了初级的珠宝加工技能再说。"
D.Strings[8262]="我会和你分享我的珠宝加工知识。"
D.Strings[8263]="制造珠宝和雕琢宝石是我生存的理由。想让我把这种激情分享给你吗？"
D.Strings[8264]="我希望有更多的时间来向所有找我学习的人传授知识，但是做事必须循序渐进。在你把帕达尔教你的东西都学会之前，我帮不了你。"
D.Strings[8265]="我很愿意教你这样的技术人才更多的珠宝加工知识。你想知道什么？"
D.Strings[8266]="我非常忙，$r。$B$B我们现在有一个非常棘手的问题需要立刻解决！"
D.Strings[8267]="希尔达迦，我需要一副新的眼镜。"
D.Strings[8268]="最后一批了，伙计们！让他们尝尝厉害！"
D.Strings[8269]="这是他们最后的挣扎了。不要大意。"
D.Strings[8270]="干得好，士兵们！这是他们最后的挣扎了！"
D.Strings[8271]="骑兵们，让我们杀出去吧！"
D.Strings[8272]="伊利丹对这个地方的控制逐渐放松了。你能感觉到吗，$n？"
D.Strings[8273]="当你和拉沙克驯马师一起逃跑的时候，你会学到这么两件事。$B$B第一件是：战斗，直到死亡；第二件是：参照第一件事。"
D.Strings[8274]="你要磨刀还是要一把新武器？安全第一、安全第一……"
D.Strings[8275]="要是你想买把锤子，那你可找对地方了。"
D.Strings[8276]="$G孩子:年轻的女士;，我不准备向你撒谎，这里的事情不是那么如意。我们受到了虫子持续的攻击，我们的生活、我们的自由，都受到了威胁！$B$B你愿意尽一位好公民的责任来帮助我们吗？"
D.Strings[8277]="在最黑暗的夜晚，乌鸦将再次飞起，它将飞入阴影，显露本性。当它到来之时，虔诚的信徒会随它一并飞翔，剩余的人将被遗忘在大地之上，夹着翅膀羞愧不已。"
D.Strings[8278]="坚定你的信念，捍卫你的想法。黑暗之翼会淹没与吞噬弱者的信念。他们的双脚将永远无法离开大地高飞。"
D.Strings[8279]="古神的血液会因为乌鸦的到来而再度流淌，黑暗将在天际重现。猩红的夜晚，古神将会复生。"
D.Strings[8280]="乌鸦曾因贸然飞得太高而被击落。黑暗守望者为了他的飞翔准备了亿万年，就是为了在地平线上拉起黑暗的斗篷。"
D.Strings[8281]="塔隆·血魔？没错……我认识他。"
D.Strings[8282]="太精彩了！精彩绝伦！多华丽的演出啊！"
D.Strings[8283]="我年轻的时候刻苦训练，是为了成为牧师中的学者。那时候我从没听说过还有女性主教。$B$B现在性别已经不是问题了——那是因为勇气和信仰会改变一切。"
D.Strings[8284]="你的躯体为我所有！我们的命运将永远纠缠在一起！"
D.Strings[8285]="如果你准备好了，并且希望能尽快回到正常的时间流，我可以把你传送回去。"
D.Strings[8286]="请让我返回我的时间流。"
D.Strings[8287]="修正流动的时间是非常困难和精细的工作，但是你今天表现得很完美。"
D.Strings[8288]="不……不！你在干什么？我才是主宰！你听到没有？我……啊啊啊啊！控制……不住了。"
D.Strings[8289]="我终于解放了。很久都没有感受到真正的自由了！"
D.Strings[8290]="不要浪费时间，蠢货！用我们的力量来消灭那些挡路的家伙！在你被抑制之前消灭卡修斯！"
D.Strings[8291]="血魔，你最好打消逃跑的念头。离开这个$G小伙子:姑娘;的躯体，投降吧！即便你全力以赴，也是不可能逃走的！"
D.Strings[8292]="你……做了些什么……"
D.Strings[8293]="我们总有一天……会再见面的。"
D.Strings[8294]="死亡的化身再度降临这个世界！塔隆·血魔回来了……"
D.Strings[8295]="不要感觉……太好。"
D.Strings[8296]="什么时候再开饭？"
D.Strings[8297]="站住！"
D.Strings[8298]="你是来帮忙平息混乱的？"
D.Strings[8299]="索鲁斯，我要一副新的护目镜。"
D.Strings[8300]="给我讲讲一些关于卡拉波废墟的恶魔猎手训练场的事情吧。"
D.Strings[8301]="作为多年效忠的奖励，伊利丹允许凯尔萨斯将五名战士送到他那里进行特训。这应该是有史以来第一次有血精灵被允许参与恶魔猎手的训练。$B$B训练是严酷的，凯尔萨斯的战士所经受的考验足以难倒大部分的训练有素的恶魔猎手。$B$B三个凯尔萨斯的血精灵在训练中死去——另一个疯了。$B$B只有一个成功了。"
D.Strings[8302]="他就是瓦雷迪斯。让伊利丹感到意外的是，瓦雷迪斯不仅成功征服了极其痛苦的仪式之路，还显示出了比其他身经百战的恶魔猎手更能支配自己力量的天赋。$B$B伊利丹察觉到了瓦雷迪斯的潜力，指派了三名恶魔猎手大师来进一步训练他。"
D.Strings[8303]="在伊利丹手下最好的三名恶魔猎手的训练之下，一年后，瓦雷迪斯已然青出于蓝。$B$B他不再满足于恶魔猎手所提供的训练内容，于是瓦雷迪斯混入了暗影议会，在那里，他得知有一本叫做恶魔名册的圣物，书中蕴含着强大的力量。他偷偷地通读了这本书，把每一页都暗暗记在了心里。"
D.Strings[8304]="传说，知晓一个恶魔的真名即可获得超越他的力量。$B$B恶魔名册记载着所有真实存在的恶魔的名字。在默记书中的章节时，瓦雷迪斯发现了一种力量来源，这种力量可以与伊利丹从古尔丹之颅中汲取的力量相媲美。$B$B在伊利丹的要求下，瓦雷迪斯和三位指导过他的恶魔猎手大师们一起管理着卡拉波废墟的训练场。"
D.Strings[8305]="滚开，凡人！你在这里不受欢迎……"
D.Strings[8306]="对于血精灵拥有着可以掌握恶魔猎手力量的天赋，我一点都不感到吃惊。毕竟，辛多雷并不像暗夜精灵那样天生讨厌恶魔法。$B$B然而，我并不希望太多的血精灵可以掌握这种力量。大部分人，包括瓦雷迪斯，都把追逐力量作为一种乐趣。但那力量会吞噬他们，因为驱动他们的并不是真正的恶魔猎手心中燃烧的那团纯焰。"
D.Strings[8307]="说来话长。"
D.Strings[8308]="我还有其他事想问你，奥图里斯。"
D.Strings[8309]="我在听。"
D.Strings[8310]="你可以让一个人脱离洛萨之子组织，但你不能从他心中抹去这个身份的意义。$B$B<工匠耸了耸肩。>$B$B这很难解释，但是我觉得我不应该呆在荣耀堡。$B$B或许我应该成就一番伟业。"
D.Strings[8311]="穆曼的小店就在城市主入口附近，就是刚过旅店的那家美食店。"
D.Strings[8312]="魔法织布机"
D.Strings[8313]="位于花园街市西北角的基伦裁缝店里有你说的那种织布机。"
D.Strings[8314]="滚开吧，脆弱的精灵。现在我说了算！"
D.Strings[8315]="我的放逐终于结束了！"
D.Strings[8316]="我们内心都有一只恶魔……"
D.Strings[8317]="<奥术守护者静静地等着你的进一步描述。>"
D.Strings[8318]="啊……毒性侵袭了我……"
D.Strings[8319]="感觉好多了。"
D.Strings[8320]="你想从我这里得到什么，萨满祭司？"
D.Strings[8321]="你瞎了吗？你没看见恶魔已经打到家门口了吗？我没有人手给你！"
D.Strings[8322]="向你的神祈祷吧，萨满祭司。也许他们会来帮助你的。然而部落是不可能……"
D.Strings[8323]="我不明白！你瞎了吗？你没看到恶魔们正在攻击我们的大门吗？我能派谁出去和你的萨满朋友谈话？告诉我！"
D.Strings[8324]="这本书将赐予我无尽的力量……我会变得……无坚不摧！"
D.Strings[8325]="不……你必须把这东西从我这里拿走，$n！我感觉到它的黑暗力量已经开始动摇我的意志了！用它来消灭瓦雷迪斯吧。"
D.Strings[8326]="“因为你刚才离开过棋局，所以你暂时还不能控制我。”"
D.Strings[8327]="想穿越我的大厅，你就必须用你的精湛棋艺来击败我！当你准备好了之后，就去控制你的国王……"
D.Strings[8328]="无论我给你什么样的对付食人魔的建议，你都要听取！"
D.Strings[8329]="公告上写着去杀死一头凶恶的狼的内容。她的巢穴就在锯齿山的南面，靠近那里的部落要塞。"
D.Strings[8330]="<奥术守护者指了指平台下面，城市中心东北方向的楼梯。>"
D.Strings[8331]="<奥术守护者指了指平台下面，城市中心东南方向的楼梯。>"
D.Strings[8332]="<奥术守护者指了指贫民窟的西北部分，沙塔斯城的鸦人居住地。>"
D.Strings[8333]="<奥术守护者指了指下面的贫民窟，在那里可以找到一座巨大的熔炉。>"
D.Strings[8334]="<奥术守护者指了指贫民窟的露天市场，就在东南方。>"
D.Strings[8335]="继续，杀了他们吧！我会变得更强大！"
D.Strings[8336]="更多的知识，更多的力量！"
D.Strings[8337]="我从来都没有如此强大过！"
D.Strings[8338]="<奥术守护者指了指贫民窟的东北区域。>"
D.Strings[8339]="<奥术守护者指了指奥尔多高地。>"
D.Strings[8340]="<奥术守护者指了指贫民窟的露天市场。>"
D.Strings[8341]="欢迎来到奥尔多高地，你在寻求指引吗？"
D.Strings[8342]="医护中心位于奥尔多高地的南部。"
D.Strings[8343]="医护中心附近就有邮箱。"
D.Strings[8344]="兽栏管理员在医护中心附近。"
D.Strings[8345]="你可以在奥尔多高地的北部找到宗师级珠宝匠哈曼纳尔。"
D.Strings[8346]="你好，$C——我是银月城的嘉奖官。我的职责就是帮助那些获得部落荣誉徽章的冒险者们。$B$B我一次可以收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章就能获得最高的收益。我会保留你缴纳徽章的记录，你在银月城的声望也会因此提高。"
D.Strings[8347]="你好，$C——我是埃索达的嘉奖官。我的职责就是帮助那些获得联盟荣誉徽章的冒险者们。$B$B我一次可以收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章就能获得最高的收益。我会保留你缴纳徽章的记录，你在埃索达的声望也会因此提高。"
D.Strings[8348]="灵岩巨人？！那东西一脚就能把你踩扁！不用了，谢谢！"
D.Strings[8349]="上次有人妄想获得灵岩巨人的赏金，最后那个愚蠢的冒险者被踩成了照片。"
D.Strings[8350]="刀锋山是充满机遇的地方。不幸的是总有些家伙自认为他们要比其他人更能占有先机。$B$B塞纳里奥远征队觉得他们自己是谁？居然敢在这里对我们指手画脚？"
D.Strings[8351]="工头，我是来代表塞纳里奥远征队和你谈判的。"
D.Strings[8352]="谈判？谈判！$B$B请允许我把我们的立场完全说清楚。我们是自由人，没有人能干涉我们的自由。塞纳里奥远征队并不是这片山脉的主人。$B$B所以没有什么好谈的！现在，回去告诉那些德鲁伊，我们还是要我行我素。"
D.Strings[8353]="我们来到卢安荒野是想看看是否能够帮助这些山脉恢复自然的平衡。$B$B然而，我们与鸦人和拜龙教之间的矛盾让这个任务变得困难起来。$B$B幸运的是，还有像你和萨米亚那样的人愿意帮助我们。"
D.Strings[8354]="哈哈，你回来了？你不会真的期盼我改变心意吧？$B$B你错了。"
D.Strings[8355]="我已经准备好开始测试飞行了！"
D.Strings[8356]="送我到拉扎安码头去！"
D.Strings[8357]="带我去卢安。"
D.Strings[8358]="带我去晶歌山脉。"
D.Strings[8359]="开火！"
D.Strings[8360]="我们可以控制住形势了。硬汉队，你们可以休息了。"
D.Strings[8361]="我在你的大肠后部区域检测到了电荷！你最近肯定使用过风动电容器……在电荷消失前，你不能再使用它了……"
D.Strings[8362]="我的主人萨博迈恩男爵派我来这里帮助塞纳里奥远征队解决他们与拜龙教之间的问题。$B$B我是这方面的专家。"
D.Strings[8363]="我本不想屈尊与你们交战，但是你们让我别无选择……"
D.Strings[8364]="努埃尔，你还好吧？你今天看上去有些不大对劲。"
D.Strings[8365]="滚开，工头！我们已经谈过了。$B$B别再磨蹭了，去卢安荒野执行命令吧。"
D.Strings[8366]="我很好，谢谢你。你在找我？"
D.Strings[8367]="是的，让我们静下心来商讨一下吧。$B$B实际上，你负责把木材和家畜汇聚到卢安荒野，而你的进度越来越慢了。$B$B我们需要那些资源，但是你却让塞纳里奥远征队的德鲁伊来妨碍我们！"
D.Strings[8368]="哦，这不是我的错，我向你保证。"
D.Strings[8369]="我不要借口，我需要结果！$B$B你觉得我像是在开玩笑吗？如果我们不这么做的话，那么不仅那些所谓的好人们会跑过来叫嚷，而且这也对提升黑翼的繁荣没有任何价值。$B$B那是你想看到的结果吗？"
D.Strings[8370]="呃，不……不，我压根没想过。"
D.Strings[8371]="你怎么着也应该说得可信一点吧。$B$B努埃尔，我原本不打算告诉你这件事的，但是你还是知道为好，因为你跟这件事扯上关系了。玛克纳尔正筹划着对卢安荒野的德鲁伊们发动一次全面进攻，并且把他们一网打尽。$B$B对我们来说，和砾石食人魔们战斗已经足够糟糕了，所以我们不能双线作战。我准备和鸦人签署短暂的停战协议。$B$B你觉得怎么样？"
D.Strings[8372]="太棒了。我们什么时候进攻？"
D.Strings[8373]="我们现在正紧锣密鼓地进行着最后的准备。剩下的就要看你能多快地组织起你在卢安荒野的力量了。$B$B你觉得你能迅速搞定这件事吗？"
D.Strings[8374]="这就对了！$B$B这次小碰头会让我很高兴，我对进攻更有信心了。有你这样的领袖在前线，我们怎么可能输呢？$B$B好吧，这是你的行军令。返回卢安荒野，付诸实施吧！"
D.Strings[8375]="卡拉赞并非永远被厄运所笼罩。卡拉赞的黑暗是在麦迪文死后才降临的。或者说是我们认为如此。"
D.Strings[8376]="事情到了这一步，我们已经不能回头了。"
D.Strings[8377]="嗨，监工。准备好发动攻击了吗？"
D.Strings[8378]="您需要什么吗，长官？"
D.Strings[8379]="你看上去气色不好，监工。"
D.Strings[8380]="我听说库尔菲斯·暗鳞一直在找你。"
D.Strings[8381]="萨米亚，你知道谁是库尔菲斯·暗鳞吗？"
D.Strings[8382]="嗯，他是拜龙教的人，西边黑翼集会所的副指挥。"
D.Strings[8383]="这些德鲁伊好像有一个巨大的能量源！他们可以变成动物……放射出闪电和强烈的月光……我必须要弄清楚他们是怎么做到这些的！$B$B也许他们的长袍下绑着蓄电池……"
D.Strings[8384]="<鸦人用诡异的眼神上下打量着你。>$B$B我们的努力非但没有结果，怎么反而还招来了一个新的怪物？"
D.Strings[8385]="在外域，为了争夺风暴之眼的控制权，我们与部落展开了激烈的战斗。在虚空的狂暴能量之间战斗是很危险的。你是否想加入我们呢？"
D.Strings[8386]="风暴之眼中的魔法晶格非常珍贵，我们不能把它们拱手送给德莱尼人！你！协助我们作战吧！在战火中证明你的价值！"
D.Strings[8387]="$n！过来！相信你肯定听说过艾泽拉斯大陆上著名的奥特兰克山谷吧。我们需要集合所有强壮的士兵，与雷矛卫兵一起击败霜狼氏族！"
D.Strings[8388]="这次飞行将把你带到远方的晶歌山脉。那里是非常危险的！$B$B正因为如此，我需要你签一份免责声明……"
D.Strings[8389]="我已经签署免责声明了！把我发射到晶歌山脉去吧！"
D.Strings[8390]="我们永远渴望得到更多的飞行资料！你想去哪里？"
D.Strings[8391]="我想飞回曾经去过的地方！"
D.Strings[8392]="%s开始引导奥术能量……"
D.Strings[8393]="我需要另一份免责声明！"
D.Strings[8394]="又怎么了？你没看到我正在忙吗？"
D.Strings[8395]="在新大陆的探索无疑非常重要，但是你不能遗忘艾泽拉斯！我们比以前更加需要你去和污染者作战！那些资源需要得到保护！"
D.Strings[8396]="嗨，$C！我们需要你的帮助！战歌氏族的那些野蛮兽人正在破坏风景如画的灰谷，我们希望你能在战场上跟这帮家伙一较高下。跟我们返回艾泽拉斯世界，为了银翼哨兵的荣耀而战！好吗？"
D.Strings[8397]="嗯……你想要什么，$r？你没看到我这里正忙着吗？"
D.Strings[8398]="古语说得好，“授人以鱼，不如授之以渔，授人以鱼只救一时之急，授人以渔则可解一生之需。”当然，你如果想学煮鱼的话，找我就对了。"
D.Strings[8399]="你好，$n！你的冒险怎么样了？我的实验进展很不错……$B$B记得以后要经常回来看看我！我可能有更多的测试飞行机会给你哦！"
D.Strings[8400]="力量和荣誉，$c。我们非常渴望像你这样的士兵能前往奥特兰克山谷，保卫霜狼氏族的领土！你会回到艾泽拉斯帮助我们吗？"
D.Strings[8401]="$c！是的，就是你！为什么你会在这座破败的城市里闲逛着浪费时间，而不是出现在阿拉希盆地的战场上？我们阿拉索联军正被敌人无情地攻击，我们需要你的奉献，而且你也一定会得到奖励的！"
D.Strings[8402]="$C，回到艾泽拉斯吧， 银翼哨兵妨碍了我们在森林里的伐木工作。我们需要你赶赴那边的前线，将战线推回去！如果你帮助我们，就将获得无上的荣誉，在战歌氏族当中也会积累很高的声望——现在就加入我们吧！"
D.Strings[8403]="先救救你自己吧，$r。立刻从这个地方逃走！如果你被发现的话，一定会被火色魔印就地处死。"
D.Strings[8404]="热砂格斗联赛已经开始了。竞技场组织者正在加基森、纳格兰竞技场和刀锋山竞技场外兜售竞技场战队登记表。"
D.Strings[8405]="热砂格斗联赛就要开始了。现在，地精们正在竞技场组织练习赛，正式的排位赛将在$4262d后开始。"
D.Strings[8406]="<灰头发的角斗士用结结巴巴的通用语说着。>什么？你对我有意见？上竞技场去解决吧。我不会为你们的什么小“部落”和小“联盟”浪费时间。"
D.Strings[8407]="<身经百战的角斗士用结结巴巴的通用语说着。>什么？你对我有意见？上竞技场去解决吧。我不会为你们的什么小“部落”和小“联盟”浪费时间。"
D.Strings[8408]="角斗士们通过在竞技场的段位赛中取胜来获得使用我身上这套装备的权利。"
D.Strings[8409]="哟！你听说过热砂港搏击会吗？\n\n你可以在加基森城内以及纳格兰和刀锋山的竞技场外面找到竞技场组织者，他正在出售竞技场战队登记表。"
D.Strings[8410]="你好。在休息吗，监工？自从你被派去卢安荒野以后，我们就很少能在这里看到你了。$B$B看看我这些东西，似乎跟我们上次见面的时候没什么改变，但是我这里存货很多。$B$B别这么客气嘛！"
D.Strings[8411]="非常好，让我看看你有什么。"
D.Strings[8412]="我讨厌别人打断我说话，但我更讨厌屠龙者格鲁尔和他的七个儿子！"
D.Strings[8413]="竞技场排位赛会在$4262d后开始。想要成为冠军的人已经开始忙着磨炼技术和寻找最好的装备了。你呢，准备好了吗？"
D.Strings[8414]="你必须……解救……我的孩子们……"
D.Strings[8415]="他们不能继续这样！他们的翅膀终将……"
D.Strings[8416]="你的命运早已注定。"
D.Strings[8417]="我所播种的混乱只是一个开端……"
D.Strings[8418]="我只是一个……不值一提的小角色。"
D.Strings[8419]="你将听从我的指挥。"
D.Strings[8420]="恐惧吧！逃跑吧！"
D.Strings[8421]="我会让你体验到前所未有的恐惧。"
D.Strings[8422]="我们遍布宇宙的每一个角落，像群星一样无穷无尽！"
D.Strings[8423]="我甚至都没有流一滴汗！"
D.Strings[8424]="你们随时都可以来跟我一起作战！"
D.Strings[8425]="我要把你们烤熟了！"
D.Strings[8426]="冰冰凉，宝贝！"
D.Strings[8427]="治疗我！天杀的，赶快治疗我！我要嗝屁了！"
D.Strings[8428]="你很快就会收到我的律师函了！"
D.Strings[8429]="谢谢你，凡人。"
D.Strings[8430]="啊，又有一个想成为角斗士的$c，嗯？很好！\n\n我可以卖给你参加热砂搏击会的赛事所必需的竞技场战队登记表。"
D.Strings[8431]="怎样才能组建一支竞技场战队？"
D.Strings[8432]="你的自负将给你带来灭亡！卫兵，把你们的力量借给我!"
D.Strings[8433]="断背岗哨真是一处优秀的营地！离那些血环的邪兽人们那么近，甚至都可以闻到他们肮脏的血液的味道！那个氏族竟然遗忘了它的同伴，还和恶魔之间达成了协议，让我们在此向他们发起复仇吧！"
D.Strings[8434]="愤怒之心……很久以前，维伦持有它的时候，我目睹过它的力量。而现在，我依然可以感觉到相同的力量正在它内部澎湃着！"
D.Strings[8435]="有了这块水晶的力量，我的死誓者和我……将会不可抵挡！我们甚至可以消灭伊利丹！我们可以……替代他成为新的外域之王！"
D.Strings[8436]="但那不是纳鲁在我的梦境中给予我的指示……那不是……我解救同胞的方式。"
D.Strings[8437]="法维瑟和我在这里代表着希尔瓦纳的利益。$B$B这里的德鲁伊未免过于热情好客了，竟然允许部落随意穿越这里，这让我感到非常不安。"
D.Strings[8438]="你好，凡人。"
D.Strings[8439]="我在听着呢，龙。"
D.Strings[8440]="龙喉要塞坐落在灵翼平原的东部区域。在那里，无数残酷的龙喉氏族兽人正在折磨着他们抓来的虚空幼龙，甚至尝试扭曲它们的意志。很多幼龙就此放弃了对自由的希望，选择屈服，并开始遵守龙喉兽人的命令。而其它幼龙……它们因为害怕被龙喉兽人抓住而不敢降落，只能在天上不停地飞翔。"
D.Strings[8441]="我……我们无力反抗。伊利丹找到了龙喉氏族的首领祖鲁希德。他曾经参与过抓获和囚禁阿莱克丝塔萨的行动。我们要怎么才能反抗这样的力量呢？他甚至曾经捕获过一只强大的守护巨龙！$B$B而且他同样这么简单地捕获了我的配偶。"
D.Strings[8442]="你的配偶？"
D.Strings[8443]="<奈尔萨拉库点了点头。>$B$B卡瑞纳库……她被关押在龙喉要塞的顶部。为了解救她，我已经试遍了各种方法。不幸的是，所有的尝试都失败了……你曾经和这些野蛮的家伙战斗过吗？"
D.Strings[8444]="我与许多野蛮的家伙都战斗过，龙。我会帮你的。"
D.Strings[8445]="$n，你必须把愤怒之心带到安全的地方去……你必须把它交给阿达尔！"
D.Strings[8446]="发现入侵者！立即终结威胁！"
D.Strings[8447]="我不能那么慷慨地……与你分享信息。你必须向我证明，你与我有着共同的敌人。"
D.Strings[8448]="愚蠢的小家伙！我打！"
D.Strings[8449]="我抓狂了。我要抽你的脸！"
D.Strings[8450]="我生气了。啊呀呀呀呀呀呀！"
D.Strings[8451]="与凯尔萨斯和伊利丹的战斗仍然在前线继续进行着。我们只可成功，不许失败。"
D.Strings[8452]="部落的兽人们！这个入口将是通向全新命运的道路！艾泽拉斯就在你的面前，等待着你们去占领。"
D.Strings[8453]="古尔丹说得不错！我们应该一起回去把这个消息告诉我们的弟兄们！从黑暗之门撤退！"
D.Strings[8454]="据我所知，你最近才加入我们，可能并不清楚我们的传统。月光林地那边正在举办一场庞大的庆典。这是一年一度向长者们致敬的日子，你被邀请了！如果你想加入的话，去任何一座城市都可以！"
D.Strings[8455]="艾泽拉斯各地都在庆祝春节！回到那边去吧，在这个伟大的节日向你的长者表达敬意吧！最大的庆典活动会在月光林地举行，但我们在暴风城、铁炉堡、达纳苏斯、雷霆崖、奥格瑞玛和幽暗城也都提供了方便快捷的传送器。希望能在那边见到你，一定要来哦！"
D.Strings[8456]="这里有着我们兽人不顾一切想要揭开的秘密。有关我们过去的秘密，有关我们未来的秘密，还有能够反映我们内心的秘密。$B$B我毕生的愿望就是揭开这些秘密的面纱……你愿意和我一起进行研究吗？"
D.Strings[8457]="过来，我会好好欢迎你们的！"
D.Strings[8458]="啊，不要哀号了。"
D.Strings[8459]="任务完成！"
D.Strings[8460]="你可不是在跟跑龙套的打交道！"
D.Strings[8461]="卫兵！干掉这些入侵者！"
D.Strings[8462]="我还……没有开始……"
D.Strings[8463]="%s摆脱了柯柯的灵魂的束缚，似乎在对你表示由衷的感谢。"
D.Strings[8464]="你们在干什么？这些标本非常脆弱！"
D.Strings[8465]="你的生命划上了句号。"
D.Strings[8466]="你将成为虫子的食物。"
D.Strings[8467]="自然的力量听我调遣……"
D.Strings[8468]="标本……不能受到破坏。"
D.Strings[8469]="古树们遇到了麻烦。我们必须尽快找出堕落之源，否则就太迟了！"
D.Strings[8470]="你们应该趁早逃走的。"
D.Strings[8471]="我可警告过你……"
D.Strings[8472]="哇，我真厉害！"
D.Strings[8473]="你以为你们能打伤我？你以为我会怕你？"
D.Strings[8474]="来呀，用你最厉害的招数！我照单全收！"
D.Strings[8475]="不要把自己的生命看得太有价值。"
D.Strings[8476]="永远别再回来！"
D.Strings[8477]="你们能受得了这高温吗？"
D.Strings[8478]="我不是孤身一人。"
D.Strings[8479]="终于有个发泄怒气的目标了！"
D.Strings[8480]="你们是来杀达尔莉安的吗？我可以在旁边看吗？"
D.Strings[8481]="啊，真令人满足。"
D.Strings[8482]="看招！"
D.Strings[8483]="尽量保住自己的小命吧……"
D.Strings[8484]="我就知道……这是唯一的结局。"
D.Strings[8485]="遇到麻烦了吗，达尔莉安？啧啧。"
D.Strings[8486]="你八成活不过今天了，达尔莉安。多丢人啊。"
D.Strings[8487]="我想到一个新的战术，你吸引他们的火力，我去找援兵。"
D.Strings[8488]="哈哈！干得好！"
D.Strings[8489]="激怒我可不是个好主意！"
D.Strings[8490]="先不要管我，去杀了那个毫无价值的蠢货！"
D.Strings[8491]="完全不是我的对手，和其他的家伙一样。"
D.Strings[8492]="你选错了对手。"
D.Strings[8493]="旋风斩！"
D.Strings[8494]="我要把你们削成碎片！"
D.Strings[8495]="啊……真是太及时了。"
D.Strings[8496]="我可真的生气了。"
D.Strings[8497]="嘿，你这就顶不住了？"
D.Strings[8498]="看起来我得独自解决他们了。"
D.Strings[8499]="我已经习惯于帮你收拾残局了。"
D.Strings[8500]="恭喜。我想干掉他已经很久了。"
D.Strings[8501]="播下种子之后我就要睡觉了。在休息之前，我必须做好这些应该做的事。"
D.Strings[8502]="你在这么短的时间内就为这片土地带来了绿色，干得很好。我觉得心绪安宁了许多。我要去长眠啦。"
D.Strings[8503]="我无可匹敌！"
D.Strings[8504]="死吧，凡人！"
D.Strings[8505]="对……就是这样！"
D.Strings[8506]="杀！杀啊！"
D.Strings[8507]="就是这样！"
D.Strings[8508]="谁才是真正的主宰？"
D.Strings[8509]="你们杀不死我的，蠢货！我会回来的！我会……"
D.Strings[8510]="卫兵！提高警惕！我们有客人来了……"
D.Strings[8511]="住在地面上的蠢货！"
D.Strings[8512]="我解决你了。"
D.Strings[8513]="女王……陛下……在等待着。"
D.Strings[8514]="成功了！我已经完成了与地狱火堡垒的同调，并与堡垒的魔法能量相互融合。啊，这种力量！$B$B地狱火堡垒中盘踞着不计其数的邪兽人……但是，事情并非如此简单！那些城墙后也涌动着恶魔的力量，我感觉得出……$B$B如果你愿意让我控制你的心灵——别担心，只是暂时的，那么我就能挥笔在羊皮纸上为你记录我发现的一切……"
D.Strings[8515]="当然。你可以控制我。"
D.Strings[8516]="太过分了！你们死定了！"
D.Strings[8517]="你想要奖品，对吗？死亡听起来如何?"
D.Strings[8518]="我不想再说我已经警告过你了……"
D.Strings[8519]="你的生命属于我！"
D.Strings[8520]="你的痛苦就是我的快乐！"
D.Strings[8521]="我要把你烧成灰！"
D.Strings[8522]="在烈焰中哭喊吧！"
D.Strings[8523]="你们……不会得逞的。"
D.Strings[8524]="死吧，入侵者！就凭这件破烂的设备，也想洞悉地狱火堡垒的黑暗魔法？"
D.Strings[8525]="%s深深地吸了一口气。"
D.Strings[8526]="也许这不是……不，我们要战斗！来帮助我！"
D.Strings[8527]="可怜的渣滓。我要腾空而起，让你尝尝毁灭的滋味！"
D.Strings[8528]="谁敢闯入这座圣殿？"
D.Strings[8529]="你去死吧！等等，这不……不，不……你去死吧!"
D.Strings[8530]="我在干什么？我为什么……"
D.Strings[8531]="入侵者！去死吧！"
D.Strings[8532]="非常……困惑。我不属于……这里。"
D.Strings[8533]="没什么技术含量，但是很有效。"
D.Strings[8534]="我的计算居然没有……"
D.Strings[8535]="预料之中的结果。"
D.Strings[8536]="一切都在按计划进行！"
D.Strings[8537]="你们还有大约五秒可活。"
D.Strings[8538]="我断定你们会痛苦地死去。"
D.Strings[8539]="你的战术有漏洞。"
D.Strings[8540]="啊，这是唯一符合逻辑的结果。"
D.Strings[8541]="三思而后行。"
D.Strings[8542]="如果我的切割没有出错……你们应该离死不远了。"
D.Strings[8543]="一个意料之外的……偶然。"
D.Strings[8544]="现在你为我效力！"
D.Strings[8545]="我们的时间非常紧迫。你们休想添乱！"
D.Strings[8546]="一点小麻烦。"
D.Strings[8547]="你好像输了。"
D.Strings[8548]="计划……要继续下去。"
D.Strings[8549]="生命的能量……"
D.Strings[8550]="这具躯体已经空了。"
D.Strings[8551]="没有……生命了。"
D.Strings[8552]="阴影……会笼罩你。"
D.Strings[8553]="黑暗……吞噬一切。"
D.Strings[8554]="虚空……在召唤。"
D.Strings[8555]="你刚才叫我？"
D.Strings[8556]="大概是帮你搬东西之类的。"
D.Strings[8557]="我保证那时候我会对你不理不睬的。"
D.Strings[8558]="你真应该被——等等，我们有伴了……"
D.Strings[8559]="我为什么要叫你？"
D.Strings[8560]="如果我想找人来像个肥胖的孔雀一样走台步，那我会叫你的。"
D.Strings[8561]="你还知道保证这个词啊，sheet-sah？"
D.Strings[8562]="莫克纳萨村周围都是敌人的势力范围。若不是这些敌对势力迫使我们不得不为了生存而战，我相信莫克纳萨氏族会拥有更美好的生活。$B$B想要向莫克纳萨氏族证明自己的价值，就帮助我们消灭这些敌人吧。"
D.Strings[8563]="戈隆才是外域的主宰！"
D.Strings[8564]="休想打败格鲁尔之手！"
D.Strings[8565]="下一个就没这么容易杀掉了。"
D.Strings[8566]="哈！没关系！"
D.Strings[8567]="我不怕你！"
D.Strings[8568]="很好，来跟我打吧！"
D.Strings[8569]="你并没有多强嘛。"
D.Strings[8570]="%s笑了。"
D.Strings[8571]="莫加尔是大王！"
D.Strings[8572]="格鲁尔……会杀了你们的。"
D.Strings[8573]="我仍然清晰地记得第三次大战时败北的耻辱。我等待复仇的机会已经等得太久了。现在，军团的阴影将笼罩这个世界，你们彻底毁灭的日子……已经不远了。"
D.Strings[8574]="军团将会征服一切！"
D.Strings[8575]="所有的凡人都将灭亡!"
D.Strings[8576]="所有的生命都将被根除！"
D.Strings[8577]="我要把你们生吞活剥!"
D.Strings[8578]="可笑的蠢货！"
D.Strings[8579]="宇宙将获得新生。"
D.Strings[8580]="军团……永远不会……失败。"
D.Strings[8581]="水……就是生命。在外域，它已经变成了一种稀有的资源，一种我们要牢牢控制住的资源。我们是上层精灵，现在，夺回我们在这个世界上的地位的时机已经成熟了！"
D.Strings[8582]="直指人心！"
D.Strings[8583]="一击必杀！"
D.Strings[8584]="我要把你们全都杀死！"
D.Strings[8585]="伊利丹大人必胜！"
D.Strings[8586]="入侵者都要受死！"
D.Strings[8587]="我唾弃你们，地表的渣滓！"
D.Strings[8588]="机会来了！一个活口都不要留下！"
D.Strings[8589]="你失败了！"
D.Strings[8590]="伊利丹大人，我……我很抱歉。"
D.Strings[8591]="陌生人，眼前的景象令你困惑吧？$B$B我们供奉着氏族先祖的记忆碎片，以此表达我们对先祖的崇拜之情。"
D.Strings[8592]="%s的引擎出了故障，发出噼里啪啦的响声。"
D.Strings[8593]="耶！我们自由了！"
D.Strings[8594]="真棒！"
D.Strings[8595]="哈哈！我们爱你！你救了我们！"
D.Strings[8596]="我想那些怪异的鸟人是来吃我们的。真恶心！"
D.Strings[8597]="真恶心！"
D.Strings[8598]="来了……就得死。"
D.Strings[8599]="跑啊。"
D.Strings[8600]="休想逃走。"
D.Strings[8601]="站住。"
D.Strings[8602]="求饶吧。"
D.Strings[8603]="你完了。"
D.Strings[8604]="真没用。"
D.Strings[8605]="死吧。"
D.Strings[8606]="伊利丹大人，赐予我飞翔的力量吧！"
D.Strings[8607]="愚蠢的凡人，竟敢冒犯我！别以为我会放过你们！"
D.Strings[8608]="没错，游戏就快要结束了！"
D.Strings[8609]="消灭他们！一个不留！"
D.Strings[8610]="我可以教你炼金术。你感兴趣吗？"
D.Strings[8611]="我可以教你工程学。你感兴趣吗？"
D.Strings[8612]="我可以教你附魔。你感兴趣吗？"
D.Strings[8613]="我可以教你裁缝。你感兴趣吗？"
D.Strings[8614]="我可以教你制皮。你感兴趣吗？"
D.Strings[8615]="我可以教你锻造。你感兴趣吗？"
D.Strings[8616]="你被%s发现了！"
D.Strings[8617]="四处走走，伸展四肢，这种感觉真好。$c，有什么我可以帮忙的吗？"
D.Strings[8618]="我不小心弄坏了魔誓防毒面具，你能再给我一个吗？"
D.Strings[8619]="你好，$C。请原谅我的无理，不过我得提醒你——在我完成与地狱火堡垒同调的过程中，地狱火守卫必定会趁着我最脆弱的时候发动攻击！$B$B那么，拿出部落勇士的样子来，像个英雄那样……保护我！"
D.Strings[8620]="谢谢你肯让我洞察你的内心，$n。你的灵魂很有趣，只是比我想象得要聪明许多……不然我还会多待一会儿的！"
D.Strings[8621]="是哪个胆大妄为的家伙杀死了卡加斯指挥官？我要你用生命偿还这一切！"
D.Strings[8622]="蠢货，哪儿都别想去！"
D.Strings[8623]="别想轻易逃跑！"
D.Strings[8624]="无能的蠢货！奥金顿是我们的……瞧瞧你们那抱头鼠窜的丑样儿！"
D.Strings[8625]="我们苦苦搜寻着失散的族人，随时要提防联盟的袭击，还要与食人魔和他们的戈隆主子抗争。$B$B$c，氏族的重担都落在我的肩上。$B$B因此，有时我不得不向外界寻求帮助。"
D.Strings[8626]="奥金顿是先祖灵魂的家园。或许那里是破碎者的禁地，但是所有的破碎者都曾是德莱尼人……我们的灵魂是一样的。"
D.Strings[8627]="在燃烧军团的监控下，暗影议会负责死亡熔炉的正常运转。"
D.Strings[8628]="下面就是死亡熔炉，死亡……这个名字取得真是恰当。如果任由他们运转死亡熔炉，暗影议会就可以源源不断地为燃烧军团提供地狱火大军。"
D.Strings[8629]="魔法，能量，我的人民陷入其中不能自拔……自从太阳之井被摧毁之后就是如此。欢迎来到未来。真遗憾，你们无法阻止什么。没有人可以阻止我了！Selama ashal’anore！！"
D.Strings[8630]="如果世界变得上下颠倒，你们会怎么办呢？"
D.Strings[8631]="站不住脚了吗？"
D.Strings[8632]="以太阳之名！"
D.Strings[8633]="听我号令！"
D.Strings[8634]="你用生命作赌注，而且你输了。"
D.Strings[8635]="小孩子的把戏。"
D.Strings[8636]="为了……奎尔……萨拉斯！"
D.Strings[8637]="我的心血是不会被你们轻易浪费的！我精心谋划的未来是不会被你们轻易破坏的！感受我真正的力量吧！"
D.Strings[8638]="狂热的黑龙崇拜者现在就聚集在龙颅小径的另一头。我们要与他们抗衡。"
D.Strings[8639]="你们最好找掩护。"
D.Strings[8640]="我能制造出完全相同的魔誓防毒面具来，这真是件好事。"
D.Strings[8641]="欢迎你，$n。我擅长利用原始月布制作精美的衣物。那些想要学习月布专精的裁缝们常常来我这里讨教新知识。"
D.Strings[8642]="我已经没有什么新知识可以教给你了，$c。当然，你可以随意浏览我出售的货物，但是它们对你来说似乎没有什么用处了。"
D.Strings[8643]="很高兴遇见你！我名叫金吉，是常驻沙塔斯城的魔焰裁缝大师。如果你对魔焰裁缝感兴趣，而还没有决定裁缝专精方向的话，我可以帮你。"
D.Strings[8644]="如果你不是裁缝的话，我想你是不会对我出售的图样感兴趣的，不过还是欢迎你来看看！"
D.Strings[8645]="如果你想要购买图样，或是学习暗纹裁缝的话，我很乐意帮忙。"
D.Strings[8646]="对不起，$c。只有懂得针线活儿的裁缝才会对我出售的货物感兴趣。$B$B我敢说，裁缝这门手艺远比做一块手帕要复杂得多。"
D.Strings[8647]="我不能允许你们介入！"
D.Strings[8648]="我要将你彻底净化！"
D.Strings[8649]="你也毫无力量！"
D.Strings[8650]="他们强迫我这么做的。"
D.Strings[8651]="我没有选择。"
D.Strings[8652]="我……自由了。"
D.Strings[8653]="你……是疾病……不是我！"
D.Strings[8654]="这些被艾露恩祝福过的女神之泪蕴藏着强大的力量，可以帮助你对抗阿克蒙德的邪恶魔法。好好利用女神之泪的力量吧。"
D.Strings[8655]="他们害怕我的预言。他们囚禁了我，想要起到罚一儆百的效果，以示对真神耐普图隆的嘲笑。$B$B<斯卡希斯吐了口唾沫。>$B$B凡人，他们会受到惩罚的。总有一天，猎潮者会挥起武器，就像镰刀收割成熟的庄稼那样，将这群丧失信仰的家伙统统歼灭。"
D.Strings[8656]="可怕的魔法滋扰着这片荒野。我们必须竭尽所能，治愈大地的创伤。"
D.Strings[8657]="燃烧军团在另一个位面养殖了大量恶魔猎犬和其他犬类恶魔，并开启了一道被称为死亡之门的传送门，以便将这些生物召唤至这个世界。无论什么时候，只要你看见那些犬类恶魔，它们必定是穿越死亡之门而来的。$B$B最近，我们察觉到燃烧军团加快了召唤恶魔猎犬的速度。$B$B你必须尽快关闭死亡之门，否则事态将一发不可收拾。"
D.Strings[8658]="我来这里是为了净化那些不安分的灵魂，但是在那次袭击后我就担心自己的任务会失败。白骨荒野夺走了太多生命，请你一定要帮助他们。"
D.Strings[8659]="让圣光引导你吧，$n。"
D.Strings[8660]="米莎巨吼一声，同时用它的爪子掠过了戈隆的祭坛。"
D.Strings[8661]="是谁胆敢污染食龙者高格鲁姆的祭坛！"
D.Strings[8662]="能在荣耀堡服役，我非常自豪。"
D.Strings[8663]="等我搞定之后，我要把它碾碎，剥皮，吃肉，然后把它的骨头一块一块敲成渣！"
D.Strings[8664]="更多泰罗克的爪牙过来了！"
D.Strings[8665]="入侵者持续不断地涌了过来！守住！"
D.Strings[8666]="泰罗克的化身！！准备战斗！"
D.Strings[8667]="泰罗克的化身被击败了！去死吧，泰罗克！去死吧，斯克提斯！"
D.Strings[8668]="我的眉毛！你烧焦了我的眉毛！"
D.Strings[8669]="不要担心。这是个进步！"
D.Strings[8670]="当初我在沙塔斯城开设这所盗贼学院的时候，这里的人还没有那么多。不久之后，大量难民就开始涌向这里，纳鲁们几乎把每一座房子都让给了他们。$B$B于是，我现在被迫暂时关闭了这所盗贼学校，当然，这绝对不是永久的。我只是需要重新找一个地方而已。$B$B很快，新一代的盗贼就会先凿击再消失，战斗中趁机搜尸，以及如何将破坏变形的罪责都扣在猎人头上。哦，当然，还得学会盗贼理论的核心教条——真正的盗贼永远不佯攻。"
D.Strings[8671]="我是星界财团的萨雷维。我的转化技术在数个世界中都闻名遐迩。"
D.Strings[8672]="使用闪避技能的诀窍就是认识到你生命中最辉煌的十五秒往往是你最后的十五秒。"
D.Strings[8673]="剑、爪，还有匕首，当然——我所训练的盗贼对这些武器都非常精通。至于锤，我是不会碰锤子的，我也不会让任何我教出来的盗贼去玩锤子，免得他们敲到自己的脑袋。$B$B总之，锤与盗贼必备的隐秘行动完全没有关系。你若是用锤，杀起人来的时候就不会再那么安静，不过威力倒是不错。"
D.Strings[8674]="在最初期的课堂上，教室里总是一群眼神清澈的小伙子。可是，他们当中很少有人能通过第一次考试。$B$B我那时候对此非常愤怒，但现在已经不再那样大吼大叫了，“当我大喊消失的时候你们必须消失！”，我不再这么喊了。现在，考试中无能者直接会去死。"
D.Strings[8675]="千万不要在准备足够的闪光粉之前就离开基地，特别是在与其他人合作的时候。我保证你的同伴永远会给你制造麻烦。$B$B当闷棍失败时，你的选择只剩下扔出闪光粉迅速逃跑，或是硬拼闷棍对象的时候，我……都会选择前者。"
D.Strings[8676]="你休想完成复仇，$n！"
D.Strings[8677]="我听说你的小狗菲菲叼走了克拉图的祈祷念珠……"
D.Strings[8678]="哦，真糟糕！我的菲菲从不会拿其他人的东西！它是条好狗……它只是有时候需要些关心。如果你请它好好吃一顿，一切麻烦就都没有了！"
D.Strings[8679]="<返回>"
D.Strings[8680]="%s用爪子刨着泥土……"
D.Strings[8681]="%s把它的食物埋了起来！"
D.Strings[8682]="好吧，听好了！在我周围排成圆圈，然后出发！"
D.Strings[8683]="%s看了看周围，有些不满意这个隐藏点。"
D.Strings[8684]="%s正寻找着隐藏点……"
D.Strings[8685]="好吧，$r，你只需要在我们工作的时候保护我们不被伤害。等我们回去以后会付给你酬劳的。"
D.Strings[8686]="那个挖掘站就在这里的北面。"
D.Strings[8687]="我们到了！开始挖掘！"
D.Strings[8688]="我觉得这里的沙子底下埋着东西！"
D.Strings[8689]="就快了！"
D.Strings[8690]="以布莱恩喜欢吃的烂香蕉的名义！这是什么？看上去……像只鼓。"
D.Strings[8691]="哇……一只鼓。"
D.Strings[8692]="这个发现肯定会动摇现代考古学的基础理念。"
D.Strings[8693]="是啊，太棒了。我们现在能回去了吗？这片沙漠让我浑身发痒。"
D.Strings[8694]="你疯了吗？你竟然不希望我去敲打这只鼓，不希望看看接下来会发生什么事？那可有违铁炉堡之子的名声！绝不能这样！"
D.Strings[8695]="这让我想起了过去，那时候，你为了寻找所谓沙漠侏儒的证据，让我们搜遍了整个希利苏斯。"
D.Strings[8696]="还有那一次，你告诉我们说，你发现了治愈20世纪疾病的办法。这所谓的20世纪又到底是什么东西？"
D.Strings[8697]="我曾以接受别人的挑战为乐，但是他们无一例外地都败了，我早已厌倦了这种廉价的胜利。$B$B现在，我将精力放在经营材料生意上，还打算写一本回忆录，记录我在暮光之锤度过的岁月。"
D.Strings[8698]="我觉得还是那一次最劲。那次他说他认为阿尔萨斯表弟的骨骼被冻在冬泉谷的冰河之下。我永远都不会原谅你，雷托尔。说真的……阿尔萨斯的表弟又是乜了？"
D.Strings[8699]="我真不知道雷托尔脑子里装的是什么。有一次他居然试图说服我们，说我们不过是某种生物臆想出来的意识体，是他们用来取乐的调剂品。那段时间，每次晚餐的时候他都会喋喋不休地说个不停。"
D.Strings[8700]="闭嘴！反正我现在就要狠敲这只鼓！"
D.Strings[8701]="我无意与你为敌，不过我想看看你的货物。"
D.Strings[8702]="那么，你们都听到了吗？"
D.Strings[8703]="哈哈！我告诉过你这里有东西的！"
D.Strings[8704]="不要就这么站在那里！帮帮$g他:她;！"
D.Strings[8705]="你给予了我们相当大的帮助，$R！我们赶紧离开这儿吧，免得再惹麻烦上身！我会转告杜瓦弗维兹，说你出色地完成了自己的任务。"
D.Strings[8706]="什么？！是谁胆敢给燃烧军团惹麻烦？"
D.Strings[8707]="准备接受无尽的折磨吧，凡人！"
D.Strings[8708]="什么都无法阻止你的末日！"
D.Strings[8709]="我要把你从表皮到骨髓都完全烤熟，我一定会很喜欢那滋味！"
D.Strings[8710]="你胆敢袭击我？！"
D.Strings[8711]="你胆敢冒犯我！我要慢慢地将你折磨至死！"
D.Strings[8712]="我受够了！现在我要让你们看看宇宙的愤怒！"
D.Strings[8713]="我和虚空……融为了一体！"
D.Strings[8714]="炼金实验室"
D.Strings[8715]="我们的常驻炼金师罗罗基姆把他的设备都一起带了过来。不过，这些设备和你以前习惯使用的略微有些不同——毕竟他是个鸦人——但这些设备应该足以满足你要求。他就在贫民窟的西北部分。"
D.Strings[8716]="宝石商人"
D.Strings[8717]="这里居住着两位宝石商人：一位与占星者走得很近，而另一个忠诚于奥尔多。你在找哪个？"
D.Strings[8718]="奥尔多宝石商人"
D.Strings[8719]="英妮瑟拉是个贩卖各种宝石以及珠宝加工用品的精明女人。你可以在奥尔多高地的北部找到她的商店。"
D.Strings[8720]="占星者宝石商人"
D.Strings[8721]="利萨尔丝可能……看上去有点凶，但是她出售你想要的东西。她在占星者平台的东部。"
D.Strings[8722]="<这台构造体生物对着平台的东部做了个手势。>"
D.Strings[8723]="如果你还没有在德莱尼人阵营中达到崇拜声望，我是不会训练你的。"
D.Strings[8724]="放狗！"
D.Strings[8725]="我准备好了，学者。开始驱魔仪式吧。"
D.Strings[8726]="喔，谢谢你！我体内的黑暗物质已经被驱除了！我的眼睛又能看见东西了……啊，我看到了救世主的脸庞！"
D.Strings[8727]="滚开，$c！离我们远点，否则我们会让你知道什么是真正的绝望！"
D.Strings[8728]="是时候了。驱魔仪式马上开始……"
D.Strings[8729]="做好准备。不要让这仪式被打断，否则我们会失去他……"
D.Strings[8730]="小心。这个蠢货交给我来对付。"
D.Strings[8731]="让圣光净化你吧，人类！让恶魔的腐蚀不再吞噬你的灵魂！"
D.Strings[8732]="退却吧，肮脏的黑暗！你在这里没有力量！"
D.Strings[8733]="让圣光的力量来驱散你！回到你的深渊去吧！"
D.Strings[8734]="我……不能……失败！"
D.Strings[8735]="圣光指引着我……它一直支持着我！"
D.Strings[8736]="啊！停止你的咒语，学者！停下，否则我会让你体会到你们这些可悲的凡人从未想象过的痛苦！"
D.Strings[8737]="我看到了你的祖先，学者！他们在黑暗中翻滚着，尖叫着……他们和我们在一起！"
D.Strings[8738]="这是徒劳的，德莱尼人！你和你弱小的助手们夺不回这个悲惨人类的控制权。他是我的！"
D.Strings[8739]="我会把你的灵魂撕成碎片，把它们放在恶魔之火上慢慢灸烤！"
D.Strings[8740]="退散！我命令你退散……信念的腐蚀者！痛苦的创造者！不要再回来，否则你会遭受到和今天同样的失败命运。"
D.Strings[8741]="不要担心，破碎岗哨固若金汤！不过为了以防万一，如果基地开始碎裂的话，你要马上跳上狮鹫……"
D.Strings[8742]="现在你遇到了我，让我们看看谁的棋艺更加优秀吧！控制国王便可开始棋局。"
D.Strings[8743]="<阿达尔和谐而婉转的音响再次传入了你的心灵。>$B$B不要担心，孩子。看看你的背包，你会再次找到它的。"
D.Strings[8744]="$R，你想跟我谈谈？"
D.Strings[8745]="我在这片荒野上看到了许多危险的存在。谁会注意到那些生物竟然潜伏在灰烬中，准备伏击那些粗心大意的旅者呢？"
D.Strings[8746]="你们所有的努力全都是白费力气，我已经开始吸取世界之树的力量了！很快，这个世界的心脏将停止跳动。"
D.Strings[8747]="你没有足够的声望，或尚未宣誓效忠奥尔多。"
D.Strings[8748]="你没有足够的声望，或尚未宣誓效忠占星者。"
D.Strings[8749]="外域的战争比我之前所经历过的任何战争都要惨烈。大部分受害者都是那些留在后方的孩子。$B$B现在，斯克提斯的鸦人对沙塔斯城的威胁进一步加剧，那里会有更多的孤儿需要照顾。这些孩子几乎已经看不到光明的未来。$B$B但是，你却有能力为他们做些什么。儿童周来了，$c，我恳求你给这些孩子的生活带来些乐趣和奇迹吧。"
D.Strings[8750]="儿童周还没有结束……我能得到另一个血精灵孤儿哨吗？"
D.Strings[8751]="儿童周还没有结束……我能得到另一个德莱尼孤儿哨吗？"
D.Strings[8752]="我很寂寞。我希望在这里有更多的和我同龄的孩子。有时候，我真的很怀念在沙塔斯城孤儿院的日子。"
D.Strings[8753]="我自由了！但是秘密……有泄露的危险。必须警告阿卡玛！"
D.Strings[8754]="为什么外域不再叫作德拉诺了？"
D.Strings[8755]="如果恶魔是掉下来的，他们是从哪里掉下来的呢？"
D.Strings[8756]="是不是扭曲虚空的形成就像椒盐卷饼那样？还有，“虚空”是什么意思？孤儿院长说我不应该问别人“虚空”是什么感觉。"
D.Strings[8757]="<莫希斯注视着天空。>$B$B从某种程度上说，我很羡慕鲁克和考瓦克斯所享受的自由。摆脱大地的束缚事实上是一种伟大的祝福。$B$B将来我会再次进入天空飞翔的，不过我必须先完成一项使命。"
D.Strings[8758]="纳杉从天空中缓缓落下。"
D.Strings[8759]="杰赫真是个好人，他让我来这里当学徒。于是我也学到了许多有趣的东西。$B$B<希尔低下了头。>$B$B不过，我讨厌远离妹妹的生活。"
D.Strings[8760]="奥鲁姆，我的老朋友。看到你一切安好，真是令人欣慰。"
D.Strings[8761]="伊利丹会起疑心，这是毫无疑问的。不过我们会挺过去的，一直以来不都是这样吗？"
D.Strings[8762]="你……不要开玩笑，奥鲁姆。你已经做出了太多的牺牲。"
D.Strings[8763]="看来你已经做出了决定，那么好吧。我们会尽可能让你进入灵魂世界的过程没有痛苦。"
D.Strings[8764]="再会，我的朋友。当我们在这个世界的使命完结之后，就可以在另一个世界中再次相聚了。"
D.Strings[8765]="主人！我们抓住了从瓦丝琪那里逃跑的叛徒！他的尸体就躺在我的面前！"
D.Strings[8766]="但是，大人！您误解了我的行动……我确实知道有个您非常信任的人想要背叛您，他就是凯尔萨斯那条狗！他现在投靠了基尔加丹，想要取代您，统治外域！"
D.Strings[8767]="遵命，大人！"
D.Strings[8768]="阿卡玛！你听到消息了吗？我被瓦丝琪的人跟踪了。我们的秘密就要暴露了！"
D.Strings[8769]="伊利丹必定会抓住我，那时候，他肯定会得知灰舌部队的秘密。这对他来说根本没有什么难度！不，我们只有一个办法。是我的愚蠢和疏忽导致了今天的局面，那么就让我进入灵魂的世界，结束这次危机。"
D.Strings[8770]="我已经下定了决心，不要再劝说我了。我把自己的生命都献给了我们的计划，如果现在前功尽弃，我们怎么能对得起那些为此牺牲的伙伴？"
D.Strings[8771]="谢谢你，阿卡玛。你让我感到了无上的荣耀，我感到自己的兄弟们就在身边。再会，朋友。好好指引我们的同胞。"
D.Strings[8772]="伊利丹正在搜捕我。我在这里非常危险，我们大家都非常危险。"
D.Strings[8773]="埃兰被打败了？啊……我能感觉到他的控制已经被解开了——虽然感觉很微弱。但是这足够让我继续履行看门人的工作了！你愿意被传送到守护者的图书馆吗，$n？"
D.Strings[8774]="请把我传送到守护者的图书馆去吧。"
D.Strings[8775]="%s突然跪下，但他的心思似乎游离在别处。"
D.Strings[8776]="你在伊瑟拉的领域里干什么，入侵者？走开！你们在这里不受欢迎！"
D.Strings[8777]="%s站稳了脚跟，开始辨识周围的环境。"
D.Strings[8778]="很高兴再次见到你，$c$n。多尔南一直在问起你。"
D.Strings[8779]="很高兴再次见到你，$c$n。萨兰蒂亚一直在问起你。"
D.Strings[8780]="外域的战争比起我所经历过的任何战争都惨烈。大部分悲惨的受害人都是那些留在后方的孩子。$B$B现在，斯克提斯的鸦人对沙塔斯城的威胁进一步加剧，那里也会有更多的孤儿需要照顾。这些孩子看不到光明的未来。$B$B但是你却有能力为他们做些什么。儿童周来了，$c，我恳求你给这些孩子的生活带来些乐趣和奇迹吧。"
D.Strings[8781]="他们还在追我，$r！快点，在我们被发现前告诉我，你来这里干什么！要是被他们抓住了，我们两个人都得死！"
D.Strings[8782]="<这位德鲁伊似乎陷入了沉睡，全然忘却了他周围的环境。>"
D.Strings[8783]="我求你了，$r，快一点。他们是不会放弃追踪的！就算是在这里，我也无法从他们手中逃脱！"
D.Strings[8784]="你……你不是他们的同党！快，在他们找到我们之前，得躲进某个隐密的地方！快点！"
D.Strings[8785]="你可以从暴风城维勒武器店的人类武器大师吴平、埃索达贸易阶梯的德莱尼武器大师韩迪尔或是铁炉堡密林武器店内的侏儒武器大师比克斯那里学会使用弩。"
D.Strings[8786]="居住在达纳苏斯战士区的暗夜精灵武器大师伊琳尼雅·月火可以教你使用弓。"
D.Strings[8787]="这家店里的比克斯可以教你使用匕首。如果你还想认识其他人的话，暴风城的吴平、埃索达的韩迪尔和达纳苏斯的伊琳尼雅·月火也都能教你。至于我，我一直不喜欢用匕首战斗。"
D.Strings[8788]="达纳苏斯战士区的武器大师伊琳尼雅·月火，或是铁炉堡密林武器店的矮人武器大师布里维夫，都能教你如何使用拳套。"
D.Strings[8789]="能教你使用枪的是布里维夫，去铁炉堡的密林武器店找他吧。"
D.Strings[8790]="布里维夫会很高兴把他所知道的一切关于枪的知识都教给你的！"
D.Strings[8791]="我是按照节点亲王哈拉迈德的吩咐来这里的。奇怪的事情似乎正在风暴尖塔中酝酿着。"
D.Strings[8792]="一个%s从翡翠梦境中侵入了现实世界！"
D.Strings[8793]="矮人武器大师布里维夫能教你怎么使用单手斧和双手斧。你可以在铁炉堡的密林武器店找到他。"
D.Strings[8794]="据我所知没有比这里的布里维夫更出色的斧子专家了！单手斧，双手斧……他都是大师。"
D.Strings[8795]="我的朋友布里维夫能指示你怎么使用拳套……或者，如果你喜欢女性教师的话，达纳苏斯战士区的暗夜精灵武器大师伊琳尼雅·月火同样能教会你！"
D.Strings[8796]="那个勇敢的比克斯就能教你怎么使用弩。不过如果你在找其他训练师的话，可以去找达纳苏斯战士区的伊琳尼雅·月火，或者是埃索达内贸易阶梯的德莱尼人武器大韩迪尔。"
D.Strings[8797]="居住在达纳苏斯战士区的暗夜精灵武器大师伊琳尼雅·月火能指导你怎么使用弓。"
D.Strings[8798]="韩迪尔和布里维夫都能指导你怎么挥舞锤子，无论大小。你可以在铁炉堡的密林武器店内找到布里维夫，而韩迪尔则整天待在埃索达的贸易阶梯训练着德莱尼人。"
D.Strings[8799]="锤子是布里维夫的最拿手的武器！他就在这家店附近。如果你不喜欢他的训练方法，我听说埃索达的德莱尼的武器大师韩迪尔同样也知道怎么摆弄锤子！他就在贸易阶梯那里。"
D.Strings[8800]="吴平是长柄武器的大师。他一般在暴风城的维勒武器店训练学生。"
D.Strings[8801]="暴风城维勒武器店的武器大师吴平和达纳苏斯战士区的伊琳尼雅·月火都能教会你怎么使用法杖。"
D.Strings[8802]="联盟有两名使剑的大师：韩迪尔和吴平。你可以在埃索达的贸易阶梯找到前者，而后者可以在暴风城的维勒武器店找到。"
D.Strings[8803]="达纳苏斯战士区的伊琳尼雅·月火和铁炉堡密林武器店的比克斯都能指导你怎么适当地使用投掷武器。"
D.Strings[8804]="斧"
D.Strings[8805]="弓"
D.Strings[8806]="弩"
D.Strings[8807]="匕首"
D.Strings[8808]="拳套"
D.Strings[8809]="枪"
D.Strings[8810]="锤"
D.Strings[8811]="长柄武器"
D.Strings[8812]="法杖"
D.Strings[8813]="剑"
D.Strings[8814]="投掷武器"
D.Strings[8815]="这里的比克斯能教你怎么使用投掷武器。要是你去达纳苏斯更方便的话，也可以去找那里战士区的伊琳尼雅·月火学习。"
D.Strings[8816]="如果你需要武器训练，我可以向你提供。"
D.Strings[8817]="啊，你希望去其他地方训练？我会指引你的。告诉我你对什么武器有兴趣。"
D.Strings[8818]="鲁罗萨，我把艾维娜圣物委托给$n转交莫希斯·轻翼了。现在我必须彻底地回到翡翠梦境去了。不要让$n失败！"
D.Strings[8819]="哈纳什和塞尤克可以教会你如何使用单手斧和双手斧。你可以在奥格瑞玛的荣誉谷找到他们。"
D.Strings[8820]="奥格瑞玛荣誉谷内的武器大师塞尤克和哈纳什可以教你如何射箭，银月城远行者广场的武器大师伊蕾达同样也是这方面的专家。"
D.Strings[8821]="阿基巴德是用弩的大师。他是幽暗城的武器大师，就居住在军事区。"
D.Strings[8822]="你可以从三个武器大师那里寻求匕首的使用指导：幽暗城军事区的阿基巴德，奥格瑞玛荣誉谷内的塞尤克，和银月城远行者广场的伊蕾达。"
D.Strings[8823]="那个丑陋的兽人塞尤克可以教你如何使用匕首。要是你想在其他地方学的话，也可以去银月城远行者广场找伊蕾达或是去幽暗城军事区找阿基巴德，如何？"
D.Strings[8824]="你可以在奥格瑞玛的兽人武器大师塞尤克那里学会使用拳套。他每天都在荣誉谷。"
D.Strings[8825]="你想学习拳套的使用方法吗？和这里的塞尤克谈谈，他会教你的。"
D.Strings[8826]="我们的射击教师是安塞瓦，居住在雷霆崖中部高地底层的牛头人武器大师。"
D.Strings[8827]="安塞瓦会教你怎么使用锤子，你可以在雷霆崖的中部高地底层找到他。"
D.Strings[8828]="遗忘者的武器大师阿基巴德知道如何使用长柄武器，他就在幽暗城的军事区训练其他人。银月城远行者广场的血精灵武器大师伊蕾达也能教你相同的技能。"
D.Strings[8829]="奥格瑞玛荣誉谷的巨魔武器大师哈纳什和雷霆崖中部高地底层的牛头人武器大师安塞瓦可以教你如何使用法杖。"
D.Strings[8830]="这里的哈纳什知道怎么使用法杖。如果你想找一个更强健的教师，就去雷霆崖，安塞瓦会在中部高地底层教你。"
D.Strings[8831]="银月城远行者广场的血精灵伊蕾达会教你学习使用单手剑和双手剑。幽暗城的武器大师阿基巴德同样也能教你，他就在军事区。"
D.Strings[8832]="奥格瑞玛的武器大师塞尤克和哈纳什是真正的投掷武器专家。他们在荣誉谷训练所有对此有兴趣的学生；如果想看更加优雅的投掷姿势，那么没人比得上银月城远行者广场的伊蕾达。"
D.Strings[8833]="阿基巴德是弩类武器的教师。他是幽暗城的武器大师，就在军事区。"
D.Strings[8834]="我们的射击老师是雷霆崖中部高地底层的牛头人武器大师安塞瓦。"
D.Strings[8835]="他们都是从在雷霆崖中部高地底层的安塞瓦那里学会使用锤子的。"
D.Strings[8836]="遗忘者的武器大师阿基巴德知道如何耍长柄武器，他就在幽暗城的军事区训练着其他人。银月城远行者广场的血精灵武器大师伊蕾达也能教你相同的技能，朋友。"
D.Strings[8837]="我不知道为什么你想学些其他技能……但我想我能为你找到合适的训练师。你具体想要什么训练？"
D.Strings[8838]="既然你不是过来接受训练的，就站后面点，不要妨碍我工作。"
D.Strings[8839]="你让我失望了，阿卡玛。我本想要亲自审讯这条狡猾的虫子！现在我有些怀疑你们这些破碎者的忠诚了。"
D.Strings[8840]="看来你没有撒谎，阿卡玛。凯尔萨斯的背叛并没有让我感到多么吃惊，我并没有某些家伙所想的那样健忘。你的同族与他有重大的牵连，这让我不得不质疑你的忠诚。"
D.Strings[8841]="将你的灰舌部队派进风暴要塞，去杀掉他最得意的部下，那只名叫奥的凤凰。以此来向我证明你不是他的同党。不要妄图背叛我，破碎者。我们都知道你的灵魂在谁的掌握中！"
D.Strings[8842]="提防那些包围我们的复仇军。"
D.Strings[8843]="过来，我会教如何骑乘这些坐骑。不过，你……带了足够的钱来付这笔费用吧？"
D.Strings[8844]="欢迎来到常青林，$c。坦莫和我一直在研究刀锋山一带的鸦人，最近，我们发现他们和那些泰罗卡森林的鸦人之间有着一些令人担忧的差别。"
D.Strings[8845]="<鸦人的幽灵逐渐接近你，仿佛是在辨认你。但你觉得它似乎总是看不清楚。>$B$B罗卡拉姆，是你吗？"
D.Strings[8846]="是的……是的，是我……"
D.Strings[8847]="请原谅我质问你，孩子。我的视力已经不如从前了，但是乌鸦之神赐我长生。$B$B不久之后，你就会接替我的位置。我将我所知道的知识都传授给了你。唯一的遗憾就是我没能夺回氏族神圣的乌鸦之书。"
D.Strings[8848]="是的，长者。告诉我关于乌鸦之书的故事吧。"
D.Strings[8849]="自从斯克提斯的鸦人同胞背信弃义，从我们手中偷走乌鸦之书，打破石板并将碎裂的石板碎片掩埋在他们那肮脏的城市中之后，鸦神真正的信徒便永远地生活在耻辱之中。$B$B祈祷乌鸦之神能挑中你，让你成为夺回神圣书典的英雄吧。孩子，要时刻保持信仰，并永远铭记这条预言：“与乌鸦之神为敌的人们，鸦神会从你们的睡梦中进入这个世界。”"
D.Strings[8850]="葛罗克需要帮助。小$r，快去刀锋山帮助血槌氏族吧！"
D.Strings[8851]="你去找莫戈多格吗？"
D.Strings[8852]="我正在寻找一名技艺超群的英雄。$G他:她;将召集其他人拯救血槌氏族，并从戈隆的残暴统治下解放生活在刀锋山的所有食人魔氏族。$B$B当你了解到更多的知识之后再来找我吧。但是，$c，在此之前请你保持低调，以免被戈隆察觉到我们的动机。"
D.Strings[8853]="如果我们想摆脱身上的枷锁，再次享受自由的滋味，就必须杀死所有的格鲁尔之子！$B$B但是，我们必须隐秘行动，只有通过秘密的抵抗行动，我们才有机会获得成功。"
D.Strings[8854]="要想拯救尤勒斯上校，恐怕只能利用那种危险性很高的仪式——是的，驱魔仪式。"
D.Strings[8855]="葛罗克需要帮助！为什么没人帮忙啊？"
D.Strings[8856]="要是你们这些小家伙不去刀锋山和莫戈多格谈话，葛罗克会生气的！"
D.Strings[8857]="为了克希利！为了沙塔尔！"
D.Strings[8858]="你们的末日到来了，伊利达雷！"
D.Strings[8859]="把伊利丹的走狗们全部消灭！"
D.Strings[8860]="来吧，恶魔！死亡正等待着你！"
D.Strings[8861]="可怜虫……你主人的计划破产了！"
D.Strings[8862]="我有个消息要带给你们的主人，渣滓！"
D.Strings[8863]="我眼花了吗？我们很久没有见过面了，罗卡拉姆兄弟，真的是你吗？$B$B你在找塞克卡尔？他就在漩涡峰西部的水晶田中。他说自己可以在那里感受到某种原始的、未开化的超自然力量，并为此神魂颠倒；但是在旁人看来，那片水晶田并没有什么异常现象。"
D.Strings[8864]="我觉得我需要洗个澡。*嗅* 我想你也要洗个澡！"
D.Strings[8865]="一个牛头人圣骑士会是一头圣牛吗？"
D.Strings[8866]="我穿这条裙子是不是看起来比较胖？"
D.Strings[8867]="我敢打赌伊利丹其实是个好人，他只是需要母爱。"
D.Strings[8868]="我敢打赌要是冰淇淋打过孔的话味道肯定会更好！"
D.Strings[8869]="男孩有虱子女孩有美貌！"
D.Strings[8870]="如果我摒住呼吸，我会变成什么颜色？"
D.Strings[8871]="如果连马都能得到马蹄铁，我能得到德莱尼靴子吗？"
D.Strings[8872]="如果燃烧军团是这么大的麻烦，为什么就不能给他们浇些水呢？那么他们就只好停止燃烧了。"
D.Strings[8873]="你为什么吃这么多也不会胖？"
D.Strings[8874]="纳鲁睡觉的时候是不是要把圣光关掉的？"
D.Strings[8875]="%s开始引导圣光的力量。"
D.Strings[8876]="前进，占星者！让伊利丹的侍从们见识一下我们的厉害！"
D.Strings[8877]="你也许了解一点点驾驭走兽的技巧，但是你有乘坐飞禽自由飞翔的经历吗？蛮锤矮人懂得如何驯养最好的飞行坐骑。如果你有胆的话，只需付一笔小钱，我就教给你这项技能。"
D.Strings[8878]="提到蛮锤部族时你会想到什么呢？当然是狮鹫骑士啦！影月谷虽说不是鹰巢山，但我们的狮鹫数量依然很充足，嗯，非常充足。瞧瞧那些美丽的小宝贝儿，你看上哪一只了呀？"
D.Strings[8879]="让我看看你的狮鹫，拉瑟尔。"
D.Strings[8880]="猛烈的地震警告了附近的鱼人们！"
D.Strings[8881]="%s把他的敌人送入了水下的坟墓！"
D.Strings[8882]="%s召唤了水泡！"
D.Strings[8883]="%s拿走了南国之怒月亮石，并逃进了河里。跟着她！"
D.Strings[8884]="%s阴险地举起战锤……"
D.Strings[8885]="你！快交出月亮石，我保证任何人都不会受到伤害！"
D.Strings[8886]="可怜的家伙，你们胆敢进攻伊利丹大人的神殿？好吧，我会让这里变成你们的墓地！"
D.Strings[8887]="好吧，你赢了！我投降！不要伤害我！"
D.Strings[8888]="啊！我要撕碎你的灵魂！"
D.Strings[8889]="%s一言不发，心中权衡着要做出怎样的抉择。站在他旁边的沙塔尔军队鸦雀无声，空气中弥漫着紧张的气氛……"
D.Strings[8890]="时机到了，玛维！释放你的怒火吧！"
D.Strings[8891]="这一天我已经等待许多年了！伊利丹和他的走狗都将彻底被毁灭！"
D.Strings[8892]="把所有看到我们的人都杀掉……一定不能让伊利丹得知我们的到来！"
D.Strings[8893]="你的死期就要到了，阿卡玛。主人马上就会得知你的背叛！"
D.Strings[8894]="阿卡玛没有主人了。再也没有了。"
D.Strings[8895]="我们的计划早已危在旦夕。好像玛维决定以她自己的方式来做事。"
D.Strings[8896]="%s的注意力转移到了神殿南墙的一道裂缝上。"
D.Strings[8897]="无论玛维是不是和我们在一起，我们都必须继续。进去！快点！"
D.Strings[8898]="年轻的麻鹰，如果没有你，我们恐怕要花上几年的时间才能找到乌鸦之书。带着我们的感激返回纳格兰吧。"
D.Strings[8899]="这就是了！这就是真正的……乌鸦之书！"
D.Strings[8900]="堕落与腐化的盛宴已经不复存在了！玛瑟里顿在$n和$g他:她;的伙伴们面前倒下了！它的灭亡见证了联盟力量的伟大！一个深渊领主被消灭了！"
D.Strings[8901]="兄弟们，姐妹们！敌人的末日降临了！我们必须打击剩余的邪兽人！把他们像虫子那样消灭掉！在洛萨之子的庇护下继续战斗吧！"
D.Strings[8902]="一切都真相大白了……乌鸦之神的追随者将敌人的灵魂永久地禁锢在石像中，以此俘获和制服他们。石板甚至提到了乌鸦之神的名字——安苏。我一直以为他的名字早已湮没在历史的长河中！"
D.Strings[8903]="石板上还记载着别的信息。在一段血腥战斗和乌鸦之神落败的描述之后，有一个预言：安苏将在敌人的梦境中出现，扭曲他们的意志，以重返这个世界……"
D.Strings[8904]="石板应证了我先前的猜想。我们必须利用这条信息，在安苏对翡翠梦境造成更大的破坏之前，将他召唤到这个世界中，然后击败他！"
D.Strings[8905]="你似乎懂得如何驾驭野兽在地面行走，但是如果你想要在天空翱翔的话，就需要经过刻苦的训练，当然还需要金币。你身上有金币的，对吧？"
D.Strings[8906]="瞧这些漂亮的野兽。我们在这里饲养双足飞龙，并训练这些既可靠又勇敢的野兽适应德拉诺世界严酷的天气环境。"
D.Strings[8907]="地狱火堡垒是我们的了！伊利丹的邪兽人军团已经不复存在了！玛瑟里顿在$n和$g他:她;的朋友们面前倒下了！"
D.Strings[8908]="决战的时刻到了！让我们拿起武器，消灭残余的邪兽人势力吧！为了你们的酋长而战！为了部落而战！"
D.Strings[8909]="蠢货！山鹰精华永远不会落入你的手中！"
D.Strings[8910]="乌鸦之神的时代即将来临，而你的末日就在眼前！"
D.Strings[8911]="你胆敢打扰乌鸦之神的忠实追随者？"
D.Strings[8912]="你会为你的傲慢而付出代价，$c！"
D.Strings[8913]="猎鹰被击败了，它注定再也不会出现了！你的任务失败了！"
D.Strings[8914]="乌鸦之神会像预言所说的那样重返这个世界，而你根本没有能力阻止他！"
D.Strings[8915]="你胆敢召唤我？"
D.Strings[8916]="%s深深吸了一口气！"
D.Strings[8917]="%s开始施放炎爆术！"
D.Strings[8918]="沉默突然笼罩着整个沙塔斯城。"
D.Strings[8919]="%s的思想似乎侵入了你的心灵。"
D.Strings[8920]="凯尔萨斯·逐日者被$n和$g他:她;的伙伴们打败了。"
D.Strings[8921]="现在，攻击风暴要塞内的残余血精灵的时刻已经来临了。拿起武器！让阿达尔的战歌激励你们吧！"
D.Strings[8922]="我不关心你是谁，或是你在天空卫队以外做些什么。不过只要你在这里，你就要听从我的命令。"
D.Strings[8923]="我饿了。水果应该很好吃。"
D.Strings[8924]="枯瘦的莫戈多格告诉葛罗克，要去城市里为血槌氏族寻求帮助。葛罗克就来了。"
D.Strings[8925]="要是没人帮忙，葛罗克就打人！"
D.Strings[8926]="刀塔氏族没有公平地战斗。他们有戈隆帮忙。你去刀锋山，和枯瘦的莫戈多格谈谈。去消灭戈隆吧。"
D.Strings[8927]="等我长大以后，我要成为一个制革工人！"
D.Strings[8928]="大家为$n，食人魔新的$G国王:女王;欢呼吧！"
D.Strings[8929]="你手下那群猴子可耻地失败了，纳鲁。虽然我已经落败，但是我还活着……当我们控制纳鲁飞船的时候，绝对没有犯下这样的错误。"
D.Strings[8930]="这一切都是为了什么？几样无关紧要的小玩意？太迟了。迎接主人归来的准备工作早就开始了。很快，他就会重返这个世界。"
D.Strings[8931]="你，或是伊利丹那个蠢货，都根本不能阻止我！你们一直扮演着我的仆从的角色，只是你们对此一无所知罢了。"
D.Strings[8932]="放下武器，向基尔加丹的力量屈服吧！"
D.Strings[8933]="在烟火表演以后，他们还会拿出美酒，那样我们就能好好干一杯了！"
D.Strings[8934]="辛多雷是不可战胜的！"
D.Strings[8935]="还没完！"
D.Strings[8936]="太阳的光芒……在等待着我。"
D.Strings[8937]="你的灵魂将归于深渊！"
D.Strings[8938]="以上层精灵之血的名义！"
D.Strings[8939]="为了太阳之井！"
D.Strings[8940]="你们势单力薄！"
D.Strings[8941]="我要让你们自以为是的错觉荡然无存！"
D.Strings[8942]="不！我……不会……"
D.Strings[8943]="血债血还！"
D.Strings[8944]="更大的危机……在等着你们。"
D.Strings[8945]="到处都是对这个……这个家伙的抱怨声。据说他是个可疑的人物。我是来调查他的生意是否合法的……如果他胆敢做违法的勾当，我就会立即采取行动。"
D.Strings[8946]="如果你集齐一套报复卡片的话，你将获得一张暗月卡片：复仇。当你拿着这张卡片时，任何攻击你的人都有一定几率遭到神圣的复仇。"
D.Strings[8947]="如果你集齐一套风暴卡片的话，你将获得暗月卡片：怒火。当你拿着这张卡片时，你的法术或物理攻击的爆击几率会不断提高，直到你打出一次爆击。"
D.Strings[8948]="如果你集齐一套祝福卡片的话，你将获得暗月卡片：远征。当你拿着这张卡片时，你只需持续战斗，你的法术和物理攻击的伤害就会不断提高。"
D.Strings[8949]="如果你集齐一套愚人卡片的话，你将获得暗月卡片：疯狂。当你拿着这张卡片时，每当你杀死一个敌人，你就会充满疯狂的力量。"
D.Strings[8950]="告诉我更多关于报复套牌的信息。"
D.Strings[8951]="告诉我更多关于愚人套牌的信息。"
D.Strings[8952]="告诉我更多关于祝福套牌的信息。"
D.Strings[8953]="告诉我更多关于风暴套牌的信息。"
D.Strings[8954]="当心点，朋友们。背叛者就在那边的大厅中冥想。"
D.Strings[8955]="原谅我，王子殿下！我……失败了。"
D.Strings[8956]="警报！消灭入侵者。"
D.Strings[8957]="系统……关闭……"
D.Strings[8958]="目标已终结。"
D.Strings[8959]="入侵生命体已经停止运转。"
D.Strings[8960]="威胁已排除。"
D.Strings[8961]="备用方案启动……"
D.Strings[8962]="计算力量参数……"
D.Strings[8963]="嘘！小声点。孩子们正在睡觉。"
D.Strings[8964]="深渊中的洪水会淹没你们！"
D.Strings[8965]="以潮汐的名义！"
D.Strings[8966]="我的仆从，干掉他们！"
D.Strings[8967]="你们无处可逃！"
D.Strings[8968]="很快就都结束了。"
D.Strings[8969]="挣扎只会让你更痛苦。"
D.Strings[8970]="只有强者才能生存。"
D.Strings[8971]="埃格恩的……巨浪……"
D.Strings[8972]="停止前进。否则你们将被消灭。"
D.Strings[8973]="地面破坏程序启动。"
D.Strings[8974]="范围确认。释放。"
D.Strings[8975]="轨道锁定。"
D.Strings[8976]="提升至最高速度。"
D.Strings[8977]="威胁等级归零。"
D.Strings[8978]="指令完成。"
D.Strings[8979]="目标已歼灭。"
D.Strings[8980]="系统崩溃倒计时，五，四……"
D.Strings[8981]="嗯，$g国王:女王;陛下？"
D.Strings[8982]="你杀死了戈隆！现在你又得和那些天上来的家伙作战吗？"
D.Strings[8983]="为$n而战！"
D.Strings[8984]="这酒真好喝！"
D.Strings[8985]="要是$G国王:女王;陛下跳舞的话，我也跟着跳！"
D.Strings[8986]="$G国王:女王;陛下不生我的气吗？"
D.Strings[8987]="你为什么这么看着我？你不会是想吻我吧，是不是！？"
D.Strings[8988]="现在所有的格鲁尔之子都死了！现在新的$G国王:女王;陛下将领导所有的食人魔去奥格瑞拉！"
D.Strings[8989]="你最好快点醒来，新人。这里不是斯克提斯外的某个舒适的后院，这里是刀锋山！一不小心就会导致灾难性的后果！"
D.Strings[8990]="我遗失了灌注精华的月亮石。你能再给我一个吗？"
D.Strings[8991]="好吧，现在，你立刻前往大锻炉那里找先知亚瓦德，就在东边略微往北一点。"
D.Strings[8992]="身为萨尔酋长大人的顾问，派雷亚诺一直待在智慧谷的格罗玛什要塞里。"
D.Strings[8993]="我可以教你珠宝加工。有兴趣吗？"
D.Strings[8994]="醒来吧，我的孩子，来帮助你们的主人！"
D.Strings[8995]="你想要什么？作为一名邪兽人，你闻上去有点古怪……"
D.Strings[8996]="你不是想把这里当做自己家吧。也许你想吃点什么？"
D.Strings[8997]="我想让古格修护甲。也许我还会买点什么。"
D.Strings[8998]="有时候，那些该死的血精灵会顺路从我这里购买一些特殊的材料或是毒药。我必须随时保持这类货源，以免谣言传到伊利丹大人耳朵里，说龙喉氏族不与血精灵合作……$B$B<鲁姆普斯艰难地咽了口气。>$B$B我们可不希望发生那种事……"
D.Strings[8999]="你有什么特别的货物吗，鲁姆普斯？"
D.Strings[9000]="哦耶！你想尝尝这些枪支的威力吗，渣滓？走近点！"
D.Strings[9001]="你怎么和这些巨蟒扭打的？哦哦哦，呀呀呀，兄弟！"
D.Strings[9002]="听见了吗？你听见颂歌了吗，兄弟？他们正在为鲁克斯特欢呼！"
D.Strings[9003]="如果疯狂的鲁克斯特对你大发雷霆，你准备怎么做，兄弟？！"
D.Strings[9004]="<克希利浑身散发着红色的光芒。纳鲁在欢迎你这位盟友。>"
D.Strings[9005]="我愿意与你的军队并肩作战，克希利。"
D.Strings[9006]="你与灵翼龙族结下了深厚的情谊，我们都愿意在背后支持你！朋友，现在就给予我们的敌人致命一击吧！我们必须夺回失去的一切。"
D.Strings[9007]="你帮了灵翼龙族许多忙，$n。但是在你掌握更高级的骑术之前，是无法有什么进展的。只有最坚定的骑士才能帮助灵翼龙族。"
D.Strings[9008]="是的……施放你珍贵的小法术吧，呱——啊——呱！"
D.Strings[9009]="你的法术……呱——呱……脆弱的魔法……轻而易举地就能转而对付你……"
D.Strings[9010]="地面崩裂了！"
D.Strings[9011]="苏普雷姆斯愤怒地击打着地面！"
D.Strings[9012]="你一定很好奇为什么食人魔说话也能这么流利。这是生长在奥格瑞拉周围的水晶簇的副作用。那里的食人魔将这根法杖送给了我，镶嵌在法杖上的水晶赐予了我无穷的智慧。$B$B只要你继续在奥格瑞拉行善，那么总有一天，所有的食人魔同胞都能享受到这种福泽。谢谢你，我的$g国王:女王;。感谢你为我们所做的一切。"
D.Strings[9013]="啊……我……死了。"
D.Strings[9014]="我要去……奥格瑞拉了。"
D.Strings[9015]="伟大的$g国王:女王;陛下，杀了我吧……我很荣幸。"
D.Strings[9016]="$g国王:女王;$n陛下，我现在死了。"
D.Strings[9017]="$G国王:女王;陛下，你觉得……世上真的有个……奥格瑞拉吗？"
D.Strings[9018]="弱小的$r……你是一个……可怕的$g国王:女王;。"
D.Strings[9019]="又一个，嗯？你永远都不会成功……"
D.Strings[9020]="记住，你每天只能做一次收集工作。但是，我们也一直需要更多的水晶。任何废柴苦工都能把那些东西带回营地。"
D.Strings[9021]="我没有新任务交给你了，孩子。你已经不适合做体力活啦……"
D.Strings[9022]="感受我体内的恶魔之力吧！"
D.Strings[9023]="%s变成了一个灵体生物……"
D.Strings[9024]="%s的肉体在剧烈的怒火中烧得粉碎！"
D.Strings[9025]="%s把注意力集中在$n身上。"
D.Strings[9026]="伊利丹对我的氏族的控制非常严密，$n。但是无论如何，一切很快就会结束了。$B$B$n，你准备好了吗？氏族的未来就靠你了。"
D.Strings[9027]="以瓦丝琪女王的名义，去死吧！"
D.Strings[9028]="留在这里……"
D.Strings[9029]="我等会儿再对付你。"
D.Strings[9030]="你的成功转瞬即逝！"
D.Strings[9031]="你该去死了。"
D.Strings[9032]="伊利丹大人……会干掉你们的！"
D.Strings[9033]="我的耐心用尽了！死吧！去死吧！"
D.Strings[9034]="我要复仇！"
D.Strings[9035]="你知道，我是第一个。对我来说，死亡之轮已经旋转了许多次。时间已经流逝了许多……有太多事情要做了。"
D.Strings[9036]="你可以派上一些用场……"
D.Strings[9037]="事情更糟糕了。"
D.Strings[9038]="死亡真的并非那么糟糕。"
D.Strings[9039]="你在害怕什么？"
D.Strings[9040]="投降吧。"
D.Strings[9041]="我有些东西给你。"
D.Strings[9042]="你要表现出足够的尊敬！"
D.Strings[9043]="死亡之轮……又开始旋转了。"
D.Strings[9044]="嗨……我感觉不是太好。"
D.Strings[9045]="让我们开始做事吧，$n。我会让你了解我所掌握的知识，不过，先继续。"
D.Strings[9046]="是。除非这事跟我有关系。"
D.Strings[9047]="在明天到十年后这个阶段期间的某一天就会发生。我肯定。"
D.Strings[9048]="对你来说不错……对我则相反。"
D.Strings[9049]="我跟其他的小鬼开会讨论了一下，答案是“是”。不过有一个小鬼投了反对票。"
D.Strings[9050]="前景不错，但我比较悲观。"
D.Strings[9051]="要我说出这样的话真是有些难过，不过答案是“是”。"
D.Strings[9052]="如果矮人会飞，答案就是“是”。他们真的会飞？那就是咯！"
D.Strings[9053]="当然，但是你不会喜欢的。"
D.Strings[9054]="你在这里听到和看到的一切都要保密，$r。"
D.Strings[9055]="$g国王:女王;陛下！卓尔特愿为您效劳。"
D.Strings[9056]="葛罗克听说你是所有食人魔的新$g国王:女王;。恭……恭喜你，小$r。"
D.Strings[9057]="很不幸……是的。"
D.Strings[9058]="我看不到否定的理由，不过话说回来，有很多东西我都看不到。"
D.Strings[9059]="我可以用你的灵魂打赌。"
D.Strings[9060]="是的。但是如果别人问起来……别说是我告诉你的。"
D.Strings[9061]="你是不是已经问过一次了？是啊！"
D.Strings[9062]="告……告诉我……基尔加丹是红色的吗？"
D.Strings[9063]="啊，当然。你做梦去吧。"
D.Strings[9064]="大概吧。"
D.Strings[9065]="显然。"
D.Strings[9066]="跳三次，然后扭摆十分钟，就行了！"
D.Strings[9067]="绝对是啊。"
D.Strings[9068]="是的，但并非你所想的那样。"
D.Strings[9069]="没错没错！我说了一千次了！"
D.Strings[9070]="是啦是啦，别烦我啦！"
D.Strings[9071]="如果你让我出去，我就回答“是”。"
D.Strings[9072]="就像我背上的瘤那样千真万确。"
D.Strings[9073]="我这里的答案是肯定的，到你那里就不知道了。"
D.Strings[9074]="一个字，“当然！”"
D.Strings[9075]="是的。但是我宁愿不用回答这个问题。"
D.Strings[9076]="过会再问我，我忙着抓鼻子呢，精神很难集中。"
D.Strings[9077]="为啥我一定要回答你的问题？你会在别人摇晃你的时候占卜吗？"
D.Strings[9078]="是的，今天会下雨。什么？你没有问这个问题？太遗憾了。"
D.Strings[9079]="抱歉，我只会讲恶魔语。"
D.Strings[9080]="是！我是说，不是！嗯……哪个答案可以让你同意把我放出来？"
D.Strings[9081]="可能也许大概是。"
D.Strings[9082]="区别不大，反正你明天就要挂了。"
D.Strings[9083]="你应该问“我背后那个盗贼是不是要杀了我？”"
D.Strings[9084]="我真希望自己的冷却时间更长一点。"
D.Strings[9085]="%s耸了耸肩。天知道！"
D.Strings[9086]="就像我妈妈常说的一样：[恶魔语] “Razxx khaj jhashxx xashjx。”"
D.Strings[9087]="%s无视你。"
D.Strings[9088]="为什么是我？为什么不是一个地精或者侏儒……"
D.Strings[9089]="扭曲虚空中发生的事，就在扭曲虚空了结吧。"
D.Strings[9090]="不要进行无意义的赌博。你的幸运数字是2，2.5和根号2。"
D.Strings[9091]="你不想知道吗？"
D.Strings[9092]="哦哦哦！我可以清晰地感觉到……呃，没了。"
D.Strings[9093]="我的契约上可没有这个！"
D.Strings[9094]="你在拿我寻开心么？"
D.Strings[9095]="你觉得我是哪种小鬼？"
D.Strings[9096]="说“请”。"
D.Strings[9097]="想交换一下地盘吗？"
D.Strings[9098]="是不是无论什么东西困在球里，你都会这样向它发问？"
D.Strings[9099]="嘿！你倒是试试在有混蛋摇你的房子时来摆放家具看看啊！"
D.Strings[9100]="一切皆有可能。你只需要在这里签个字……"
D.Strings[9101]="答案有些模糊且潮湿。请清理一下思维后再重试。"
D.Strings[9102]="集中注意力（把我从这个牢笼里放出来）然后再试试看。"
D.Strings[9103]="请投入25银币，然后再试一次。"
D.Strings[9104]="你是我的朋友吗，丹尼？"
D.Strings[9105]="你还记得上次自己做的傻事吗？"
D.Strings[9106]="行啦，别白费力气了！"
D.Strings[9107]="两个字：不可能！"
D.Strings[9108]="你需要去搞个奥术智慧效果了，难道答案还不明显吗？不！"
D.Strings[9109]="你这辈子别想了！"
D.Strings[9110]="就算我不是个可以预知未来的小鬼，答案也是很明白的：不！"
D.Strings[9111]="成功的几率是百分之32.33（无限循环）。"
D.Strings[9112]="当黑石山冻成冰块的时候！"
D.Strings[9113]="哈哈哈哈，你在开玩笑对吧？"
D.Strings[9114]="难以置信！"
D.Strings[9115]="我的线人说“不”。不过那是在动刑之前……"
D.Strings[9116]="这个可能性等同于我逃出这只球的可能性。"
D.Strings[9117]="你在错误的时间摇晃了我，伙计！准备失望吧。"
D.Strings[9118]="除非你是超人什么的。而且你也知道，你分明不是。"
D.Strings[9119]="这个可能性等同于我跟一位魅魔约会的可能性。"
D.Strings[9120]="我预知未来的能力趋于无穷大，不过你成功的机会趋于零。"
D.Strings[9121]="不可能——你继续摇我也不会改变这个答案。"
D.Strings[9122]="答案是肯定的……"
D.Strings[9123]="……不！"
D.Strings[9124]="答案很简单，看我口型：没门。"
D.Strings[9125]="前景不妙！哈哈哈哈！接受现实吧！"
D.Strings[9126]="调查结果表明：哼哼！"
D.Strings[9127]="我来对付这些渣滓！进攻吧，朋友们！向伊利丹发起进攻！"
D.Strings[9128]="来吧，我的手下。让这个叛徒付出代价！"
D.Strings[9129]="你们这些乌合之众休想碰到我！"
D.Strings[9130]="猩猩宝宝"
D.Strings[9131]="现在我会变得更大，我会压碎你！"
D.Strings[9132]="球中的小鬼"
D.Strings[9133]="午餐篮"
D.Strings[9134]="让埃辛诺斯的烈焰吞噬你们！"
D.Strings[9135]="欢迎来到基伦的裁缝店，你可以在这里找到你需要的商品。如果你愿意向我讨教裁缝技能的话，和我说一声就成，我会很乐意教给你的。"
D.Strings[9136]="这里散发着污秽的恶臭，看来鸦人最近又堆积了新的战利品。"
D.Strings[9137]="<召唤猎手吉萨拉克。>"
D.Strings[9138]="如果你是在寻找零件、齿轮这种小玩意的话，那么你来对地方了！"
D.Strings[9139]="让我看看你都有些什么……呃，东西……"
D.Strings[9140]="<召唤风怒者瓦克奇斯。>"
D.Strings[9141]="<召唤卡尔洛格。>"
D.Strings[9142]="<召唤黑暗尖啸者阿克卡莱。>"
D.Strings[9143]="你看上去很眼熟……"
D.Strings[9144]="我的预言梦境中充满了世界各地正在发生着和可能发生的事件的景象。它们大部分都非常可怕，不过，这未必是不可改变的。"
D.Strings[9145]="需要施法材料的话，你可来对了地方。即使找遍整个沙塔斯城，你也找不到更好的选择了。"
D.Strings[9146]="你……你是谁？？你想要什么？"
D.Strings[9147]="在我把你做成我护甲上的又一个装饰前，给我滚到一边去。你的领袖和我有事要商量……"
D.Strings[9148]="好……好……我们马上走开……请不要伤害我们……"
D.Strings[9149]="%s笑了笑。"
D.Strings[9150]="我还以为你认同我的观点……"
D.Strings[9151]="莫格霍尔大王，我想……能够和你攀上交情真是荣幸。"
D.Strings[9152]="我是女伯爵希奈丝特拉。"
D.Strings[9153]="我不想说太多废话，女伯爵希奈丝特拉。就直接告诉我你想从龙喉氏族这里得到什么吧。"
D.Strings[9154]="我相信你肯定已经听说了奈法利安在艾泽拉斯的失败……虽然他失败了，但实验仍然继续着。我的主人……他继续进行着他的儿子没能完成的研究。"
D.Strings[9155]="主……主人？他还活着？"
D.Strings[9156]="你曾是一位重要的军官，莫格霍尔。我们不会轻易忘记你在格瑞姆巴托所做的一切。"
D.Strings[9157]="现在……我们要你找回龙卵。灵翼龙卵。他们毕竟是主人的东西。无论你出多高的价钱，我们都会和你交换的。"
D.Strings[9158]="%s显得非常紧张，话都说不利索了。"
D.Strings[9159]="是……是，是的……当然，我们只需要这个地方的水晶和矿石。也就是说……我们需要坐骑。"
D.Strings[9160]="主人听到这个消息一定会很高兴的。黑龙军团会满足你的一切要求，必要的情况下，你可以骑我们的幼龙。"
D.Strings[9161]="感谢你的慷慨，莫格霍尔。但我现在必须走了。"
D.Strings[9162]="你永远都别想活着离开这里！"
D.Strings[9163]="冷静！"
D.Strings[9164]="<玛德拉普正在擦着他的靴子。>"
D.Strings[9165]="立正，步兵！"
D.Strings[9166]="哇！好吧，好吧。我回去工作！"
D.Strings[9167]="嘿！不要再用训诫靴踢我啦！对不起！我马上就干活！"
D.Strings[9168]="啊！训诫靴踢得我好疼！我觉得在训诫靴下会工作得更好！"
D.Strings[9169]="为什么用训诫靴踢我？？为什么？？"
D.Strings[9170]="啊！！训诫靴！！"
D.Strings[9171]="啊呀！总有一天我也要拿到训诫靴……"
D.Strings[9172]="无尽的诅咒等待着你，$r！这座监狱再也关不住我了！"
D.Strings[9173]="灰舌破碎者们，你们的首领有话要说！"
D.Strings[9174]="背叛者不再掌控着我们的命运了，他施加在灰舌氏族灵魂上的邪恶魔咒已经消散了！"
D.Strings[9175]="从阴影中解脱吧！我将领导你们对抗真正的敌人。脱下你们的镣铐，拿起武器，去对抗你们的伊利达雷主人吧！！"
D.Strings[9176]="滚开，否则我就用训诫靴踢你。"
D.Strings[9177]="阿卡玛万岁！"
D.Strings[9178]="为我们的首领欢呼！阿卡玛万岁！"
D.Strings[9179]="不要浪费我的感情了！"
D.Strings[9180]="哦，你喜欢我的眼罩呀？嗯，不过你还是别戴它的好。"
D.Strings[9181]="嗯？什么？我这里有点忙，朋友！$B$B当然，要是你是来帮忙的，我有着整个世界的时间。"
D.Strings[9182]="%s似乎已经做好被捕捉的准备了。"
D.Strings[9183]="哇哦！感谢你一路把我带回这里。你原本不需要这样做的。"
D.Strings[9184]="你真是个讨人喜欢的家伙。我保证会好好照顾这只以太鳐的。"
D.Strings[9185]="棱柱中燃烧的眼睛让你感到恐怖……"
D.Strings[9186]="将35块埃匹希斯碎片放入棱柱中。"
D.Strings[9187]="邪能水晶熔炉可以将埃匹希斯碎片转化成不稳定的野兽合剂。这种合剂能让饮用者变得更加敏捷、强壮，并且更具活力。$B$B来吧，做出你的选择。"
D.Strings[9188]="用10块埃匹希斯碎片购买1瓶不稳定的野兽合剂"
D.Strings[9189]="<当你将埃匹希斯碎片放入邪能水晶熔炉并拉下控制杆后，从熔炉中传来了物体被碾碎的声音。很快一瓶合剂就从熔炉口落了出来。>"
D.Strings[9190]="利用邪能水晶熔炉制造另一瓶合剂。"
D.Strings[9191]="用50块埃匹希斯碎片购买5瓶不稳定的野兽合剂"
D.Strings[9192]="巴什伊尔水晶熔炉可以将埃匹希斯碎片转化成不稳定的巫术合剂。这种合剂能让饮用者变得更加聪明、更具活力，还可以增加法术伤害和治疗效果。$B$B来吧，做出你的选择。"
D.Strings[9193]="用10块埃匹希斯碎片购买1瓶不稳定的巫术合剂"
D.Strings[9194]="利用巴什伊尔水晶熔炉制造另一瓶合剂。"
D.Strings[9195]="<当你将埃匹希斯碎片放入巴什伊尔水晶熔炉并拉下控制杆后，从熔炉中传来了物体被碾碎的声音。很快一瓶合剂就落在了你的脚旁。>"
D.Strings[9196]="用50块埃匹希斯碎片购买5瓶不稳定的巫术合剂"
D.Strings[9197]="希望你能帮我们解决这件麻烦事。试想一下，如果你有10个儿子，他们都想尝试去做那些自己力所不能及的事，你该怎么办？$B$B尽管如此，我们却必须尽到做父亲的职责。"
D.Strings[9198]="你有孩子吗，$c？$B$B听我说，来到奥格瑞拉之后，我们都觉得没有以前快乐了。那些水晶让孩子们变得聪明了许多。从前，我们只需要敲打他们的小脑瓜就能让他们闭嘴。而现在，他们却整天吵着问我们各种各样关于天空卫队的事情。$B$B无知真是幸福！"
D.Strings[9199]="这孩子还是有些愚钝——看来他还需要接受水晶的启迪，不过，谢谢你为他制造了那些合剂。$B$B嗨！还有九个孩子需要你帮忙呢。$B$B<托尔库斯的两个脑袋都叹了口气。>$B$B想从我这里领走一个小孩吗？我愿意便宜卖给你。"
D.Strings[9200]="你刚来奥格瑞拉不久，这些水晶簇的好处你还没有完全体会到呢。何况，你只有一个脑袋。$B$B而我们就不同了。我们在这里住了很长一段时间了。因此，你可以想象我们聪明的头脑精通多少事情。$B$B最近，我们对铸魔营地的恶魔挺感兴趣的。具体来说，我们设计出了一个彻底摆脱他们的好办法。$B$B至少，理论上是那样。"
D.Strings[9201]="我们希望每天都能制造出一个以上的黑暗符印，但那样做太浪费时间了。从自然法则上来讲也办不到，而且我们的能力有限，这样的出产频率恐怕很难实现。$B$B只要有聪明的家伙愿意帮忙，我们就会将他们征召过来，以此获得更多的黑暗符印。"
D.Strings[9202]="巴什伊尔水晶熔炉可以将埃匹希斯碎片转化成不稳定的巫术合剂。这种合剂能让饮用者变得更加聪明，更具活力，还能增加法术伤害和治疗效果。$B$B但是10块埃匹希斯碎片才能购买1瓶合剂，你身上的碎片数量不够。"
D.Strings[9203]="邪能水晶熔炉可以将埃匹希斯碎片转化成不稳定的野兽合剂。这种合剂能让饮用者变得更加敏捷、强壮和更具活力。$B$B但是10块埃匹希斯碎片才能购买1瓶合剂，你身上的碎片数量不够。"
D.Strings[9204]="甘克和$r一样都是刚来奥格瑞拉的。这里就和下面那些食人魔所说的一样，真是天堂一般的地方。那些水晶簇让甘克变聪明了，但是也让甘克的脑袋很痛。$B$B<甘克的两个脑袋互相点着头。>$B$B我们正在学习制造晶铸黑暗符印。学会的话，就能粉碎恶魔的迁跃门了！"
D.Strings[9205]="甘克现在很聪明！我们知道如何将黑暗符印制成晶铸黑暗符印！"
D.Strings[9206]="$n破坏了迁跃门，做得好！但是恶魔又修复了被毁坏的迁跃门。$B$B$n，只要你给甘克另一枚黑暗符印，甘克就为你制作晶铸黑暗符印！"
D.Strings[9207]="欢迎来到奥格瑞拉，$c。$B$B食人魔通过奥格瑞拉周围的水晶簇散发出的魔力获得了敏锐的才智。尽管我们不完全明白这是怎么回事，但我们喜欢这个新家，只想在这里过安宁的生活。$B$B可是恶魔、虚灵，还有黑龙却偏偏要来滋扰生事。"
D.Strings[9208]="我代表奥格瑞拉对你的所做的一切表示感谢，$n。$B$B<库洛尔的左边脑袋点着头，右边脑袋则对着你微笑。>$B$B不要忘了，帮助奥格瑞拉就是帮助我们在刀锋山的食人魔同胞。为了表达对你的敬意，他们已经将你奉为$g国王:女王;。"
D.Strings[9209]="凭你的能力，还不够资格参加晋级赛。不过你可以找竞技场管理员谈一谈，参加一些练习赛。训练永远都不会嫌太晚的。"
D.Strings[9210]="你要伤害我吗？我可不想和战争扯上关系，$r。$B$B我只是个体弱多病的学者，请你别来打扰我！"
D.Strings[9211]="这枚龙卵看上去和正常的黑龙卵一样富有弹性。如果你在它附近放上一些埃匹希斯碎片，它们的震动或许能让龙卵裂开？"
D.Strings[9212]="这枚龙卵看上去和正常的黑龙卵一样富有弹性。如果你在它附近放上一些埃匹希斯碎片，它们的震动或许能让龙卵裂开？$B$B可惜这样做需要35块埃匹希斯碎片，你身上没有足够的水晶。"
D.Strings[9213]="将35块埃匹希斯碎片放在龙蛋附近使其碎裂。"
D.Strings[9214]="<安吉拉在地狱猎犬耳边低语着什么，直到她留意到你。>$B$B和其它地狱猎犬相比，基尔西的体型显得娇小许多，但是这并未影响到它。我相信外域会改变这一切的，基尔西，对吧？$B$B妈妈的小天使一定会成长为一头巨大凶猛的地狱猎犬！一定！"
D.Strings[9215]="%s尖叫着呼唤它的母亲。"
D.Strings[9216]="穆维里克！！！"
D.Strings[9217]="要不是塞纳里奥远征队，我肯定早就葬身矿洞了……是他们救了我的命！因此，我为塞纳里奥远征队的盟友们提供修理装备以及出售施法材料的服务。"
D.Strings[9218]="你在这里可以找到很多事情做，$n。"
D.Strings[9219]="嗨，你最近挺忙的是吧？！你不仅帮助我们轰炸恶魔，还替我们捕捉虚空鳐，我都不知道该怎么感谢你。$B$B你让我们的工作轻松了许多。继续保持下去吧！"
D.Strings[9220]="狂暴姿态！无情地攻击他们！"
D.Strings[9221]="我们必须在矿洞附近重建我们的要塞！"
D.Strings[9222]="<暗血监工咕哝着。>"
D.Strings[9223]="他们派你来杀我的吧，嗯？我早就猜到了……被恐怖支配的生物都一样。$B$B不过你……你和他们不一样……"
D.Strings[9224]="我是为你而来的，监工。"
D.Strings[9225]="你竟敢质问一个龙喉督工！"
D.Strings[9226]="督工？$B$B你不是龙喉督工，正如我不是暴风城的国王一样。对……你就是他们提起的那个家伙。"
D.Strings[9227]="灵翼龙族。他们说愿意保护破碎者氏族，让我们享受未曾体验过安宁与和平。我们决定接受龙族的恩惠，帮助托兰纳古唤醒了那些居住在矿洞中的生物，并为此付出了巨大的代价。在这场骚乱中，很多兄弟不幸遇难。我们计划让矿洞变成不适合居住的废墟，以此迫使龙喉兽人离开这座岛屿。"
D.Strings[9228]="谁提到了我？你在说什么，破碎者？"
D.Strings[9229]="请继续说。"
D.Strings[9230]="龙喉氏族已经堕落了。他们在岛上疯狂地开采天然资源，并利用这些资源支援伊利丹派驻在黑暗神殿外的军队。当然，他们将大部分资源据为己有，而且把私藏的资源出售给出价最高的人。"
D.Strings[9231]="这些出价者是谁？"
D.Strings[9232]="我们不知道。但我们相信黑龙一族以独立的第三方身份参与了此事。这就是你来这里的目标，$r。你要抽丝剥茧般地揭开这个秘密，让灵翼龙族重获自由。$B$B那么……我想矿洞女王要求你带回我的手吧。"
D.Strings[9233]="呃……是的。"
D.Strings[9234]="如果它能换来龙喉氏族的衰落，我很乐意做出这样的牺牲。"
D.Strings[9235]="我必须马上离开这个地方！"
D.Strings[9236]="埃匹希斯圣物闪着微光，似乎里面隐藏着什么东西。"
D.Strings[9237]="插入1块埃匹希斯碎片，然后开始！"
D.Strings[9238]="你隐约看见了前方的埃匹希斯纪念碑。"
D.Strings[9239]="插入35块埃匹希斯碎片，然后开始！"
D.Strings[9240]="立正，队长！"
D.Strings[9241]="棱柱中燃烧的眼睛让你感到恐怖……召唤它需要35块埃匹希斯碎片，而你身上没有足够的水晶。"
D.Strings[9242]="这一下是为了娜萨！"
D.Strings[9243]="通往欢愉之园的大门打开了。"
D.Strings[9244]="你这个小家伙，害我看走了眼。$B$B我猜你是来购买我出售的特殊货物的吧？"
D.Strings[9245]="直视背叛者的双眼吧！"
D.Strings[9246]="太轻松了！"
D.Strings[9247]="谁想成为下一个？"
D.Strings[9248]="你们对力量一无所知！"
D.Strings[9249]="别理会维克斯顿的话。你想要好东西？那就和克里希谈一谈。如果你的声望够高的话，我正好有你需要的货物。孩子，你要明白，竞技场上的懦夫是没有资格拥有这些东西的。"
D.Strings[9250]="是面对伊利丹的时候了，$n。你准备好了吗？"
D.Strings[9251]="我准备好了，阿卡玛。"
D.Strings[9252]="欢迎你，朋友！你想看什么？"
D.Strings[9253]="你好，朋友。我们能帮你什么忙吗？"
D.Strings[9254]="我们能帮你什么忙吗？"
D.Strings[9255]="勇士！我们能帮你什么忙吗？"
D.Strings[9256]="你来到这里真是我们的荣幸，朋友。我们能帮你什么忙吗？"
D.Strings[9257]="勇士！希望你喜欢我们的食物。"
D.Strings[9258]="我们的食物能令最强大的勇士赞不绝口。"
D.Strings[9259]="还是很饿吗，朋友？我们能帮你什么忙吗？"
D.Strings[9260]="朋友，我们为你准备了一顿美餐。"
D.Strings[9261]="我们能为你提供什么美味吗？"
D.Strings[9262]="嘿，朋友。如果你和天空卫队搞好关系的话，我就为你开通前往鸦羽山黑风码头的直达航线。$B$B你喜欢这只漂亮的虚空鳐吗？它真可爱。"
D.Strings[9263]="你好，$n。要赶去我们位于鸦羽山的基地黑风码头吗？我为你准备了一只漂亮的小虚空鳐。$B$B现在就出发吗？和我说一声就成！"
D.Strings[9264]="是，我愿意乘坐虚空鳐飞往黑风码头。"
D.Strings[9265]="你好！如果你想要飞往刀锋山的天空卫队哨站的话，我可以为你准备一只虚空鳐。$B$B和我说一声就成。"
D.Strings[9266]="你好。如果你在沙塔尔天空卫队的声望再提升一点，我就为你开通前往刀锋山天空卫队哨站的直达航线。"
D.Strings[9267]="当然！送我回天空卫队哨站吧。"
D.Strings[9268]="我们会为你奉上秘制饮品：鸡尾酒和梦想。至少我们能帮你实现其中一项。"
D.Strings[9269]="所有人都要喝酒。我们能为你做些什么呢？"
D.Strings[9270]="你好，朋友。我们能为你做些什么吗？"
D.Strings[9271]="我们的美酒能滋润最干涸的喉咙。"
D.Strings[9272]="除了和我闲聊，你就没有别的事可做了吗？$B$B拿出你的勇气来！"
D.Strings[9273]="这样就对啦！我们为你所做的一切感到光荣！$B$B如果你想要前往我们在鸦羽山的另一处基地，就和天空卫队训练师伊雷娜谈一谈吧。她会很乐意为你安排的。"
D.Strings[9274]="你受到了大家的尊敬，朋友！要不是我明白事理的话，肯定会以为你想抢我的饭碗！！！$B$B只要你像之前那样继续帮助我们，你就值得受到这样的尊重！"
D.Strings[9275]="要么饮酒，要么滚开！"
D.Strings[9276]="我还能说什么，$n？你是最棒的沙塔尔天空卫士！$B$B别被溢美之词冲昏了头脑。我还有别的东西可以教给你！$B$B<天空指挥官凯勒对你咧嘴一笑，眨了眨眼睛。>"
D.Strings[9277]="我知道你耗费了不少精力来帮助我们，$c。$B$B新手，继续努力吧，歼灭所有的恶魔！"
D.Strings[9278]="哨站的每个人都在提起你的名字。别因此沾沾自喜，我知道你能做得更好！$B$B我会继续关注你的，新手。"
D.Strings[9279]="尊敬的勇士，我们能帮你什么忙吗？"
D.Strings[9280]="好吧，我承认。$n，你已经证明了自己的实力。$B$B如果说我之前对你太过严厉的话，那也是因为我发现你具备一名优秀的天空卫士的潜质。我敢说你就是我们的王牌飞行员！$B$B任何时候你想来帮忙都成，我会为你准备好一组炸弹的。"
D.Strings[9281]="我们很高兴为你提供补给。"
D.Strings[9282]="嗨，$c！$B$B<卡提害羞地看着你。>$B$B如果你愿意为我们捕捉更多的以太鳐，可以随时过来找我！"
D.Strings[9283]="朋友！好久不见！我们能为你做些什么吗？"
D.Strings[9284]="你知道吗，$n，很荣幸能和你一起共事！$B$B当你闲下来的时候，或许我们可以共进晚餐？$B$B哦，我们为你开通了前往鸦羽山基地的直达航线，我有没有告诉你这件事啊？如果你想去那里的话，就与天空卫队训练师伊雷娜谈一谈。"
D.Strings[9285]="这么说，你常来这附近，可惜闲暇时我们总是没机会聚聚。$B$B我说得对吗？$B$B<卡提故意流露出振奋的神情。>$B$B不管怎样，我都想告诉你，我……我们真的非常感谢你为天空卫队所做的一切！"
D.Strings[9286]="希望你没把我当做马屁精之类的家伙，$n。$B$B我的意思是，我知道你在天空卫队享有很高的声誉，嗯……我想你大概不会愿意和我这样地位卑微的工人呆在一起。$B$B不过，如果你想出去逛逛，或是一起捕捉以太鳐什么的，随时来找我！我等着你。$B$B我真想你……"
D.Strings[9287]="这些圣物伟大而神秘。如果能系统地研究它们，或许就能揭示它们蕴藏的真正力量。"
D.Strings[9288]="<库洛尔的左脑袋在说话。>$B$B你如此热情地帮助我们，真是令人感动呀……$B$B<他的右脑袋作着结论。>$B$B……因此我们想让你知道，我们非常感谢你所做的一切！"
D.Strings[9289]="尊贵的英雄，钢铁远没有血肉之躯来得强壮。唯有持有者才能令钢铸武器的效力发挥到极致。嗯，不说这些了……我们能帮你什么忙吗？"
D.Strings[9290]="人们已经开始对你表示崇敬了。$B$B<库洛尔的左眼凝视着你，折射出冷漠的目光。>$B$B继续加油，$n！"
D.Strings[9291]="首先你成为了刀锋山食人魔的$g国王:女王;，接着又赢得了奥格瑞拉食人魔的尊敬。$B$B从来没有哪个$r能取得这样的成就，你简直是活生生的例证。$n，谢谢你，我们欠你的永远都无法偿还！"
D.Strings[9292]="一生当中能信任的东西可不多。钢铁就是其中之一。"
D.Strings[9293]="我们食人魔能得到你这样一位$r的帮助，我感到十分荣幸。你让我们重新拥有了一个光明的未来。$B$B现在，我们只需要处理掉这些剩下来的头疼事务就好了。不过，你确认不想要领养一个我们的孩子吗？"
D.Strings[9294]="和钢铁比起来，铸钢者的双手是不是更厉害呢？"
D.Strings[9295]="你给予了我们这么多帮助，真是令我们感到惊讶。要是没有你，我们肯定早就被恶魔或是黑龙给撵出了家园！$B$B顺便说一句，我们提过想要将一个孩子便宜卖给你，对吧？不要？你不感兴趣吗？"
D.Strings[9296]="在奥格瑞拉这里，我们有足够的时间来沉思有关钢铁的秘密。不过这都是另一个话题了……有什么我可以为你效劳的吗？"
D.Strings[9297]="需要我为你铸造钢铁武器吗？"
D.Strings[9298]="$n，你慷慨地帮助我们，使我们一家子过得其乐融融，我们真不知道要怎么感谢你才好。 $B$B嗯，我们之前开玩笑说要把其中一个小孩卖给你，你没有当真吧？我们真的是在开玩笑呃……虽然这群小子不断地制造麻烦。$B$B嘿，你们就不能安静点吗？！"
D.Strings[9299]="我们有点开始喜欢小$n了！你好厉害！连恶魔也能打赢！"
D.Strings[9300]="甘克喜欢小$r$n。你杀死了大恶魔，让所有小恶魔们感到害怕！$B$B<甘克的两个脑袋都在对着你笑。>"
D.Strings[9301]="我们永远欢迎你来这里！$B$B库洛尔说$r是我们的英雄！$B$B$n现在就像是我们食人魔的一员了。但是，甘克搞糊涂了，因为他觉得$n需要再长大点。"
D.Strings[9302]="我们能为你做些什么吗，尊贵的$G兄弟:姐妹;？"
D.Strings[9303]="麻鹰被证明在搜索乌鸦石方面是非常有天分的，因此观察者艾莱亚训练了另一只麻鹰远程传递我的声音。当你研究显现在石板上鸟的灵魂时，它可以帮助我们进行联络！"
D.Strings[9304]="尊敬的$G兄弟:姐妹;，我们能帮你什么忙吗？"
D.Strings[9305]="你好，朋友！我们能帮你什么忙吗？"
D.Strings[9306]="我们是来帮忙的。"
D.Strings[9307]="你在这里的知名度已经相当高了，$r。这是件好事。$B$B我相信你不会被溢美之词冲昏了头脑，你会继续帮助我们放逐恶魔的，对吗？"
D.Strings[9308]="你的无私让我们感到无地自容，$n。先前，我们确实有点自以为是，但是你让我们彻底改变了态度。$B$B谢谢你，希望你会继续帮助我们对抗铸魔营地。"
D.Strings[9309]="你在奥格瑞拉过得很愉快吧？$B$B我们有许多手工打造的好东西。我们挑选出最好的货物，准备出售给你这样酷毙了的客人！$B$B嗯，在你外出执行任务、确保奥格瑞拉安全的同时，有空的时候可以顺路过来看看我们出售的货物。$B$B朋友，祝你好运。"
D.Strings[9310]="你想要什么？"
D.Strings[9311]="我是巴塔斯的特使。他派我来收集一份完美的奥术精华。"
D.Strings[9312]="霍纳斯，让我看看你出售的货物。"
D.Strings[9313]="<莫格霍尔大王向你敬礼。>"
D.Strings[9314]="<召唤泰罗克。>"
D.Strings[9315]="嘿，$n，只要你继续努力的话，我们出售的货物就任你挑选。这有点像是因果报应的说法吧。$B$B那么，请尽力帮助我们以及北边的天空卫队吧。$B$B嗯……谢谢你！"
D.Strings[9316]="库洛尔在我面前为你说了一堆好话，$n。怎么样，我们还出售一些特别的食人魔美酒哩。$B$B它们都是非常美味的！"
D.Strings[9317]="你在这里很受尊敬，朋友。好像每个人都在说起你。真酷。$B$B请随便看看吧，说不定有你感兴趣的东西呢。我们有很多上等货。"
D.Strings[9318]="还有什么好说的呢，$n？伙计，你可以随意选购店里的商品！$B$B对极了！"
D.Strings[9319]="下一个是谁？"
D.Strings[9320]="%s吃着刚被杀死的迁跃追迹者。"
D.Strings[9321]="滚开！你别想从我这里得到任何东西。"
D.Strings[9322]="今天你想从我这里学到什么新知识呢？"
D.Strings[9323]="过来，过来。要是你已经准备好了上好的皮革，我会让你看看怎么制作有用的物品。"
D.Strings[9324]="我听说，海对面有个名叫萨鲁·钢怒的铁匠大师。如果你想要继续提升你的技能，就去奥格瑞玛的铁匠铺找他吧，$c。祝你好运。"
D.Strings[9325]="你想考验我？"
D.Strings[9326]="勇敢的尝试。"
D.Strings[9327]="华丽的击杀！"
D.Strings[9328]="算……算你走运。"
D.Strings[9329]="你们完全不够格。"
D.Strings[9330]="你们想要杀了我？你们先死吧！"
D.Strings[9331]="逃吧，否则就来受死！"
D.Strings[9332]="我的使命完成了。"
D.Strings[9333]="本该如此。"
D.Strings[9334]="命运……在等待。"
D.Strings[9335]="没有第二次机会了！"
D.Strings[9336]="为了奎尔萨拉斯！为了太阳之井！"
D.Strings[9337]="我觉得今晚我能享用一顿用$r和食人魔烹制的美餐。"
D.Strings[9338]="我有很多惊喜要给你们！"
D.Strings[9339]="嗨，$r。今天你对什么感兴趣呀？"
D.Strings[9340]="通用语……多么粗俗的语言。Bandal！"
D.Strings[9341]="我还有更重要的事情要做……"
D.Strings[9342]="伊利丹大人，我……"
D.Strings[9343]="享受你们最后的时光吧。"
D.Strings[9344]="你是我的了！"
D.Strings[9345]="部落会……毁灭你们。"
D.Strings[9346]="午餐时间。"
D.Strings[9347]="更多！我还要更多！"
D.Strings[9348]="喝你的血。吃你的肉。"
D.Strings[9349]="我饿了。"
D.Strings[9350]="我要把你们撕成碎片！"
D.Strings[9351]="当心吧，我复活了！"
D.Strings[9352]="太愚蠢了……"
D.Strings[9353]="够了！不要继续了！"
D.Strings[9354]="给我跪下！"
D.Strings[9355]="我不要……被忽视！"
D.Strings[9356]="当心点，懦夫！"
D.Strings[9357]="你可以获得任何你想要的东西……只要付得起代价。"
D.Strings[9358]="我很满足。"
D.Strings[9359]="没错，你要和我们在一起了……"
D.Strings[9360]="当心你所期望的东西……"
D.Strings[9361]="你们走得太远了。"
D.Strings[9362]="我会等着的。"
D.Strings[9363]="我不会离开太远的！"
D.Strings[9364]="等待你们的只有痛苦与折磨！"
D.Strings[9365]="不要留下我一个人！"
D.Strings[9366]="看看你们强迫我做了些什么！"
D.Strings[9367]="我不愿意这样！"
D.Strings[9368]="痛苦才刚刚开始……"
D.Strings[9369]="我不想回去！"
D.Strings[9370]="现在，我该做些什么？"
D.Strings[9371]="既然来了，就要付出代价。"
D.Strings[9372]="我根本没什么感觉。"
D.Strings[9373]="你们觉得很有趣吗？"
D.Strings[9374]="是办正事还是找乐子呢？"
D.Strings[9375]="你看起来有点紧张……"
D.Strings[9376]="不要害羞。"
D.Strings[9377]="我是你的了。"
D.Strings[9378]="我们正准备对巴什伊尔码头发动一次进攻，来研究他们的水晶熔炉。请你尽力帮助我们！天空卫队以太技师会在$4581d后出发。"
D.Strings[9379]="来得快，去得也快。"
D.Strings[9380]="多么快乐的结局啊。"
D.Strings[9381]="我……还不能死。"
D.Strings[9382]="我支撑不了多久了。"
D.Strings[9383]="不！我不能死！"
D.Strings[9384]="过来，$n。伊利丹大人在等你。"
D.Strings[9385]="龙喉氏族的勇士们，都聚集过来吧！就在你们中间，一位佼佼者已经晋升为领主了！向$n领主致敬！表达你们的敬意和忠诚吧！"
D.Strings[9386]="伊利丹大人很快就来到这里。"
D.Strings[9387]="这里散发着污秽的恶臭，看来鸦人最近又堆积了新的战利品。\n\n你需要10张迷时卷轴来召唤泰罗卡仇敌的后裔。"
D.Strings[9388]="伊利丹大人万岁！"
D.Strings[9389]="伊利丹大人，这位就是我和其他人向您提到过的龙喉氏族的英雄。他会引领我们走向胜利！"
D.Strings[9390]="这是什么意思，莫格霍尔？"
D.Strings[9391]="但是……大人，我不明白。$n……这个兽人曾经为我们……"
D.Strings[9392]="骨堆中弥漫出一股恐怖的黑暗能量。"
D.Strings[9393]="安静！"
D.Strings[9394]="你给我闭嘴，白痴。你真是个不可理喻的蠢材……"
D.Strings[9395]="这就是你所谓的英雄？"
D.Strings[9396]="你们被欺骗了，白痴。"
D.Strings[9397]="整个……计划……都被破坏了！"
D.Strings[9398]="我希望立即在神殿内看到这个渣滓的尸块。否则你们就将遭受比死亡更痛苦的命运！"
D.Strings[9399]="需要战场补给吗？"
D.Strings[9400]="长官，我能为你提供什么装备吗？"
D.Strings[9401]="需要补给吗？"
D.Strings[9402]="你胆敢欺骗莫格霍尔！在将你送到伊利丹大人的神殿之前，我要让你尝尝你想都不敢想的痛苦！我要折磨你，享受复仇的乐趣。"
D.Strings[9403]="你休想伤害这个孩子，莫格霍尔！$n，快点，爬到我的背上来！"
D.Strings[9404]="你永远都无法做好万全的准备。"
D.Strings[9405]="你好，旅行者。"
D.Strings[9406]="太空卫队以太技师和他的护卫队正在前往巴什伊尔码头的途中。去那里和他们碰面，帮助他们完成任务吧！"
D.Strings[9407]="太空卫队以太技师和她的护卫队正在研究巴什伊尔水晶熔炉，她需要帮助！前往巴什伊尔码头，找到以太技师并确保她的安全！"
D.Strings[9408]="遗忘药剂专精并不是件轻松的事。\n\n你真的确定吗？"
D.Strings[9409]="遗忘转化专精并不是件轻松的事。\n\n你真的确定吗？"
D.Strings[9410]="伊利丹的将领已经全部被打败了，$n。如果你准备就绪，就勇敢地前进吧。"
D.Strings[9411]="我准备好了。带我去命令大厅吧。"
D.Strings[9412]="伊利丹的侍从依然守护着神殿大厅，$n。如果你打败了他们，我就能带你进入神殿的深处。"
D.Strings[9413]="嗨，那是我们的王牌飞行员，$n！"
D.Strings[9414]="瞧，是$n，我们的王牌飞行员。"
D.Strings[9415]="$n，你有在玩极品飞车的感觉吗？"
D.Strings[9416]="最近你去过巴什伊尔码头帮忙吗，$n？"
D.Strings[9417]="$n，见到你真是个意外的惊喜。"
D.Strings[9418]="立正，$n军官来了！"
D.Strings[9419]="$n，天空的统帅，你在干什么？"
D.Strings[9420]="呵呵，有$n在天空飞翔，我们的敌人就要小心了！"
D.Strings[9421]="好吧，有件事是肯定的。$n再也不是移动荣誉了！"
D.Strings[9422]="$n，你的坐骑还撑得住吧？最近情况很艰难吗？"
D.Strings[9423]="嗯，这不是我们的常驻飞行员$n吗……最近怎么样啊，王牌飞行员？"
D.Strings[9424]="你已经清除了前路的障碍，离我的同胞又近了一步。我与他们之间，与这座神殿之间仍然有着强烈的羁绊。你愿意继续深入神殿吗？"
D.Strings[9425]="不久前，我的同胞还在这里，但是现在我和他们之间的感应却越来越微弱。一个拥有强大力量的生物守护着庭院，阻止了通往神殿深处的道路。"
D.Strings[9426]="带我去找其他死誓者，奥鲁姆。"
D.Strings[9427]="%s呲着牙发出嘶嘶声，以示威胁。"
D.Strings[9428]="瓦克奇斯携着狂风朝你恶狠狠地扑过来。"
D.Strings[9429]="只有最擅长追捕伊利丹仆从的猎手才能在我这里选购货物。$B$B当你在沙塔尔、塞纳里奥远征队以及奥尔多的声望达到崇拜时，我才会出售货物给你。"
D.Strings[9430]="只有最擅长追捕伊利丹仆从的猎手才能在我这里选购货物。$B$B当你在沙塔尔、塞纳里奥远征队以及占星者的声望达到崇拜时，我才会出售货物给你。"
D.Strings[9431]="欢迎你，$n。伊利丹将特殊的徽记赐给了他麾下最强大的仆从，替我取回这些徽记，我就让你选购这些炼金商品。"
D.Strings[9432]="$n，我们应该找个时间来赛跑。"
D.Strings[9433]="在天空卫队的队员名单上，$n最为出众，因此名字也排在首位。"
D.Strings[9434]="$n是一位文雅的军官。"
D.Strings[9435]="也许有一天$n会将$g他:她;的绝招教给我们？"
D.Strings[9436]="肉眼见不见的鸦人们……他们就在我们身边……注视着我们……他们在等待！"
D.Strings[9437]="我是做幼龙生意的，$n。我得到授权，向最高阶的军官们出售虚空幼龙。"
D.Strings[9438]="我想要购买一只新的幼龙。"
D.Strings[9439]="你需要什么，$c？"
D.Strings[9440]="苏普雷姆斯锁定了一个新目标！"
D.Strings[9441]="游戏时间到此结束！"
D.Strings[9442]="你没发现我在这里正忙着吗？"
D.Strings[9443]="科隆克，能给我解释一下充能的聚焦水晶有什么用吗？"
D.Strings[9444]="聚焦水晶？当然，我会解释清楚的，毕竟，看上去你只具备完全理解这个概念所必需的一半脑力。$B$B首先，通过一个简单的反应，一块耗尽能量的聚焦水晶可以与十块埃匹希斯碎片产生连接，并在反应结束之后转化为一块充能的聚焦水晶。这些充能的聚焦水晶具备某种医疗能力，但更重要的是，它可以与某只被占据的恶魔产生共效，并应用在特殊的地方。$B$B比如说，每块充能的聚焦水晶的都可以使某只被占据的恶魔展现出特殊的力量。不久之后，甘克就会派你去完成一个类似的任务。"
D.Strings[9445]="你浪费了太多的时间，凡人。长眠吧！"
D.Strings[9446]="神秘的蹄印，烧焦的盾牌，四散的徽章……这些东西有什么联系吗？"
D.Strings[9447]="这种罪行不容姑息。旅店的地理位置和它的离奇被毁让事态变得非常棘手。朋友，用谨慎的态度去树荫旅店展开调查吧。"
D.Strings[9448]="你能再撒一次反光粉吗？"
D.Strings[9449]="“朋友”，如果你认为自己能阻止我们的话，那你就大错特错了。"
D.Strings[9450]="我们一定要把吉安娜的懦弱行径曝光！"
D.Strings[9451]="这些家伙总有一天会明白，普罗德摩尔将军是一位真正的英雄！"
D.Strings[9452]="就是像你这样的家伙削弱了联盟的力量，邀请部落来夺走我们为之奋斗的一切！"
D.Strings[9453]="朋友，感谢你成功地保卫了塞拉摩。"
D.Strings[9454]="等你下班以后，我请你去旅店喝上几杯，一起回忆过去的美好时光。"
D.Strings[9455]="难道你不怀念往昔的岁月吗？我的朋友知道如何重返荣耀……"
D.Strings[9456]="朋友，你看上去是位通情达理的$c。你可曾记得塞拉摩昔日的光辉岁月？那是吉安娜禁止我们与部落交战之前的事情了。兽人仍在频频挑衅，而我们却被告知不得挑起战乱，你是否对此感到厌倦？"
D.Strings[9457]="你的言论根本影响不了我。去别的地方散布那些叛逆的理论吧，叛徒！"
D.Strings[9458]="我感觉到了真正的战争气息。水果贩已经得到了食人魔的援助，我也必须叫来我的援兵。"
D.Strings[9459]="无头骑士的灵魂已经变得疯狂了！在万圣节期间，他随时可能袭击这座村庄！"
D.Strings[9460]="无头骑士要攻击村子了！谁能救救孩子们，谁能阻止它！"
D.Strings[9461]="现在，无头骑士对我们的威胁已经解除了。我们又可以呼吸到自由的空气了，但如果不能在有头的情况下击败它，它随时还会回来的。"
D.Strings[9462]="%s看到午餐之后高兴地叫了起来！"
D.Strings[9463]="%s开心地吃着午餐。"
D.Strings[9464]="%s跳了一支特殊的舞蹈，对你表示感谢。"
D.Strings[9465]="老实说，我也搞不清楚飞艇目前到底在哪儿……"
D.Strings[9466]="飞艇目前在哪里？"
D.Strings[9467]="飞艇应该是刚刚到达奥格瑞玛。"
D.Strings[9468]="飞艇应该是刚刚从奥格瑞玛起航。"
D.Strings[9469]="飞艇应该是刚刚从幽暗城起航。"
D.Strings[9470]="无头骑士发动了攻击！火焰可能会吞噬整个村落！我们该怎么办？"
D.Strings[9471]="飞艇应该是刚刚到达幽暗城。"
D.Strings[9472]="飞艇应该是刚刚到达格罗姆高。"
D.Strings[9473]="飞艇应该是刚刚从格罗姆高起航。"
D.Strings[9474]="飞往格罗姆高的飞艇已经靠港了！要去荆棘谷的就赶快啦！"
D.Strings[9475]="飞艇应该是刚刚到达格罗姆高……"
D.Strings[9476]="飞艇应该是刚刚到达奥格瑞玛……"
D.Strings[9477]="飞艇应该是刚刚从格罗姆高起航……"
D.Strings[9478]="飞艇应该是刚刚从奥格瑞玛起航……"
D.Strings[9479]="我整天都在收集飞艇零件。就这样，弗雷萨还不肯给我加点薪水。至于你，你肯定不是来跟我抢工作的，对吧？我猜你想知道飞艇现在的位置在哪。总之，你运气不错，我这里就有个飞艇追踪装置了！"
D.Strings[9480]="去往幽暗城的飞艇目前在哪里？"
D.Strings[9481]="嗨，谢谢。"
D.Strings[9482]="这……这只是个玩笑吧？"
D.Strings[9483]="我很久没读到过这么好笑的东西啦。你是来逗我开心的吧？"
D.Strings[9484]="一群疯子！你们真的相信这东西吗？"
D.Strings[9485]="我永远都不会参与这样的组织。不过最好留着这个。这东西迟早有用……"
D.Strings[9486]="商人格里伏塔因多次诈骗顾客，被判驱逐出沙塔斯城。我们要仔细检查他出售的这些小玩意儿。请配合我们的工作，离开他的摊位。"
D.Strings[9487]="我们有世界上最棒的酿酒厂，雷霆啤酒酿造商们一直引以为傲。"
D.Strings[9488]="哇！你真的想要从我们手中购买吗？"
D.Strings[9489]="你没看到我有好多事情要忙吗？走开点，农夫！"
D.Strings[9490]="等等！我想喝点咖啡！"
D.Strings[9491]="我想你知道我是谁吧。但是，你还是不停地烦我？$b$b你是不是想引起我的注意？"
D.Strings[9492]="拜托，别讲那种荒谬的话了！我就是巴德·奈德雷克，如假包换！$b$b我游历过这片大陆的每个角落，从海加尔山颠到沉没的神庙都留下了我的足印。事实上，沉没的神庙还是我命名的呢！$b$b是啦，就是我。你还怀疑什么呢。"
D.Strings[9493]="我强烈建议你去找塞格占卜一下……我知道，他是个豺狼人。但是他是个非常特殊的、可以帮你占卜命运的豺狼人！$B$B我们也在不断给马戏团增加新项目以保持吸引力！"
D.Strings[9494]="好吧，$c，听我说。我的实际年龄比外表所显示出来的更大，我还拥有超越年龄的智慧。你最好别怀疑我所说的。\n\n当然，若是你不相信我的话呢，就去看看城镇中招贴的公告牌吧。每张上面都写着我的名字！$b$b不过嘛，标有“通缉”字样的公告牌请直接无视吧。我向你保证，那只是误会。"
D.Strings[9495]="$c，你好。我正在向巴德拉克讨教驾驭狮鹫的窍门。真希望有一天我能拥有自己的狮鹫棚。"
D.Strings[9496]="狗在哪里？"
D.Strings[9497]="你能帮我找到我的狗吗？"
D.Strings[9498]="我好想它啊！"
D.Strings[9499]="人们总是希望在旅店或是这样的节日聚会上找到艳遇，我非常理解这种想法。但是酒精会让人的感官变得迟钝，让你忘却生计的艰辛。$B$B不过，我找到了解决方法！通过很多次的试验和磨难，我设计出一种特别的装置！只要戴上这些护目镜，所有人都会变得魅力十足！$B$B嗯……包括你，美人！怎么样，我还可以给你打折！"
D.Strings[9500]="吉安娜女士让我来和你谈谈关于乘坐狮鹫调查奥卡兹岛的事。"
D.Strings[9501]="事情会变成什么样呢……"
D.Strings[9502]="我想要喝一杯。"
D.Strings[9503]="我听说你的厨艺很不错。"
D.Strings[9504]="啊，我的厨艺吗？应该是吧。作为女招待，当然总得在厨房里跑来跑去的。我确实学到了一些新的菜谱，虽然不是很特殊，但至少可以填饱葛罗克那无底洞一样的胃。"
D.Strings[9505]="我还想学习更多。"
D.Strings[9506]="很抱歉，$n，但是我已经没有什么可以教你的了。当然，说不定哪天我灵光一闪，就发明出新菜谱啦，所以不要忘了经常回来看看！"
D.Strings[9507]="我的兄弟克里克斯觉得他在奥格瑞玛的工作很糟糕。但和这个地方的恶臭比较起来，那算得了什么？不过至少老板还付给我额外的危险津贴！\n\n什么？你想知道飞艇在哪里？你很幸运，我正好带着我的飞艇追踪器！"
D.Strings[9508]="保持警惕。尘泥沼泽中强敌四伏，我们担负着构筑塞拉摩岛第一道防线的重任。"
D.Strings[9509]="去往格罗姆高的飞艇目前在哪里？"
D.Strings[9510]="目前逃亡者占领了废弃哨塔，所以北点哨塔成为距离塞拉摩岛最远的岗哨。"
D.Strings[9511]="这一次，你不会有机会再进监狱了！"
D.Strings[9512]="你是说巴德手下的探险队？$b$b他对任何人都一视同仁的。只要你会用铁铲，他就会雇佣你。$b$b呃……除非你是亡灵。巴德讨厌他们。不过我认为他是害怕亡灵。"
D.Strings[9513]="这家伙是巴德手下的一名探险队员吧，他是什么人？"
D.Strings[9514]="嗯，我很有本事呢。你要我帮你什么啊？"
D.Strings[9515]="$c，要我帮忙吗？"
D.Strings[9516]="你是来掠夺战利品的么？去排队候着吧！$b$b我的那份还没有到手呢……"
D.Strings[9517]="孩子，你可难倒了我。我跟探险队的成员不熟。$b$b这些巨魔烈酒我已经喝腻了，就盼着巴德许诺的财宝呢……"
D.Strings[9518]="这帮家伙真有意思……"
D.Strings[9519]="是啊，你永远不会知道下一个入伙的家伙是谁，也不会知道下一个因此事而丧命的家伙是谁。$b$b我的建议么，就是不要和任何人扯上关系。"
D.Strings[9520]="说得没错。巴德纠集了形形色色的酒鬼。$b$b似乎只要能喝到免费的美酒，这帮家伙就会抛开彼此的差异与分歧，聚到一起来。"
D.Strings[9521]="哎呀！那是什么味道？"
D.Strings[9522]="<闻了闻身上的气味，然后退了一步>$b$b$c，这就是冒险的味道！"
D.Strings[9523]="<嗝儿>听好了，$r。不如你也去和那些野蛮的巨魔扭打一番，然后闻闻自己身上的味儿！"
D.Strings[9524]="瞧，这营地附近只有兽人烈酒而已。$b$b我可不喜欢喝这种酒，你懂我的意思吧……"
D.Strings[9525]="詹姆斯？詹姆斯……不，你不是詹姆斯，但我知道你是谁……"
D.Strings[9526]="你就是追踪那帮野蛮的渣滓，替我们报仇的英雄。"
D.Strings[9527]="我千方百计地想要告诉吉姆……想要告诉所有人……谁才是幕后黑手，可惜始终没有机会……"
D.Strings[9528]="谢谢你为吉姆和我们所做的一切。如果你遇见吉姆，请告诉他我和小吉米始终爱着他，我们一直在等他回家。"
D.Strings[9529]="妈妈，我们什么时候能再见到爸爸？"
D.Strings[9530]="吉米，我也不知道我们何时才能与你爸爸重逢。但你要知道，他爱你，无时无刻都在思念你。"
D.Strings[9531]="哦……见鬼，让我换个绷……带！"
D.Strings[9532]="这样或许可以延缓感染的速度。"
D.Strings[9533]="欢迎来到警戒哨岗，$c。"
D.Strings[9534]="湮远而艰辛的探索到此为止，真正的正义者将由命运择示。"
D.Strings[9535]="我的躯体健壮而纯洁！现在，让我来治愈你们这帮阴暗的灵魂吧。"
D.Strings[9536]="听着，朋友！$b$b我会把我知道的一切都告诉你，但你得先把我从这个恐怖的地方救出去！$b$b怎么样？"
D.Strings[9537]="布洛格很感激收留他的泥链镇地精，不过有时他觉得地精们在嘲笑自己。"
D.Strings[9538]="我想要输入神秘兑换码以获得我的鱼人服装。"
D.Strings[9539]="啊哈！坦扎尔自由啦！$b$b我真走运！竟然毫发未伤。$b$b朋友，我是被命运之神眷顾的幸运儿。是啦。肯定是这样。"
D.Strings[9540]="我从未到过这么冷的地方，$r。就算是没有冰雪覆盖，在诺森德的冰荒废土上行走还是异常艰难。"
D.Strings[9541]="你……好似有点面熟。我以前在哪儿见过你吗？"
D.Strings[9542]="我认识你吗？"
D.Strings[9543]="让我给你一个忠告吧：永远不要信任侏儒。"
D.Strings[9544]="给我再来点酒，笨蛋。"
D.Strings[9545]="好吧，朋友，我告诉你……$b$b那晚我们潜入祖阿曼，想要一探究竟。$b$b夜色寂静，突然传来一阵微风掠过树叶般的飒飒声。没等我们回过神来，就被这帮野蛮的巨魔和他们的宠物包围了！等我醒来的时候已经是次日，我发现自己被囚禁在牢笼中。$b$b日复一日，囚犯们接二连三地惨遭毒手。每杀死一名囚犯，那名熊巨魔的力量就增加一些。$b$b朋友，我对祖阿曼的了解仅限于此。我也不想知道更多了！"
D.Strings[9546]="等我长大以后，我要当一个马夫！"
D.Strings[9547]="这旅馆可是在北边那些野蛮人觉醒之前就建起来了。至少，感谢圣光！$B$B你在这里会呆很久吗？"
D.Strings[9548]="我想看看你卖的货物，哈吉尔。"
D.Strings[9549]="*嗝儿*酒精……和毒药……*嗝儿*都是很……危险的……"
D.Strings[9550]="我需要一些材料，苏雷。"
D.Strings[9551]="<巴德见你走近，眼珠子一转。>$b$b哟，这不是即将成名的$n么！$b$b您大驾光临真是我的荣幸啊！"
D.Strings[9552]="好啦，$n，放轻松点，做个深呼吸吧。你要相信我。$b$b你缺乏处理这类情况的经验，才会搞得惊惶失措。心理上的恐惧感往往会夸大事实。所以啦，根本不存在什么危机。$b$b我说，你不要这么消极嘛。这会影响到整个探险队的士气……"
D.Strings[9553]="你可以在塔贝萨的房中找到学徒加里奥。至少，他没法偷走那儿的所有材料。"
D.Strings[9554]="要是有牧师或是德鲁伊在就好了。在康复之前，我没法继续研究工作了。"
D.Strings[9555]="等等，莫非……你是$n，对吧？$b$b我能为你做些什么吗？"
D.Strings[9556]="哦，那要看你所说的“伙伴”是谁。这些年来来往往的人可多啦，唯有巴德·奈德雷克还保持着追寻历史传说的热诚！$b$b大部分人在收获财富之后都隐退了。不过我不会选择这样的道路。我始终觉得，我的使命就是揭开世间神秘事物的面纱。哎，我不去做的话，还有谁肯担起这个差事呢？"
D.Strings[9557]="啊，他们呀——悲惨的结局。$b$b探险队进入祖阿曼已有数日，至今音信全无。$b$b类似的情形我也见得多了，这帮被名誉和财富冲昏了头脑的蠢货。我警告过他们，没有做好充分的准备就别贸然涉险，可惜他们压根儿没听进去……"
D.Strings[9558]="听着，$n，聪明的话就别放弃唾手可得的财富。这种好事不是每天都能碰上的！$b$b那么，$c，你愿意加入探险队吗？$b$b<巴德没等你答话便继续开口。>$b$b你显然是愿意啦！还有很多工作要做呢，你这家伙废话不少，却没有一点实质行动嘛。你最好做出点成绩给我看，不然我就找人顶替你的位置。$b$b我敢打赌，这样的机遇不知道有多少人垂涎呢！"
D.Strings[9559]="喂喂！我们被那群该死的海盗给堵在海湾里了！$B$B朝他们丢炸弹，看能不能帮我们出去？$B$B我们偷来的飞艇就在那边，趁它起航之前跳上去！"
D.Strings[9560]="喂喂！我们被那群该死的海盗给堵在海湾里了！$B$B朝他们丢炸弹，看能不能帮我们出去？$B$B我们偷来的飞艇在$3078w分钟后就要起航了。趁它起飞之前跳上去！"
D.Strings[9561]="喂喂！我们被那群该死的海盗给堵在海湾里了！$B$B朝他们丢炸弹，看能不能帮我们出去？$B$B我们偷来的飞艇就在那里……我都听见它的声音了！趁它起航之前跳上去！"
D.Strings[9562]="我是个囚犯！$B$B这帮混蛋把我美丽的飞艇从天上打了下来。你知道这是为什么吗？就因为我帮部落运输了一些士兵和补给物资！这算什么新鲜事嘛！真是的！$B$B现在他们逼我开着飞艇在海湾上巡逻，帮他们轰炸海盗。现在飞艇的零件短缺得厉害，她随时都有坠毁的危险！我几乎靠口水和绳子才能保证她不散架！$B$B你要是出了什么事，我可不负责，不过你最好趁她起航前跳上去。$B$B我跟你说，这是违法的！"
D.Strings[9563]="我是个囚犯！$B$B这帮混蛋把我美丽的飞艇从天上打了下来。你知道这是为什么吗？就因为我帮部落运输了一些士兵和补给物资！这算什么新鲜事嘛！真是的！$B$B现在他们逼我开着飞艇在海湾上巡逻，帮他们轰炸海盗。现在飞艇的零件短缺得厉害，她随时都有坠毁的危险！我几乎靠口水和绳子才能保证她不散架！$B$B如果你愿意帮忙的话，就去那边候着吧。她在1分钟之内就会入港。$B$B我跟你说，这是违法的！"
D.Strings[9564]="我是个囚犯！$B$B这帮混蛋把我美丽的飞艇从天上打了下来。你知道这是为什么吗？就因为我帮部落运输了一些士兵和补给物资！这算什么新鲜事嘛！真是的！$B$B现在他们逼我开着飞艇在海湾上巡逻，帮他们轰炸海盗。现在飞艇的零件短缺得厉害，她随时都有坠毁的危险！我几乎靠口水和绳子才能保证她不散架！$B$B如果你愿意帮忙的话，就去那边候着吧。她在$3078w分钟之内就会入港。$B$B我跟你说，这是违法的！"
D.Strings[9565]="$n，要有耐心。若是我像你这般草率行事，也就不会成名了。$b$b做好最后的准备工作，祖阿曼的财富和秘密很快就属于我啦！$b$b<巴德看了看你，轻声地笑了。>$b$b……哎呀，我是说属于我们俩啦。"
D.Strings[9566]="监护员！那个坏人是来吃我们的吗？"
D.Strings[9567]="要是我爸爸活着的话，他会把火灭掉的！"
D.Strings[9568]="要是我妈妈活着的话，她会把火灭掉的！"
D.Strings[9569]="管你是谁，给我滚远点！女巫岭属于我……属于我！"
D.Strings[9570]="庄园……下一个牺牲者……很快就会被吞噬……"
D.Strings[9571]="黑暗……堕落……悄无声息地侵蚀了大地……"
D.Strings[9572]="陌生人，你来这儿做什么？你会堕入痛苦的深渊！落得和我们一样的下场……"
D.Strings[9573]="黑暗将吞噬一切……生命……"
D.Strings[9574]="对加尔来说太晚了……它的控制力太强大了……"
D.Strings[9575]="我的工作就是日夜不停地制造弹药或是给弓换弦。$B$B你需要帮助吗？"
D.Strings[9576]="听着，$c，我知道你和你的朋友非常熟悉艾泽拉斯世界。你们一定遇见过好些渴求名望和财富的家伙。$b$b如果有谁对祖阿曼感兴趣的话，记得介绍给我认识哟，我会酬谢你的。"
D.Strings[9577]="在你们这些可怜的种族踏足这里之前，这片土地就属于我了！"
D.Strings[9578]="所有胆敢冒险进入这里的家伙都会成为我的财产，你也一样！"
D.Strings[9579]="他逃走了？万岁！"
D.Strings[9580]="在远古魔法的作用下，这场森林大火绵延燃烧了数年都不曾熄灭。这里本是始祖龙女王及其配偶的栖息地。$B$B然而，某个早已被遗忘的邪恶种族已经觉醒，并企图再次奴役始祖龙女王的后裔，让它们为自己服务。$B$B这些维库人最近在灰烬龙巢附近频频滋事，严重威胁到你们的安危。"
D.Strings[9581]="这块公告板被热砂集团派驻泥链镇的代表用来张贴悬赏和工作通知。"
D.Strings[9582]="我觉得德拉兹特根本找不到有能力杀死那头迅猛龙的人。我的意思是说，他已经两次提升赏金了……"
D.Strings[9583]="继续射击！阻挡他们的援军！"
D.Strings[9584]="掩护射击！"
D.Strings[9585]="将他们从主力部队中孤立出来！"
D.Strings[9586]="探险队使用的伪装都准备好了吗？"
D.Strings[9587]="事实上！他们向我提出了所有我能做到的改进建议。我简直不能想像什么地方会有问题。$b$b好吧，$c，拿上这个。我做了一些的修改——一些很小很小的修改。现在没有任何失败的借口了！"
D.Strings[9588]="说什么呢！$b$b我只是想铲除邪恶势力啊，你应该知道，这种事情肯定要付出代价的嘛。$b$b$n，换个角度来想吧。我这是为普通人谋福利，让他们有机会成为世人瞩目的英雄！多么难得的机遇呀！$b$b你只需让他们来这儿找我，剩下的事就交给我来应付好了……"
D.Strings[9589]="你最好站远点。剖鱼是件肮脏的活。"
D.Strings[9590]="这些是幽暗城送来的最后10份药剂样本……可它们毫无价值！"
D.Strings[9591]="这样叫我怎么研究！我需要一份能在这种气候下存活的药剂样本！"
D.Strings[9592]="幽暗城的药剂样本原本已经取得了一些进展。但是不知道怎么回事，突然又不行了！"
D.Strings[9593]="皇家药剂师协会欢迎你来到诺森德，$c。你愿意为我们伟大的希尔瓦娜斯女王陛下做些什么呢？"
D.Strings[9594]="%s显得非常虚弱，可以捕捉了！"
D.Strings[9595]="这里的情况比我想象的糟得多！飞艇并不比一堆扭曲的金属和燃烧的燃料好多少！"
D.Strings[9596]="谢谢你！真不知道那些野蛮人会怎么对付我。"
D.Strings[9597]="欢迎来到塞拉摩，$c。"
D.Strings[9598]="射手，列队准备！"
D.Strings[9599]="听我的命令！准备，瞄准……"
D.Strings[9600]="射击！"
D.Strings[9601]="这些炮弹每天都会被打到斯克恩或是地平线那边的某些地方去，但你知道为什么晚上又会回到这里吗？$B$B炮弹回收任务！$B$B但这工作跟我的合约完全不对口，你知道吗？"
D.Strings[9602]="休息会吧，小甜甜，要不要来点吃的，放松放松？$B$B这里就你最需要休息啦。"
D.Strings[9603]="有什么吃的，塞蕾丝？"
D.Strings[9604]="除非有紧急事务，否则我没有太多时间与你闲聊，公民。我肩负着保卫塞拉摩的重要使命。"
D.Strings[9605]="艾登中尉总是自愿地承担起驻守城门的重任。我对此没什么意见。$b$b我喜欢呆在岗哨，既能看到手下的侍卫，还能欣赏商人的女儿。"
D.Strings[9606]="你是来换班的吗？时间刚刚好呢。如果你愿意换班的话，我就能喝上两杯啦。"
D.Strings[9607]="感谢圣光，迪菲亚的那帮家伙对潜水一窍不通。"
D.Strings[9608]="你就不能挑个更好的时候来吗！我们赶紧离开这里。"
D.Strings[9609]="好了，我们走吧……但别忘记给联盟留下点终身难忘的东西！"
D.Strings[9610]="这座营地的补给物资有限。真要出什么差错的话，他们就完蛋了。"
D.Strings[9611]="亚当斯上尉派我来调查哈尔格林德到底发生了什么事。我以这座被废弃的维库人哨塔为掩护，费了好大的工夫，最多只能靠到这么近了。$B$B被遗忘者一定在秘密策划着什么。我感觉得到！"
D.Strings[9612]="啊，对……看着它烧个精光！"
D.Strings[9613]="我们离成功很近了！"
D.Strings[9614]="你们这帮联盟的渣滓，尝尝药剂师的厉害吧！"
D.Strings[9615]="我们赶紧逃离这里吧！"
D.Strings[9616]="别动手！是药剂师！"
D.Strings[9617]="我们欠你的情，朋友。与复仇港的雷杉德尔谈谈吧，他会给你一份适当的酬劳。"
D.Strings[9618]="啊哈哈哈哈！我要挖掘出真相！"
D.Strings[9619]="人们只要专注于研究和挖掘，他们就能发现真相。"
D.Strings[9620]="我们安全了，它不会追到这里的！"
D.Strings[9621]="它来了！快躲起来！"
D.Strings[9622]="如果时间再充裕一点就好了！"
D.Strings[9623]="原谅我吧，伟大的主！我不是故意要挖掘真相的。"
D.Strings[9624]="既然你已经知道了真相，我就更不能让你离开了！"
D.Strings[9625]="一切即将结束。接受那位不可名状之存在的拥抱吧！"
D.Strings[9626]="入侵者！你是来杀我们的吧！"
D.Strings[9627]="你不能走……不能让它找到我们！"
D.Strings[9628]="你在这里，那么它肯定就在后面不远处！"
D.Strings[9629]="在你了解到这恐怖的真相之前，我要结束你的生命！"
D.Strings[9630]="现在你必须加入我们了……永远地！"
D.Strings[9631]="欢迎来到塞拉摩。"
D.Strings[9632]="$c，今天你想学习哪些附魔公式？"
D.Strings[9633]="今天我是不是可以为你展示一两张新图样？"
D.Strings[9634]="很高兴见到你，$c。"
D.Strings[9635]="暗月卡片共有八套：野兽、祝福、元素、报复、愚人、入口、风暴和督军，每套卡片各有八张。如果你能集齐一套八张卡片，就能用一副暗月套牌在萨杜斯·帕雷教授处兑换到强大的饰品。"
D.Strings[9636]="无头骑士正在村子里到处放火！我们必须要保护孩子们！"
D.Strings[9637]="无头骑士来了！快一点，帮助你们的部落同胞保卫村庄！"
D.Strings[9638]="无头骑士暂时被击退了。我们可以稍微松口气，但是仍然不能掉以轻心。"
D.Strings[9639]="万圣节是个可怕的节日，但我喜欢！"
D.Strings[9640]="发生了什么事？"
D.Strings[9641]="我想回孤儿院去！"
D.Strings[9642]="朋友，你好。欢迎光临外域最精彩的盛会！$B$B来，尽情体验我们精心准备的节目吧。瞧瞧这些新奇玩意儿，它们是暗月马戏团从这个广袤而神秘的世界中收集来的！我们会尽力为孩子们带来欢乐！"
D.Strings[9643]="欢迎来到塞拉摩，$c。你在找什么？"
D.Strings[9644]="你看起来是个非常明智的人。为什么不来读一读这份传单并谈谈你的想法呢？"
D.Strings[9645]="真不该把主力部队留在瓦加德。都是凯勒中将那个自大狂的错！$B$B现在手头就这么点人，我们怎么执行任务？这里的要塞需要驻军，维德瓦堡垒也需要部队！$B$B不过你既然来了，或许我们需要担心的就能少一些啦。"
D.Strings[9646]="我按照上尉的意思，提供了针对部分决策的参考意见，但是我觉得他更想听听你的看法。"
D.Strings[9647]="这么多张嘴要喂，谁来喂？我！$B$B做饭、洗碗，还有买菜什么的全都是我在做！"
D.Strings[9648]="……逃亡者内衣对折出售？这是什么玩意儿？"
D.Strings[9649]="……逃亡者能尽情享受游泳与喂狗的乐趣？可笑！"
D.Strings[9650]="这些年来，我从来没想过还能看见这样的新疆界。$B$B只是，这里已经被邪恶玷污，亘古流传的知识也被掩埋了。"
D.Strings[9651]="我也算得上是经历丰富吧，可这次探险者协会在低语峡谷的遭遇还是超出了我的想象。$B$B能从那里逃生，我真是万幸！"
D.Strings[9652]="……逃亡者要建立一个新的塞拉摩岛，所有的城民都能为所欲为？这是什么狗屁？"
D.Strings[9653]="……把小鸡绘在塞拉摩岛的旗帜上？！这些家伙是不是疯了！"
D.Strings[9654]="……建立一笔基金来购买发胶？算了吧，我喜欢我现在的发型！"
D.Strings[9655]="牛头人酋长每小时都会登台表演一次。提起精神来吧，让吟游诗人激发他们的灵感，将这盛会吟唱成令人难忘的诗篇！"
D.Strings[9656]="啧啧。尊重你的长者。卡亚特才是你的导师。"
D.Strings[9657]="我所掌握的裁缝技能非常有限，已经没有什么可以教你的了。在无尽之海的另一边，暴风城的法师区中有一位伟大的裁缝。他名叫乔吉奥·波利罗，我想由他来做你的导师比较合适。去那儿和他谈谈吧。"
D.Strings[9658]="嗤！感受燃烧的烈焰吧！"
D.Strings[9659]="布洛格，我记得我们谈过这个问题。你不能待在房间里。当然啦，你是可以塞进去，不过其他人就没空间了！"
D.Strings[9660]="你说过布洛格可以待在这里的！你许诺过会帮助布洛格夺回石槌氏族的土地！"
D.Strings[9661]="是，我们是说过你可以待在这儿，但是这间房子是我们的总部！所有的手册和蓝图都存放在里面！"
D.Strings[9662]="但这是唯一适合布洛格的房子，地精的房子都太小太小啦！"
D.Strings[9663]="我想说，食人魔的体型也太大了吧！好吧，我打消说服你挪动地方的念头，不过这只是暂时的！"
D.Strings[9664]="地面……已经完全结冰了。我们只能傻傻地坐在这里，这些绞肉车哪里都不能去。"
D.Strings[9665]="高级执行官安希尔姆要求你立刻报告情况。"
D.Strings[9666]="这也太可怕了吧？这地面简直冻得跟岩石一样硬！$B$B你瞧，这些轮子之前还是陷在烂泥里，现在和泥土冻成一块了！恐怕得叫个憎恶用铁链将它们拖出来。"
D.Strings[9667]="我绝不会把蕨墙村当作自己的家。那么做就等于放弃了收复失地的希望。"
D.Strings[9668]="地精杂烩煲"
D.Strings[9669]="钓鱼椅"
D.Strings[9670]="幽灵虎坐骑"
D.Strings[9671]="好吧，$r，算我欠你情啦。$b$b在你出现之前，我还以为这是我最后一口酒呢。"
D.Strings[9672]="那么，一个像你这样的矮人到底是怎样沦落到这里的呢？"
D.Strings[9673]="那是个伤心的故事——还有几分尴尬。$b$b矮人嗜酒如命可是众所周知的事。我自然也不例外，而且我对美酒的喜爱程度完全超越了我的想象。$b$b就这样，我遇见了巴德。他说只要我愿意加入探险队，就能尽情享受所有的美酒。我经受不了诱惑，做出了令我后悔至今的决定。$b$b那天晚上，我喝下足以放倒一头科多兽的烈酒之后，跟随巴德的杂牌探险队进入了祖阿曼。$b$b待我清醒时，发现自己已经沦为囚犯了。"
D.Strings[9674]="噢，谢谢你帮我逃离了牢笼我被囚禁了好久那里闻起来就像被太阳曝晒了一周的碎羊肉但是呢我很讨厌羊肉因为我在很小很小的时候被变成了一头羊而且长达一分钟因此我很清楚做羊的滋味所以我自然不希望被吃掉尤其是被打扮得像猫的大巨魔吃掉……$b$b<阿什莉深深地吸了一口气。>$b$b我的发型没乱吧？"
D.Strings[9675]="进退两难的联盟水手想必已经明白他们难逃一死，却选择了负隅顽抗。$B$B真是可悲可叹啊。"
D.Strings[9676]="击败荒弃海岸的联盟只是时间问题。他们已经被包围了，而且我们还占有数量优势。"
D.Strings[9677]="希尔瓦娜斯的意志在上，我们的敌人终将失败。"
D.Strings[9678]="高级执行官安希尔姆要求你立刻报到。"
D.Strings[9679]="就是城墙上的那两尊大炮延缓了我们的攻城速度。要是没有它们的保护，城墙上的守军早就会被我们杀得丢下要塞仓皇逃命去了。$B$B现在我们有两个选择，摧毁那些大炮，或者等他们弹药消耗完。就看安希尔姆怎么决定吧。"
D.Strings[9680]="无头骑士本是白银之手的成员，可惜这位昔日的英雄被诅咒了。他盘踞在血色修道院中，失去理智的无头骑士竟然认为自己还活着，我们才是没有生命的亡者。$B$B他再也不是圣光忠诚的仆从了。随着万圣节的来临，他在艾泽拉斯世界各地的村落中散播着阴暗的种子，还有那仇恨的火焰。"
D.Strings[9681]="把你们的灵魂给我，帮助我消灭敌人！"
D.Strings[9682]="自由啦！克拉斯的痛苦结束了。$b$b谢谢你，$c。"
D.Strings[9683]="克拉斯就不该来这个鬼地方……不该相信人类。我真是个大傻瓜，$c，你莫非也是听信了巴德的鬼话来进来的？$b$b我的儿子已经失踪两个月了，据说有人最后一次看见他是和巴德在一起。巴德说我或许可以在祖阿曼中找到他的下落……$b$b我跟着探险队来到这里，然后沦为俘虏。要不是你帮忙，我肯定没命了。$b$b陌生人，谢谢你。"
D.Strings[9684]="成功了！我们打败了泰瑟尔！"
D.Strings[9685]="过来暖和暖和，让你那一身疲倦的骨头歇歇。我们很好客的。"
D.Strings[9686]="你已经无法阻止我了！我们的王，马上就要苏醒了！"
D.Strings[9687]="求你了，带我离开这里！"
D.Strings[9688]="钥匙……你得先找到钥匙！"
D.Strings[9689]="我好像在那些维库人身上见过钥匙。"
D.Strings[9690]="我不要被他们拖进下面的墓穴！"
D.Strings[9691]="我不要成为祭品！"
D.Strings[9692]="他们正在下面的墓穴中举行邪恶的仪式，我马上就要变成他们的祭品了！"
D.Strings[9693]="有没有英雄来救我啊？"
D.Strings[9694]="这就是一切的结束。"
D.Strings[9695]="噢，谢谢你，谢谢你！"
D.Strings[9696]="谢谢你，我永远不会忘记你的恩情！"
D.Strings[9697]="为那些沦为祭品的朋友复仇！"
D.Strings[9698]="你必须阻止这疯狂的一切，否则就来不及了！"
D.Strings[9699]="谢谢你，英雄！"
D.Strings[9700]="必须消灭那些邪恶的维库人！"
D.Strings[9701]="你救了我的命！"
D.Strings[9702]="太感谢你了！"
D.Strings[9703]="遵循圣光为你照亮的道路吧，孩子。"
D.Strings[9704]="火，赐予我洞察……"
D.Strings[9705]="弓箭手准备！瞄准！"
D.Strings[9706]="哪个蠢货竟敢不经觐见就擅自闯入陛下的领域？"
D.Strings[9707]="水，赐予我宁静……"
D.Strings[9708]="但是，你闯入了主上的领域。就凭僭越入侵这一点，他就有权处决你！阿尔萨斯大人对那些逃跑的奴隶没有任何的怜悯与仁慈！"
D.Strings[9709]="%s吸入了从火炉中腾起的轻烟。"
D.Strings[9710]="但是……他已经得知了你们战胜暴风城北方舰队的消息，并且相信你们有足够的潜力，能够明察事理并抛弃希尔瓦娜斯幼稚的复仇理论。"
D.Strings[9711]="谢谢你们，万物之灵。"
D.Strings[9712]="阿尔萨斯准备赐予你力量，超乎你想象的力量。比起以后你将领导的天灾军团来说，眼下你手中的军队简直脆弱得可笑。"
D.Strings[9713]="这就是你要说的？"
D.Strings[9714]="把这些渣滓都赶下地狱！开火！"
D.Strings[9715]="$g先生:女士;！我负责保护你的安全。$B$B请下令吧！"
D.Strings[9716]="这些年来，我一直处于迷失的混沌中。现在，我终于看到自己的灵魂变得有多么黑暗……"
D.Strings[9717]="为了伊米隆国王！"
D.Strings[9718]="千万小心那些维库人！这是一个嗜血而凶残的种族，每日所想不过是征伐与杀戮。更何况，他们已经向巫妖王宣誓效忠！维库人在附近建立了多处定居点，他们的人数几乎是你们的5倍。"
D.Strings[9719]="做出选择吧，安希尔姆。回到巫妖王的军队，与天灾军团并肩作战或者对你所谓的女王保持忠诚，直到天灾军团将你驱出他们的家园！"
D.Strings[9720]="Aranal ledel! 他们的命运归你们处置！"
D.Strings[9721]="别这么快。"
D.Strings[9722]="我要你的血！"
D.Strings[9723]="%s清了清嗓子。"
D.Strings[9724]="每一次我望向这个基地时，唯一能看到……就是恐惧……等到天灾军团占领了铁炉堡或是暴风城以后，你们还会感到恐惧吗？不！不会了！知道为什么吗？因为那时候你们早已没命了。"
D.Strings[9725]="如果你感觉脊椎下传来阵阵凉意，甚至有尿裤子的冲动，倒是应该感到欣慰。让这种感觉刺激你的情绪吧。恐惧是唯一能让你保持呼吸的情感。"
D.Strings[9726]="我说得够清楚了吧？你们听明白没？我可不想再送更多的棺材或者阵亡通知单回去了。"
D.Strings[9727]="南瓜头冒出了邪恶的烟雾……"
D.Strings[9728]="召唤无头骑士。"
D.Strings[9729]="你们竟如此渴望将我灭亡。可却不知，首级还在，我便可避过一切灾殃！"
D.Strings[9730]="瞧你这丧气的模样。"
D.Strings[9731]="快点，$c！$b$b这场危机快要失控了。"
D.Strings[9732]="这绝不是你最后一次看见我。等乌特加德的大军将你践踏至渣后，我还会回来朝你的尸体吐口水！"
D.Strings[9733]="我要吸取你们的灵魂，我要听你们临死前的哀号！"
D.Strings[9734]="你需要长途旅行么，$n？我的蝙蝠会很快把你送到目的地的。"
D.Strings[9735]="我需要飞往风行者号。紧急军务！"
D.Strings[9736]="脚下小心，$r。$b$b你绝不会是第一个死在这里的人。"
D.Strings[9737]="这些联盟蛤蟆真是太讨厌了！居然还敢登上满员的被遗忘者驱逐舰……这真是我听过的最愚蠢的自杀方式。"
D.Strings[9738]="你以为我不知道你想干什么吗？你以为我没有在观察着你的一举一动吗？"
D.Strings[9739]="你不可能阻止我完成升华仪式，卑微的$r。去死吧！"
D.Strings[9740]="不可能！你不可能击败我！"
D.Strings[9741]="我和姐妹们都欢迎您造访，$R。"
D.Strings[9742]="太不走运了，哈尔弗丹。"
D.Strings[9743]="哈尔弗丹，你没有资格获得升华。你的灵魂将坠入湮灭的深渊！"
D.Strings[9744]="对敌军舰队的测试报告出来了，长官！"
D.Strings[9745]="呃……好消息是增援部队撤退了。"
D.Strings[9746]="这种药剂效力不是非常……强。但是，目前已知的有害效果包括晕眩、平衡感丧失和剧烈的胃痛。"
D.Strings[9747]="很好。那么结果如何呢？"
D.Strings[9748]="直说吧！坏消息是什么？"
D.Strings[9749]="保持警惕，$n。$b$b我们还没有走出这片森林呢……"
D.Strings[9750]="我们是皇家药剂师协会的成员！药剂引起胃痛不在我们的工作范围之内！"
D.Strings[9751]="你们都是业余的吗？明天早上，我要见到一份完整的分析报告！拉维恩，给我做事去！"
D.Strings[9752]="你好，陌生人。如果你是在找一处用武之地，那么恭喜你，你找到了。$B$B那些亡者从坟墓中爬出来，在大地上游荡，并乘着船飘洋过海来到这里。峡湾的局势越来越严峻了，再这样下去，我们就不得不往北逃亡了。"
D.Strings[9753]="我是来此协助与保护你的。$B$B接下来我们要如何打击敌军呢？"
D.Strings[9754]="过来点，年轻人，我的耳朵已经不那么好用了，说话声音也不如以前洪亮了。"
D.Strings[9755]="上尉，我弄丢了指挥官徽记。"
D.Strings[9756]="灰烬图腾酋长，我弄丢了你给我的徽章。"
D.Strings[9757]="你这家伙真令我作呕！"
D.Strings[9758]="看看这是谁来了。"
D.Strings[9759]="你的生命到此结束！"
D.Strings[9760]="我要把你碾碎！"
D.Strings[9761]="你的种族就是世界的污点！"
D.Strings[9762]="只能祈祷治疗方案能生效了。"
D.Strings[9763]="我根本没有能治疗你们的药品和器械。"
D.Strings[9764]="别担心，士兵。亚米娜会照顾好你的。"
D.Strings[9765]="我需要搭乘巨型蝙蝠去拦截联盟援军。"
D.Strings[9766]="这是怎么了！"
D.Strings[9767]="谁把那只蝙蝠给我打下来！"
D.Strings[9768]="感觉有点不对劲…"
D.Strings[9769]="这液体……真是难闻！"
D.Strings[9770]="现在，让我来告诉你们什么叫……数量优势。"
D.Strings[9771]="药剂的用途如此广泛，我们得加紧研究！"
D.Strings[9772]="这些都非常不错。非要从中选一个的话，真有点难以做决定。"
D.Strings[9773]="很好，我找到合适的号角啦。现在我要开始雕刻了，这恐怕会很难。我根本没听过雌雪人的叫声！"
D.Strings[9774]="我已经把大部分基础图案雕刻好了，在完成雕刻之前需要测试一下。你愿意帮我测试吗，$n？"
D.Strings[9775]="贡纳·索瓦德森在此！拿命来！"
D.Strings[9776]="蔑冬的敌人，你们很快就会被撕成碎片！"
D.Strings[9777]="把这些蝼蚁赶出维库人的家园！"
D.Strings[9778]="你就是那个打扰我吃晚餐的家伙吗？是你吗？"
D.Strings[9779]="你也算是雌雪人吗？又丑又不丰满！你快让我抓狂了……"
D.Strings[9780]="真高兴见到你！$B$B要做的工作还有很多，我们的时间偏偏不多了。"
D.Strings[9781]="戈斯从来不怕战死。被遗忘者只要把我重新拼起来就行了。"
D.Strings[9782]="戈斯有时候也很迷茫。戈斯是个好杀手，所以升到了中士。但戈斯很不习惯没有东西杀的日子！"
D.Strings[9783]="维库人身材高大，也比我们强壮。但！我们比他们长得帅！"
D.Strings[9784]="雷管5000型超级大炮是一种代表世界最尖端技术水平的单人发射装置，它能以龙的速度将人发射出去。发明该设施的地精家族是家喻户晓的航空领域先驱，这种超级大炮已经成为了家族的荣耀！$B$B如果你想象鸟儿一样在空中翱翔，就去沙塔斯城的圣光广场找玛克希玛·雷管吧。她会把你发射到城外的小池塘去！"
D.Strings[9785]="鲜美的脑！"
D.Strings[9786]="好……饿……呀……"
D.Strings[9787]="饿死我了……"
D.Strings[9788]="肉！吃了你！"
D.Strings[9789]="过来……再过来点……"
D.Strings[9790]="啊！火焰般的光芒！！！"
D.Strings[9791]="啊呀呀呀……"
D.Strings[9792]="圣光……明亮的圣光……"
D.Strings[9793]="该死的光……好痛……"
D.Strings[9794]="走开……滚……"
D.Strings[9795]="或许我们选择靠近裂木森林和亚勒伯龙的道路是个错误。"
D.Strings[9796]="滚回寒冷的黑暗中去吧！"
D.Strings[9797]="瞧你这花拳秀腿的！"
D.Strings[9798]="你训练的时候怎么跟睡着了一样。"
D.Strings[9799]="要是那帮小东西敢杀进来，我可不会像跟你对练的时候那样克制。"
D.Strings[9800]="老太太，要不要休息一下啊？"
D.Strings[9801]="你的拳头缺乏力道！"
D.Strings[9802]="不管你是练还是不练，都得满地找牙！"
D.Strings[9803]="来呀，你倒是给我一拳啊！"
D.Strings[9804]="我一生戎马，经历过无数战争的洗礼。我曾在不同的旗帜下作战，不过那都是别人的战争。$B$B这次却截然不同了。这些被遗忘者士兵来这里的理由都只有一个。阿尔萨斯必须死。"
D.Strings[9805]="饿了吗？你还可以在这里睡觉哦。"
D.Strings[9806]="保持警惕，$r，我们已经被亡灵包围了。"
D.Strings[9807]="谢谢你，陌生人。"
D.Strings[9808]="我必须回去，祝你狩猎愉快。"
D.Strings[9809]="愿天地间的精魂永远保佑你。"
D.Strings[9810]="你救了我的命。我欠你一份情。"
D.Strings[9811]="我们不应该穿越裂木森林的。是个人都该明白这点！"
D.Strings[9812]="这里到处都是幽魂。小心！"
D.Strings[9813]="他们将我们分别关押起来。我敢肯定还有其他的幸存者。"
D.Strings[9814]="我欠你一条命，陌生人。"
D.Strings[9815]="等一等……"
D.Strings[9816]="这只是……"
D.Strings[9817]="啤酒！只是啤酒而已！"
D.Strings[9818]="这酒真是稀松平常，毫无新意。"
D.Strings[9819]="你！不许告诉葛瑞克！听到没有？"
D.Strings[9820]="灵魂，到我这里来！"
D.Strings[9821]="我经不起派特洛夫的说辞，居然同意跟着一帮无能的矮人到了这里。"
D.Strings[9822]="[维库人土语] Bjorns mottar haelgond sygar！"
D.Strings[9823]="你竟敢辱骂我的妈妈！"
D.Strings[9824]="相比起来，药剂师更强调实践吧。毕竟我们在负责后勤工作的。$B$B这并不代表我们的理论基础知识不够扎实。我们只是……做实事而已。"
D.Strings[9825]="你见过无头骑士吗？要是他到这里来的话，我会和他战斗，然后偷走他的南瓜！"
D.Strings[9826]="我喜欢在大水桶里划水，但是他们说那不是给孩子们玩的。"
D.Strings[9827]="他们说这些水桶是灭火用的。你是个消防队员吗？"
D.Strings[9828]="无头骑士与其他令人毛骨悚然的鬼魂和人类一起住在血色修道院。"
D.Strings[9829]="他们正在旅店里分发糖果！守护者格雷沃基说要是他们不给我们糖果……我们就去和他们捣乱！"
D.Strings[9830]="你见过无头骑士吗？守护者格雷沃基说，如果他出现了的话，千万不要看他，否则他会把我变成南瓜！"
D.Strings[9831]="你可以在大水桶里打满一桶水。泼水真有趣！"
D.Strings[9832]="我看到暴风城来的士兵们在灭火。他们是英雄！"
D.Strings[9833]="无头骑士居住在血色修道院。有时候他会出来吓唬小孩子，但我不怕！"
D.Strings[9834]="我从旅店那里得到了一些糖果！不过我还想要更多！"
D.Strings[9835]="%s显得非常虚弱！"
D.Strings[9836]="谢谢你。我还以为我再也见不到我的姐妹啦！"
D.Strings[9837]="我在哪里？发生了什么事？是你……救了我？"
D.Strings[9838]="我就知道鲁莉尔蕾会派人来救我的！谢谢你，朋友，也帮我谢谢鲁莉尔蕾！"
D.Strings[9839]="$c，谢谢你。$b$b要是有什么事我能帮上忙的，尽管开口。"
D.Strings[9840]="探险者协会允许我跟他们一起来真是太好了。但是裂木森林和周边区域实在是太危险，我没带帮手就闯了进来，真是蠢到家了。"
D.Strings[9841]="无头骑士很可怕，但我一点都不害怕！一点也不害怕！"
D.Strings[9842]="无头骑士落荒而逃了！"
D.Strings[9843]="要是他回来了，你会再去和他战斗吗？"
D.Strings[9844]="我希望我能有个像你一样的$g爸爸:妈妈;！"
D.Strings[9845]="蔑冬部族必胜！"
D.Strings[9846]="将入侵者驱逐出去！为安格博达女王而战！"
D.Strings[9847]="勇敢地战斗吧，瓦格里会奖赏你的！"
D.Strings[9848]="别打哑谜了！"
D.Strings[9849]="把这些东西拼起来可真够难的！"
D.Strings[9850]="足骨……连接到髋骨！髋骨再……再连接到这里好了！嗯嗯……"
D.Strings[9851]="我弄丢了座狼伪装服。"
D.Strings[9852]="怎么会弄丢呢？好吧好吧，别再弄丢了。"
D.Strings[9853]="调配失败的混合物溅到了地板上，呈现出了奇特的生命迹象！"
D.Strings[9854]="我会很想念冬蹄营地的，但是我能理解灰烬图腾酋长做出的决定。我们没有能力永远维持家园这个温暖的港湾。"
D.Strings[9855]="%s完全丧失了自控能力，开始无差别地攻击朋友和敌人！"
D.Strings[9856]="嘿，你没看见我正要喝酒吗？"
D.Strings[9857]="很好，这个就行。我觉着……嗝儿。"
D.Strings[9858]="掠龙维库囚犯感到不适。"
D.Strings[9859]="小心我的钢锯，它会让你看到很多内在的东西，不是吗？"
D.Strings[9860]="哎哟，真恶心！"
D.Strings[9861]="怎么会这样！"
D.Strings[9862]="我很不舒服。"
D.Strings[9863]="嘿，放松点！"
D.Strings[9864]="你哪里不舒服？"
D.Strings[9865]="他们竟然能做出那样的事。"
D.Strings[9866]="真……特别。"
D.Strings[9867]="那是被遗忘者最新研制的药剂？！"
D.Strings[9868]="它是活的！"
D.Strings[9869]="药剂！它动了！"
D.Strings[9870]="%s转身面对着你。"
D.Strings[9871]="嗯……？"
D.Strings[9872]="呀。"
D.Strings[9873]="他没事吧？"
D.Strings[9874]="这可不太好。"
D.Strings[9875]="有意思。"
D.Strings[9876]="哇。"
D.Strings[9877]="入侵者！警报！"
D.Strings[9878]="格雷尔，我需要一匹狮鹫和一些炸弹来轰炸新阿加曼德！"
D.Strings[9879]="拿去吧。好好利用这些武器！"
D.Strings[9880]="我们也被诅咒了吗？"
D.Strings[9881]="%s指着那个婴儿。"
D.Strings[9882]="%s呜咽着。"
D.Strings[9883]="神灵抛弃了我们！我们必须在伊米隆国王发现之前处理掉它！"
D.Strings[9884]="不！你不能这样！求你了！这是我们的孩子啊！"
D.Strings[9885]="那要怎么办？一旦他们发现了这个畸形的胎儿，我们就会被处死。"
D.Strings[9886]="我……我会把它藏起来，直到我为它找到一个家，一个远离这里的家……"
D.Strings[9887]="尊贵的伊米隆国王，万岁！"
D.Strings[9888]="绝不能对畸形儿心存怜悯！"
D.Strings[9889]="我的国王，手下留情！那是我们的骨肉啊！"
D.Strings[9890]="它们是祸害！维库人的力量会因它们的存在而削弱！杀掉它们！"
D.Strings[9891]="%s要求大家安静下来。"
D.Strings[9892]="维库人，国王恳请你们安静下来！"
D.Strings[9893]="人群在惊惶中骚动起来。"
D.Strings[9894]="在最黑暗的时刻，他们依然不忘嘲笑我们！"
D.Strings[9895]="在我们最需要泰坦指引的时候，他们又在哪儿呢？氏族诞生了畸形的胎儿，它们面貌丑陋，甚至无法站立！又丑又弱……一无是处……"
D.Strings[9896]="伊米隆身心疲惫。自从我坐上王位，就一直在思考为什么维库人的生活如此艰难。答案只有一个……只有一个……"
D.Strings[9897]="除了泰坦，还有谁能对我们下这样的诅咒？谁能拥有那样的力量？"
D.Strings[9898]="没有……是泰坦诅咒了我们！"
D.Strings[9899]="今天，所有的维库人都将抛弃过去的信仰！废除我们曾经信奉的神灵！维库人将效忠伊米隆国王！伊米隆会保护我们的！"
D.Strings[9900]="人群欢呼起来。"
D.Strings[9901]="现在，我颁布第一道法令！所有维库人畸形婴儿一出生就要立即被处死！我们必须保证血统的纯正！违抗伊米隆国王的法令的维库人将被带往亚勒伯龙处决！"
D.Strings[9902]="%s咧嘴一笑。"
D.Strings[9903]="萨满的精魂将你带来了这里……我能感应到空气中涌动着那种力量。*巫妖王大笑起来* 我也曾是个萨满祭司。"
D.Strings[9904]="不，我的仆从。这一个还没有准备好。"
D.Strings[9905]="你感觉到了吗，凡人？死亡之力从我的每一寸皮肤上渗透出来，覆盖了所有我碰触过的事物。只要我的手指轻轻一触，你的灵魂就将在诅咒中永远地凋零消逝。"
D.Strings[9906]="但……现在还不是让你为巫妖王效力的时候。是的，更伟大的命运还在等待着你。力量……在你为我效劳之前，你必须获得更多的力量。"
D.Strings[9907]="看仔细了，瓦格里。看我如何施压。你瞧，它还没有成熟呢。接着它就会爆裂，毫无生气地陨落。"
D.Strings[9908]="需要为您准备好一切吗？"
D.Strings[9909]="当然。我是在附近一具矮人的尸体上找到的。"
D.Strings[9910]="看好了，我有许多新招，比如变个熊……"
D.Strings[9911]="没人能逃过猎鹰的眼睛！"
D.Strings[9912]="现在来见识一下我的尖牙和利爪吧！"
D.Strings[9913]="遮天的龙鹰降临了！"
D.Strings[9914]="烈火会烧光你们！"
D.Strings[9915]="就算我倒下了……阿曼尼帝国……绝不会消亡……"
D.Strings[9916]="你们……永远无法消灭……我的灵魂！"
D.Strings[9917]="你们什么也得不到！"
D.Strings[9918]="我是猎鹰，而你们，就是猎物！"
D.Strings[9919]="你们所做的一切不过是浪费我的时间！"
D.Strings[9920]="让我猜猜，你是巴德派来的另一队乌合之众吧？$b$b$r，趁你还没受伤——甚至送命之前离开这里吧。"
D.Strings[9921]="嗨！我是最优秀的赛羊手，这并不代表我就乐意帮助那些酿酒商。你高兴的话，你去帮他们好了。$B$B等等，我还没说完呢！$B$B你要是能帮到酿酒商，就有机会骑上世界上最好的赛羊！"
D.Strings[9922]="接下来，我会帮你雕刻符文，它拥有支配巨人的力量。"
D.Strings[9923]="我省掉了代表“北面”和“西面”的符文，因为我还不确定它们会对巨人产生怎样的影响。而且，我还添加了限制控制时间的符文。"
D.Strings[9924]="瞧，命令符文……希望能起作用。它并不没有铁矮人那股邪恶的气息，却同样具备操纵巨人的能力。"
D.Strings[9925]="啊哈哈哈，瞧见了吗？格里伏塔回来了！我带着一堆古董回到了熟悉的货摊前，而且我已经准备好和你做买卖了！$b$b想要变得更健壮更强大更矫健吗？我出售的护身符都具备这些功能哟。来吧，掏钱买个绝世珍宝吧！破盘价啦！"
D.Strings[9926]="又有入侵者，敲响警钟！"
D.Strings[9927]="黑暗的岁月可以促成奇怪的友谊。如果能去旧洛丹伦，观看被遗忘者们烧毁稻草人的话也挺不错的。"
D.Strings[9928]="这个节日原本是部落发明的，不是联盟。真不明白我们为什么也要庆祝。"
D.Strings[9929]="我们这是在庆祝谁摆脱了谁的束缚？呸，管他呢？！我要更多的糖果！"
D.Strings[9930]="为什么每个人都不停地说侏儒只想要更多的糖果？！"
D.Strings[9931]="我说，免费的糖果真是个赔钱的买卖。呃……或许它们只是招揽顾客的减价货呢……糖果诱使你进入旅店，接下来你就要花钱吃肉啦。太棒了！"
D.Strings[9932]="万圣节结束后我们就要打碎所有的南瓜。那将会是我最开心的日子！"
D.Strings[9933]="退一步说，庆祝另一位死敌的诞辰真是件诡异的事。不过，我们还是会参加盟友们的节日。"
D.Strings[9934]="被遗忘者有权庆祝自己重获自由。还有什么比这更重要的吗？"
D.Strings[9935]="被遗忘者每晚都会焚毁一个巨大的稻草人，真不明白这样做的意义何在，不过我们的仪式在他们眼中应该也很奇怪。"
D.Strings[9936]="万圣节期间，被遗忘者每晚都会焚毁一个稻草人。真不明白他们为什么不烧真人，不过这大概是他们的节日传统吧。"
D.Strings[9937]="我们在万圣节上狂欢，纪念女妖之王将我们从巫妖王和天灾军团的魔掌中解救出来。每晚在幽暗城外都会举办稻草人晚会，记得参加哦。"
D.Strings[9938]="你知道……我们为什么要庆祝这个节日吗？"
D.Strings[9939]="我们的被遗忘者同盟在每年的这个时候都要举办重要的庆典。"
D.Strings[9940]="我们一定得参加下次的稻草人焚烧祭典。"
D.Strings[9941]="还有其它的旅店可以捣乱的吗？"
D.Strings[9942]="让这个变态的夜晚去见鬼吧。不过，糖倒是真不错。"
D.Strings[9943]="被遗忘者一定要庆祝他们重获自由！"
D.Strings[9944]="真该发明个侏儒夹心软糖啥的……"
D.Strings[9945]="肯·定·有什么办法能趁这节日的时候发上一笔！"
D.Strings[9946]="旅店老板们居然免费发糖，真是疯了。"
D.Strings[9947]="陌生人，你们很快就将步入死亡。你们根本不该来到这里……"
D.Strings[9948]="兄弟们，复活吧！"
D.Strings[9949]="铁领主交给我们一项任务！"
D.Strings[9950]="跟着我进入山岭，执行主人的计划！"
D.Strings[9951]="这些珍贵的器物都是我的客户指名预订的呢。$b$b$c，只要你能帮我找回来，我是绝对不会亏待你的，我懂你的心思啦。$B$B我们来谈谈今天的订单如何？"
D.Strings[9952]="玛哈杜恩听见虚空风中传来的低语声。$B$B有人来到玛哈杜恩面前，谈论起今天的猎物。"
D.Strings[9953]="我们不会失败！"
D.Strings[9954]="孩子，看来你相当自信哦？如果你能在竞技场中占一席之地，我倒是可以送你点什么。是相当不错的东西呢，比克里希的那些破玩意儿好多啦。$b$b祝你好运。"
D.Strings[9955]="为了联盟！"
D.Strings[9956]="我的钱呢？我的酒呢？我的脚呢？"
D.Strings[9957]="噗嗤！我是一个小侏儒！而且……，我没有主……呃，算了……"
D.Strings[9958]="绝望吧！看着我的章鱼脸，绝望吧！可笑的艾泽拉斯人！"
D.Strings[9959]="大脑……大脑脑脑！"
D.Strings[9960]="老子有了疯狂巫毒啦，哥们！"
D.Strings[9961]="为了联盟！等等……为了部落！等等，我是哪边的来着……"
D.Strings[9962]="美酒节上总是需要大量的酒桶！$B$B我会让你从我们这里借一头山羊和一根缰绳。$B$B你每给我带来一个酒桶，我就给你一些奖币，作为你给我带来酒桶的感谢，我甚至会让你更久地使用我的山羊！\n\n但是，只要你开始了，在明天以前你就不能再做了。\n\n你确定已经准备好了吗？"
D.Strings[9963]="我今天准备为你工作！给我点好酒！"
D.Strings[9964]="嗨！有什么我可以帮忙的吗？"
D.Strings[9965]="瞧，她多漂亮呀！想带她出去兜兜风吗？"
D.Strings[9966]="小声点，$c。别被他们发现了。"
D.Strings[9967]="嗨！你有兴趣知道更多关于赛羊和赛羊会的事吗？"
D.Strings[9968]="我能免费得到一匹坐骑？"
D.Strings[9969]="我要怎么样才能让山羊跑得更快些？"
D.Strings[9970]="速度有什么区别？"
D.Strings[9971]="我的山羊会筋疲力尽吗？"
D.Strings[9972]="听上去很复杂……"
D.Strings[9973]="在你接受了任务之后，我们会借给你一头山羊。只是借你而已，所以你不能永远拥有它。山羊可能看上去有点慢，不过只要甩几下缰绳，它就会加快速度。$B$B我们的山羊爱吃苹果。我们已经在一路上放了很多苹果，记得顺路吃几个。吃苹果会让你的山羊忘记疲惫。"
D.Strings[9974]="给你山羊的同时，你也同样会得到一根缰绳。这可不是什么祖传的宝贝，你得真的去使用它！$B$B甩甩缰绳就可以让它加快些速度。你的缰绳放得越松，山羊就会跑得越快。$B$B不过它跑得越快，就越容易疲劳。所以你得注意点。"
D.Strings[9975]="你只要一开始甩甩缰绳，就可以看到山羊速度的改变。它起初是步行，甩几下缰绳以后就会开始疾走，在它疾走的时候再来几下，就会开始慢跑了。在它慢跑得时候再加把劲，就可以让它飞奔起来。"
D.Strings[9976]="让你的山羊慢跑或者飞奔太久的话，它会精疲力尽。如果你想让山羊恢复，让它步行或疾走一会儿就行了。如果附近有苹果就更好了，带它去吃一点，可以更快地恢复。"
D.Strings[9977]="赛羊其实比看上去更简单，不过要掌握的话还是需要技术的。如果你能避免让你的山羊精疲力尽，你只需要用用缰绳，吃吃苹果就可以了。"
D.Strings[9978]="我曾经经历过这样的结局。这次会有新意吗？"
D.Strings[9979]="嗯？这是什么？$B$B别浪费时间！"
D.Strings[9980]="我特意为你留着这个呢！"
D.Strings[9981]="一切正在按照计划进行着，法库雷斯特公爵。我向你保证，这只是时间问题。"
D.Strings[9982]="我想你应该是带来了什么好消息吧？"
D.Strings[9983]="如果你有足够多的美酒节奖券，美酒节营地的奖券兑换员就可以给你一个“荣誉酿酒商”的戳印。$b$b有了那个戳印，我就可以卖给你一头美酒节赛羊。不过我要提醒你，它们可并不便宜！"
D.Strings[9984]="这里是我们辛辛苦苦用双手建设起来的！朋友，它凝聚着我们的血和泪。$B$B相信我，我们绝对不会放弃瓦加德。"
D.Strings[9985]="嘿，朋友，我拿来的这个东西可以说是一个伟大的成就，一件你从未看到过的东西！不过现在你可以买到它，可以非常便宜地买到它！$B$B你知道，我已经厌倦了花钱在酒馆里找寻完美的人。所以我做了这个东西……这副眼镜可以让每个人看上去都是那么完美无缺。你可别错过这种好东西！$B$B那么，你想试试吗？让我的口袋里多一点钱？既然你看上去那么完美，我会给你打折的！"
D.Strings[9986]="我看到你在街对面闲逛，就满心希望你可以到这边来。那么，甜心，有什么需要我为你效劳的？"
D.Strings[9987]="你的疯狂眼镜有什么用？"
D.Strings[9988]="正常的狗根本不敢靠近我。当我发现这点时深受打击……我其实是很喜欢动物的。$B$B天灾犬是不错的替代品。当然，它们的模样……并不好看。但你知道吗，我的相貌也好看不到哪儿去！"
D.Strings[9989]="嗨，朋友，你想试试全世界最好的酒吗？"
D.Strings[9990]="孵化者呢？快去孵蛋！"
D.Strings[9991]="这里是练习灭火技术的地方，为了被遗忘者！"
D.Strings[9992]="我败了！弟兄们，别害怕！没有谁能将你们赶出岩石熔炉！"
D.Strings[9993]="%s在临死前扭动着身躯，发出痛苦的呼喊声。"
D.Strings[9994]="要令这些意志脆弱的外来者屈服真是太容易了。"
D.Strings[9995]="很好！你还活着。我又有乐子咯！"
D.Strings[9996]="这帮家伙体型不大，意志倒是强硬得多嘛。"
D.Strings[9997]="$n的混合剂被毁坏了！必须重做一瓶。"
D.Strings[9998]="<乌尔芬低声嚎叫，嗅了嗅你身上的气味；接着你就明白了他的语言。>$B$B北方那头名叫迦瓦尔的白色座狼带走了我的狼群。我要割断他的喉咙，重新成为群族的首领。"
D.Strings[9999]="在剃刀岭和这里之间发生的坠毁事故把酿造流程搞的一塌糊涂！但那也不能改变黑铁矮人几乎每小时一次的进攻！$B$B如果你想帮忙的话，那么这样，我会让你从我们这里借一头山羊和一根缰绳。$B$B你每给我带来一个酒桶，我就给你些奖币，作为你给我带来酒桶的感谢，我甚至会让你更久地使用我的山羊！\n\n但是，只要你开始了，在明天以前你就不能再做了。\n\n你确定已经准备好了吗？"
D.Strings[10000]="我看到你在欣赏我们合法拥有的赛羊……我能感觉到，你想要参加赛羊会……不过在你参与之前，你必须得做些事。$B$B嗯，对于这些山羊来说，工作和玩其实是一样的。"
D.Strings[10001]="他们将工具放在这样的箱子里。去营帐附近找找看。"
D.Strings[10002]="我们设立这个地方就是为了练习灭火。你永远都无法预知村子什么时候会有危险。"
D.Strings[10003]="喂，你！干嘛呢，勤快点！$B$B没看到这里人人都忙着么，你这个饭桶！"
D.Strings[10004]="朋友，瞧你那副得意忘形的模样！你是不是从哪个富商那儿抢到什么好东西了？财富是要大家分享的……朋友，别小气嘛！"
D.Strings[10005]="瞧那边！那蠢货把农夫给惹火了。这下麻烦了吧，我看他的小命难保啦。"
D.Strings[10006]="为骡子钉上马蹄铁要花多少钱啊？"
D.Strings[10007]="我们不负责给骡子钉马蹄铁。准确地说，那是远征队的事儿。"
D.Strings[10008]="你完全不了解状况！如果我不赶紧出发的话，好的建筑用地都会被别人抢先霸占啦！"
D.Strings[10009]="这又不是我的问题！如果你这么着急建房子的话，就在要塞里建好了，省得你整天抱怨！"
D.Strings[10010]="朋友，我说的是实话！北海海盗是世界上最强硬的海盗。$B$B你最好不要惹事。算啦！反正所有的白痴海盗都会被处死！"
D.Strings[10011]="你能不能从我的熔炉旁滚开……"
D.Strings[10012]="那，那是头骡子！"
D.Strings[10013]="嗯……那是什么？"
D.Strings[10014]="朋友，你这样就很无耻了。你是想惹我发火是吧？滚，你这个懦弱的海盗。明天再见！"
D.Strings[10015]="欢迎来到维德瓦堡垒！瞧，那片土地等着你去占领呢！"
D.Strings[10016]="是啊，诺森德的环境极其恶劣，但是我们拥有强壮的体魄和勇敢的精神，能面对一切挑战！"
D.Strings[10017]="我们要用刀剑夺得这片土地的所有权，然后用犁来开垦荒地！而你们，将作为拓荒的先驱者，被后世传颂。"
D.Strings[10018]="你们并不孤单。我们特意准备了一群骡子，运送你们所需的补给物资。"
D.Strings[10019]="斧头、锄头、种子、钉子、食物、毯子、水……任凭你们挑选。价格非常合理哟。"
D.Strings[10020]="我的物资供应非常充足。如果你们还需要其它的货物，欢迎随时来找我！"
D.Strings[10021]="我忠诚的顾客，呃……朋友们，来吧，征服这片土地！"
D.Strings[10022]="你是新来的吧，瞧你那副自以为是的模样。$B$B<索雷克朝地上吐了口唾沫。>$B$B肯定是……"
D.Strings[10023]="我不太懂艺术……但是我知道自己喜欢什么！"
D.Strings[10024]="朋友，你瞧，谁敢欺负我的朋友，我就让他没好果子吃！"
D.Strings[10025]="<老冰鳞在沙地上画画，希望你能从粗糙的图案上看出他是在企求你的帮助。>"
D.Strings[10026]="一切都结束啦，伙计！"
D.Strings[10027]="祖尔金……会给你们惊喜的……"
D.Strings[10028]="你们没有时间啦！"
D.Strings[10029]="烧死你们！"
D.Strings[10030]="风之圣魂将是你的梦魇！"
D.Strings[10031]="亲爱的，我们得找到一块带温泉的好地方。"
D.Strings[10032]="当然啦，亲爱的。"
D.Strings[10033]="我可不希望在咱们的土地上遇见恐怖的狼、巨人或是丑陋的山羊。"
D.Strings[10034]="你说得对，亲爱的。不过在庄稼成熟之前，咱们还不得靠羊肉维持生计……"
D.Strings[10035]="我宁可屠宰那些骡子！我说，你为什么不带些牲畜来呢？"
D.Strings[10036]="亲爱的，我宁可听骡子叫也不愿意听你讲话。"
D.Strings[10037]="在利爪与尖牙面前，下跪吧，祈祷吧，颤栗吧！"
D.Strings[10038]="你没可能胜过这伟大的战力！"
D.Strings[10039]="你们注定要失败！"
D.Strings[10040]="我要把你撕碎！"
D.Strings[10041]="你将死无全尸！"
D.Strings[10042]="你竟敢向蔑冬部族宣战？！我要用那面旗帜刺穿你的身体！"
D.Strings[10043]="啧啧，祭品自己送上门来了？你脑子坏掉了吧？"
D.Strings[10044]="我要拿你的尸体去喂匕鞘湾的鲨鱼！"
D.Strings[10045]="<老冰鳞警惕地盯着你，他漫不经心地晃动着脑袋，眨巴着死鱼眼。>"
D.Strings[10046]="美酒节来啦！"
D.Strings[10047]="没有什么节日比得上美酒节的美食和美酒！"
D.Strings[10048]="陌生人，我说你还是回去吧。$b$b这里不是供你游历的风景地。它会摧毁你的躯体，嚼碎你的骨头。"
D.Strings[10049]="上面那些亚勒伯龙维库人身上就有钥匙。"
D.Strings[10050]="这只巨大的南瓜灯矗立在村子的中央。"
D.Strings[10051]="南瓜被打碎了，不过没有更多的财宝了。"
D.Strings[10052]="打碎南瓜就能得到隐藏的财宝！这真是太棒了！"
D.Strings[10053]="不要告诉我，你没有多余的缰绳了……"
D.Strings[10054]="看什么看？哈哈……开个玩笑嘛！"
D.Strings[10055]="和好朋友坐在一起分享美酒，还有什么能比得上这样的惬意呢……嗝儿！"
D.Strings[10056]="“耶……酒精真令人发狂呀！”等等……酒劲来没上来呢……"
D.Strings[10057]="朋友，坐下来喝一杯吧！也给我来一杯！"
D.Strings[10058]="……那个卑鄙的海盗安着两条木腿，左手是个铁钩，他还有两颗玻璃假眼和木头鼻子！"
D.Strings[10059]="啧啧，送上门来的祭品。"
D.Strings[10060]="你是来送死的吧？"
D.Strings[10061]="你也会成为巫妖王的仆从。"
D.Strings[10062]="……因此他说“我只有一颗眼珠！当然不会重影！”"
D.Strings[10063]="嗨，咱们来玩玩吧？"
D.Strings[10064]="你是为巫妖王而活的！"
D.Strings[10065]="我会让你大吃一惊的。"
D.Strings[10066]="停尸间还留着你的空位呢。"
D.Strings[10067]="亲吻炮手的女儿？为什么我总是碰不到心仪的少女……"
D.Strings[10068]="听说泰里镶个画框就能赚1000金币。或许我也该考虑做工艺品生意！"
D.Strings[10069]="新鲜的尸体。"
D.Strings[10070]="嗯？你想飞？不……这是不可能的！"
D.Strings[10071]="米克高维尔，我负责处理探险者协会的官方事宜。带我去探险者协会哨站！"
D.Strings[10072]="呸！是，我也是南海海盗的一员了——如果你想打什么鬼主意，就趁早死了这条心。信不信我现在就砍翻你！"
D.Strings[10073]="嗨，欢迎来到美酒节！"
D.Strings[10074]="你好，朋友！欢迎来到美酒节！"
D.Strings[10075]="欢迎，$c！欢迎参加铁炉堡一年一度的美酒节庆典！"
D.Strings[10076]="嗨，欢迎参加美酒节。过来喝上几杯吧！"
D.Strings[10077]="怎么了，朋友？欢迎来到美酒节！现在就去买些酒喝喝吧！"
D.Strings[10078]="嗨，$c！欢迎来到美酒节庆典……现在尽情享受这里的美酒美食吧！"
D.Strings[10079]="呀啊啊啊！别想得到我的望远镜，你这只配滚去舱底喝污水的蠢货！"
D.Strings[10080]="维萨鲁斯放射出纯净的能量！"
D.Strings[10081]="%s开始吸取附近邪能水晶的能量。快摧毁它！"
D.Strings[10082]="欢迎来到美酒节，朋友！在赞美那些相互对抗的酿酒厂之间的友好竞争精神时，我们可以得到很多乐趣。如果你有任何疑问，找我就是了！"
D.Strings[10083]="奖币和纪念品"
D.Strings[10084]="赛羊"
D.Strings[10085]="你好，$r。我是希达尔格，擅长狩猎，算得上是一流的驯鹰大师。停在我肩膀上的就是杀人机器木丝了。$B$B你可能会想，“驯鹰师是干什么的呢？”我来告诉你——我们是优秀的猎手！训鹰术是一门利用经过特殊训练的猛禽来狩猎的艺术。你对此感兴趣吗？希达尔格可以教你！"
D.Strings[10086]="美酒节就是个享受这个世界中最好的食物和美酒的盛典，一点都不夸张。过来看看这么多清爽的手工啤酒、节日香肠、椒盐卷饼和奶酪。还有什么比这更好的呢？而且你只需要花那么一丁点钱。"
D.Strings[10087]="除了啤酒和香肠，美酒节最受欢迎的就是纪念品了！不管是传统节日的服装，还是美酒的袖珍酒桶，一切应有尽有，你可以在贝尔比这里买到各种美酒节的主题物品。记得你手上要有足够多的美酒节奖币，因为你只能用它们来购买纪念品。你可以通过在美酒节的场地附近帮忙来获取奖币。"
D.Strings[10088]="赛羊会是美酒节的一个重要传统节目。如果你想知道更多的信息，就去和羊圈旁的波尔·冻石谈谈。而且那也是获取美酒节奖币的好方法！"
D.Strings[10089]="嗨，欢迎来到美酒节！在这里你可以享受各种乐趣，如果你有任何问题的话，随时可以过来问我。不然，就去买些啤酒和椒盐卷饼吧！"
D.Strings[10090]="美酒节的意义就在于美食和美酒，而且我们所提供的就是最好的！你觉得我在撒谎？看看我们的那些美酒、香肠、椒盐卷饼和奶酪吧。你会发现，你周围都是最棒的美食，而且你找不到比这更便宜的了！"
D.Strings[10091]="每个人都喜欢那些疯狂的美酒节赛羊。想要了解更多信息吗？去和羊圈旁的德利兹·塔波奎克谈谈吧。享受一点乐趣，并获取一些美酒节奖币！"
D.Strings[10092]="嗨，记得给你自己弄些美酒节的纪念品！不管是传统节日的服装还是美酒的袖珍酒桶，应有尽有。只要去找布利克斯·菲克维特就行了，但是首先请确保你手上有着足够的美酒节奖券……因为你只能用它们来购买纪念品。你可以通过在美酒节的场地附近帮忙以获取奖券。"
D.Strings[10093]="你好，愿艾露恩之光与你同在。"
D.Strings[10094]="我非常乐意！\n\n不要在我的墓碑前哭泣，\n我不在那里，我没有长眠。\n\n我是凛冽的寒风，\n掠过诺森德的雪原。\n\n我是温柔的春雨，\n滋润着西部荒野的麦田。\n\n我是清幽的黎明，\n弥漫在荆棘谷的林间。\n\n我是雄浑的鼓声，\n飞越纳格兰的云端。\n\n我是温暖的群星，\n点缀达纳苏斯的夜晚。\n\n我是高歌的飞鸟，\n留存于美好的人间。\n\n不要在我的墓碑前哭泣，\n我不在那里，我从未长眠。"
D.Strings[10095]="我跟你说啊，猎艳的最佳方法就是保持良好的风度，还要戴上这种护目镜！"
D.Strings[10096]="<岩石猎鹰啄着你的手。>"
D.Strings[10097]="<猎鹰发出饥饿的叫声，想要吃幼虫。>"
D.Strings[10098]="<喂食岩石猎鹰。>"
D.Strings[10099]="“朋友”，你最好埋下头！希望你懂我的意思！$B$B耶！"
D.Strings[10100]="亲爱的，快啦。你很快就会苏醒过来，艾泽拉斯世界将在恐惧中颤抖！"
D.Strings[10101]="苏醒吧，伊米隆国王。时机已经成熟，你很快就能重掌统治权。"
D.Strings[10102]="从沉睡中醒来吧，我的爱。有了巫妖王的支持，世界将因你而颤抖。"
D.Strings[10103]="仪式怎么要进行这么久？你的主子向我保证过，说有了你的帮助，仪式会快很多的！"
D.Strings[10104]="加倍努力！伊米隆国王很快就要苏醒了，接着他将登上王座！"
D.Strings[10105]="仪式进行得太慢啦。需要更多的祭品！"
D.Strings[10106]="不要着急，伊米隆。我对你另有安排。你先回到乌特加德之巅去，在那里更好地为我效劳。如果真有这些蝼蚁再次找上你的那一天，到时你就可以亲自为妻子复仇了。"
D.Strings[10107]="谁才是猎物啊？"
D.Strings[10108]="真容易对付……"
D.Strings[10109]="今晚我们要吃你的肉，喝你的血！"
D.Strings[10110]="我负责主持格斗比赛。你想不想赌一把啊？怎么样，有信心吗？但是——谁敢搞贿赂选手的猫腻，我就让他走跳板。$B$B我会亲自维持比赛的公平！"
D.Strings[10111]="与其他种族不同，血精灵的财富不仅仅局限于金币、丝绸或是宝石之类的原材料。辛多雷精妙的工艺本身就是无价的财富。"
D.Strings[10112]="塔鲁克派我来收欠款。"
D.Strings[10113]="别惹我，败狗！老子是接受过血骑士正统训练的强者！"
D.Strings[10114]="我还钱！我还钱！呀～！不要伤害我！"
D.Strings[10115]="还钱，哈瑞！"
D.Strings[10116]="“疯狗”约纳·斯特林要我整日整夜地打扫甲板。$B$B打扫甲板？！$B$B我是个法师，凭什么让我做这种杂事！就算要打扫，也该玩点新花样吧。"
D.Strings[10117]="安静点好吗？要是被人发现，我们就死定了。"
D.Strings[10118]="好吧，伙计！谁点了风味朗姆酒啊？小杰克，是你吗？"
D.Strings[10119]="没事，甜心。这杯是免费的。"
D.Strings[10120]="免费的朗姆酒？啊……这可是我的最爱！"
D.Strings[10121]="太棒了！喝得……有点……多了！"
D.Strings[10122]="<这个海盗显然是喝多了，看上去有点不省人事。>"
D.Strings[10123]="<谨慎地翻开海盗的口袋，寻找塔鲁克的欠款。>"
D.Strings[10124]="来点什么呢？朗姆酒？还是麦酒？$B$B或者你想尝尝别的？"
D.Strings[10125]="我想请杰克喝一杯。最好是……那种后劲儿特足的饮料。"
D.Strings[10126]="你想公然和杰克叫板是吗？$B$B嘿，我得说着这绝对是个……愚蠢的决定。这会让你损失惨重的。我可不想冒着丢掉小命的危险去干这种一分钱都挣不来的破事。嗯，你最好等我跑远了再动手。"
D.Strings[10127]="给，你可以用这枚金币买给自己想要的东西。"
D.Strings[10128]="当然啦，亲爱的。把它算到哈里的账上好不好呀？他欠我一杯酒呢！"
D.Strings[10129]="呀啊啊啊！想要夺得我的财宝……你要费一番功夫了！"
D.Strings[10130]="黑铁矮人进攻"
D.Strings[10131]="那些黑铁矮人简直是失心疯了，他们几乎每个小时都要来一次，打碎酒桶之后就跑掉了！$B$B也许你要问，“我为什么要关心这个呢？”$B$B那么我告诉你，他们破坏掉的都是提供免费啤酒的酒桶！没错，免费的！$B$B如果你正好遇到黑铁矮人破坏酒桶，别忘了帮我们保护这些免费的美酒！"
D.Strings[10132]="美酒节是个完美的节日！不过万事无绝对，黑铁矮人就是这个节日中的一个小麻烦。他们几乎每个小时都要来一次！$B$B他们的目标是提供免费啤酒的酒桶，而且那些啤酒还都是最棒的上等啤酒！$B$B你看，如果你正好遇到黑铁矮人破坏酒桶，别忘了帮我们保护这些免费的美酒！"
D.Strings[10133]="你死定了，旱鸭子！"
D.Strings[10134]="呀啊啊啊……又死了！"
D.Strings[10135]="你就是这样报答主子的吗？你这烂熊！啊啊啊啊啊！"
D.Strings[10136]="约纳·斯特林这个蠢货迟早要害死我们。如果他多花点时间观察局势的话，就会明白在战争期间攻击职业海军是件多么愚蠢的事。"
D.Strings[10137]="你最好快滚，$n。我不想和约纳的死扯上关系。$B$B他们还不知道我杀了以前的船长取而代之，我才能勉强坐稳头领的位置。"
D.Strings[10138]="%s吞食着主人的尸体。"
D.Strings[10139]="沧海桑田，你，还有他们……世事变幻。$B$B卡玛古因此受到威胁。你能为我们做些什么呢？"
D.Strings[10140]="我是个外行，嗯？沃尔特讲话不经过大脑吗？我独自一人就教训了那些铁矮人，还在这里搭建起营地观察挖掘场的动静。"
D.Strings[10141]="瞧，那家伙正在为地毯的事烦恼呢。"
D.Strings[10142]="晚上好。"
D.Strings[10143]="暗礁母海狮和公海狮找到了真爱。"
D.Strings[10144]="启动。"
D.Strings[10145]="士兵们，起来战斗吧！为死去的骑士带来胜利的荣耀！"
D.Strings[10146]="沃尔特派我来要一些黑铁条。"
D.Strings[10147]="呃……这么说……你打算启程返回前哨站，是吧？"
D.Strings[10148]="沃尔特的工作台可以使用了。"
D.Strings[10149]="<跳上工作台，让沃尔特将你塞进魔像中。>"
D.Strings[10150]="瞧，完美的作品！"
D.Strings[10151]="每天两次，分别是在早上6点15分和下午6点15分，大工匠梅卡托克会亲自来到美酒节的现场，主持开酒罐仪式。千万别错过！"
D.Strings[10152]="哇欧，哇欧，哇欧！伙计们，稳住！"
D.Strings[10153]="矮人们突然都大笑起来。"
D.Strings[10154]="开酒罐仪式"
D.Strings[10155]="噢，尊贵的岩石与钢铁领主，您……您打算如何处理呢 ？"
D.Strings[10156]="每天两次，分别是在早上6点15分和下午6点15分，萨鲁法尔大王会亲自来到美酒节的现场，主持开酒罐仪式。千万别错过！"
D.Strings[10157]="朋友，这行不通的。铁矮人才不会喜欢那个大家伙！"
D.Strings[10158]="雷波斯基，不懂就别折腾了！完全没有必要！那些铁矮人不会知道真相的！你不如回去调查到底是谁在你的地毯上捣鬼，这里的工作就交给真正的科学家吧！"
D.Strings[10159]="我非常伤心！就别开玩笑了！"
D.Strings[10160]="要是爸爸能活着看到这一天该多好啊！"
D.Strings[10161]="铁符文构造体U-9207无法识别你的声音。雷波斯基，现在开始摧毁你的地毯。"
D.Strings[10162]="加文·雷酒负责看管酒窖。只要他呆在地下室，这些酒桶就十分安全。"
D.Strings[10163]="我准备好了，沃尔特。"
D.Strings[10164]="系统故障。3……2……"
D.Strings[10165]="尽情享用吧，兄弟们！"
D.Strings[10166]="等等，凡人，我有话和你说。"
D.Strings[10167]="是陆地，科瓦斯基先生！港口就在前方，长官！"
D.Strings[10168]="谢谢你，亨德尔先生。"
D.Strings[10169]="梅拉先生，请你驶向港口。"
D.Strings[10170]="托格雷船长！我们即将抵达目的地，长官！"
D.Strings[10171]="谢谢你，科瓦斯基先生！你可以回去继续监督进港情况了！"
D.Strings[10172]="干得好。请把我们安全带到下一个港口吧。"
D.Strings[10173]="托格雷船长是最棒的！"
D.Strings[10174]="我在拖洗甲板！"
D.Strings[10175]="梅蕾女士号永远是最棒的船！"
D.Strings[10176]="拖洗甲板治好了我的驼背！"
D.Strings[10177]="是，是，科瓦斯基先生。"
D.Strings[10178]="形势正在发生变化，$n。战争开始了。$B$B是让我们的人民抓住机遇去帮助盟友们……还是在一旁静观局势发展呢？"
D.Strings[10179]="对不起，我没时间闲聊。"
D.Strings[10180]="没看见我正忙着吗？离我远点，别让科瓦斯基撞见了。"
D.Strings[10181]="真是个启航的好日子，对吧？"
D.Strings[10182]="在托格雷手下做事非常辛苦，不过他是位好船长。"
D.Strings[10183]="我们剩下的人不多了，$n。宿敌的回归让我们忧虑万分。"
D.Strings[10184]="我得密切注意船只和船员的情况。请原谅我不能和你闲聊。"
D.Strings[10185]="梅蕾女士号长期停靠塞拉摩岛，我们奉命保护船只上的乘客。"
D.Strings[10186]="欢迎乘坐梅蕾女士号。我是船长托格雷。$b$b我负责解答所有关于这艘船的疑问，并祝愿大家旅途愉快。就像我喜欢的座右铭那样：对我来说，船只的意义在于带你游历全世界。没有它，你就无法享受这样美妙的体验。"
D.Strings[10187]="梅蕾女士号"
D.Strings[10188]="物品和装备"
D.Strings[10189]="“鼠胆船长”？"
D.Strings[10190]="是呀，梅蕾女士号，她是一艘很漂亮的船。$b$b你知道，呆在船上能学到很多知识的。有首诗说得好：苍茫黑夜中两只落寞行船，擦身而过时互相道安，风笛长鸣，堪堪见到模糊的形，片刻后却只余远去的影；人生亦如这广阔的洋，你我的船不期中徜徉而遇，彼此仅是浅烙下容与音，即又遁入黑暗与寂静。"
D.Strings[10191]="肚子饿的话，可以找厨师长格莱斯。"
D.Strings[10192]="考布斯先生是随船的工程师和军需官，他出售各种你可能需要的物资。若是你想要修理装备的话，也可以找他哦，他技术不错的。"
D.Strings[10193]="啊，是啊……这个名字。嗯……人们常说，好名字就像美好的愿望，你需要用心经营，却很可能因一次失误前功尽弃。至于我的名字的由来嘛，不用说也知道为什么别人这么称呼我吧……"
D.Strings[10194]="亡者已经复苏，任何敢于穿越亡者领地的人都会遭到疯狂的报复。回去吧！"
D.Strings[10195]="大地开裂，神器失窃。古神之盾已经遗失。混乱将会笼罩世界。"
D.Strings[10196]="风暴愤怒法杖被盗。这片大陆遭到了诅咒！风暴永远不会停息！"
D.Strings[10197]="除非伊斯多弗的冰冷之心归位，否则它迟早会吞噬这片大陆。但凡拥有它的人，无一例外地被冰冷鲜血诅咒所困扰，为他们的痛楚默哀吧……"
D.Strings[10198]="那些试图穿上克瓦迪尔的上古甲胄的蠢货将会尝到无尽的痛苦。凡人，当心这片迷雾，你很可能丢掉性命。"
D.Strings[10199]="我真幸运。没几个牛头人能成为护卫舰的船员的！格雷兹克斯甚至让我操纵这些不可思议的战斗快艇。"
D.Strings[10200]="我没功夫和你闲聊，洛伊。带我去无赖港。"
D.Strings[10201]="维库人的怒火将吞噬你！"
D.Strings[10202]="它的能量在我体内流淌！我是神！！！"
D.Strings[10203]="阿卜杜尔像牛一样强壮！！"
D.Strings[10204]="你想挑战我？我拥有十倍于常人的力量！！！！"
D.Strings[10205]="我……需要你们的……帮助！我……快支持不住了！"
D.Strings[10206]="啊！我要疯了，快帮帮我！"
D.Strings[10207]="快！我的心志快要完全丧失了！"
D.Strings[10208]="如果我们要建造一道前往奎尔丹纳斯岛和太阳之井的传送门，就需要有足够多的强力能量资源来开启传送门。$B$B我们现在已经完成了$3269w%%。你愿意帮助我们吗，$c？"
D.Strings[10209]="这道传送门与其它连接艾泽拉斯世界的传送门不同。为了让它持续工作，我们需要有更多的法力晶格。$b$b否则我们就有可能失去通向奎尔丹纳斯岛和太阳之井的捷径。"
D.Strings[10210]="开火！开火啊，你们这群胆小的海盗！"
D.Strings[10211]="裂隙的能量是我们的！"
D.Strings[10212]="滚开，这是我们的地盘！"
D.Strings[10213]="我的！你们休想夺走这块地方！"
D.Strings[10214]="这不是给你的！滚出这里！"
D.Strings[10215]="目标确定。启动安全程序。"
D.Strings[10216]="命令接受成功。入侵者将被消灭。"
D.Strings[10217]="你好，$r。$b$b我的商店终于开张了。希望你能找到你想要的东西！"
D.Strings[10218]="你好啊，$c。$B$B这里有很多事需要帮忙，不过在我得到所有必需的补给之前，我几乎什么都帮不了你。$B$B在我开始工作之前，必须得到足够的荆刺根须，不过目前只有$3223w%%的存量。你的帮助会对我的工作进展非常重要，真的。"
D.Strings[10219]="凯尔萨斯的军队就是从这里撤退到太阳之井的。他的一些走狗仍然残留在这里，燃烧军团以最不平常的方式奖赏着他们……"
D.Strings[10220]="你有没有看到那些在岛上游荡的魔像守卫？只要对控制它们行动的水晶核心做一些小小的改动，就能让我们获得它们的控制权，用它们来保护战略要地。$b$b阳湾圣殿很快就会是我们的了，眼下我们的目标完成率已经达到了$3244w%%。"
D.Strings[10221]="我们成功地拿下了圣殿。我们可以继续转变这些魔像守卫，用它们来保护其它的战略要地。"
D.Strings[10222]="喂！伙计，你想要预订慈悲修女号的座位？你找对地方啦……"
D.Strings[10223]="我们必须确保不会再有谁葬身大海。"
D.Strings[10224]="开火！亲爱的，为了财宝，开火吧！"
D.Strings[10225]="有人或许能风光一辈子，但是总不可能在死后也为所欲为吧！开火！"
D.Strings[10226]="$c，请原谅，我必须专心工作。"
D.Strings[10227]="很多人葬身大海。我和小精灵负责在海面上搜寻灵魂。"
D.Strings[10228]="索罗夫的财宝掉在了地上。"
D.Strings[10229]="我和小精灵守护着那些迷失的灵魂。"
D.Strings[10230]="海洋是个危险的地方，$c。我们必须保持警惕。"
D.Strings[10231]="我现在恐怕不能和你谈话。"
D.Strings[10232]="啊哈哈哈，来一瓶侏儒烈酒庆祝一下！"
D.Strings[10233]="一炮轰成渣啊！"
D.Strings[10234]="尽情享受美酒和女人！"
D.Strings[10235]="受死吧，旱鸭子！"
D.Strings[10236]="财宝属于我们！"
D.Strings[10237]="纳鲁祝福你，我的朋友。"
D.Strings[10238]="我这边的行动倒不是很频繁。在战区中如此靠近前线，真是紧张刺激。"
D.Strings[10239]="说到行动，我接到命令，要去发动一次空袭。"
D.Strings[10240]="占领阳湾圣殿是我们战斗计划的第一步。下一步是要控制军械库。$b$b我们的目标完成率已经达到百分之$3233w了。"
D.Strings[10241]="我们已经夺取了军械库的控制权，但我们在岛上的工作还没有完成。"
D.Strings[10242]="我的任务是在死亡之痕吸引敌人的注意力，这样我们的军队就可以拿下阳湾军械库了。虽然听上去并不像和恶魔直接交锋那么吸引人，但如果这能让我们赢下这场战争，那我一定会全力去做。$B$B我们的目标完成率已经达到了百分之$3233w。"
D.Strings[10243]="我们已经夺下了军械库，$n。尽管如此，我们仍然不能沾沾自喜，满足现状。燃烧军团不会就此停下他们的脚步。"
D.Strings[10244]="我们的努力得到了回报。我们已经占领了阳湾圣殿，$n。去那里看看有什么可以帮忙的吧。"
D.Strings[10245]="武装圣殿的防御结界可以让我们更快地占领它。我们不希望在全力攻击燃烧军团和凯尔萨斯时还要为失心者的偷袭操心。$B$B我们的目标完成率已经达到$3244w%%了。"
D.Strings[10246]="勇者号上的水手将竭诚为你提供温馨舒适的服务。"
D.Strings[10247]="不好意思，我们还是另找时间谈吧。再见。"
D.Strings[10248]="欢迎乘坐勇者号。不好意思，失陪……"
D.Strings[10249]="我有点嫉妒维瓦·水歌了。为什么？他比我更优秀！"
D.Strings[10250]="对水手来说，这是个不幸的名字，是吗？"
D.Strings[10251]="欢迎回来，$n。"
D.Strings[10252]="他大概是年纪最大、最有经验的水手了吧，他的体格最强壮！嗯？嗯？和食人魔一样粗壮的手臂！"
D.Strings[10253]="我们发誓要全力保卫勇者号乘客。必须确保鲁瑟兰村至暴风城港口航道的安全。"
D.Strings[10254]="嗨，孩子。欢迎乘坐少女之爱号。我是维克诺兹船长，能与黑水海盗一起航行是你的荣幸。血帆海盗根本不敢靠近，因为我们有最精锐的水手，货舱里还堆放着大量火药。你知道，所谓安全保障嘛。$b$b如果你有有疑问，尽管来问我好了。"
D.Strings[10255]="少女之爱号"
D.Strings[10256]="这就是少女之爱号。她很漂亮，是吧？不久前，公爵委派我担任这艘船的船长。她本不属于我，因此“少女之爱”这个名字不是我取的。我猜为她取名的水手大概是在海上航行太久了，没能好好享受港口的美妙时光。你懂我的意思吗？"
D.Strings[10257]="如果你的肚子饿得咕咕叫，就去找厨师长拜雷·钢胃谈谈，可别说是我告诉你的这家伙的名字可是有来历的……"
D.Strings[10258]="热砂港的船只怎可能没有工程师呢？托克斯宾德出售所有你需要的物品。如果你想要修理物品的话，他的技术也不错哟。"
D.Strings[10259]="欢迎乘坐羽月渡船号。我们往返于羽月要塞和被遗忘的海岸，搜寻不幸的落水者。大海暗藏危机，你必须做好充分的准备。$b$b你可以和食物供给商谈谈，购买足够的干粮。他们会很乐意帮忙的。"
D.Strings[10260]="我代表月海之浪号的全体船员欢迎你,\127$c。希望在起航之前，我们的食物供应商能帮你准备好一切。"
D.Strings[10261]="搭乘艾露恩的祝福号时请保持警惕，$r。虽然艾露恩保佑我们找到了新的盟友，但是深不可测的海洋依然危机四伏。$B$B但是，在月神的感召下，我们承担起搜寻失落灵魂的重任。"
D.Strings[10262]="在航海之旅中，艾露恩一直庇护着我们。但是我们仍然要保持警惕，$c。"
D.Strings[10263]="不好意思，$r，我必须专心工作。"
D.Strings[10264]="对不起，除了与小精灵交流并向船长汇报我的发现之外，我没时间和其他人闲聊。请原谅。"
D.Strings[10265]="欢迎乘坐少女之爱号。她将载你安全驶往港口。"
D.Strings[10266]="如果你狠狠地捏一个侏儒，是可以学到很多东西的：比如说逃脱的小伎俩，制作美味的曲奇饼干，甚至可以学到如何制造飞行器。"
D.Strings[10267]="我一有空就会这么做。感觉非常不错，同时也能让我把握他们的心思——照我的经验来说，通常没什么好事。"
D.Strings[10268]="风筝"
D.Strings[10269]="火箭鸡"
D.Strings[10270]="纸飞机"
D.Strings[10271]="嗯……如果那个讨厌的船长向你推销他的特价品，你就直接把那些烂货扔进海里去。说不定有些龙虾人会因此丧命，不过好在你能捡回一条命呀。"
D.Strings[10272]="你好，$r。$B$B让我们开动起来！根本不要指望那些也许永远都到不了的补给。$B$B我需要一块铁砧才能为我们的军队提供装备，但是现在只完成了$3228w%%。$b$b等铁砧完成之后，我就可以为你锻造许多强大的武器装备了。"
D.Strings[10273]="你好，$n。$b$b我已经造好了铁砧，可以开始装备我们的军队了。这一步对我们来说非常重要，不过仍然有许多事需要去做。$B$B对你来说更重要的是：我可以制造新的武器装备了！也许你会对此感兴趣。"
D.Strings[10274]="我们已经拿下了港口，这艘船真的算是个不错的奖励。只不过她还不适合航海。$B$B对了，我得到命令去监视绿鳃海岸一带的纳迦。$B$B你觉得你能帮帮我吗？"
D.Strings[10275]="我必须阻止晨锋部队的增援。"
D.Strings[10276]="欢迎登上唤雷号！$b$b不用理会那群整天抱怨爆炸或者类似东西的家伙。真的，每个人都会犯错误，我们应该开除掉一些懒惰的家伙。$b$b你看，我知道如果有一个船长的船坠毁了22还是23次是有点……但任何少于那个次数的事故就根本算不得什么了。"
D.Strings[10277]="<抱怨> 那些山都不知道从哪里钻出来的……五次都是突然出现！"
D.Strings[10278]="<抱怨> 你可能会觉得让一艘飞艇撞进海里挺困难的，但是前后发生了四次就更不可思议了！"
D.Strings[10279]="<抱怨> 我真希望我们能设法避免坠入湖中。我真希望我们只坠入湖中一次……但实际上，我们先后坠入四面湖中，其中还包括洛丹米尔湖！"
D.Strings[10280]="很幸运，那些松树枝看上去并没有怎么伤到飞艇。$b$b不过那也不是我们三次坠毁在森林里的借口。"
D.Strings[10281]="我从未想过我能看见泰达希尔……我也的确没想到我们会坠入泰达希尔。"
D.Strings[10282]="现在我们已经成功地穿越雷霆崖两次了！"
D.Strings[10283]="<抱怨> 我真不知道为什么我们能毫发无损地穿过千针石林的那一大堆石柱，最后却坠毁在闪光平原上！"
D.Strings[10284]="如果你喜欢刺激，那可是我们船长最擅长的事了！我爱这份工作！"
D.Strings[10285]="不要多问……"
D.Strings[10286]="你不能把我们的坏运气都怪在我的头上吧……我甚至都不知道我要去哪！$b$b尽管也许那意思是说你能责怪我……$b$b不！等等！我能把这艘船完好的停进港口的……但那肯定是船长发出的命令！也许他喜欢挑战我们的极限来测试我们的生存能力还有修理技术。"
D.Strings[10287]="我的名字曾经是埃欧罗，这是我的故事：有一天，村子里进行了一场秘密的投票，最终那次投票导致我改变了自己的名字。他们让我选择是改名字还是像考尔奇一样。要是你的话，你也会这么做的吧。你觉得我的新名字怎么样？有很大的改进，对吧？$b$b对了，如果你在找活干的话，去布告栏那里看看吧。"
D.Strings[10288]="西边出现龙鹰！把那个$c打下来！"
D.Strings[10289]="破碎残阳的垃圾！随意开火！"
D.Strings[10290]="盯着恶魔。我们今天不是来消灭那些亡灵天灾的。"
D.Strings[10291]="新兵们，你们好。我是教官巴尔杜姆。在接下来的几天内，你们会接受我的训练。"
D.Strings[10292]="凯尔萨斯·逐日者王子的军队占领了奎尔丹纳斯岛。先前的情报表明他已经死了，但情报错了。"
D.Strings[10293]="他和他的恶魔同伴们正在高地上设法重新点燃太阳井，打开一道裂缝，把他们的首领基尔加丹重新召唤回这个世界。"
D.Strings[10294]="我们的任务是在支援上头派来的特种部队的同时，尽可能多的消灭凯尔萨斯的手下。"
D.Strings[10295]="不用说也知道，我们中的很多人将一去不复返。但你们只需要牢记训练的内容，时刻保持警惕，就可以大大提高生还的机率。"
D.Strings[10296]="我要说的就这些了。认真点，孩子们。"
D.Strings[10297]="好吧，安静。我们有很多事需要做，但时间只有那么一点。"
D.Strings[10298]="我曾经和一些德莱尼人在斯克提斯并肩作战，也曾经和另一些德莱尼人在影月谷对抗伊利丹。然而现在，我们是在艾泽拉斯，这里的情况看上去很艰险。"
D.Strings[10299]="首先，我要告诉你们这些辛多雷，我的要求很严格……这和占星者们的行事方式并不一样。要么给我打起精神，要么就给我滚回去！"
D.Strings[10300]="既然没人有异议，欢迎来到奎尔丹纳斯岛。太阳之井就在南边的高地上，而凯尔萨斯王子则躲藏在东面的魔导师平台里。"
D.Strings[10301]="我们是来这里支援那些高级军官召集来的所谓“冒险者”的。我们会帮助他们守卫岛上的关键位置，让他们远离战火，这样他们就能安心去做他们的事情了。"
D.Strings[10302]="你们可以从小队指挥官那里得到更进一步的分配和指示。如果没有什么其他问题，就这样，好运！"
D.Strings[10303]="欢迎来到太阳之井。尽管这里气候宜人，景色秀丽，但女士们先生们，你们不是来这里度假的！"
D.Strings[10304]="现在的情况是这样：在那些更有经验、并且装备精良的伙计们对付凯尔萨斯王子时，我们正在努力保护我们所能保护的一切。"
D.Strings[10305]="我知道，我们也以为他已经死了，不过事实并非如此。他正设法用太阳之井将燃烧军团的主子——基尔加丹带到这个世界来。"
D.Strings[10306]="我跟你们打保票，如果他成功了，这个世界将会遭受比外域更严重的灾难！所以，我们必须保证这一切不会发生。"
D.Strings[10307]="在猎人们被指派狙击敌方飞行员的同时，战士们也将被分配前往关键地区进行防御。"
D.Strings[10308]="我正在等待着给你们指派特殊任务的命令。在此期间，请待在这里随时准备出发！"
D.Strings[10309]="很高兴你问起这个，我们占领军械库的计划已经实施了百分之$3233w。$B$B我知道战斗法师艾尔娜和先驱者伊努罗需要你的帮助。去奎尔丹纳斯岛上的阳湾圣殿找他们谈谈吧。"
D.Strings[10310]="上次我从霍尔萨那里听说我们已经完成了百分之$3228w。$B$B我不知道该怎么形容这些设施对我们来说有多么重要。我们的人民需要更好的武器和装备，而铁砧和熔炉则是这一切的关键所在。$B$B铁匠铺就在阳湾军械库的后面，$n。"
D.Strings[10311]="我还有其他事想问你。"
D.Strings[10312]="真不幸，我们还没有拿下港口，不过报告说我们的进程已经达到了百分之$3238w。$B$B$n，如果你想帮忙的话，去奎尔丹纳斯岛的阳湾军械库找魔导师伊拉斯塔和守备官凯兰谈谈吧。"
D.Strings[10313]="炼金台还没完全准备好，$n。不过玛尔娜说她已经完成了$3223w%%。$B$B如果你想帮她一把的话，就去阳湾港口的旅店里找她吧。"
D.Strings[10314]="摧毁太阳之井高地中的魔法屏障的进展如何了？"
D.Strings[10315]="我们仍然在尝试摧毁第一道屏障阿加麦斯。拜托你了，$c，请立即前往奎尔丹纳斯岛，尽一切可能帮助我们！"
D.Strings[10316]="第一道屏障阿加麦斯已经被摧毁了，基尔加丹的两个副官——萨洛拉丝女王和高阶术士奥蕾塞丝——必须接受正义的制裁。$B$B召集你的伙伴吧，$c，攻入太阳之井！第二道屏障洛希多尔是我们的下一个目标。"
D.Strings[10317]="如果基尔加丹通过太阳之井进入这个世界，我们就将陷入一场一万年以来最残酷的战争。"
D.Strings[10318]="铁鹰号是客船，并不是战舰！好吧，对我来说这仅仅是一份工作。只要王子肯付工钱，我就顺从那个喜欢自吹自擂的船长。$b$b不管怎样，欢迎上船。"
D.Strings[10319]="你有东西需要修理吗？请使用售货机器人。"
D.Strings[10320]="我们保护着这艘由奥格瑞玛飞往荆棘谷格罗姆高营地的飞艇。"
D.Strings[10321]="现在没空，朋友……我有事要做，再见。"
D.Strings[10322]="我管理着艾泽拉斯最坚固的飞船。她曾经靠两门轻型火炮就炸平了一座城市，真的……她投射下的阴影就足以让敌人魂飞魄散。$b$b什么？这当然是真的！"
D.Strings[10323]="阳湾港很快就要被我们控制了。如果我们能够持续不断地让港口得到增援，那就必胜无疑了。$B$B我们的目标完成率已经达到了$3238w%%。"
D.Strings[10324]="成功了，$n。掌控了阳湾港之后，我们离全面胜利只有一步之遥了。"
D.Strings[10325]="我正在收集捐款，为那些在战争中牺牲的勇士们建造一座纪念碑。对我们来说，铭记这些为了取得胜利而牺牲的伙伴是非常有意义的。$B$B我们的目标完成率已经达到了百分之$3275w。"
D.Strings[10326]="这座纪念碑不漂亮吗？对我们来说，铭记这些为胜利而牺牲的伙伴们非常有意义。我们永远都不能忘记战争的代价——即便是那些我们最终获胜的战争。"
D.Strings[10327]="欢迎上船，$c。放下行李，享受你的旅程吧。在紫色公主号上，我们希望您心情愉快。如果你在船上有什么需要的话，船舱里有售货机可以为您服务。"
D.Strings[10328]="娱乐是让船员保持工作效率的重要手段。心情轻松了，他们的表现才会更好。"
D.Strings[10329]="船长真是太明理啦！我们在靠港后可以去放松一下！那是我最向往的时刻。"
D.Strings[10330]="请让我休息一小会。"
D.Strings[10331]="让我再睡会吧，就五分钟，朋友……"
D.Strings[10332]="我现在很忙。"
D.Strings[10333]="我现在没时间和你闲聊。"
D.Strings[10334]="尽管从格罗姆高营地到幽暗城的航线平淡无奇，但是一路上的风景秀色宜人。可是这并不能成为工作时候睡着的理由。"
D.Strings[10335]="进来休息一会儿吧，远离灰尘和泥沼吧。"
D.Strings[10336]="牛头人酋长乐队在下一场巡回演出期间会停留在银月城。他们经常在没有练习任务的时候在我上方的阳台上懒洋洋地晒太阳。请随意和他们打招呼吧……他们喜欢被关注的感觉。\n\n我们暂时不需要新的人手，不过你可以时常来看看。谁知道会发生什么？"
D.Strings[10337]="牛头人酋长乐队一定是整个艾泽拉斯最著名的乐队了！"
D.Strings[10338]="我想知道他们会在银月城待多久，真希望他们能在这里表演！"
D.Strings[10339]="如果可以的话，我愿付出一切来找寻一个上台和他们谈话的机会……"
D.Strings[10340]="不要在还未准备好的时候就去战斗，$n。倘若你已经向我们证明了自己的能力……我就可以给你提供一些非常强大的装备。"
D.Strings[10341]="很快凯尔萨斯的走狗们就会得到深刻的教训。我们很快就会碾碎晨锋部队，把阳湾港口从他们手里夺回来。$b$b我们的目标完成率已经达到$3238w%%了。"
D.Strings[10342]="阳湾港是我们的了。凯尔萨斯的走狗们落荒而逃……是时候让他们脱离苦海了！"
D.Strings[10343]="我是牛头人酋长乐队的后勤人员主管。\n\n你知道啦，就是打包、转运、卸货、搭建拆卸舞台、调试灯光效果，所有这类事情。"
D.Strings[10344]="舒维瑟尔是我的一个老朋友了……很有价值。我的意思是指我们的友谊。我以为我已经遗忘了那种感觉，直到我们再次在沙塔斯城相遇。\n\n他最近并不常在提瑞斯法林地，所以我想通过传送宝珠过去，向他问个好。"
D.Strings[10345]="<呀噜咕噜发现自己竟然能听懂你说的话，感到分外震惊。>"
D.Strings[10346]="只要同心协力，我们一定能逃离这里。你准备好了吗？"
D.Strings[10347]="我们已经脱离了危险。我可以自己回去的。"
D.Strings[10348]="感谢你救了我，$r。请转告国王我回来了。"
D.Strings[10349]="为什么要将我强行关押起来啊！你脑子坏了吗！"
D.Strings[10350]="我希望在冬幕节结束之前有机会去拜访一下冬天爷爷。"
D.Strings[10351]="万圣节快乐！"
D.Strings[10352]="我可能吃了太多糖……"
D.Strings[10353]="明年我要打扮成一个海盗，要么就打扮成刺客。"
D.Strings[10354]="你觉得这面具怎么样？"
D.Strings[10355]="最好的防守就是进攻，这是尽人皆知的。"
D.Strings[10356]="如果你没法保证自己能活下来，那么再强的武器对你来说也毫无意义，$c。"
D.Strings[10357]="$r，你已经掌握了与我们交流的诀窍，不过这算不了什么。$B$B水塘那边还有大群的冬鳞背叛者等着你去收拾呢。"
D.Strings[10358]="下一个！"
D.Strings[10359]="不错，我们需要你这样的人手。向平民联络官报到吧，他会为你分配工作。"
D.Strings[10360]="我倒是能提供适合你的工作机会。向平民联络官报到吧。"
D.Strings[10361]="我还以为人手已经够了，不过好像还有一些空缺。向平民联络官报到吧。"
D.Strings[10362]="很好，你在这块领域算得上是熟练工。立即向平民联络官报到吧，我们需要你这样的人手！"
D.Strings[10363]="我又不是瞎子。我能看到真实的情况！"
D.Strings[10364]="又是来应征士兵的！喏，这是你的剑。去兵营报到吧！"
D.Strings[10365]="别害怕，朋友。这是你的剑和盾。去兵营报到吧。"
D.Strings[10366]="啧啧，瞧你这强壮的胳膊？朋友，前线正需要你这样的勇士。去兵营报到吧。"
D.Strings[10367]="你让我很伤心呢——我得招满分配的名额，你知道吗？你能拿剑吗？去兵营报到好了。"
D.Strings[10368]="似乎我们还需要一名……啊，不对。是七名士兵。希望你擅长使剑——去兵营报到吧。"
D.Strings[10369]="下一位，下一位。"
D.Strings[10370]="下一位！"
D.Strings[10371]="木匠，长官。"
D.Strings[10372]="木匠。"
D.Strings[10373]="造船工，长官。"
D.Strings[10374]="造船工。"
D.Strings[10375]="雇农，大人。"
D.Strings[10376]="雇农，长官。"
D.Strings[10377]="裁缝。"
D.Strings[10378]="裁缝，大人。"
D.Strings[10379]="铁匠。"
D.Strings[10380]="泥瓦匠，长官。"
D.Strings[10381]="矿工。"
D.Strings[10382]="矿工，长官。"
D.Strings[10383]="厨师。"
D.Strings[10384]="厨师，长官。"
D.Strings[10385]="不久前，我来这里观察冬鳞鱼人。我伪装成他们的模样，保持着一定的距离，记录鱼人的日常生活情况。$B$B没过多久，一切都改变了。$B$B考达拉的一场地震引发山崩，附近的洞穴都露了出来。居住在洞穴中的龙虾人开始偷窃冬鳞蝌蚪。鱼人们试图拯救他们的后代，但是一旦他们进入洞穴，就像被转换了心智似的，沦为了龙虾人的走狗。$B$B那些尚未堕落的鱼人撤退到这里，我勉为其难地成为了他们的首领。"
D.Strings[10386]="报上你的职业。"
D.Strings[10387]="很好。你的职业是？"
D.Strings[10388]="你的职业？"
D.Strings[10389]="应征者，你以前是做什么工作的？"
D.Strings[10390]="来诺森德之前，你是做什么的？"
D.Strings[10391]="我的兄弟姐妹都发疯了！你能帮我逃离这里吗？"
D.Strings[10392]="没时间闲聊——我有工作要做！"
D.Strings[10393]="你能听懂我说的话？我能听懂你说的！"
D.Strings[10394]="$R，我为什么要和你说话？这堆烂摊子很可能就是拜你们所赐！"
D.Strings[10395]="我们要忙着收集贝壳和消灭逆戟鲸呢。你要么来帮忙，要么就别挡路！"
D.Strings[10396]="Blurglgr murbrgl……开个玩笑，我能听懂你的话。"
D.Strings[10397]="你查明村落里的鱼人发狂的原因了吗？"
D.Strings[10398]="我就知道我们不应该进入洞穴。那里的状况太异常了！"
D.Strings[10399]="总觉得新国王姆嘎姆嘎有什么地方不对劲，但是又说不上来是哪儿有问题"
D.Strings[10400]="火焰将在阴影中燃烧！"
D.Strings[10401]="萨洛拉丝向$n施放暗影新星。"
D.Strings[10402]="奥蕾塞丝向$n施放燃烧。"
D.Strings[10403]="$n，你已经能够与冬鳞鱼人沟通了。"
D.Strings[10404]="我的同胞已经醒了。你的努力白费了……"
D.Strings[10405]="太迟了，小东西。迷雾已经逼近。克瓦迪尔回来了……"
D.Strings[10406]="瞧瞧波涛汹涌的大海，潮水高涨的时刻就是你的末日。"
D.Strings[10407]="克瓦迪尔从迷雾中迫近。逃跑吧，趁你还有命在，逃吧。"
D.Strings[10408]="我是阿图伊克，卡玛古的卡鲁亚克氏族酋长。"
D.Strings[10409]="该死的凯尔萨斯和他的走狗们！我们的一切都没有了，但他们竟然愚蠢到认为我们不会反击。女伯爵莉亚德琳已经给我们找到了一种新的能量源。我们不会坐以待毙。"
D.Strings[10410]="奥蕾塞丝！你的火焰会在我心中燃烧下去！"
D.Strings[10411]="<龙鹰似乎由于附近的骚动而变得狂乱起来。>"
D.Strings[10412]="对奥格瑞玛的攻击不仅是向兽人宣战，更是对部落的冒犯。这是对我们的侮辱！$B$B巫妖王企图散播恐惧的种子。$B$B这些……$B$B<加尔鲁什指着他周围的防御工事。>$B$B这就是阿尔萨斯一役的战果。$B$B部落决不退缩……"
D.Strings[10413]="<骑上龙鹰前往阳湾港。>"
D.Strings[10414]="我们被包围了……加尔鲁什，敌人正从四面八方涌来。"
D.Strings[10415]="天灾军团如蝗虫一般挥师北下。"
D.Strings[10416]="联盟控制着这个地区唯一一条安全的航道，即便如此，这条航道也面临着随时被致命的迷雾吞噬的危险。"
D.Strings[10417]="唯一能够正常运转的补给港口位于这片大陆的另一端，在被遗忘者手中！"
D.Strings[10418]="无法用地精飞艇运送的物资必须通过航运，横穿整个诺森德才能到我们这里。"
D.Strings[10419]="航道……补给……我快给你烦死了！萨鲁法尔，部落需要的只是勇者无畏的精神罢了！既然我们已经在这片冰原上站稳了脚跟，还有什么能阻挡我们呢！"
D.Strings[10420]="攻城器械、弹药、重型盔甲……没有这些，你打算如何轰开冰冠冰川的城墙？"
D.Strings[10421]="我的计划？你很快就会明白的！"
D.Strings[10422]="瞧……我们已经开辟出了一条航道。"
D.Strings[10423]="不仅如此……"
D.Strings[10424]="这就是你所谓的计划吗！"
D.Strings[10425]="加尔鲁什，你的脾气和你父亲简直一模一样。总是这么暴躁……既暴躁又卤莽。"
D.Strings[10426]="你脑子里只想着战争与杀戮，完全不考虑后果。"
D.Strings[10427]="别跟我谈什么后果，老家伙。"
D.Strings[10428]="加尔鲁什，我和你的父亲都饮下了恶魔领主的鲜血。玛诺洛斯的诅咒同样在我的血脉里流淌。"
D.Strings[10429]="我也曾征战沙场，令敌人心胆俱裂。"
D.Strings[10430]="格罗姆付出了生命的代价，将我们从诅咒中解放出来，但他无法让我们忘记那段可怕的岁月。"
D.Strings[10431]="他也无法抹去我们犯下的可怕罪行。"
D.Strings[10432]="%s顿了一顿。"
D.Strings[10433]="诅咒解除后的那个严冬，数以百计的兽人士兵都在绝望中迷失了方向，我也不例外。"
D.Strings[10434]="我们终于恢复了理智，是的……终于能够反省自己在燃烧军团驱使下做出的鲁莽行径。"
D.Strings[10435]="最让他们愧疚难安的就是德莱尼小孩的哭喊声……日夜萦绕在耳畔……"
D.Strings[10436]="你去过野猪农场吧？猪长到适合屠宰的年纪时……对，那种惨烈的嘶叫。你听过猪临死前的哀嚎声么……非常刺耳。那些日子对我们这样的老兵来说真是煎熬。"
D.Strings[10437]="你总不会认为那些孩子会永远单纯吧？他们长大之后，就会拿起武器来对付我们了！"
D.Strings[10438]="我指的不仅仅是敌人的孩子……"
D.Strings[10439]="加尔鲁什，我不能坐视不管，任由你带领族人重新踏上那条黑暗的道路。我会在局势无可挽回之前亲手杀了你……"
D.Strings[10440]="萨鲁法尔，你能活那么久吗？昔日的阴影难道不会吞噬你的躯壳吗？"
D.Strings[10441]="我可不吃猪肉……"
D.Strings[10442]="%s啐了一口。"
D.Strings[10443]="你发现了一堆部落篝火。亵渎这堆篝火，扑灭它吧！"
D.Strings[10444]="扑灭部落篝火！"
D.Strings[10445]="每个人都能享受到仲夏火焰节的乐趣！"
D.Strings[10446]="你发现了一堆联盟篝火。亵渎这堆篝火，扑灭它吧！"
D.Strings[10447]="扑灭联盟篝火！"
D.Strings[10448]="部落已经尝试来偷取我们的火焰了。我希望能以其人之道，还治其人之身。"
D.Strings[10449]="联盟的火焰在熊熊燃烧！"
D.Strings[10450]="我倒想看到联盟来试着偷我们的火焰。"
D.Strings[10451]="部落的火焰永远都不会熄灭！"
D.Strings[10452]="仲夏节是每个夏天里最重要最欢乐的时刻！"
D.Strings[10453]="我很喜欢看仲夏火焰节结束时的烟花表演。"
D.Strings[10454]="恐惧永远是我们最强大的武器。整场战争的胜负就取决于敌人的惊恐与犹疑。那么，对面不知道恐惧为何物的敌人，我们要怎么打呢？$B$B<萨鲁法尔摇了摇头。>$B$B我们不仅要在诺森德与天灾军团作战，还要在他们将我们击溃之前，努力控制住自己的情绪。"
D.Strings[10455]="我们要做好进军索拉查盆地的准备。$B$B别光站在那儿啊，$c。为部落的荣耀而战吧！"
D.Strings[10456]="我还有一堆乱七八糟的事情要处理呢，但是我不会有丝毫抱怨。$B$B如果你还为自己身处部落自豪的话，就来帮我一把！"
D.Strings[10457]="灵魂在我们身边低语。你听见了吗，$r？"
D.Strings[10458]="这里躺着一具钢腭的车队卫兵的尸体。"
D.Strings[10459]="这里躺着一具钢腭的车队工人的尸体。"
D.Strings[10460]="暮光教派仇视一切我们珍视的东西。我们发誓要尽一切努力保卫这里，不让他们造成的灾祸将这里毁灭，$r。"
D.Strings[10461]="$n会帮助我们展开攻击。让祖先的灵魂重归宁静吧！"
D.Strings[10462]="出击！"
D.Strings[10463]="发动伏击。让他们重新安息吧！"
D.Strings[10464]="打起精神来。钢腭就死在前面。"
D.Strings[10465]="喏，瞧见那面旗帜和他的尸体了吧。怎么回事？他朝我们冲了过来！"
D.Strings[10466]="你做得很好。返回北方的兽人要塞吧，告诉博古洛克大王我们成功了！"
D.Strings[10467]="我自由了！谢谢你。"
D.Strings[10468]="我真是无地自容。我应该和先知一起死在犸格莫斯的。$B$B让我静一静。"
D.Strings[10469]="附近的气元素躁动不安。小心……它们不会让你安全通过的。"
D.Strings[10470]="搞什么啊？！是谁打扰我享用美餐！"
D.Strings[10471]="%s装配完毕。"
D.Strings[10472]="爆破倒计时，5……"
D.Strings[10473]="谢谢你救了我！愿好运永远伴随你。"
D.Strings[10474]="卡斯卡拉会铭记你的恩情。"
D.Strings[10475]="谢谢你，$c。愿微风与海洋保佑你。"
D.Strings[10476]="$c，谢谢你给予我们的帮助，愿先祖永远庇佑你。"
D.Strings[10477]="看到先祖的灵魂无法安息，我非常痛心。$B$B指挥官斯尔加·钢腭这个蠢货居然带领商队穿越这片神圣的墓地，我们必须消灭他那被诅咒的灵魂。"
D.Strings[10478]="是谁打断了我的冥想？"
D.Strings[10479]="卡加尼舒！"
D.Strings[10480]="$n，只有你能从卡加尼舒的魔掌中救出我。"
D.Strings[10481]="转告因波莉安，我会考虑停战的提议。但是卓恩必须先停止对我们的攻击！"
D.Strings[10482]="你很烦诶。快滚！"
D.Strings[10483]="别……住手！"
D.Strings[10484]="我……投降。只要西米尔不再侵犯我的地盘，我愿意休战。"
D.Strings[10485]="你，立即从我的视线中消失。最好别让我再看见你。"
D.Strings[10486]="你竟敢招惹我？！"
D.Strings[10487]="噢不……他们禁锢了他的灵魂！"
D.Strings[10488]="在西部的侦察行动中，我们损失了许多出色的双足飞龙。天灾军团对任何可疑的探子都不会手下留情。$B$B幸运的是，我想出了解决办法，虽然这样可能会威胁到骑手的性命。你要知道，在纳萨姆平原的侦察行动中，骑手的生还率已经高达百分之三十了。而我们之前使用双足飞龙的时候，简直可以说是有去无回！"
D.Strings[10489]="亚尼，送我到加尔鲁什码头吧。"
D.Strings[10490]="我太可耻了。我应该和先知一起死在犸格莫斯的。"
D.Strings[10491]="迷雾已经蔓延到了加尔鲁什码头和帕尔依。我们却还留在这里，真是疯了！"
D.Strings[10492]="菲兹兰克死命地催我，可我手里没有任何工具，这叫我怎么做事啊？！"
D.Strings[10493]="你在海岸上目睹的一切并不是天灾军团造成的。事实上他们也害怕这片迷雾——你也瞧见了，连天灾军团都不肯涉足此地。$B$B朋友，迷雾中危机四伏。死亡的气息就萦绕在那片雾气中……$B$B一旦你踏入禁地，就会付出生命的代价。迷雾会吞噬你！$B$B我们还没有见过谁能活着从迷雾中走出来的。"
D.Strings[10494]="燃烧吧，旱鸭子！燃烧吧！"
D.Strings[10495]="我们的征服之旅才刚刚开始……以后有的是乐子。"
D.Strings[10496]="在迷雾中化为灰烬吧！"
D.Strings[10497]="自打我来到这里，就目睹了原本只存在于噩梦中的恐怖景象，但是没有什么能比潜伏在迷雾中的可怕生物更让人毛骨悚然了。$B$B<穆图点了点头。>$B$B就在距离我们几码的雾气中，盘踞着一种名叫克瓦迪尔的噬血生物。迷雾席卷码头时，只有少数的幸运儿捡回了性命。从那之后，但凡进入迷雾的人无一生还。地狱咆哮也因此将这里划为禁区。如果你坚持要进去的话，后果自负……"
D.Strings[10498]="我……你是……$B$B<小穆图浑身颤抖。>$B$B你是来救我的吗？"
D.Strings[10499]="毒蛇之喉被烈焰吞没了！"
D.Strings[10500]="库尔达卡被烈焰吞没了！"
D.Strings[10501]="伯尔之锤被烈焰吞没了！"
D.Strings[10502]="伯尔之砧被烈焰吞没了！"
D.Strings[10503]="舵手奥拉布斯来对付你了！"
D.Strings[10504]="可悲的蠢货！玛里苟斯的仆人宁死也不会为敌人效劳……"
D.Strings[10505]="啊啊！$c，有什么手段尽管使出来吧！我什么也不会说的！"
D.Strings[10506]="我想找人好好聊聊！"
D.Strings[10507]="你有什么要问我的吗？"
D.Strings[10508]="告诉你吧，我们已经封印了那位尊贵的大法师。就算你能找到她，可钥匙在莎尔兰德手中。你不过是在白费力气！"
D.Strings[10509]="我能感觉到父亲的光环。他肯定就在这个方向……跟我来，$n。"
D.Strings[10510]="前方的迷雾出现了缺口。我们就要到了！"
D.Strings[10511]="爸爸！爸爸，我得救了！"
D.Strings[10512]="我是不会失败的！这个世界注定要毁灭！"
D.Strings[10513]="不！！！这太过份了！你已经问出大法师的下落了……为什么还不放了我？"
D.Strings[10514]="我所知道的统统告诉你了，$r！你这是在浪费时间……"
D.Strings[10515]="怎么啦，$c？你是不是觉得自己相当优秀，不屑与我们为伍了？"
D.Strings[10516]="你总算露面啦！我很虚弱，怎么都扭不断这些生锈的锁链。$B$B别站在那儿呀！帮我弄断它！"
D.Strings[10517]="我们来做个交易吧：如果你把我从这儿救出去，我就给你一大笔钱，多到超出你的想象！"
D.Strings[10518]="我现在很忙，$c。$B$B我能为你做什么呢？"
D.Strings[10519]="我可不是什么开胃小菜！"
D.Strings[10520]="将军，我向你保证，我能在一个月内招募到两个团的兵力。"
D.Strings[10521]="好吧，将军。如果你改变主意的话，我们会很乐意提供军事援助的。"
D.Strings[10522]="将军，我们的军队主要是由村民和农夫构成的。他们都是很好的人，但是还没有完全摆脱自小养成的偏见和迷信。他们还没有准备好与外来盟友并肩作战。"
D.Strings[10523]="先驱者，我会认真考虑你的建议。同时，我们也会随时向你们咨询的。"
D.Strings[10524]="我们已经被天灾军团包围了。从目前的情况看，我们还能坚持一段时间。但这将是一场你死我活的战斗。"
D.Strings[10525]="我们别无选择，只能发动进攻。我知道局势对我们不利，但是牦牛人绝不能坐以待毙。"
D.Strings[10526]="就算是死，我也要紧握沾满敌人鲜血的战斧！"
D.Strings[10527]="我不会让将士们为了所谓的“荣耀”白白送命。如果没人能活下来，那么为生存而战还有什么意义呢？"
D.Strings[10528]="杜尔姆，战争看来是不可避免的。但首先，我们得找到扭转局势的法子。埃恩雷，你有什么提议吗？"
D.Strings[10529]="我们的先祖懂得如何扰乱敌人的心智。我们可以利用这种能力找出天灾军团的弱点，或是杀死他们的指挥官。没有了首领的指挥，天灾军团很快就会败下阵来。"
D.Strings[10530]="啧啧，卑鄙的阴谋。"
D.Strings[10531]="杜尔姆，你所谓的荣誉又能挽救什么？你的性命？我的性命？还是抚养你长大的盲眼老人玛罕宗父的性命？"
D.Strings[10532]="对死人而言，荣誉还有什么意义。战士可以为了荣耀投身沙场，但酋长要考虑的问题则要多得多。我们决定采取先知埃恩雷的计划，继续保卫村落。"
D.Strings[10533]="慢点说，孩子。我还不熟悉你们的语言。"
D.Strings[10534]="请你小点声，$r。哈玛特老了，她需要休息。"
D.Strings[10535]="该采取行动了。我们必须在天灾军团摧毁我们之前解决他们。"
D.Strings[10536]="这个消耗品已经没用了！不管它了！现在我已经做到了连萨格拉斯都没有做到的事情！我要彻底毁灭这个世界，真正成为燃烧军团的主宰者！末日已经到来啦！让这个世界就此支离破碎吧！"
D.Strings[10537]="埃恩雷，$n将你要的兽皮带回来了。请你赶快把它们拿走，我真是受不了这玩意儿。"
D.Strings[10538]="我会拿走的。怎么能让伟大的酋长被一堆兽皮吓得瑟瑟发抖呢。"
D.Strings[10539]="这是怎么回事呢？！"
D.Strings[10540]="钥匙已经被我摧毁了！你们那位尊贵的大法师归玛里苟斯了！"
D.Strings[10541]="竟敢打扰我的工作？！胆小鬼，不敢露面吗！"
D.Strings[10542]="我会将我的力量导入宝珠中！准备好！"
D.Strings[10543]="这是我所能做的一切了！力量现在掌握在你们的手中！"
D.Strings[10544]="别再抱有幻想了！你们不可能赢！"
D.Strings[10545]="有人吗……救命……"
D.Strings[10546]="别让他们把我变成那种畸形的怪物！"
D.Strings[10547]="杀了我……立刻杀了我！"
D.Strings[10548]="谢谢你，朋友。"
D.Strings[10549]="终于自由啦！我要立即返回战歌要塞！"
D.Strings[10550]="非常感谢，陌生人。"
D.Strings[10551]="我永远欠你一个人情，朋友。"
D.Strings[10552]="我要将他们都转变成巫妖王的仆从！把尸体都带来吧……"
D.Strings[10553]="你竟敢挑战奥拉布斯，蠢货！"
D.Strings[10554]="死亡不过是无尽痛苦的开始。"
D.Strings[10555]="好啦！"
D.Strings[10556]="快活过来呀！"
D.Strings[10557]="这样没用……你需要更多的零件。"
D.Strings[10558]="我来啦！"
D.Strings[10559]="新鲜的肉！"
D.Strings[10560]="啊，很好……送上门来的零件！"
D.Strings[10561]="我建议进行摘除手术！"
D.Strings[10562]="你别想阻止我们！"
D.Strings[10563]="肮脏的生物！"
D.Strings[10564]="这是你的科多兽，托普！"
D.Strings[10565]="科多兽送货上门！"
D.Strings[10566]="哎呀！起作用啦！"
D.Strings[10567]="%s已经痊愈！"
D.Strings[10568]="埃霍恩，你的力量再也不会增强了！"
D.Strings[10569]="你的野心永远都不会实现！"
D.Strings[10570]="寒冰之石融化了！"
D.Strings[10571]="菲兹兰克，出了什么事。"
D.Strings[10572]="菲兹兰克，把你的故事再说一遍吧。"
D.Strings[10573]="好吧，坐吧。说来话长。$B$B当我们首次踏足这片冰封地狱时，无畏要塞的阿洛斯将军交给飞行敢死队一项特殊的任务。为了扩展联盟的势力范围，他命令我们建设一座空军基地。$B$B这个小机场就是我们的成果啦。这鬼地方到处都是肮脏的野兽，土地还冻得跟石头一样硬，你知道我们有多不容易吗！但是我们排除万难，在短期内就建成了这座机场！是不是很厉害呀！"
D.Strings[10574]="继续讲呀。"
D.Strings[10575]="嗯……为了确保机场的正常运转，我们需要抽取大量的沙砾和石油。这附近的池塘恰好有丰富的储量。$B$B某些沙砾甚至具有魔法属性……你能想象其中的潜在利润吗！？好吧，我就不扯远了。$B$B于是我们抽走大部分池水，在池塘中央修筑了泵站。本来一切都进展得挺顺利的，直到有一天，主管道突然堵塞了。"
D.Strings[10576]="等等。你刚才说什么？"
D.Strings[10577]="不过呢，当时我并不在场，所以接下来发生的事我是后来才知道的。$B$B他们从主管道中扒拉出一些零件来，似乎是机械侏儒的部件！结果，那群“勤奋”的蠢货就擅自将这玩意儿拼接起来了！$B$B从此，我们就与泵站失去了联系。"
D.Strings[10578]="接连几天都没有泵站的消息，我就派了一支侦察队去查看情况。可是他们再也没有回来。$B$B第二天，我又派出一队，结果他们还是跟蒸发了似的。此外，我们还损失了好几架侦察机。$B$B事情到这一步，我不得不派人去了南边寻求支援，让剩余的队员留下来做最坏的打算。我们全力锻造护甲、武器以及机器人，准备全副武装地进军泵站。$B$B几天前，当我们到达那里时，顿时被眼前的情景惊呆了！"
D.Strings[10579]="确实如此，那场面真是难以形容。$B$B泵站的工作人员都不见了踪影，取而代之的是一支名副其实的机器人大军！$B$B他们和侏儒的外形相似，还说什么一直在等我们呢。诡异的是，那些机器人好像真的认识我们。我们被包围了，接着就被拖到了泵站的顶层。$B$B在那里我们见到了他们的首领，并目睹了他对幸存的侏儒所做的坏事！"
D.Strings[10580]="他自称是机甲专家麦卡佐德。我们被押上泵站顶层时，他正忙着将幸存者转换成机械生物！$B$B麦卡佐德热情地欢迎了我们，并解释说他是“大建筑师”的杰作，这位建筑师则是来自奥杜尔的泰坦守护者。$B$B我们这才明白，原来是这家伙堵塞了主管道。他显然出过什么故障，被埋在地底有数千年了吧，却因此重见天日。我们正好将泵站建在他的头顶，也真够“幸运”的。"
D.Strings[10581]="在泵站机械师的帮助下，这家伙“活”了过来。$B$B于是，他打算帮助我们“治疗”所谓的“血肉诅咒”，以此表达他的感激之情。$B$B按照麦卡佐德的说法，正是这种诅咒在逐渐侵蚀泰坦的创造物！换句话说，最初我们都是机械侏儒之类的玩意儿，在经历了数千年的演变之后，才成为有血有肉的生物的！$B$B这简直太荒谬了。"
D.Strings[10582]="这哪里是什么“治疗”啊，而且我也不打算继续听这个机械疯子的胡言乱语，尤其是他还当面屠杀我们的同胞！$B$B你瞧，我们都是心智正常的侏儒……只能选择逃跑！好吧，大多数人都纵身跃下了平台，结果你也看到了。$B$B只有少数幸运儿得以逃生。我们势单力薄，本来就疲于应付北方的猛犸人和东方的天灾军团。如今，部落又在西北方扎营，局势真是糟糕透顶！"
D.Strings[10583]="$n，我们陷入了进退维谷的窘境。$B$B我们根本没有能力应付眼前的种种状况，说实话，我真是心有余而力不足啊。我建议你去找金吉谈一谈。她或许会告诉你接下来要怎么办。$B$B只希望你能在确保我们的安全的同时，处理好这堆烂摊子。"
D.Strings[10584]="你瞧，$n。世界末日很快就会降临。而你，将成为这噩梦的终结者……"
D.Strings[10585]="我们走……"
D.Strings[10586]="就这样？这就是伟大的部落所能召集到的全部人手？"
D.Strings[10587]="我真是搞不懂你这样的人物。英雄……"
D.Strings[10588]="为什么不选择放弃？为什么要执泥于必然的结局？"
D.Strings[10589]="巫妖王是不可战胜的。认命吧。"
D.Strings[10590]="世界即将终结。就·让·它·燃·烧·吧。"
D.Strings[10591]="把$g他:她;带走，准备复活仪式。"
D.Strings[10592]="巫师，在你伤害$n之前，我就会徒手将你干枯的徽记拿过来。"
D.Strings[10593]="$n，你永远不会孤单。"
D.Strings[10594]="你想要毁灭的世界是我们的家园。"
D.Strings[10595]="怎么回事？"
D.Strings[10596]="我们将竭尽全力于你抗衡——直到化为尘埃。我们会战斗到最后一刻。"
D.Strings[10597]="你这蠢货。"
D.Strings[10598]="通灵领主，你很快就会死在蠢货手中了。我要粉碎你，即便是巫妖王，也无法再复活你！"
D.Strings[10599]="就你？区区一只兽人？也想对抗我……"
D.Strings[10600]="大地之环的进攻开始了。"
D.Strings[10601]="埃霍恩退却了。他的防御变弱了。"
D.Strings[10602]="埃霍恩很快就会重新出现。"
D.Strings[10603]="我……我真不敢相信……萨鲁法尔……我……我很荣幸……能与您并肩作战。"
D.Strings[10604]="朋友，你应该立即返回战歌要塞。地狱咆哮一定很想知道……关于萨鲁法尔的故事。"
D.Strings[10605]="不许对任何人提起我。你们俩听到了吗！"
D.Strings[10606]="什么？你要把我送回去？！"
D.Strings[10607]="我要把那些机械侏儒炸成碎片！"
D.Strings[10608]="长官，我需要一架新的飞行器……"
D.Strings[10609]="愚蠢的元素仆从！你和你的主人会付出代价的！"
D.Strings[10610]="我命令你服从号角持有者的意志！"
D.Strings[10611]="谢谢你，$r。我现在就把这个孬种带走。"
D.Strings[10612]="我又变回血肉之躯啦！谢谢你，$c！"
D.Strings[10613]="啊……可是……之前的我很完美！"
D.Strings[10614]="我在哪儿？你是谁？为什么我的感觉这么奇怪？"
D.Strings[10615]="逃兵的行径让我们倍感羞耻。这种耻辱感是如此强烈，你只有在亲身经历后才能有所体会。这也是乌格索来到这里的原因……他必须得到教训。"
D.Strings[10616]="诺克，我真是难以启齿……逃兵不见了。"
D.Strings[10617]="$n，别让这名逃兵再溜走了。至少我们得维护联盟的颜面。"
D.Strings[10618]="启动反击模式。击退入侵者。"
D.Strings[10619]="你的行踪已经败露。要么乖乖接受改造，要么就去死。"
D.Strings[10620]="我还有命在！我恢复了血肉之躯！"
D.Strings[10621]="我又变回血肉之躯啦。这才是最重要的！"
D.Strings[10622]="$n，血孢花粉能削弱犸格莫斯所有猛犸人的力量。"
D.Strings[10623]="谢谢你，达拉然的朋友。"
D.Strings[10624]="我们不能在这里久留……靠近我，我们要转移到安全的地方去。"
D.Strings[10625]="$r，处处小心啊。血孢平原生活着许多残忍的生物。"
D.Strings[10626]="我们是机械侏儒……放弃抵抗吧。"
D.Strings[10627]="血肉之躯太脆弱了。我们能让你变得更加完美、强壮……敏捷。"
D.Strings[10628]="我们能移除你身上的诅咒，我们拥有强大的科技。"
D.Strings[10629]="以海象人的名义起誓，我要为族人复仇……这帮凶手将帕尔依烧得精光。"
D.Strings[10630]="我医治过农夫、贵族、商贩和乞丐。我要告诉你一个真理：面对死亡时，我们都一样。"
D.Strings[10631]="托奇！"
D.Strings[10632]="ED-210来啦！"
D.Strings[10633]="我是麦卡佐德的使者。我们会治好你的！"
D.Strings[10634]="闹剧该结束了。一旦我搞定你，麦卡佐德就会治愈你身上的诅咒。"
D.Strings[10635]="如果我献上你的皮，说不定奈辛瓦里会赏我点什么！"
D.Strings[10636]="我猜老赫米特肯定会用得着你的骨头的！"
D.Strings[10637]="还要50只蹄子我就能有新火枪啦！"
D.Strings[10638]="杀杀杀！！！！！"
D.Strings[10639]="今天晚上有肉吃啦！"
D.Strings[10640]="让我们较量一下吧！"
D.Strings[10641]="放弃吧，小鬼！"
D.Strings[10642]="孩子，你是来找我的吗？$n，为什么要杀我呢？我只是想帮忙啊。"
D.Strings[10643]="我再次复苏啦，这样我们就能回到那个完美的时代……泰坦的时代！"
D.Strings[10644]="你的眼神和心跳骗不了我，虽然我能让你永生，但是你还是会杀了我！"
D.Strings[10645]="非常好。事情变成这样真令我难过。我把你们都当作自己的孩子。如果有必要的话，我会杀了你的！"
D.Strings[10646]="你是否心怀虔诚，崇尚正义？如果是，欢迎你与德鲁伊一起为保护动物贡献力量。只要你没有误入歧途，没有伤害过那些与我们共同分享这片天空的生灵，你就是仁德会的朋友。"
D.Strings[10647]="%s恢复了意识。"
D.Strings[10648]="这名飞行侦察员未能在空难中生还。"
D.Strings[10649]="寻找飞行员的佩章。"
D.Strings[10650]="X-51型虚空火箭坐骑"
D.Strings[10651]="宠物饼干"
D.Strings[10652]="地精天气制造机 - 原型机01-B"
D.Strings[10653]="让我们的火焰在整片大陆上熊熊燃烧吧！"
D.Strings[10654]="你在彩带杆那里跳过舞吗？"
D.Strings[10655]="我羡慕那个家伙玩火炬的技巧。"
D.Strings[10656]="你要向猛犸毁灭者卡奥挑战！？啧啧，来一较高下吧！"
D.Strings[10657]="那么，$n，你想要什么东西？"
D.Strings[10658]="来率先体验一下超级无敌的静电除污器吧！"
D.Strings[10659]="源自破碎残阳的军用高端技术，轻松去除各类顽固污渍！"
D.Strings[10660]="无论是酒渍、泥渍，还是宠物留下的污渍，静电除污器都能将它们清除干净！"
D.Strings[10661]="不要犹豫了！现在订购还能得到我免费赠送的超导聊天铁！"
D.Strings[10662]="啊——各种珍品都在这里！我们专门为有识别能力的冒险者挑选艾泽拉斯世界的宝贝。$B$B既然你来找我谈话了，我想你肯定已经想好要什么了吧。"
D.Strings[10663]="艾泽拉斯英雄传"
D.Strings[10664]="积分兑换"
D.Strings[10665]="穿越黑暗之门"
D.Strings[10666]="外域之火"
D.Strings[10667]="燃烧军团的进攻"
D.Strings[10668]="背叛者的仆从"
D.Strings[10669]="你还有什么其它的促销内容吗？"
D.Strings[10670]="嘿，先驱者，调查进行得怎么样了？如果你在订购期限前购买的话，就有机会得到一块超导聊天铁哦。"
D.Strings[10671]="一切进展顺利，瓦菲雷。你不是要去做些产品示范之类的事情吗？"
D.Strings[10672]="你知道炼金师可以转化特定的宝石吗？玛尔娜和我讨论过这个问题。$B$B我深信只要能给她造好炼金台，就可以让她发挥自己的才干。这样一来我和她也就可以去制造那些被认为已经失传的宝石了。"
D.Strings[10673]="我们成功了，$n。玛尔娜已经学会一些非常特殊的宝石的转化方法了。我也已经知道了该如何好好利用它们。"
D.Strings[10674]="不要害怕，$r。我们有着相同的目标。"
D.Strings[10675]="我是蓝龙军团的卡雷苟斯。$B$B我监视太阳之井形成的能量已经有一段时间了，但是现在我意识到，它那可怕的能量也许会导致世界的毁灭！"
D.Strings[10676]="我和一个朋友一起赶来，想要从燃烧军团的首领基尔加丹手中营救一位年轻的姑娘。$B$B我们发现凯尔萨斯正在尝试从太阳之井的深处召唤出基尔加丹！$B$B为了这个世界——我们不能让他的计划成功！我的任务就是阻止他们。"
D.Strings[10677]="我们有什么可以帮你的吗？"
D.Strings[10678]="打败凯尔萨斯是一件值得你专心去做的事情。$B$B除此之外，如果你能组织一支军队的话，太阳之井里面还有许多邪恶的家伙需要你去处理。$B$B也许我们会在那里再次相遇。"
D.Strings[10679]="这里不允许你来打扰！"
D.Strings[10680]="我们的理想终将实现！"
D.Strings[10681]="元素会将你们彻底毁灭！"
D.Strings[10682]="欢迎，$c。你有没有向这团火焰表达你的敬意？$B$B记住：我们的节日火焰在联盟的每一片土地上燃烧，如果你有时间的话，去向它们一一表达你的敬意。$B$B当然部落也点燃了他们自己的火焰，如果你有看到的话，记得去踏灭那些毫无价值的东西。"
D.Strings[10683]="你竟敢挑战北风苔原的领主尼达尔！？"
D.Strings[10684]="你的卤莽会毁了你！"
D.Strings[10685]="你没有任何机会！"
D.Strings[10686]="看，夏日的烈焰！"
D.Strings[10687]="小心，不要被烧着了！"
D.Strings[10688]="对火焰节满意吗？"
D.Strings[10689]="欢迎！你有没有向这块大陆上的火焰表达你的敬意？"
D.Strings[10690]="这个世界遭受了许多我们肉眼看不到的破坏。甚至是时间的通路都感觉有些异常。"
D.Strings[10691]="你为我们做了很多。我来这里是为了执行一项重要的任务，不过如果你需要前往时光之穴的话，我很乐意带你去那里。"
D.Strings[10692]="送我去时光之穴。"
D.Strings[10693]="在飞行员的尸体上搜寻应急工具包。"
D.Strings[10694]="不是吧！30个犀牛头就能换一个犀牛头盔？给我来两个！"
D.Strings[10695]="如果奈辛瓦里一意孤行的话，他很快就会完蛋了！兰恩根本就不知道他在干什么！"
D.Strings[10696]="你想打倒我？可怜虫……等等……那是什么声音？"
D.Strings[10697]="竞技场管理员就在东南面贫民窟的墙边。"
D.Strings[10698]="这些石头应该是最后一批了。我们和耐普图隆部队的合作将会无懈可击。"
D.Strings[10699]="是的，猎潮者会对这项部署非常满意。火焰领主的威力将被削弱。"
D.Strings[10700]="那么你们自己的准备做得怎么样了？冰霜之王会打开通往传送门的道路吗？"
D.Strings[10701]="卡希斯已经告诉我们了。我们已经进入了奴隶围栏，就等你们的冰术师了。"
D.Strings[10702]="盘牙水库的仪式将在埃霍恩完全准备好的时候唤醒它，炎魔之王和冰霜之王的冲突将会对这个世界的根基造成伤害。我们的最终目的终于就要实现了……"
D.Strings[10703]="奈辛瓦里不会停止杀害诺森德的野生动物的，他迟早会再下毒手。你必须保持警惕，$n！$B$B无论如何，不要屈服于任何可能出现的诱惑……这家伙一定会企图迷惑你。坚持住！"
D.Strings[10704]="菲兹克斯，我想我们已经搞定引擎的故障了。"
D.Strings[10705]="这次总行了吧……对吧？"
D.Strings[10706]="成功了，多莱安！你看！它动起来了……"
D.Strings[10707]="别想控制我，小$r！"
D.Strings[10708]="我要飞啦！"
D.Strings[10709]="好痛！"
D.Strings[10710]="我放弃了！我受够地精的这些小玩意了！"
D.Strings[10711]="安薇娜，你必须觉醒过来！这个世界需要你！"
D.Strings[10712]="你必须清醒过来！变回过去的你，变回你原来的样子！就是现在，安薇娜！"
D.Strings[10713]="安薇娜，我爱你！仔细聆听我的声音！回到我的身边来！只有你才能净化太阳之井！"
D.Strings[10714]="对，安薇娜！投入命运的怀抱吧！"
D.Strings[10715]="永别了，我挚爱的安薇娜。尽管只有我们少数人会记住你，但是你今天的英勇事迹改变了命运的轨迹。曾被玷污的太阳之井又重归纯净。英雄们，千万不要让安薇娜白白地牺牲。"
D.Strings[10716]="我现在只效忠于主人。"
D.Strings[10717]="但我似乎迷失了……，我找不到回去的路。"
D.Strings[10718]="卡雷……卡雷？"
D.Strings[10719]="噩梦结束了！法术被破除了！再见，亲爱的卡雷！"
D.Strings[10720]="啊啊啊！太阳之井的能量……开始……对抗我！你们都做了些什么？你们都做了些什么？？"
D.Strings[10721]="现在让我们释放他们的灵魂，听一听他们要说些什么吧。"
D.Strings[10722]="谢谢你救了我们。我们偶然发现了机甲专家麦卡佐德的零件，并把他重新组装了起来。"
D.Strings[10723]="作为感谢，他要为我们“驱除诅咒”，将我们“变回”机械体。"
D.Strings[10724]="他声称泰坦的创造物都中了什么“血肉的诅咒”。他还说侏儒原本都是机械侏儒。"
D.Strings[10725]="他疯了！必须阻止他，否则就迟了！"
D.Strings[10726]="这消息太可怕了！"
D.Strings[10727]="我绝不容许天灾军团将我们驱逐出这里！我们放弃了一切，准备在诺森德开始新的生活。$B$B我向你保证，我们会拼死抵抗的。"
D.Strings[10728]="你身后有动静！"
D.Strings[10729]="欢迎你，$n。我是杜尔克特·狼脉，氏族的守护者。"
D.Strings[10730]="石头散发出一阵寒气，冻结住了周围的空气和放置石头的平台。在石头的深处，一道蓝色的光芒跳动着，等待着。"
D.Strings[10731]="把你的手放在石头上。"
D.Strings[10732]="到处都是天灾军团！这真是……一场噩梦！"
D.Strings[10733]="来呀，试试你们的运气吧！"
D.Strings[10734]="等等，朋友们！送这只恶魔下地狱之前，我还有些事要问它。"
D.Strings[10735]="可笑的大蜥蜴！你只有死路一条！"
D.Strings[10736]="哈哈哈！你的魔法太脆弱太可笑了！"
D.Strings[10737]="安薇娜在哪，恶魔？卡雷怎么了？"
D.Strings[10738]="你必须说出他们的下落！"
D.Strings[10739]="说！我可不耐烦了！"
D.Strings[10740]="玛里苟斯大人……我……尽力了……"
D.Strings[10741]="阿尔萨斯以为他手下的几名亡灵渣滓就能将我们赶回东部王国……他会尝到后果的。"
D.Strings[10742]="黑暗的力量正在这片土地上蔓延。$n，睁大眼睛，鼓起勇气吧。"
D.Strings[10743]="我们中的某些人打算逃避兵役。任何时候，好的渔夫总是有用的……将军也得吃饭啊。"
D.Strings[10744]="每天都在厨房里做同样的事。要不了多久肯定会厌倦的。"
D.Strings[10745]="差不多到换班的时间了。我好想眯一会儿，你明白我的意思吧？"
D.Strings[10746]="好吧……"
D.Strings[10747]="好吧，然后呢？我不会坐以待毙的！"
D.Strings[10748]="总算不用遮遮掩掩了！阿尔萨斯，赐予我力量吧！"
D.Strings[10749]="$c，你还不知道自己招惹到什么人了吧！死神在朝你招手呢！"
D.Strings[10750]="没钱花了？来，给你5000枚金币。"
D.Strings[10751]="虽然玛蒂苟萨的命运不该如此悲惨，你们的所作所为仍然是必须和必要的，不过，这场战争远未结束！"
D.Strings[10752]="我欠你们一份情。当我们战胜基尔加丹时，整个世界都会感激你们的。"
D.Strings[10753]="阿尔萨斯曾是万民敬仰的人类王子。他所率领的诺森德远征军遭遇了可怕的命运。$B$B我的哥哥萨萨里安就是军中的一员。"
D.Strings[10754]="我准备好动身啦，杜尔克特。"
D.Strings[10755]="%s向你欢呼。"
D.Strings[10756]="是，我们不过是一群手无寸铁的矿工、农夫和工匠。可是情况危急时，我们也会赤手空拳地抗争到底，像士兵那样守卫我们的家园。"
D.Strings[10757]="抱歉，但我只跟德鲁伊打交道。"
D.Strings[10758]="我可以清除你所有的天赋，这样你就可以重新选择了。$B$B不过每次的价格都会变得越来越贵。"
D.Strings[10759]="抱歉，但我只跟猎人打交道。"
D.Strings[10760]="抱歉，但我只跟法师打交道。"
D.Strings[10761]="抱歉，但我只跟圣骑士打交道。"
D.Strings[10762]="抱歉，但我只跟牧师打交道。"
D.Strings[10763]="抱歉，但我只跟潜行者打交道。"
D.Strings[10764]="抱歉，但我只跟萨满祭司打交道。"
D.Strings[10765]="抱歉，但我只跟术士打交道。"
D.Strings[10766]="抱歉，但我只跟战士打交道。"
D.Strings[10767]="停下！"
D.Strings[10768]="小心！"
D.Strings[10769]="%s哭了。"
D.Strings[10770]="想要点什么吗？可想而知……能供你挑选的东西也不多。"
D.Strings[10771]="为国家牺牲是军人的职责。如果将这场战争称为闹剧就算是叛国的话，那我就是一名十足的叛徒了。"
D.Strings[10772]="%s指了指东北方。"
D.Strings[10773]="远处那股烟……啊，是沃图克。他想要告诉我们什么……"
D.Strings[10774]="不……这不可能……"
D.Strings[10775]="冰雾村……但愿不是冰雾村……不！！！快！英雄，跟我来！"
D.Strings[10776]="%s熟练地破译出了烽烟中包含的信息。"
D.Strings[10777]="我现在很忙，$r。让我静一静。"
D.Strings[10778]="别走神啊。这场战争非比寻常，前线的气氛尤其紧张。$b$b想帮忙的话就打起精神来，让我看看你有多大的本事。"
D.Strings[10779]="陛下，我们的教徒已经顺利地混入联盟的地盘并取得了一定的控制权。"
D.Strings[10780]="您赐予我的力量使我能够更好地控制人类的思维。这些祭品就是证据。"
D.Strings[10781]="莉蕾萨！"
D.Strings[10782]="你这个混蛋精灵杂种，你对我的妹妹做了什么！？"
D.Strings[10783]="让我来对付这些入侵者吧。我会将他们的内脏拿去喂蛆。"
D.Strings[10784]="你在这里所取得的进展令人眼前一亮，血之王子。我很满意。"
D.Strings[10785]="这可真是个惊喜，萨萨里安。我已经数月没有听到有关莫格莱尼和其他死亡骑士的消息了。我猜，你是回来重新加入天灾军团的？"
D.Strings[10786]="别让我失望，萨莱因。把这个蠢货的首级带回冰冠冰川，否则就不用回去见我了。"
D.Strings[10787]="遵命，陛下！"
D.Strings[10788]="我宁愿自行了断。为了你对同胞犯下的罪行，阿尔萨斯，为了你对我犯下的罪行，你会付出代价的！我发誓！"
D.Strings[10789]="我好像弄丢了强化奥术牢笼。在你这儿吗？"
D.Strings[10790]="你无法阻止冰霜之王进入这个世界，凡人。猎潮者的力量将毁灭属于拉格纳罗斯的一切，将你们的土地变成一块冰封的乐园！"
D.Strings[10791]="当埃霍恩出现时，我们能准备好吗？"
D.Strings[10792]="你一定要在我们引导火焰的这段时间内挡住埃霍恩的手下。在我们削弱埃霍恩之前，不要靠近它。"
D.Strings[10793]="局势动荡！$B$B巫妖王率领萨莱因卷土重来，巨龙们纷纷投身魔枢之战，而维库人也在此时再度觉醒。$B$B你们乘坐木船来到严寒的极北之地与他们作战。各方势力互相牵制，形势大乱，使得海象人处于进退维谷的尴尬境地。$B$B眼下，新的邪恶势力又企图利用魔法力量彻底炸毁这片土地。我们必须寻找一处安全的避风港才能继续生存下去。$B$B这两位大使让我挺为难的……$r，你愿意帮助我的族人吗？"
D.Strings[10794]="我已经准备好对付莎拉苟萨了！"
D.Strings[10795]="别拿那种眼神看着我！我知道你们在想些什么，但风暴要塞的失败早就过去了。你们真以为我会把命运交给一个又瞎又粗野又下贱的暗夜精灵杂种？"
D.Strings[10796]="复仇之炎，燃烧吧！"
D.Strings[10797]="我要让你们的世界……彻底颠覆……"
D.Strings[10798]="主人，赐予我力量。"
D.Strings[10799]="不会让你们好过的。"
D.Strings[10800]="我的死根本算不了什么！主人一定会消灭你们的！你们会溺毙在自己的鲜血中！这个世界将会熊熊燃烧！啊！"
D.Strings[10801]="很高兴能再见到你，$n。"
D.Strings[10802]="$n，克瓦迪尔生性残忍，可是我不能放弃神圣的卡斯卡拉。只要我们不抛弃灵魂，灵魂就不会抛弃我们。"
D.Strings[10803]="卡斯卡拉遭到攻击！我们必须拖住敌军，直到所有人安全撤离。"
D.Strings[10804]="该死的巨人！如果他们想打仗，那就打吧！"
D.Strings[10805]="欢迎你，$c。你祭拜过这座火堆了吗？$b$b记住：所有部落人民定居的地方，都会有我们的节日之火在那里熊熊地燃烧着。$b$b联盟也一样，在各处都点起了他们自己的火焰。当你看见这些火堆时，不妨亵渎之，对我们会有帮助的。"
D.Strings[10806]="这名年轻的海象人似乎经历过一场激烈的打斗，不像是淹死的。"
D.Strings[10807]="<在尸体上寻找伊斯利鲁克的图腾。>"
D.Strings[10808]="你们只会浪费我的时间！"
D.Strings[10809]="我的渴求是无限的！"
D.Strings[10810]="对，没错，我就是神！"
D.Strings[10811]="不……更多，我还要更多！"
D.Strings[10812]="别打扰我了！"
D.Strings[10813]="消灭他们！"
D.Strings[10814]="这……这可不在计划……之内……"
D.Strings[10815]="噢，天啊，你们真可怕！"
D.Strings[10816]="天啊，你们运气怎么就这么好？"
D.Strings[10817]="现在我可真有点火了。"
D.Strings[10818]="该死的废物！看我亲自解决你们！"
D.Strings[10819]="这就是一个好的开始。"
D.Strings[10820]="我发誓你们还会有更多人躺下的……"
D.Strings[10821]="看样子你们要“灭团”了？"
D.Strings[10822]="“一”这个数字，可真令人感到孤独。"
D.Strings[10823]="一场完胜，绝对的完胜。"
D.Strings[10824]="克莉斯塔萨，我完成了自己的使命。请送我回到永生之盾。"
D.Strings[10825]="很高兴你能来。我想你已经很了解我们的火焰了，这些，你需要祭拜……不过，不知道你是否了解敌人的火焰……对于那些，你必须浇灭……去吧，回来以后可以向他领取奖赏。"
D.Strings[10826]="$n！我一直在担心你。有事耽搁了吗？"
D.Strings[10827]="希望你已经做好了防范措施……$b$b这里非常危险，如果你出了什么事，我是不会原谅自己的。"
D.Strings[10828]="$n，我们必须尽快阻止玛里苟斯。否则他的阴谋一旦得逞，就会产生毁灭性的后果。"
D.Strings[10829]="在动荡不安的年代，好朋友简直是无价之宝。$b$b保重，$n。尽可能地保护好自己……"
D.Strings[10830]="要不是你出手相助，我肯定已经死在监牢里了。$b$b我怎么都忘不了……"
D.Strings[10831]="当我们完成使命后，会设法报答你的救命之恩的。"
D.Strings[10832]="我的力量在逐渐恢复……$b$b很快你就能见识到我真正的实力。"
D.Strings[10833]="噢……$b$b我在哪儿？"
D.Strings[10834]="简言之，就是魔法。$b$b凡人的生命如此短暂，他们从不考虑自己的行为可能会造成怎样的长远影响。$b$b过于活跃的奥术能量严重影响了世界的稳定。如果听之任之的话，艾泽拉斯世界迟早会被毁灭。$b$b对于这一点，我们已经达成了共识。可还没等我们组织起专门的议会，玛里苟斯就擅自采取了行动。$b$b我们别无选择，只能与他作战。"
D.Strings[10835]="玛里苟斯是谁？"
D.Strings[10836]="$r，我们取得了一些进展，但还是太慢了。"
D.Strings[10837]="我们不能失败！艾泽拉斯世界的命运就维系在这脆弱的平衡上……"
D.Strings[10838]="魔法之王玛里苟斯是蓝龙军团的统帅。作为蓝龙守护者，他是艾泽拉斯世界最古老的生物之一。$b$b据说他已经从数千年来的疯狂中觉醒，可是他最近的行为表明他远没有恢复理智。$b$b对于我们的困境，他竟然决定以摧毁艾泽拉斯世界所有施法者的方式来解决。$b$b生命守护者红龙不得不采取行动。$b$b蓝龙军团和红龙军团展开了一场激战，世界的命运，就取决于那脆弱的平衡。"
D.Strings[10839]="构造体，要不惜一切代价保住我们的主城！"
D.Strings[10840]="战斗吧，孩子们！不要对敌人心软！"
D.Strings[10841]="为了领主！为了洛肯！"
D.Strings[10842]="同胞们，消灭岩石的子嗣！"
D.Strings[10843]="啊！我不再是玛里苟斯的奴隶了！所有挑战我的人都要被消灭！"
D.Strings[10844]="以基尔加丹的名义！"
D.Strings[10845]="我警告过你们了！"
D.Strings[10846]="我的觉醒已经完成了！你们的死期到了！"
D.Strings[10847]="已经来不及了！我的工作马上就要完成了！"
D.Strings[10848]="我绝不会落到……输的……那一边。"
D.Strings[10849]="你的痛苦就是我的欢乐！"
D.Strings[10850]="我就要这么看着你流血！"
D.Strings[10851]="可悲的凡人！"
D.Strings[10852]="没听说过吗？我永远属于赢的一方！"
D.Strings[10853]="阴影将在火焰下存在！"
D.Strings[10854]="火焰将你吞噬！"
D.Strings[10855]="萨洛拉丝！"
D.Strings[10856]="你们的好运到此为止了！"
D.Strings[10857]="暗影将你包围。"
D.Strings[10858]="时间，这是你永远也无法拥有的奢侈之物。"
D.Strings[10859]="我……要消失了。"
D.Strings[10860]="我真高兴能在这里看见你，$c。目前太阳之井高地一带的战略状况非常糟糕。"
D.Strings[10861]="报告全部状况，上尉。"
D.Strings[10862]="破碎残阳目前在奎尔丹纳斯岛的外围地域进展非常良好，基尔加丹的部队正被我们逼得节节败退。此外，趁着双方掌握地域的混乱，我直接派一小支侦察部队进入了太阳之井。我的部队目前已经通过了幻日广场，还曾在那附近发现了一小队血精灵，并与之交战，结果，那场战斗很快就变成了一场灾难。"
D.Strings[10863]="基尔加丹派驻在太阳井之内的卫兵远远比外面这些我们遇到过的要强大。军团将那里面的魔像全部灌入了恶魔能量能，转为他们所用。仅仅只是一只炎刃保卫者就将我派去的小队打得丢盔弃甲，我只好立刻命令他们撤退。我当时推断敌人会立刻将我的部队全部赶出高地区域，可令我吃惊的是，他们没有展开任何追击行动。"
D.Strings[10864]="他们为什么停下来了？"
D.Strings[10865]="不知道，但我对这个结果表示庆幸。他们行动上的迟缓使我有机会派出学者埃尔巴顿救下了许多小队成员。我又派出了一些擅长潜行和匿踪的斥候进去侦察了一下，他们带回了一些很有意思的消息。据说，所有的炎刃保卫者都停止运作了！基尔加丹的军队大概不想浪费它们的能量，只启动了一台炎刃保卫者用于对付我们。如果你和你的朋友想突入其中的话，就请允许我先制订一个进攻计划。"
D.Strings[10866]="非常感谢你的建议。"
D.Strings[10867]="你要充分利用他们那些已经关闭了的炎刃保卫者。如果被炎刃斥候发现的话，我敢肯定那些血精灵会立刻冲向最近的炎刃保卫者旁，试图启动它。你们得立刻冲上去杀了他。消灭了那些血精灵之后，只要你不激活那些保卫者的近距传感器，应该就可以安然通过，不用费力消灭它们了。这可以为你节省无数的时间和资源。"
D.Strings[10868]="塞拉娜上尉命令我协助你们在太阳之井高地一带的行动。"
D.Strings[10869]="目前太阳之井内各道门的状况怎样？"
D.Strings[10870]="所有挡在你前往太阳之井路上的魔法屏障都已经被摧毁了。前往太阳之井吧！立刻阻止基尔加丹进入这个世界！"
D.Strings[10871]="你们并不是在孤军奋战！蓝龙军团会帮助你们消灭欺诈者！"
D.Strings[10872]="我又将能量灌入了另一颗宝珠！快去使用它！"
D.Strings[10873]="又有一颗宝珠准备好了！快点行动！"
D.Strings[10874]="我所有的计划都是为了这一刻的到来！"
D.Strings[10875]="集中注意力，不要浪费时间！"
D.Strings[10876]="我的等待太漫长了！"
D.Strings[10877]="要是让我失望的话，就准备接受惩罚吧！"
D.Strings[10878]="抽取她的力量！抽空她，直到她只剩下一具空空的躯壳为止！"
D.Strings[10879]="离毁灭又近了一步！"
D.Strings[10880]="你还能相信谁？"
D.Strings[10881]="敌人就在你们中间！"
D.Strings[10882]="你为什么来到太阳之井？"
D.Strings[10883]="你不是一个人来的？"
D.Strings[10884]="玛蒂苟萨与我结伴而行，但是我们在太阳之井走散了。$B$B愿命运庇护她。"
D.Strings[10885]="基尔加丹为什么会对普通的人类女孩感兴趣？"
D.Strings[10886]="$r，安薇娜绝不是“普通”的凡人。那些家伙一旦感知到蕴藏在她体内的强大能量，就会不择手段地想要将她占为己有。$b$b安薇娜曾经救过我，现在是我报恩的时候了。"
D.Strings[10887]="$c，玩得开心吗？护火者负责照看熊熊燃烧的篝火，而我更像是守护火焰节历史的学者。当然，我还负责记录每年节日庆典的情况。到目前为止，一切都进展得很顺利，你认为呢？$b$b$n，你应该知道，火焰节期间燃起的簇簇篝火都蕴藏着与生俱来的能量。我们照看着自己的篝火，但是在敌人的主城深处，也会燃起这样神圣的火焰……"
D.Strings[10888]="$c，欢迎来到我们的营地。你可以在这里休息。"
D.Strings[10889]="我想从你这里买点什么。"
D.Strings[10890]="这鬼地方什么都没有。"
D.Strings[10891]="我的家人都被残忍地杀害了。连孩子都不能幸免。"
D.Strings[10892]="巫妖王对这片土地所做的一切，足以让他永远在地狱之火中倍受煎熬。"
D.Strings[10893]="我们已经是无家可归的人了。"
D.Strings[10894]="天灾军团是不懂得恐惧的机器，他们只知道摧毁这个世界上所有的生命。"
D.Strings[10895]="被他们称为“地狱咆哮”的那个人恐怕是我们最后的希望了。"
D.Strings[10896]="现在只有部落能救我们了。"
D.Strings[10897]="抽取……生命！"
D.Strings[10898]="解……放！"
D.Strings[10899]="无……法……控制。"
D.Strings[10900]="吞……噬。"
D.Strings[10901]="啊，又来了一群小绵羊！"
D.Strings[10902]="死吧，小虫子！"
D.Strings[10903]="你就是一块肉！"
D.Strings[10904]="太简单啦！"
D.Strings[10905]="来呀，挑战我吧！"
D.Strings[10906]="又一场光荣的战斗！"
D.Strings[10907]="我为杀戮而生！"
D.Strings[10908]="这根本算不上真正的挑战。你们去死吧！"
D.Strings[10909]="啊！干得好！现在……有意思了……"
D.Strings[10910]="基尔加丹万岁！所有敌人都要死！"
D.Strings[10911]="这是你的最后一口呼吸！"
D.Strings[10912]="我比以前更强大了！"
D.Strings[10913]="为了主人，杀了你！"
D.Strings[10914]="别再犹豫了！你们的命运就是如此了！"
D.Strings[10915]="基尔加丹……会胜利的！"
D.Strings[10916]="<巴德强作镇静，假装没有听你讲话。你专注地盯着他，发现一滴口水从他的面具下落下。>"
D.Strings[10917]="<巴德来回扭动，用巨魔语念叨着什么。>"
D.Strings[10918]="走开。"
D.Strings[10919]="朋友，我没功夫和你聊天。我需要休息……"
D.Strings[10920]="别担心。部落会保护牦牛人的。但是你必须发血誓效忠酋长。"
D.Strings[10921]="部落能让我参与对抗天灾军团的战争吗？"
D.Strings[10922]="当然。部落的所有成员都有复仇的权力。"
D.Strings[10923]="我愿意与你们结盟，为我死去的族人，为驱逐贪得无厌的天灾军团。我愿意用我的生命向部落起誓。"
D.Strings[10924]="那就跟我念：“Lok'tar ogar！非胜即死——为了这一信念我宣誓效忠部落。这是所有部落战士最神圣最基本的信条。\n\n我自愿将全部身心奉献给伟大的酋长。我愿意无条件服从酋长的意志和命令。\n\n从这一刻起直到永远——为了部落！”"
D.Strings[10925]="Lok'tar ogar！非胜即死——为了这一信念我宣誓效忠部落。这是所有部落战士最神圣最基本的信条。\n\n我自愿将全部身心奉献给伟大的酋长。我愿意无条件服从酋长的意志和命令。\n\n从这一刻起直到永远——为了部落！"
D.Strings[10926]="为了部落！\n\n从箱子里取些装备来武装自己吧，然后前往东边的阿格玛之锤报到。加入部落之后，你的首要任务是要活下去。\n\nLok'tar ogar！"
D.Strings[10927]="来吧，巴德。和冰巨魔较量的时刻来临了！"
D.Strings[10928]="嘿，朋友！带我去看看那些巨魔兄弟呀！"
D.Strings[10929]="朋友，就让你见识一下巨魔的把戏！"
D.Strings[10930]="这些巨魔朋友今天可有乐子了！"
D.Strings[10931]="嘿嘿嘿！这肯定会非常有趣！"
D.Strings[10932]="朋友，你确信我们没走错路？"
D.Strings[10933]="<嗅，嗅>朋友，我能嗅出他们的气味。"
D.Strings[10934]="敲打脑袋就是表达爱意的完美方式。"
D.Strings[10935]="非胜即死！为了部落！"
D.Strings[10936]="兄弟，来吧！"
D.Strings[10937]="不对，不对。这里没有巨魔……"
D.Strings[10938]="好啦。什么时候才能找到那些巨魔兄弟呀？"
D.Strings[10939]="$n，太阳井之岛的三座大门已被全部摧毁。$B$B集合你的军队，阻止基尔加丹进入艾泽拉斯世界！"
D.Strings[10940]="朋友，这就是巨魔的力量！"
D.Strings[10941]="别大惊小怪的。朋友，你没见过巨魔吗？"
D.Strings[10942]="裂鞭海岸昔日的荣耀不复存在，我发誓，这些混蛋会为此付出代价！"
D.Strings[10943]="“将回到钢铁与岩石的摇篮。”"
D.Strings[10944]="“回到坐落在风暴峭壁的奥杜尔。”"
D.Strings[10945]="“造物主最伟大的子嗣们，索求你们与生俱来的权力吧。”"
D.Strings[10946]="我们必须保护这些牦牛人，并尽可能地安慰他们。"
D.Strings[10947]="这些孩子会活下去的。他们会在关爱中长大，成为坚强的部落勇士。时间会让他们淡忘那些悲惨的过去。"
D.Strings[10948]="$n，再次感谢你为我带来这么好闻的熏香。"
D.Strings[10949]="格里西达，快醒醒。嘿。"
D.Strings[10950]="这里很安全，对吧？他们抓走了乔伊和米克基，我们得躲起来，不能让他们发现。"
D.Strings[10951]="我们已经摆脱那些怪物了！格里西达，他们和我们截然不同。"
D.Strings[10952]="我们是猎人。这里没有狼人。"
D.Strings[10953]="小姑娘，保持警惕！别让他们抓到我们！"
D.Strings[10954]="基尔加丹开始引导黑暗能量。"
D.Strings[10955]="你来晚了！协议已经达成。只剩下一些无关紧要的细节。比如……如何处理你！"
D.Strings[10956]="%s吞噬了薰香。好胃口！"
D.Strings[10957]="真是太棒啦！香味中充斥着能量！"
D.Strings[10958]="熊熊燃烧的火炬就应该散发出这样浓烈的香味！"
D.Strings[10959]="%s放声大笑！"
D.Strings[10960]="就是现在！我们的计划生效啦！"
D.Strings[10961]="渺小的凡人，跪下！向炎魔之王拉格纳罗斯的使者致敬！"
D.Strings[10962]="你们都将在火焰中化为灰烬！"
D.Strings[10963]="%s眨了眨眼……"
D.Strings[10964]="啊。我只是在开玩笑……"
D.Strings[10965]="时局动荡不安，我们却顽强地抵御了天灾军团猛烈的攻势！能成为部落的一员真是荣幸。"
D.Strings[10966]="我能感受到体内涌动的能量！"
D.Strings[10967]="你卖这类东西吗？"
D.Strings[10968]="%s被塞吉刀刃上反射的光芒迷惑了。"
D.Strings[10969]="%s盯着停泊的船只，发出急促的叫声。"
D.Strings[10970]="看着我的刀子，蠢货！看着它，告诉我是谁背叛了我的兄弟！"
D.Strings[10971]="朋友，你在看什么呢？"
D.Strings[10972]="嗯……青蛙说你就是叛徒，我的“朋友”。"
D.Strings[10973]="你发现什么情况了吗？"
D.Strings[10974]="元素之魂躁动不安……"
D.Strings[10975]="真搞不懂为什么有些海盗喜欢把财宝埋起来，你看……我就喜欢将它们放在随手可及的地方。"
D.Strings[10976]="大海龟“踏浪者”将从这个港口游往龙骨荒野的莫亚基港口。"
D.Strings[10977]="联盟的蒸汽动力破冰船“北海之矛”将穿越东部王国的海域，开往湿地的米奈希尔港。"
D.Strings[10978]="莫亚基港口因两只大海龟“踏浪者”和“绿背岛”而闻名。它们往返于乌努比和卡玛古。"
D.Strings[10979]="想去诺森德，是吧？蒸汽动力船“海怪号”将载你前往北风苔原的无畏要塞。"
D.Strings[10980]="想去诺森德的话，就乘坐破冰船“北海之矛”吧。它会载你前往嚎风峡湾的瓦加德。"
D.Strings[10981]="嗨！你想念东部王国了吧？如果你想回去的话，“海怪号”正要返回暴风城。那里的气候肯定比这里温暖得多！"
D.Strings[10982]="大海龟“绿背岛”将从这个港口游往龙骨荒野的莫亚基港口。"
D.Strings[10983]="嗨。你想回到艾泽拉斯世界吗？搭乘“吻云号”返回提瑞斯法林地吧。"
D.Strings[10984]="嗨。你可以乘坐“强风号”前往诺森德。她会载你飞往北风苔原的战歌要塞。"
D.Strings[10985]="$r，诺森德等你去开拓。“吻云号”会载你前往嚎风峡湾的复仇港。"
D.Strings[10986]="$c，想回家吗？如果你住在卡利姆多的话，“强风号”可以送你一程。她将直接飞往杜隆塔尔。"
D.Strings[10987]="快！快！这些武器必须今天送抵库卡隆先锋营地！"
D.Strings[10988]="如果能用地精将你们统统替换掉，我会很高兴的！别让我失望！"
D.Strings[10989]="阿格玛大王等着我们的好消息呢！我们不能让他失望！"
D.Strings[10990]="别逼我从箱子上跳下来！我会把你痛打一顿的。"
D.Strings[10991]="嘿，美人儿，塞布坦有两条毯子！为什么不过来一起暖和缓和呢，嗯？"
D.Strings[10992]="看看塞布坦要送你什么！玫瑰赠佳人！"
D.Strings[10993]="%s咕哝着。"
D.Strings[10994]="除非艾泽拉斯世界的其他巨魔都死绝了！"
D.Strings[10995]="真恶心！！！"
D.Strings[10996]="没门！"
D.Strings[10997]="放开我！"
D.Strings[10998]="我已经心有所属了！你给我滚远点！"
D.Strings[10999]="这个巨魔以为你喜欢上他了！哈哈！"
D.Strings[11000]="别害羞啦。你难道感觉不到爱情之火在燃烧吗？"
D.Strings[11001]="小毛球，准备好了吗？靠近我，小心这些狼！"
D.Strings[11002]="嗯……有头狼折回来了……"
D.Strings[11003]="他是来抓小毛球的！"
D.Strings[11004]="我们必须冲出去，否则狼群就要来了！"
D.Strings[11005]="噢，不！又来了一头狼，好大！！！"
D.Strings[11006]="别朝有光的地方跑，小毛球！"
D.Strings[11007]="小毛球，你竟然没事！谢谢你救了小毛球，太感谢了！"
D.Strings[11008]="悬赏猎杀部落叛徒！$B$B赏金由高尔特上尉提供。"
D.Strings[11009]="开始传送吧，我准备好了！"
D.Strings[11010]="欢迎你，$c！希望你没有恐高症！$b$b我为你准备了练习用的降落伞。它们是在紧急着陆时使用的。如果你想要缓缓落地，还不如骑着坐骑随便蹦两下呢。如果你想体验极速快感，就要从高处跳下来，在快到落地时打开降落伞！动作要快！你的反应够快吗？$b$b降落伞的效果只能持续几秒，因此你必须在适当的时机使用它。不知道你能不能掌握其中的诀窍。希望你成功。"
D.Strings[11011]="你好啊，伙计！坐下来喝一杯吧，怎么样？"
D.Strings[11012]="再来两杯好酒，马克。"
D.Strings[11013]="趁他虚弱时发动攻击！杀死基尔加丹！"
D.Strings[11014]="嘘……这里，邮箱旁边。快过来，你没有被跟踪吧。"
D.Strings[11015]="放我出去，朋友！"
D.Strings[11016]="你最好祈祷我永远也出不来！"
D.Strings[11017]="杀！"
D.Strings[11018]="我一直希望能再次为国王效劳。出于人道精神，一起对抗共同的敌人。$B$B但是我发现有教徒混进了我们中间……而所有证据都表明，纳克萨纳尔就是这场灾难的源头。"
D.Strings[11019]="教徒接到的指令都来自于他们的首领。这家伙也许很快就会出现。$B$B这是个好机会。"
D.Strings[11020]="动手吧，萨萨里安。否则就再也没机会了。"
D.Strings[11021]="怎么回事……我怎么了？"
D.Strings[11022]="萨萨里安！你还活着！"
D.Strings[11023]="我还以为……还以为你已经死了。"
D.Strings[11024]="莉蕾萨……你……你没事吧？"
D.Strings[11025]="我还不能跟你回家，莉蕾萨。我和天灾军团之间的账还没有算清呢。"
D.Strings[11026]="也许你是对的，莉蕾萨。我早已经不再亏欠我的祖国和国王任何东西，可是……我还欠自己一个交代。"
D.Strings[11027]="啊……我感到头晕目眩。"
D.Strings[11028]="别再离我而去了！你想为你的祖国而战，可你的祖国根本不愿意接纳你！他们派你来送死！"
D.Strings[11029]="你的眼神说明了一切……我说服不了你。别再让我听到你的噩耗了……"
D.Strings[11030]="别担心，莉蕾萨。我完成使命后就回去找你。那时，世界上就再也没有任何东西能阻挡我回家的脚步了。"
D.Strings[11031]="朋友，这里到处都是天灾军团！"
D.Strings[11032]="$n，为什么召唤我？你和这里的巨魔在策划什么阴谋？你想要杀死我，夺取我的力量吗？"
D.Strings[11033]="朋友，各自保命吧！"
D.Strings[11034]="达克萨隆要塞失守了！"
D.Strings[11035]="快跑！"
D.Strings[11036]="凡人，你犯了个致命的错误……别想逃跑……"
D.Strings[11037]="叛徒！审判之日已经来临，你的死期也到了！我倒要看看你效忠的巫妖王能否让你逃脱命运的审判！死吧！"
D.Strings[11038]="安薇娜的牺牲为我们带来了新的希望。"
D.Strings[11039]="你是卡鲁亚克氏族的朋友？我对此持保留意见。如果你想让我为他们占卜的话，就先证明自己的忠诚吧。"
D.Strings[11040]="我要你做的事也不算太过分。当着我的面跳入深海吧，这样你才能与我的精神融合，以此表达你的诚意。"
D.Strings[11041]="虽说我提出了要求，不过你可以选择跳或是不跳。我给你20秒做决定。"
D.Strings[11042]="$n，你拒绝了我的要求。那么我也拒绝占卜卡鲁亚克氏族的命运。在你鼓起勇气接受挑战之前，别再召唤我！"
D.Strings[11043]="很好，$n。你充分表达了自己的诚意。我会如约告诉你关于卡鲁亚克氏族的命运，请转告他们吧。"
D.Strings[11044]="请你转告卡鲁亚克海象人，逃亡是没有出路的。一旦选择逃亡，他们的灵魂将被诺森德滋生的邪灵毁灭。"
D.Strings[11045]="告诉秘法师，卡鲁亚克氏族必须与部落和联盟并肩战斗，共同抵抗玛里苟斯和巫妖王的军队。"
D.Strings[11046]="你的使命已经达成，游回去吧。尽你所能地帮助他们，$r。"
D.Strings[11047]="嗯？干什么？！走开。"
D.Strings[11048]="如果能制造出新型的空中作战机器，我肯定能在天谴之门大赚一笔。$B$B我们进行过多次尝试，但是效果并不……理想。可别小瞧我的飞行器，一旦我鼓捣出完善的轰炸系统，它就能成为彪悍的战斗机。"
D.Strings[11049]="趁这时候赶紧捞钱啊！我老爸经常说：战争是发横财的绝好机会。"
D.Strings[11050]="站在这尊远古神像前，你产生了某种异样的感觉。"
D.Strings[11051]="数千年来存放预言者之眼的位置如今已是空空如也。"
D.Strings[11052]="从神像脸上取下预言者之眼。"
D.Strings[11053]="朋友，等你的好消息。"
D.Strings[11054]="欢迎！想找地方休息的话，我能为你提供食宿服务哦。"
D.Strings[11055]="我们要杀死阿尔萨斯！即便是天灾军团，也不能与部落抗衡！"
D.Strings[11056]="别让他们靠近！"
D.Strings[11057]="你在寻找竞技场管理员吗？他们在城镇之间来回行走，或是呆在主城。$B$B你可以将炉石绑在这儿。我还能将你传送到任意主城去。"
D.Strings[11058]="将这座村落夷为平地吧！"
D.Strings[11059]="放弃吧，牦牛人！你们不是天灾军团的对手！"
D.Strings[11060]="我……自由了！"
D.Strings[11061]="他们对我的族人做了什么……"
D.Strings[11062]="你将为自己的所作所为付出代价，接受先祖的惩罚吧！"
D.Strings[11063]="重生吧，我的兄弟……站起来……再次投入战斗。"
D.Strings[11064]="为了冰雾村！为了牦牛人！"
D.Strings[11065]="别以为你们从此就高枕无忧了！"
D.Strings[11066]="巨大的冰虫张开大嘴，颤抖了一会儿。"
D.Strings[11067]="来和我较量较量吧！"
D.Strings[11068]="我会击败你的！风啊，让我飞翔吧！"
D.Strings[11069]="傲慢的凡人！你死定了！"
D.Strings[11070]="啊！！这不可能！怎么会……"
D.Strings[11071]="嗨！菲兹兰克的飞行员都是王牌中的王牌呀。坚持训练是我们保持领先的秘诀。这其中就包括了跳伞训练。你永远也不知道什么时候会用到降落伞，但是迟早你会用上的。$b$b因此，我们设置了通往塔顶的传送装置。如果你是真正的士兵，就勇敢地拉开降落伞跳下来吧。塔顶有一位军官，负责提供降落伞包。$b$b$c，想要接受训练的话，我就教你如何使用传送装置。喏，你只需要踩在上面就是了。"
D.Strings[11072]="钢铁之王，请在战斗中助我一臂之力！"
D.Strings[11073]="碾碎这些小矮子！"
D.Strings[11074]="可怜虫，我们要杀死你！"
D.Strings[11075]="钢铁之子，助我一臂之力吧！"
D.Strings[11076]="敌人越战越勇！快帮帮我！"
D.Strings[11077]="没有谁能阻止我们完成使命！"
D.Strings[11078]="为洛肯的荣耀而战！"
D.Strings[11079]="蠢货，你替库伦卖命是毫无意义的！"
D.Strings[11080]="去死吧，石头的盟友！"
D.Strings[11081]="%s飞走了。"
D.Strings[11082]="朋友，你不应该朝北航行的！"
D.Strings[11083]="阿努布耶坎被打败了！随便捡一块虫壳碎片，作为你获胜的证明吧！"
D.Strings[11084]="你最好滚远点，除非你也想尝尝被关进牢笼的滋味……"
D.Strings[11085]="$c，谢谢你，自从收到兄弟的来信后，我就一直在关注这件事。$B$B他的牺牲总算不是徒劳的，愿他的灵魂安息。蓝龙军团会付出惨痛的代价的。$B$B我等着这一天！"
D.Strings[11086]="好吧，孩子。退到我身后去，免得伤到你。"
D.Strings[11087]="仪式大厅，他们本打算在那里将我作为祭品的……"
D.Strings[11088]="是时候阻止这一切了！"
D.Strings[11089]="奇怪。怎么不对劲呢。"
D.Strings[11090]="士兵，阻止天灾军团的行动！随时向我汇报情况。一旦你发现可疑的人物，不管是谁，先杀了再说！"
D.Strings[11091]="记住我说过的话，这帮愚蠢的被遗忘者迟早会毁了我们！"
D.Strings[11092]="你问我的意见？我觉得我们应该趁早杀掉所有的药剂师！"
D.Strings[11093]="部落是为荣耀与战斗而生的。这帮药剂师肯定在干什么不光彩的勾当。"
D.Strings[11094]="我始终留意着这群白痴的一举一动。真是怎么提防都不为过！"
D.Strings[11095]="这是什么？"
D.Strings[11096]="啊！！蛇！"
D.Strings[11097]="%s向你致谢。"
D.Strings[11098]="离开前，%s从身上剥下一块树皮递给你。"
D.Strings[11099]="%s对你提出的要求感到非常愤怒，朝你发动了攻击！"
D.Strings[11100]="如果你要和那些医师打交道的话，千万当心。他们一定在干什么不正常的勾当。"
D.Strings[11101]="朋友，西边那片荒野上都是尸体。如果你还想活命的话，就离开这里！"
D.Strings[11102]="我已经受够这个地方了。"
D.Strings[11103]="你可以走了，小姐。"
D.Strings[11104]="我在阿格玛之锤的工作远不止照料兽栏里的动物这么简单。"
D.Strings[11105]="听着，孩子。交给我解决吧。你站在我身后看着就好啦！"
D.Strings[11106]="再见，孩子！"
D.Strings[11107]="死？我吗？嘿嘿，还早着呢。那次不过是点小擦伤。"
D.Strings[11108]="趁现在！抬起那根木材就跑吧。部落不会打上一辈子仗，眼下正是赚钱的好机会呀！"
D.Strings[11109]="很震撼吧？这些巨人简直是完美的炮灰……呃，是盟友啦。这位就是他们的首领，但他一直拒绝和我谈话。"
D.Strings[11110]="你好，$r。你也是为了躲避巨龙才来到这条峡谷的吧，我们欢迎你啊。但是你要当心那个矮小的家伙……地精就没一个可靠的。"
D.Strings[11111]="只要有足够的钱，我就能征服全世界……"
D.Strings[11112]="这个控制台后面是一大堆碎石块。发动机的声音从地下传来。"
D.Strings[11113]="蠢货！你永远别想逃脱！"
D.Strings[11114]="你竟敢挑衅钢铁的子嗣？"
D.Strings[11115]="旅行者，欢迎来到龙眠神殿。$B$B这里供奉着巨龙先祖的遗骸，是巨龙们商谈要事的圣地。$B$B但是最近，蓝龙军团突然对神殿发动攻击，打破了持续数千年的宁静。$B$B带着我们的祝福进入神殿吧，但是请谨记，我们绝不允许任何挑衅行为。"
D.Strings[11116]="你连祭品都没有准备就敢召唤我！"
D.Strings[11117]="$c，你想回去？$B$B我可以派一条幼龙将你安全地送达目的地。"
D.Strings[11118]="嗯，我想返回神殿底层。"
D.Strings[11119]="别来烦我，蠢货！"
D.Strings[11120]="你是不可能摆脱宿命的，明白吗？你不过是个孩子。"
D.Strings[11121]="小姑娘，你才多大？"
D.Strings[11122]="最终，我们都会成为巫妖王的仆从。孩子，这比变成一具腐烂的尸体好多了。"
D.Strings[11123]="你的父亲是个懦夫，萨莎……他没有勇气完成自己的使命。"
D.Strings[11124]="别小瞧我，我也能一箭射中野兽的眉心……而且是在两倍距离开外。"
D.Strings[11125]="我宁愿死也不要变成你们那副模样！你们还是人吗？是……畜生！"
D.Strings[11126]="你居然敢侮辱我的父亲。他比你勇敢得多。"
D.Strings[11127]="嗯？$c，你想接受我的训练？那你最好做好准备。"
D.Strings[11128]="我必须返回阴影世界，库尔迪拉。送我回去吧。"
D.Strings[11129]="如果你愿意的话，就去兵营休息吧。但不要吵醒我的士兵，不然我会亲手将你扔到雪地里。"
D.Strings[11130]="谢谢你救了我，$n。我永远不会忘记你的勇气和决心。"
D.Strings[11131]="大酋长，您好。请问您是否愿意接受我的邀请，以牦牛人首领的身份正式加入部落呢？"
D.Strings[11132]="$n，能以部落的兄弟的身份与你并肩作战是我的荣幸。我接受你的提议。"
D.Strings[11133]="大酋长，这是我的荣幸才对。喏，这份卷轴就是结盟的誓约，请您过目。"
D.Strings[11134]="%s让其他牦牛人都聚集在他身边，并按照卷轴上的内容诵读了誓言。"
D.Strings[11135]="$n，让我们并肩战斗吧。"
D.Strings[11136]="同胞们，集合。"
D.Strings[11137]="Lok'tar ogar！不胜利，毋宁死——正是这条被所有的部落成员奉为真理的信条促使我加入部落！"
D.Strings[11138]="我发誓终身效忠于萨尔酋长。他的意志就是我的信条。他的指令就是我的使命！"
D.Strings[11139]="从这一刻直到我阖上双眼——为了部落！"
D.Strings[11140]="为了我们的牦牛人同胞！为了部落！"
D.Strings[11141]="欢迎加入部落，大酋长。Lok'tar ogar！"
D.Strings[11142]="除非你亲手杀死一条龙，否则我可不认你这个朋友……"
D.Strings[11143]="还有什么比猎杀巨龙更惊心动魄的呢。"
D.Strings[11144]="你好，$r。这是你首次踏上我们的圣地吧，让你目睹这样的情景真是抱歉。"
D.Strings[11145]="终于自由啦。"
D.Strings[11146]="朋友，我要永远沉睡了……"
D.Strings[11147]="我的木乃伊在哪里？"
D.Strings[11148]="总算可以休息啦……"
D.Strings[11149]="开始收集能量。"
D.Strings[11150]="能量收集完毕。"
D.Strings[11151]="为什么打搅我？"
D.Strings[11152]="我要去永生之盾。"
D.Strings[11153]="嘿！需要什么东西，直接告诉我就行啦。"
D.Strings[11154]="可恨的天灾军团……他们很快就会得到报应的。"
D.Strings[11155]="辛克的伐木机已经就绪，随时摧毁林地。"
D.Strings[11156]="辛克的伐木机的安全功能已经激活。正在返回营地。"
D.Strings[11157]="如果你饿了，我这里有食物；如果你需要休息，可以钻进我的帐篷。"
D.Strings[11158]="%s获得了燃料。"
D.Strings[11159]="保护？为什么？那绝不是真理所在。不不不……要夺取！我现在终于明白了！"
D.Strings[11160]="外面或许没有下雪，不过这里的夜晚能把你的鼻子给冻掉。床铺就在后面——别招惹是非就是了。"
D.Strings[11161]="嗨。没有谁要故意为难你啦，不过你最好另找地方过夜。瞧你这身细皮嫩肉的，我不忍心让你吃苦。"
D.Strings[11162]="进来坐在火堆旁休息一下吧，$r。希望你不要介意鱼腥味儿。"
D.Strings[11163]="在险峻秀丽的海加尔山，在黄沙滚滚的希利苏斯，我们肩负着与燃烧军团抗衡的重任，血战到底。我们无名无姓，默默无闻，但我们都是联盟的英雄儿女。在圣光的指引下，我们冲锋陷阵，无坚不摧。$B$B我们就是第七军团。"
D.Strings[11164]="小家伙，你在寻找他们的首领……你竟然想要挑战雷霆使者戈洛塔尔领导的猛犸人氏族。别急着去送死吧。"
D.Strings[11165]="哈！好吧。碧蓝巨龙圣地以南有一处火炬环绕之地，在那里吹响猛犸人首领号角。向你信奉的诸神祈祷吧……戈洛塔尔就会出现。"
D.Strings[11166]="谢谢你救了我，我的同胞还被关押在上面几层！"
D.Strings[11167]="谢天谢地！我正担心他们会不会强迫我去对付石巨人呢！"
D.Strings[11168]="这帮铁矮人疯子！他们反复谈论要为“洛肯大人”效劳，但是据我所知，只有少数人接到他的指令而已。"
D.Strings[11169]="你好！需要什么吗？"
D.Strings[11170]="啊！！发生了什么事？"
D.Strings[11171]="那个没用的巨魔再度失败了。我的容忍已经到了极限！安希斯！给我打断他的腿！"
D.Strings[11172]="我立即去办！"
D.Strings[11173]="我还没见过你如此迫切地想要给他人留下痛苦的回忆呢。这是进步呢……很好，去吧！"
D.Strings[11174]="监工，进展太缓慢了。"
D.Strings[11175]="命运不会为谁停留。在石巨人大军抵达奥杜尔之前，你必须监督工匠提高作战魔像的产量。"
D.Strings[11176]="告诉你手下的符文铁匠，必须加紧改造石巨人。摧毁那些不服从指令的家伙。"
D.Strings[11177]="如果石巨人胆敢阻挠我们在奥杜尔的工事，我就撤消你和你的领主的权利。绝不允许凡人帮助巨人。"
D.Strings[11178]="回到你的岗位上去吧，监工。必须让工匠们明白任务的急迫性。"
D.Strings[11179]="我设计的掷杯训练器不只是用来训练扔酒杯的，它还是非常有价值的训练设施。如果你能击中它，就可以击中任何东西！$B$B不要击中我就行了。"
D.Strings[11180]="让我们瞧瞧这管不管用。"
D.Strings[11181]="注意！"
D.Strings[11182]="矮人，欢迎拜访欧尼瓦营地的牦牛人。"
D.Strings[11183]="如果你愿意帮助我们抵御共同的敌人，我们保证不伤害你。"
D.Strings[11184]="考虑一下吧，勘查员，希望你能尽快做出决定。我们必须立即采取行动。"
D.Strings[11185]="步兵，我能闻到你身上的土臭味儿。换班之前，向主教报到吧。"
D.Strings[11186]="高级执行官乌洛斯负责发送悬赏令的奖励。$B$B有诚意者请入内咨询。$B$B谢绝中介！"
D.Strings[11187]="摧毁那些行尸走肉……我当然是指天灾军团。"
D.Strings[11188]="乔伊，是你。真的是你！"
D.Strings[11189]="冷静。我是想问你关于铁矮人和洛肯的情况。"
D.Strings[11190]="你来这里干什么，小家伙？"
D.Strings[11191]="关于铁矮人和洛肯，你都知道些什么？"
D.Strings[11192]="乔伊怎么会问这样的问题！好吧，我确实知道洛肯的事。"
D.Strings[11193]="他也在找我的麻烦呢！如果我是你的话，我在这一带走动时会额外小心的。你永远都不知道他会躲在哪棵树后面！"
D.Strings[11194]="啊，是的。我对洛肯非常了解。"
D.Strings[11195]="他指挥钢铁的子嗣，对我们发动了战争。"
D.Strings[11196]="他藏身在不为人知的角落，监督着战争的准备工作，想要消灭石巨人！"
D.Strings[11197]="你能来真是太好啦，我的孩子。圣光对你的眷顾正在消退。"
D.Strings[11198]="好了。好好为圣光效劳。"
D.Strings[11199]="笨手笨脚的蠢货！"
D.Strings[11200]="你把这批样本完全搞砸了！你还有什么可辩解的？"
D.Strings[11201]="<海象人怀疑地打量着你。>$b$b别在此地久留。你并不了解我们，我可希望招惹什么麻烦。"
D.Strings[11202]="但是……我是严格按照你的指令做的！我该说对不起吗？"
D.Strings[11203]="对不起？就会说对不起？！我对你太失望了！"
D.Strings[11204]="哎呀。我觉得这玩意儿起作用啦！真奇怪。"
D.Strings[11205]="耶！"
D.Strings[11206]="天空并不安全，朋友。要小心！"
D.Strings[11207]="凡人，当你在伊瑟拉的花园中走动时，请随时保持警惕。别轻易相信你所看到的一切。"
D.Strings[11208]="等我处理完收尾工作，就换个新助手！"
D.Strings[11209]="你需要什么？要不要修理一下护甲或是武器？嗯？"
D.Strings[11210]="$c，在这个黑暗的时代，我们必须铤而走险。"
D.Strings[11211]="有什么我可以尝试的玩意儿吗？"
D.Strings[11212]="黑暗就蛰伏在这片秀丽的山岭下。朋友，千万当心。"
D.Strings[11213]="厕所好像被占用了。"
D.Strings[11214]="小心，周围可能有那些传播着巫妖王诅咒的爪牙。"
D.Strings[11215]="愿圣光净化你，勇敢的$n。"
D.Strings[11216]="我的父亲将他的作战盔甲和斧头都送给我啦。很快我就能好好利用它们了。"
D.Strings[11217]="真幸运，厕所现在没人。"
D.Strings[11218]="上厕所。"
D.Strings[11219]="我们的食物和饮料储备已经出现短缺。恐怕我没什么能给你的。"
D.Strings[11220]="谢谢你的帮助，$n。这些冰莓就当作你的劳动果实吧。"
D.Strings[11221]="我要消灭你们！"
D.Strings[11222]="你不是猛犸人！你的……力量……是……怎么来的？"
D.Strings[11223]="我真是选了个戒酒的好日子啊！"
D.Strings[11224]="谢谢你的帮助，勇士！"
D.Strings[11225]="你救了我！谢谢！"
D.Strings[11226]="你真的懂得如何驾驭狮鹫吗？我怎么觉得有点晃悠悠的？"
D.Strings[11227]="我不是忘恩负义的家伙啦，但是你能飞得再低一点吗？我恐高！"
D.Strings[11228]="当我得知北方还有宗亲时，就满心欢喜地赶来寻访。可我见到的全是侵略性极强的部族，他们身上完全没有和平的天性。$B$B$c，我很绝望。就连伟大的乌索克都没能逃过堕落的命运。$B$B我已经丧失了所有希望。"
D.Strings[11229]="你真是我的守护天使！你就像来自天堂的白衣骑士，将我从地狱的深渊中解救出来！"
D.Strings[11230]="我该怎么报答你呢，朋友？"
D.Strings[11231]="我有点头晕……呕……"
D.Strings[11232]="站到我身后，$r。我会尽力保护你的。"
D.Strings[11233]="如果不能拯救乌索克，那我的自由也就毫无意义了。要快，$n。"
D.Strings[11234]="我会保护你和你的盟友，$r。"
D.Strings[11235]="图尔，变成熊形态吧。"
D.Strings[11236]="帮我们制伏他。"
D.Strings[11237]="我们需要一名治疗者。"
D.Strings[11238]="我们已经净化了沃达希尔的树苗。如果能制伏乌索克，我们或许能治愈他的灵魂。"
D.Strings[11239]="是的……我能感觉到沃达希尔的魔法能量……没有丝毫被污染的迹象。$B$B让我帮助你吧！命运让我来到这里，或许我能帮上忙的！"
D.Strings[11240]="终于安全了！谢谢你，陌生人！"
D.Strings[11241]="万岁！"
D.Strings[11242]="乌瑞克，这位勇士真是太善良了。谢谢你，英雄！"
D.Strings[11243]="我们成功了！我们真的成功了！"
D.Strings[11244]="我的店门将永远对你敞开，朋友。"
D.Strings[11245]="我们不会忘记你的英勇行为，$n。你永远是暮冬城的客人。$B$B你愿意将这座旅馆当作自己的家吗？"
D.Strings[11246]="我想看看你出售的货物，伊露希亚。"
D.Strings[11247]="塞巴鲁斯打心眼儿里感激你。若不是你，我早就没命啦，说不定还会变成亡灵的一员……"
D.Strings[11248]="%s呻吟着，但是似乎并没有受到感染。"
D.Strings[11249]="你的信仰很坚定，孩子。继续做事吧。"
D.Strings[11250]="你需要主教大人的祝福。快去找他吧。"
D.Strings[11251]="你这个不洁者！"
D.Strings[11252]="阿比迪斯大人将会净化你！"
D.Strings[11253]="你将被净化！"
D.Strings[11254]="以圣光之名！"
D.Strings[11255]="圣光在上！"
D.Strings[11256]="钢铁的利刃将你净化！"
D.Strings[11257]="你竟敢干扰我们正义的事业？！"
D.Strings[11258]="我曾经以乌索克之子的身份在灰熊丘陵巡游，统治着这片领地。$B$B如今……我却只能窝在洞穴中苟延残喘，度过悲惨的余生。"
D.Strings[11259]="奥索恩，你随时可以离开，但是请先告诉我熊怪们到底出了什么事。"
D.Strings[11260]="你不能理解我的处境。我真想出去的话，早就杀出一条血路离开这个洞穴了。$B$B可我不能丢下父亲乌索克不管啊。他复活了……却不再是从前的心性。$B$B在数千年前的上古之战中，我的父亲就已经阵亡。崇拜他的熊怪部族一直想要复活他。$B$B最终他们决定重新培植那株被德鲁伊砍倒的世界之树——沃达希尔，企图利用它的力量复活我的父亲。"
D.Strings[11261]="小声点，$c。没瞧见我正穿着伪装为怨毒镇侦察吗？"
D.Strings[11262]="他们种下的树苗结出了一枚果实。最初一切都进展顺利。乌索克真的复活了，我也完全沉浸在这短暂的喜悦中。$B$B很快我就察觉到，他与生前截然不同。那些熊怪也发生了转变。$B$B当年，德鲁伊们因为不堪世界之树被邪恶力量所腐化，忍痛砍倒了沃达希尔。如今，新生的世界之树再度成为滋生邪恶的温床，令所有的熊怪变成了嗜血的野兽。$B$B出没在灰熊丘陵的怪物不再是我的父亲了，必须让他得到安息。"
D.Strings[11263]="谢谢你，乌索克之子。我会力所能及地帮助你。"
D.Strings[11264]="我是科蒂安，乌索克的女儿。我守护着这座曾经被视为圣地的祭坛。$B$B很久以来，都没有陌生人到这里来拜访了。"
D.Strings[11265]="这位陌生人是谁？"
D.Strings[11266]="他是一只名叫图尔·怒爪的熊怪。嗯，不属于我们的氏族。$B$B他来自南部的木喉部族。$B$B图尔想见见乌索克。他觉得有希望净化沃达希尔的污染，并借此拯救我的父亲。$B$B抱着这样的希望未免有些天真。等你亲眼目睹我的父亲受到的黑暗污染之后，你就能认同我的看法了。"
D.Strings[11267]="谢谢你，科蒂安。我会尽力的。"
D.Strings[11268]="天哪，我漂亮的小磨坊！你！我要你为此付出性命！"
D.Strings[11269]="总算来了一份有价值的祭品！"
D.Strings[11270]="乌索克，乌索尔的兄弟，熊怪部族的守护者……现身吧！"
D.Strings[11271]="谢谢你们。将沃达希尔砍倒的德鲁伊做出了明智的决定，蛰伏在地底的远古邪灵已经侵淫了那棵世界之树的根须。"
D.Strings[11272]="你们将这种生物称为上古之神。它就是尤格-萨隆，拥有一千张嘴的怪物。它通过沃达希尔的根须散播着邪恶之力。"
D.Strings[11273]="你能带我离开这里吗，$C？"
D.Strings[11274]="不行，斯克尼德。你的日子到头了！"
D.Strings[11275]="啊，你是来救我的吧。快带我离开这个鬼地方！"
D.Strings[11276]="今天不行，首席抄写员！"
D.Strings[11277]="嘿！我觉得我好像在哪儿见过你。$B$B不如救我出去，怎么样？"
D.Strings[11278]="不行。你担任卫生设备工程师的日子到头了。"
D.Strings[11279]="我根本不知道出了什么状况。我刚到怨毒镇没多久，就突然在睡梦中被关进了牢笼！$B$B你是来救我的吗？"
D.Strings[11280]="不行，司法官。从本质上讲，我并不是来“营救”你的。"
D.Strings[11281]="什么叫我的日子到头了？！把话说清楚，不然我宰了你！"
D.Strings[11282]="你不会是想……我要把你的罪行详细记录下来，$C！"
D.Strings[11283]="你一看就是个大好人，放我出去吧！"
D.Strings[11284]="谁放我出去呀？我还要返回怨毒镇换班呢。"
D.Strings[11285]="不！我求求你！千万别杀我！"
D.Strings[11286]="这到底是什么意思？！住手！他们付你多少？？我可以给你两倍的钱！"
D.Strings[11287]="我刚刚到怨毒镇啊，怎么可能招惹到你？"
D.Strings[11288]="你好，$c。$B$B我能帮上什么忙吗？"
D.Strings[11289]="托瓦德·埃里克森领主的始祖龙被锁链拴在这儿，它是一只脾气暴躁、喜怒无常的凶兽。"
D.Strings[11290]="解开烈焰使者的锁链并控制它。"
D.Strings[11291]="战士们，站起来为你们的新主子而战吧！"
D.Strings[11292]="谢谢你，善良的灵魂。"
D.Strings[11293]="我永远不会忘记你的，朋友。"
D.Strings[11294]="终于，来了一位英雄！"
D.Strings[11295]="你来得正是时候，英雄！我差点被那畜生给吃了！"
D.Strings[11296]="要玩玩吗？"
D.Strings[11297]="让他们陪伴你吧，巫妖王向你致意！"
D.Strings[11298]="别急着逃走呀！我还有份“饯别”礼物呢……"
D.Strings[11299]="呸！我什么都不会告诉你，肮脏的$r，！"
D.Strings[11300]="等等……等等！你到底想知道什么啊？！我知道你是个名叫$n的$C。"
D.Strings[11301]="噢……不！我们知道是你偷了我们的盔甲、武器，还有马匹！"
D.Strings[11302]="我们知道……你们无法理解……为什么我们……对所谓的病菌免疫。海军上将巴利·韦斯温似乎向高阶修士传授了什么祷言。啊啊，求你了……住手……好吗？！"
D.Strings[11303]="啊啊啊啊啊！求求你……我们……知道……有间谍……混进了……我们中间！我……我……我就知道这么多啦。求求你……发发慈悲吧……停手呀！"
D.Strings[11304]="我告诉你……我……什么……都不知道！"
D.Strings[11305]="求你……住手。我……我什么都愿意做……"
D.Strings[11306]="让一切……结束吧。"
D.Strings[11307]="他们……都在……乞求……活命!"
D.Strings[11308]="每两年竞争之魂就会变得特别狂躁……喏，就是现在！我们要穿上这件战袍进入战场并击败敌人，以此获得竞争之魂的青睐。"
D.Strings[11309]="我求求你……住手。"
D.Strings[11310]="你别想……从我这里……得到……任何东西！"
D.Strings[11311]="啊啊啊啊啊啊啊啊啊啊！"
D.Strings[11312]="你只需要进入任意战场英勇作战就行了。无论胜负，只要你坚持到最后一刻，就能收到我们邮寄给你的竞争者的战袍。"
D.Strings[11313]="你必须进入任意战场并击败敌人。获胜之后，你就有可能收到我们邮寄给你的金色勋章。"
D.Strings[11314]="你知道竞争之魂吗？$B$B每两年它们就会接近我们的世界。在此期间，联盟或是部落的成员都可以穿着竞争者的战袍进入战场，以此赢得竞争之魂的青睐。$B$B我收集了一些相关的纪念品。如果你知道那段密语的话，我或许可以送你一些……"
D.Strings[11315]="$n，很快我们就明白了死亡在这片冰封之地意味着什么。诺森德弥漫着巫妖王的邪恶力量，这种力量甚至渗透每一寸土地！他唤醒了那些在战斗牺牲的将士，命令他们与我们为敌。$B$B复活的狮鹫骑士随同地面的亡灵大军对我们发动了枪林弹雨般的猛烈攻击。"
D.Strings[11316]="克雷娜对我的能力颇有质疑。她派出最精锐的将士对付联盟以及他们的猎户盟友，让他们执行针对冰霜巨魔的大规模作战计划，却让我与这帮粗俗的掠龙维库人周旋。$B$B或许我们应该联手，共同改变我们在征服者眼中的形象。"
D.Strings[11317]="欢迎来到琥珀松木营地，$C。"
D.Strings[11318]="首席抄写员巴里加被关在哪儿？"
D.Strings[11319]="他似乎被关在伐木场附近的某个牢笼。"
D.Strings[11320]="你知道他们把卫生设备工程师布尔克带到哪儿去了吗？"
D.Strings[11321]="他应该被关押在修道院的南边。"
D.Strings[11322]="知道他们把亡灵卫兵斯克尼德关在哪儿了吗？"
D.Strings[11323]="她应该被绑在绞刑架下。"
D.Strings[11324]="你能告诉我他们把司法官亚麦关在哪里了吗？"
D.Strings[11325]="我看见他被带往修道院北边了，就在箭靶附近。"
D.Strings[11326]="增援！我们需要增援！"
D.Strings[11327]="帮帮忙啊！我抗不住了！"
D.Strings[11328]="你不知道？猎户？他们已经不是人类了……我们必须离开这里！快走！"
D.Strings[11329]="牵走杜卡尔的马吧，他已经彻底沦陷了！"
D.Strings[11330]="这里发生了什么事，长官？"
D.Strings[11331]="我不知道。为了安全起见，最好将他们统统杀掉！"
D.Strings[11332]="帮帮我！帮帮我！这家伙偷走了我的影像！"
D.Strings[11333]="我知道你为什么会来这里——平原上那些愚蠢的猛犸人多管闲事，竟然胆敢与龙族交战。当他们的走狗很有趣吗？"
D.Strings[11334]="愚蠢的$g小子:小丫头;……你竟然敢打扰我的工作，受死吧！"
D.Strings[11335]="不……天哪！你都做了什么？！竟然杀死了这么多远古巨龙……这是什么魔法？"
D.Strings[11336]="你好，$c。$b$b你想去风险湾吗？"
D.Strings[11337]="什么？没看见我正忙着吗？$B$B难道你觉得这玩意儿能自动恢复正常？！"
D.Strings[11338]="伯瓦尔·弗塔根公爵一直都在为正义的事业奋斗。要不是他，阿尔萨斯没准已经坐上了暴风城的王座。"
D.Strings[11339]="啊，这种矿石，我差一点就能想出眉目来啦！只要灵光一闪，我就能给出答案！"
D.Strings[11340]="你们被骗了！血色先锋军都是骗子！天灾军团和被遗忘者不是我们的敌人！醒醒吧！"
D.Strings[11341]="阿比迪斯将军亲口对我说，北征诺森德是个错误，我们被诅咒了！我奉劝你们赶紧放下武器，趁早离开这里！"
D.Strings[11342]="与血色先锋军断绝关系！别再听信将军和元帅编造的谎言了！"
D.Strings[11343]="阿比迪斯就是个臭婊子！海军上将巴利·韦斯温也不过是个皮条客，他以低廉的价格出卖了阿比迪斯，就像出卖我们一样！"
D.Strings[11344]="毁灭结界正在充能。"
D.Strings[11345]="毁灭结界充能完毕！"
D.Strings[11346]="嗨，$c！$b$b你打算前往风险湾对付部落吗？"
D.Strings[11347]="是的，我已经准备好前往风险湾了！"
D.Strings[11348]="很好。看来不派你去好好地教训他们一下，他们是搞不清楚状况的。"
D.Strings[11349]="喂，是谁在鸣钟？"
D.Strings[11350]="孩子，有事吗？"
D.Strings[11351]="请问我能不能与您单独谈一谈？"
D.Strings[11352]="<高阶修士打量了你一番，然后露出了笑容。>$B$B孩子，我知道有个地方不错的。如果你准备好了，就亲吻着我的戒指吧。"
D.Strings[11353]="我准备好了。<亲吻戒指>"
D.Strings[11354]="去修道院门口等我吧。我很快就会过去的。"
D.Strings[11355]="在摧毁这一文明的战事中，我已经尽到了自己的义务……我不得不屈尊亲自对付诅咒神教，一想到这点就觉得恶心。"
D.Strings[11356]="斯古莉探员，请再对我使用一次女妖的魔镜！"
D.Strings[11357]="好吧，不过这次希望你再当心一点！"
D.Strings[11358]="我知道有个僻静的去处，我们可以去那里单独谈谈。跟我来吧，孩子。"
D.Strings[11359]="你觉着我看不出你那拙劣的伪装吗，$n？"
D.Strings[11360]="$r，世间有许多你无法了解的玄机。只有全知全能的主上才能洞悉一切。"
D.Strings[11361]="他早就预知你会来对付我。我亲眼目睹了你对我的同胞做过的事。但是，我是不会死在你手上的。"
D.Strings[11362]="别妄想了。我将以自己选择的方式离开这个世界。但是，我会遵照主上的意志卷土重来的！"
D.Strings[11363]="小声点。别被那些野兽发现啦！"
D.Strings[11364]="哎！你干什么呢？"
D.Strings[11365]="圣光在上！你杀死了乔伊，还抢走了肉！你是怎么找到我们的？"
D.Strings[11366]="你被咬了？"
D.Strings[11367]="回答我啊！你是不是被咬了？"
D.Strings[11368]="好吧，就算你要杀我，至少等我喂饱格里西达吧？我可怜的宝贝已经好些日子没吃过东西啦。"
D.Strings[11369]="宝贝，杀死乔伊的凶手很快就要对我们下手了，让我最后再喂你一次吧。"
D.Strings[11370]="喏，后面有灯油——你知道该怎么做吧。那帮混蛋对火焰又恨又怕！"
D.Strings[11371]="你怎么忍心对乔伊这样手无寸铁的老头下毒手？你把肉带回来又有什么企图？"
D.Strings[11372]="真是匪夷所思，我完全不明白你是怎么想的……我得说，我很难和你这样的家伙相处……"
D.Strings[11373]="你最好趁格里西达还没有胃口吃餐后甜点之前离开。"
D.Strings[11374]="别拿琐碎的小事打扰我！"
D.Strings[11375]="韦斯温大人正在这一带巡视呢！如果再让我看见你在岗位上划水，我就把你撕成碎片。"
D.Strings[11376]="谢谢你，$c。"
D.Strings[11377]="啊……感觉好多了。"
D.Strings[11378]="哇咧！我差点死在这里。谢谢你，$r！"
D.Strings[11379]="你没看见我正忙着吗！再这样拖沓，我们是不可能在王子殿下归来之前修好这座基地啦！"
D.Strings[11380]="要不是那群混蛋烧毁了船只，我们早就到家啦。别来烦我了，我要回去工作啦！"
D.Strings[11381]="朋友，银色北伐军的部队已经抵达此地。我们不会让你独占所有荣耀的！"
D.Strings[11382]="欧瑞克，请再给我一瓶黑暗草药剂。"
D.Strings[11383]="朋友，很抱歉打扰到你了。你忙你的吧！"
D.Strings[11384]="事情远没有结束……死亡……会令我……更加强大……"
D.Strings[11385]="让那群该死的农夫赶紧干活啊！我好想回到铁炉堡。实在是太想念我的老婆和孩子了。"
D.Strings[11386]="船长说，只要阿尔萨斯王子殿下回来，我们就能返回洛丹伦了。"
D.Strings[11387]="不知道王子殿下究竟是被什么事给耽搁了，但是我们真的坚持不了太久了。许多士兵都无法忍受如此严寒的气候。"
D.Strings[11388]="我相信阿尔萨斯殿下很快就会回来的。千万别气馁！"
D.Strings[11389]="看着那些被野蛮人烧毁的船只，我们的心情仿佛跌到了谷底。说实话，我从来没有觉得如此无助……"
D.Strings[11390]="愤怒。看着眼前这堆烂摊子，我实在是压抑不住心中的怒火。我们历尽艰辛，一路披荆斩棘穿越森林才来到海边，却发现还是迟了一步。返回家园的唯一希望已经破灭了。"
D.Strings[11391]="尽管这片冰霜废土给我们留下了痛苦的回忆，但我相信，年轻的王子殿下终将领导我们走向胜利。我夜夜祈祷，希望他能平安归来。"
D.Strings[11392]="我要出发了，士兵。保持警惕！"
D.Strings[11393]="<被遗忘的步兵摇了摇头。>$B$B我们快要支撑不下去了。阿尔萨斯王子殿下再不回来的话，我们都会没命的。"
D.Strings[11394]="我们不可能及时备好船只了。寒冬降临时，就是我们的末日。恐怕我们都被王子殿下遗弃了。"
D.Strings[11395]="阿尔萨斯殿下和穆拉丁殿下离开这里很长时间了。希望他们平安。"
D.Strings[11396]="一切都会好起来的。"
D.Strings[11397]="祝福你，朋友。我快……不行了……"
D.Strings[11398]="谢谢你，$r！"
D.Strings[11399]="就在我近乎绝望的时候，你为我带来了生的希望！"
D.Strings[11400]="要不是你，我肯定没命了……"
D.Strings[11401]="今天你想去哪儿呢？"
D.Strings[11402]="加入上等的俱乐部可以为你的生活增添别样的风采。"
D.Strings[11403]="我要购买本月美酒。"
D.Strings[11404]="嘿，伙计！你手里拿的不是美酒节奖币吗？我恰好有一些美酒节物品要出售。"
D.Strings[11405]="你有什么货物啊？"
D.Strings[11406]="我要立刻前往暮冬要塞！"
D.Strings[11407]="你好，$r！$b$b想找一台可以乘坐的伐木机？恐怕你得进入山岭啦。$b$b这台坏掉了。"
D.Strings[11408]="够劲的啤酒才是好啤酒。"
D.Strings[11409]="事情是这样。在武装冲突爆发之前，我们利用伐木机来砍伐这里的树木。$B$B战争很快一触即发，我们不得不改装这些机器来对抗部落。要知道，翻新后的伐木机简直是超级厉害的战斗机器呢。如果你有钥匙的话，为什么不好好利用一番呢！"
D.Strings[11410]="能加入“本月美酒俱乐部”真是太棒了。"
D.Strings[11411]="我的兄弟塞尼普斯有很多伐木机。你可以前往北边的蓝天伐木场和他谈谈。"
D.Strings[11412]="抱歉，大使阁下，但王子殿下因故离开了。请问您来这片冰霜废土有什么事吗？"
D.Strings[11413]="根据皇家敕令，部队立刻返回洛丹伦。乌瑟尔大人已经说服国王陛下召回这支远征军。"
D.Strings[11414]="这么说我们要马上离开这里？"
D.Strings[11415]="没错。我的手下也报告说，从这里通向海岸的道路被亡灵占据了。你必须另找一条路回到船上。"
D.Strings[11416]="该死的亡灵！弟兄们，直接从森林中穿过去！"
D.Strings[11417]="上尉，卫兵怎么都不在自己的哨位里？"
D.Strings[11418]="呃，殿下，您的父王应乌瑟尔大人的请求召回了全军。"
D.Strings[11419]="乌瑟尔要召回我的军队？见鬼！如果战士们离我而去，我要怎么杀死玛尔加尼斯？必须要赶在他们回到海边之前烧毁船只！"
D.Strings[11420]="这是否太过分了，伙计？"
D.Strings[11421]="全都烧成灰烬！我们事业未尽，谁也不能提前回家！"
D.Strings[11422]="你对你的部下说谎，还背叛了为你而战的雇佣兵。你到底怎么了，阿尔萨斯？你就只有复仇这个念头了吗？"
D.Strings[11423]="别管我了，穆拉丁。你没见过玛尔加尼斯对我的家乡做了什么。"
D.Strings[11424]="只要集满足够的奖币就能加入“本月美酒俱乐部”。加入了“本月美酒俱乐部”就好象天天都过美酒节！$b$b每个月你都可以通过邮件收到一份新出的酒样。如果你喜欢的话，可以到铁炉堡的石火旅店向商人购买。"
D.Strings[11425]="本月美酒俱乐部"
D.Strings[11426]="只要集满足够的奖币就能加入“本月美酒俱乐部”。加入了“本月美酒俱乐部”就好象天天都过美酒节！$b$b每个月你都可以通过邮件收到一份新出的酒样。如果你喜欢的话，可以到奥格瑞玛精神谷的黑石南小屋向商人购买。"
D.Strings[11427]="本月美酒俱乐部？"
D.Strings[11428]="“本月美酒俱乐部”是什么东西？"
D.Strings[11429]="你还不知道“本月美酒俱乐部”？那是一群希望天天都是美酒节的可爱家伙！过去他们一直希望让美酒节回归，但每次持续的时间都不长。$b$b一旦你加入了这个俱乐部，每个月都能收到俱乐部邮寄来的最新酒样！如果你喜欢某种啤酒，可以到铁炉堡向商人购买。$b$b我觉得你也非常可爱，完全有资格加入这个俱乐部。只要给我一些美酒节奖币，我就会给你加入的申请表。然后我们或许就能天天一起庆祝美酒节了！"
D.Strings[11430]="那些亡灵竟然来自我们的墓地！"
D.Strings[11431]="你做到啦！我还以为你会赔上性命呢！"
D.Strings[11432]="你还在这里干什么呢？赶紧回到镇上去！"
D.Strings[11433]="塔里奥斯塔兹，请允许我搭乘龙兽前往神殿顶端女王陛下的王廷。"
D.Strings[11434]="阿莱克丝塔萨女王任命我负责龙眠神殿的防务工作。$B$B但如你所知，玛里苟斯和他的军团摧毁了附近一处魔网能量线的锚点。蓝龙军团将其中的能量导向了碧蓝巨龙圣地。$B$B毫无疑问，他们是想利用这种能量强化自己，伺机向神殿发动攻击！我们已渐渐处于劣势。$B$B$r，你愿意帮助我们吗？"
D.Strings[11435]="退后点，$n。这头野兽可能会突然暴起伤人。"
D.Strings[11436]="高弗雷！你这恶魔！你听仔细了！我要代表圣光将你从邪恶中拯救出来！"
D.Strings[11437]="%s咆哮着。"
D.Strings[11438]="很好。高弗雷，你肯听我说话了。"
D.Strings[11439]="高弗雷，这事儿吧有两种解决方式，我更喜欢开门见山的做法。你看，不如你直接告诉我秘典上的邪恶符号是什么含义。怎么样？"
D.Strings[11440]="%s发出嘶嘶声。"
D.Strings[11441]="我不会告诉你的，你这神棍。"
D.Strings[11442]="你能把我怎么样？你莫非比克尔苏加德更残忍？比巫妖王更厉害？"
D.Strings[11443]="你说得没错，这本秘典是拯救你们的唯一希望……但是你休想知道！我不会说的！绝不！"
D.Strings[11444]="好吧，那我就要用第二种解决方式了。"
D.Strings[11445]="迷失的灵魂，我会为你念上一段祷言。愿圣光拥你入怀。"
D.Strings[11446]="训诫开始。"
D.Strings[11447]="让圣光拥抱你吧，野兽！"
D.Strings[11448]="屈服在圣光的力量下吧！"
D.Strings[11449]="让圣光渗入你的灵魂，高弗雷！"
D.Strings[11450]="在圣火中化为灰烬吧！"
D.Strings[11451]="圣光！不要！求求你！"
D.Strings[11452]="我从未体验过这样的煎熬！"
D.Strings[11453]="高弗雷，你已经见识到圣光的力量了……恶魔，说吧。秘典上都写了些什么？"
D.Strings[11454]="秘典中记载了即将到来的天启。世界将在灰烬中毁灭，然后重获新生。"
D.Strings[11455]="一派胡言！高弗雷，你当我是傻子吗？别拿天灾军团那套邪说来恐吓圣光的战士！你放聪明点，不然我就叫人把你丢进装满圣水的木桶，像给狗除跳蚤那样让你冲个圣水浴！"
D.Strings[11456]="不要啊！！！我说！我什么都说！！！"
D.Strings[11457]="人类……自作孽。纳克萨玛斯为什么会攻击这里？就因为你们在暮冬城地下建起的陵墓！塞尔赞躲在你们的墓穴中，唤醒成千上万的僵尸与你们为敌！你们将被毁灭……"
D.Strings[11458]="什么！？暮冬城旧址下面有一座陵墓？我们对此事竟然毫不知情！高弗雷，我们会消灭你的主子，结束这场噩梦。"
D.Strings[11459]="高弗雷，我们自会对付塞尔赞。"
D.Strings[11460]="你们打算如何对付他？人类真是既天真又愚蠢。居然想打败黄昏使者塞尔赞！为了获得力量，他牺牲了原本的血肉之躯。巫妖王庇佑着如今的巫妖塞尔赞！"
D.Strings[11461]="你们不可能阻止塞尔赞！他拥有巫妖王陛下赐予的黑暗之能！"
D.Strings[11462]="$n，向哈尔弗汇报这位“坦诚”的市长先生招供的情报吧。剩下的事交给我解决，说不定还能从他口中榨出一些有关塞尔赞的消息呢。现在，我就让高弗雷见识一下罕见的“第三种解决方式”。"
D.Strings[11463]="来吧，我们开诚布公地谈一谈。"
D.Strings[11464]="为了联盟，为了弗塔根公爵！"
D.Strings[11465]="啊！骑兵队到啦！"
D.Strings[11466]="技术不错啊！我们毫发无损！"
D.Strings[11467]="要不是你，我们就死定了。谢谢你带我们回来！"
D.Strings[11468]="逃出这里！"
D.Strings[11469]="我们会没命的！"
D.Strings[11470]="我可没有同意做这样的事！"
D.Strings[11471]="我不管啦！我要回家！"
D.Strings[11472]="我根本不想呆在这里！"
D.Strings[11473]="别让那些坏人靠近我！"
D.Strings[11474]="别让他们靠近我！我保证能在15秒内搞定这玩意儿。"
D.Strings[11475]="看着吧，我会把这台天灾战车包装得像是地精的工程制品！保护我！"
D.Strings[11476]="%s娴熟地装配出一台外形奇特的机械。"
D.Strings[11477]="就快搞定啦！再给我几秒钟。"
D.Strings[11478]="觉醒吧，阿鲁高！巫妖王的力量命令你觉醒！"
D.Strings[11479]="对……他完全符合我们的要求。请你将他送去冬至村吧。如果我们不能按时完成阿尔萨斯陛下交代的任务，他会不满意的。"
D.Strings[11480]="嗨，$c。你瞧见了吗？水面上那是什么玩意儿……$b$b你到底看清楚没有啊？"
D.Strings[11481]="你是说冰山吗？"
D.Strings[11482]="冰……冰山？？$b$b呃，我是指漂在空中的不明障碍物。在我的家乡，大家都说没有见过此类物体。$B$B我是真的见过！还在近处观察过它们呢！喏，这艘船就是我近几年的创造结晶，为的就是追踪并记录这些不明物体并且在必要的时候摧毁它们！"
D.Strings[11483]="你的计划竟然成功了，我真是又惊又喜。"
D.Strings[11484]="这艘船……仅仅是为了检查浮冰？"
D.Strings[11485]="我们不能让你回到同伴身边，也不能让你和我们呆在一起……"
D.Strings[11486]="等等！你说过如果我帮你的忙，你就放我一条生路的。我可是一直遵照约定帮助你的！"
D.Strings[11487]="酋长，刀下留人。他还有利用价值。"
D.Strings[11488]="$r，别被假象蒙蔽了双眼。那些不明物狡猾着呢。前一秒你还能看见它们，转瞬之间就消失得无影无踪——简直是匪夷所思！$b$b我告诉你一个秘密，不许说出去哦。我曾经搞到过一块碎片！可惜在我进行测试实验之前，它就莫名地消失了！就像蒸发了似的……不见了……"
D.Strings[11489]="只是冰块而已吧。你也太大惊小怪了。"
D.Strings[11490]="还记得你找到的那本矮人日记吗？呃，它的主人很可能就是我们追捕布莱恩·铜须的重要线索。"
D.Strings[11491]="圣光在上，布莱恩还活着？我死也不会帮你追捕他的！"
D.Strings[11492]="我相信你会的，除非你想为难自己。"
D.Strings[11493]="托尔玛克，你对此满意吗？"
D.Strings[11494]="他还有利用价值，就留着他吧。矮人，如果我是你的话，我会更加谨慎的。"
D.Strings[11495]="你能听到许多关于不明物体的传说……$b$b有人说它们在观测冰洋，有人说它们试图改变海洋的生态系统，还有人认为它们是来接管艾泽拉斯世界的！$b$b等我用火箭推进弹头将它们打得粉碎，就能找到答案了。相信我！"
D.Strings[11496]="畜生！快说！我的妹妹在哪儿，否则我不会放过你们的。"
D.Strings[11497]="等等！别开枪！不要伤害塔特亚娜！"
D.Strings[11498]="囚犯们被关押在山脉另一侧的狼穴中。你说的姑娘很快就会被送到阿鲁高那里了。我们可以走了吗？"
D.Strings[11499]="原谅我，塔特亚娜……"
D.Strings[11500]="和阿鲁高比起来，你对我们的威慑力差得远了！我要将你撕成碎片！"
D.Strings[11501]="安娅在哪儿？"
D.Strings[11502]="只剩最后一件事了。我必须知道阿鲁高的下落。"
D.Strings[11503]="谢谢你帮我返回营地。请转告瓦尔特，就说我已经平安无事啦！"
D.Strings[11504]="他会吃掉小毛球的！你得帮帮小毛球！帮帮小毛球呀！"
D.Strings[11505]="小毛球遇到大坏蛋啦！救命啊！"
D.Strings[11506]="是营地！小毛球，我们很快就要到家啦！快点！"
D.Strings[11507]="你好，$r。$B$B我一直在盼着你。"
D.Strings[11508]="我们要投身战斗了。准备好了吗？"
D.Strings[11509]="很好，出发！"
D.Strings[11510]="让我们一起加入战斗吧，$n！"
D.Strings[11511]="栖息在诺森德山峰上的狮鹫是适应性最强的物种。"
D.Strings[11512]="朋友，狮鹫骑士距离我们仅十步之遥。他们会送你前往索尔森的岗哨。准备出发吧！"
D.Strings[11513]="你不会吃掉我的，对吧？"
D.Strings[11514]="安娅！！你平安无事！"
D.Strings[11515]="邪月岛？是血月岛吧？"
D.Strings[11516]="别害怕……现在你安全啦。"
D.Strings[11517]="姐姐！那些卑鄙的家伙打算将我带去邪月岛，把我变成他们的一员。"
D.Strings[11518]="对，就是那个岛屿！邪月岛！萨莎……别再离开我啦！他们抓走了爸爸，然后又抓走了你……我不想和他们单独相处！"
D.Strings[11519]="不要以为过去的成就能为你带来任何权利与荣耀，$n。$B$B想要得到我的尊重，你必须证明自己。也就是说，你要遵循我的指令，并且毫无异议地完成使命。"
D.Strings[11520]="笼罩你的寒气就是厄运的先兆。"
D.Strings[11521]="协助防御！快点，废物们！"
D.Strings[11522]="你好。侍从瓦尔特和我负责照看老马布兰契和其他马匹。"
D.Strings[11523]="你好，$r。$B$B如果你愿意帮助我们保卫神殿的话，请入内与指挥官阿弗拉沙斯塔兹谈一谈。"
D.Strings[11524]="感谢你们，凡人。蓝龙军团已经察觉到你们的动向，你们要当心。眼下，玛里苟斯任命瓦尔洛斯·云击率领碧蓝魔环卫士死守魔环。请接受我们的帮助，这样才有机会击败敌人。"
D.Strings[11525]="我一直守护着这座被阿莱克丝塔萨女王祝福过的圣地，光阴荏苒……连我都不记得度过了多长时间。在最为黑暗的年代，我未能尽到自己的职守……我倒在了死亡骑士血毒的脚下。"
D.Strings[11526]="巫妖王已经伸出魔爪……肆无忌惮地践踏着龙族最神圣的领地。他想逼迫我们采取行动。"
D.Strings[11527]="我的时日不多了……我为阿莱克丝塔萨女王奉献了一生，可死亡终将阻断我的奉献之意。红玉巨龙圣地需要一名新的守护者。"
D.Strings[11528]="谢谢你……谢谢你将我从被诅咒的枷锁中解救出来。你是个英雄……我知道你还会干出惊天动地的大事来的。"
D.Strings[11529]="达莉亚想起那个名字，往地上啐了口口水。"
D.Strings[11530]="达莉亚之魂逐渐消失了……"
D.Strings[11531]="欢迎来到欧尼瓦营地。"
D.Strings[11532]="我想使用兽栏。"
D.Strings[11533]="掷杯训练器不仅仅是用来投掷啤酒杯的靶子，更是宝贵的训练设备。如果你能击中它，那你就能击中任何东西！$b$b可不要砸到我哦。"
D.Strings[11534]="我想坐在绿龙背上飞翔。"
D.Strings[11535]="贝加里斯塔兹说得没错，这里的局势非常严峻。\n\n我能赐予你召唤绿龙的能力。如果你想要召唤红龙或青铜龙，就得和贝加里斯塔兹或伊特努斯谈谈。"
D.Strings[11536]="我想坐在红龙背上飞翔。"
D.Strings[11537]="贝加里斯塔兹说得没错，时间紧迫！\n\n我能赐予你召唤青铜龙的能力。如果你想要召唤红龙或绿龙，就得和贝加里斯塔兹或沃尔蒂萨谈谈。"
D.Strings[11538]="我想坐在青铜龙背上飞翔。"
D.Strings[11539]="报告，长官！"
D.Strings[11540]="不惜一切代价，守住神殿！"
D.Strings[11541]="我看见了一辆天灾战车！"
D.Strings[11542]="萨多尔大桥是我炸毁的！我难道没有告诉你们？真的，所谓黑铁矮人破坏了大桥，那都是谣传！我才是真凶！"
D.Strings[11543]="这样毫无道理啊。为什么天灾军团不将纳克萨玛斯飞到暮冬要塞上空，然后直接炸毁它呢？我是说，如果我是克尔苏加德，肯定这么做啦。"
D.Strings[11544]="或许有一天，我们能揭开这种神秘矿石的真面目。那时我们就可以好好利用它啦。"
D.Strings[11545]="嘿，你们认识瓦加德的米克高维尔吗？他是我的叔叔哦。那你们知道他的头衔吗？“专家。”听听，多帅气啊。我也想成为一名专家。"
D.Strings[11546]="什么东西这么臭啊！肯定不是我。侏儒散发着黄油和阳光的味道，才不像那些脏兮兮的矮人。他们简直像从穴居人的腋窝里爬出来的一样！这里没有矮人，对吧？"
D.Strings[11547]="我认识一个矮人，这家伙宣称侏儒是从地下进化来的。我们的祖先是沙漠侏儒。简直是一派胡言！还沙漠侏儒呢！我呸！"
D.Strings[11548]="我从未见过如此严重的破坏程度……"
D.Strings[11549]="安静！我们要保持警惕！"
D.Strings[11550]="死亡的气息覆盖着这里的每一寸土地。"
D.Strings[11551]="听说你独自一人就将村民们空运到安全地带，使他们免受苦难的折磨。是真的吗？"
D.Strings[11552]="有谁知道塞尔赞吗？他是谁？他是如何成为统领天灾军团地面部队的统帅的？"
D.Strings[11553]="瞧瞧眼前的惨状……天灾军团会此付出代价的！"
D.Strings[11554]="尸体都到哪儿去了？他们对村民们做了什么？"
D.Strings[11555]="我希望自己能亲眼目睹阿尔萨斯接受命运的审判！"
D.Strings[11556]="大部分血精灵都对部落的“野蛮习气”嗤之以鼻，我当然也不例外。当我刚刚被派到这又潮湿又……芳香的地方时，我觉得自己实在是太不走运了。$B$B渐渐地，我发现这里的环境还是挺棒的。你觉得呢？$b$b我的研究工作也觉得了不小的进展。嗯，只需一个小法术，法师们就能回到这里哦。你想学习吗？"
D.Strings[11557]="大部分血精灵都对部落的“野蛮习气”嗤之以鼻，我当然也不例外。当我刚刚被派到这又潮湿又……芳香的地方时，我觉得自己实在是太不走运了。$B$B渐渐地，我发现这里的环境还是挺棒的。你觉得呢？$b$b我和你废什么话呢……你又不是法师，对我的研究肯定没兴趣。"
D.Strings[11558]="嗯？哦，请原谅我的心不在焉。我正在为北方城堡的伙计们担心，我应该派些学徒去帮他们的……你有什么事吗？"
D.Strings[11559]="嗯？哦，请原谅我的心不在焉。我正在为北方城堡的伙计们担心，我应该派些学徒去帮他们的……"
D.Strings[11560]="我的魔法只传授给法师。很抱歉，$c。"
D.Strings[11561]="Sinu a'manore。如果你想要学习开启一道通向塞拉摩的传送门的法术，我可以帮你。"
D.Strings[11562]="与第一届相比，美酒节已经发生了一些变化。今年，我们发行的是美酒节奖币，而不是奖券啦。如果你手里还有旧的奖券，我可以帮你兑换。"
D.Strings[11563]="$r，想要搭乘双足飞龙吗？$B$B或者你有什么烦心事儿想向我倾诉？"
D.Strings[11564]="我们有必要闹得这么僵吗？"
D.Strings[11565]="面对困境，我做出了明智的判断，而你却束手无策。克雷娜，我不愿意眼睁睁地看着你将我们带上绝路！"
D.Strings[11566]="你背着我耍花招，无视我的命令。你会付出代价的。"
D.Strings[11567]="够了。这场战斗结束后，我与你便再无瓜葛。那时，即便是座狼，也不愿意靠近你的尸体。"
D.Strings[11568]="女士们，先生们！我说……你们一定不想错过这场战斗吧！"
D.Strings[11569]="为什么……为什么？我们非要闹到这步田地吗？"
D.Strings[11570]="我想用红玉精华换取翡翠精华。"
D.Strings[11571]="我想用琥珀精华换取翡翠精华。"
D.Strings[11572]="火箭推进弹头？是不是太夸张啦？"
D.Strings[11573]="听着。想知道不明物的真相，最好是制造一场爆炸——当然是越大越好啦！$b$b不过眼下还有很多问题没有解决，$r。$b$b这些弹头都是由机密材料制成的，而作为推进能量源的115号元素就更加机密啦！$b$b事实上，你最好假装从来没有见过我，继续过你的安稳日子去。"
D.Strings[11574]="我想用翡翠精华换取琥珀精华。"
D.Strings[11575]="我想用红玉精华换取琥珀精华。"
D.Strings[11576]="我想用琥珀精华换取红玉精华。"
D.Strings[11577]="我想用翡翠精华换取红玉精华。"
D.Strings[11578]="我想去龙眠神殿中层，与阿弗拉沙斯塔兹指挥官谈一谈。"
D.Strings[11579]="指挥官，我想去龙眠神殿顶层。"
D.Strings[11580]="欢迎你，冒险家。你来的正是时候。"
D.Strings[11581]="塞尔赞必须死，只有这样才能使怨灵停止那永无止境的哭泣！"
D.Strings[11582]="阿弗拉沙斯塔兹，能让我返回神殿底层吗？"
D.Strings[11583]="暮冬要塞的市民与官员联名发布的官方公告。"
D.Strings[11584]="能让我搭乘幼龙前往龙眠神殿中层，与阿弗拉沙斯塔兹会面吗？"
D.Strings[11585]="面对黑龙令你感到不安吗？$B$B很好。的确如此。在黑龙面前，其他龙族也会心生胆怯。这一点倒是继承了他们的祖先的美德——瞧，他们根本不敢攻击我。$B$B一帮蠢货。"
D.Strings[11586]="接下来介绍纳克萨玛斯恐怖的天灾区。天灾军团在这里进行药理研究，企图改良他们在洛丹伦传播的药剂。"
D.Strings[11587]="接下来介绍纳克萨玛斯被诅咒的蜘蛛区。天灾军团在这里培育蛛怪的变种，以便繁殖出毒性更厉害的危险生物。"
D.Strings[11588]="接下来介绍纳克萨玛斯毒气缭绕的憎恶区。天灾军团在这里制造大批强壮而丑陋的怪物，以此扩充他们的军事武装力量。"
D.Strings[11589]="接下来介绍纳克萨玛斯的死亡骑士区。在腐化力量的侵蚀下，我们最杰出的战士沦为了天灾军团的走狗。如今，战争的号角日夜在死亡骑士区的大厅中回荡。"
D.Strings[11590]="接下来介绍盘踞在纳克萨玛斯顶端的生物。他们拥有无可思议的强大力量，当之无愧地被冠以诺森德两大威胁的称号。"
D.Strings[11591]="这是药剂师诺斯。天灾军团将人们囚禁在冰冷的死灵牢笼的计划，便是他提出的创意。至今，诺斯仍然负责监督并完善这一流程。"
D.Strings[11592]="这是肮脏的希尔盖。他就是指挥天灾军团利用天灾之锅将艾泽拉斯宁静的旷野变成瘟疫之地的罪魁祸首。"
D.Strings[11593]="据说希尔盖对纳克萨玛斯的墙壁和地板进行了改造，设置了大量可以随意触发的可控陷阱。"
D.Strings[11594]="洛欧塞布。据说这个由瘟疫之地的活性诅咒与艾泽拉斯的沼泽兽缝合而成的怪物有着自我愈合的能力。"
D.Strings[11595]="这尊影像就留给你们观察吧。仔细研究对手的能力，他的优势很可能也是致命的弱点。"
D.Strings[11596]="注意。这是教官拉苏维奥斯，由克尔苏加德亲自指派的死亡骑士训练师。这位威严的教官拥有独特的教学法则，据说只有他的学徒才有可能承受得住他的威力。"
D.Strings[11597]="收割者戈提克。作为巫咒与魔法的大师，据说戈提克能瞬间召唤出亡灵军团为他作战。在他的指导下，即便是能力最弱的死亡骑士也能令亡者复生。"
D.Strings[11598]="天启四骑士是纳克萨玛斯中最强大的死亡骑士，是克尔苏加德麾下最顶尖的护卫。首先介绍库尔塔兹领主，他能操纵火焰的力量。"
D.Strings[11599]="下一位是女公爵布劳缪克丝。她能召唤暗影的力量，吞噬活人的灵魂。"
D.Strings[11600]="瑟里耶克爵士。生前他是一名信仰坚定的圣骑士，虽然他已是死灵之躯，却依然能召唤圣光的力量惩击敌人。"
D.Strings[11601]="最后一位死亡骑士是大领主莫格莱尼。他曾经是一名杰出的战士，最优秀的死亡骑士在他面前也会黯然失色。但是，当他在艾泽拉斯经历了一系列的变故后，便消失得无影无踪了。目前还不知道克尔苏加德指派了谁来取代他的位置。"
D.Strings[11602]="阿努布雷坎，艾卓-尼鲁布最杰出的蛛怪领主之一。多年前，他与蛛怪之王阿努巴拉克都惨败在巫妖王手中，此后便被天灾军团控制了。据说他曾是阿努巴拉克麾下最忠诚的领主。"
D.Strings[11603]="听着，$r。$B$B想找一台能驾驶的伐木机，你恐怕得进入北面的山岭。$b$b这台已经坏掉了。"
D.Strings[11604]="我为什么要驾驶伐木机？"
D.Strings[11605]="一开始我们只是利用这些机器砍伐森林，但是自从联盟踏上这片土地，战争就愈发频繁起来。我们这才发现，原来翻新过的伐木机也能充当战争机器。$b$b$c，相信我。如果你有伐木机钥匙的话，干嘛不试着驾驶一下呢。"
D.Strings[11606]="黑女巫法琳娜。生前她是一位植物学家，死后她为巫妖王效力，负责管理蜘蛛区的蛛怪培育与毒药研制工作。"
D.Strings[11607]="我要去哪儿找翻新过的伐木机钥匙？"
D.Strings[11608]="格利克有很多钥匙。$b$b如果你肯帮他的忙，他或许会考虑送你一把。下次你造访蓝天伐木场时，记得找他谈谈。"
D.Strings[11609]="迈克斯纳。数百年前，这只出生在诺森德冰峰深处的蜘蛛就被天灾军团虏进了纳克萨玛斯。她在这座恐怖之城中繁衍后代，那些胆敢进入纳克萨玛斯的冒险者都沦为了蜘蛛的美餐。"
D.Strings[11610]="这是帕奇维克。圣光兄弟会第一次听闻他的传言时，没有谁相信憎恶也能拥有如此迅捷的速度和可怕的力量。当帕奇维克初战告捷后，大家便不再认为那是谣言了……"
D.Strings[11611]="格罗布鲁斯，天灾军团制造的血肉巨人。格罗布鲁斯体内蠕动着纳克萨玛斯的软泥怪，能侵蚀给任何敢于靠近它的敌人。被注入软泥怪的受体通常会逃回盟友身边，顷刻之间就能击溃所有人。"
D.Strings[11612]="格拉斯，纳克萨玛斯肮脏的天灾犬。据说这只野兽极其贪婪，每天费尔根都会给它送去一批缺乏作战力的亡灵。格拉斯堪称是天灾军团废物利用系统的终端。"
D.Strings[11613]="塔迪乌斯，用女人与孩子的血肉缝合而成的巨人。据说他们的灵魂也融入塔迪乌斯体内，永远被禁锢在这肮脏的囚牢中。"
D.Strings[11614]="萨菲隆。它本是高贵的蓝龙，自由地翱翔在诺森德的冰峰间，被征战极寒之地的阿尔萨斯所杀。克尔苏加德复活了萨菲隆，如今这头冰霜巨龙守卫着主子的巢穴，等待那些胆敢挑战克尔苏加德的冒险者。"
D.Strings[11615]="巫妖克尔苏加德。显然他为巫妖王效力。克尔苏加德生前是一名强大的通灵师，死后自然而然地成为了巫术大师。据说他是巫妖王最忠诚的部下。"
D.Strings[11616]="克尔苏加德通过了最为严酷的试炼。即便是圣光兄弟会的成员，这样的试炼也会撼动他们的灵魂。克尔苏加德将自己的生命完完全全交给了阿尔萨斯，然后借助太阳之井的力量得以复生。"
D.Strings[11617]="克尔苏加德再次被驻扎在瘟疫之地的银色黎明击败。可是他的护命匣落到了圣光兄弟会某个不忠诚的成员手中。至今我们还不知道是谁偷走了护命匣以及其中的阴谋。"
D.Strings[11618]="%s凝视着莫度鲁的德拉诺礼袍。"
D.Strings[11619]="诺哈因，你说莫度鲁为什么还穿着这件可笑的袍子啊。他看上去就像那些刚刚逃出埃门谷的乡巴佬似的。"
D.Strings[11620]="旧斯坦索姆……为什么送我回到这一时间流？"
D.Strings[11621]="永恒之龙企图改变阿尔萨斯·米奈希尔王子的命运。$B$B你所熟悉的巫妖王在这一时间流里仍然是洛丹伦的王子，而且全心全意地为国效力。$B$B今天，阿尔萨斯做出了一个重大的决定，它所导致的后果，被我们时光守护者们称之为时间流的拐点。"
D.Strings[11622]="是什么决定？"
D.Strings[11623]="阿尔萨斯下令清洗斯坦索姆，杀死城内所有的居民。$B$B他发现了天灾军团在斯坦索姆传播瘟疫的证据。这种疾病不仅能致人死命。$B$B它还能让死于瘟疫的人复生成为无脑的僵尸，将他们统统改造成天灾军团的战争机器。"
D.Strings[11624]="永恒之龙打算如何破坏这一时间流呢？"
D.Strings[11625]="谢谢你掩护我！下面简直就像精神病院！"
D.Strings[11626]="哇，我还以为我死定了呢！谢谢你，朋友！"
D.Strings[11627]="我差点被食尸鬼给吃了！谢谢你救了我！"
D.Strings[11628]="谢天谢地，你来救我们啦！我们还以为这次肯定完蛋了呢！"
D.Strings[11629]="猎户，让我看看你出售的货物。"
D.Strings[11630]="永恒之龙计划以某种隐秘的手段掩盖天灾军团污染斯坦索姆的证据，以此达到蒙蔽阿尔萨斯王子的目的。$B$B永恒之龙的密探已经潜入附近的农场，对感染瘟疫的谷物施加了幻术，令它们看上去和正常的粮食没有任何区别。$B$B我要你找到这些被藏起来的谷物，然后对它们使用奥术干扰器。阿尔萨斯麾下的士兵正在寻找被污染的粮食，只要你驱除了幻象，他们应该很快就能发现真相了。"
D.Strings[11631]="我们不能放弃奉承红龙军团的好机会。战争迫在眉睫，与红龙结盟对我们是大有裨益的。"
D.Strings[11632]="这些年来，耐克鲁斯滥用神器奴役阿莱克丝塔萨女王和其他红龙。虽然祖鲁希德和耐克鲁斯都死了，但是我们亏欠红龙的债远没有还清。"
D.Strings[11633]="联盟控制这座偏远的营地有好些日子了。对我们的猎户和伐木工而言，这倒算不上是什么坏事。$B$B不过局势日益恶化，很快这里也要进驻军队了吧。"
D.Strings[11634]="交给我来处理吧。"
D.Strings[11635]="真搞不懂，你为什么要招惹她呢？"
D.Strings[11636]="你……你这蠢货！你的胆子可不小。别怪我狠心，至少我得让你看起来像是断腿的伤员。"
D.Strings[11637]="如果你还想走路的话，就别乱动。"
D.Strings[11638]="啊，不要！住手！"
D.Strings[11639]="<指挥官停止授课，转过身来打量着你。>$B$B要不要听听，$c？接纳新知识对你来说是很有好处的。"
D.Strings[11640]="$c，有事吗？"
D.Strings[11641]="$n，我们又见面啦。$B$B想要复习对付天灾军团的战术吗？"
D.Strings[11642]="亲爱的，那些漂亮的鞋子简直值得你为它们而死啊！说真的啦。你从谁手中抢来的啊？肯定免不了一场血腥吧。"
D.Strings[11643]="$n，我会将她赶出藏身之地。你要做好准备，待会她一露面就动手！"
D.Strings[11644]="奖券兑换"
D.Strings[11645]="等待命令！"
D.Strings[11646]="开火！！击中她！"
D.Strings[11647]="欢迎来到岩石之泉。$b$b如果你能活捉这些冰霜巨魔的话，记得来找我谈谈。我愿意出高价买他们。"
D.Strings[11648]="塞尔赞的护命匣滚落到冰雪风暴脚下。"
D.Strings[11649]="“我们都喜欢树木，芬里克。它们是很好的遮蔽物。”呸，就是不肯让我砍掉这些讨厌的植物。"
D.Strings[11650]="他们想让蝙蝠以那种危险的飞行角度降落吗？好呀，就让乘客们摔断脖子吧，他们还能喝到鲜美的蝙蝠汤。"
D.Strings[11651]="援军正陆续赶来，不知道伤亡人数要上升到什么程度，他们才肯同意我砍掉这些讨厌的树木。我们的蝙蝠损失严重。或许我应该给它们配备盔甲……"
D.Strings[11652]="侏儒们今晚又有蝙蝠胃囊吃啦……"
D.Strings[11653]="嘿，你手里拿的不是美酒节奖币吗？如果你有兴趣的话，我这里还有一些美酒节物品出售。"
D.Strings[11654]="龙饵，是吧？去吧，引诱冰雪风暴！"
D.Strings[11655]="我们又见面啦，$n。希望你能喜欢我们的俱乐部。"
D.Strings[11656]="嘿，$n！希望你喜欢我们的俱乐部！"
D.Strings[11657]="看上去像是通往地狱的大门！"
D.Strings[11658]="如果我不能重返暮冬要塞，请转告我的家人，我从未放弃过与他们团聚的梦想……"
D.Strings[11659]="一切都结束了？只要阻止塞尔赞的阴谋，天谴之门的战事就能取得胜利？"
D.Strings[11660]="我有些担心。原本应该站出来领导我们的英雄在哪儿？"
D.Strings[11661]="能与你们并肩作战是我无上的荣耀。"
D.Strings[11662]="来吧……结束这场噩梦！"
D.Strings[11663]="死亡终究会夺走我们的性命，但是有时候它比预想的来得要快。今天，我们将其称之为盲勇……明天，后人或许就将其形容为愚蠢。"
D.Strings[11664]="%s对$n施放冰霜坟墓。"
D.Strings[11665]="$n，很高兴见到你！$B$B这是我们初次见面吗？$B$B我游历过许多地方，穿越过数条时间流，很难记住所有的事。"
D.Strings[11666]="士兵们，振作起来。$n已经帮我们揭开了最后的谜团。巫妖塞尔赞很快就会显身，让我们一举击败他吧！"
D.Strings[11667]="这就是塞尔赞的护命匣，它是我们取胜的关键！"
D.Strings[11668]="凡人，曾经……我和你一样，血肉之躯，不堪一击！"
D.Strings[11669]="士兵们，坚持住！"
D.Strings[11670]="阿尔萨斯王子从我身上看到了凡人的脆弱。"
D.Strings[11671]="“终生为我效劳吧。我承诺，我会抹除你灵魂中的弱点。彻底抹除！”我以这样的方式被巫妖王选中……接受了他的赐福。"
D.Strings[11672]="我成为了巫妖王的仆从……恐怖之城纳克萨玛斯能重返诺森德全都是我的功劳。"
D.Strings[11673]="到此为止吧……你历经万难，终于站到了黄昏使者面前。我不会令你失望的……"
D.Strings[11674]="让我拯救你吧，就像阿尔萨斯王子拯救我一样！"
D.Strings[11675]="复活吧，我的侍从！听从主人的命令！"
D.Strings[11676]="样本……样本……除了样本，就不能谈点别的吗？生活应该丰富多彩才对啊！$B$B我说，你的宠物呢？你肯定带着小宠物的吧。喏，这瓶药剂能让它们变得……呃，变得既聪明又强壮！我不骗你啦！$B$B试试吧！"
D.Strings[11677]="好吧，我试试这瓶药剂。"
D.Strings[11678]="要当心哦。它不是很稳定，药效随时可能消失。动作要快！最好……现在就用……"
D.Strings[11679]="荣耀、勇气、怜悯、公正！塞尔赞，当年你也曾发誓恪守这些美德，成为一名合格的银色黎明祭司。"
D.Strings[11680]="你将全副身心都花在对抗天灾军团的大业上。你曾亲眼目睹他们在洛丹伦犯下的罪行。巫妖王夺走了你的一切！"
D.Strings[11681]="那么英尼戈·蒙托尔神父是如何堕落的呢？身为银色黎明的精神领袖，他为什么会变成自己百般唾弃的魔鬼？"
D.Strings[11682]="圣骑士，这将是你最后一次提及那个名字！受死吧！"
D.Strings[11683]="公爵！"
D.Strings[11684]="胜利属于联盟！"
D.Strings[11685]="你拯救了暮冬要塞！塞尔赞的威胁已经解除，残余的天灾士兵就交给第七军团解决吧。等你处理完这里的事务后，就去天谴之门安加萨报到吧！"
D.Strings[11686]="加入战斗吧！让我们了结这一切！"
D.Strings[11687]="当我得知西部荒野发生骚乱时，便毅然告别战友，返回家乡处理当地的事务。算算也是陈年旧事啦。感谢圣光，迪菲亚兄弟会的威胁得以解除。$B$B如今我们再次出征，来到偏远的极寒之地。如果我们嬴不了这场战争，或许就再也没有机会回家了。"
D.Strings[11688]="霜之哀伤洞穴剧烈地摇晃起来。"
D.Strings[11689]="看，穆拉丁，我们最后的希望，霜之哀伤。"
D.Strings[11690]="等等，伙计。基座上有一行铭文，好像是警告。上面说，“持此剑者将获永恒之力。此剑喋血以展锋锐，此力噬灵以显威能”。噢，我早该知道的。这把剑被诅咒了。我们快走吧，别管它了！"
D.Strings[11691]="为了拯救我的祖国，再恶毒的诅咒我也承受。"
D.Strings[11692]="别去动它，阿尔萨斯。忘了它吧，带你的弟兄们回家。"
D.Strings[11693]="该死！无论是谁，都无法阻止我的复仇，老朋友。你，也不行。"
D.Strings[11694]="现在，我召唤镇守此地的魂灵。我愿付出任何代价，做出任何牺牲，只要你能协助我拯救祖国的人民。"
D.Strings[11695]="啊……头疼……我……我在哪儿？"
D.Strings[11696]="我……我是谁？"
D.Strings[11697]="我手下的战斗法师很快就会回来。$B$B等他们到了之后再来找我谈谈吧。"
D.Strings[11698]="抱歉，$r。我还有正事要办，不能耽搁。$B$B不好意思。"
D.Strings[11699]="嗨，$n。别害怕。我……就是来自未来的……你。我是来帮你的。"
D.Strings[11700]="我们要如何穿越迷雾？"
D.Strings[11701]="那是什么！你看到了吗？"
D.Strings[11702]="瞧……他们来了。我会尽全力帮助你。别让他们靠近沙漏！"
D.Strings[11703]="很好！阿尔萨斯已经得知斯坦索姆中有被瘟疫污染的粮食，正准备展开清洗行动。$B$B但是我总觉得哪里不对劲，肯定有别的生物侵入了这条时间流，恐怕永恒之龙就在我们附近。"
D.Strings[11704]="他们想干什么？"
D.Strings[11705]="不知道，我有些担心。不过我会设法找到永恒之龙的。$B$B与此同时，我希望你能加入阿尔萨斯的部队，尽量待在他身边。"
D.Strings[11706]="什么？加入王子的军队？"
D.Strings[11707]="这么说吧，你不用去填征兵表格之类的东西，只要和王子并肩战斗就行了。$B$B你必须确保阿尔萨斯成功清洗斯坦索姆并击败玛尔加尼斯。没有了乌瑟尔和吉安娜在身边，他就需要一切可能的帮助。$B$B如果你找阿尔萨斯谈谈的话，他应该会将你编入对抗玛尔加尼斯的部队。我会继续追查永恒之龙的阴谋，一有消息就联络你。"
D.Strings[11708]="好吧，克罗米。"
D.Strings[11709]="祝你好运，千万当心。瞧，乌瑟尔和吉安娜来了。"
D.Strings[11710]="坐稳啦，$n！向无赖港出发！"
D.Strings[11711]="啊！我们到啦！你瞧，无赖港！"
D.Strings[11712]="瞧，沙漏显现出诺兹多姆的影像！"
D.Strings[11713]="<达库鲁将滴血的手掌伸出笼子，满怀期待地看着你。>"
D.Strings[11714]="与达库鲁握手。"
D.Strings[11715]="换成以前，我会把你打倒，瞧瞧你脸上的表情……"
D.Strings[11716]="嗨，朋友！$B$B很高兴再次见到你……$n，对吧？我怎么会忘记你的名字呢。$B$B我有一种强烈的直觉，我们一定会成为真正的好朋友！$B$B<巨魔露出一丝狡黠的笑容。>"
D.Strings[11717]="达库鲁，我还需要一瓶药剂。"
D.Strings[11718]="再见，$n。好好活着，搞些更好的装备！"
D.Strings[11719]="给。千万别大意哦。$B$B等你进入达克辛废墟后，在底座旁喝下它！"
D.Strings[11720]="我负责传达地狱咆哮的命令。他的指令都是生死攸关的决策。"
D.Strings[11721]="堕落的巨魔……"
D.Strings[11722]="……接受烈焰的惩罚……"
D.Strings[11723]="好啦！扯远了……你觉得呢？"
D.Strings[11724]="愿艾露恩保护你，$r。"
D.Strings[11725]="艾米鲁尔，是凯勒中将派我来的。请送我去西部卫戍要塞！"
D.Strings[11726]="我到啦。我们开始吧？"
D.Strings[11727]="$g先生:女士;，你觉得这个怎么样？"
D.Strings[11728]="这玩意儿要怎么用？"
D.Strings[11729]="让我看看你出售的货物。"
D.Strings[11730]="我来告诉你虚灵是怎么做生意的。我让合作伙伴去杀死生物，然后我来抽取它们的精华……只要一点点就够啦，真的。$B$B我会支付虚灵货币，以此履行合同规定的义务。$B$B你可以用货币购买我出售的货物哦。肯定有你感兴趣的东西……"
D.Strings[11731]="真不敢相信，我竟然穿过这样的装备。"
D.Strings[11732]="只有这样，哈瑞才会和我讲话！我必须一直戴着这个愚蠢的面具……"
D.Strings[11733]="哈瑞说我可以搭乘他的小船去巴尔古挖掘场。我准备好出发啦！"
D.Strings[11734]="瞧瞧你在战斗中的表现，难怪我会染上酒瘾。"
D.Strings[11735]="什么？你应该很清楚吧，我们的命运是休戚相关的！"
D.Strings[11736]="你可千万别出事啊。你若是死了，我也就不存在了，对吧？但是如果你真的死了的话，我又是如何能从未来返回呢。我被绕糊涂了！"
D.Strings[11737]="啊，我差点忘记啦，原来以前我是这么缺乏经验啊。"
D.Strings[11738]="朋友！$B$B事实上并不是这样的。呃……$B$B情况太复杂了。"
D.Strings[11739]="朋友！我认识你？$B$B哦，是你啊，普雷蒙有过目不忘的本事。$B$B你……跟踪我？不关我的事！我什么都没做过！"
D.Strings[11740]="不好意思，克罗米禁止我透露任何未来的事情。她警告说，如果我告诉了你，那我有可能就不会存在了。"
D.Strings[11741]="我真希望能想起来到底有多少永恒之龙想阻止你。这场战斗实在是太久远啦。"
D.Strings[11742]="听着。我本来不打算告诉你的，很快你就会接到聚会的邀请。总之，千万别喝宴会上的饮料！"
D.Strings[11743]="乌瑟尔，你总算及时赶到了。"
D.Strings[11744]="注意你讲话的态度。没错，你贵为王子，但我仍然是你的导师。"
D.Strings[11745]="我自然不会忘记这一点。听着，乌瑟尔，现在我来告诉你关于天灾的事……"
D.Strings[11746]="糟糕。我们太迟了。他们已经被感染了！虽然他们现在表面上还正常，但是迟早会变成亡灵！"
D.Strings[11747]="必须净化整座城市。"
D.Strings[11748]="你怎么会产生这种想法？肯定有别的解决方式。"
D.Strings[11749]="乌瑟尔，大胆！我是你未来的国君，我命令你清理这座城市！"
D.Strings[11750]="孩子，你还不是我的王上！况且就算你是，我也不会遵从这样的命令！"
D.Strings[11751]="那么，我只能将你的决定视为叛国了。"
D.Strings[11752]="叛国？你疯了吗，阿尔萨斯？"
D.Strings[11753]="是这样吗？我以王储的身份在此宣布，解除乌瑟尔勋爵在白银之手骑士团的所有权力与职务。"
D.Strings[11754]="阿尔萨斯！你怎么能……"
D.Strings[11755]="就这样吧！有谁希望拯救这片土地的，就跟我来！其他人……给我滚远点！"
D.Strings[11756]="阿尔萨斯，你做出了一个非常可怕的决定。"
D.Strings[11757]="吉安娜？"
D.Strings[11758]="对不起，阿尔萨斯。我不能眼睁睁地看着你走上歧途。"
D.Strings[11759]="啊，我要吸取更多的精华……"
D.Strings[11760]="旅途愉快！这是单程航线！"
D.Strings[11761]="这是你的那份。"
D.Strings[11762]="欢迎来到我的营地，$r。$B$B好吧，她或许算不上一座营地，但至少我把她看作自己的家园。"
D.Strings[11763]="请将我传送到琥珀崖。"
D.Strings[11764]="本来呢我是带小毛球出来散步的走着走着就迷了路，你也知道这附近有狼群出没呀没想到真被我们给撞上啦，我抱起小毛球撒开脚丫没命地逃就在我近乎绝望的时候眼前出现了一座哨塔！我们迅速躲进塔内惊魂未定地熬了许久直到外面的狼群悻悻地离开才松了一口气……这段经历真是太可怕啦而且我们还不知道回家的路。"
D.Strings[11765]="你最好马上离开。你吓到小毛球啦！"
D.Strings[11766]="我能飞去其他地方吗？"
D.Strings[11767]="有什么能帮忙的吗？"
D.Strings[11768]="这是毅力还是愚蠢？无所谓了。铭记这个教训吧，凡人！"
D.Strings[11769]="欢迎来到龙眠神殿，$r。希望神殿外的骚乱没有为你带来任何困扰；最近玛里苟斯展开了一系列的行动，龙眠神殿已经被包围了。不过你还是可以安心地待在这儿，我们会确保你的安全。"
D.Strings[11770]="阿比迪斯，杀光他们！别让我失望！"
D.Strings[11771]="海军上将眯起眼睛，仔细地打量着你。"
D.Strings[11772]="你已经体现了自己的价值。"
D.Strings[11773]="到冰冠冰川来找我吧，懦夫……如果你们还能活着到那里的话！"
D.Strings[11774]="天灾军团如潮水般向我们涌来。战斗吧！"
D.Strings[11775]="坚持！做好准备！一旦发现污秽，立即烧毁它！"
D.Strings[11776]="%s打开了一道混乱裂隙！"
D.Strings[11777]="%s撑起护盾，将自己的能量转移到裂隙中！"
D.Strings[11778]="伊利丹之路"
D.Strings[11779]="跳舞球"
D.Strings[11780]="灵魂商人"
D.Strings[11781]="猎杀伊利丹"
D.Strings[11782]="你以为冥想能帮助你洗涤内心的杂念吗？"
D.Strings[11783]="蠢货！我要彻底摧毁你，成为你内心世界真正的主宰！"
D.Strings[11784]="别想打败我。我是你身体不可分割的一部分！"
D.Strings[11785]="不！！！"
D.Strings[11786]="干得不错。"
D.Strings[11787]="又一只蓝龙倒下啦。我们的配合真是天衣无缝！"
D.Strings[11788]="只要我们通力合作，这场战争很快就能分出胜负。"
D.Strings[11789]="我从来没有想过自己会载着一名$r投身战斗。"
D.Strings[11790]="还好你留意到那只蓝龙啦！"
D.Strings[11791]="抓紧。让我们勇敢地迎接挑战吧。"
D.Strings[11792]="我从未见过这样的场面。有你陪同真是太好了。"
D.Strings[11793]="玛里苟斯显然是疯了。"
D.Strings[11794]="看来你们还不知道自己将面临怎样的恐怖？看来你们根本一无所知！纳克萨玛斯的霜寒之心正等待着你们！"
D.Strings[11795]="你好，$c！$b$b希望你能胜任艰苦的工作。我们的人手紧张，非常需要帮助。"
D.Strings[11796]="凛风与森林低声诉说着隐忧。这片看似生机勃勃的土地其实隐藏着莫大的危机。"
D.Strings[11797]="<塞瑞恩的眼神异常空洞。为了净化沃达希尔，她似乎耗尽了全部精力。>"
D.Strings[11798]="朋友，我们会为部落提供最优质的皮革！"
D.Strings[11799]="买点干粮在路上吃？或者观战的时候也可以喝上一杯？"
D.Strings[11800]="敌人从四面八方向我们逼近，长老们都认为应该放弃这座岗哨。但是我认为我们应该留下来，勇敢地与敌人抗衡。"
D.Strings[11801]="这片广袤的土地便是巨龙先祖的埋骨地。他们的灵魂已经升华，在龙神之厅中享受着永恒的宁静。"
D.Strings[11802]="天灾军团的行径将会世界造成不可挽回的恶劣影响。必须阻止他们！"
D.Strings[11803]="迦拉克隆是龙族的祖先。泰坦以它为雏形，甄选了五条巨龙来守护艾泽拉斯世界。"
D.Strings[11804]="我还没有完全成熟，必须依赖进食来强化自身的力量。"
D.Strings[11805]="朋友，今天真是个美好的日子。我一直待在龙眠神殿，已经很久没有在龙骨荒野上空自由飞翔了。"
D.Strings[11806]="最近，女王陛下召集议会谈论了奥杜尔遭遇的一场灾难。风暴峭壁似乎出了什么大事！"
D.Strings[11807]="蓝龙军团竟然选择了如此残酷而冷血的道路，整个龙族都因此蒙羞。我却不得不与玛里苟斯的子嗣交战，做出这样的决定真令我痛心。"
D.Strings[11808]="朋友，我必须返回龙眠神殿了。再见！"
D.Strings[11809]="奴仆们，快！绝不能给敌人任何喘息的机会！"
D.Strings[11810]="迦拉克隆的骸骨很快就要从永恒的长眠中觉醒，为世界带来一场残酷的浩劫！"
D.Strings[11811]="奴仆们！听从我的号令吧！通灵主宰命令你们：肃清敌人，否则你们要为失败付出惨痛的代价！"
D.Strings[11812]="巫妖王下令继续向天谴之门安加萨调派冰霜巨龙！服从指令，否则就尝尝我的厉害！"
D.Strings[11813]="敌人发动了攻击！禁止任何人穿越这座古老的陵墓！"
D.Strings[11814]="看看是谁来了？一群公然蔑视并挑战织法者的狂徒？一群完全缺乏理解与远见的蠢货。我怎样才能让你们看清这真相呢？玛里苟斯是在拯救这个世界！咳，我为什么要跟你们废话？"
D.Strings[11815]="可怜而无知的蠢货！"
D.Strings[11816]="显然，我的宠物们失败了。看来还得另外安排一次示范。"
D.Strings[11817]="你们还要打下去吗？你们仍然遵守着被扭曲的教条吗？如果你们能活下来，就到中央的圆环中找我吧。"
D.Strings[11818]="你以为自己嬴了，是吗？尝尝安提沃克的怒火吧！"
D.Strings[11819]="瞧！安提沃克的镰刀！"
D.Strings[11820]="我将她称作诺莫瑞根之魂。她很漂亮，不是吗？要不是你帮忙，她也不可能恢复原貌。"
D.Strings[11821]="好！让我们来尝尝这个所谓的烈酒……"
D.Strings[11822]="天啊！真是好酒！"
D.Strings[11823]="真可惜，科林的烈酒不能在广大啤酒爱好者中推广开来！我知道这么说可能不合适，但我真的很嫉妒那些黑铁矮人！"
D.Strings[11824]="$n，这啤酒……好吧，它可能是美酒节上最好的酒了！"
D.Strings[11825]="欢迎来到银色前沿，$c。$b$b你可以将这里当作自己的家，不过别太放松啦。我们仍处于危险的丛林深处。$b$b要想所有人都安全地走出这片森林，就必须同心协力……你也一样。"
D.Strings[11826]="恐怖船长德梅萨已经进驻藏宝海湾并宣布这一天为海盗日！$B$B她邀请所有敢于前往的人与船员们一起开怀畅饮。"
D.Strings[11827]="我们的处境非常狼狈。"
D.Strings[11828]="天灾军团的邪恶气息与达卡莱巨魔的黑暗仪式亵渎了这片土地。$B$B我们必须将他们彻底铲除。"
D.Strings[11829]="感谢圣光！"
D.Strings[11830]="嗨，$C。我们正忙着打仗呢。"
D.Strings[11831]="你来这儿做什么？"
D.Strings[11832]="你是$n？我听说你已经死了啊。"
D.Strings[11833]="麻烦你快一点……局势每况愈下，我必须做好战斗准备。"
D.Strings[11834]="你是新兵？瞧你这身行头，不像是正规的军装啊。"
D.Strings[11835]="哎呀，是援军啊！"
D.Strings[11836]="有口信要捎给我吗？"
D.Strings[11837]="士兵，听令！立即撤退，向中士报到！"
D.Strings[11838]="好吧，时间就是金钱，光阴飞逝！我们来喝一杯吧……"
D.Strings[11839]="哇！它真的可以润滑蒸汽阀门！"
D.Strings[11840]="如果我是一个诚实的地精，我要说这是节日上最好的啤酒……"
D.Strings[11841]="科林已经死了，这可真糟糕。如果我能从他手中买下这些酒再转卖出去的话——当然要兑上水，重新装瓶，再贴上自己的商标——那我肯定发财了！"
D.Strings[11842]="$r，是不是觉得这里比想象中更加毛骨悚然啊？$b$b如果你真有这种感觉，我一点也不吃惊。几乎所有来过这里的人都这么说，我已经习惯了。"
D.Strings[11843]="我是赞达拉部族的乌布戈。$B$B$r，眼前的情形非常糟糕。达卡莱巨魔将自己送上了绝路。$B$B为什么要重蹈覆辙呢？"
D.Strings[11844]="好吧。我还是返回中士身边吧。"
D.Strings[11845]="再见。"
D.Strings[11846]="保持警惕。达卡莱巨魔生性卑鄙。"
D.Strings[11847]="千万小心，$c。那些巨魔连他们崇拜的蛇神都敢杀！"
D.Strings[11848]="我想知道我们这是去哪儿，以及谁会来对付这些家伙？"
D.Strings[11849]="达卡莱巨魔真是麻烦。我们必须继续前进！"
D.Strings[11850]="喂，伙计！$B$B今天是我们的节日，你知道啦……是海盗日！$B$B我和查姆巴克想出了这个主意，而恐怖船长立即同意了……所以，我们就来啦！"
D.Strings[11851]="明天我们就把海湾还给大财主里维加兹……可在今天——海盗日——这地方归恐怖船长德梅萨和她的船员了。耶！$B$B记住：可不能光做做样子哦。在海盗日上，你还要讲些道上的黑话才行！"
D.Strings[11852]="哈帕纳咕哝着，挥挥手让你去找恐怖船长德梅萨。$B$B你发现他那条毛发浓密的粗壮胳膊上刺着一箭穿心的纹身，上面写着“玛加萨”。"
D.Strings[11853]="呱呱！龙骨拖！龙骨拖！"
D.Strings[11854]="呱呱！让他走跳板！走跳板！"
D.Strings[11855]="呱呱！见鬼！真见鬼！"
D.Strings[11856]="呱呱！住手，你这条下贱的狗！住手！"
D.Strings[11857]="噢……我有点头晕……"
D.Strings[11858]="别来烦我，$c！我要照看整整两大锅起泡酒呢，不能让它们变味儿！$B$B要是这些酒出了一点差子，科林·烈酒大人会把我剥来煮了！"
D.Strings[11859]="祝你健康，恐怖船长！今天让我也尝尝当海盗的滋味吧！"
D.Strings[11860]="要我帮你尝一尝吗？"
D.Strings[11861]="部队在这里待命，我会亲自率领一支小分队进入斯坦索姆，开始清理行动。为了洛丹伦，我们必须除掉所有被感染的城民！"
D.Strings[11862]="欢迎来到藏宝海湾，伙计。别担心德梅萨和她的船员……每年我们允许他们来这里发泄一次，就在海盗日这一天，然后她就会回到南海去，让我们继续平静地生活。$B$B那么……作为热砂集团谦卑的仆人，我能为你做点什么呢？或者我更愿意说——你能为我做点什么呢，嗯？"
D.Strings[11863]="感觉太棒啦！真是暖胃的美酒呀！$n，你真是个时髦的$g家伙:姑娘;！"
D.Strings[11864]="好酒！可惜不够劲。我觉得可以在里面多加一点大蒜……"
D.Strings[11865]="嘿！今天是海盗日，你知道的……在明天的太阳升起之前，藏宝海湾是我的。"
D.Strings[11866]="我们的处境远比在东西瘟疫之地时狼狈得多。$b$b天灾军团变得更加强大了。"
D.Strings[11867]="我受不了啦……$b$b他们会杀了你，然后吃掉你的尸体！据说这样还算幸运的！你能想象比这更倒霉的遭遇吗！"
D.Strings[11868]="你一定要救我出去，$r！$b$b我可不想落得他们那样悲惨的下场！"
D.Strings[11869]="自打我来到这里，就一直吃不下睡不着。$b$b我根本不该加入银色北伐军……"
D.Strings[11870]="<呜咽>我叔叔是银色黎明的成员。$b$b他怎么有勇气面对这些肮脏的怪物啊？"
D.Strings[11871]="一闭上眼睛，就浮现出我被天灾士兵包围的景象！$b$b我要离开这个鬼地方……"
D.Strings[11872]="我一定会死在这里的……我心里很清楚。"
D.Strings[11873]="我们死定了！！！"
D.Strings[11874]="趁早逃命去吧，$c！$b$b我们不可能获胜……"
D.Strings[11875]="这下麻烦大了。"
D.Strings[11876]="去吧，让天灾军团尝尝厉害！"
D.Strings[11877]="好酒！但我觉着还不够刺激。要不我们用滑腻的蜥蜴眼来提提味道……"
D.Strings[11878]="呃，还不错吧……总觉得少了点什么！不如加点蝎毒？对呀！那样就很完美啦！"
D.Strings[11879]="差不多啦！不过还需要加点料。嘿嘿，你猜对啦……把昨天的袜子丢进锅里吧……哎哟，那种味道……真是美呀！"
D.Strings[11880]="$g先生:女士;，这可真是好酒呀！不骗你！"
D.Strings[11881]="我们来唱歌吧！$B$B啤酒，吵闹，$B啤酒，吵闹！$B黑铁矮人的生活！$B$B哈哈！$n，我喜欢你！"
D.Strings[11882]="我说到哪儿啦？对啦……于是我对她说：“可是我需要你！我需要你啊！”……她却哈哈大笑，扭着尾巴爬走了！我说的都是真心话啊，$n。纳迦真是残酷的种族！"
D.Strings[11883]="让我们再尝尝看！"
D.Strings[11884]="再来一杯！"
D.Strings[11885]="你说得对！我在想什么呢！天灾军团，放马过来吧！"
D.Strings[11886]="你说得对！我们能做到！"
D.Strings[11887]="我们会净化这片土地！阿尔萨斯，等着瞧吧！"
D.Strings[11888]="兄弟，干杯！"
D.Strings[11889]="西莱图斯的魔精属于我们啦。世间万物都将臣服于达卡莱的力量！"
D.Strings[11890]="他们竟敢发动攻击？这帮蠢货！他们难道不清楚我们有多强大吗？！"
D.Strings[11891]="杀死入侵者！看看谁敢来亵渎我们神圣的祭坛！"
D.Strings[11892]="杀死他们，然后我们去南边对付他们的同胞！"
D.Strings[11893]="狂野诸神的力量在我们的血脉中燃烧，即便是巫妖王，也无法阻挡我们前进的道路！"
D.Strings[11894]="我看见你了，蝼蚁！过来吧。"
D.Strings[11895]="我要消灭银色北伐军！我要消灭天灾军团！"
D.Strings[11896]="若是在别的日子，我才不会这么做。不过……我很口渴，而且我讨厌独自饮酒。$B$B干杯！"
D.Strings[11897]="干杯！"
D.Strings[11898]="你愿意不惜一切代价保卫洛丹伦吗？"
D.Strings[11899]="砰！$b$b我只记得听见一声巨响……"
D.Strings[11900]="<叹气>……这次大劫难逃了。"
D.Strings[11901]="谢谢你，朋友。要不是你帮忙，我肯定没命了。"
D.Strings[11902]="<叹气>……$b$b你能帮我个小忙吗？"
D.Strings[11903]="<叹气>……呃，我还以为事情会更糟糕呢。"
D.Strings[11904]="遵命，王子殿下。我们准备好了。"
D.Strings[11905]="不用管我。我只是个糟老头，让我静静地等待那位老……朋友。"
D.Strings[11906]="啊，难以忍受的……痛苦……"
D.Strings[11907]="啊，我……快撑不住了……"
D.Strings[11908]="朋友，我欠你一份情。谢谢你救了我。"
D.Strings[11909]="快，$r。$b$b我的时间不多了。"
D.Strings[11910]="快点。我在流血呢……"
D.Strings[11911]="嗯，再来点魔精。"
D.Strings[11912]="<叹气>……你觉着我们能逃出去吗，$C？$b$b我的血快流干了！"
D.Strings[11913]="大家都做好准备了吧。记住，斯坦索姆的城民已经受到感染，很快就会丧命。我们必须清洗斯坦索姆，确保洛丹伦的其它地区免受天灾军团的侵蚀。出发吧。"
D.Strings[11914]="赞美圣光！是阿尔萨斯王子！殿下，我们都被感染了，现在该怎么办？"
D.Strings[11915]="你已经感染得太深了，我能做的只有让你毫无痛苦地安息。"
D.Strings[11916]="这只是个开始。"
D.Strings[11917]="有个教徒不小心撞上了我的剑刃，然后就死了……我能再要一套伪装吗？我发誓这次会更加谨慎的。"
D.Strings[11918]="对，这只是个开始。年轻的王子，我等你很久了。我就是玛尔加尼斯。"
D.Strings[11919]="如你所见，你的子民现在已经属于我了。我已经将城中的居民统统变成了我的奴仆，让斯坦索姆的生命之火……永远熄灭了。"
D.Strings[11920]="奥法徽章"
D.Strings[11921]="我不会让你得逞的，玛尔加尼斯！我绝对不会眼睁睁地看着他们成为你的奴仆！"
D.Strings[11922]="辉煌徽章"
D.Strings[11923]="防御者徽章"
D.Strings[11924]="愤怒徽章"
D.Strings[11925]="自然徽章"
D.Strings[11926]="虚空徽章"
D.Strings[11927]="什么事？没看见我正忙着吗？"
D.Strings[11928]="玛尔加尼斯肯定会派出天灾部队阻挠我们。我希望能有些精通剑术或魔法的勇士对抗天灾士兵。而我，会率领剩余的军队清理斯坦索姆中的亡灵，将全城拯救出来。"
D.Strings[11929]="嗯……它的确比之前碰见过的所有机器都诡秘复杂……啊，见鬼……敌人来了！"
D.Strings[11930]="玛多兰在上，这玩意到底干了些什么？哦！等等，我马上就搞定它了……"
D.Strings[11931]="哈，终于搞定了！援军来了！接招吧，你们这群白痴铁疙瘩！"
D.Strings[11932]="你摆出这种鄙视的面孔算什么意思？$B$B说到匹斯波特家族，名气可是响当当的！我的祖辈世代以炼金师为业，享有很高的声誉。$B$B不骗你！$B$B我敢说，无论是艾泽拉斯世界还是别的异位面，你找不出比匹斯波特家族更有才的炼金师啦！$B$B虽说我目前还挂着学徒的头衔，但我的技术是顶呱呱的！你要明白，在学术界，只有保持低调才能博得上位。$B$B我说，你是来帮我的吧？$B$B<小侏儒傲慢地笑了笑。>"
D.Strings[11933]="我会让你们见识见识先锋军的真正实力！"
D.Strings[11934]="听着，你去告诉舒维瑟尔和洛伊塔，就说我们已经控制住了这里的局势。他们不需要……什么？$B$B他们没派你来？那你干嘛还来浪费我的时间？$B$B我还有工作要做呢！"
D.Strings[11935]="嗨，没看见我正忙着吗？！$B$B你想看演出？乐队每晚8点开演。"
D.Strings[11936]="呃……好吧，好吧。我们需要测试一下设备。$B$B稍等。我来安排一场“排练”。$B$B你准备好了吗？"
D.Strings[11937]="<受伤的雨声神谕者痛苦地呻吟着。>"
D.Strings[11938]="啊！你竟然抢走属于我的猎物！基克吉克要干掉你！"
D.Strings[11939]="你好，$r。$b$b非常抱歉，你得体谅我一下，我现在实在是太忙了。"
D.Strings[11940]="%s愤怒地尖啸着，冲过来帮助她的孩子。"
D.Strings[11941]="$n，时间很紧迫。你准备好了吗？"
D.Strings[11942]="我准备好啦。你要的第一种材料是什么？"
D.Strings[11943]="在这里，东南方。啊，你也落到他们手里了……"
D.Strings[11944]="又有入侵者？我倒要看看谁敢和风险投资公司过不去！"
D.Strings[11945]="呃，居然能在这种地方遇到别的冒险者，这还真让我吃惊！$B$B既然你们在这里，就帮助我进入前面的大厅吧！如果我的研究理论没错的话，我们一定能在这里找到矮人一族起源的秘密！"
D.Strings[11946]="布莱恩，能帮助你是我们的荣幸！"
D.Strings[11947]="要是我的兄弟现在也在这里就好了。他们肯定不会相信这项发现有多么惊人！$B$B这座大厅是储存泰坦圆盘的档案馆；而这里，就是存储圆盘的地方。$B$B瞧！地板下就散落着泰坦圆盘！我们必须赶快行动，矮人一族有史以来最伟大的发现在等着我们呢。"
D.Strings[11948]="我会让你搭乘我的飞行器的。睁大你的眼睛，给我调查清楚赫米特的情况！"
D.Strings[11949]="警报：飞行器已被导弹锁定。启动闪避机动功能。"
D.Strings[11950]="似乎还要加点料……"
D.Strings[11951]="在它变浓之前，得加点……"
D.Strings[11952]="快，给我来点……"
D.Strings[11953]="我觉得还要加点……"
D.Strings[11954]="给我找些……"
D.Strings[11955]="结根草！"
D.Strings[11956]="腌鹰蛋！"
D.Strings[11957]="斑点杂色鸟粪！"
D.Strings[11958]="干瘪的蝙蝠翼！"
D.Strings[11959]="陈年苹果冰酒！"
D.Strings[11960]="石像鬼牙齿粉末！"
D.Strings[11961]="泥潭蛆虫！"
D.Strings[11962]="尖刺蜘蛛卵！"
D.Strings[11963]="毛茸茸的鲱鱼头！"
D.Strings[11964]="恶臭的海盗汗液！"
D.Strings[11965]="冰冠冰川的水！"
D.Strings[11966]="蜂翼！"
D.Strings[11967]="原始魔精！"
D.Strings[11968]="迅猛龙爪！"
D.Strings[11969]="琥珀种子！"
D.Strings[11970]="皱巴巴的龙爪！"
D.Strings[11971]="冰冷的毒蛇粘液！"
D.Strings[11972]="结晶的野猪鼻涕！"
D.Strings[11973]="碎裂的石化蜥蜴水晶！"
D.Strings[11974]="巨魔杀除剂！"
D.Strings[11975]="结冰的蜘蛛毒液！"
D.Strings[11976]="我们需要一些……"
D.Strings[11977]="我们得添加一些……"
D.Strings[11978]="接下来，我们需要……"
D.Strings[11979]="趁它沸腾之前，我还需要……"
D.Strings[11980]="变浓稠啦！快，拿些……"
D.Strings[11981]="进展顺利，但是还需要一些……"
D.Strings[11982]="就快成功啦。给我找些……"
D.Strings[11983]="天哪！药水全毁啦！"
D.Strings[11984]="太晚了。我不得不重新开始……"
D.Strings[11985]="嗯，是时候啦……"
D.Strings[11986]="这么说，神谕者决定帮助你了。好吧，我会把我所知的一切都告诉你。"
D.Strings[11987]="碎角犀牛的族长法鲁恩就是你的同伴寻找的目标。他很少和族群的其他成员待在一起。"
D.Strings[11988]="法鲁恩喜欢独自在苦潮瀑布以北的林地游荡。你可以在那里找到他；不过你很快就会明白，他并不需要族群其他成员的保护。"
D.Strings[11989]="告诉你的同伴，让他去那里猎杀法鲁恩，然后领取奖赏吧。"
D.Strings[11990]="事情办完之后，就让他趁早离开。他并不属于这里。"
D.Strings[11991]="那些疯狂的达卡莱巨魔竟然击落了一座浮空城！$B$B他们是如何做到的？！"
D.Strings[11992]="啊，当初真不该抢着要专家的名头。他们老是让我做一些根本就不可能的事！"
D.Strings[11993]="来玩玩吧！"
D.Strings[11994]="你们来的太迟了，洛丹伦的勇士们，现在已经是亡灵的时代了。"
D.Strings[11995]="快，$c！$b$b把材料都扔进去。时间紧迫！"
D.Strings[11996]="<当你靠近时，被俘虏的鳄鱼发出一声低吼。>"
D.Strings[11997]="看来不会有什么危险……来吧。"
D.Strings[11998]="今天特别适合出门劫掠一番，不是吗？"
D.Strings[11999]="远行者，那些炮火……呃，我是说那些人……他们是对抗维库人的重要资源。啊，我说的是“资源”？好吧，我的意思是“盟友”。"
D.Strings[12000]="<俯下身去扶起受伤的雨声神谕者。>"
D.Strings[12001]="哎呀，好粘啊！它们是怎么结网的啊？"
D.Strings[12002]="啊！见鬼，我把自己给网住了！粘死啦。哎呀，我的发型！"
D.Strings[12003]="好吧！让我看看能不能将这堆破铜烂铁改造成有用的装置。"
D.Strings[12004]="我知道了！"
D.Strings[12005]="萨满祭司维克伊克从旁边的灌木丛中走了出来。"
D.Strings[12006]="你竟然帮助雨声鳄鱼人！我都看见了！你这个叛徒！"
D.Strings[12007]="如果你要和大舌头怪交朋友，那你就不是狂心狼獾人的朋友啦！我要告诉全村人！我们再也不会相信你了！"
D.Strings[12008]="萨满祭司维克伊克朝狂心岭的方向奔去。"
D.Strings[12009]="勇敢的士兵，你从未放弃过对抗玛尔加尼斯统帅的天灾军团。继续努力吧。"
D.Strings[12010]="没错。玛尔加尼斯就在十字军广场指挥天灾军团，但是从斯坦索姆入口通往广场的大门都被关闭了。$B$B如果我率领一支小分队穿过市政厅的话，也能抵达十字军广场。所幸的是，玛尔加尼斯并不知道这一点。你愿意加入我们的突袭行动吗？"
D.Strings[12011]="殿下，我们的所作所为都是为了洛丹伦的利益。"
D.Strings[12012]="带路吧，阿尔萨斯王子。"
D.Strings[12013]="我们得搞清楚，为什么天灾军团如此看重这种矿石。"
D.Strings[12014]="科尔法克斯，你知道萨隆邪铁吗？"
D.Strings[12015]="没听说过。它似乎散发着邪恶的气息。"
D.Strings[12016]="我倒要看看它能不能挡住我的斧子！"
D.Strings[12017]="见鬼！连一丝裂痕都没留下！这是我见过的最硬的矿石！"
D.Strings[12018]="谢谢！"
D.Strings[12019]="就快到家啦。走吧！"
D.Strings[12020]="啊啊！它直冲着我们来了！"
D.Strings[12021]="我的胡子！两边不对称了！"
D.Strings[12022]="耳朵！你弄伤了我的耳朵！"
D.Strings[12023]="痛！我不干了，我不要当靶子！"
D.Strings[12024]="莱茵，雷布拉特，试试自然与元素的力量？"
D.Strings[12025]="冷静点，伙计。这只是小号铅弹啊！"
D.Strings[12026]="呸，还是有进步的。"
D.Strings[12027]="女神在上。自然的力量也无法撼动它！"
D.Strings[12028]="别抱怨了。你的运气还不错啊。"
D.Strings[12029]="只是有点伤自尊嘛，伙计。振作一点啦！"
D.Strings[12030]="没有用。"
D.Strings[12031]="梅兹？"
D.Strings[12032]="你会什么力量啊。"
D.Strings[12033]="有什么值得大惊小怪的。"
D.Strings[12034]="什么？"
D.Strings[12035]="好吧。不过你记住，圣光的力量是不能随便运用的。"
D.Strings[12036]="怎么回事？！"
D.Strings[12037]="好吧，事情毫无进展。我们还是将这块萨隆邪铁交给大领主弗丁研究吧。"
D.Strings[12038]="朋友们，谢谢你们的尝试。我们一定会揭开其中秘密，只希望一切不会太迟。"
D.Strings[12039]="很快你们就会发现一切都是徒劳无功。"
D.Strings[12040]="好准！"
D.Strings[12041]="萨隆邪铁？"
D.Strings[12042]="战争之鼓"
D.Strings[12043]="我倒要看看它是否真的坚不可摧。"
D.Strings[12044]="%s转了转眼珠。"
D.Strings[12045]="受伤的雨声神谕者笨拙地站了起来。"
D.Strings[12046]="哇！"
D.Strings[12047]="嗷！"
D.Strings[12048]="%s掸去身上的灰尘。"
D.Strings[12049]="你竟然和大舌头怪搅和在一起！你不再是狂心氏族的朋友了。狂心狼獾人要让你尝尝厉害！"
D.Strings[12050]="不妙！我们被狗狗人跟踪了！"
D.Strings[12051]="跟我来，我知道路。"
D.Strings[12052]="先生，有客户投诉说我们出售的致命药膏中，魔女之毒的含量不足。"
D.Strings[12053]="先生，有客户投诉说我们出售的麻醉药膏中，丧命草的含量过高。"
D.Strings[12054]="先生，我认为上一张配方中死亡根须的用量已经很接近合适剂量了。"
D.Strings[12055]="乌雷特，你调配出新的混合药剂了吗？店里堆满了该死的孢子，我快被烦死了！"
D.Strings[12056]="下次放双倍的剂量好了！"
D.Strings[12057]="下次就放一半的剂量吧。"
D.Strings[12058]="记住：你犯下的错误永远比你想象的要严重得多。给我加双倍的剂量！"
D.Strings[12059]="我还在调制啊，我可不想随便出售连我自己都不满意的半成品。用不了多久啦。"
D.Strings[12060]="残忍的斯卡迪已经进入鱼枪的射程！"
D.Strings[12061]="你每次都这么说。有时候，我甚至怀疑你永远也配制不出那玩意儿。"
D.Strings[12062]="啊，是阿尔萨斯王子。您来的正是时候。"
D.Strings[12063]="是的，我很高兴能在灾难大爆发之前找到你。"
D.Strings[12064]="这是什么巫术？"
D.Strings[12065]="阿尔萨斯，你不需要弄明白这是什么。你唯一要做的，就是等死。"
D.Strings[12066]="部落占领了冬拥堡垒！"
D.Strings[12067]="联盟占领了冬拥堡垒！"
D.Strings[12068]="你要去哪儿吗？我可以送你一程。"
D.Strings[12069]="我能不能搭乘飞行器呀？"
D.Strings[12070]="卡拉，我想飞往亡者之穴寻找比希。"
D.Strings[12071]="嘲讽旗"
D.Strings[12072]="熊坐骑"
D.Strings[12073]="我准备好前往你的村子了。"
D.Strings[12074]="等你做好准备，我们就启程回家吧。"
D.Strings[12075]="带我离开这个鬼地方，$r！"
D.Strings[12076]="你听到附近传来一声低沉的咆哮。"
D.Strings[12077]="自动跳舞信号发射器"
D.Strings[12078]="别打扰维克伊克。"
D.Strings[12079]="维克伊克，我诚恳地和大舌头怪们谈过了，他们渴望和平。这是他们赠送的求和礼物。"
D.Strings[12080]="你居然和大舌头怪交朋友，真恶心！你不属于这里。赶紧滚出狂心氏族的土地，不然我就召唤魔法生物干掉你！"
D.Strings[12081]="狂心氏族永远不会和大舌头怪做朋友。你这个叛徒，竟然还有脸回来！"
D.Strings[12082]="你要是敢回来，狂心狼獾人就要你的命。从现在开始，你是我们的敌人！"
D.Strings[12083]="没有……我没有背叛狂心氏族的意思。我当时只是……正当防卫啊。完全是个误会。"
D.Strings[12084]="$r飞行员来啦！击落$g他:她;！"
D.Strings[12085]="看来玛尔加尼斯除了天灾军团的亡灵大军外，还另有秘密武器。我们得抓紧时间了。"
D.Strings[12086]="你可能为我带来救赎的希望。$B$B你也可能将我送入死亡的深渊。"
D.Strings[12087]="又是这种邪恶的巫术！提高警惕！"
D.Strings[12088]="我的宝藏！可耻的叛徒，不许偷塔尔特克的东西。"
D.Strings[12089]="塔尔特克要和凶暴的龙一起杀了你！蠢货。"
D.Strings[12090]="我还以为自己死定了呢！"
D.Strings[12091]="朋友，我欠你一份情。"
D.Strings[12092]="你没见过始祖龙吗？喏，这周围到处都是啊。祝你狩猎愉快。"
D.Strings[12093]="小心背后，我们被包围了。"
D.Strings[12094]="玛尔加尼斯不会让我们好过的。"
D.Strings[12095]="%s开始施放强化魔爆术！"
D.Strings[12096]="它们还真是够顽强的。"
D.Strings[12097]="他还会派些什么东西来阻挡我们？"
D.Strings[12098]="通向玛尔加尼斯的最短路线就在前面那个书架之后。"
D.Strings[12099]="不要给他喘息的机会！"
D.Strings[12100]="如果伦诺克恢复力量，那我们就死定了！"
D.Strings[12101]="必须让巨熊之神处于虚弱状态，这样先知才能完成仪式。"
D.Strings[12102]="入侵者！杀死他们，不然他们会毁了一切！"
D.Strings[12103]="阿尔萨斯·米奈希尔王子殿下，今天，你的灵魂已经被某种强大的黑暗力量侵蚀。你想要以死亡净化这座城市，现在你也要面对毁灭的命运了。"
D.Strings[12104]="为了洛丹伦，我会竭尽所能，无论是你的言论还是行为，都无法阻止我。"
D.Strings[12105]="那就来吧，年轻的王子。"
D.Strings[12106]="你听见什么了吗？"
D.Strings[12107]="很抱歉，我们的啤酒只对“本月美酒俱乐部”的会员出售。"
D.Strings[12108]="这座岗哨目前是安全的，$r。$b$b敌人暂时不敢再次来犯。"
D.Strings[12109]="天灾军团扩张如此迅速，我有时都忍不住会想，他们怎么还没赢得这场战争呢。"
D.Strings[12110]="啊，终于回到了达克萨隆要塞！"
D.Strings[12111]="达库鲁凝视着达克萨隆要塞。"
D.Strings[12112]="朋友，干得好……"
D.Strings[12113]="你远远超出了我的期望。"
D.Strings[12114]="我可不管长者怎么说，反正你永远都是格利基克的奴隶。"
D.Strings[12115]="匹奇根本构不成威胁嘛……要不然格利基克肯定不会放过他。"
D.Strings[12116]="狂心狼獾人用大舌头怪喂养卡塔克，保证自己不会沦为他的食物。奴隶，这就是我们比你聪明的证据。"
D.Strings[12117]="狂心狼獾人最厉害！"
D.Strings[12118]="到家啦！奴隶，你最好为格利基克带回了足够的肉。"
D.Strings[12119]="格利基克去搞点酒喝。你乖乖地待在角落里等我。"
D.Strings[12120]="格利基克饿死了。奴隶，快趴到火堆上去。等你烤熟之后告诉格利基克一声。"
D.Strings[12121]="你最好耐心地等着格利基克。"
D.Strings[12122]="格利基克要去睡一会儿。奴隶，你去给我搞点吃的回来。"
D.Strings[12123]="格利基克的主要工作之一就是猎捕硬皮猩猩。"
D.Strings[12124]="猎杀硬皮猩猩对格利基克来说容易极了……它们很愚蠢的。"
D.Strings[12125]="奴隶，你待在一旁看着就是了。让格利基克来对付这些硬皮猩猩！"
D.Strings[12126]="别挡格利基克的道！"
D.Strings[12127]="吃到苦头了吧！哈哈！你这蠢奴隶。"
D.Strings[12128]="当心点，坏心肠的软皮猩猩能一口吃掉你！哈哈！"
D.Strings[12129]="哈！是格利基克杀的！"
D.Strings[12130]="格利基克是最好的猎人……永远是。"
D.Strings[12131]="一击必中！格利基克真厉害。"
D.Strings[12132]="格利基克为什么要带上你啊。你这废物。"
D.Strings[12133]="下次格利基克让你试试。"
D.Strings[12134]="凭借邪恶的力量，我们才能统御亡者！"
D.Strings[12135]="奥莉丝塔夫人，我想接受训练。"
D.Strings[12136]="鲜血就是生命……如果能随意掌控鲜血的奔涌，那么敌人的性命也就如同掌中玩物了。"
D.Strings[12137]="索瓦尔勋爵，我想接受训练。"
D.Strings[12138]="凛冽的北风承载着我们散发出的不祥气息。我们就像绝望的寒冬……接受死亡的冰封之拥吧……"
D.Strings[12139]="阿曼萨加德，我想接受训练。"
D.Strings[12140]="将你的肉体抛诸脑后吧！"
D.Strings[12141]="多里安，你错过了一场惊心动魄的战斗！真是难忘的经历啊！"
D.Strings[12142]="我们骑在斯塔比背上，全速开战……"
D.Strings[12143]="我感觉周围的景象在颤抖，差点抓不住手中的枪。"
D.Strings[12144]="接着，那只恐怖的野兽进入了我们的视线！"
D.Strings[12145]="$n全神贯注地控制斯塔比战斗。"
D.Strings[12146]="达卡莱帝国走上了自我毁灭的道路，我们为此感到悲哀。$B$B他们通过弑神夺来的力量只能维持一段很短的时间。$B$B这短暂的收益将葬送达卡莱帝国的未来。"
D.Strings[12147]="这场战斗真是腥风血雨啊。母龙的攻击速度越来越快了！"
D.Strings[12148]="但是，我，还有$n凭借卓越的智慧和完美的合作，最终取得了胜利。喏，这就是我们的战利品。"
D.Strings[12149]="这一切……都是毫无意义的。"
D.Strings[12150]="这就是反抗巫妖王的下场！"
D.Strings[12151]="多里安，怎么你看上去有点嫉妒啊？"
D.Strings[12152]="呃，才没有。我是来照料篝火堆的，顺便找苏特菲兹谈谈机械零件的缺陷问题。我承认，这件战利品看上去是挺不错的。"
D.Strings[12153]="集中精神，我们必须继续前进。"
D.Strings[12154]="这只需要一小会儿。"
D.Strings[12155]="我确信这条秘道还通着。"
D.Strings[12156]="局势严峻。斯坦索姆正在燃烧。我们必须穿越着火带，击杀沿途的天灾军团，设法抵达玛尔加尼斯所在的十字军广场。做好准备吧。"
D.Strings[12157]="为洛丹伦而战！"
D.Strings[12158]="休息一会，你们抓紧时间喘口气，我们马上就得重新上路。"
D.Strings[12159]="希姆托加倒是能为我们提供一定的保护，但是天灾军团的势力不断扩张，再加上达卡莱帝国的弑神举动，她的力量已经被严重削弱了。$B$B因此防御的重任就落在我和埃霍奈的肩上了。"
D.Strings[12160]="就这样吧，我们必须继续上路了。玛尔加尼斯在等着我们呢。"
D.Strings[12161]="圣光在上。市场小径还没有着火。玛尔加尼斯应该就躲藏在前面的十字军广场。你们准备好继续前进的话，就告诉我。"
D.Strings[12162]="愚蠢的奴隶，别挡道！这是格利基克的猎物！"
D.Strings[12163]="哈哈！格利基克是最最厉害的猎手！格利基克杀死了个头最大的硬皮猩猩！"
D.Strings[12164]="奴隶，看清楚了吧。或许有一天你也能领悟这一招。"
D.Strings[12165]="你一边呆着去，奴隶。格利基克正在吃饭呢。"
D.Strings[12166]="格利基克要去抓鸡！"
D.Strings[12167]="它们可真灵活！"
D.Strings[12168]="快跑呀，软皮猩猩！格利基克来抓你们啦！"
D.Strings[12169]="软皮猩猩是我们重要的生活来源。"
D.Strings[12170]="埃霍奈的斧头就是达卡莱巨魔的末日。$B$B即便有一些漏网之鱼从我的斧下逃脱，你也会干掉他们！"
D.Strings[12171]="狡猾的法师领主伊洛姆守护着第三道环。表面上他显得孤立无援，但那不过是欺骗敌人的假象！伊洛姆是位强大的咒术师，能召唤各种幽灵生物为他作战。去上面找他吧。\n\n我能赋予你召唤红玉幼龙协同作战的能力。当然，如果你希望借助青铜龙或是绿龙的力量，就去找伊特努斯或是沃尔蒂萨谈谈。"
D.Strings[12172]="你即将面临迄今为止最大的挑战。魔网守护者埃雷苟斯，这只蓝龙拥有超乎想象的可怕力量。埃雷苟斯在魔枢的最高环飞翔。\n\n现在，幼龙的终极力量已经解封。利用它们的力量击败埃雷苟斯吧！"
D.Strings[12173]="你从玛里苟斯的部队手中夺得了魔环的控制权。红龙军团欠你一个人情。"
D.Strings[12174]="青铜龙军团欠你一个人情。"
D.Strings[12175]="绿龙军团欠你一个人情。"
D.Strings[12176]="红玉幼龙有什么能力？"
D.Strings[12177]="琥珀幼龙有什么能力？"
D.Strings[12178]="翡翠幼龙有什么能力？"
D.Strings[12179]="红玉幼龙的终极技能是什么？"
D.Strings[12180]="琥珀幼龙的终极技能是什么？"
D.Strings[12181]="翡翠幼龙的终极技能是什么？"
D.Strings[12182]="红玉幼龙擅长降低伤害以及保护盟友。\n\n它们使用灼热之怒喷出液体火焰，在敌对目标之间跳跃，每次跳跃都能增加对目标的伤害。\n\n当红玉幼龙受到攻击时，它将获得可叠加的闪避能量，由此触发的闪避机动可使幼龙暂时躲过接下来的攻击与法术伤害。"
D.Strings[12183]="琥珀幼龙擅长操控时间来制造伤害。\n\n它们使用震击之枪扰乱敌对目标附近的时间流，立即对目标造成伤害。震击能量将在目标身上叠加，叠加次数越多，目标受到的伤害就越高。\n\n危急时，琥珀幼龙还能停止敌对目标的时间流。在这种情况下，目标身上将储存大量的震击能量。"
D.Strings[12184]="翡翠幼龙擅长在毒伤敌人的同时治疗自己。\n\n它们使用吸血之毒从敌对目标身上偷取生命。毒药可以叠加，每次叠加都能增加生命偷取的效果。\n\n翡翠幼龙还能使用噩梦之触进入梦境，将一部分自身的生命能量转化成高伤害的攻击，令敌对目标虚弱并在短时间内降低目标造成的伤害。"
D.Strings[12185]="拥有终极力量的红玉幼龙可以使用殉难，撑起护盾保护友方目标，短时间内对友方目标的所有魔法伤害将由红玉幼龙承担。使用该技能的同时仍可触发闪避机动。"
D.Strings[12186]="全盛状态的琥珀幼龙可以使用时间裂隙，制造出压缩时间结界包围敌对目标。穿过结界的法术将对该目标造成双倍的伤害，还能在目标身上叠加震击能量。"
D.Strings[12187]="全盛状态的翡翠幼龙可以使用梦境通道，将自身的生命能量转移到友方目标身上，以此进行治疗。使用该技能的同时仍可利用吸血之毒恢复生命值。"
D.Strings[12188]="小……小姐，您的盔甲需要抛……抛光吗？"
D.Strings[12189]="小……小姐，您的战马需要梳……梳洗吗？"
D.Strings[12190]="小……小姐，您需……需要更多的尸尘吗？"
D.Strings[12191]="遵命，尊贵的小……小姐……"
D.Strings[12192]="离我远点，爱德华。否则我要你好看。"
D.Strings[12193]="别出现在我面前，不然我杀了你。我再说一次。"
D.Strings[12194]="不要。滚远点。"
D.Strings[12195]="对于你付出的努力，我一定要给你丰厚的报酬……"
D.Strings[12196]="真相！"
D.Strings[12197]="朋友，现在来安静地领悟真相吧！"
D.Strings[12198]="我……我就要挂了……要坚持……不住了……"
D.Strings[12199]="哈！别想夺走我的财宝！"
D.Strings[12200]="杀光他们！杀光他们，夺回希姆托加！"
D.Strings[12201]="主人，我的任务完成了。"
D.Strings[12202]="杀死赞达拉巨魔和他们的傀儡！谁也别想阻止我们！"
D.Strings[12203]="在这些凡人的帮助下，所有胆敢反抗我们的家伙都已经被清除了。"
D.Strings[12204]="你做得很好，达库鲁。"
D.Strings[12205]="你对达卡莱帝国的背叛为我制造出了一支新的军团。"
D.Strings[12206]="你的军团……"
D.Strings[12207]="平身，接受我的赏赐吧。"
D.Strings[12208]="朋友，欢迎你。在这里记得随时保持警惕！"
D.Strings[12209]="如果你是来戳软皮猩猩的话，达伊克就要戳你了。别学格利基克的坏习惯。"
D.Strings[12210]="哈……我们在哪儿？不对呀。我们不是来找硬皮猩猩的吧？"
D.Strings[12211]="不久前，狂心氏族在这里安了新家……大舌头怪的屋子看上去很漂亮啊，我们其实可以抢来自己住。它们那么丑，才不配住这么好看的地方。"
D.Strings[12212]="看看你有没有忘记什么东西啊。我以前就老忘事儿。"
D.Strings[12213]="我在栅栏上安了许多尖刺。它们看上去挺锋利的。你觉得呢？"
D.Strings[12214]="这里有许多优秀的猎手，大部分都是达伊克调教出来的。不过教你这样的家伙还是头一次。要知道，你并不是狂心氏族的成员。"
D.Strings[12215]="哈！或许你能学到点什么！"
D.Strings[12216]="蜂后是杀不绝的。很快就会产生新的蜂后。"
D.Strings[12217]="什么！你杀死了蜂后！怎么可能……呃，没什么。好吧，没什么。"
D.Strings[12218]="对！多捅几下，以防万一！捅得好！捅得好！"
D.Strings[12219]="真不明白它怎么能捕杀那些多生物。不过反正它已经死了，威胁解除啦。"
D.Strings[12220]="达伊克的上一个学徒就是被躲在沙里的怪物给吃掉的。我们最好别落得同样的下场！"
D.Strings[12221]="再来听听达伊克的小建议！好多亡灵啊，这意味着我们有很大的几率被变成亡灵。达伊克要逃命去了。"
D.Strings[12222]="好吧！你什么都学会啦！没错！达伊克不管你了，你去研究那根邪恶的红柱子吧。"
D.Strings[12223]="你看那堆死尸，这就是靠近破柱子的下场。它们已经得到教训了。我们回家吧。"
D.Strings[12224]="再来听听达伊克的小建议！如果格利基克又把鸡给放跑了，就让他把鸡们都捉回去。"
D.Strings[12225]="你可能没注意到，鸡……跑得有点快。"
D.Strings[12226]="狂心狼獾人不去追鸡是有原因的。因为如果追不上的话，就太丢脸了。"
D.Strings[12227]="噢！达伊克想到个办法！我们来学鸡叫，它们或许会循声而来！"
D.Strings[12228]="我们改吃钢刺野猪怎么样？我不要再跑来跑去的。"
D.Strings[12229]="再来听听达伊克的小建议！在你搜刮战利品之前，要确保敌人已经死翘翘了。"
D.Strings[12230]="把尸体清理干净！达伊克最讨厌剥皮的时候被什么东西给挡着了。很烦人的。"
D.Strings[12231]="你瞧见它的脸了吗？一副惶恐的表情，“啊，我要被那个大家伙砸扁啦！”哈哈哈。"
D.Strings[12232]="达伊克从来没有见你吃过东西。你也要吃东西的，对吧？"
D.Strings[12233]="再来听听达伊克的小建议！尽量别用脸去挡刺。没什么用的。"
D.Strings[12234]="我本来想写一份详细的攻击计划的……但是你拿走了我的笔。"
D.Strings[12235]="雄蜂只是外表凶悍而已，其实很容易对付的。巨蜂就比较麻烦一点。"
D.Strings[12236]="我们来这里是有目的，对吧？我想不起来了。"
D.Strings[12237]="每次来虫巢，达伊克都觉得这里的巨蜂又变多了。它们的数量怎么就不见少呢？"
D.Strings[12238]="我告诉你，被蜇的滋味可不好受。你最好别去尝试。"
D.Strings[12239]="再来听听达伊克的小建议！水晶不适合用来挠背。你最好别去尝试。"
D.Strings[12240]="有时候大舌头怪会来这里采集水晶。当然，它们现在敢来的话，就是找死。"
D.Strings[12241]="某个强大的存在制造了柱子、水晶以及别的东西。不过它已经不在这里了，所以我们不用害怕。"
D.Strings[12242]="达伊克一直想教我狩猎的技巧，事实上，我按自己的方式来做，效果反而更好。"
D.Strings[12243]="只要你能带回上等的肉，我们就把你当作高阶萨满祭司那样伺候一天。很不错的交易吧。"
D.Strings[12244]="你应该把鸡们都放出来，然后说是格利基克干的。这招屡试不爽。"
D.Strings[12245]="我又不急着办什么事。我们甚至可以在这里休息一阵子。"
D.Strings[12246]="我很少呆在营地……不久前，我还独自游历了不少地方呢。嗯，我喜欢那些关于野兽、巨龙和神灵的传说。"
D.Strings[12247]="长者哈尔卡克是个大好人。在我年幼的时候，他帮过我很多忙，一点也不像达伊克。"
D.Strings[12248]="哈哈哈！你看见没有？闪电直接击中了他！"
D.Strings[12249]="砰！真棒！再来！再来！"
D.Strings[12250]="附近的湖里全是海洋生物。不知道是怎么来的……莫非是洪水？"
D.Strings[12251]="我喜欢狩猎大舌头怪的原因之一……就是它们不像其他猎物那样愚蠢。懂得耍花招的猎物才是真正的挑战。"
D.Strings[12252]="雾语大舌头怪很会利用那些祭坛捣鬼……它们能让迷雾覆盖整片区域，令我们难以发现它们的行踪。"
D.Strings[12253]="格利基克才不会错过抓鸡活动呢……格利基克得填饱他的肚子。每次抓完鸡，我们都会发现有一只鸡不见了。"
D.Strings[12254]="技术不错嘛！狩猎手法和我一样纯熟自然。"
D.Strings[12255]="格利基克总是摆出一副高高在上的模样，但这家伙每天吃那么多，打回来的猎物却少得可怜。"
D.Strings[12256]="达伊克经常会忘记他在做什么，忘记他在哪儿……甚至会忘记自己的名字。有时候，他还真算不上是个好老师。"
D.Strings[12257]="你有没有跟巨龙、神灵或者别的什么打过架啊？瑟匹克最喜欢听故事啦。"
D.Strings[12258]="干得好！它一点也没有察觉。"
D.Strings[12259]="哈哈！给瑟匹克留点猎物吧。"
D.Strings[12260]="不玩了？"
D.Strings[12261]="烈焰！死亡！毁灭！黑色的火焰在我心中燃烧！我必须……释放它！哈哈哈！"
D.Strings[12262]="欢迎来到营地，$c。"
D.Strings[12263]="科弗斯能为你提供什么服务？"
D.Strings[12264]="使用灼热之怒对敌人造成伤害；如果我开始承受伤害，就使用闪避机动。记住，我必须以承受伤害的方式积攒闪避能量，才能使用闪避机动！"
D.Strings[12265]="使用吸血之毒对敌人造成伤害，同时保持对我的治疗。噩梦之触非常强大，但会对我造成伤害，所以只能在我的生命值较高的情况下使用！"
D.Strings[12266]="使用震击之枪对敌人造成伤害。如果我们遇到麻烦，就使用停止时间将敌人冻结，然后使用震击之枪对他们造成大量伤害！"
D.Strings[12267]="我伤得很重！我无法承受更多的伤害了！"
D.Strings[12268]="我已经具备全部力量，可以使用时间裂隙了。你能利用它对敌人造成额外的伤害并获得震击能量。积攒足够的能量后，再使用震击之枪造成大量伤害！"
D.Strings[12269]="我已经具备全部力量，可以使用梦境通道了。你能利用它治疗其他幼龙，但这个技能会消耗我的生命值，因此必须与吸血之毒配合使用！"
D.Strings[12270]="我已经具备全部力量，可以使用殉难了。你能利用它保护其他幼龙，但这会让我承受大量伤害，因此必须与闪避机动配合使用！"
D.Strings[12271]="噢！闪闪发亮的宝贝！"
D.Strings[12272]="拉弗乌的宝藏！祭坛的宝藏！"
D.Strings[12273]="我挖，我挖，我挖……"
D.Strings[12274]="没准还有更多闪闪发亮的虫虫！我们爱虫虫！"
D.Strings[12275]="它再也不能来捣乱啦！"
D.Strings[12276]="嘶嘶……嘶嘶……死了。都死了。"
D.Strings[12277]="你的眼珠看起来好有趣。"
D.Strings[12278]="我没有见过造物主。真的，只见过他们留下的祭坛。"
D.Strings[12279]="大树。温暖的家。"
D.Strings[12280]="这些虫虫又脆又美味。要不要来点？"
D.Strings[12281]="没准你能成为索干皮。你喜欢吗？"
D.Strings[12282]="太古怪了。有人把虫虫都抢走了。不会是你干的吧？"
D.Strings[12283]="有馅饼吗？以前有人给过我一块馅饼。好吃极了！"
D.Strings[12284]="更多的宝藏！各种各样的宝藏！宝藏！"
D.Strings[12285]="亮闪闪！亮闪闪！虽然不如我的水晶闪亮，但依然很闪亮！"
D.Strings[12286]="我们挖地的速度可快啦！真的哦！你瞧……完成啦！是不是很快呀？"
D.Strings[12287]="亮闪闪的水晶怎么都不嫌多啊！不嫌多！"
D.Strings[12288]="塔尔特克比不上你！你真够厉害的。呀！"
D.Strings[12289]="让你偷我们的财宝！财宝属于……我们，明白吗？！"
D.Strings[12290]="雾气。好重的雾气啊。对你来说，这或许算不上浓雾吧？"
D.Strings[12291]="唤雾者擅长利用祭坛来控制气候。他们知道各种水晶的用途！对，他们知道得一清二楚！"
D.Strings[12292]="你喜欢吗？我打赌你不会喜欢的！因为你已经死啦！哈哈哈！"
D.Strings[12293]="影舞步！"
D.Strings[12294]="胜……利……啦！啾啾啾！"
D.Strings[12295]="家！家！家……闪闪发亮的地方！"
D.Strings[12296]="家里真好，可惜呆不长！我们要更多的冒险！"
D.Strings[12297]="来来，一起从树上跳下去吧！超级好玩！"
D.Strings[12298]="追赶幼体！追赶幼体！快跑！"
D.Strings[12299]="造物主能够保证家的安全，因为他们喜欢先知！他们知道鳄鱼人都是好人。"
D.Strings[12300]="我们知道你们有龙！但我们不怕！我们要将你们统统打扁！"
D.Strings[12301]="逃命去吧，狗狗人！我们来抓你们啦……最好滚回自己的山上去！"
D.Strings[12302]="唉……又是泥土。"
D.Strings[12303]="嗨……或许我们会找到更多没用的虫虫。"
D.Strings[12304]="这里怎么会有亮闪闪的兔子啊？"
D.Strings[12305]="你瞧，我刚刚认识那家伙，他就派我来这里挖掘没用的小玩意儿……你觉得这件事正常吗？"
D.Strings[12306]="我不敢相信……他们全都……死了。"
D.Strings[12307]="整个苔行村都在谈论异常的气候时，索乌塞没有采取任何措施，现在他们都死了……你觉得这件事正常吗？"
D.Strings[12308]="又倒下一个。"
D.Strings[12309]="呀，我们出发吧。"
D.Strings[12310]="事情办好啦。"
D.Strings[12311]="为什么我们还留在这里？给我个说得过去的理由啊。"
D.Strings[12312]="我是最聪明、最强壮、最有修养的鳄鱼人，但是索乌塞却拥有氏族的统治权……你觉得这件事正常吗？"
D.Strings[12313]="唯一值得欣慰的是，他们没有变成亡灵。"
D.Strings[12314]="现在，我命令你去净化祖达克，达库鲁。"
D.Strings[12315]="令我失望，你就将迎来末日……"
D.Strings[12316]="获得成功，更加强大的力量就唾手可得！"
D.Strings[12317]="遵命，我的主人。"
D.Strings[12318]="朋友，请原谅，我欺骗了你。这样是为了你好。"
D.Strings[12319]="那时，你要证明自己的价值……"
D.Strings[12320]="而我，则急需优秀的下属，能支配强大力量的下属，在祖达克为我效劳。"
D.Strings[12321]="自己权衡一番吧。要知道，巫妖王陛下对于所有忠诚的仆从都非常慷慨。"
D.Strings[12322]="朋友，只要踏上这条路，很快你也能成为不朽的存在！"
D.Strings[12323]="仔细回想今天你目睹的一切，$n。$B$B未来已经注定，你唯一需要考虑的只是你想在其中扮演怎样的角色。"
D.Strings[12324]="玛里苟斯最强大的仆从守卫着上层的环。单凭你的力量，根本不可能战胜他们。我们将赋予你召唤幼龙的能力。你可以骑着幼龙在魔环飞翔并使用强大的龙族魔法。"
D.Strings[12325]="接下来，我们要去哪儿？"
D.Strings[12326]="贝加里斯塔兹说得没错，时间不多了！\n\n幼龙的终极力量已经解封。使用它们的力量击败埃雷苟斯吧！"
D.Strings[12327]="贝加里斯塔兹说得没错，情况非常危急。\n\n幼龙的终极力量已经解封。使用它们的力量击败埃雷苟斯吧！"
D.Strings[12328]="上古之神，我们乞求你的帮助。我们应该怎么做，才能拯救这片土地的神灵？"
D.Strings[12329]="必须找到雪豹女神。他们的命运与此休戚相关。"
D.Strings[12330]="不过她被锁住了。必须设法搭救她。"
D.Strings[12331]="这名凡人必须前往她的祭坛。他们必将肩负起艰难的使命，甚至可能面临失败的惨境。"
D.Strings[12332]="但是他们必须尝试，否则一切都完了。达卡莱巨魔很可能将自己和他们崇拜的神灵送上绝路！"
D.Strings[12333]="没有谁比死亡骑士更了解天灾军团。$B$B相信我，$r。全力火拼，以牙还牙才是最奏效的战争策略。"
D.Strings[12334]="对老纳斯宽容点。他年纪大了，体力早已不如从前。"
D.Strings[12335]="我找不到纳斯了……"
D.Strings[12336]="老纳斯每次都能找到回来的路，真是奇怪。肯定是靠闻的吧……"
D.Strings[12337]="事情到底有完没完啊？"
D.Strings[12338]="每收集一束毛发，就损失一份尊严……"
D.Strings[12339]="他说，我们去祖达克。他说，这样我们才能查明真相……"
D.Strings[12340]="你控制了阿彻鲁斯之眼。"
D.Strings[12341]="哈！真有趣！"
D.Strings[12342]="相信我——你会喜欢的！"
D.Strings[12343]="尝尝厉害吧，大舌头怪！"
D.Strings[12344]="我的同胞或许会让你探索祖达克的秘密，但是赞达拉氏族始终肩负着见证历史的使命，并将如实地记载巨魔帝国毁灭的篇章。"
D.Strings[12345]="笨蛋！停止射击！格利基克想要完整的战利品！"
D.Strings[12346]="别让它逃走！这次一定要抓住它。"
D.Strings[12347]="当心！别像上次那样被它抓伤了。"
D.Strings[12348]="勇士，今天不应该是你的死期。复活吧！站起来，再次投身战斗！"
D.Strings[12349]="嗨，巨魔……这是给你的礼物！"
D.Strings[12350]="你准备好和我一起挑战玛尔加尼斯了吗？"
D.Strings[12351]="阿彻鲁斯之眼朝目标发射能量。"
D.Strings[12352]="唷……真恶心！"
D.Strings[12353]="给我的？真的吗？"
D.Strings[12354]="太……太漂亮了！"
D.Strings[12355]="一切都准备就绪啦。"
D.Strings[12356]="5秒后开始蒸馏。"
D.Strings[12357]="再加一颗橙子！快点！"
D.Strings[12358]="更多的香蕉！"
D.Strings[12359]="往蒸馏器里扔颗木瓜！"
D.Strings[12360]="蒸馏器温度过低！点燃火盆！"
D.Strings[12361]="压力过高！打开施压阀！"
D.Strings[12362]="让我们来做个了断吧，玛尔加尼斯。"
D.Strings[12363]="成功啦！去拿桶来。"
D.Strings[12364]="不好！我要关掉蒸馏器……"
D.Strings[12365]="很好！时刻做好准备！"
D.Strings[12366]="走开。这里没什么好看的。"
D.Strings[12367]="<血玫瑰好奇地打量着你。>$B$B你这样的家伙也能吸引大家的目光，真是奇怪。$b$b我没有侮辱你的意思……"
D.Strings[12368]="斯特凡说你可以示范要如何使用这东西。"
D.Strings[12369]="你的旅程才刚开始，年轻的王子。集合你的部队，到诺森德再次挑战我。在那里，我们将了结彼此之间的恩怨，你将了解到你真正的命运。"
D.Strings[12370]="就算你跑到天涯海角，我也一定要抓到你！听到了吗？天涯海角！"
D.Strings[12371]="你们表现得很出色。玛尔加尼斯留下的一切都是你们的了，把它们收下作为奖励吧。现在我要马上开始计划远征诺森德了。"
D.Strings[12372]="达卡莱巨魔将我囚禁在祭坛，令我的肉身处于濒死状况。但是他们无法看见我的灵魂。$B$B我们必须协同作战，阻止他们夺取我的力量。"
D.Strings[12373]="醉鬼，我准备好啦，可以开始蒸馏了。"
D.Strings[12374]="很好！不要大意！"
D.Strings[12375]="干得好！集中精神。"
D.Strings[12376]="也行吧。不知道接下来应该加点什么……"
D.Strings[12377]="能量在水晶柱中涌动，发出低沉的嗡嗡声。"
D.Strings[12378]="请你快一点，$n。我承受着莫大的痛苦，时间已经不多了。"
D.Strings[12379]="肮脏的入侵者。死吧！"
D.Strings[12380]="我不会躺在这里等死的！凡人，想杀我的话，也得看看你有没有那个本事！"
D.Strings[12381]="我好像在喝……引擎清洁剂！"
D.Strings[12382]="好吧，我会尝尝的。"
D.Strings[12383]="这正是我梦寐以求的美酒啊！"
D.Strings[12384]="酿造得很成功啊！这酒的后劲还挺大的。"
D.Strings[12385]="我对葛瑞姆酿造的酒总是充满兴趣的。"
D.Strings[12386]="呃，我的妻子应该会喜欢这种果味酒……"
D.Strings[12387]="哇，仔细品味后才发现口感一流啊！葛瑞姆总是能为我带来惊喜！我喜欢！"
D.Strings[12388]="你想喝酒？我们有酒！"
D.Strings[12389]="嘿！喝食人魔的酒，变得更大更强！"
D.Strings[12390]="食人魔美酒！值得品尝！"
D.Strings[12391]="我们尽快离开这里。否则，就算不被亡灵杀死，也要被火烧死。"
D.Strings[12392]="正义必将得到伸张。"
D.Strings[12393]="嗷嗷……瞧那只食尸鬼。$b$b跳一下呀！跳一下！$b$b哈哈哈……真是一只可爱的食尸鬼。"
D.Strings[12394]="我们打算将这面墙炸掉，让维克的人可以修建新的港口和道路，但是这个蠢货居然嫌我用了太多的炸药！$B$B哼。我玩爆破的时候，他小子还裹着尿布呢。大不了我一脚把他踹进运河，然后自己把这该死的活儿干完！"
D.Strings[12395]="我们计划等拆了这面墙之后开始修建另一条通往暴风城港口的路……但是这个疯狂的矮人带来的炸药足以把这整个区域都给炸上天！$B$B我不知道阿历克斯顿大人是怎么想的，居然会雇佣她……这个满嘴脏话、刁钻刻薄、像头牛一样固执的矮人！"
D.Strings[12396]="天灾军团玷污了这片古朴的土地。以伟大的造物主之名，我会将他们污朽的躯壳踩得粉碎。"
D.Strings[12397]="我和你一样，希望能阻止天灾军团的入侵。我能帮上什么忙吗？"
D.Strings[12398]="泰坦并非在一夜之间就创造出了所有生命。整个过程相当漫长，其中涉及大量的试验与叠代。$B$B因此，造物主看中了索拉查盆地，并将它改造成戒备森严的实验场所。$B$B为了确保安全，泰坦还制造出一台机械防御装置，它拥有无可匹敌的破坏力。除非你发誓对我效忠，否则我拒绝透露更多的机密。"
D.Strings[12399]="将造物主的秘密告知你这样的凡人，简直是对神灵的亵渎，但是我别无选择。$B$B泰坦的女儿弗蕾亚要我不惜一切代价保卫索拉查盆地的安全，这就是我留守此地的唯一目的。$B$B盆地内有一座大门，连接着另一块与这里的环境极其相似的土地。穿越那座大门，就能找到我们所说的秘密武器。"
D.Strings[12400]="相信我。我不是巫妖王的朋友。"
D.Strings[12401]="我不会令你失望的。"
D.Strings[12402]="你手里藏着什么？"
D.Strings[12403]="哨站属于无齿轮区域。如果有谁在制造机械装置时使用齿轮，就会遭到无情的嘲笑。"
D.Strings[12404]="看来你和我的想法一样啊。你想找些水果，对吧？"
D.Strings[12405]="洛肯？！这下我们碰到大麻烦了……虽然铁矮人已经被全部摆平了，但我敢打赌不知道什么鬼地方还有台机器，正不停向外吐着铁维库人！"
D.Strings[12406]="哎哟！你拉哪儿呢！"
D.Strings[12407]="很高兴我能帮上忙！"
D.Strings[12408]="还有香蕉吗？"
D.Strings[12409]="肮脏的天灾兵！死吧！"
D.Strings[12410]="我要将你献给阿比迪斯！"
D.Strings[12411]="接受圣光的洗涤吧！"
D.Strings[12412]="圣光保佑你，我的孩子。"
D.Strings[12413]="奥格瑞玛城外有两座飞艇塔。东侧的飞艇塔开通了前往提瑞斯法林地和荆棘谷的航线，西侧的飞艇塔则用于飞往诺森德和雷霆崖。"
D.Strings[12414]="东侧飞艇塔"
D.Strings[12415]="西侧飞艇塔"
D.Strings[12416]="谁在敲我的鼓？"
D.Strings[12417]="我要杀了你，$r！"
D.Strings[12418]="受死吧！"
D.Strings[12419]="请收下……我亮闪闪的财宝。结束了……"
D.Strings[12420]="我们得救啦。你真好，干皮人。"
D.Strings[12421]="苔行鳄鱼人似乎受了重伤。"
D.Strings[12422]="<检测脉搏……>"
D.Strings[12423]="勇敢的旅者经由这座港口在暴风城和鲁瑟兰村之间往返。"
D.Strings[12424]="苔行村受害者发出痛苦的呻吟。"
D.Strings[12425]="我可怜的飞行器。她在坠机事故中遭到严重损坏，我偏偏没有备用零件。看样子她是没法恢复原貌了！"
D.Strings[12426]="很快，$n！$B$B很快，你就能拥有真正的力量。很快，你的付出就能得到回报。"
D.Strings[12427]="来吧，凡人……$B$B忍耐！你将拥有真正的力量！"
D.Strings[12428]="啊，英雄。我听你的小伙伴说，你会来的。这样挺好的，省去了我亲自搜寻你的麻烦。"
D.Strings[12429]="我经历了一百年的战争与痛苦。你真的觉得，凭着血肉之躯与不死生物作对是明智的选择吗？我敢说，你很可能会失败。"
D.Strings[12430]="即便是碎裂成粉末，这些水晶依然在削弱我的力量……或许我不该低估泰坦的强大……"
D.Strings[12431]="这两个有勇无谋的蠢货彼此厌恶，却异口同声地称你为英雄。你或许还不愿意做出选择……那么，就让我多给你一点时间吧。"
D.Strings[12432]="阿尔萨斯也曾拥有……同样的力量……或许你应该沿着他的足迹追寻力量。"
D.Strings[12433]="伟大的哈克娅，请召唤一名子嗣，让它将我悄悄地带进奎丝鲁恩祭坛。"
D.Strings[12434]="谢谢你救了我，$n。这是我唯一能为你做的。握紧了，我们出发吧。"
D.Strings[12435]="事情似乎不太顺利。千万别跌下去。那里满是肮脏的东西！"
D.Strings[12436]="天哪……奎丝鲁恩死了！别动。我们偷偷绕过先知。"
D.Strings[12437]="呃，能带我在祖达克逛一圈吗？"
D.Strings[12438]="我们被发现了！别慌张。我们得离开这里！"
D.Strings[12439]="成功啦！保重，$n。再次对你表示感谢！"
D.Strings[12440]="启航！当心那些藤蔓植物！"
D.Strings[12441]="看来前面的区域已经被天灾军团清扫过了……"
D.Strings[12442]="看见了吗？她……真大啊！"
D.Strings[12443]="来吧！坐稳啦——前面有强气流！"
D.Strings[12444]="他们发动攻击了！当心那些火箭！"
D.Strings[12445]="啊啊啊！被击中了！你得帮帮忙！快，趁飞行器还没有爆炸！"
D.Strings[12446]="我想我们现在安全了。回去吧！"
D.Strings[12447]="欢迎光临。请问你想休息还是进餐？"
D.Strings[12448]="你喜欢我为那些所谓的崇拜者创造的新家吗？$B$B临死前，我强忍着莫大的痛楚诅咒了他们，并将他们一同拖进了我所创造的异界。$B$B我可以随心所欲，这固然不错；但我真正希望的，是向先知寻仇！"
D.Strings[12449]="%s召唤出天灾军团的大军！"
D.Strings[12450]="天灾军团，听我的号令！血色十字军的末日已经降临！攻占这片土地吧！"
D.Strings[12451]="朋友，我已经占领了这里的部分土地，但这仅仅是个开始！"
D.Strings[12452]="冰川正在逐渐扩展……到处都是亡灵！先等教授控制这里的局势吧！"
D.Strings[12453]="自以为是的北伐军挡住了我们前进的道路。他们注定会失败！"
D.Strings[12454]="很快，一切都将属于巫妖王！"
D.Strings[12455]="达卡莱巨魔在破坏他们的土地！他们很快就会失去这一切……很快。"
D.Strings[12456]="啊，这就是我们的命运之城……古达克！"
D.Strings[12457]="引擎爆炸了！快将维克的飞行器开回湖边着陆场！"
D.Strings[12458]="当然。$r，看仔细了。"
D.Strings[12459]="你是来找哈古斯买东西的吗？"
D.Strings[12460]="是啊。我想购买一些补给品。"
D.Strings[12461]="黑暗在等待……"
D.Strings[12462]="不…………！"
D.Strings[12463]="高阶祭司变成了焦炭。"
D.Strings[12464]="火！啊！！！！"
D.Strings[12465]="想要赢得巫妖王的宠爱？$B$B有充分价值的人才能获得黑暗的礼物……"
D.Strings[12466]="%s爆炸了！"
D.Strings[12467]="欢迎来到达拉然公会注册办事处。请问你需要什么帮助？"
D.Strings[12468]="炸药束将在5秒后引爆……"
D.Strings[12469]="炸药束将在4秒后引爆……"
D.Strings[12470]="炸药束将在3秒后引爆……"
D.Strings[12471]="炸药束将在2秒后引爆……"
D.Strings[12472]="炸药束将在1秒后引爆……"
D.Strings[12473]="死吧，蠢货！"
D.Strings[12474]="什么？怎么可能？"
D.Strings[12475]="我费了很多功夫，才迫使赫米特遵守协议。只希望大法师能赏识我的才能。"
D.Strings[12476]="很不错啊，死亡骑士。返回生者的世界，领取你应得的奖励吧。"
D.Strings[12477]="你应该紧跟着阿尔萨斯！"
D.Strings[12478]="你来做什么，可悲的家伙？送死吗？"
D.Strings[12479]="我很熟悉你身上的臭味。捕杀雪豹时，你一路潜行尾随在我身后！"
D.Strings[12480]="我邀请你去地底世界参加我的乔迁庆宴！"
D.Strings[12481]="我也想静静地陪伴你，但我们都知道，这是不可能的。就让我的小伙伴送你去地狱吧。"
D.Strings[12482]="远古海滩的战斗开始了！"
D.Strings[12483]="不！！！！！"
D.Strings[12484]="我们赶紧离开这里吧。"
D.Strings[12485]="听着，风险投资公司的蠢货！准则第一条：永远不要把囚犯关押在爆炸物附近。"
D.Strings[12486]="你的伪装骗不了我！我要杀了你，达库鲁一定会很满意的！"
D.Strings[12487]="否则，这就是后果。"
D.Strings[12488]="这里越来越热了。我们继续前进吧？"
D.Strings[12489]="我们将夺走他们的一切，死亡骑士。"
D.Strings[12490]="瞧，又是一车炸弹！让我们引爆它吧。"
D.Strings[12491]="萨拉纳尔，我必须返回暗影界。"
D.Strings[12492]="你不该随意摆弄这些东西。会弄伤人的。"
D.Strings[12493]="成功啦！谢谢你带我逃离那个地狱般的洞穴。告诉赫米特，让他等着我！"
D.Strings[12494]="这次就靠你自己了！"
D.Strings[12495]="很好。我会让先知永远待在我身边的。"
D.Strings[12496]="等等……住手！你不能夺走力量！！"
D.Strings[12497]="我们应该离开这里。我需要恢复！"
D.Strings[12498]="旅途愉快！等你抵达目的地后再召唤我吧。"
D.Strings[12499]="狂心氏族将夺得这块土地的控制权。大舌头怪最好滚得远远的，不然我们就将他们统统杀掉。"
D.Strings[12500]="狂心狼獾人很看起来凶猛，但其实我们是好人呀。时间长了，你就会发现，我们和聪明强壮的朋友相处得很好。$B$B我们只是不善于和笨蛋打交道而已。"
D.Strings[12501]="这就是雨水巨石。我们保护它，向它供奉闪闪发亮的宝贝；它就会庇护我们。$B$B你有亮闪闪的宝贝吗？"
D.Strings[12502]="我的个子不高，但是我会很厉害的魔法。我负责保护迷雾巨石……嗯，大多数时候我还是相当称职的。$B$B愚蠢的狗狗人。"
D.Strings[12503]="狗狗人的攻击已经持续好几天了。但是闪电巨石还很安全。$B$B跟往常一样，索乌霍鲁向我们伸出了援手……狗狗人不会有获胜的机会。"
D.Strings[12504]="卡塔克是来吃大舌头怪的。我们要为他准备一顿大餐。"
D.Strings[12505]="立即与我在市政厅会合，勇士。我们必须直接挑战玛尔加尼斯。"
D.Strings[12506]="伪装失效了！避开天灾兵！"
D.Strings[12507]="苏特菲兹，今天是你的幸运日。$n为你带回了更多的龙崽。"
D.Strings[12508]="我凭什么要替你照顾龙崽啊，多里安。我还要搞研究工作呢。"
D.Strings[12509]="好吧，你随时可以返回营地，帮助维斯雷摆弄那堆齿轮……"
D.Strings[12510]="不要，我讨厌齿轮！别让我碰那玩意儿！"
D.Strings[12511]="朋友，他们比我想象的更强壮。进攻！"
D.Strings[12512]="听我指挥，这个交给我来处理！"
D.Strings[12513]="这东西是从哪儿来的？趁工头还没发现，我最好赶紧把它拖到船上去！"
D.Strings[12514]="管它做什么呢。放在这里就是了，不会有人发现的！"
D.Strings[12515]="我们把闪闪发光的宝贝都供奉给了神殿……我们一点也不贪心啊……为什么会这样？"
D.Strings[12516]="把我的宝藏拿去吧……这样天气就会好转……亡灵也会离开。"
D.Strings[12517]="我们……什么都没做啊……我搞不明白。"
D.Strings[12518]="我做错事了？对不起……"
D.Strings[12519]="谢谢你！你是个好人！"
D.Strings[12520]="或许你也能让天气好转？"
D.Strings[12521]="你救了我们！谢谢你！"
D.Strings[12522]="干皮人，你好。"
D.Strings[12523]="一切顺利吗？"
D.Strings[12524]="嗯？"
D.Strings[12525]="有你这样优秀的猎手陪同，感觉真好。"
D.Strings[12526]="怎么啦？"
D.Strings[12527]="嗨！你还好吧？我们很好……嗯，很好很好。嗨！"
D.Strings[12528]="你被自己绊倒过吗？我们有过这样的经历诶。有点痛。不好玩，我们不要再绊倒了。"
D.Strings[12529]="你好！你看上去又强壮又和善。我喜欢你。我们做朋友好不好啊？"
D.Strings[12530]="要帮忙吗？要帮忙吗？我们是很乐于助人的。"
D.Strings[12531]="为什么我们还待在这里？"
D.Strings[12532]="你想要什么东西吗？"
D.Strings[12533]="我永远欠你一份情，$n。"
D.Strings[12534]="我们躲在你身后，这次你休想抓到我们！现在要好好教训你！哼！"
D.Strings[12535]="坏东西，你很快就要死了！你再也不能打扰瑟匹克睡觉啦！"
D.Strings[12536]="$n，到我这里来。我就在希姆托加。"
D.Strings[12537]="我要找格利基克，你有他的镣铐吗？"
D.Strings[12538]="我要找达伊克，你有他的粉笔吗？"
D.Strings[12539]="我要找瑟匹克，你有他的狩猎号角吗？"
D.Strings[12540]="我要找拉弗乌，你有他的虫袋吗？"
D.Strings[12541]="我要找亚鲁乌特，你有他的宝贝水晶吗？"
D.Strings[12542]="我要找莫乌德，你有他的皮球吗？"
D.Strings[12543]="天气不错啊，很适合飞行，不是吗？"
D.Strings[12544]="我一眼就能认出谁是王牌飞行员。谢谢你救了我！"
D.Strings[12545]="第一回合 - 结束！"
D.Strings[12546]="当你的身体和索乌霍鲁融合时，你感到一阵剧烈的能量波动。"
D.Strings[12547]="看看你所取得的成就，死亡骑士！你真是天灾军团的荣耀！"
D.Strings[12548]="当你的身体和卡塔克融合时，一股怒气从你心中腾起。"
D.Strings[12549]="爸爸！"
D.Strings[12550]="我不会屈服！我要战斗下去！"
D.Strings[12551]="求你住手！停止杀戮！"
D.Strings[12552]="我挑错了戒酒的日子！"
D.Strings[12553]="啊……我……我好象拉屎了……"
D.Strings[12554]="我... 我要继续战斗下去... 我... 我不会屈服。"
D.Strings[12555]="祖达克不欢迎天灾军团！"
D.Strings[12556]="朋友，祖达克属于达卡莱氏族。永远都是！"
D.Strings[12557]="天灾军团注定会失败。"
D.Strings[12558]="我们会杀光天灾兵！"
D.Strings[12559]="滚开，恶心的天灾兵！"
D.Strings[12560]="你不是天灾军团的成员。朋友，你来这儿做什么？"
D.Strings[12561]="天灾军团怎么会允许你四处闲逛？"
D.Strings[12562]="你迷路了吧……"
D.Strings[12563]="你有一个魔化蒂基面具？是你杀了我的家人！"
D.Strings[12564]="我要杀了你，$n！"
D.Strings[12565]="天空吞噬着被征服者的痛苦！"
D.Strings[12566]="血色十字军休想阻止我们！"
D.Strings[12567]="那些尸体只会令我们的军队日益壮大！"
D.Strings[12568]="停泊在破碎海岸的十字军舰队已成残骸！"
D.Strings[12569]="天灾军团的战士一定会击败敌人！"
D.Strings[12570]="巫妖王和你们都谈过！让他的教诲再次引起你们的共鸣吧！"
D.Strings[12571]="是伟大的巫妖王将你们重新唤醒。"
D.Strings[12572]="是伟大的天灾军团让你们重获生机。"
D.Strings[12573]="不必怜悯弱者！"
D.Strings[12574]="死亡骑士不需要怜悯，"
D.Strings[12575]="一切胆敢阻挡我们的敌人，"
D.Strings[12576]="毁灭！"
D.Strings[12577]="血色十字军的末日即将来临。我的骑士们，用你们手中的长剑，让他们瞧瞧究竟什么是真正的血色！"
D.Strings[12578]="接受痛苦的试炼吧，死亡骑士！"
D.Strings[12579]="一旦放置天灾锅，这块看似普通的南瓜田就会成为诅咒的源头！"
D.Strings[12580]="诺斯，希尔盖呢？"
D.Strings[12581]="你竟敢提起他！滚出我的视线！"
D.Strings[12582]="那个马屁精大概正在房间里练习芭蕾舞吧。"
D.Strings[12583]="别在我面前提他的名字！我只警告你这一次！"
D.Strings[12584]="我可以告诉你他不在哪儿……"
D.Strings[12585]="希尔盖可能在清理他那间肮脏的舞蹈室。"
D.Strings[12586]="我的任务完成了！"
D.Strings[12587]="新阿瓦隆被攻陷只是时间问题。"
D.Strings[12588]="芬努斯这里有你需要的东西，朋友。"
D.Strings[12589]="啊……你来了。主人说过，你很快就会到的。"
D.Strings[12590]="请跟我来，$n。有很多东西要给你看……"
D.Strings[12591]="“血色的黎明”是什么？"
D.Strings[12592]="关于“血色的黎明”，你都知道些什么？快说，不然就等着吃鞭子吧！"
D.Strings[12593]="我对你已经够客气的了！“血色的黎明”到底是什么？"
D.Strings[12594]="“血色的黎明”究竟是什么！说！"
D.Strings[12595]="我有的是精力对付你！说吧，“血色的黎明”是什么！"
D.Strings[12596]="我迟早会掏出埋在你心里的所有秘密！只要你肯开口，我就饶你一命！"
D.Strings[12597]="你的性命就这么不值钱吗？只要你告诉我关于“血色的黎明”的资料，我就立即结束你的痛苦。"
D.Strings[12598]="你杀了我吧，怪物。我什么都不会说！"
D.Strings[12599]="啊……痛……差点就赶上我小时候在学校里受过的鞭刑了。"
D.Strings[12600]="我说，你挥舞鞭子的力道像个小姑娘。你就这点能耐？"
D.Strings[12601]="我说！住手！求你了！"
D.Strings[12602]="我们……我们只知道“血色的黎明”象征着觉醒。你……你瞧，圣光给了阿比迪斯将军新的启示。是圣光……"
D.Strings[12603]="是圣光在指引我们。天灾军团抵达之前，这次行动就已经开始了……我们……只是简单地奉命行事。我们必须服从军令。"
D.Strings[12604]="其他的我就不清楚了……阿比迪斯将军决定谁走谁留。我只知道这些……你要相信我啊！"
D.Strings[12605]="啊！住手！还有一件事我忘记说了……很快就会有信差……从壁炉谷赶来。嗯……"
D.Strings[12606]="你很快就要被押上绞刑架了，魔鬼！"
D.Strings[12607]="我曾是大检察官伊森利恩的部下！你的鞭刑就像午后茶点一般！"
D.Strings[12608]="啊！你烧坏了我的战袍！那是我唯一保存完好的战袍！"
D.Strings[12609]="撒谎！接下来你要承受的痛苦足够你谈论好几年！"
D.Strings[12610]="十字军……$B$B<瑞文戴尔男爵摇了摇头。>$B$B他们是一群特殊的人类。在我看来，十字军似乎不具备高等智慧，他们无法理智地评估局势并计算得失。只要提到圣光，就能让他们群情激昂——接着，这帮家伙会完全无视自己的利益，盲目地投身战斗。"
D.Strings[12611]="你应该感到荣幸。主人要我们向你展示沃尔塔鲁斯的工事，这还是头一遭。"
D.Strings[12612]="主人从达克萨隆来到这里时，就预言了你到此造访的时间。"
D.Strings[12613]="我向你展示的东西绝对不能在沃尔塔鲁斯以外提起。我们的秘密很快就能揭晓了！"
D.Strings[12614]="这些是我们储藏的荒芜水晶。没有水晶，我们的计划就不可能成功。"
D.Strings[12615]="我知道，你会为我们做好了充足的储备而感到庆幸。"
D.Strings[12616]="这些是你在战场上俘虏的巨魔。你的身手确实不错……"
D.Strings[12617]="我自由了，达卡莱巨魔。为你们的罪行付出代价吧！"
D.Strings[12618]="阿卡里，我的主人需要你的鲜血，我也要夺取你的一部分力量！"
D.Strings[12619]="$n！我一直在等你。你怎么去了那么久？$b$b我们可以对荒芜之血进行转换了。$b$b让我们共同见证军队的诞生吧！"
D.Strings[12620]="我准备好了，达库鲁。"
D.Strings[12621]="好了。滚回你的主人身边吧。告诉哈克娅，我来了！"
D.Strings[12622]="我好像弄丢了你的伐木机控制器……还有吗？"
D.Strings[12623]="我要找回符文剑和盔甲……很快就好。"
D.Strings[12624]="我很虚弱，但是我应该能撑起一个反魔法屏障。你最好别走出屏障，否则就会被他们的法术杀死。"
D.Strings[12625]="我伤得很重，但是我会尽量帮忙的。你最好待在我撑起的反魔法屏障中，否则侍僧的魔法会将你撕成碎片。"
D.Strings[12626]="我必须集中精神维持这个屏障。去消灭他们！"
D.Strings[12627]="敌人再次发动了攻击。注意安全！别离开反魔法区域！没有屏障的保护，他们轻易就能将你撕成碎片！"
D.Strings[12628]="屏障支撑不了多久了……那个胆小鬼在哪儿呢？"
D.Strings[12629]="我能帮你什么忙吗，$r？"
D.Strings[12630]="大检察官来了！准备迎战，死亡骑士！别离开反魔法屏障的安全区域！击败他，拿到他的徽记！"
D.Strings[12631]="十字军会从这个世界上抹去你们的存在！"
D.Strings[12632]="看样子我得亲自对付你了。尝尝大检查官的厉害吧，天灾军团！"
D.Strings[12633]="接受圣光的净化吧！"
D.Strings[12634]="你想要寻求救赎？我就是你的救星！"
D.Strings[12635]="%s的尸体跌落在地。"
D.Strings[12636]="别离开反魔法屏障！将他们引过来！"
D.Strings[12637]="库弗，我们再次听到你的召唤。请允许我们给你和$n几句忠告。你们即将面临巨大的威胁，如果不赶紧行动的话，你们和哈克娅都会丧命。"
D.Strings[12638]="唯有完美的守卫者徽记能传达挑衅的意图。拥有这颗徽记的守卫者就在戒备森严的希姆鲁克。"
D.Strings[12639]="只有杀死奎丝鲁恩祭坛典狱官，获得充满活力的典狱官精华，才能引出阿卡里先知。你必须将这两件稀罕物交给哈克娅。"
D.Strings[12640]="未来仍然笼罩着阴霾。$n，这是你的命运。虽然你和你的伙伴或许不是先知的对手，但是，你必须尝试。"
D.Strings[12641]="不，也不是哈克娅！"
D.Strings[12642]="新阿瓦隆大检查官的死亡必然会引起敌人的注意。你最好立刻离开！快跑吧，趁敌人还没有涌上来。我会照顾好自己的。"
D.Strings[12643]="我来吸引火力，掩护你逃走。"
D.Strings[12644]="十字军，你们的大检查官已经死了！没有人能逃出天灾军团的控制！"
D.Strings[12645]="<库尔迪拉呻吟着。>"
D.Strings[12646]="旅店的设施并不符合我的要求，不过……这里至少还算暖和。"
D.Strings[12647]="血色十字军将迎来一名新主子——我是说，在他们死后……"
D.Strings[12648]="剑刃残留着鲜血的余温，雷耶克很喜欢。"
D.Strings[12649]="雷耶克感觉自己变强壮了！雷耶克能徒手击败大舌头怪！"
D.Strings[12650]="雷耶克和$n要让狂心氏族的敌人吓得簌簌发抖！"
D.Strings[12651]="这是什么？我杀死阿卡里时就认出你了。你是$n，他们都很惧怕你。"
D.Strings[12652]="你根本不足为患，$g小子:小丫头;。相反，我正想杀了你。谁也别想阻止我进入希姆托加！"
D.Strings[12653]="直到现在你才明白——我拥有神灵的力量，这真是遗憾。你不过是个凡人，怎可能击败我！"
D.Strings[12654]="你这是挑衅吗？"
D.Strings[12655]="我要挑战你，死亡骑士！"
D.Strings[12656]="多管闲事。你只是闯入巨魔帝国的外来者。去死吧！"
D.Strings[12657]="先知开始施放歼灭仪式。"
D.Strings[12658]="你这是在挑战死神！"
D.Strings[12659]="看我怎么把你揍趴下，菜鸟！"
D.Strings[12660]="别逗我笑了。"
D.Strings[12661]="啧啧，哭鼻子啦……"
D.Strings[12662]="不准喝药！"
D.Strings[12663]="你快完蛋了！"
D.Strings[12664]="你赢不了的，$n。"
D.Strings[12665]="看看谁才是巫妖王麾下真正的勇士！"
D.Strings[12666]="先知！"
D.Strings[12667]="什么？哈克娅？！"
D.Strings[12668]="把你的脏手拿开！"
D.Strings[12669]="很好，小东西。看来我也不必对你手下留情了。等我解决掉这个蠢货，再来对付你！"
D.Strings[12670]="是吗？我命令你立即终止仪式，放了他们！"
D.Strings[12671]="不！我是不会被打败的！"
D.Strings[12672]="谢谢你。你再次拯救了我们。我会在希姆托加等你。"
D.Strings[12673]="朋友，好好瞧瞧这里。你要帮我征服它！"
D.Strings[12674]="$n，我认得你的犄角……他们……他们对你做了些什么，$n？"
D.Strings[12675]="你不记得我了？该死的天灾军团……他们挫败了你的正义之气、泯灭了你最后一丝良知……还有你身为牛头人的天性！"
D.Strings[12676]="朋友！瞧瞧，这片土地承载了多少荣耀！"
D.Strings[12677]="巫妖王愿意与忠于他的仆从分享力量。"
D.Strings[12678]="来见我吧，$n。我必须和你谈谈。"
D.Strings[12679]="$n，仔细回忆。想想莫高雷起伏的草原，那是你的家乡。想想生命的壮丽画卷。你，曾是牛头人氏族的勇士！眼前的你，不是真正的你。"
D.Strings[12680]="蓝玉之门遭到攻击！"
D.Strings[12681]="翡翠之门遭到攻击！"
D.Strings[12682]="红日之门遭到攻击！"
D.Strings[12683]="紫晶之门遭到攻击！"
D.Strings[12684]="金月之门遭到攻击！"
D.Strings[12685]="我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……想想莫高雷。这个世界值得你去拯救。"
D.Strings[12686]="%s因为伤势过重而死掉了。"
D.Strings[12687]="金月之门被摧毁了！"
D.Strings[12688]="紫晶之门被摧毁了！"
D.Strings[12689]="红日之门被摧毁了！"
D.Strings[12690]="翡翠之门被摧毁了！"
D.Strings[12691]="蓝玉之门被摧毁了！"
D.Strings[12692]="你不记得我了？该死的天灾军团……他们挫败了你的正义之气、泯灭了你最后一丝良知……还有你身为人类的天性！"
D.Strings[12693]="$n，仔细回忆。想想艾尔文森林静谧的山谷，那是你的家乡。想想生命的壮丽画卷。你，曾是联盟的勇士！眼前的你，不是真正的你。"
D.Strings[12694]="我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……想想艾尔文森林。这个世界值得你去拯救。"
D.Strings[12695]="我是来……"
D.Strings[12696]="你不记得我了？那时候，你还是襁褓中的婴儿。你的母亲每次去月神殿当值时，就会把你托付给我。我抱着你，喂你蜂蜜和羊奶。我耐心地哄你睡觉，直到你的母亲回家。你就像我的小天使。该死的天灾军团……他们对你做了什么，$n？"
D.Strings[12697]="想想生命的壮丽画卷。你，曾是卡多雷的勇士！眼前的你，不是真正的你。"
D.Strings[12698]="听我说，$n。你必须摆脱巫妖王的控制。他一心盘算着毁掉这个世界，毁掉我们的家园。你不该沦为任由他摆布的棋子！过去，你曾是一名伟大的英雄；现在，我相信你能为新的英雄。反抗吧！摆脱巫妖王的控制！"
D.Strings[12699]="我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……想想泰达希尔，我们挚爱的家园。这个世界值得你去拯救。"
D.Strings[12700]="你是来执行任务的吧？"
D.Strings[12701]="啊，来自铁炉堡的孩子，你想做什么……"
D.Strings[12702]="$n，我认得你的脸庞……他们……他们对你做了些什么，$g小伙子:小姑娘;？"
D.Strings[12703]="你不记得我了？该死的天灾军团……他们挫败了你的正义之气、泯灭了你最后一丝良知……还有你身为铁炉堡的孩子的天性！"
D.Strings[12704]="$n，仔细回忆。想想丹莫罗被白雪覆盖的山脊，那是你的家乡。想想生命的壮丽画卷。你，曾是矮人氏族的勇士！眼前的你，不是真正的你。"
D.Strings[12705]="我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……为了卡兹莫丹！！！"
D.Strings[12706]="能不能让我……"
D.Strings[12707]="你不记得我了？该死的天灾军团……他们挫败了你的正义之气、泯灭了你最后一丝良知……还有你身为侏儒的天性！"
D.Strings[12708]="$n，仔细回忆。想想穴居人入侵前的诺莫瑞根！想想手握弧光扳手的感觉。你，曾是侏儒氏族的勇士！眼前的你，不是真正的你。"
D.Strings[12709]="我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……想想诺莫瑞根。这个世界值得你去拯救。"
D.Strings[12710]="$n，我认得你的面须……他们……他们对你做了些什么，$n？"
D.Strings[12711]="你不记得我了？该死的天灾军团……他们挫败了你的正义之气、泯灭了你最后一丝良知……还有你身为德莱尼人的天性！"
D.Strings[12712]="$n，仔细回忆。想想阿古斯高耸的山脊，那是你的家乡。想想生命的壮丽画卷。你，曾是德莱尼氏族的勇士！眼前的你，不是真正的你。"
D.Strings[12713]="我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……想想阿古斯。这个世界值得你去拯救。"
D.Strings[12714]="看着我的眼睛……"
D.Strings[12715]="$n，仔细回忆。想想银月城宏伟的殿堂，那是你的家乡。想想生命的壮丽画卷。你，曾是辛多雷氏族的勇士！眼前的你，不是真正的你。"
D.Strings[12716]="我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……想想银月城。这个世界值得你去拯救。"
D.Strings[12717]="出了什么状况吗？你怎么去了那么久，$n？"
D.Strings[12718]="我要像兽人那样死去……"
D.Strings[12719]="$n，我认得你的脸庞……他们……他们对你做了些什么，$n？"
D.Strings[12720]="你不记得我了？该死的天灾军团……他们挫败了你的正义之气、泯灭了你最后一丝良知……还有你身为兽人的天性！"
D.Strings[12721]="$n，仔细回忆。想想杜隆塔尔！氏族的勇士不惜牺牲自己，解除了嗜血的诅咒。想想我们的诞生之地——试炼谷。那时，我们的世界一片祥和，不曾翻涌着恶魔的气息。我们共同书写了壮丽的生命画卷，$n。你，曾是部落的勇士！眼前的你，不是真正的你。"
D.Strings[12722]="我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……为了部落！这个世界值得你去拯救。"
D.Strings[12723]="很讽刺吧？身为被遗忘者，还能再死一次……"
D.Strings[12724]="$n，我认得你的骨头……他们……他们对你做了些什么，$n？"
D.Strings[12725]="你不记得我了吗？很久很久以前，我们曾经是人类。天灾军团攻陷洛丹伦后，我们相继沦为僵尸。但是不久之后，黑暗女王解放了我们。"
D.Strings[12726]="我们曾经起誓！要向巫妖王复仇！他摧毁了我们的王国，我们发誓要让他付出代价！我们组建起被遗忘者大军，和天灾军团作战，将他们赶回了瘟疫之地，解放了提瑞斯法林地！你和我都曾是被遗忘者氏族的勇士！"
D.Strings[12727]="我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……想想提瑞斯法林地。这个世界值得你去拯救。"
D.Strings[12728]="动手吧，$n！让我解脱吧！"
D.Strings[12729]="$n？伙计？"
D.Strings[12730]="$n，我认得你的獠牙……他们……他们对你做了些什么，伙计？"
D.Strings[12731]="你不记得我了？该死的天灾军团！他们榨干了你的魔精，泯灭了你最后一丝良知……还有你身为巨魔的天性！"
D.Strings[12732]="$n，仔细回忆。我们是暗矛巨魔啊，朋友！我们情同手足！还记得我们击败扎拉赞恩的英雄事迹吗？我们打败了他，解放了回音群岛！朋友！好好想想！你曾经是暗矛巨魔氏族的勇士！"
D.Strings[12733]="我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……想想森金村，朋友！这个世界值得你去拯救。"
D.Strings[12734]="呃，这棵树真奇怪。我必须研究一下。"
D.Strings[12735]="总有一天，雷耶克会成为强大的战士。"
D.Strings[12736]="这是什么！？这根本不是树！守卫！来人啊！"
D.Strings[12737]="要去奥伯丁或者无畏要塞吗？只要穿过运河，就能抵达位于教堂广场和花园之间的暴风城港口。"
D.Strings[12738]="暴风城港口是前往奥伯丁和无畏要塞的捷径。它就在教堂广场和花园之间。"
D.Strings[12739]="你好，$c。我相信你带来了一些关于全球邀请赛的好消息？如果是的话，那么你肯定已经获得了一段神秘兑换码。只要你把那段神秘兑换码告诉我，我就可以送给你一件礼物，泰瑞尔的剑柄。$B$B准备好了之后就告诉我吧。"
D.Strings[12740]="我要告诉你那段神秘兑换码，获得泰瑞尔的剑柄。"
D.Strings[12741]="就凭这点能耐，也想打败我？"
D.Strings[12742]="尽情告饶吧。我是不会心软的！"
D.Strings[12743]="永恒的诅咒就是你的下场！"
D.Strings[12744]="你杀了我，现在轮到我杀你了……反反复复地杀！"
D.Strings[12745]="休想逃走。尝尝我的怒火吧！"
D.Strings[12746]="你的命运由我主宰！"
D.Strings[12747]="在怒火中煎熬吧！"
D.Strings[12748]="我们觉得最好将他们安置在这里，让他们乖乖地接受注定的命运。"
D.Strings[12749]="这就是他们的命运……"
D.Strings[12750]="诅咒会逐渐侵入他们的肉体，使他们的体质发生变化。"
D.Strings[12751]="这种特殊的转变将赋予他们难以想象的力量。"
D.Strings[12752]="很快，主人会赐予他们黑暗的礼物，让他们能够永远为巫妖王效劳！"
D.Strings[12753]="$n，你想在这里呆多久都行。好好享受你的努力所换来的成果吧！"
D.Strings[12754]="你帮助主人实现了他伟大的计划。愿你的力量越来越强……"
D.Strings[12755]="看！我们正在创建一支最强大的天灾部队！"
D.Strings[12756]="这只是第一批！最终，我们将横扫整个祖达克……"
D.Strings[12757]="快，$n。快使用传送门！"
D.Strings[12758]="我们是被巫妖王选中的死亡骑士，$n。身为天灾军团的一员，我们要坚定执行巫妖王的意志。"
D.Strings[12759]="我错过了通往阿彻鲁斯的传送门，奥尔巴兹。能再次开启传送门吗？"
D.Strings[12760]="这些怪物杀死了我的父亲，绑架了我的妹妹。我要让他们付出代价！"
D.Strings[12761]="谁要看雷耶克的新头盔？"
D.Strings[12762]="我要看！"
D.Strings[12763]="我也想看！"
D.Strings[12764]="好吧，雷耶克让你们瞧瞧！"
D.Strings[12765]="怎么样？"
D.Strings[12766]="啊，钢盔把雷耶克吃掉了！快跑啊！"
D.Strings[12767]="哦耶！连狗崽子们都害怕这头盔，肯定能把那些胆小的大舌头怪吓得屁滚尿流啊！"
D.Strings[12768]="大门已经被攻破了！快，派兵去挡住那些入侵者！"
D.Strings[12769]="欢迎来到我的厨房！我们在这里为达拉然的居民烹制最美味的食物。"
D.Strings[12770]="我是来学习烹饪的。"
D.Strings[12771]="希望你好好地教训一下大舌头怪。他们该滚蛋了！"
D.Strings[12772]="灵鳍湾的战斗仍在继续。$B$B你能抽空去那里帮帮忙吗？"
D.Strings[12773]="你好，$c！暴风城港口的景色别具风格。从空中俯瞰的效果更佳。你要鸟瞰一下整座港口吗？"
D.Strings[12774]="我要绕暴风城港口游览一圈。"
D.Strings[12775]="凭你的智慧，恐怕无法掌握传送魔法的奥秘。$B$B但是你可以使用我身后的水晶，它能将你传送到达拉然下方，位于晶歌森林的废墟。"
D.Strings[12776]="身为一名法师，你拥有开启传送门，将自己传送回这里的能力。如果你愿意的话，我可以将传送法术传送给你。$B$B你也可以使用我身后的水晶，传送到达拉然下方的晶歌森林。"
D.Strings[12777]="你有空吗？索乌尼可以教你好听的曲子！"
D.Strings[12778]="我要传送到达拉然。"
D.Strings[12779]="朋友，欢迎来到我的理发店！你是想理发？还是染发啊？要不试试别的项目？$B$B我们提供各种修面、打洞、绘制暗夜精灵纹身等服务，甚至能为德莱尼人修整犄角和卷须！$B$B请坐吧，我们这就为你服务！只要花上几个子儿，你就能变得魅力四射……"
D.Strings[12780]="朋友，欢迎来到我的理发店！你是想理发？还是染发啊？要不试试别的项目？$B$B我们提供各种修面、打洞、獠牙和犄角整形等服务，甚至能为亡灵整容！$B$B请坐吧，我们这就为你服务！只要花上几个子儿，你就能变得魅力四射……"
D.Strings[12781]="来喝一杯！"
D.Strings[12782]="还有$3486W个离心构造体。我们必须摧毁它们，才能破除瓦尔洛斯·云击的护盾。你可以在位于魔环中层的加速之环找到那些构造体。"
D.Strings[12783]="只剩1个离心构造体了。我们必须摧毁它们，才能破除瓦尔洛斯·云击的护盾。你可以在位于魔环中层的加速之环找到那些构造体。"
D.Strings[12784]="破除护盾，削弱瓦尔洛斯的防御力量！击败他，碧蓝魔环卫士就会消失，这样我们就能继续往上层前进了。前往位于魔环中层的加速之环，在浮动平台上找到瓦尔洛斯。"
D.Strings[12785]="下一个目标是法师领主伊洛姆。前往靠近魔环顶层的转化之环，在浮动平台上找到伊洛姆。他正在引导蓝色的魔枢能量旋。当心，这位强大的咒术师能召唤仆从帮他作战。"
D.Strings[12786]="只要除掉魔网守护者埃雷苟斯，我们就能控制魔环。他就在位于魔环顶层的校准之环上方盘旋。埃雷苟斯拥有难以想象的力量。开战之后你待在我背上吧，让我来对付他。"
D.Strings[12787]="我要去圣光据点。"
D.Strings[12788]="你或许也可以为我效劳。"
D.Strings[12789]="行了，别再估计什么形势不形势的了，蠢货！赶紧给我加入战斗！"
D.Strings[12790]="斯卡瓦尔德，你这无能的废物！滚回来，让我把你变得更有用一点！"
D.Strings[12791]="再……见……"
D.Strings[12792]="真是……无上的……荣耀。"
D.Strings[12793]="达尔隆！你有没有勇气和我一起上啊！"
D.Strings[12794]="呸！通灵师岂有死了就放弃的道理？你这没用的东西！"
D.Strings[12795]="没……完……呢。"
D.Strings[12796]="一个战士的……死。"
D.Strings[12797]="瓦尔洛斯·云击和魔环卫士守护着第二环。你召唤的幼龙足以对付魔环卫士，但是瓦尔洛斯利用魔环自身的能量，撑起了一面难以穿透的护盾。10个离心构造体不断地为护盾提供能量，它们就分布在我们头顶的环面和平台上。只有摧毁它们，才有可能伤害到瓦尔洛斯。"
D.Strings[12798]="接下来我们该怎么办？"
D.Strings[12799]="位于风暴峭壁的岩石大厅已开放测试，该地下城适合77至79级的玩家。请组满队伍后再传送至岩石大厅。该地下城的集合石尚未开放。\n\n穿过地下城内的常规出口，即可离开岩石大厅并返回这里。如果角色死亡并选择释放灵魂，请从该NPC处传送回去。"
D.Strings[12800]="我……我不知道。"
D.Strings[12801]="前往幽暗城的飞艇已经抵达！要去提瑞斯法林地的旅客请登机！"
D.Strings[12802]="我说，莫度鲁，你从哪儿弄到这件……呃……“漂亮”的长袍的啊？"
D.Strings[12803]="噢。噢……原来如此。不错呀！"
D.Strings[12804]="%s强忍着笑。"
D.Strings[12805]="前往战歌要塞的飞艇已经抵达！要去北风苔原的旅客请登机！"
D.Strings[12806]="%s完全没有意识到她在嘲笑自己，竟然露出了笑容，用带有重口音的通用语回答了她的问题。"
D.Strings[12807]="哈！这是我的祖母送给我的礼物呀。这件长袍是她用德拉诺最上等的丝绸亲手缝制的！穿上它令我倍感自豪呢！"
D.Strings[12808]="%s窃笑着，用鼻子摩挲着哨兵琪珊·清泉的脚踝。"
D.Strings[12809]="%s冲营地那头的哨兵蓝塔娜·琥珀咧嘴一笑，意味深长地挑动着她长长的眉毛。"
D.Strings[12810]="压……扁……你……"
D.Strings[12811]="%s嗤了一声，狠狠地瞪了瞪哨兵琪珊·清泉，然后将头扭向一旁。"
D.Strings[12812]="哈……哈……哈……"
D.Strings[12813]="打……碎……你……"
D.Strings[12814]="啊……"
D.Strings[12815]="警告：生命体形态模式无法辨识。文档处理程序中断。继续干涉程序将导致安全对策启动。"
D.Strings[12816]="你回来做什么？立即返回斯坦索姆！$B$B要我把你传送过去吗？"
D.Strings[12817]="你不该来这里……现在你就要死了！"
D.Strings[12818]="为什么会这样呢？"
D.Strings[12819]="是你逼我这么做的！"
D.Strings[12820]="我心中的负担更加沉重了……"
D.Strings[12821]="都是你的错！"
D.Strings[12822]="失去了这么多时间……你们永远也无法挽回！"
D.Strings[12823]="我诅咒你们烂在这里！我……不想要这个结局……"
D.Strings[12824]="安全系统发现不明入侵。历史文档的分析工作优先级转为低。对策程序立即启动。"
D.Strings[12825]="已超出威胁指数标准。天界文档中断。提高安全级别。"
D.Strings[12826]="威胁指数过高。虚空分析程序关闭。启动清理协议。"
D.Strings[12827]="找出那些携带了病毒的谷物箱，对它们使用奥术干扰器！$B$B这样阿尔萨斯就有充分的证据对斯坦索姆动手了。"
D.Strings[12828]="警告：安全系统自动修复装置已被关闭。立刻消除全部存储器内容并……"
D.Strings[12829]="系统已上线。生命形态模式已确认。您好，铜须先生。是否需要问询？"
D.Strings[12830]="你还待在这里做什么？$B$B阿尔萨斯就在斯坦索姆的入口处，你应该跟紧他！快去！"
D.Strings[12831]="看看你们那软弱的躯壳和短暂的生命。你们永远也无法逃避血肉的诅咒！"
D.Strings[12832]="血肉永远无法胜过钢铁！"
D.Strings[12833]="钢铁的大军将令整个世界窒息！"
D.Strings[12834]="洛肯是不会放弃的……他一定会夺回熔炉！你们……什么也无法改变！"
D.Strings[12835]="%s寻求帮助！"
D.Strings[12836]="我将……融入这黑夜。"
D.Strings[12837]="你们知道好奇心过剩的下场吧……"
D.Strings[12838]="我要让你们尝尝无所适从的滋味！"
D.Strings[12839]="这里有我千万个分身。"
D.Strings[12840]="现在，最后一步！"
D.Strings[12841]="你已经死了。"
D.Strings[12842]="这该死的……运气。"
D.Strings[12843]="混沌已降临。"
D.Strings[12844]="谜底将揭示。"
D.Strings[12845]="不灭而不朽。"
D.Strings[12846]="当然。"
D.Strings[12847]="不……！"
D.Strings[12848]="萨隆亚已经预见了一切！凡人的徒劳努力根本无法毁灭永恒的王朝！"
D.Strings[12849]="回去！"
D.Strings[12850]="正如萨隆亚所料！"
D.Strings[12851]="正如预言所说！"
D.Strings[12852]="你的血肉现在要为萨隆亚效劳了！"
D.Strings[12853]="你的躯壳对萨隆亚还有些用处！"
D.Strings[12854]="不，这感觉……太短暂了！"
D.Strings[12855]="啊啊啊！我还要这种感觉！"
D.Strings[12856]="不……不可能！萨隆亚是不朽的！萨隆亚是……"
D.Strings[12857]="留下。好好享受你们的最后时光吧。"
D.Strings[12858]="了断吧！来个了断吧！杀了我，否则我以女王陛下之名发誓，你们绝对看不见明天的太阳！"
D.Strings[12859]="现在我们终于接近真理了！"
D.Strings[12860]="女王陛下……生命的缚誓者……请保护……我。"
D.Strings[12861]="这是怎么回事？Mok-thorin ka！杀了他们！"
D.Strings[12862]="我们的工作还没完成呢！"
D.Strings[12863]="我要如何训练宠物？"
D.Strings[12864]="与猎人一样，宠物也可选择天赋专精。狂野宠物，例如猫科动物。它们拥有可观的输出伤害，承受伤害的能力却偏弱。坚韧宠物，例如海龟。它们拥有多种防御技能，能吸引敌人的火力，便于你进行远程输出。狡诈宠物，例如蜘蛛。它们同时拥有攻击和防御技能，在战场和竞技场的作用显得尤为突出。$B$B每种宠物都自带一种默认天赋，但你可以根据自己的喜好加以更改。"
D.Strings[12865]="什么？我这是在哪？别傻站着了，杀了他们！"
D.Strings[12866]="这才像话！"
D.Strings[12867]="你们……不过如……此……"
D.Strings[12868]="你确定要这样做吗？$B$B一旦我抹去你已经学会的天赋，就不能反悔啦。"
D.Strings[12869]="好吧。遗忘完毕。"
D.Strings[12870]="我要征服你们的灵魂！"
D.Strings[12871]="妄图挑战巫妖王的力量？你太愚蠢了！"
D.Strings[12872]="陛下，我已执行了您的意志！"
D.Strings[12873]="让我再为主人奉上一个灵魂吧！"
D.Strings[12874]="你的死亡临近了……"
D.Strings[12875]="你的灵魂可以去主人那里了！"
D.Strings[12876]="你的末日已经不可避免。"
D.Strings[12877]="还有什么遗言吗？"
D.Strings[12878]="不！我历尽千辛万苦，不是为了……"
D.Strings[12879]="尊敬的陛下！我已经完成您的全部要求，希望您能不吝赐下伟大的祝福！"
D.Strings[12880]="我不会忘记你为萨萨里安所做的一切。不胜感激。"
D.Strings[12881]="这感觉……真是超乎想象。我将永远听命于您，陛下。"
D.Strings[12882]="能以您的名义杀死这些蝼蚁令我十分荣幸，来吧，天灾军团的敌人们！我让你们看看巫妖王的真正力量！"
D.Strings[12883]="这次献祭只是对你恭顺与服从的考验。现在你已证明自己确实可以胜任我的嘱托。平身吧，席瓦拉·索格蕾！"
D.Strings[12884]="你的第一个试炼正在等待着你。消灭那些不速之客。"
D.Strings[12885]="就在这里，我放弃了一切，只为换取父亲的自由。如今，我要亲手摧毁它……"
D.Strings[12886]="大领主，我准备好了。向圣光之愿礼拜堂发起进攻吧！"
D.Strings[12887]="天灾军团的士兵们，做好准备！你们马上就可以向银色黎明倾泻怒火了！"
D.Strings[12888]="大地即将崩裂，天空也要为之哭泣！很快，艾泽拉斯那悲戚的血泪就会降下！"
D.Strings[12889]="阿彻鲁斯的死亡骑士们，死亡的远征现在开始！"
D.Strings[12890]="天灾军团的士兵们，阿彻鲁斯的死亡骑士们，黑暗的仆从们：听从大领主的召唤！"
D.Strings[12891]="十字军必胜！"
D.Strings[12892]="这里不欢迎你，怪物！"
D.Strings[12893]="接受净化吧！"
D.Strings[12894]="天空变得血红！巫妖王在注视着我们。前进！苏醒的你们将带来毁灭，身后只留下灰烬和痛苦。"
D.Strings[12895]="兄弟姐妹们，坚持住！圣光必胜！"
D.Strings[12896]="天灾军团来了！"
D.Strings[12897]="臣服于大领主的力量吧！"
D.Strings[12898]="天灾军团将要毁灭这里！"
D.Strings[12899]="没有痛苦，生命就毫无意义！"
D.Strings[12900]="你们的部队还能坚持多久呢？"
D.Strings[12901]="银色黎明完蛋了！"
D.Strings[12902]="这是什么？！我的……我不能攻击了……"
D.Strings[12903]="服从我，灰烬使者！"
D.Strings[12904]="遵照我的意愿！我是你的主人！"
D.Strings[12905]="我……我竟不能……这把剑背叛了我……"
D.Strings[12906]="到底是怎么了？"
D.Strings[12907]="力量……消失了……"
D.Strings[12908]="灰烬使者正在抗拒我……"
D.Strings[12909]="仆从们，快来帮我！"
D.Strings[12910]="你赢不了的，达里安！"
D.Strings[12911]="你难道还不明白吗，孩子？你已经沦为了你父亲毕生都在对抗的存在！你已经和阿尔萨斯那个懦夫一样，甘心堕入黑暗……堕入仇恨……以害人为生！"
D.Strings[12912]="你的主子知道礼拜堂下面埋藏着什么。所以他才不敢露面！你和你的死亡骑士就是他派来送死的，达里安。"
D.Strings[12913]="你现在感受到的，是上千个迷失灵魂的痛苦！他们都是牺牲在你和你的主人剑下的英灵！圣光会把你撕碎的，达里安！"
D.Strings[12914]="带到礼拜堂前！"
D.Strings[12915]="%s逃跑了。"
D.Strings[12916]="%s被提里奥·弗丁击败，跪倒在地。"
D.Strings[12917]="死亡骑士们，撤退。我们战败了……这里的……圣光之力…………我们输定了……"
D.Strings[12918]="省点力气吧，老家伙。这将是你的最后一口气息了。"
D.Strings[12919]="我的儿子！最让我自豪的孩子！"
D.Strings[12920]="父亲！"
D.Strings[12921]="啊……这……这是……"
D.Strings[12922]="父亲，您回来了！"
D.Strings[12923]="您去了好久啊，父亲。我还以为……"
D.Strings[12924]="%s拥抱了他的父亲。"
D.Strings[12925]="没有什么能够阻止我回家，达里安。我绝不会离开自己的家乡和亲人。"
D.Strings[12926]="父亲，我也想加入部队，和您一起抵抗亡灵。我也要战斗，不能再袖手旁观了！"
D.Strings[12927]="达里安·莫格莱尼，你还没有到可以握剑的年龄呢，更不用说去跟肆虐洛丹伦的亡灵作战了！我不能失去你，想都不敢想……"
D.Strings[12928]="父亲，就算死，我也要在和亡灵军团的战斗中光荣地战死！就算死，我也要和您死在一起！"
D.Strings[12929]="我的儿子啊，你总有一天会举起灰烬使者，凭借它的力量在这片土地上匡扶正义。我坚信，当那一天终于到来的时候，你会为我们的人民带来荣光，洛丹伦将因你而变得更加美好。但，我的孩子，不是今天。"
D.Strings[12930]="不要忘记……"
D.Strings[12931]="真感人……"
D.Strings[12932]="他现在归我了……"
D.Strings[12933]="你……背叛了我。你背叛了我们所有人，怪物！感受莫格莱尼的力量吧。"
D.Strings[12934]="真可怜……"
D.Strings[12935]="阿尔萨斯，你这该死的怪物！"
D.Strings[12936]="你说对了，弗丁。我就是派他们去送死的。他们的生命毫无意义，但你的不同……"
D.Strings[12937]="把伟大的提里奥·弗丁揪出来还真是容易啊。你已经暴露了，圣骑士。谁也救不了你了……"
D.Strings[12938]="提里奥！"
D.Strings[12939]="%s倒下了。"
D.Strings[12940]="阿尔萨斯！！！"
D.Strings[12941]="%s击碎了脆弱的魔像！"
D.Strings[12942]="但，不是今天……"
D.Strings[12943]="还……没有完呢！"
D.Strings[12944]="下一次，我们就不会在这片圣地上决战了，圣骑士。"
D.Strings[12945]="我的迷惑项圈不见了！"
D.Strings[12946]="%s切换到战斗姿态！"
D.Strings[12947]="%s切换到狂暴姿态！"
D.Strings[12948]="%s切换到防御姿态！"
D.Strings[12949]="站起来，达里安，你听着……"
D.Strings[12950]="我们见证了一场可怕的悲剧。善良人的鲜血早已将这整片土地染红！无数高贵而英勇的骑士，为了保卫我们而牺牲在这里！"
D.Strings[12951]="我们永远不会忘记这一幕，我们仍然需要保持警惕！"
D.Strings[12952]="巫妖王必须为他的所作所为付出代价，我们绝不能再让他继续破坏这个世界。"
D.Strings[12953]="兄弟们，姐妹们，我向你们发誓：巫妖王一定会被消灭！今天，我们大家要重新团结起来。"
D.Strings[12954]="银色黎明和白银之手骑士团将在此合二为一！我们一定可以完成前人未尽的事业！"
D.Strings[12955]="我们要继续抗争阿尔萨斯，我们终将推倒冰冠冰川的城墙！"
D.Strings[12956]="阿尔萨斯，银色北伐军向你宣战！"
D.Strings[12957]="这也是黑锋骑士们的心愿……尽管在你们的世界中已没有立足之地，但我们仍要为打倒巫妖王而战斗。我在此立誓！"
D.Strings[12958]="%s沿着隧道爬了过来！"
D.Strings[12959]="给，$n。$b$b麻烦你集中精神，完成任务……"
D.Strings[12960]="我们的库房已经空了。在补给物资送来之前，我没东西可卖。"
D.Strings[12961]="谢谢你送来了一些补给物资，这样我又能拿起厨具啦。我能为你做什么呢？"
D.Strings[12962]="%s开始施放闪电新星！"
D.Strings[12963]="保持警惕，$r。$b$b生命在这里显得尤其脆弱！"
D.Strings[12964]="作为鲜血学徒，你们必须懂得如何掌控敌人的生命。"
D.Strings[12965]="借助武器或咒术，鲜血能提高我们的攻击力，同时削弱敌人的力量。"
D.Strings[12966]="真正的大师能利用鲜血在战斗中爆发出超越自身的强大力量。"
D.Strings[12967]="无论对手是一息尚存还是已然毙命，我们都能汲取他们的能量，以此获得远胜于低等生物的生存力。"
D.Strings[12968]="敌人倒下后，我们能窃取并利用他们残余的所有能量继续展开攻击。"
D.Strings[12969]="对鲜血大师来说，战斗是永无止境的……"
D.Strings[12970]="我们渴望着鲜血的洗礼……"
D.Strings[12971]="我们拥有敌人永远无法战胜的力量……"
D.Strings[12972]="鲜血大师掌控着生命与死亡。胆敢与我们为敌的家伙，会被抽干所有的能量，沦为毫无生气的死尸。"
D.Strings[12973]="飞船又不是因为我才坠毁的，为什么大家都朝我瞪眼？"
D.Strings[12974]="我们总算找到零件，可以修理诺莫瑞根之魂了。"
D.Strings[12975]="让我瞧瞧，拧一拧，再调整一下……"
D.Strings[12976]="你看，诺莫瑞根之魂！修好啦！"
D.Strings[12977]="你可以开着她去兜风，不过万一你在座椅上发现了刀片，可别来跟我抱怨。你要知道，我好不容易才凑齐了零件修理她，就别那么讲究啦。"
D.Strings[12978]="这是背叛！你将为这场骗局付出生命的代价！"
D.Strings[12979]="支配节杖散发着明亮的光芒！快使用它！"
D.Strings[12980]="一名地穴卫士加入了战斗！"
D.Strings[12981]="嗯……你有点面熟……让我想想……$B$B哈哈！西部荒野！我在西部荒野见过你。你是$n！咱们又见面啦，希望你能再次伸出援手。$B$B这里离西部荒野非常遥远，但是如果我们打不赢这一战，恐怕就要无家可归了。"
D.Strings[12982]="$n！你换了新衣服，差点认不出你啦。你还留着那件外套吗……或者你选了马裤……还是法杖？我不记得了，那已经是很久之前的事情了吧……$B$B嗯，很高兴你能来这里帮忙。我们需要一切可以动用的力量。$n，如果你的表现能像在西部荒野帮助人民军时一样好，那我们就有希望了。$B$B眼前的局势非常严峻，赢不了这一战，我们就休想回到西部荒野了。"
D.Strings[12983]="$n，有了圣光的祝福和你的帮助，迪菲亚已经不再构成威胁。$B$B但是我们距离西部荒野非常遥远，而且如果我们打不赢这一战，恐怕就要无家可归了。"
D.Strings[12984]="蠢货！你本来可以获得强大的力量！"
D.Strings[12985]="怎么可能？巫妖王陛下说过，他已经为你规划好了未来……"
D.Strings[12986]="我就知道任何人都不能相信！"
D.Strings[12987]="你拒绝了远大的前程。现在，去死吧！"
D.Strings[12988]="而且，即使是你的背叛，也已经阻止不了我了。"
D.Strings[12989]="我用不着再依靠你了。没有你，我一样可以毁灭祖达克！"
D.Strings[12990]="够了！"
D.Strings[12991]="你会为这场愚蠢的背叛而丢掉性命的！"
D.Strings[12992]="联盟夺取了东部墓地！"
D.Strings[12993]="联盟夺取了西部墓地！"
D.Strings[12994]="联盟夺取了南部墓地！"
D.Strings[12995]="部落夺取了东部墓地！"
D.Strings[12996]="部落夺取了西部墓地！"
D.Strings[12997]="部落夺取了南部墓地！"
D.Strings[12998]="空气中有潜藏着的能量在涌动……丰收的时候到啦！"
D.Strings[12999]="乌格雷斯开始施放强大的黑暗力量！"
D.Strings[13000]="一点都不好玩……"
D.Strings[13001]="新的玩具！"
D.Strings[13002]="真没意思……"
D.Strings[13003]="你怎么不动了呢？"
D.Strings[13004]="起来起来！我还没玩够呢！"
D.Strings[13005]="你们……只是让主人的计划更进一步……"
D.Strings[13006]="啊，娱乐节目要开始了！"
D.Strings[13007]="好玩的事才刚开始呢！"
D.Strings[13008]="啊！上等的材料！"
D.Strings[13009]="别担心，我会好好利用你的！"
D.Strings[13010]="去跟我的几位朋友打个招呼吧。"
D.Strings[13011]="来呀，斯坦索姆的市民们！来见见你们的“救世主”。"
D.Strings[13012]="砰！哈哈哈哈哈……"
D.Strings[13013]="鲜血……毁灭……真令人愉悦！"
D.Strings[13014]="我需要一份样本……"
D.Strings[13015]="如此强壮……我要了！"
D.Strings[13016]="你的血肉背叛了你。"
D.Strings[13017]="库尔格能为你做些什么呢？"
D.Strings[13018]="我准备好了。让我们保卫神庙吧！"
D.Strings[13019]="真不敢相信，蓝龙军团居然会攻击我们。我们要发动反击！"
D.Strings[13020]="从哪里着手呢？"
D.Strings[13021]="$n，久仰大名啊。这场战斗一定会非常有趣。"
D.Strings[13022]="我们是先攻打圣地呢，还是先对付敌军？"
D.Strings[13023]="我们一直在盼望着你，$n。现在我们总算占据了优势。"
D.Strings[13024]="你准备好作战了吗，$c？"
D.Strings[13025]="欢迎你，朋友。"
D.Strings[13026]="蠢货！你想唤醒那个可怕的造物，让它与我们的军队为敌吗？别想把源生石像带回诺森德！"
D.Strings[13027]="主人，就是这个无耻的凡人出卖了我们。我们一定要好好教训他！"
D.Strings[13028]="我要把你们的血涂在脸上！"
D.Strings[13029]="我是天生的战士！"
D.Strings[13030]="我的生命……献给死神！"
D.Strings[13031]="我又回来了！又得到一次把你们脑壳敲碎的机会！"
D.Strings[13032]="不！不！我还可以……做得更好。"
D.Strings[13033]="因格瓦尔！你这可耻的失败将警示所有巫妖王的仆从！你被诅咒了！站起来，重新执行主人的意志！"
D.Strings[13034]="真有意思……这附近储存着高纯度的奥术能量。我要去探察一番……"
D.Strings[13035]="这是你应受的惩罚。值得庆幸的是，你会死得很痛快。"
D.Strings[13036]="至于你……"
D.Strings[13037]="出演了一次如此令人愉悦的背叛，你那卑微的生命，我就留给你作为奖赏吧。或许你身上还大有潜力呢。"
D.Strings[13038]="下次见面时，你的性命可就没法如此轻易地保住了！"
D.Strings[13039]="你令我失望了，达库鲁。"
D.Strings[13040]="但你记住……"
D.Strings[13041]="我相信，巫妖王会败在我们手下。我们的复仇大业一定会取得成功。$B$B但首先，我们必须将血色先锋军这个祸端彻底解决掉！"
D.Strings[13042]="高级指挥官，我要听你的故事。"
D.Strings[13043]="好吧，但如果我是你的话，我会集中精神仔细聆听，而不是盲目地点点头表示回应。$B$B和所有精彩的故事一样，这个故事也是以背叛开场的。不过，并非是别人背叛了我们……事情并非如此。在巫妖王的众多仆从中，他最看重的就是我们——死亡骑士。$B$B但是，在大领主达里安·莫格莱尼的帮助下，我们背叛了他。$B$B瘟疫之地圣光之愿礼拜堂的那场决战中，就在我们几乎全军覆没的紧要关头，提里奥·弗丁帮助莫格莱尼以及幸存的死亡骑士摆脱了巫妖王的束缚。"
D.Strings[13044]="<你微微地点了点头，高级指挥官顿时眯起了眼睛。于是你赶紧停止动作，他这才开口继续说起了故事。>"
D.Strings[13045]="放弃吧，老老实实地受死吧。"
D.Strings[13046]="弗丁举起了灰烬使者，巫妖王见势不妙，便迅速逃走了。于是，我们轻而易举地从残余的天灾兵手中夺取了黑锋要塞的控制权。$B$B但是我们与血色十字军的隔阂并没有消除。$B$B就像被遗忘者当初的境遇一样，血色十字军总是将我们与天灾军团混为一谈。$B$B我们拥有独立的思想和目标，我们拥有生者的一切特质。但是对他们来说，我们和巫妖王麾下那些没脑子的奴隶没什么两样。$B$B他们居然误认为我们会再次臣服于巫妖王的淫威。"
D.Strings[13047]="他们现在自称血色先锋军了吧？"
D.Strings[13048]="高级指挥官，能再讲一遍刚才的故事吗？"
D.Strings[13049]="<高级指挥官瞪了你一眼，继续说道。>$B$B我马上就会讲到了。没错，阿比迪斯将军率领部队抵达诺森德后，就将血色十字军更名为血色先锋军了。$B$B先锋军驻扎龙骨荒野的新壁炉谷后不久，海军上将巴利·韦斯温前来拜访。据说，阿比迪斯将军完全没有料到他会来。她更没有料到韦斯温上将动摇了她在军中的地位，并最终夺得了兵权。$B$B你一定要问，她怎么能心甘情愿地让位呢，但这已经不重要了。阿比迪斯将军死后，韦斯温也神秘失踪了，我们一直没有找到他。"
D.Strings[13050]="我要内脏！要鲜血！要食物！"
D.Strings[13051]="把你剁碎，再吃掉！"
D.Strings[13052]="好饿啊！必须吃饭！"
D.Strings[13053]="要爆炸啦！"
D.Strings[13054]="韦斯温元帅去哪儿了？"
D.Strings[13055]="我说过，我们失去了他的行踪，但我相信你能帮我们找到他。我怀疑他就躲在岛上，可是我派出的探子始终搜不到他的藏身之所。$B$B虽然怨毒镇的被遗忘者对新壁炉谷展开了一系列的攻击行动，但如今残余在那里的先锋军都是身经百战的强者。不幸的是，他们设法获得了更精良的装备，还从某些白痴手里弄到了狮鹫。$B$B我想说，$n，不管你有多厉害，这项任务绝非是去乡间散步那么简单。"
D.Strings[13056]="没问题。什么时候可以开始行动？"
D.Strings[13057]="我们很快就要展开行动了。$B$B但是我必须说明——我们不是来削弱他们的士气的，也不是来吸引敌人的火力的。我们的目标是，彻底消灭血色先锋军。$B$B如果你对此不感兴趣，就趁早滚远点。我需要的是每天都能来帮忙，直到使命达成的伙伴。$B$B你觉得自己能胜任吗，$n？"
D.Strings[13058]="来吧，消灭先锋军！"
D.Strings[13059]="<高级指挥官咧嘴一笑，从头到脚地打量了你一番。>$B$B这正是我想听的。"
D.Strings[13060]="%s的防御气泡破裂了！"
D.Strings[13061]="%s开始召唤！"
D.Strings[13062]="多年来，血色十字军酿造的惨剧简直不尽其数。他们沦为了痛苦、狂热与谋杀的代名词。$B$B我不能再让这样的悲剧继续重演。你觉得呢？"
D.Strings[13063]="高级指挥官，这真是个精彩的故事。"
D.Strings[13064]="可恶的……哇哇！杀！对，杀了你！"
D.Strings[13065]="海德比武会是神圣的。获胜者将赢得终身陪伴托里姆的殊荣。"
D.Strings[13066]="我自由了？我自由了！"
D.Strings[13067]="真不敢相信！我可以走了！"
D.Strings[13068]="我该离开啦！谢谢你，朋友！"
D.Strings[13069]="我不知道元帅的下落。你去死吧！"
D.Strings[13070]="我要告诉大主教兰德雷！啊……"
D.Strings[13071]="卫兵！快来帮帮我！"
D.Strings[13072]="你好，$c。我可以帮你看管宠物，或者帮你找回走失的伙伴。"
D.Strings[13073]="我想寄养宠物。"
D.Strings[13074]="只有一个人能活下来！"
D.Strings[13075]="我要争取自由，离开这个该死的地方！"
D.Strings[13076]="你犯了一个严重的错误，魔鬼！"
D.Strings[13077]="他们说我是废物？我要让他们瞧瞧什么才叫废物！"
D.Strings[13078]="我曾经为圣光而战……可你看看我现在的样子……"
D.Strings[13079]="你会让我挑一把武器和一套盔甲吧？"
D.Strings[13080]="你没有获胜的希望，$r。"
D.Strings[13081]="我要拆除这座腐烂的地狱！"
D.Strings[13082]="尝尝冰冷钢铁的厉害吧，$r！"
D.Strings[13083]="死亡是唯一的出路！"
D.Strings[13084]="我们的未来看不到希望……"
D.Strings[13085]="战斗吧！"
D.Strings[13086]="该结束了！"
D.Strings[13087]="让恐惧将你淹没吧！"
D.Strings[13088]="哈！你连剑都拿不稳！你的末日即将来临。"
D.Strings[13089]="很好。来个了断吧。"
D.Strings[13090]="利斯巴克的载具商店开始营业啦！"
D.Strings[13091]="斯巴克莱特的战车商店开始营业啦！"
D.Strings[13092]="过来，兰德雷。我有很重要的事情要问你，你最好老实交代。"
D.Strings[13093]="你的母亲是一只扳手，你的父亲则散发着爆盐炸弹的气味！"
D.Strings[13094]="告诉我韦斯温的下落，不然我就摧毁你的灵魂！"
D.Strings[13095]="你休想从我嘴里问出元帅的下落。我还不至于受你摆布。"
D.Strings[13096]="看来我别无选择了。好吧，其实我很乐意这样对付你的。"
D.Strings[13097]="住手！用不着这样。我告诉你他的下落。"
D.Strings[13098]="很好。快说！"
D.Strings[13099]="这座岛屿的南端有一处极端隐蔽的洞穴。元帅就躲在那儿，策划着对巫妖王的最后决战。"
D.Strings[13100]="隐蔽的洞穴？真有意思。兰德雷，你没有利用价值了。恐怕这次你就没有复活的机会了！"
D.Strings[13101]="事情总算有了眉目，那么就让我们谈谈要如何对付巴利·韦斯温元帅吧。"
D.Strings[13102]="冰牙已经陪伴我经历过无数次战役。$b$b不要被她不穿护甲的表象迷惑了。她是我见过的最聪明的熊。"
D.Strings[13103]="别再耽搁时间了！$b$b激烈的战斗在等待！"
D.Strings[13104]="为布伦希尔达村的荣耀而战！"
D.Strings[13105]="黑暗编织者冲你露出邪恶的笑容，他的身体紧接着变成了完全不同的形态。"
D.Strings[13106]="既然你已经知道了，那就必须死了！"
D.Strings[13107]="即便在死后，你也无路可逃！"
D.Strings[13108]="我要吞噬你的灵魂！"
D.Strings[13109]="你休想活着离开这里！"
D.Strings[13110]="什么？！没关系。就算没有魔法屏障，我仍然可以轻易消灭你们！在绝望中感受我真正的力量吧！"
D.Strings[13111]="啊！我在那具虚弱的躯壳中待得太久了！"
D.Strings[13112]="Kirel narak！我是玛尔加尼斯！我是不朽的！"
D.Strings[13113]="够了！我在这里浪费了不少时间，必须回到家乡去回复体力。"
D.Strings[13114]="没有我的部队，你们永远也别想击败巫妖王。我会向他复仇的……还有你们！"
D.Strings[13115]="你们觉得我会甘心等死吗？"
D.Strings[13116]="你怎么找到我的？难道兰德雷全招了？"
D.Strings[13117]="冰牙非常勇敢，不穿盔甲也敢上战场。$b$b$n，或许她能让你鼓起勇气，面对即将到来的挑战。"
D.Strings[13118]="天啊……"
D.Strings[13119]="嘿，$c。如果你弄丢了钥匙，我或许能帮上忙。"
D.Strings[13120]="我把通灵学院的钥匙弄丢了。"
D.Strings[13121]="我把禁魔监狱的钥匙弄丢了。"
D.Strings[13122]="我把破碎大厅的钥匙弄丢了。"
D.Strings[13123]="我把灼热峡谷的钥匙弄丢了。"
D.Strings[13124]="我把暗炉钥匙弄丢了。"
D.Strings[13125]="我把哈拉迈德之眼弄丢了。"
D.Strings[13126]="我把卡拉赞的钥匙弄丢了。"
D.Strings[13127]="站在你面前的是一位奥术魔法的大师。只有蠢货才会不自量力地向我宣战。他们无一例外地变成了烧焦的尸体。"
D.Strings[13128]="我的生命与灵魂中充斥着部落留给我的痛苦回忆。悲伤、绝望和牺牲已经成为历史。战争的怒火永远在我内心深处燃烧！"
D.Strings[13129]="该传送门通往阿拉希盆地战场。"
D.Strings[13130]="该传送门通往奥特兰克山谷战场。"
D.Strings[13131]="该传送门通往风暴之眼战场。"
D.Strings[13132]="你的能力还不足以参加暴风之眼的战斗。等你拥有更多经验的时候再来这里吧。"
D.Strings[13133]="该传送门通往战歌峡谷战场。"
D.Strings[13134]="有什么事吗？$B$B你是来吃东西，还是来学习厨艺的？我可是最棒的大厨噢。"
D.Strings[13135]="想要购买战袍？"
D.Strings[13136]="我把血骑士战袍弄丢了。"
D.Strings[13137]="我把阿古斯之手战袍弄丢了。"
D.Strings[13138]="我把绿色伊利达雷战袍弄丢了。"
D.Strings[13139]="我把紫色伊利达雷战袍弄丢了。"
D.Strings[13140]="你好，$c。我可以帮你找回失散的伙伴。"
D.Strings[13141]="我把成就战袍弄丢了。"
D.Strings[13142]="我把保卫者的战袍弄丢了。"
D.Strings[13143]="你被发现了！快使用投网和地面速冻，别让那些矮人靠近你！"
D.Strings[13144]="%s嗅着地面，寻找气味的踪迹。"
D.Strings[13145]="%s循着气味找到了源头。"
D.Strings[13146]="冰霜猎犬发现了小偷的藏身之所。快去对付他！"
D.Strings[13147]="蛇鳞的仆从，响应我的召唤！"
D.Strings[13148]="你的血肉将被千万颗利齿撕咬！"
D.Strings[13149]="巨魔把我惹火了！"
D.Strings[13150]="你好啊！你想要购买渔具，还是学习垂钓的艺术？"
D.Strings[13151]="我踏遍了艾泽拉斯的每一寸土地，想要寻找失落的荣耀并收复属于我的王国。在我离开暴风城的这段日子里，联盟经历了种种考验。有你这样的英雄保卫我们脆弱的盟国，我真是倍感欣慰。"
D.Strings[13152]="%s开始变形！"
D.Strings[13153]="%s变成了一头猛犸象！"
D.Strings[13154]="怒爪自由了！巨魔去死吧！"
D.Strings[13155]="再也不会有狼獾人好好先生了！"
D.Strings[13156]="去死吧，巨魔！"
D.Strings[13157]="为怒爪复仇！"
D.Strings[13158]="啊啊啊啊！！！"
D.Strings[13159]="我要宣战！"
D.Strings[13160]="检测到创世者的圆盘的用途。激活紧急协议。"
D.Strings[13161]="检验诺甘农之壳的状态。"
D.Strings[13162]="诺甘农之壳处于安全状态。核实用户身份后即可进行数据传输。"
D.Strings[13163]="准备核实守护者米米尔的身份。"
D.Strings[13164]="身份核实失败。用户非守护者米米尔。"
D.Strings[13165]="创世者的圆盘已落入非法用户手中。激活防御协议。"
D.Strings[13166]="消灭冒名顶替者。夺回创世者的圆盘。"
D.Strings[13167]="我的先锋军，将会荡平巫妖王的部队！"
D.Strings[13168]="你的牺牲是徒劳的，渺小的凡人。"
D.Strings[13169]="你的生命结束了。"
D.Strings[13170]="别再浪费时间了。$c，消灭巫妖王的爪牙！"
D.Strings[13171]="对抗巫妖王的战事有何进展，$c？"
D.Strings[13172]="先锋军将彻底消灭巫妖王的部队！"
D.Strings[13173]="很高兴再见到你，$n。"
D.Strings[13174]="你还好吧？如果你能站起来的话，我会送你返回冰霜堡。"
D.Strings[13175]="<当你靠近时，霜脉斥候试图站起来；但是他很快就跌倒在地，紧紧地捂住身体上那条明显的伤口。>"
D.Strings[13176]="来不及了。我失血过多……坚持不了多久了。"
D.Strings[13177]="很抱歉，我来晚了。发生了什么事？"
D.Strings[13178]="一群鹰身人突然冲出山谷。带领她们的是一只名叫希尔拉娜的鹰身人……我无路可逃。我不明白……她们为何变得如此具有攻击性……我放松了警惕……是我的失误。"
D.Strings[13179]="我去求援。你待在原地别动。"
D.Strings[13180]="没……没有用……太晚了。$B$B<霜脉斥候往雪地上咳出几口鲜血。>$B$B替我……报仇……$B$B<霜脉斥候咽下最后一口气，摊倒在地。>"
D.Strings[13181]="$c，环顾四周，将这破败的景象印在你的脑海中吧。居住在这里的巨魔不是死了就是逃到上层去了。$B$B局势越来越严峻了。$B$B陷入绝望的达卡莱巨魔杀害了氏族崇拜的动物之神，并饮下它们的鲜血来攫取难以言喻的力量。虽然他们凭借新的力量成功地牵制了天灾军团的攻势，却由此引发了灾难性的后果。沦为废墟的远古帝国祖达克就是最好的例证。"
D.Strings[13182]="你千万不能败露自己的行踪。我要继续装出臣服于巫妖王的模样！"
D.Strings[13183]="戈尔克、布尔和达加斯都死了……只有我和马克拉尔活了下来。希望你为我们带来了好消息。"
D.Strings[13184]="你能修好我的设备吗？"
D.Strings[13185]="嘀嗒嘀，嘀嗒嘀……"
D.Strings[13186]="还不够快！"
D.Strings[13187]="我们快点了结这一切吧。"
D.Strings[13188]="你已经没有未来了。"
D.Strings[13189]="这是我们获得伟大胜利的一刻！"
D.Strings[13190]="你命该就此陨落。"
D.Strings[13191]="你敢？！斯利文男爵呢？我要和他说话！"
D.Strings[13192]="维尔自由了？维尔爱$n！"
D.Strings[13193]="碾碎你……毁灭！"
D.Strings[13194]="是谁干扰了我的仪式？"
D.Strings[13195]="你就是那个捣乱的家伙？要对付你，真是易如反掌。"
D.Strings[13196]="亲爱的将军，你的末日来临了！"
D.Strings[13197]="安静！孩子们在睡觉！"
D.Strings[13198]="他们是来杀你的。"
D.Strings[13199]="放纵你内心的恐惧吧。"
D.Strings[13200]="杀光他们……别让他们先杀了你。"
D.Strings[13201]="他们已经背叛了你。现在……复仇吧。"
D.Strings[13202]="告诉你自己，这些人并不是你真正的朋友。"
D.Strings[13203]="没有退路了。这一生不会有。下一世亦不会有。"
D.Strings[13204]="你正被某种隐形的力量操控着。"
D.Strings[13205]="这是你的错。"
D.Strings[13206]="你们这些丑陋的小怪物，最好祈祷我出不去！"
D.Strings[13207]="我要把你们碾碎！"
D.Strings[13208]="恶心的家伙！"
D.Strings[13209]="我的兄弟会来救我的，然后你们就会见识到真正强大的力量！"
D.Strings[13210]="你们的酷刑只会激怒我！"
D.Strings[13211]="我要把你打垮！"
D.Strings[13212]="你们以为这个笼子能关我多久，魔鬼！"
D.Strings[13213]="我要能把你打败的话会很高兴！"
D.Strings[13214]="我要拿你去领赏！"
D.Strings[13215]="你的武器将成为我的收藏品。"
D.Strings[13216]="别想打赢我！"
D.Strings[13217]="你来送死吗？"
D.Strings[13218]="我诅咒你！"
D.Strings[13219]="面对我的愤怒吧！"
D.Strings[13220]="我要消灭你！"
D.Strings[13221]="干得漂亮！到斯坦索姆的大门去，我会交给你下一项任务！"
D.Strings[13222]="再见。希望下次见面时，局势能好一些。我永远不会忘记你为我们所做的一切！"
D.Strings[13223]="天选者奥贾尔就在东北方的痛苦之匣。\n\n纳瓦留斯王子在东边死亡旷野的远端。"
D.Strings[13224]="我……还没……还没……"
D.Strings[13225]="休息一会，然后和我一起来启动这个东西。一切……马上就要真相大白了。好了，我们开始吧！"
D.Strings[13226]="干得好，你们的晚饭算是有着落了。"
D.Strings[13227]="抓紧，这边走这边走！"
D.Strings[13228]="你们想要挑战主人？先平息我的风暴吧！"
D.Strings[13229]="这点轻微的花火，将带来你们的灭亡！"
D.Strings[13230]="没有人是安全的！"
D.Strings[13231]="很震惊？我可以理解。"
D.Strings[13232]="你在尝试不可能做到的事！"
D.Strings[13233]="你的生命之火……就此熄灭了。"
D.Strings[13234]="主人……您有客人了。"
D.Strings[13235]="你们还有什么希望可言？完全没有！"
D.Strings[13236]="我曾见证过无数帝国的崛起与衰落……也见证过无数物种的诞生与灭绝……千百年来，凡人种族的愚蠢都不曾改变过。你们出现在这里，更是印证了这一点。"
D.Strings[13237]="在主人为我展示的未来图景中，没有你们的位置。艾泽拉斯将在黑暗中获得新生。尤格-萨隆将获得自由，而万神殿，必将毁灭！"
D.Strings[13238]="你们无法逃避命运！"
D.Strings[13239]="靠近点。我立刻送你们归天。"
D.Strings[13240]="你们的血肉之躯无法长存于世。"
D.Strings[13241]="区区凡人……"
D.Strings[13242]="我……就是永恒！"
D.Strings[13243]="你们把短暂的生命全部浪费掉了！"
D.Strings[13244]="我的死亡……预示着世界的终结。"
D.Strings[13245]="你们还不知道自己正在注视着无尽的深渊吗！"
D.Strings[13246]="你们太无知了。竟然看不清这条路通向何方吗？"
D.Strings[13247]="这条道路的尽头就是湮灭！"
D.Strings[13248]="铁矮人在追你！快使用结网和地面速冻逃跑！"
D.Strings[13249]="霜齿已经追踪到了气味的源头。进入洞穴仔细搜查！"
D.Strings[13250]="%s嗅着气味，寻找踪迹。"
D.Strings[13251]="%s循着气味找到了洞穴中的气味源头。"
D.Strings[13252]="嗯，你们帮我看着点外面。我这样的强者只要锤两下就能搞定这破烂……"
D.Strings[13253]="噢，见鬼，好像有点不太妙，看来我们遇到点小麻烦啦……"
D.Strings[13254]="嘿，破机器，怎么样？你想跟我来硬的？太可惜了，这是属于我的游戏！"
D.Strings[13255]="再给我几分钟，马上就能……啊噢……"
D.Strings[13256]="提高？这算是好消息吗？"
D.Strings[13257]="哈！终于找到问题出在哪儿了！我马上就能搞定了……"
D.Strings[13258]="等等！你想清理谁啊！有我在，没门！"
D.Strings[13259]="哈！看来还是我这把老骨头厉害呀！然后再看看这里……"
D.Strings[13260]="消除？不不不不……呀，我刚才搞到哪来着？啊哈！应该是这样！"
D.Strings[13261]="是该收获答案了！让我们一路杀过去吧！"
D.Strings[13262]="我已经竭尽全力了！"
D.Strings[13263]="圣光会保佑你的！"
D.Strings[13264]="希望这牺牲是值得的！"
D.Strings[13265]="问询？要不你以为我来这干嘛？喝下午茶吗？少废话！"
D.Strings[13266]="告诉我矮人是怎样演化出来的！从最初开始！"
D.Strings[13267]="对，对。我已经知道土灵是用石头创造出来，用以改造地下世界的。但变异是怎么发生的？我听说过什么母体扰动？"
D.Strings[13268]="寄生性噬主……什么来着？讲通用语会死吗？"
D.Strings[13269]="上古之神是吧，也就是说他们给土灵施加了什么血肉的诅咒，然后怎么样了？"
D.Strings[13270]="如果他们真的杀光上古之神，那艾泽拉斯也就毁灭了……"
D.Strings[13271]="什么守护者？"
D.Strings[13272]="艾塞尔与瓦尼尔……好吧，这么说意志熔炉又从头开始创造了新的土灵……那老的怎么样了？"
D.Strings[13273]="等等！等等！你是说艾塞尔与瓦尼尔之间爆发了战争？为什么？"
D.Strings[13274]="这个“洛肯”听起来真是阴险狡诈。还好不用再理会他了。那么……如果我的理解没有错，最初的原始土灵是否因为某种原因从休眠仓里苏醒了过来，还受了这个什么母体扰动的影响，最终演化成现代的矮人？至少……是现代矮人的祖先。"
D.Strings[13275]="啊，现在我得花上很长时间来好好消化这些知识。我要在这里再待一会儿。谢谢你们。"
D.Strings[13276]="我会用熔炉来制造一些土灵，让他们保卫这里……但现在最大的挑战是：找到并阻止洛肯！"
D.Strings[13277]="暴风将赐予我力量！"
D.Strings[13278]="愿闪电指引我的怒火！"
D.Strings[13279]="让暴风吞噬你！"
D.Strings[13280]="邪恶必将受到惩罚！"
D.Strings[13281]="啊啊啊！！！强大的力量！"
D.Strings[13282]="闪电的力量在我体内流淌！"
D.Strings[13283]="尝尝暴风之王的怒火！"
D.Strings[13284]="美味的点心自己送上门来了呀！我能用炸弹把你烤熟吗？"
D.Strings[13285]="欢迎你，$c。"
D.Strings[13286]="我要把你踩在脚下！"
D.Strings[13287]="我要用你来擦靴子！"
D.Strings[13288]="小家伙，我一脚就能踩扁你！"
D.Strings[13289]="尝尝盖米尔的厉害！"
D.Strings[13290]="我自由了！！！你很快就会感受到暴风之王的怒火！"
D.Strings[13291]="正在检索……造物主曾经亲自回来清除噬主共体生物所造成的感染。根据当时的评估，上古之神滋生所造成的危害非常严重。强行分离被感染部分将导致宿主损毁——"
D.Strings[13292]="正确。造物主决定中和寄生体的威胁，并将其封锁在宿主内部。之后，包括意志熔炉在内的各系统受命开始创造新的土灵。植入了新的安全机制，并任命了守护者。"
D.Strings[13293]="名称：艾塞尔与瓦尼尔。如果用通用语命名，则是风暴巨人与岩石巨人，最高领袖为哨兵洛肯。守护巨龙受命监管艾泽拉斯世界的进化过程。"
D.Strings[13294]="另有后台信息与你的问询关联：在艾塞尔和瓦尼尔的全面战争之后——"
D.Strings[13295]="不详。数据显示，全面战争是由首席管理官洛肯发起的，他在此之后中和了所有残余的艾塞尔与瓦尼尔，结束了冲突。接着，他停止了包括土灵、巨人和维库人在内的数个源种生物的演化进程，并将他们全部封存在指定的封存仓内。"
D.Strings[13296]="本质上的确如此。"
D.Strings[13297]="我自由了，暴风的复仇将随之而来！"
D.Strings[13298]="开战之前，我会向你介绍敌人的情况。听仔细了，要对付天灾军团，必须做好充分的准备。"
D.Strings[13299]="正在检索史前数据……文档定位完毕。创世之初，土灵的使命是——"
D.Strings[13300]="正在检索……在其发展周期的初始阶段，艾泽拉斯世界遭受到了寄生性噬主共体生物的感染。"
D.Strings[13301]="名称：上古之神。上古之神感染了包括土灵在内的整个毫无防备的系统，意图将所有事物向他们自身同化。这种扰动母体结构的行为与现象被定义为“血肉诅咒”。扰动的效果与日俱增。"
D.Strings[13302]="收到，布莱恩布隆赞。进程终止。"
D.Strings[13303]="盖米尔，奥贾尔、纳瓦留斯和塞穆在哪儿？"
D.Strings[13304]="盖米尔，我要注意些什么？我从来没有骑过巨人。"
D.Strings[13305]="我准备好了，盖米尔。我们走吧！"
D.Strings[13306]="<布莱恩满怀期待地看着你。>"
D.Strings[13307]="你能想象吗？奥杜尔中埋藏着所有的智慧与知识，甚至还有生命本身的秘密！"
D.Strings[13308]="你能听懂我的话吗？现在，我们应该能沟通了吧。"
D.Strings[13309]="探险者协会真的派出了其他探员？我一个也没见着。我在一座被铁矮人攻占的营地里发现了你的日记。"
D.Strings[13310]="有个斥候在索尔莫丹发现了这本日记的剩余部分。从那时起，我们就开始寻找你的下落了。"
D.Strings[13311]="我……我能听懂！呃，既然我们能够对话，那么我想听听你的解释！"
D.Strings[13312]="你是怎么从探险者协会那里拿到我的联络器的？"
D.Strings[13313]="你解决了铁矮人，我很感谢你。但是部落为什么会对我感兴趣？"
D.Strings[13314]="该不会是斥候沃塔肯吧？连我都听说过他冷酷无情的名头。所以他是打算绑架我的吧？"
D.Strings[13315]="如果你看过日记，就该知道我发现了什么。泰坦的造物正在自相残杀！"
D.Strings[13316]="洛肯和他的铁矮人已经将土灵逐出了奥杜尔，并占领了这座城市。"
D.Strings[13317]="如果我们继续厮杀，洛肯就会利用奥杜尔的资源将联盟和部落一起摧毁。"
D.Strings[13318]="去和指挥官谈谈，劝他放弃沃塔肯的愚蠢计划吧。"
D.Strings[13319]="伯克塔认为坠机事故只是一次倒霉的经历，但是我相信我们可以从中学到点什么。"
D.Strings[13320]="伊米亚的战争领主，天选者奥贾尔就在东北方的痛苦之匣，准备唤醒他的瓦古大军。$B$B跨越东边的死亡旷野，你可以在通往祖达克第二层的阶梯附近找到纳瓦留斯王子。$B$B塞穆不知所踪，从体型来看，他是很难藏匿的。$B$B必须将他们统统解决！"
D.Strings[13321]="毒药……胃部在剧烈翻腾……"
D.Strings[13322]="我准备好了——我们离开这里吧。"
D.Strings[13323]="你准备好了就告诉我一声。我希望越快越好……因为毒药正在慢慢发作。"
D.Strings[13324]="我本来想把毒囊交给莉吉特的……接着……你也知道了……我倒下了。谢谢你帮我！"
D.Strings[13325]="我们必须继续攻打尤顿海姆。不能给他们丝毫喘息的机会！让他们不眠不休地疲劳作战！拒绝纳降！$B$B即便是灰烬使者的持有者提里奥·弗丁和他麾下的银色北伐军，都不可能取得你如今的成就！$B$B$n，开战吧！就在我们闲聊的时候，说不定局势已经发生了巨大的逆转。"
D.Strings[13326]="等你准备好，我就将你放在我的头顶，然后我们一起消灭祖达克的天灾军团。你要指挥我对付敌人！"
D.Strings[13327]="你达到了1级军衔：下士"
D.Strings[13328]="你达到了2级军衔：中尉"
D.Strings[13329]="我们遇到麻烦了，$r！当心身后！"
D.Strings[13330]="主人！不！"
D.Strings[13331]="塞穆来了！"
D.Strings[13332]="塞穆……为……为我报仇……"
D.Strings[13333]="哦，是你放了他？无所谓，不过是将他的死期和重生稍微往后推了一点而已。"
D.Strings[13334]="感谢你帮助黑锋骑士团夺取了暗影拱顶。能得到你的支持真是我们的荣幸。$B$B联盟和部落仍在互相厮杀，殊不知这只会让巫妖王获益。我们必须集中精力，处理好眼前的要事。$B$B对银色北伐军来说，他们总是在制定作战计划时犹豫不决，一心想着如何完美地击败敌人，我们就没有这些乱七八糟的担忧。$B$B$n，你就是我们执行复仇大业的工具。"
D.Strings[13335]="我要把你撕成碎片。"
D.Strings[13336]="你想挑战？"
D.Strings[13337]="你看上去并不强壮。"
D.Strings[13338]="你觉得自己够格吗？"
D.Strings[13339]="动手吧，我的姐妹。"
D.Strings[13340]="欢迎你，我的姐妹。我能帮你找回失散的伙伴。"
D.Strings[13341]="死亡骑士们……到这儿来！"
D.Strings[13342]="进来吧，我的姐妹。$B$B好好地吃上一顿，再睡个安稳觉，这样才能养足精力，全力备战！"
D.Strings[13343]="他们还真是不堪一击啊！"
D.Strings[13344]="挑战者只留下了一滩血迹！"
D.Strings[13345]="不如叫些小丑来！神圣的斗兽场已经沦为马戏团了！"
D.Strings[13346]="哇！那家伙需要好好地“刮一刮”！"
D.Strings[13347]="我还没回过神来——就听见“砰”的一声！挑战者就死了！"
D.Strings[13348]="女士们先生们，请闭上双眼！这简直是大屠杀！"
D.Strings[13349]="进入痛苦斗兽场吧，$n。战斗开始后，你就必须留在竞技场里。要么获胜，要么死亡！"
D.Strings[13350]="女士们先生们，我们又见面啦。痛苦斗兽场的生死大战即将拉开帷幕！这一轮，将由$n对阵庞大的冰虫伊戈……伊戈达？伊戈杜斯？这名字是谁起的？！好吧，由$n对阵大虫子！"
D.Strings[13351]="%s出场了！"
D.Strings[13352]="$n击败了伊戈……伊戈这只大虫子！"
D.Strings[13353]="做好准备，$n！进入斗兽场，准备战斗！记住，你和你的对手都不能离开竞技场，否则你会被取消资格！"
D.Strings[13354]="战斗即将开始！我没念错吧？这……这是邪恶的猛犸人领主，恶臭之须！是的，各位，是恶臭之须！$n毫无取胜的希望！"
D.Strings[13355]="$n以绝对优势战胜了猛犸人领主！龙骨荒野的猛犸人氏族会怀念恶臭之须的！"
D.Strings[13356]="一群小不点，恶臭之须来了！"
D.Strings[13357]="我要熔化你们的血肉！"
D.Strings[13358]="你们感觉到了吗？能量在空气中沸腾！这只能说明……"
D.Strings[13359]="懦夫！"
D.Strings[13360]="站起来吧，大地的兄弟们。伊拉修斯要消灭这群凡人！"
D.Strings[13361]="为猎潮者而战！海洋与风暴的力量，摧毁我的敌人吧！"
D.Strings[13362]="风之领主，让我的敌人迅速死去吧！"
D.Strings[13363]="除非亲眼目睹，否则接下来的战斗将令人难以置信！这位即将出场的战士原本是个脾气温和的海象人渔夫，但是他的全家被恶毒的海狮和暴躁的企鹅杀死了，从此他就变成了一个行尸走肉般的雇佣兵。现在，他只为金币而战！女士们先生们，他就是奥里努克·碎牙！！"
D.Strings[13364]="来吧，旱鸭子。面对我的怒火吧！"
D.Strings[13365]="科尔拉克来了！雪落墓地属于冰斧的勇士！呃，科尔拉克是想要说，斗兽场属于冰斧的勇士！"
D.Strings[13366]="别想对科尔拉克耍花招，斗兽场可没有墓地！去死吧！"
D.Strings[13367]="来自冰冠冰川野蛮之台的屠夫乌拉多弗以及他的猛犸象恩诺姆斯！各位，这次我们的挑战者恐怕会被轰得连渣都不剩！让我们共同期待一场腥风血雨的大战吧！"
D.Strings[13368]="嗨，宝贝儿，将他们统统撕碎！我们才是真正的王者！"
D.Strings[13369]="没用的家伙！看来我得亲自动手了！"
D.Strings[13370]="乌拉多弗跃下了猛犸象！"
D.Strings[13371]="黑锋骑士团指挥官、天灾军团征服者以及暗影拱顶征服者——兰克拉尔公爵命令你束手就擒。你接不接受这份裁决？"
D.Strings[13372]="接不接受？这就是我的回答，小信差！"
D.Strings[13373]="冰斧巨魔的勇士向你发起了挑战，$n！希望你已经做好了准备！"
D.Strings[13374]="奥特兰克山谷的访客，斗兽场中迄今为止最为凶猛的斗士：血怒者科尔拉克！！！"
D.Strings[13375]="难以置信！新的痛苦斗兽场勇士诞生了！！！一群无名小卒击败了屠夫乌拉多弗！真是个奇迹！"
D.Strings[13376]="%s聚集了魔精，向前冲去！"
D.Strings[13377]="$n被逼到了绝路！"
D.Strings[13378]="如果你没别的事可做，就去杀掉这些家伙吧！"
D.Strings[13379]="我能照顾自己的，$n。"
D.Strings[13380]="%s越来越疯狂了！"
D.Strings[13381]="魔精池里似乎有什么生物在骚动……"
D.Strings[13382]="你在这儿干什么？$B$B别挡我的路。我不会让你这种人干扰血色先锋军的！"
D.Strings[13383]="我要和你决斗，先锋军的混蛋！"
D.Strings[13384]="你竟敢挑战我？！别以为这样就能阻止我向巫妖王效忠！"
D.Strings[13385]="尝尝我的铁拳吧，小鬼！"
D.Strings[13386]="别来打扰我。我正在研究那些“格斗者”的笨拙动作。$B$B我要将他们统统击败，然后我就会被提拔为巫妖王的部属了。"
D.Strings[13387]="我听说女性维库人根本不擅长战斗。如果你想证明我是错的，可以自己试试。"
D.Strings[13388]="你似乎能帮我赚点钱。来痛苦斗兽场转转怎么样，伙计？"
D.Strings[13389]="现在你是斗兽场的勇士啦！你觉得自己能保住这个头衔吗？"
D.Strings[13390]="%s开始施放毒性新星！"
D.Strings[13391]="本单元正在忙碌。请稍后查询。"
D.Strings[13392]="在监工看见我们之前，快回去工作吧。"
D.Strings[13393]="我不是工人。我是来解救你的，你不用再在矿井里干苦力了。"
D.Strings[13394]="又自由了？守护者米米尔的工作还没有做完。"
D.Strings[13395]="谢谢你，$r。我要和你一起反抗雷铸铁矮人。"
D.Strings[13396]="新指令：离开矿井并返回创世者的图书馆。"
D.Strings[13397]="新指令：帮忙击败铁矮人。"
D.Strings[13398]="无法计算。单元发生故障。指令：关闭。"
D.Strings[13399]="我是至高无上的土灵之王！仆从们，现身吧——快来帮助你们的君王！"
D.Strings[13400]="你无法用火焰烧毁我的王国！来吧，仆从们，我还不打算退位呢！"
D.Strings[13401]="我带起一阵足以吹倒大树的狂风！仆从们，快来帮我，他们不会得逞的！"
D.Strings[13402]="我是万恶之恶，冷血之王！过来吧，元素仆从们，让我们冰封一切，统治世界！"
D.Strings[13403]="冻须！你在哪儿？！快来帮我！"
D.Strings[13404]="这里是神圣的献祭之厅！你们这些入侵者的结局只有死亡！"
D.Strings[13405]="%s开始旋转，一个魔法护盾包围了他！"
D.Strings[13406]="这件霍迪尔号角的仿制品是为了纪念安格里姆国王以及所有在落雷谷之战中牺牲的巨人而造的。"
D.Strings[13407]="该死的！你不能把我当牲口一样对待！"
D.Strings[13408]="够了！我要教你学会懂礼貌！"
D.Strings[13409]="我宁愿战死，也不会为了苟活而去做奴隶！"
D.Strings[13410]="回去……工作……"
D.Strings[13411]="在你眼里，我们连牲口都不如！"
D.Strings[13412]="总有一天……我们要复仇。"
D.Strings[13413]="谢谢，谢谢你！总算能摆脱这些蓝皮肤的疯女人了！"
D.Strings[13414]="这个绿皮肤的小鬼根本派不上用处。不过没关系，他可以在作战前充当热身的对象。"
D.Strings[13415]="你还需要热身吗……莫非你害怕面对与你同等体型的对手？"
D.Strings[13416]="我什么都不怕——来吧！"
D.Strings[13417]="强者将获得胜利！"
D.Strings[13418]="祝你好运……你需要的就是运气了！"
D.Strings[13419]="你不配与托里姆并肩作战！"
D.Strings[13420]="打得不错啊，小家伙。我输了。我们还会再见面的。下次我一定会做好充分的准备。"
D.Strings[13421]="啊！！！！我要宰了你！"
D.Strings[13422]="你也想向巫妖王证明自己的实力吗？$B$B你不觉得这样的方式有点过时吗？非要争个你死我活吗？"
D.Strings[13423]="嘿，我认识你！我要感谢你把我送到这里。那次传送事故是我最美好的体验。$B$B如果你有机会回到北风苔原的话，告诉那个自以为是的复制品，我已经取得了相当大的成就！"
D.Strings[13424]="抱歉，丁奇。我有事要办，不能陪你。"
D.Strings[13425]="哟！！！"
D.Strings[13426]="出售小吃！"
D.Strings[13427]="小吃！"
D.Strings[13428]="来买点小吃吧！"
D.Strings[13429]="小吃！来买点小吃吧！"
D.Strings[13430]="爆米花！来买点爆米花吧！"
D.Strings[13431]="花生！来买点花生吧！"
D.Strings[13432]="痛苦啤酒！来买点冰镇的痛苦啤酒吧！"
D.Strings[13433]="爆米花！花生！啤酒！"
D.Strings[13434]="弗约恩的铁砧被摆放在丹尼芬雷最显然的位置，象征着他们击败弗约恩以及冰霜巨人大军的战绩。$b$b你忍不住笑了起来，你的举动竟然对世界产生了如此深远的影响。"
D.Strings[13435]="我不再训练死亡骑士了，我受够了那些愚蠢的新兵和他们无穷无尽的提问。$B$B现在，请你走开。"
D.Strings[13436]="检测到不明金属样本。"
D.Strings[13437]="开始分析……"
D.Strings[13438]="确认样本为萨隆邪铁与铁的合金。"
D.Strings[13439]="该样品中的矿石成分来自艾泽拉斯的地壳深处，这种矿石是最近才被挖掘出来的。"
D.Strings[13440]="该样品中萨隆邪铁的纯度非常高。在自然状态下，这种矿石是不会出现在艾泽拉斯表面的。"
D.Strings[13441]="只有强大而邪恶的力量才能创造出这种矿石。尝试访问数据库，搜索更多信息……"
D.Strings[13442]="奥努森要宰了你！"
D.Strings[13443]="奥努森来这里挑战维库人，以此提升自己的地位。$B$B然后，奥努森要在瓦哈拉斯战斗并赢得胜利，奥努森要为巫妖王效力！"
D.Strings[13444]="奥努森，我要告诉你一个坏消息。那就是，我将粉碎你的梦想！"
D.Strings[13445]="拒绝访问？！"
D.Strings[13446]="要了解更多信息，必须获取守护者洛肯的指令，然后访问奥杜尔的档案。"
D.Strings[13447]="指令完成。返回待机模式。"
D.Strings[13448]="你们当中有谁愿意献身？"
D.Strings[13449]="你好，$n。这里是守护者米米尔的工作室。"
D.Strings[13450]="我发现了这块奇怪的护甲板。你知道这玩意儿的来历吗？"
D.Strings[13451]="我敢肯定的是：从护甲板的尺寸、厚度以及螺丝孔的位置来看，它肯定是某个巨型装置的护甲。"
D.Strings[13452]="雷铸铁矮人的暴政终于走到头了！"
D.Strings[13453]="你的奴仆将再也不能攻击岩石的子嗣和他们的盟友了。"
D.Strings[13454]="我要终结你的性命，瓦杜兰！"
D.Strings[13455]="自以为是的预言家！不过谁能想到，一块岩石也能思考？"
D.Strings[13456]="如果你急于开战，我可以满足你。但是，无论你做什么，都无法阻止铁巨人的完成！"
D.Strings[13457]="我曾经拥有一切。名望、财富、一整套最棒的角斗士套装……我却亲手毁了这一切。$B$B他们发现我有舞弊行为……进行胜负交易……一切全完蛋了。$B$B如今我一无所有，只剩下这身破烂的衣衫，还有一只坏掉的肝脏。"
D.Strings[13458]="霍迪尔之子！在此，我谦卑地奉上……"
D.Strings[13459]="霍迪尔之盔！"
D.Strings[13460]="你是谁？$B$B走开……港口的建设工作非常繁重，我已经累得筋疲力尽了。现在我要喝上两口矮人啤酒，痛痛快快地哭一场再美美地打个盹儿。"
D.Strings[13461]="座狼一路飞奔，搜索着敌人的踪迹。"
D.Strings[13462]="接近猎物时，座狼咆哮起来。"
D.Strings[13463]="冰霜座狼嗥叫着，它发现了猎物！"
D.Strings[13464]="我曾经拥有一个温暖的家，它就坐落在奎尔萨拉斯苍翠的森林中。我还记得我的丈夫……还有孩子们的笑容。我曾经生活在这个美好的世界。眨眼之间，巫妖王夺走了这一切。$B$B虽然单凭我的力量根本不足以与他抗衡，但是总有一天，我要让他付出三倍的代价！"
D.Strings[13465]="这简直是里程碑式的胜利！皇家炼金师协会花费了数年时间来破解巫妖王诅咒的秘密，现在总算取得了突破！$B$B虽然实验的成功堪称历史的转折点，但是还有很多东西有待研究。我要做更多的实验……挑选更多的样本……$B$B至少我不用担心浮空城。联盟会解决那个玩意儿的。这样我就有足够的时间来研究，揭示其中的奥妙。"
D.Strings[13466]="有霜脉矮人的地方就有雄鹰。在我降生之前，它们就是氏族的盟友了……如今我已不再年轻了。"
D.Strings[13467]="联盟占领了沉降之环攻城车间！"
D.Strings[13468]="联盟占领了破碎神殿攻城车间！"
D.Strings[13469]="部落占领了沉降之环攻城车间！"
D.Strings[13470]="部落占领了破碎神殿攻城车间！"
D.Strings[13471]="国王派你来接受试炼？他一定在你身上发现了某种潜质，不然也不会让你参加如此神圣的仪式。"
D.Strings[13472]="我知道你对霜脉矮人还缺乏了解，因此我会在路上为你做一些简单的介绍。"
D.Strings[13473]="很多年前，我的父亲和一些霜脉矮人行走在穿越龙骨荒野的艰难归程中。他们遇到了暴风雪……比我们见过的任何一场暴风雪都厉害。"
D.Strings[13474]="沿着雪地上的血迹，他们遇见了一位流浪的矮人。他操着一口难以理解的方言……嗯，因为他不是一般的矮人啊。这个神秘的流浪者自称是高山矮人——我们从未听说过这个氏族。"
D.Strings[13475]="高山矮人似乎迷了路，不记得自己是从哪儿来的，甚至不记得自己的名字。他们不忍心将这位表亲丢在冰天雪地里，于是收留了他，然后踏上了返回冰霜堡的旅途。"
D.Strings[13476]="走着走着，他们面前的雪地突然裂开了，一只像维拉努斯那么大的冰虫袭击了他们……其中一位伙伴还来不及反应，就被整个吞了下去。"
D.Strings[13477]="我的父亲以为大家都难逃此劫……但听背后的雪地里传来一声怒吼，他扭头看见高山矮人的体型正在增大，他的皮肤上浮现出岩石般的纹理，他的手上冒出嘶嘶作响的闪电。"
D.Strings[13478]="高山矮人带着闷雷般的吼声向前冲去，将一把闪亮的金属锤直接掷进了冰虫的喉咙，我的父亲还看见金属锤的表面环绕着闪电。"
D.Strings[13479]="那只冰虫立即倒下了，它的脑袋勉强挂在不断抽搐的躯体上。我的父亲敬畏地注视着高山矮人，举起拳头表示赞美……"
D.Strings[13480]="这位神秘的高山矮人没有名字，于是我的父亲尊称他为“约尔格”，这是传说中的勇士才能享受的称呼。很多年以后，他成为了霜脉矮人熟知的国王——约尔格·雷心。"
D.Strings[13481]="国王对我们进行了严格的训练……让我们成长为可怕的战士。如今的我们，远比当年与冰霜巨人交战时吹嘘的还要厉害。"
D.Strings[13482]="朋友，你最近还好吗？"
D.Strings[13483]="作为霜脉战士最严厉的试炼之一，就是战胜比自己高大许多的敌人，比如巨人、龙或是冰虫——由此证明体型并不是我们的弱点。"
D.Strings[13484]="接受今天的试炼吧。杀死钢铁观察者，再回来见我们，然后你就能成为倍受尊敬的霜脉战士了。"
D.Strings[13485]="我能帮你什么忙吗？"
D.Strings[13486]="冬拥湖之战即将开始！"
D.Strings[13487]="战斗开始！"
D.Strings[13488]="你以为我会放你进来，让你拿走风暴之心吗？"
D.Strings[13489]="哪怕你杀死了瓦杜兰，也无法阻止我铸造巨人。"
D.Strings[13490]="欢迎你，土灵的朋友和盟友。"
D.Strings[13491]="朋友，谢谢你。再见，我必须回到银色前线基地。"
D.Strings[13492]="$r，我允许你进入我们的城堡。$b$b但是，别让我们蒙羞！"
D.Strings[13493]="约库姆国王，如果您不介意的话，能不能告诉我科洛米尔的消息？"
D.Strings[13494]="我对你的信任还不够，抱歉不能将如此重要的信息透露给你。$b$b你必须尊重我们接受的考验以及我们背负的重担……$b$b如果你能为丹尼芬雷带来荣耀的话，我或许会考虑与你分享我们的知识。"
D.Strings[13495]="很好，$c。$b$b虽然你还需要付出更多努力，才能缓解我们与托里姆的关系，但是我决定将这个秘密告诉你。$b$b等你做好了解真相的准备后，再来与我谈话吧。"
D.Strings[13496]="我想知道科洛米尔的命运。"
D.Strings[13497]="这块熊腰肉都冻得发硬了……再试试吧。"
D.Strings[13498]="等等，$r。"
D.Strings[13499]="约库姆国王，是你在召唤我吗？"
D.Strings[13500]="约库姆国王，安格里姆之子，我一直对自己的行为感到后悔。我压抑不住内心的伤痛，深深地伤害了身边的亲人。"
D.Strings[13501]="巫妖王对此次反击迅速做出了反应，竟然比我预想中的还要快。"
D.Strings[13502]="你要对付的有史以来最狡猾、最聪明、最凶狠的生物。"
D.Strings[13503]="巫妖王不同于已往的任何敌人，大领主。虽然你曾在圣光之愿礼拜堂打败过他，但如今，你却身处巫妖王统御下的邪恶王国中。"
D.Strings[13504]="你不可能获胜。照目前的情形，是毫无希望的……"
D.Strings[13505]="达里安，你觉得我应该怎么做？"
D.Strings[13506]="什么也不能。你的能力受到圣光的局限，在这种情况下你什么都做不了。圣光完全控制了你，将你牢牢地束缚在它所能触及的范围之内。"
D.Strings[13507]="说话小心点，死亡骑士。你身边的人都是圣光虔诚的信徒。"
D.Strings[13508]="大领主，认清眼前的局势吧。巫妖王已经彻底封锁了你的前路，占据了上风。"
D.Strings[13509]="蛛魔的巨网将迅速封印你打开的突破口。"
D.Strings[13510]="在回音谷，你的士兵成为了阻挡炮火的肉盾，帮助巫妖王的军队顺利地攻陷了你的营地。"
D.Strings[13511]="巫妖王清楚你心中的底线，大领主。他知道你是不会对自己人开火的。你还不明白吗？对他来说，不谈底线，不讲原则。"
D.Strings[13512]="我们要光明正大地战斗，达里安。不能为了胜利，做出和天灾军团一样的行径。如果我们那么做了，和怪物又有什么差别！"
D.Strings[13513]="那你就输定了，大领主。"
D.Strings[13514]="托里姆！快出来吧！"
D.Strings[13515]="%s受到了黑女巫的拥抱的影响！"
D.Strings[13516]="你修复了钥匙，我对此感激不尽。我保证，你的努力将成就伟大的事业。"
D.Strings[13517]="铁矮人……到处都是……他们冲我们来了。这帮固执的家伙看来是不会放过我们的。"
D.Strings[13518]="他们想要击落飞机！我没法往上攀升……别让他们靠近我们！"
D.Strings[13519]="前面还有更多的铁矮人——坚持！"
D.Strings[13520]="我们就快脱险啦……还差一点。"
D.Strings[13521]="只要别被巨人扔下的石块砸到，我们就很安全……虽然下面已经被砸得一团糟了。"
D.Strings[13522]="他们的数量多得难以置信……好在雷心国王伸出了援手。我听说过他的许多事迹——是时候见见他了。"
D.Strings[13523]="可怜的克莱特乌斯。他是个优秀的守护者……至少他完成了自己的使命。我相信，这件事的重要性对他来说是不言而喻的。"
D.Strings[13524]="我们就快抵达冰霜堡了。如果你能在离开前把我介绍给雷心国王，我会非常感激你的。我们俩都欠他一份情。"
D.Strings[13525]="天啊……这不是……穆拉丁吗？！"
D.Strings[13526]="哥们儿，我怎么会搞错啊——肯定是你。你不认识自己的弟弟了吗？！"
D.Strings[13527]="我真不敢相信自己的眼睛！你不是死了吗？大家都这么认为……到底发生了什么事，穆拉丁。你怎么会在这里？"
D.Strings[13528]="天哪！如果麦格尼见到你，不知道他会高兴成什么样子呢！他已经很久没有听到过好消息了，这次一定能令他欣喜若狂！"
D.Strings[13529]="眼下麦格尼就在诺森德，他是来寻找你的下落的。暮冬城的先知传来消息，说你还活着。于是麦格尼立即离开铁炉堡，来这里找你了。"
D.Strings[13530]="什么？你是在和我说话吗？"
D.Strings[13531]="我的弟弟？呃……我倒是有几个兄弟……"
D.Strings[13532]="穆拉丁抓着脑袋，使劲地晃了晃，一幕幕的往事渐渐涌入他的脑海。"
D.Strings[13533]="……布莱恩？"
D.Strings[13534]="完全不对，$n。在驯风者巴兰告诉我的传说里，雷蹄是个英雄，不是暴徒。"
D.Strings[13535]="我……我不知道，布莱恩。我在这里待了很长时间……但是在此之前的记忆，只剩下支离破碎的噩梦。"
D.Strings[13536]="见到你我还是很高兴的。我真是激动得不知道说什么好了。"
D.Strings[13537]="北风是牦牛人的夙敌。它统治着元素生物，肆意践踏着牦牛人的性命。"
D.Strings[13538]="麦格尼！很抱歉啊，我的记忆恢复得很慢。"
D.Strings[13539]="他们宁愿死，也不愿意臣服于北风。这里出了差错。"
D.Strings[13540]="霜脉矮人对我很好。他们非常强壮。"
D.Strings[13541]="知识之锤……"
D.Strings[13542]="这证实了我们的怀疑。时间流的进程被切断了，历史也被篡改了。这是怎么做到的呢？"
D.Strings[13543]="风暴之王，您的$r仆人做出了超乎寻常的高尚行为。通过努力，$g他:她;已经成功地软化了我的子民的心。"
D.Strings[13544]="托里姆竟然说出过如此谦卑的言辞。我会将你的这番话转达给丹尼芬雷的。"
D.Strings[13545]="我们决定宽恕你在黑暗时代的所作所为。不会再有谁提起那些往事了。"
D.Strings[13546]="作为我们重铸友谊的见证，我就把这东西物归原主吧……"
D.Strings[13547]="我要造一辆攻城车。"
D.Strings[13548]="你好，$r。我能帮你什么忙吗？"
D.Strings[13549]="大爆炸来临时，我的父亲对锤子施放了符文，绝不能让它落入敌人之手。这是他做的最后一件事……"
D.Strings[13550]="我要造一辆投石车。"
D.Strings[13551]="托里姆，希望今后还能与你并肩作战。"
D.Strings[13552]="我必须返回丹尼芬雷了。风暴之王，我相信我们还会见面的。"
D.Strings[13553]="我要造一辆攻城坦克。"
D.Strings[13554]="请求您宽恕我为您和您的子民带来的痛苦和伤害。"
D.Strings[13555]="科洛米尔……谢谢你，约库姆。我都不敢奢望它还完好无损。很快，它将再次见证光辉的战役！"
D.Strings[13556]="你在想什么，孩子？"
D.Strings[13557]="对不起，朋友。只有部落的正式军官才有权购买载具。"
D.Strings[13558]="永歌森林，达尔弗斯。我至今仍然记得，在阿尔萨斯将死亡的气息散播到那片森林之前，她是多么的美丽……"
D.Strings[13559]="是时候阻止洛肯的愚蠢行径了。"
D.Strings[13560]="洛肯！！！"
D.Strings[13561]="来吧，和我交战！你这没用的叛徒！"
D.Strings[13562]="很高兴再次见到你！$B$B雷心国王告诉我，说他会离开一段日子……他回忆起一些可怕的往事，决定算清这笔旧账。他坚持不让我们随行，按照惯例，我们也尊重他的决定。$B$B同时，我负责接管整个氏族。当然，你仍然是我们的贵客。"
D.Strings[13563]="托里姆，急着和你心爱的西芙做伴吗？"
D.Strings[13564]="你竟敢……"
D.Strings[13565]="拉格努斯，我一直觉得你是个人材，不过我的耐心正在逐渐消失。我知道穆拉丁在这里，但是你到底能不能带我找到他？！"
D.Strings[13566]="我的兄弟！真的是你！我几乎不敢相信自己的眼睛……你还活着！"
D.Strings[13567]="能再见到你真是太好了，穆拉丁。我听说你现在登上了王座，真的吗？铜须家族的人注定是要成为大人物的！"
D.Strings[13568]="说起来……"
D.Strings[13569]="似乎的确如此！你看上去还是那么强壮。你还记得发生了什么事吗，穆拉丁？在你离开的日子里，命运愈发糟糕了。"
D.Strings[13570]="我不太记得了，麦格尼。我经常做噩梦，梦见一个人类……很高……浅色的头发……死黑色的盔甲。他的名字……话在嘴边却说不出口……"
D.Strings[13571]="博士委托我执行关于尼尔盖德的计划，那可是完全由瓦古制成的血肉巨人！它将成为最强大的血肉巨人，只要有一整支这样的巨人组成的部队，你们就全都玩完了！"
D.Strings[13572]="……阿尔萨斯。"
D.Strings[13573]="麦格尼点了点头。"
D.Strings[13574]="他不再是你记忆中的男孩了，穆拉丁。他已经完全变了。"
D.Strings[13575]="嗯，我知道。我亲眼目睹了他的转变……我看着他抛弃正义，而我却没有伸出援手……等我意识到事情的严重性时，一切都晚了。"
D.Strings[13576]="那已经是陈年旧事了，穆拉丁。后悔是没有用的。"
D.Strings[13577]="是的……后悔是没用的。但是我能纠正这一切……我必须这么做。我要找到那个孩子，让他为自己的所作所为负责。"
D.Strings[13578]="你是认真的吗，穆拉丁？这些年来，我一直以为你已经死了，现在好不容易才找到你，我不想再失去你。"
D.Strings[13579]="我是认真的，麦格尼。我会小心处理的，别担心。"
D.Strings[13580]="那就这样吧。我要回去了。祝你平安。"
D.Strings[13581]="穆拉丁，保重。我很想与你同行，但是我正在发掘一个足以震惊世界的秘密。我不能半途而废。"
D.Strings[13582]="去吧，布莱恩。下次见面时，你再告诉我这个惊天动地的故事吧。再见，兄弟们。"
D.Strings[13583]="在公平对决的情况下，你似乎有机会战胜我。"
D.Strings[13584]="不幸的是……这场战斗并不公平！"
D.Strings[13585]="这就要感谢你的小朋友了。你离开了风暴神殿，在那里你才能发挥出全部的力量。而现在，我们战斗的地方更靠近主人的力量。"
D.Strings[13586]="谢谢你，朋友。但是我们还没有彻底摆脱危险！"
D.Strings[13587]="我们快离开这儿吧！赶快！"
D.Strings[13588]="直呼……"
D.Strings[13589]="她的名讳！！"
D.Strings[13590]="你是冲着博士的计划来的！你只有死路一条！"
D.Strings[13591]="当你跳上尼尔盖德时，构造体上腐烂的血肉突然活了起来。"
D.Strings[13592]="他们正在策划一场大袭击！我们必须去警告大领主弗丁！"
D.Strings[13593]="快一点，勇士！我们必须赶回银色前线基地，把进攻的事告诉他们！"
D.Strings[13594]="他们有几百人！甚至可能有几千人！他们随时可能发动进攻！我敢肯定！"
D.Strings[13595]="如果你不来的话，我就死定了！"
D.Strings[13596]="凡人，我会考虑饶恕你的性命的。毕竟……我为什么要杀掉最得力的仆从啊？我在海德尼尔矿洞里等了你好几周呢。"
D.Strings[13597]="奴隶们！把我的兄弟和他的飞龙送去他们的新家吧。别伤了那头畜生的性命。我还有个针对她的特别计划呢。"
D.Strings[13598]="……再见，我的兄弟。"
D.Strings[13599]="谢谢你，勇士。"
D.Strings[13600]="%s碎裂开来。"
D.Strings[13601]="这当然不是我的真实相貌。如果你不是那么卤莽的话，你早就看见我过去的幻影了。但是你毕竟帮助我渡过了难关……我必须谢谢你！"
D.Strings[13602]="谁敢？！就算要牺牲尼尔盖德，我也会抓到你，将你的肉一片片地割下来！"
D.Strings[13603]="哦，你好，小$r。"
D.Strings[13604]="你不是牦牛人。你为什么闯入我族战士的埋骨圣地？"
D.Strings[13605]="很抱歉打扰到你，酋长。但是，你的兄弟的灵魂可能遇到了危险。你能把关于他的回忆告诉我吗？"
D.Strings[13606]="我的兄弟雷蹄，是一位比我更出色的战士。在我接受继任氏族酋长的训练时，他正在为一项重要的任务做准备。"
D.Strings[13607]="他怎么会有危险呢？他只是想让我们获得力量，控制那些令我们难以安生的元素生物。"
D.Strings[13608]="他要去找一件神器……一只号角。他离开了村子，踏上了寻找它的漫漫长途。"
D.Strings[13609]="在他夺得号角之后，有个可怕的敌人追上了他……但是，我不记得……后来发生了什么。"
D.Strings[13610]="我的记忆似乎被一层迷雾笼罩了。我甚至不记得我的兄弟后来出了什么事。这就是你所说的危险吗？"
D.Strings[13611]="坟墓在骚动，他们一定被卷进来了。看看你的四周，$n。你看见他们了吗？"
D.Strings[13612]="是的，情况不妙，但是我无力阻止他们。你能向唐卡洛营地发出警告吗，陌生人？告诉他们，历史和他们的祖先正在危险之中。"
D.Strings[13613]="%s落到巢中，发出一声怒吼。"
D.Strings[13614]="小心下面！"
D.Strings[13615]="放松点！不认识你的旧主子了吗？"
D.Strings[13616]="我会在风暴神殿等你。看来我得再降服她一次了。"
D.Strings[13617]="看看他们……他们一心只想超过别人。"
D.Strings[13618]="让我听听你的提议。"
D.Strings[13619]="你看，托里姆和这些鹰身人不同。他是近乎神的存在。$B$B他为泰坦们守护着奥杜尔和造物者圣台。$B$B直到他的妻子西芙被他的兄弟可鄙地杀害了。"
D.Strings[13620]="那后来呢？"
D.Strings[13621]="托里姆失去了理智。他将矛头指向了他的亲密战友，冰霜巨人。$B$B这导致了海德尼尔和霍迪尔之子至今仍在这片土地上互相攻伐……托里姆也因此离开了风暴神殿。"
D.Strings[13622]="你想让我参加海德比武会并结束战争吗？"
D.Strings[13623]="就算这些母狼和冰霜巨人天天对砍，那也不关我的事。$B$B不，不……我是想让托里姆振作起来，召集起所有的盟友夺回奥杜尔。$B$B如果他失败了，这个世界就会破碎的！$B$B当然了，我会支付给你足够的报酬的。"
D.Strings[13624]="很好。我愿意参加这个比赛。"
D.Strings[13625]="我会东山再起的，到时候我会报仇的！"
D.Strings[13626]="让我独自反省吧，$r。"
D.Strings[13627]="男人——很难与他们相处，但是又离不开他们。好吧，也不是离不了……不过那样真的很无聊。"
D.Strings[13628]="这些矿洞真是太可怕了。幸好我不打算在这里待很长时间。"
D.Strings[13629]="熊是美丽的生物。野性、强壮、凶猛……就像我们一样。"
D.Strings[13630]="对不起，朋友。我们手头的零件好象都用完了。"
D.Strings[13631]="蠢货！你赢不了我的！"
D.Strings[13632]="我不会让你用元素愤怒号角来对付我们的！去死吧，懦夫！"
D.Strings[13633]="号角！趁它进入虚弱状态吹响号角！"
D.Strings[13634]="谁在叫我……？"
D.Strings[13635]="起来吧！"
D.Strings[13636]="当%s倒下时，平台上的祭坛开始发出微弱的光芒。"
D.Strings[13637]="喂，喂！"
D.Strings[13638]="你好，伙计——很高兴有你陪在我身边！"
D.Strings[13639]="这片山脉的历史非常悠久……你要随时停下脚步来倾听，$c。"
D.Strings[13640]="我们在龙骨荒野的青铜巨龙圣地发现了这些始祖幼龙。我们立即意识到这是我们的同胞——他们是我们的远古血亲。$B$B很抱歉，$c。我把你说糊涂了吧。我是青铜巨龙圣地的本诺比奥斯。为了方便行事，我变化成了现在的形态。用凡人的形态可以更好地和凡人进行交流，共同生活。$B$B我能帮你什么忙吗？"
D.Strings[13641]="贝索德的剑？！！太好了，$r，我接受你的挑战。但首先，你必须打败我的勇士们。沃尔格！给我碾碎这只爬虫！"
D.Strings[13642]="布莉塔，去把这个卑微的$c打成筛子！"
D.Strings[13643]="你或许可以打败我的勇士们，$c。但我和他们是完全不同的。"
D.Strings[13644]="赶快向你们的诸神祈祷，企求速死吧。"
D.Strings[13645]="你好，$n！今天你想要点什么？"
D.Strings[13646]="伊尔斯卡领主，你接受了公平决斗的挑战，并且输了。"
D.Strings[13647]="你显然还有所欠缺，并将受到制裁。站起来吧，被诅咒的伊尔斯卡领主！"
D.Strings[13648]="说吧，$c。"
D.Strings[13649]="长久以来，我一直不明白自己的命运。我的使命从未像现在这样清晰过。$B$B我必须亲手解决洛肯。"
D.Strings[13650]="你能把西芙的事告诉我吗？"
D.Strings[13651]="刚才那一瞬间，我把你当成了我亲爱的西芙……那一缕头发……不！那不可能……西芙已经死了……$B$B我……我的兄弟……杀了她！"
D.Strings[13652]="他罪行还不止于此，托里姆。他现在控制了奥杜尔。"
D.Strings[13653]="奥杜尔……我曾经发誓要守护奥杜尔。$B$B发誓要守护造物者圣台。$B$B发誓要守护与冰霜巨人之间的盟誓。$B$B可是我都没有做到！我被我的兄弟欺骗了。他诱使我将矛头指向我的朋友。他骗我说是我亲密的朋友，冰霜巨人之王安格里姆害死了西芙。$B$B当我意识到自己做了什么时……我……陷入了绝望。"
D.Strings[13654]="事情或许还有挽回的余地啊。"
D.Strings[13655]="你是谁，小家伙！竟然对强大的托里姆说这些话……$B$B我应该……撕碎你！$B$B但是你将我从昏迷中唤醒了。你的来到是一个预兆！$B$B我把你错当成西芙，这并不是巧合。她会怎么看我呢？我必须准备战斗了。$B$B我一定要为她报仇，把泰坦的圣地从我那个疯狂的兄弟手中解放出来！"
D.Strings[13656]="我会帮助你的，托里姆。"
D.Strings[13657]="随着%s最后的残骸渗入地下，附近的祭坛开始散发出微弱的光芒。"
D.Strings[13658]="不！！！！"
D.Strings[13659]="欢迎来到风暴峭壁，$r。"
D.Strings[13660]="西北方的塔楼遭到破坏！"
D.Strings[13661]="西南方的塔楼遭到破坏！"
D.Strings[13662]="东南方的塔楼遭到破坏！"
D.Strings[13663]="东北方的塔楼遭到破坏！"
D.Strings[13664]="东北方的塔楼被摧毁了！"
D.Strings[13665]="东南方的塔楼被摧毁了！"
D.Strings[13666]="西南方的塔楼被摧毁了！"
D.Strings[13667]="西北方的塔楼被摧毁了！"
D.Strings[13668]="东边的哨塔遭到破坏！"
D.Strings[13669]="南边的哨塔遭到破坏！"
D.Strings[13670]="西边的哨塔遭到破坏！"
D.Strings[13671]="西边的哨塔被摧毁了！"
D.Strings[13672]="南边的哨塔被摧毁了！"
D.Strings[13673]="东边的哨塔被摧毁了！"
D.Strings[13674]="雷吼长者在哪里？"
D.Strings[13675]="雷吼长者在北风苔原的仁德会营地。"
D.Strings[13676]="长者帕姆亚就在战歌要塞外面。"
D.Strings[13677]="长者帕姆亚在哪里？"
D.Strings[13678]="毫无疑问，有东西在干扰雷蹄和唐卡洛战士的真实历史。这究竟是怎么回事呢？"
D.Strings[13679]="别自找麻烦了。无论是雷蹄，还是你和你的盟友，谁都不能阻止我。"
D.Strings[13680]="我的力量在不断增长。我期待已久的复仇之日总算来临了。"
D.Strings[13681]="雷蹄和他的同胞的历史将被抹去，这片土地将回到真正的主人手中！"
D.Strings[13682]="不！真实的历史不容亵渎。我们将恢复被你摧毁的一切！"
D.Strings[13683]="$n，我们必须尽快确定北风是从什么时候开始篡改时间流的。然后我们才有可能打败他并纠正历史。"
D.Strings[13684]="长者伊加苏在哪里？"
D.Strings[13685]="人们最后一次看见长者伊加苏时，他正在探索魔枢。"
D.Strings[13686]="长者诺塔尔在哪里？"
D.Strings[13687]="你可以到考达拉的永生之盾去找长者诺塔尔。"
D.Strings[13688]="长者萨迪斯在哪里？"
D.Strings[13689]="我最后一次听到长者萨迪斯的消息时，他正要前往无畏要塞。"
D.Strings[13690]="蓝狼长者在哪里？"
D.Strings[13691]="蓝狼长者正在参加冬拥湖的战斗。"
D.Strings[13692]="长者瓦尼卡在哪里？"
D.Strings[13693]="长者瓦尼卡在索拉查盆地的雨声河。"
D.Strings[13694]="长者杉德雷在哪里？"
D.Strings[13695]="长者杉德雷到索拉查盆地的湖边着陆场去了。"
D.Strings[13696]="长者墨尔希在哪里？"
D.Strings[13697]="你可以到龙骨荒野的群星之墓去找长者墨尔希。"
D.Strings[13698]="长者索伊姆在哪里？"
D.Strings[13699]="长者索伊姆已经在龙骨荒野的莫亚基港口住了很多年了。"
D.Strings[13700]="天守长者在哪里？"
D.Strings[13701]="天守长者就在龙骨荒野的阿格玛之锤附近。"
D.Strings[13702]="长者努尔根在哪里？"
D.Strings[13703]="根据我最后得到的消息，长者努尔根在艾卓-尼鲁布。"
D.Strings[13704]="长者伍雷恩在哪里？"
D.Strings[13705]="长者伍雷恩在灰熊丘陵的欧尼瓦营地。"
D.Strings[13706]="长者库甘达加在哪里？"
D.Strings[13707]="长者库甘达加在乌特加德之巅。"
D.Strings[13708]="长者卢纳罗在哪里？"
D.Strings[13709]="长者卢纳罗在灰熊丘陵的特塞斯废墟。"
D.Strings[13710]="长者贝尔达在哪里？"
D.Strings[13711]="长者贝尔达在灰熊丘陵的月溪旅营地。"
D.Strings[13712]="长者亚尔特恩在哪里？"
D.Strings[13713]="你能在乌特加德城堡找到长者亚尔特恩。"
D.Strings[13714]="长者基里亚斯在达克萨隆要塞里。"
D.Strings[13715]="长者陶鲁斯在哪里？"
D.Strings[13716]="长者陶鲁斯到祖达克的希姆托加去了。"
D.Strings[13717]="长者奥哈齐在哪里？"
D.Strings[13718]="长者奥哈齐在古达克。"
D.Strings[13719]="灰鬃长者在哪里？"
D.Strings[13720]="最后一次有人看见灰鬃长者时，他在风暴峭壁的K3。"
D.Strings[13721]="长者穆拉克在哪里？"
D.Strings[13722]="长者穆拉克就在风暴峭壁的唐卡洛营地外面。"
D.Strings[13723]="长者法迦尔在哪里？"
D.Strings[13724]="长者法迦尔在风暴峭壁的冰霜堡。"
D.Strings[13725]="石须长者在哪里？"
D.Strings[13726]="石须长者住在风暴峭壁的布德克拉格庇护所。"
D.Strings[13727]="长者尤拉克在哪里？"
D.Strings[13728]="长者尤拉克在岩石大厅里。"
D.Strings[13729]="Mrfrrmrfrmrrr！$B$B<恶鬼清了清喉咙。>$B$B嗯？"
D.Strings[13730]="你还不够强壮，不足以参加远古海滩的战斗。等你经验更丰富一些的时候再来找我吧。"
D.Strings[13731]="我们不能让部落利用远古海滩的秘密来对付我们。你愿意帮助我们在那里战斗的勇士吗？"
D.Strings[13732]="我们不能让联盟利用远古海滩的秘密来对付我们。你愿意帮助我们在那里战斗的勇士吗？"
D.Strings[13733]="沙德隆，帮帮我！一切都危在旦夕！"
D.Strings[13734]="塔尼布隆！你也有保护龙卵的责任！"
D.Strings[13735]="维斯匹隆，情况危急！快来帮助我！"
D.Strings[13736]="%s在注视你！"
D.Strings[13737]="自由啦……呱呱。呱呱……没有找到……我们！逃跑！"
D.Strings[13738]="我……就是……无尽的愤怒！"
D.Strings[13739]="快去干活！现在是时候实施我们的越狱计划了。"
D.Strings[13740]="我获得了……新生。"
D.Strings[13741]="理发师"
D.Strings[13742]="这……就是失败的……代价……"
D.Strings[13743]="缝合场是天灾军团制造食尸鬼、憎恶和血肉巨人的中心。如果我们能摧毁这座工厂，巫妖王的力量就会被大大削弱。"
D.Strings[13744]="岁月的侵蚀令他变得行动迟缓……你只要保持身手敏捷，他是不可能战胜你的。雷心国王在默默地支持你——别让他失望。"
D.Strings[13745]="这真是最好的试炼，阿尔萨斯王子殿下。"
D.Strings[13746]="时间到。"
D.Strings[13747]="你似乎很累了。"
D.Strings[13748]="太简单了。"
D.Strings[13749]="黑暗之王对你的介入很不高兴。"
D.Strings[13750]="我要的是阿尔萨斯王子，不是你！"
D.Strings[13751]="又少了一个障碍。"
D.Strings[13752]="我在做饭呢！"
D.Strings[13753]="又一个饥饿的新兵？"
D.Strings[13754]="你给我带什么来了？"
D.Strings[13755]="%s周围的岩浆沸腾了起来！"
D.Strings[13756]="这些小虫太容易燃烧起来了……"
D.Strings[13757]="我们是托里姆的仆人。"
D.Strings[13758]="你们这可笑的骚扰到此为止了！"
D.Strings[13759]="能在这片被遗弃的土地上见到你这样的英雄，真是令人愉快。我能帮你什么忙吗？"
D.Strings[13760]="很高兴见到你，大德鲁伊。我奉提里奥之命执行一项重要的使命，时间紧迫。你能送我去月光林地吗？"
D.Strings[13761]="当然可以！愿艾露恩祝福你。"
D.Strings[13762]="朋友，今天是巨魔历史上黑暗的一天。"
D.Strings[13763]="没有你的帮助，我们很难取得胜利。"
D.Strings[13764]="瞧，前线基地的英雄！"
D.Strings[13765]="你是我们的荣耀，$n。"
D.Strings[13766]="谢谢，$n。衷心地感谢你。"
D.Strings[13767]="随时为你效劳，$n。"
D.Strings[13768]="为了后世的幸福，我有责任记录下这些悲剧。"
D.Strings[13769]="我们不能放松警惕。在这种时候，一次小小的失利就可能令我们置身于危险中。唉，这种高度紧张的气氛下，士兵们真的需要喘口气了。$B$B享受胜利吧，$n。如果没有你，我们可能已经失去前线基地了。"
D.Strings[13770]="总算盼来了援军！面对如此大规模的入侵，监狱守卫是坚持不了多久的！请你前去增援我的士兵，尽量为我们争取时间吧。防御系统的能量尚未用尽。如果情况危急的话，务必要激活监狱周围的水晶发射能量波。"
D.Strings[13771]="我的职责是保护这些龙卵。在伤害到它们之前，你们就会被我的龙息烧成灰烬！"
D.Strings[13772]="遇到麻烦时就激活水晶。"
D.Strings[13773]="联盟守住了冬拥堡垒！"
D.Strings[13774]="部落守住了冬拥堡垒！"
D.Strings[13775]="我是父亲最优秀的儿子！你们的末日来临了！"
D.Strings[13776]="来呀！出招吧！"
D.Strings[13777]="接招吧，让你看看我的厉害！"
D.Strings[13778]="啊啊啊啊啊！见识见识钢与铁的愤怒吧！"
D.Strings[13779]="让我结束你的诅咒吧。"
D.Strings[13780]="血肉……是……脆弱的！"
D.Strings[13781]="怎么可能……？血肉之躯竟强过了……钢铁！"
D.Strings[13782]="就是你们杀死了我那么的多孩子吗？你们……要付出代价！"
D.Strings[13783]="腐化而成的血肉生物……死吧。"
D.Strings[13784]="一切都不会被浪费的。看着吧……"
D.Strings[13785]="我要把你们踩在脚下，彻底碾碎！"
D.Strings[13786]="我的工作……还没结束！"
D.Strings[13787]="钢铁的大军将征服一切！"
D.Strings[13788]="呸！可怜虫！"
D.Strings[13789]="你们的确让我费了不少力气！"
D.Strings[13790]="主人……果然……深谋远虑。"
D.Strings[13791]="你和你的伙伴们都准备好了吗？我会激活水晶，发射能量波，让我的守卫趁机撤退。"
D.Strings[13792]="让他们放心撤离吧，我们会竭尽全力牵制蓝龙军团的入侵。"
D.Strings[13793]="连天灾军团都被我们击败了，你们以为自己能有几分胜算？"
D.Strings[13794]="来应付更“大”的挑战吧！"
D.Strings[13795]="大地要将你们吞噬！"
D.Strings[13796]="看我踩碎你们这些蟑螂！"
D.Strings[13797]="谁能阻止我？就凭你？"
D.Strings[13798]="怎么，这就不行了？"
D.Strings[13799]="神都会死去……何况我们自身……"
D.Strings[13800]="我为银色北伐军所做的一切只是为了履行义务。当然，也算是报恩吧。大领主让我摆脱了巫妖王的控制并为我们指明了救赎之路。我说过，我们做事的方式是有差异的——你必须明白这一点。我和黑锋骑士团会竭尽全力，帮助银色北伐军在冰冠冰川站稳脚跟。在那之后，我们就会离开。我希望能以这样的方式报答大领主的恩情。$B$B等待我们的，将是截然不同的命运。"
D.Strings[13801]="毫无疑问，和这些北伐军将士相处起来别提有多别扭了。但是不承担痛苦的话，算什么牺牲呢？你曾经与我共同经历了圣光之愿礼拜堂一战，目睹过许多伟大的牺牲。我们是来这里报答大领主的，报答他所做出的牺牲。$B$B一旦银色北伐军在冰冠冰川的高墙内站稳脚跟，我们就会离开。等待我们的，将是截然不同的命运。"
D.Strings[13802]="尊贵的主人。"
D.Strings[13803]="这……是哪里？我……我要……消灭你们！"
D.Strings[13804]="你去死吧！这是主人的命令。"
D.Strings[13805]="真是简单的工作！"
D.Strings[13806]="什么样的狗杂种竟然胆敢入侵这里？快点，弟兄们！谁要是能把他们的头提来，就赏他吃肉！"
D.Strings[13807]="你想要挑战死亡本身吗？来吧，“王”。面对莫格莱尼的怒火！"
D.Strings[13808]="我会在回音谷等你。朋友，坚持住。"
D.Strings[13809]="你这只无能的蠢龙！你的尸体干脆给我的新飞龙拿去当点心算了！"
D.Strings[13810]="你现在怎么不那么嚣张了啊？"
D.Strings[13811]="我要让你尝尝我的厉害！"
D.Strings[13812]="啊啊！这也能叫……攻击？我要……让你们……见识见识……啊啊啊……"
D.Strings[13813]="你们不仅侵入我的家园，还有胆来挑战我？我要把你们的徽记拿来作为礼物献祭给伟大的死神！Rualg nja gaborr！"
D.Strings[13814]="黑色风暴之王布约恩！应我的召唤前来协助我！"
D.Strings[13815]="岩石峭壁之王赫尔多！把你的力量借给我！"
D.Strings[13816]="恐怖深渊之王拉努夫！以漆黑的深夜吞噬这群蝼蚁！"
D.Strings[13817]="野蛮杀戮之王托尔，将你的威能赐予我！"
D.Strings[13818]="你的死亡仅仅是个开始！"
D.Strings[13819]="你让你的人民失望了！"
D.Strings[13820]="这就是我能加冕为王的理由！"
D.Strings[13821]="就此咽气吧！"
D.Strings[13822]="又……又有什么……在等着我呢？"
D.Strings[13823]="监狱守卫们，准备撤退了！这些冒险者将接管这里的防御事务！迅速撤离！"
D.Strings[13824]="我要锁上大门了。祝你们好运，感谢你们的帮助。"
D.Strings[13825]="尤顿海姆传来消息，据说那里的沉睡卫士发现了一位重要人物。"
D.Strings[13826]="教徒激动得语无伦次。"
D.Strings[13827]="模样？他就是个维库人。呃，其实我并没有见过他本人。自从暗影拱顶……"
D.Strings[13828]="名字？对，他的名字！我记得是叫伊斯卡德尔。"
D.Strings[13829]="汇报情况吧。"
D.Strings[13830]="描述一下这名维库人吧。他长什么模样？"
D.Strings[13831]="我没兴趣听你找借口。他们总该告诉过你他的名字吧。"
D.Strings[13832]="伊斯卡德尔？！蠢货！你没听过他的名头吗？他是有史以来最伟大的维库人战士！"
D.Strings[13833]="立即返回尤顿海姆，告诉他们，在我抵达之前不准让他苏醒过来。我要亲眼看看这个维库人。"
D.Strings[13834]="来，和我的小伙伴打声招呼吧！"
D.Strings[13835]="现身吧，熔尸！"
D.Strings[13836]="这里没我们的事了。我走了。"
D.Strings[13837]="连这样的场面都应付不了，你还真够弱的。好吧……"
D.Strings[13838]="在我离开之前，你还需要什么帮助吗？好吧，我不认为……"
D.Strings[13839]="远古的魔法在眼睛深处旋转，令你感到一阵眩晕，仿佛自己被吸入了虹膜之中并永远地陷落了。"
D.Strings[13840]="紧握巫妖王之眼并集中你的意志，以此获取重要的信息。"
D.Strings[13841]="你观察着貌似平静的冰冠冰川，突然发现了有趣的景象……"
D.Strings[13842]="开始对创世神殿进行分析。"
D.Strings[13843]="创世神殿完好无损。"
D.Strings[13844]="机械仆人之间似乎发生了内讧。部分机械侏儒随从被随意地堆放在一起。"
D.Strings[13845]="某种未知的力量摧毁了剩余的机械侏儒守卫。"
D.Strings[13846]="未发现守护者米米尔。分析完毕。"
D.Strings[13847]="维库人安详地沉睡着。"
D.Strings[13848]="开始对寒冬神殿进行分析。"
D.Strings[13849]="叫醒休眠的尤尔丁人，确认他是不是远古英雄伊斯卡德尔。"
D.Strings[13850]="寒冬神殿完好无损。"
D.Strings[13851]="神殿守卫者已经死亡。弥漫神殿的硫磺气味表明他是被某种火焰生物杀死的。"
D.Strings[13852]="神殿之前设定的寒冷气候模式已终止。"
D.Strings[13853]="未发现守护者霍迪尔。分析完毕。"
D.Strings[13854]="未发现守护者弗蕾亚。分析完毕。"
D.Strings[13855]="生命神殿遭到破坏，无法修复。"
D.Strings[13856]="种种迹象表明神殿曾发生过激战。估计守护者弗蕾亚的对手在体型和力量上都与她不相上下。"
D.Strings[13857]="未发现神殿守护者。与神殿伴生的植物形态已经死亡。"
D.Strings[13858]="开始对生命神殿进行分析。"
D.Strings[13859]="开始对秩序神殿进行分析。"
D.Strings[13860]="秩序神殿完好无损。"
D.Strings[13861]="未发现战斗迹象。未发现神殿守护者。"
D.Strings[13862]="未发现守护者提尔。分析完毕。"
D.Strings[13863]="<嗝儿>$b$b没有同伴，真是孤单呐。"
D.Strings[13864]="对了！你去给他们点颜色瞧瞧！$b$b<嗝儿>"
D.Strings[13865]="该喝点双份朗姆酒啦！$b$b哎呀，我的酒快喝光了……"
D.Strings[13866]="伊斯卡德尔，你总算露面了。怎么？你已经开始战斗了吗？"
D.Strings[13867]="天哪！这怎么可能？"
D.Strings[13868]="我不明白怎么会这样，但是你一定是伊斯卡德尔。等等……怎么回事？"
D.Strings[13869]="怎么回事？你被我控制了！我是来复仇的！"
D.Strings[13870]="滚远点！别碰我！"
D.Strings[13871]="哈哈哈哈！好啦。回到我待的洞穴去吧。我们还有很多要事要商量呢。"
D.Strings[13872]="北伐军的神圣军旗已经插好了。\n保护旗帜，击退攻击者！"
D.Strings[13873]="来战，$n！杀死伊斯卡德尔！"
D.Strings[13874]="卡塔莉娜·斯坦弗就在监狱西南方的运河边。"
D.Strings[13875]="耶利尼克的理发店就在贸易区的北部。"
D.Strings[13876]="你来了！我刚刚找出开启这扇门的方法。你准备好之后就告诉我，我来打开它！"
D.Strings[13877]="来吧，布莱恩！打开它！"
D.Strings[13878]="艾莉丝·布莱里特就在飞行管理员旁边的大锻炉附近。"
D.Strings[13879]="理发店就在平民区的西部。"
D.Strings[13880]="啧啧。你犯下了如此可怕的错误，是不是感觉很自豪啊？"
D.Strings[13881]="我本来就打算销毁他，看来可以提前完成了。"
D.Strings[13882]="芬迪·达金就在工匠区中央的第二层。"
D.Strings[13883]="哎呀，这些质量上等，可以重复利用的零件都要报废啦……真是可惜……"
D.Strings[13884]="补丁再也不想被随意地切开或是缝合了！"
D.Strings[13885]="嘿！别担心！老布莱恩在后面给你们加油呢！把这些该死的金属疙瘩给我挡住，让我来好好跟这台可爱的大机器谈谈，让它帮帮你们！"
D.Strings[13886]="补丁要向萨布诺克博士复仇！"
D.Strings[13887]="水晶大厅的索斯能教你铭文技能。"
D.Strings[13888]="犹尔曼就在暗巷区二层的某座建筑物内。"
D.Strings[13889]="理发师？她已经把理发店搬出暗影裂口，挪到力量谷上方的悬崖中去了。就是原来开水果店的那个地方。"
D.Strings[13890]="天啊！该死的怪物！看看它们对我们的人民做了些什么！"
D.Strings[13891]="烧死它们。烧毁这一切。"
D.Strings[13892]="来吧。让它们为此付出代价！"
D.Strings[13893]="玛尔迦·帕克雷就在炼金房，她是一位漂亮的女士。"
D.Strings[13894]="理发师纳兹尼克在贸易区的上层，紧邻银行。"
D.Strings[13895]="波什金·哈比德尔在灵魂高地下的预见之池。"
D.Strings[13896]="赞塔希娅在逐日王庭。"
D.Strings[13897]="面对我的恐怖造物，颤抖吧！"
D.Strings[13898]="仆从们，把他们都消灭！"
D.Strings[13899]="放下武器，交出你们的灵魂！"
D.Strings[13900]="毁灭。"
D.Strings[13901]="成功啦！我们从天灾军团手中夺得了北伐军之峰！立刻向古斯塔夫神父汇报这一好消息！我们要立即展开建设工事！快！"
D.Strings[13902]="了解……我的……痛苦。"
D.Strings[13903]="凝视……虚空。"
D.Strings[13904]="更多的……能量。"
D.Strings[13905]="放弃吧。"
D.Strings[13906]="坠入……黑暗。"
D.Strings[13907]="消散。"
D.Strings[13908]="面对如此大规模的危机，我要如何应对？"
D.Strings[13909]="所有人都病倒了——这是天灾！"
D.Strings[13910]="药物根本不起作用——整座城市在痛苦中呻吟。"
D.Strings[13911]="关于变质粮食的传闻在士兵之间流传，恐慌正在蔓延。市民们互相指责邻居就是投毒者。城市已经陷入骚乱。"
D.Strings[13912]="我完全不知所措。面对这样的灾难，我又能做些什么呢？"
D.Strings[13913]="我发誓，我的不适感源于焦虑……"
D.Strings[13914]="由于唤醒的方式不当，维库人死亡了。"
D.Strings[13915]="由于唤醒仪式受到了干扰，维库人死亡了。"
D.Strings[13916]="由于唤醒魔棒的使用不当，沉睡中的维库人死亡了。"
D.Strings[13917]="占领北伐军之峰只是第一步，我们的事业漫长而危险。要攻陷冰冠冰川，要做的事情还有很多。$B$B只有在像你这样的勇士的帮助下，我们才有可能取得胜利。"
D.Strings[13918]="欢迎来到达拉然，$c。"
D.Strings[13919]="我准备好飞往索拉查盆地了。"
D.Strings[13920]="他就快到了！"
D.Strings[13921]="我弄丢了博学者的罩衫。"
D.Strings[13922]="你胆敢挑战我？你还不够资格呢！"
D.Strings[13923]="不，大领主巴拉加德。你必须接受挑战！"
D.Strings[13924]="瓦尔德玛达？！巫妖王亲自派你来的？"
D.Strings[13925]="好吧。我会解决掉这些生物。不过是小小的麻烦罢了。准备受死吧！"
D.Strings[13926]="萨菲德拉，让他们感受到来自冰冠冰川的寒意吧！"
D.Strings[13927]="我把探索者战袍弄丢了。"
D.Strings[13928]="立即返回布伦希尔达村！"
D.Strings[13929]="给我的？"
D.Strings[13930]="礼物？"
D.Strings[13931]="干嘛给我炸弹？"
D.Strings[13932]="是要我送到什么地方去吗？"
D.Strings[13933]="恐怕不太安全吧，小恶鬼。"
D.Strings[13934]="这个不应该放在这儿。"
D.Strings[13935]="小恶鬼想要什么啊？"
D.Strings[13936]="那样可不太好！"
D.Strings[13937]="破天号将开往冰冠冰川。世界上找不到比它更好的飞船啦。"
D.Strings[13938]="请送我上船。"
D.Strings[13939]="奥格瑞姆之锤即将开往冰冠冰川。你找不到比它更好的船只啦。"
D.Strings[13940]="住手！快跪下！蠢货，这可是巫妖王！"
D.Strings[13941]="愿荣耀与你同在。"
D.Strings[13942]="瓦尔德玛达。我还以为你失踪了呢。伊斯卡德尔呢？"
D.Strings[13943]="陛下。"
D.Strings[13944]="奈丝伍德夫人，我能看穿你的伪装。你以为这点小把戏就能愚弄我吗？！"
D.Strings[13945]="但是……！"
D.Strings[13946]="你可以继续战斗了，领主。"
D.Strings[13947]="陛下，但是……？"
D.Strings[13948]="但是什么！杀了他们！别让我失望，BALARGARDE！"
D.Strings[13949]="<大领主达里安·莫格莱尼点了点头。>"
D.Strings[13950]="我要接受训练，大领主。"
D.Strings[13951]="你还活着只是因为我比较好奇。"
D.Strings[13952]="让我们看看入口附近的大门后面藏着什么。我会悄悄地潜过去。去那里和我碰面吧，我会带你们进去吧。"
D.Strings[13953]="血红色的液体在眼睛里漩流，显现出天灾军团大军的影像。它似乎在拉扯着你，企图侵入你的思想。你本能地抗拒着眼睛的影响，觉得心神不宁。"
D.Strings[13954]="怪物！"
D.Strings[13955]="可耻的叛徒！"
D.Strings[13956]="天灾军团杀死了我的家人！怪物！"
D.Strings[13957]="%s向$n扔烂苹果。"
D.Strings[13958]="%s向$n扔烂香蕉。"
D.Strings[13959]="%s对$n吐口水。"
D.Strings[13960]="你有什么需要，尽快开口吧。"
D.Strings[13961]="凶手！"
D.Strings[13962]="恶心的家伙。"
D.Strings[13963]="这简直是引狼入室的行为。"
D.Strings[13964]="你竟敢踏进我们的城市！"
D.Strings[13965]="你击败了我忠诚的奴仆，但是你付出的努力是徒劳的。"
D.Strings[13966]="你成功啦！你击退了蓝龙军团，并杀死了他们的指挥官。这真是个奇迹！"
D.Strings[13967]="冰冠冰川的霜寒之心在等待……"
D.Strings[13968]="这里就交给我们吧。在那场战斗之后，你已经赢得了大家的尊重。"
D.Strings[13969]="你！到前面来！"
D.Strings[13970]="尤格-萨隆！赐予我力量吧！"
D.Strings[13971]="主人，这是奉献给您的礼物！"
D.Strings[13972]="荣耀归于尤格-萨隆！"
D.Strings[13973]="你毫无价值。"
D.Strings[13974]="起来！你受的痛苦还远远不够呢。"
D.Strings[13975]="别以为你们亵渎了这里……还能安然无恙。"
D.Strings[13976]="元素之力必将崛起，夺回这个被文明玷污的世界！只有最虔诚的信徒才能幸免于难！"
D.Strings[13977]="只要将全部身心都献给伟大的尤格-萨隆，就连你们也可以获得不朽的生命！"
D.Strings[13978]="在这里，在最靠近他领地的地方，你可以亲身体会到这强大得无以复加的力量！"
D.Strings[13979]="你经历了长途跋涉和艰难险阻来到这里！你应为你的执着而得到奖励。"
D.Strings[13980]="信徒们，你们有理由高兴与欢呼，但我们仍有许多未尽的事业。在整个艾泽拉斯都被他的阴影笼罩之前，我们还要继续努力！"
D.Strings[13981]="一切胆敢践踏这片土地的入侵者都将被达卡莱巨魔消灭！"
D.Strings[13982]="你没气了？很好！"
D.Strings[13983]="害怕了吧？"
D.Strings[13984]="我下一个就要吃你！"
D.Strings[13985]="我明白了……天灾军团……并不是我们最大的敌人……"
D.Strings[13986]="你好。弗拉斯·希亚比现在不在。明天再来光顾希亚比的烟草店吧！哔哔！"
D.Strings[13987]="真是一群英勇的卫兵，但这座城市必须被夷平。我要亲自执行玛里苟斯大人的指令！"
D.Strings[13988]="<利用眼睛控制一只幻象观察者。>"
D.Strings[13989]="让我们来做个了断吧，肯瑞托的勇士们！"
D.Strings[13990]="我要终结肯瑞托！"
D.Strings[13991]="达拉然即将沦陷！"
D.Strings[13992]="你对织法者的冒犯到此为止了。"
D.Strings[13993]="或许……我们……低估了……你们。"
D.Strings[13994]="在东瘟疫之地的圣光之愿礼拜堂，银色黎明指挥着对抗天灾军团的战斗。去那里接受命令吧。"
D.Strings[13995]="有谁能在我的力量面前屹立不倒？"
D.Strings[13996]="我很可能会在眨眼之间把你劈成两半，$r！$B$B如果你说完了废话，最好趁早滚开！"
D.Strings[13997]="瓦哈拉斯是你抉择生死之地，$n。在任何情况下，你都不能擅自退出比武场。如果你选择逃跑，就意味着你可耻地输掉了比赛。"
D.Strings[13998]="$n和$g他:她;的战友被选中，将在神圣的瓦哈拉斯进行光荣的战斗。"
D.Strings[13999]="瓦哈拉斯的战斗只有一个结果：必须有一方倒下。$n，如果你想要证明自己的力量，就必须将对手的尸体踩在脚下！"
D.Strings[14000]="你们这是自寻死路！"
D.Strings[14001]="$n战胜了瓦哈拉斯的英雄之魂。虽然这仅仅是一场热身赛，但是也算是精彩的对决吧。"
D.Strings[14002]="瓦哈拉斯的英雄之魂现身了，准备再次投入战斗！"
D.Strings[14003]="你还没有获得参与瓦哈拉斯比武赛的资格，$n。$B$B等你小有名气之后再到这里来吧。"
D.Strings[14004]="许多人都死在了瓦哈拉斯，他们的尸体见证了比武场的残酷。$B$B$n，你的骸骨是否也会留在荣耀与血腥的战场呢？"
D.Strings[14005]="低等生物，竟敢入侵这里！可惜你们过度膨胀的勇气，无法挽救愚蠢所导致的悲惨结局！"
D.Strings[14006]="这里除了蓝龙军团，没有人可以进来。看来是阿莱克丝塔萨在搞鬼？很好，她实际上是派你们来送死的！"
D.Strings[14007]="你们以为自己能做些什么呢？自大地在我的领域横冲直撞，用毁灭性的魔法来对付……我？"
D.Strings[14008]="我在这里不受任何约束。那些你们必须遵循的法则对我无效。在这个领域之中，我就是一切！"
D.Strings[14009]="我给你们一次机会吧。向我宣誓效忠，这是让我原谅你们的傲慢与无礼的唯一机会。"
D.Strings[14010]="我的耐心到此为止了。我要亲自消灭你们！"
D.Strings[14011]="没有人体验过你们将要承受的痛苦！"
D.Strings[14012]="你们的愚蠢必将葬送自己！"
D.Strings[14013]="又有更多的神器可以没收了。"
D.Strings[14014]="太天真了！"
D.Strings[14015]="$n接受了黑暗主宰西塔利克斯的挑战。西塔利克斯绝不会手下留情的，愿诸神保佑$g他:她;吧。"
D.Strings[14016]="做好准备吧。西塔利克斯将从东南方进入瓦哈拉斯。记住，不要离开比武场，否则你就会输掉比赛。"
D.Strings[14017]="我原本只是想尽快结束你们的生命……可你们竟然远比我想象得要坚韧。虽然如此，你们的努力仍将付诸东流。事实上，这场战争本身就是因为你们凡人不计后果的行为而起，我只是在尽自己的责任罢了。如果这责任意味着要灭绝你们……那就这样吧！"
D.Strings[14018]="我要让你们这些无知的孩子重新了解魔法的概念。"
D.Strings[14019]="就这样无助地看着希望破灭吧！"
D.Strings[14020]="我会妥善利用你们留下的魔法能量。"
D.Strings[14021]="我是织法者！我的力量是无穷无尽的！"
D.Strings[14022]="你们的灵魂将永远在这里游荡！"
D.Strings[14023]="够了！既然你们这么想夺回艾泽拉斯的魔法，我就给你们！"
D.Strings[14024]="现在你们幕后的主使终于出现了，但已经太迟了！这里弥漫着的能量已经足以将世界毁灭十次。你们觉得他们会对你们做些什么呢？"
D.Strings[14025]="投降吧！"
D.Strings[14026]="在我的龙息之下，一切都将荡然无存！"
D.Strings[14027]="在这里涌动的力量早已超越了你们的理解与想象！"
D.Strings[14028]="我无坚不摧！"
D.Strings[14029]="阿莱克丝塔萨，又有一个你的孩子倒下了！"
D.Strings[14030]="就比小虫子强了一点点！"
D.Strings[14031]="红龙军团也将步你们的后尘！"
D.Strings[14032]="竟然还没倒下？不会太久了。"
D.Strings[14033]="你们的妄想破灭了！"
D.Strings[14034]="你们脆弱的精神即将崩溃！"
D.Strings[14035]="不可思议！这群凡人……竟然毁灭了一切！我的妹妹，你都做了些……什么？"
D.Strings[14036]="绝不能释放这些囚犯！玛里苟斯的话就是律法！"
D.Strings[14037]="颤抖吧，蠕虫！"
D.Strings[14038]="会飞么？"
D.Strings[14039]="现在逃跑已经太晚了！"
D.Strings[14040]="都给我过来……"
D.Strings[14041]="谁也别想逃跑！"
D.Strings[14042]="我判处你们死刑！"
D.Strings[14043]="多么恰当的惩罚。"
D.Strings[14044]="行刑！"
D.Strings[14045]="又一个战争的牺牲品。"
D.Strings[14046]="战争……还会继续的。"
D.Strings[14047]="看来我的自由必须用鲜血去换取了！"
D.Strings[14048]="采之不尽，用之不竭的资源……我必须要得到它！"
D.Strings[14049]="看来我们有必要重新交涉一次。"
D.Strings[14050]="我们其实没有个人恩怨。"
D.Strings[14051]="纯粹是为利益而已。"
D.Strings[14052]="利益！"
D.Strings[14053]="这真是个……不可挽回的……损失。"
D.Strings[14054]="入侵者，你们一路的胜势到此为止了。我是指挥官瓦尔洛斯。我和飞龙们制御着这里的天空，保护着这里的管线，也将保证魔枢之眼不会落入你们的手中！"
D.Strings[14055]="我是不会心慈手软的！"
D.Strings[14056]="炸死他们！摧毁他们！"
D.Strings[14057]="他们……咳……太强大！我低估了……他们的顽强。"
D.Strings[14058]="$n和$g他:她;的战友击败了黑暗主宰西塔利克斯。下一场挑战马上开始！"
D.Strings[14059]="不要……呱呱……挡我……呱呱……去路！"
D.Strings[14060]="咔咔咔！"
D.Strings[14061]="宝贵的生命……呱呱……浪费了！"
D.Strings[14062]="强大的人……呱呱……才能活下去！"
D.Strings[14063]="没……呱……逃掉……"
D.Strings[14064]="感谢圣光再次赐予我机会。同样谢谢你，$n。"
D.Strings[14065]="要不是你，我早就沦为巫妖王的奴仆，成为天灾军团中的一员了。"
D.Strings[14066]="稍后我会正式地感谢你，但是现在我们还有一场仗要打！"
D.Strings[14067]="稍微见识见识吧……见识一下织法者的真正力量！"
D.Strings[14068]="这么多不稳定的能量……但为了消灭你们，这点风险不算什么！"
D.Strings[14069]="如果你能早点理解就好了！"
D.Strings[14070]="你明白了吗？明白了吗？！"
D.Strings[14071]="真不幸，但这是必要的。"
D.Strings[14072]="我所做的一切……都是为了艾泽拉斯……"
D.Strings[14073]="我就知道你会来的。"
D.Strings[14074]="战斗结束后，我就要把你们的徽记挂在艾卓-尼鲁布的城墙上！"
D.Strings[14075]="蠢货！你们根本无法理解这种你们正在对抗着的伟大力量。魔网能量的传输是不会被你们干扰的！而你们，唯一的结局只有失败与死亡！"
D.Strings[14076]="刚才的战斗给我留下了深刻的印象。"
D.Strings[14077]="打得不错……"
D.Strings[14078]="欢迎来到亡者的世界。"
D.Strings[14079]="你们这些莽撞的入侵者已经无计可施了！我要亲自把你们碾碎！"
D.Strings[14080]="如此肆意妄为，如此骄纵轻狂……必须惩罚你们！"
D.Strings[14081]="自然魔法现在帮不了你们啦！"
D.Strings[14082]="奥术魔法归我们号令！休想用它来对付我们！"
D.Strings[14083]="熄灭你们的小火苗，完全没有难度！"
D.Strings[14084]="这可要很久才能落地的……"
D.Strings[14085]="回到尘土中去！"
D.Strings[14086]="好好享受坠落的快感！"
D.Strings[14087]="好好珍惜这场胜利吧，愚蠢的低等动物。你们和你们的龙类盟友或许赢得了这次战役，但我们……才是整个魔枢战争的胜利者。"
D.Strings[14088]="啊，是你！还记得我吗？我相信你记得！等着吧，我这就下来。"
D.Strings[14089]="我说过，下次见面时，我会做好充分的准备。我取得了海德比武会的胜利，在瓦基里安接受了严酷的训练。今非昔比，尝尝我的厉害吧！"
D.Strings[14090]="深渊的秘密，就永远留在深渊之中吧。"
D.Strings[14091]="卡纳基来啦！记住，在任何情况下，都不能离开比武场，否则就取消你们的参赛资格。"
D.Strings[14092]="幼体可千万不能饿着了……"
D.Strings[14093]="在寒冷的黑暗中长眠吧……"
D.Strings[14094]="为了巫妖王！"
D.Strings[14095]="或许你很快就要成为我的盟友啦。"
D.Strings[14096]="主人……我的使命……结束了吗？"
D.Strings[14097]="齐格莉德·冰魂已经重返尤顿海姆，她将与$n展开对决。他们上次交手时，$n战胜了她。这场比赛的胜负如何呢？让我们拭目以待吧！"
D.Strings[14098]="我……呱呱……最喜欢的！哇哇哇！呱呱！"
D.Strings[14099]="一只安卡哈守护者孵化了！"
D.Strings[14100]="我要吞噬你们的尸体！"
D.Strings[14101]="你的心跳在我耳中就是最美妙的音乐。"
D.Strings[14102]="我在，我亦不在。我就是那无形无迹的监视者。"
D.Strings[14103]="不错的开胃菜。"
D.Strings[14104]="新鲜的肉，温暖的血……好久没有尝到了。"
D.Strings[14105]="我已经很久没有痛饮过鲜血了。"
D.Strings[14106]="最后的……拥抱。"
D.Strings[14107]="我依然这么饿。我依然……这么……渴。"
D.Strings[14108]="你们烧焦的骨头正好可以用来装饰地板！"
D.Strings[14109]="你们能承受多高的温度呢？"
D.Strings[14110]="一切都将化为灰烬！"
D.Strings[14111]="燃烧吧，你们这些可怜虫！"
D.Strings[14112]="你或许会是孩子们最好的晚餐。"
D.Strings[14113]="你们真是占尽了下风。"
D.Strings[14114]="这就是你们被称为低等生物的原因！"
D.Strings[14115]="$n再次击败了齐格莉德·冰魂。好吧，虽然$g他:她;是在队友的帮助下获胜的，但是胜利就是胜利！"
D.Strings[14116]="卡纳基来自曲径幽深的地下大厅。勇敢又愚蠢的$n已经接受了这个挑战。$G他:她;将率领自己的队伍面对这个怪物。"
D.Strings[14117]="可怕的卡纳基已经不复存在啦。$n真的配得上瓦哈拉斯的战斗吗？让我们拭目以待吧。"
D.Strings[14118]="呃……别……别管我。$b$b我……没救了……"
D.Strings[14119]="收集……天灾军团的……情报。$b$b联盟的军队出现了……$b$b我们躲了起来，接着他们开始攻打大门……然后我们从背后发动了袭击。$b$b三方展开了混战……但是天灾军团……数量太多了……$b$b我的$g兄弟:姐妹;……那真是一场……荣耀的战斗。"
D.Strings[14120]="坚持住，朋友。告诉我究竟发生了什么事。"
D.Strings[14121]="够了！你们这些爬虫不配在这片圣地上战斗！你们的战斗毫无荣誉可言！你们别想战胜我！"
D.Strings[14122]="来受死吧，懦夫！"
D.Strings[14123]="往东南方看，领主很快就会出现在残忍的亚纳尔附近的平台上。等他自己下来。不要离开瓦哈拉斯的竞技场。"
D.Strings[14124]="数个世纪后，巴纳霍格领主首次重返瓦哈拉斯。他要证明，只有维库人才有资格在这片圣地上战斗。$n能证明他错了吗？"
D.Strings[14125]="巴纳霍格领主败在了$n和$g他:她;的战友手下。挑战者即将迎来最后一场对决。他们的对手是谁呢？"
D.Strings[14126]="$n，在我最需要帮助的时候，是圣光的赐福让你找到了我。"
D.Strings[14127]="我受够这个鬼地方了。我们走吧。"
D.Strings[14128]="谢谢你救了我。回去之后，我一定会向大家宣扬你的勇敢。请你竭尽所能，与天灾军团抗衡吧。我们会帮助你的。"
D.Strings[14129]="请转告我的兄弟，我还活着。"
D.Strings[14130]="难以置信啊……$n杀死了萨杜瓦尔王子！"
D.Strings[14131]="挑战者击败了王子，这证明$g他:她;及其战友完全有资格在维库人的圣地上战斗！"
D.Strings[14132]="审判之日即将来临。你深知正义才是唯一正确的道路。"
D.Strings[14133]="向$n，瓦哈拉斯的勇士欢呼吧！"
D.Strings[14134]="现在逃跑已经太迟啦。不要离开比武场。慷慨地赴死吧，$n！"
D.Strings[14135]="挑战者的对手来自冰冠堡垒，这位被巫妖王选中的勇士是来终结$n及其战友的生命的。"
D.Strings[14136]="尤顿海姆的战士们，他就是血精灵王子萨杜瓦尔！"
D.Strings[14137]="亲爱的，你的介绍可不怎么得体。那么，这位声名大噪的挑战者是谁呢？"
D.Strings[14138]="我会尽量让你死个痛快的。过来受死吧。你侵犯并玷污了这座神圣的比武场，而我只要求你用性命赎罪罢了。"
D.Strings[14139]="哎呀，黑锋骑士团派人来杀我了。我害怕得发抖啊。"
D.Strings[14140]="我为部落……奉献了一切……"
D.Strings[14141]="哈！你们就这点本事啊？就凭这点实力，你们也敢闯进城堡啊。"
D.Strings[14142]="巫妖王赐予我的力量远远超过了你们的想象。看招！"
D.Strings[14143]="该结束了。"
D.Strings[14144]="你总算来了，达里安！我正在猜想你什么时候会露面呢。"
D.Strings[14145]="%s狡黠地笑了笑。"
D.Strings[14146]="巫妖王会将……你们……统统……干掉。"
D.Strings[14147]="藐视巫妖王的权威是要付出代价的！"
D.Strings[14148]="就凭你，也想反抗我的意志，破坏我的计划吗？"
D.Strings[14149]="你将一事无成！"
D.Strings[14150]="奥尔巴兹·血毒，就凭你也敢自称是巫妖王的左膀右臂。"
D.Strings[14151]="停止无力的抵抗吧，这仅仅能延缓你的毁灭罢了。"
D.Strings[14152]="你迫不及待地想要除掉我，然后独揽大权是吗？"
D.Strings[14153]="终于除掉了祸根。"
D.Strings[14154]="趁你还活着，只管宣扬这些陈词滥调吧。你终究会落到我的手里，摩比乌斯将宣告你的死讯！"
D.Strings[14155]="摩比乌斯，让他们知道，敢于违抗国王的旨意是什么下场！"
D.Strings[14156]="奥尔巴兹，你根本就不具备领袖的天赋，你连一队没脑子的骷髅都指挥不了！"
D.Strings[14157]="我们……是无比强大的龙族！怎……怎么会这样……？"
D.Strings[14158]="我无所畏惧！你们根本不值一提！"
D.Strings[14159]="渺小卑微的东西。"
D.Strings[14160]="真是微弱的抵抗……"
D.Strings[14161]="你们太容易对付了！"
D.Strings[14162]="父亲大人教了我很多东西。"
D.Strings[14163]="我真是同情你，萨塔里奥，仅此一次。"
D.Strings[14164]="啊……太晚了，$g兄弟:姐妹;。$b$b我……快死了……"
D.Strings[14165]="你们没资格来这里！你们的归宿……在死者的国度！"
D.Strings[14166]="毫无悬念。"
D.Strings[14167]="轻松。就像我平常的娱乐一样……"
D.Strings[14168]="我要将你们投入黑暗中。"
D.Strings[14169]="一群自大的低等生物。来挑战一下你们永远也无法理解的强大力量吧。"
D.Strings[14170]="我不仅仅是一条龙。你们还可以在我身上发现更多的秘密。"
D.Strings[14171]="欣赏你的挣扎真是令人愉悦。好吧，现在让你见识见识该怎么了结这一切！"
D.Strings[14172]="我不该……犹……犹豫的……"
D.Strings[14173]="你们这些下等生物根本无法对我构成任何威胁！使出全力战斗吧！"
D.Strings[14174]="你唯一可以做到的事情，就是体面地战死！"
D.Strings[14175]="这就是你的全部实力了吗？"
D.Strings[14176]="我要用你们的骨头来剔牙！"
D.Strings[14177]="你们好像有两下子啊，那么就让你们看看我的招数吧……"
D.Strings[14178]="与你们不同的是，我有无数的绝技！"
D.Strings[14179]="父亲大人对你的评价一点都没错，萨塔里奥。你就是个废物。"
D.Strings[14180]="我还能……继续……战……"
D.Strings[14181]="朋友，坚持住。告诉我究竟出了什么事。"
D.Strings[14182]="$n，瓦哈拉斯的勇士，很高兴再次见到你。$B$B你是回来帮助朋友作战的吗？"
D.Strings[14183]="我们在暴风雪的掩护下发动了进攻……$b$b天灾军团被打了个措手不及……眼看就要取得胜利……$b$b突然……我们遭遇了……部落大军的偷袭。$b$b他们毁了……一切……"
D.Strings[14184]="黑锋骑士们，准备战斗！"
D.Strings[14185]="等等……$b$b还有一件事……"
D.Strings[14186]="干得好！阿尔萨斯正在赶往诺森德！"
D.Strings[14187]="嗯，麻烦你啦！"
D.Strings[14188]="亡灵冲我们来了！"
D.Strings[14189]="传言是真的！王子已经疯了！"
D.Strings[14190]="女王陛下，他们知道吗？"
D.Strings[14191]="不，亲爱的。"
D.Strings[14192]="不能让他们知道年轻的圣骑士的命运。还不到时候。"
D.Strings[14193]="我要输入神秘兑换码，兑换暴雪巨熊。"
D.Strings[14194]="他们不会知道的。"
D.Strings[14195]="到我这里来，$n。"
D.Strings[14196]="退潮了……"
D.Strings[14197]="我就是自然之力！"
D.Strings[14198]="我要离开这里！"
D.Strings[14199]="你们无法阻止汹涌的海潮！"
D.Strings[14200]="我是不会被困住的！Ngyah！！"
D.Strings[14201]="我要吞噬，要屠戮，要毁灭，要破坏！在澎湃的大海面前屈服吧！"
D.Strings[14202]="流水无形，它可以化为任何形态……跨越任何障碍。"
D.Strings[14203]="别挡道，凡人！"
D.Strings[14204]="西部下水道的入口在通往紫罗兰城堡的阶梯下面。"
D.Strings[14205]="东部下水道的入口在克拉苏斯平台的入口外面。"
D.Strings[14206]="达拉然墓地位于城市西部，紫罗兰城堡的北面。"
D.Strings[14207]="日暮广场位于达拉然南部。广场上的魔法喷泉是很受欢迎的钓鱼场所。"
D.Strings[14208]="鲁因广场是一座位于达拉然中心的公园。"
D.Strings[14209]="安东尼达斯的纪念碑位于达拉然北部。"
D.Strings[14210]="在达拉然城北有一口井，某些……富有冒险精神的游客能通过那口井进入下水道。"
D.Strings[14211]="紫罗兰监狱位于达拉然东南部，用于关押肯瑞托法师议会的敌人。"
D.Strings[14212]="看见达拉然东部的巨塔了吗？那就是宏伟的紫罗兰城堡。"
D.Strings[14213]="部落旅客主要集中在达拉然东北部的夺日者圣殿。$B$B那里设有旅店，还有通往各大战场和奥格瑞玛的传送门。"
D.Strings[14214]="联盟旅客主要集中在达拉然西南部的银色领地。$B$B那里设有旅店，还有通往各大战场和暴风城的传送门。"
D.Strings[14215]="达拉然至少有三条地下通道：东部和西部各有一个下水道入口，北部还有一口井。"
D.Strings[14216]="东部下水道入口"
D.Strings[14217]="西部下水道入口"
D.Strings[14218]="水井入口"
D.Strings[14219]="达拉然有许多有趣的地方。你想去哪里？"
D.Strings[14220]="联盟区"
D.Strings[14221]="部落区"
D.Strings[14222]="紫罗兰城堡"
D.Strings[14223]="紫罗兰监狱"
D.Strings[14224]="下水道"
D.Strings[14225]="安东尼达斯纪念碑"
D.Strings[14226]="鲁因广场"
D.Strings[14227]="日暮广场"
D.Strings[14228]="墓地"
D.Strings[14229]="达拉然的竞技场和管理员都在这座城市的下水道里。$B$B至少有三条地下通道可以抵达那里：东部和西部下水道的入口，还有北部的水井。"
D.Strings[14230]="在达拉然的联盟区银色领地和部落区夺日者圣殿都设有通往暴风城、奥格瑞玛和各大战场的传送门。"
D.Strings[14231]="缝合场再也不能为巫妖王制造血肉大军了。"
D.Strings[14232]="让我们杀了这个……东西……了结这里的麻烦。"
D.Strings[14233]="在肯瑞托议会中，我的职责是保障法师议会的战略利益。$B$B本周要做的事情还有很多，$n。你愿意帮忙吗？"
D.Strings[14234]="魔法商业区位于达拉然西北部，那里汇集了大部分专业技能训练师。"
D.Strings[14235]="贸易区"
D.Strings[14236]="魔法商业区的避邪纺织店汇集了全城最好的裁缝。魔法商业区就在达拉然的西北部。"
D.Strings[14237]="魔法商业区的传说皮甲汇集了各种剥皮和制皮训练师。魔法商业区就在达拉然的西北部。"
D.Strings[14238]="魔法商业区的亮晶晶矿业公司汇集了全城的采矿训练师和供应商。魔法商业区就在达拉然的西北部。"
D.Strings[14239]="你要找的卡蒂亚珠宝店就在达拉然西北部的魔法商业区。"
D.Strings[14240]="你要找的铭文师的殿堂就在达拉然西北部的魔法商业区。"
D.Strings[14241]="在达拉然西北部的魔法商业区，农艺炼金房的旁边坐落着一间温室。你可以在那里找到全城最好的草药师。"
D.Strings[14242]="在达拉然南部的日暮广场内有一座魔法喷泉，你可以在那附近找到钓鱼训练师。"
D.Strings[14243]="在达拉然西北部的魔法商业区设有全城最高级的急救中心——急你所急。"
D.Strings[14244]="工程师可以前往达拉然西北部的魔法商业区，在精密仪器接受训练。"
D.Strings[14245]="你可以去简单附魔瞧一瞧，就在达拉然西北部的魔法商业区外面。"
D.Strings[14246]="你可以在联盟区和部落区旅店的厨房里找到烹饪训练师。"
D.Strings[14247]="联盟旅店"
D.Strings[14248]="部落旅店"
D.Strings[14249]="英雄之家位于达拉然西南部的银色领地旁边。$B$B那里不仅设有露天啤酒店，还汇集了全城最好的烹饪训练师。"
D.Strings[14250]="你可以前往达拉然东北部的部落区，去夺日者圣殿的“肮脏的野兽”瞧一瞧。$B$B听说那里非常脏乱，但是有一位很棒的烹饪训练师。"
D.Strings[14251]="达拉然西北部的魔法商业区内设有大型的锻造台和熔炉。$B$B你只要找到巨大的魔法铁砧和描绘着战斧及护盾图案的彩色玻璃窗就对了。"
D.Strings[14252]="农艺炼金房位于达拉然西北部的魔法商业区，房间的门呈药水瓶状。你是不可能找错地方的！"
D.Strings[14253]="你要找哪一种专业训练师？"
D.Strings[14254]="高等精灵希拉·雪晨能教你学会寒冷天气飞行。$B$B她骑着龙鹰，就在达拉然东部的克拉苏斯平台上。"
D.Strings[14255]="达拉然的法师训练师和传送门训练师聚集在东部的一幢大型建筑物内，就在城市中心的鲁因广场和克拉苏斯平台之间。"
D.Strings[14256]="你要找哪一种训练师？"
D.Strings[14257]="你可以在达拉然东北部的魔法动物店找到兽栏管理员。"
D.Strings[14258]="魔术旅馆是达拉然最受欢迎的旅店，就在市中心以北。$B$B联盟区和部落区均设有旅店。听说达拉然下水道里也有一家旅店。"
D.Strings[14259]="达拉然著名的理发店就坐落在城市北部。"
D.Strings[14260]="你可以在达拉然东部的克拉苏斯平台找到飞行管理员。"
D.Strings[14261]="达拉然银行位于城市北部。"
D.Strings[14262]="达拉然商业银行位于城市南部，毗邻日暮广场。"
D.Strings[14263]="达拉然内设有三座银行：北部的达拉然银行，南部的达拉然商业银行以及位于下水道的银行。"
D.Strings[14264]="北部银行"
D.Strings[14265]="南部银行"
D.Strings[14266]="达拉然设有许多信箱：你可以在各个街道转角，旅店和银行外以及克拉苏斯平台找到它们。"
D.Strings[14267]="克拉苏斯平台"
D.Strings[14268]="克拉苏斯平台位于达拉然的最东端。$B$B本城的飞行管理员和寒冷天气飞行训练师都在那里。"
D.Strings[14269]="达拉然没有拍卖行。你必须通过传送门返回各大主城才能使用拍卖行。$B$B传送门位于达拉然的联盟和部落区：银色领地和夺日者圣殿。"
D.Strings[14270]="你想销毁我们的原料是吧？呃，主人已经想到了一项特殊的计划……"
D.Strings[14271]="瞧！冰霜巨龙！它冲我们来了！"
D.Strings[14272]="主城传送门"
D.Strings[14273]="竞技场"
D.Strings[14274]="欢迎来到达拉然，旅行者。$B$B我能帮你什么忙吗？"
D.Strings[14275]="陌生人，在达拉然逗留期间，请您遵守此地的法律。$B$B您迷路吗？我能帮上什么忙吗？"
D.Strings[14276]="达拉然的公会注册员就在市中心以南的旅客中心。"
D.Strings[14277]="欧尔拉金，你给我滚回来！这里还有很多工作要做呢！"
D.Strings[14278]="你会为自己的行径付出代价的！为银色北伐军而战！"
D.Strings[14279]="$n，根据我的预见，你将同大法师兰达洛克谈话。"
D.Strings[14280]="达拉然只有法师训练师。如果你要找其他职业的训练师，就必须通过传送门返回各大主城。$B$B$B$B传送门位于达拉然的联盟和部落区：银色领地和夺日者圣殿。"
D.Strings[14281]="下水道的东北部有一个黑市。"
D.Strings[14282]="西部下水道设有通往城市底层的隧道，就在咒语和乌鸦旅店以北。$B$B有些喜欢冒险的旅客会从隧道进出达拉然。"
D.Strings[14283]="你要找的是咒语和乌鸦旅店吧，就在西部下水道。"
D.Strings[14284]="西部下水道有一座地精开设的银行，就在咒语和乌鸦旅店以北。"
D.Strings[14285]="热砂港在达拉然的中心下水道里举办竞技场循环赛。$B$B你还可以参与意志竞技场的比赛。"
D.Strings[14286]="东部下水道有一条直通克拉苏斯平台的斜道。"
D.Strings[14287]="西部下水道有一条通往紫罗兰城堡附近的斜道。"
D.Strings[14288]="达拉然下水道共有三条出路：通往东城和西城的斜道，以及通往达拉然底层的隧道。$B$B当然，你可以乘坐飞行坐骑穿越那条隧道。"
D.Strings[14289]="下水管道"
D.Strings[14290]="欢迎来到达拉然下水道。我能帮你什么忙吗？"
D.Strings[14291]="必须不惜一切代价阻止天灾军团。绝不能让他们在这里组建的大军进入战场。"
D.Strings[14292]="%s跑向他的铁砧！"
D.Strings[14293]="下水道出口"
D.Strings[14294]="%s百无聊赖地在克拉苏斯平台上转悠。"
D.Strings[14295]="%s抬起手掌，轻轻地打了个哈欠。"
D.Strings[14296]="来吧，云翼。我们来飞一圈。"
D.Strings[14297]="%s轻轻地叹了口气，耸了耸肩。"
D.Strings[14298]="好无聊啊，云翼。走吧！"
D.Strings[14299]="你也像我一样安静不下来吧，云翼？那我们去飞一会儿吧！"
D.Strings[14300]="我们的道路是神圣的。我们宁愿死去，也不会背弃托里姆，与巫妖王同流合污。"
D.Strings[14301]="我不能再纵容我的兄弟了。是时候纠正他犯下的过错了。我们要消灭他和他的追随者。"
D.Strings[14302]="求求你，$r。$b$b让我解脱吧……"
D.Strings[14303]="别犹豫，$c。$b$b动……动手吧……"
D.Strings[14304]="请转告我的家人……$b$b我临死前还记挂着他们……"
D.Strings[14305]="送我上路吧……求求你……"
D.Strings[14306]="动手吧，$c……然后……为我复仇！"
D.Strings[14307]="求求你，$r……$b$b我不想被天灾军团复活！"
D.Strings[14308]="一路走好，联盟的英雄！"
D.Strings[14309]="真不敢相信，诅咒教派竟然如此粗心，把这些东西都落下了。"
D.Strings[14310]="我准备好发起进攻了，克里托斯。给我一匹骷髅狮鹫吧？"
D.Strings[14311]="<通过眼睛控制一只轻盈追迹者。>"
D.Strings[14312]="这个王国已经属于天灾军团了。只有亡者才能通行！"
D.Strings[14313]="你们的到来体现了自身的愚蠢。"
D.Strings[14314]="遵照阿努巴拉克的命令！"
D.Strings[14315]="我们被攻击了！立刻出击，把敌人的尸体给我带回来！"
D.Strings[14316]="我们必须守住大门。进攻！将他们撕成碎片！"
D.Strings[14317]="不惜一切代价保卫城门！把他们全都撕碎！"
D.Strings[14318]="小心守着隧道。我们不能让任何人通过！"
D.Strings[14319]="我听到了脚步声。提高警惕。"
D.Strings[14320]="活人的气息。准备战斗。"
D.Strings[14321]="它们很饿了……"
D.Strings[14322]="宠物们，该吃晚饭了！"
D.Strings[14323]="我本该感谢你们的……但我已经没有那个资格了……"
D.Strings[14324]="阿尔萨斯的弱点就是骄傲。随着他的力量日益强大，这个弱点也越来越明显。我相信，黑锋骑士团一定能找到机会击败这位前王子。"
D.Strings[14325]="%s吐丝结茧！"
D.Strings[14326]="%s朝四周喷射蛛丝！"
D.Strings[14327]="蛛网上爬出了小蜘蛛！"
D.Strings[14328]="%s加入了战斗！"
D.Strings[14329]="中央大门打开了！"
D.Strings[14330]="无尽的痛苦在等待着你！"
D.Strings[14331]="你将要经历我曾经历过的一切！"
D.Strings[14332]="你已经做出了选择。"
D.Strings[14333]="很快，你就将听到主人的召唤。"
D.Strings[14334]="来呀，我的子民！吞噬他们的血肉吧！"
D.Strings[14335]="在我的虫群面前，你的盔甲毫无用处！"
D.Strings[14336]="感受这可怕的热疫吧！"
D.Strings[14337]="啊……啊啊啊！从没有想到……我还能摆脱……他的魔掌……"
D.Strings[14338]="%s对附近的所有血肉之躯发动了残杀！"
D.Strings[14339]="早上好！"
D.Strings[14340]="极性转换！"
D.Strings[14341]="我能为你做什么吗？"
D.Strings[14342]="%s传送到了上层平台！"
D.Strings[14343]="%s施放传送后开始引导法术！"
D.Strings[14344]="%s再次发动进攻！"
D.Strings[14345]="死灵能量形成的光环屏蔽了一切治疗法术！"
D.Strings[14346]="光环散去了，又可以治疗了！"
D.Strings[14347]="你好啊！"
D.Strings[14348]="你不该那么做的！他不喜欢那样。"
D.Strings[14349]="战争的阴云已经迫近，$n。我们和部落都派了轰炸机进入轰炸船和失落希望之谷。你愿意参加这次行动吗？"
D.Strings[14350]="给我一架轰炸机！"
D.Strings[14351]="空气中的魔法能量正在消散……"
D.Strings[14352]="我有点忙。"
D.Strings[14353]="什么事？我正忙着呢。"
D.Strings[14354]="我在工作呢。走开。"
D.Strings[14355]="入侵者！是谁闯入了古代王国？"
D.Strings[14356]="你准备好参与夺回幽暗城一战了吗，$n？"
D.Strings[14357]="元素之灵与我们同在，$n。在它们的帮助下，我们可以竭尽全力阻止瓦里玛萨斯和普特雷斯的阴谋得逞！LOK'TAR OGAR！"
D.Strings[14358]="哎呀！小声点，$n！怎么？你想把我们害死吗？！$B$B我当然知道你是谁！你的大名早就在联盟中传遍了！$B$B你觉得我的跳跃机器人怎么样啊？她是根据机械侏儒的原理设计的，运行起来非常流畅，是以空气为动力的！"
D.Strings[14359]="哇，哇，哇！小声点，$n。小声点！$B$B<布拉斯朝四周看了看。>$B$B你也不想我们被那些冰棍儿维库人发现吧？$B$B你觉得我的跳跃机器人怎么样啊？这是根据机械侏儒的原理设计的哦。很棒吧，对吗？"
D.Strings[14360]="我准备好了，布莱恩。我们把钥石拼起来吧。"
D.Strings[14361]="形势严峻，没有捷径可走。如果你的战斗力够强，请掩护我的小队，直到他们做好爬上伊米海姆的准备。他们需要一切可利用的帮助。"
D.Strings[14362]="嗯。我们试试能不能拼好钥石。"
D.Strings[14363]="你好，布莱恩·铜须。我是这座神殿的最后一名守卫者。"
D.Strings[14364]="你当之无愧是一名优秀的探险家，你的心中充满了对知识的渴求。"
D.Strings[14365]="土灵已经将你视为忠实的盟友。"
D.Strings[14366]="在战斗以及寻找钥石的过程中，你和你的同伴都证明了自己。"
D.Strings[14367]="你们的动机是纯洁的。钥石的碎片将得以重新拼合。前往奥杜尔寻找你想要的答案吧，布莱恩·铜须。"
D.Strings[14368]="钥石拼好了！我们成功啦，$n！"
D.Strings[14369]="自信号上虫灾泛滥，我们没法开往诺森德了。"
D.Strings[14370]="谁也不知道存放在奥杜尔的档案中隐藏了什么秘密。我要去那里揭开真相。再次感谢你的帮助，$n。没有你的帮助，我现在还在找那把钥匙呢。"
D.Strings[14371]="我们已经做好了扬帆诺森德的准备，突然发现船上出现了大批害虫。"
D.Strings[14372]="在开往诺森德之前，我们必须解决自信号上的虫害问题。"
D.Strings[14373]="哎呀，你长得真难看！不过这并不表示你不会战斗。$B$B我麾下的一支小队很快就要出发啦——加入他们的行列，一起爬上伊米海姆吧！"
D.Strings[14374]="竞技场排名赛将在$6318d后再次拉开帷幕。$B$B未来的竞技场冠军正在忙于练习作战技巧以及搜寻最好的装备。你准备好了吗？"
D.Strings[14375]="要我为你指引道路吗，年轻人？"
D.Strings[14376]="请带我去冬拥堡垒墓地。"
D.Strings[14377]="请带我去沉降之环墓地。"
D.Strings[14378]="请带我去破碎神殿墓地。"
D.Strings[14379]="请带我去东部火花车间墓地。"
D.Strings[14380]="请带我去西部火花车间墓地。"
D.Strings[14381]="请指引我返回联盟营地。"
D.Strings[14382]="请指引我返回部落营地。"
D.Strings[14383]="我们在这里的行动关系到许多人的性命。你想说什么就快说吧，$c。"
D.Strings[14384]="你带来了最新的战况情报吗，$r？"
D.Strings[14385]="最好的战术是速战速决。谈话也是一样。你想说什么，$r？"
D.Strings[14386]="该传送门通往时光之穴，它位于遥远的塔纳利斯沙漠地底。$B$B如果你要去那里的话，我可以将你传送过去。"
D.Strings[14387]="该传送门通往时光之穴，它位于遥远的塔纳利斯沙漠地底。$B$B但是你的力量还不够强大，我建议你不要去那里。"
D.Strings[14388]="我能闻到炸弹和火箭里的火药味儿！你也要出去找些乐子吗？"
D.Strings[14389]="有很多声音在对我讲话。"
D.Strings[14390]="我必须服从。"
D.Strings[14391]="你最好赶紧离开，不然你也会被它影响！"
D.Strings[14392]="跟我说说精魂披风图样的事儿吧。"
D.Strings[14393]="我们就快准备好啦。再给我们一点时间，很快就能出发了。"
D.Strings[14394]="准备工作尚未完成。我们暂时还不会离开。"
D.Strings[14395]="它就在我们身边。就在我的脑海里！"
D.Strings[14396]="士兵们都准备好了。我们要让那些维库人流血！"
D.Strings[14397]="萨隆邪铁……里面藏有什么东西！"
D.Strings[14398]="邪铁里藏有东西！就在岩石和泥土里！"
D.Strings[14399]="我在旅途中学会了精魂披风的图样。$B$B图样可交易，是史诗级的施法者披风，装备后可获得耐力、法术强度、智力以及法力回复速度的加成。我一直在寻找有资格学习这张图样的人。$B$B打通诺森德所有的普通难度地下城，并获得“诺森德地下城大师”成就的人才有资格学习精魂披风的图纸。"
D.Strings[14400]="我准备好学习精魂披风了。"
D.Strings[14401]="我要离开这里！你能放我出去吗？"
D.Strings[14402]="你听见了吗？它正在你的脑海中低语。"
D.Strings[14403]="走吧，你自由了。快离开这儿！"
D.Strings[14404]="我曾去过许多黑暗的地方，学会了死寒披风的图样。$B$B图样可交易，是史诗级的施法者披风，装备后可获得法术强度、急速以及爆击的加成。我一直在寻找有资格学习这张图样的人。$B$B完成诺森德的大部分任务，并获得“诺森德的博学者”成就的人才有资格学习死寒披风的图纸。"
D.Strings[14405]="跟我说说死寒披风图样的事儿吧。"
D.Strings[14406]="我来了，主人！"
D.Strings[14407]="我的生命属于你！"
D.Strings[14408]="我准备好学习死寒披风了。"
D.Strings[14409]="我是不会离开的！"
D.Strings[14410]="不！你错了！我脑海中的声音非常美妙！"
D.Strings[14411]="我不想走！我要留在这里！"
D.Strings[14412]="我不要回去。我要去地底找寻我存在的意义！"
D.Strings[14413]="啊哈哈哈哈……你很快就会加入我们的！"
D.Strings[14414]="我要到地底深处去，到主人身边去。我一定要跳下去！"
D.Strings[14415]="你是一位颇为出色的裁缝，因此我可以教你一些特别的图样，比如精魂披风和死寒披风。"
D.Strings[14416]="天灾之锅剧烈地沸腾起来！"
D.Strings[14417]="有什么东西从锅里冒了出来！"
D.Strings[14418]="天灾之锅还在沸腾……"
D.Strings[14419]="天灾之锅中的东西被中和了！"
D.Strings[14420]="你！快过来！尽情吃喝一顿吧，为下一次的战斗做好准备。$B$B不许在这里打架！不然我就送你去喂狼。"
D.Strings[14421]="求求你，住手。"
D.Strings[14422]="再打我一下试试，你会后悔的！"
D.Strings[14423]="哎哟！"
D.Strings[14424]="对不起。我会努力干活的。"
D.Strings[14425]="主人很快就会召我回去的！"
D.Strings[14426]="欢迎来到肯瑞托议会的故乡。"
D.Strings[14427]="我下去啦。祝你们好运！"
D.Strings[14428]="谢谢你掩护我们！"
D.Strings[14429]="顺利抵达目的地——这里就是本次侦察任务的目标地点。"
D.Strings[14430]="渗透行动开始。"
D.Strings[14431]="我会为你杀死一名敌人的。"
D.Strings[14432]="我要把你碎尸万断！"
D.Strings[14433]="这之后，一切都将灭亡！"
D.Strings[14434]="你们想见识真正的力量？那我就让你们如愿以偿！"
D.Strings[14435]="剁碎他们！刺穿他们！"
D.Strings[14436]="杀了他们！"
D.Strings[14437]="来跟我的大朋友问声好吧！"
D.Strings[14438]="真快呀！"
D.Strings[14439]="谁需要神？我们自己就是神！"
D.Strings[14440]="我提醒过你了！"
D.Strings[14441]="再强大的力量……也有衰落的一天。"
D.Strings[14442]="你好，$c。$B$B一旦联盟取得冬拥堡垒的控制权，我就将为想要前往那里的旅行者开启一道传送门。$B$B下一场战斗将在$4354k内开始。"
D.Strings[14443]="你好，$c。$B$B一旦部落取得冬拥堡垒的控制权，我就将为想要前往那里的旅行者开启一道传送门。$B$B下一场战斗将在$4354k内开始。"
D.Strings[14444]="你好，$c。$B$B联盟已经控制了冬拥堡垒。如果你想去那里的话，就穿过这道传送门吧。$B$B下一场战斗将在$4354k内开始。"
D.Strings[14445]="你好，$c。$B$B部落已经控制了冬拥堡垒。如果你想去那里的话，就穿过这道传送门吧。$B$B下一场战斗将在$4354k内开始。"
D.Strings[14446]="%s开始召唤暮光传送门！"
D.Strings[14447]="冒险者们，牢门的力量开始减弱了！"
D.Strings[14448]="牢门的封印力量只剩一半了！你们必须坚持住！"
D.Strings[14449]="牢门的封印即将崩溃！如果蓝龙军团攻破大门，一切都完了！"
D.Strings[14450]="你好，朋友。我能为你做什么吗？"
D.Strings[14451]="嘿，等一等。你没有属于自己的飞行坐骑诶。$B$B如果出行不便的话，恐怕你没有办法帮助其他的地精了。他们付钱给我，让我将旧坐骑借给你这样的人使用——免费使用哦。$B$B怎么样？"
D.Strings[14452]="好吧。"
D.Strings[14453]="你需要什么帮助？"
D.Strings[14454]="我已经找到了诺甘农钥石的线索，有了它就能进入奥杜尔的档案室；但是泰坦将钥石分成了两块并分别藏了起来。$B$B钥石的外壳藏在北部海滩的创世者图书馆里，就在奥杜尔以南。首先，你要从图书馆守护者那里获得访问磁盘的碎片。"
D.Strings[14455]="时间到了。愿圣光赐予我们力量吧。"
D.Strings[14456]="说到财宝，永远不要轻视翻捡别人的垃圾的行为。偷来的财宝更加珍贵，是吗？但是免费的东西就是好的，无论你采用什么方式！"
D.Strings[14457]="不速之客！你们以为自己能偷偷地溜进我的王国吗？"
D.Strings[14458]="我必须承认……我早已预知你们的到来。希望你们能找到安息地……适合你们的安息地。"
D.Strings[14459]="人们经常置疑我身为三指大盗的本事。其实我靠的是手腕的灵活性……一旦失手，你应该立即制服他们，这同样要依赖手腕的力量。$B$B灵巧的双手比稳定的收入更加宝贵，你明白吗？"
D.Strings[14460]="我一点都不担心巫妖王。我见过无数的大人物沉沉浮浮，他们喜欢把事情搞得一团糟。但是每当人民站起来反抗时，他们很快就会偃旗息鼓，沦为历史课本上的教程。巫妖王也不会例外。"
D.Strings[14461]="我们上次交手时，你占尽了圣地的优势。但如今，你会发现我们的境遇已经发生了……逆转。"
D.Strings[14462]="或许吧。就算我的双脚没有踏在圣地上，也能用灰烬使者摧毁你的徽记。"
D.Strings[14463]="徽记……那是你残存的最后一丝人性。我要在你彻底丧失人性之前亲自摧毁它。我相信……"
D.Strings[14464]="你似乎过于自信了。你不如想想上次我们交手的结果。"
D.Strings[14465]="别虚张声势了，你毕竟是一名圣骑士。你对于救赎的痴迷已经到了不可救药的地步。"
D.Strings[14466]="你想要“挽救”我这个任性的孩子，不愿意放弃人道救赎的唯一机会，因此你只会死得更快！"
D.Strings[14467]="你心中只剩下往昔的阴影，无可救赎了！"
D.Strings[14468]="饥饿驱使着那些以失落灵魂为食的阴影。"
D.Strings[14469]="每倒下一个，会有更多的阴影接替它的位置。"
D.Strings[14470]="保持冷静，听我的指挥。"
D.Strings[14471]="它来了。做好准备。"
D.Strings[14472]="不对劲……我感觉到黑暗的气息。"
D.Strings[14473]="巫妖王就在这里。愿圣光指引我们的剑刃吧。"
D.Strings[14474]="那些嘲笑我的战袍的人都是蠢货。$B$B这件衣服所用的旧钢都来自一个远古的学习之地！"
D.Strings[14475]="这次我不会死那么快了！"
D.Strings[14476]="我只是尽了我应尽的义务，兄长。你让我别无选择。"
D.Strings[14477]="魔枢战争就此结束了。"
D.Strings[14478]="这个决定令我的心灵深处痛楚不已，但这生灵涂炭与天地崩裂的局面也终于得到了休止。无论玛里苟斯犯过什么大错，我都会为他的死默哀。他曾是一位高贵的守护者。今天，世界上最强大的守护者之一，就这样逝去了。"
D.Strings[14479]="红龙军团将会担负起修复世界创伤的责任与义务。回去吧，和你的同伴们一起回去，好好休息。明天，你们还要应对新的挑战，你们必须时刻为此做好准备。生命……仍要继续。"
D.Strings[14480]="什么？！"
D.Strings[14481]="我突然觉得很好笑。呃？！"
D.Strings[14482]="好吧，谁朝我扔了宝珠？"
D.Strings[14483]="你搞错了。我是黑暗压制者！"
D.Strings[14484]="是误会啊。我是被陷害的。别把我扔下去！"
D.Strings[14485]="你竟敢干预我们的事！"
D.Strings[14486]="我的生命……结束了……"
D.Strings[14487]="达拉然北部的再来一杯应该能满足你的需求。"
D.Strings[14488]="达拉然南部的好战的秘法师应该能满足你的需求。"
D.Strings[14489]="达拉然东部的猎人用品店出售枪支、弓弩、弹药等商品。"
D.Strings[14490]="达拉然东南部的神兵利器出售各类近战武器。"
D.Strings[14491]="达拉然西部的耶比托·乔巴斯的奇妙玩具店会出售这类物品。"
D.Strings[14492]="达拉然东南部的荣耀杂货店中，“红发”杰克·芬德出售各种杂货。$B$B如果你想购买特殊物品，就去魔法商业区吧。那里的店铺都设有供给商贩。"
D.Strings[14493]="任务完成！我在这里的工作结束了。"
D.Strings[14494]="艾美的货车通常停在达拉然北部，就在达拉然银行附近。"
D.Strings[14495]="魔法动物店位于达拉然东北部。那里出售宠物用品和珍稀坐骑，并提供兽栏服务。"
D.Strings[14496]="达拉然西部的巫术姐妹出售各种魔法材料。$B$B不过你要小心莫尔海德的那只黑猫……"
D.Strings[14497]="噢，不！冒险者们，刚刚发生了一件可怕的事！永恒之龙抓走了我的一位同伴，他们正在对他做一些可怕的事！$B$B保护阿尔萨斯还是你们的首要任务。但是如果你们行动够快的话，或许还有机会挽救一位时光守护者！"
D.Strings[14498]="达拉然南部的荣耀杂货店出售各种杂货。"
D.Strings[14499]="苹果树的水果货车通常停在达拉然的西南部，就在银色领地附近。"
D.Strings[14500]="你可以在达拉然东南部找到爱丽丝·普里洛斯小姐的花摊。"
D.Strings[14501]="冒险者可以在银色领地或者夺日者圣殿为自己立下的功绩领取公正的奖励。"
D.Strings[14502]="达拉然北部的坦克用品店是城里最受欢迎的板甲和盾牌商店。"
D.Strings[14503]="达拉然南部的摩尔珍品店有好几位商贩，他们出售各类饰品、圣物、家传宝物和副手武器。"
D.Strings[14504]="达拉然南部的兰格鲁的皮加锁应该能满足你的需求。"
D.Strings[14505]="冒险者，快！时间的守护者坚持不了多久的！"
D.Strings[14506]="我几乎感受不到时间的守护者的讯息！他的时间流正在急速消逝！"
D.Strings[14507]="达拉然西部的命运丝线是城里最受欢迎的裁缝物品和布甲商店。"
D.Strings[14508]="你需要什么类型的武器？"
D.Strings[14509]="近战武器"
D.Strings[14510]="远程和投掷武器"
D.Strings[14511]="法杖和魔杖"
D.Strings[14512]="你需要什么类型的护甲？"
D.Strings[14513]="布甲"
D.Strings[14514]="提里奥倒下了！用你们的生命保护他！"
D.Strings[14515]="皮甲"
D.Strings[14516]="锁甲"
D.Strings[14517]="板甲"
D.Strings[14518]="盾牌"
D.Strings[14519]="啊啊啊！！！"
D.Strings[14520]="你是来帮忙的吗？"
D.Strings[14521]="你……会为此付出代价！杀光他们！"
D.Strings[14522]="你要找哪种商贩？"
D.Strings[14523]="护甲"
D.Strings[14524]="裁缝供应"
D.Strings[14525]="鲜花"
D.Strings[14526]="水果"
D.Strings[14527]="快穿过传送门！他坚持不了多久的。"
D.Strings[14528]="振作起来，北伐军战士。你们并非孤军奋战！"
D.Strings[14529]="珠宝"
D.Strings[14530]="宠物和特殊坐骑"
D.Strings[14531]="馅饼和蛋糕"
D.Strings[14532]="施法和魔法材料"
D.Strings[14533]="玩具"
D.Strings[14534]="商业材料"
D.Strings[14535]="武器"
D.Strings[14536]="美酒和奶酪"
D.Strings[14537]="巫妖王受了重伤。我们应该留下来杀死他。"
D.Strings[14538]="耐心点……我们会有机会干掉巫妖王的。这次，提里奥欠我们一份情。对此我已经很满足了。"
D.Strings[14539]="地精工程学的奥秘是，教你学会如何让爆炸物在指定的地点按时引爆，而不是确保产品不会爆炸。"
D.Strings[14540]="我是见证者夏拉托尔。"
D.Strings[14541]="你愿意听我讲个故事吗？"
D.Strings[14542]="故事？"
D.Strings[14543]="嗯，我读到过你的故事，$n。"
D.Strings[14544]="做个自我介绍吧，夏拉托尔。你为什么被称为见证者？"
D.Strings[14545]="我是最早一批，也是最后一代接受过塞纳留斯教诲的牛头人德鲁伊之一。那时候世界还很年轻，没有燃烧军团，大灾变也还没有发生。一切都是那么宁静。$B$B当我的同胞学习猎杀巨兽时，我却在搜寻历史故事。对知识的渴求令我沉湎于德鲁伊的魔法。有段时间，我满足于与树木、岩石和野兽交谈，倾听它们的故事。$B$B后来，塞纳留斯不再露面，我的同胞渐渐遗忘了他的教诲，但是我忘不了，我还想了解更多关于这个世界的知识。$B$B于是我告别族人，离开家乡去远方流浪。"
D.Strings[14546]="我穷尽一生寻找知识，目睹了许多奇迹，遇见了各种各样神秘的种族，这些经历远远超越了所有的先辈。我的足迹遍布远古的卡利姆多大陆，直到再也找不到新鲜的事物，直到地平线看不见新的陆地。$B$B但是……就在这次旅途即将划上句号时，我觉得自己还是对很多东西缺乏了解。我深知这将成为永远的遗憾，禁不住放声痛哭。$B$B自然生命总有消亡的一天，我跌到在地。这时，他们找到了我。"
D.Strings[14547]="他们？"
D.Strings[14548]="青铜龙族。他们将我从死亡的边缘拯救回来，并带我去见时光之王诺兹多姆。诺兹多姆说，他们一直在关注我的动向，并希望我能够继续追寻知识。他赐我永生并任命我为观察者，担当起艾泽拉斯历史见证者的角色。$B$B我是见证者夏拉托尔，我的任务是维系艾泽拉斯的真实历史，避免它被遗忘。"
D.Strings[14549]="这里是唐卡洛营地，我的兄弟掌管着这个村落，但是……我不记得你。"
D.Strings[14550]="你的存在差点就被抹杀了。$n勇敢地与北风作战，保护了关于你的历史。"
D.Strings[14551]="北风？它还在祸害我的族人？"
D.Strings[14552]="雷蹄，你与北风的战斗已经过去了数百年。你重创了它，这些年来它一直都很沉寂。"
D.Strings[14553]="但是北风不甘心就此落败。相反，它一直在积聚力量，等待时机，意图摧毁你的历史和这座村庄。"
D.Strings[14554]="北风让它的爪牙扭曲了这个地区的历史，意图改变牦牛人口口相传的故事并消灭先祖的亡魂。"
D.Strings[14555]="黑暗主宰西塔利克斯从东南方冲进了瓦哈拉斯！"
D.Strings[14556]="要不是$n和我循着北风扭曲历史的线索，找到了破坏的源头：你与北风的那场远古之战，它们的阴谋已经得逞了。"
D.Strings[14557]="在我的帮助下，$n及时返回了那场战斗的时间流，维护了历史的真相。北风的命运已经被封印起来，你的故事也得以恢复正常。"
D.Strings[14558]="我代表村民谢谢你们，虽然你们的事迹不会为大多数人所知。"
D.Strings[14559]="齐格莉德·冰魂在瓦哈拉斯上空盘旋，她是来复仇的！"
D.Strings[14560]="南方飘来的气味预示了卡纳基的到来！"
D.Strings[14561]="我不能待在这里。我必须返回自己的陵墓。当我与长者的灵魂重聚时，会向大家讲诉你的故事。"
D.Strings[14562]="巴纳霍格领主出现在东南方的高台上！"
D.Strings[14563]="萨杜瓦尔王子在毫无征兆的情况下，如幻影般出现在瓦哈拉斯！"
D.Strings[14564]="安息吧，勇士。"
D.Strings[14565]="哇！你是来自未来的我！嘿嘿，装备强力了不少嘛。真是酷毙了！"
D.Strings[14566]="只有时间能证明一切……"
D.Strings[14567]="这里发生了什么事，阿莱克丝塔萨？"
D.Strings[14568]="欢迎来到奇妙玩具店！$B$B请随意看看。我们出售许多奇妙的玩具，老少咸宜！"
D.Strings[14569]="永恒之龙来了！我必须确保沙漏的安全。你能帮帮我吗？"
D.Strings[14570]="这件装备看上去不错啊，但是你就不能穿得更好一点吗？难道你都不去团队副本的么？"
D.Strings[14571]="嗯，冰冠冰川的局势怎么样啦？"
D.Strings[14572]="克罗米说如果我不能完成任务，我就会从历史上消失。如果我消失了，那么你也就不存在了！"
D.Strings[14573]="我似乎不够强力啊。"
D.Strings[14574]="这事儿完了之后我很可能会借酒消愁。"
D.Strings[14575]="你最好告诉我，我们总共需要面对多少个敌人。你还记得吧？"
D.Strings[14576]="我想说的是，如果我们能活下来，我一定能比你做得更好。我说这话可没有冒犯的意思。"
D.Strings[14577]="等等！既然你来到这里，那就是说将来我也会扮演你现在的角色，再回来这里来帮助我自己？天哪，这分明是一个死循环啊？！"
D.Strings[14578]="见鬼！诺兹多姆就在那里！"
D.Strings[14579]="我感觉自己正在脱离时间流。谢谢你……"
D.Strings[14580]="地穴卫士的尸体上爬出了死尸甲虫！"
D.Strings[14581]="不论付出怎样的代价，我们都会避免再次与部落开战！"
D.Strings[14582]="萨菲隆缓缓升空！"
D.Strings[14583]="萨菲隆再次发动了攻击！"
D.Strings[14584]="克尔苏加德发动了攻击！"
D.Strings[14585]="寒冰皇冠卫士加入了战斗！"
D.Strings[14586]="光环的力量开始减弱了！"
D.Strings[14587]="欢迎！"
D.Strings[14588]="欢迎！请随便看看。"
D.Strings[14589]="你需要什么，可以直接告诉我，$c。"
D.Strings[14590]="你好。我能帮上什么忙吗？"
D.Strings[14591]="有什么要修理的吗，$r？"
D.Strings[14592]="我们已经损失了好几名优秀的同胞。我开始怀疑，这里是否值得我们如此关注。"
D.Strings[14593]="你好，我的$r朋友。你的光临令我不胜荣幸。$B$B我能帮你什么忙吗？"
D.Strings[14594]="您是来给士兵们训话的吗，长官？"
D.Strings[14595]="库尔迪拉……这听上去有些诡异，但是我最近经常看见一个孩子的魂魄。米斯希尔萨·阿奈尔……你听过这个名字吗？"
D.Strings[14596]="做好战斗的准备，$n。等部队全部就位之后，我们就要开始进攻了！"
D.Strings[14597]="看来这场高强度的战斗终于让你体力不支了，$n。放心吧，我不会泄漏你的小秘密的——省得别人认为你疯了。$B$B休息一下吧。这对你有好处。"
D.Strings[14598]="最后的决战即将开始，$n。保持警惕！"
D.Strings[14599]="当然可以，不过以后请小心一些。"
D.Strings[14600]="能认识你这样杰出的$c，真是我的荣幸。"
D.Strings[14601]="$n，你的精神鼓舞着我们。"
D.Strings[14602]="$n是一个好榜样。"
D.Strings[14603]="我敢说，再也找不到比$n更出色的人了。"
D.Strings[14604]="$n，见到你真是太好啦。真的。"
D.Strings[14605]="$n！啊，见到你真是太好啦。你还是很忙吗？"
D.Strings[14606]="欢迎你，龙族的朋友和盟友。请在大厅好好休息吧。"
D.Strings[14607]="啊，是你，$n！欢迎来到我们的圣殿。在这里好好休息一下，这是你应得的权利。"
D.Strings[14608]="复活吧，辛达苟萨！带领霜巢巨龙投入战斗！"
D.Strings[14609]="我准备好进入风暴峭壁了。"
D.Strings[14610]="<女王的伴侣对你点了点头。>"
D.Strings[14611]="$n，繁忙的航程是吧？在返回战场之前，你最好先喘口气。"
D.Strings[14612]="老实说，看你轰炸真是有趣！你肯定开过不少轰炸机吧！"
D.Strings[14613]="雷心国王派我来参加霜脉矮人的试炼。我已经准备好了，弗亚林。"
D.Strings[14614]="我要参加对抗巨龙的战斗。能给我一只雄鹰吗，弗亚林？"
D.Strings[14615]="当心，$n。你的教徒长袍呢？"
D.Strings[14616]="给。准备好了吗？一旦我们开始行动，就不能回头了。"
D.Strings[14617]="我准备好了，大领主。"
D.Strings[14618]="欢迎。"
D.Strings[14619]="欢迎来到魔术旅馆，$c。祝你愉快。"
D.Strings[14620]="欢迎来到咒语和乌鸦旅店，$r。$B$B你最好当心点。纳莉萨不喜欢擦拭地板上的血迹。"
D.Strings[14621]="重获自由的始祖龙振翅飞走了！"
D.Strings[14622]="附近的裂隙中冒出了一团能量火花！"
D.Strings[14623]="一只沙德隆的信徒出现了！"
D.Strings[14624]="塔尼布隆开始孵蛋！"
D.Strings[14625]="一只维斯匹隆的信徒出现了！"
D.Strings[14626]="如果轰炸机被击落，而你被敌人俘虏的话，一定不要讲出自己的真名。要用代号噢。"
D.Strings[14627]="%s召唤出骷髅战士！"
D.Strings[14628]="%s再次投入了战斗！"
D.Strings[14629]="%s召唤出更多的骷髅！"
D.Strings[14630]="大多数巨龙都不敢来到此地，$r。$b$b你这样的凡人为何要以身犯险？"
D.Strings[14631]="你敢于进入玛里苟斯的王国，面对他手下的精英侍卫吗，$r？"
D.Strings[14632]="我……我想是的……"
D.Strings[14633]="幼龙一直在盼望你回来呢，$c。$b$b你准备好起飞了吗？"
D.Strings[14634]="我准备好了，科拉丝塔萨。"
D.Strings[14635]="一队精英蓝龙冲出了传送门！"
D.Strings[14636]="传送门守卫者保护着新的传送门！"
D.Strings[14637]="一名传送门看护者冲出了传送门！"
D.Strings[14638]="对不起，朋友。只有联盟的军官才有权购买载具。"
D.Strings[14639]="魔法力量宝典"
D.Strings[14640]="你可以在铭文训练师附近找到这种古老的书册。"
D.Strings[14641]="成功啦！你听到了吗？真是难以置信！"
D.Strings[14642]="以后有的是时间啊，布莱恩。我们必须立即转移！"
D.Strings[14643]="放置欧米伽符文。成功激活。"
D.Strings[14644]="这里的风景是不是很漂亮啊？你能看到潜在的利益吗？"
D.Strings[14645]="今天是个好日子，不是吗？希望今天结束的时候我们能欣赏到焰火表演。"
D.Strings[14646]="你好，小$r。"
D.Strings[14647]="即使东西没有损坏，也不代表你不能鼓捣它。你想要什么，亲爱的？"
D.Strings[14648]="在如此寒冷的气候下，你要如何飞行呢？"
D.Strings[14649]="D16限时炸弹分配器发出轰鸣声。"
D.Strings[14650]="<从分配器中取出一枚炸弹。>"
D.Strings[14651]="谢谢你！谢谢你一点忙都不帮！"
D.Strings[14652]="你为什么要这样对待哈克穆德？"
D.Strings[14653]="你让哈克穆德现在怎么办好呢？"
D.Strings[14654]="哈克穆德没法在这种环境下工作！再见！"
D.Strings[14655]="我以为我们是朋友！你要丢下哈克穆德吗？"
D.Strings[14656]="没人喜欢尼莫……"
D.Strings[14657]="再见！你曾经是尼莫最好的朋友！"
D.Strings[14658]="尼莫走了。"
D.Strings[14659]="噢，我明白了……你也想那样对待我，是吗？"
D.Strings[14660]="嗯……我总是被人抛弃。"
D.Strings[14661]="我们的友谊完蛋了！"
D.Strings[14662]="你想把我丢在这儿？那我怎么回去？"
D.Strings[14663]="你是认真的吗？你想丢下莫吉蒂？"
D.Strings[14664]="你很坏！别说莫吉蒂没警告过你！"
D.Strings[14665]="那就这样吧！"
D.Strings[14666]="这上面的景色可真不错！"
D.Strings[14667]="糟糕，我把轻羽毛放家里了……缓落术在这里应该很有用的！"
D.Strings[14668]="欢迎造访，$c。达拉然让我感觉身心舒畅，我喜欢待在家里。但是有时候，也会有孤单……冷清的感觉。"
D.Strings[14669]="我有一本书，你或许会感兴趣的。想看看吗？"
D.Strings[14670]="这真是太奇妙了！书里记载的很多内容都是我闻所未闻的。你肯定费了一番功夫才找到的吧？如果你再发现这样的书，一定要立即通知我。\n\n我将肯瑞托魔仆交给你，这样你可以随时向我汇报最新的进展。"
D.Strings[14671]="带上麦酒，踏上寻宝之旅——还有什么比这更美好的事情呢。"
D.Strings[14672]="谢谢你！如果有所发现，我一定会及时通知你的。"
D.Strings[14673]="翡翠梦境已然危机四伏。许多勇士放弃了艾泽拉斯的生活，试图拯救翡翠梦境。我越来越担心他们的安危了。"
D.Strings[14674]="请送我去翡翠梦境寻找橡果。我知道这很危险，但是我不怕。"
D.Strings[14675]="土灵愿意握紧铁锤，成为布德克拉格坚强的后盾。我们要和洛肯的爪牙斗争到底。"
D.Strings[14676]="我们击败了瓦杜兰！还将推倒他的塑像。"
D.Strings[14677]="干得好！今天我们取得了胜利，但是战争还在继续！"
D.Strings[14678]="快点，$c。"
D.Strings[14679]="<引擎发出巨大的轰鸣声。>"
D.Strings[14680]="<坐上轰炸机，返回无赖港。>"
D.Strings[14681]="沉降之环攻城车间遭到了联盟的袭击！"
D.Strings[14682]="沉降之环攻城车间遭到了部落的袭击！"
D.Strings[14683]="破碎神殿攻城车间遭到了联盟的袭击！"
D.Strings[14684]="破碎神殿攻城车间遭到了部落的袭击！"
D.Strings[14685]="狂风环绕着祭坛。你发现祭坛的凹槽处刚好可以放进一颗宝珠。"
D.Strings[14686]="偶尔离开圣殿，呼吸一下新鲜空气也是很不错的。"
D.Strings[14687]="好在巫妖王的魔爪还没有伸到达拉然来。"
D.Strings[14688]="她约我在这里碰面的……难道我找错地方了？"
D.Strings[14689]="终于！$b$b预言中提到的$r$c终于出现了！"
D.Strings[14690]="我准备好返回生者的世界了。"
D.Strings[14691]="宝库遭到了攻击！"
D.Strings[14692]="宝库被攻破了！泰坦圣物失去了保护！"
D.Strings[14693]="有事吗，小家伙？"
D.Strings[14694]="%s召唤出一名碧蓝魔环上尉！"
D.Strings[14695]="炼金房的铭文训练师身旁有一本巨大的，闪闪发光的魔法书，能够帮助你制作强化法术和技能的铭文。"
D.Strings[14696]="快一点，$r。我很疲倦，没功夫开玩笑……"
D.Strings[14697]="保持警惕，$r。$b$b这里不是弱者的游乐场。"
D.Strings[14698]="%s向$n冲来！"
D.Strings[14699]="%s对所有人施放了不灭痛楚！"
D.Strings[14700]="%s对所有人施放了谴责！"
D.Strings[14701]="你来了！"
D.Strings[14702]="请你再展示一次，米斯希尔萨。"
D.Strings[14703]="Lok'tar！你是来协助部落作战的吗？"
D.Strings[14704]="别对那些禽兽心软，$n！"
D.Strings[14705]="你要阻止部落收集灰烬，$n。我们不能让他们在以后的战斗中占据优势！"
D.Strings[14706]="毁掉那些邪恶的战争机器，$n！"
D.Strings[14707]="死亡……是无法阻止我的……"
D.Strings[14708]="啊，复活节。看到人们放下尊严，四处搜寻彩蛋，真是有趣啊。显然，这些彩蛋拥有某种特殊的魔力……"
D.Strings[14709]="复活节又到啦！在这个节日里，我们要感谢圣光让世界重生。"
D.Strings[14710]="糖果！这正是我想要的；希望我不用为了找糖果而东奔西跑！"
D.Strings[14711]="嘿，如果人们乐意四处奔走，在土堆里寻找彩蛋，我有什么好说的呀？反正我能从绘制彩蛋上赚到一笔，而且今年我还投资了养鸡场。"
D.Strings[14712]="复活节来啦！我找到了好多好多彩蛋。今天真是个找彩蛋的好日子呢，不是吗？"
D.Strings[14713]="复活节是艾泽拉斯的德鲁伊们庆祝生命复苏的日子。彩蛋是繁衍的象征，同时能很好地引导大家理解灵魂的奥秘，你说是吗？"
D.Strings[14714]="我们会在复活节期间庆祝春天的到来。赞美生命和一切美好的事物。"
D.Strings[14715]="此刻，我们赞美生命的诞生，而彩蛋代表着春天和复苏。愿你度过一个美好的春天。"
D.Strings[14716]="嘿，朋友，眼下正是为生命和春天欢呼的日子。你已经收集到了不少彩蛋吧？"
D.Strings[14717]="这个节日根本毫无意义。彩蛋和所谓“生命的礼赞”，我呸。"
D.Strings[14718]="嗨，朋友！你是来协助我们作战的吗？"
D.Strings[14719]="你好，朋友。希望你在复活节期间玩得开心！为什么不一起狂欢呢？"
D.Strings[14720]="你好，$c。$B$B一旦联盟取得冬拥堡垒的控制权，我就将为想要前往那里的旅行者开启一道传送门。$B$B战斗正在进行中，赶快前往冬拥湖，支援我们的部队吧！"
D.Strings[14721]="你好，$c。$B$B一旦部落取得冬拥堡垒的控制权，我就将为想要前往那里的旅行者开启一道传送门。$B$B战斗正在进行中，赶快前往冬拥湖，支援我们的部队吧。"
D.Strings[14722]="在我们的新盟友牦牛人的帮助下，部落一定会取得诺森德的统治权。"
D.Strings[14723]="我要返回大德鲁伊莉琳德拉身边。你能送我过去吗？"
D.Strings[14724]="你好啊，$c！欢迎乘坐吻云号。诺森德的环境非常恶劣，希望你已经做好了准备。"
D.Strings[14725]="哦，那么你应该去找本尼克·螺剪。他就在矮人区中心的铁匠铺。"
D.Strings[14726]="沃特尔·索雷夫。盗贼区。他做钥匙。"
D.Strings[14727]="如果你要找锁匠的话，不如去下水道看看？你可以在那里找到许多……名声不太好的家伙。"
D.Strings[14728]="入侵者！你们这些凡人竟敢坏了我的兴致，看我怎么……等等，你们……"
D.Strings[14729]="<你靠近塞瑞利恩，听到他喘息的声音。看样子，如果救治及时，他应该还有机会。>"
D.Strings[14730]="狂妄的小崽子们，竟敢在我的地盘上挑战我？我要亲自碾碎你们！"
D.Strings[14731]="<沃尔科的身躯纹丝不动。当你抬脚要走开的时候，一只手抓住了你的脚踝。他还活着！>"
D.Strings[14732]="<你靠近莎尔蒂，听到她的喉咙中传出一阵微弱的声音。>\n\n请……救救我。"
D.Strings[14733]="<戈沙拉翻滚过来，看着你。你在他的脸上发现了一抹充满希望的微笑。>"
D.Strings[14734]="<当你将巴瑞萨斯瘫软的身体在水中翻转过来的时候，他头顶上一个可怕的伤口赫然出现在你眼前。你立刻明白了他没能撑下去的原因。>"
D.Strings[14735]="<达蒙德的身体埋在浅滩中，神色很安详。>"
D.Strings[14736]="<特伦希斯的眼睛凝望着远方，眨也不眨，其中流露出哀伤的神情。>"
D.Strings[14737]="<当你靠近这名暗夜精灵的时候，她转向你，并朝你伸出手。>\n\n我已经救不活了。我们因为自身的骄傲而得到这样的命运。走吧……也许还有其他人值得你去救。尽量救助他们。\n\n<随着生命的流逝，她的手又垂了下去。>"
D.Strings[14738]="这就是……临死的感觉？\n\n<随着玛芙琳呼吸的终止，这个问题自然也有了答案。>"
D.Strings[14739]="火鸡猎人！"
D.Strings[14740]="火鸡主宰！"
D.Strings[14741]="火鸡大绝杀！"
D.Strings[14742]="维斯派塔斯的角鹰兽可以将你快速送往目的地。"
D.Strings[14743]="火鸡制霸！"
D.Strings[14744]="去找维斯派塔斯吧。他负责管理在泰达希尔底部起落的角鹰兽。"
D.Strings[14745]="我们的家园在大灾变中被摧毁了！$B$B许多幸存者向北流亡，逐步建立起新奥伯丁。而我们留在这里也是有原因的。等到我们治愈了伤口，就要从那些暮光之锤的恶棍手中夺回旧奥伯丁。$B$B希望你能在那时帮助我们消灭那些敌人。"
D.Strings[14746]="在我从达纳苏斯向南方飞行，寻找玛法里奥·怒风的途中，我遇到了这些受伤的旧奥伯丁难民。$B$B我开始帮忙照料这些伤员，但他们的数量太多了，让他们完全恢复需要很长的时间。$B$B相信你也会愿意帮助他们。"
D.Strings[14747]="多年以前，我本想帮助解决本地的鱼人问题，不料却因此而悲惨地丢了性命。但值得欣慰的是我并未如其他灵魂一般前往女神身边，而是得以留在这里继续看着我的家人和朋友。$B$B现在，他们都已经离开，甚至去世了。我留在这里的理由就只剩下了一个。$B$B复仇。"
D.Strings[14748]="需要擦鞋吗，$c？"
D.Strings[14749]="好好保养鞋子啊，$c。"
D.Strings[14750]="来擦擦鞋吧！"
D.Strings[14751]="让我来帮您擦擦鞋吧，$c。"
D.Strings[14752]="真是闪亮啊！"
D.Strings[14753]="又一个体面而又快乐的人，一路顺风，$c！"
D.Strings[14754]="桑迪斯·织风的尸体倒伏在这里。这显然是暮光之锤的诡计造成的。"
D.Strings[14755]="阿图里斯升起了护罩。你必须迅速打断他的法术。"
D.Strings[14756]="冰霜豹已经被麻醉了，静静地躺在地上。"
D.Strings[14757]="拎起冰霜豹的尾巴，检查一下它是雄性还是雌性。"
D.Strings[14758]="这是一头愤怒的雄性野兽！"
D.Strings[14759]="冰爪熊已经被麻醉了，静静地躺在地上。"
D.Strings[14760]="拎起冰爪熊的尾巴，检查一下它是雄性还是雌性。"
D.Strings[14761]="你到外面来干什么？你应该在里面跟蓝龙军团作战！"
D.Strings[14762]="我没有在打架，所以赶紧给我找个人来打！"
D.Strings[14763]="我知道，我知道……“在下水道里钓鱼？”但是如果你知道在这里能钓到什么，一定会大吃一惊的。我还听说有人钓到过鲨鱼，你信不信？"
D.Strings[14764]="这名哨兵的尸体倒在地上，他显然是死在元素攻破这座城镇的战斗中。"
D.Strings[14765]="这里是塔尔丹送上最后一杯饮料的地方。"
D.Strings[14766]="元素没有如此巨大的力量。凯莱斯和她的角鹰兽一定是被另外某个东西打下来的。"
D.Strings[14767]="你要找祖祖的麻烦？没关系……阿瑟里恩在这里，伙计。我们要冲进你们的难民营里去，再去打破你们的新奥伯丁。但首先要死的是你！"
D.Strings[14768]="我不会根据他们的外表去做出判断，而是根据他们的勇气和忠诚。"
D.Strings[14769]="我们真是焦头烂额了。先是没能及时赶到冰冠冰川与我们的部队会合，现在又处在被天灾军团和达卡莱巨魔两面夹击的险境。$B$B我早就跟大领主说过了，来这里根本就是个错误。$B$B看看你能帮帮我们什么忙吧。"
D.Strings[14770]="你听到了吗，$c？元素们哭喊着说，这片土地已经濒临死亡了。达卡莱巨魔正在窃取自己神灵的力量，用以抵御天灾军团。$B$B他们的鼠目寸光终将导致他们自身的毁灭。"
D.Strings[14771]="在目睹了瘟疫之地的凄惨和圣光之愿礼拜堂的血战之后，我以为再也看不到比那些更加恐怖的东西了。$B$B但是我错了。"
D.Strings[14772]="%s开始召唤坍缩之星！"
D.Strings[14773]="群星将为我而战！"
D.Strings[14774]="见证宇宙的怒火吧！"
D.Strings[14775]="我记得你们……在群山中……但是你们……这是怎么回事？我这是在——"
D.Strings[14776]="没用的废物！"
D.Strings[14777]="联盟的第一座塔楼已经被摧毁了！只要我们扫平全部三座塔楼，敌人就不得不撤退了！"
D.Strings[14778]="Lok'tar！第二座塔楼已经被摧毁了！只要我们解决最后一座塔楼，敌人就不得不撤退了！"
D.Strings[14779]="联盟的塔楼全部被摧毁了！他们已经落败。解决残余的敌人！"
D.Strings[14780]="部落的第一座塔楼已经被摧毁了！只要我们扫平全部三座塔楼，敌人就不得不撤退了！"
D.Strings[14781]="第二座塔楼已经被摧毁了！只要我们解决最后一座塔楼，敌人就不得不撤退了！"
D.Strings[14782]="部落的塔楼全部被摧毁了！他们已经落败。解决残余的敌人！"
D.Strings[14783]="必须保卫温室！"
D.Strings[14784]="%s的回路过载了。"
D.Strings[14785]="弗蕾亚开始施放|cFFFF0000大地震颤！|r"
D.Strings[14786]="%s获得了冰冻重击的效果！"
D.Strings[14787]="%s开始施放快速冻结！"
D.Strings[14788]="俗话说狗改不了吃屎。这话说的就是你！"
D.Strings[14789]="这是懦夫的行为！我们应该去把联盟碾碎，就现在！"
D.Strings[14790]="全力赶工，为了部落的荣耀！"
D.Strings[14791]="被遗忘者，如果你赶不上进度，地狱咆哮酋长一定会要了你的脑袋！"
D.Strings[14792]="多么特别啊……你真是很擅长采花。你要送我一支花束吗？哈哈哈哈！"
D.Strings[14793]="%s击碎了珍贵的霍迪尔宝箱！"
D.Strings[14794]="向暗夜致敬！"
D.Strings[14795]="你无法阻止我们，肮脏的$r！"
D.Strings[14796]="小可爱，想尝点儿腐化污染吗？"
D.Strings[14797]="你在这里干什么？！"
D.Strings[14798]="我会碾碎你，小$r！"
D.Strings[14799]="$c，这片森林里到处都是部落。一定要时刻警惕周围的动静！"
D.Strings[14800]="我到这里来是为了不惜一切代价完成主人的命令。还有什么比一个命悬一线的小女孩的生命更加重要？"
D.Strings[14801]="掘地鼠炖肉美味极了。"
D.Strings[14802]="欢迎你，$g先生:女士;。这片营地比我待过的上一个营地要好多了。$B$B很荣幸，我能够和一群出色的战友共事，他们教会了我不少战斗技巧。现在我已经能独立与部落作战了。"
D.Strings[14803]="你好，$c。我们在这里的位置已经暴露了，部落的军队正在南方集结。$B$B我们将非常感激你为我们提供的一切帮助。"
D.Strings[14804]="欢迎，勇士们。我们多次尝试击落她，但是都失败了。你们能不能来帮帮忙，用这些鱼叉炮把她打下来？"
D.Strings[14805]="我还以为我永远都没有办法摆脱那个可怕的诅咒了。陌生人，谢谢你。"
D.Strings[14806]="乐意为你效劳，女士。听说你曾是一把传说之剑的守护者。你能告诉我该去哪儿寻找这把剑吗？"
D.Strings[14807]="收下它吧。再次感谢你，$c。"
D.Strings[14808]="我的耐心已经到头了！"
D.Strings[14809]="这是真的吗？经历了多年的磨难，我竟然还能重获自由？"
D.Strings[14810]="现在，我必须返回湖泊了。"
D.Strings[14811]="|cFF00FFFF生命缚誓者的礼物|r开始生长！"
D.Strings[14812]="天哪！真没想到我还能看到别人！$B$B请一定救我出去！"
D.Strings[14813]="$G先生:女士;，我能为您做什么？"
D.Strings[14814]="你确定要我帮忙对付尤格-萨隆吗？"
D.Strings[14815]="凡人们，感谢你们让我摆脱了弥漫在这片土地上的堕落力量。尽管我尚未完全恢复，但我能帮助你们与尤格-萨隆作战。\n\n我将冰霜之韧赐予你和你的朋友们，以此提高你们造成的伤害并减少敌人对你们的伤害。如果你们当中有谁命悬一线，我可以将他冻结成冰，在短时间内使他免受任何伤害。这一技能需要消耗大量的精力，因此施放后我必须休息一段时间。"
D.Strings[14816]="凡人们，感谢你们让我摆脱了弥漫在这片土地上的堕落力量。尽管我尚未完全恢复，但我能帮助你们与尤格-萨隆作战。\n\n我将自然之韧赐予你和你的朋友们，以此提高你们造成的伤害并提高法术和效果的治疗量。此外，我还可以召唤理智之井，帮助那些意志动摇的队友恢复理智。"
D.Strings[14817]="凡人们，感谢你们让我摆脱了弥漫在这片土地上的堕落力量。尽管我尚未完全恢复，但我能帮助你们与尤格-萨隆作战。\n\n我将发明之速赐予你和你的朋友们，以此提高你们造成的伤害以及移动速度。此外，我还可以扰动那些用萨隆邪铁铸造的生命体的矩阵，降低它们的攻击和施法速度。"
D.Strings[14818]="凡人们，感谢你们让我摆脱了弥漫在这片土地上的堕落力量。尽管我尚未完全恢复，但我能帮助你们与尤格-萨隆作战。\n\n我将风暴之怒赐予你和你的朋友们，以此提高你们造成的伤害以及生命值上限。当你们面对难以摧毁的邪恶时，我会将自己全部的力量汇聚成一道泰坦风暴。即便是神，也会在它的威力下挫骨扬灰。"
D.Strings[14819]="帮助我们作战吧，守护者。只要我们齐心协力，就一定可以击败尤格-萨隆。"
D.Strings[14820]="联盟必死！"
D.Strings[14821]="这些是冬水仙？给我的？"
D.Strings[14822]="已经很久没有手捧鲜花的旅行者到这里来了。"
D.Strings[14823]="这些年来，寂寞萦绕着这面湖泊。旅行者再也不愿涉足此地，而邪恶的力量侵蚀了这片水域。"
D.Strings[14824]="你的礼物传达出珍贵的温情，旅行者。为表谢意，请你收下这把剑。很久以前，另一位旅行者将它赠给了我，不过我几乎用不上。"
D.Strings[14825]="自然的盟友出现了！"
D.Strings[14826]="你准备好骑乘作战了吗？"
D.Strings[14827]="我准备好了！"
D.Strings[14828]="到这里来，$c。我没有太多的时间……"
D.Strings[14829]="这个受了重伤的兽人已经不省人事了。"
D.Strings[14830]="<这具没有了生命的兽人躯体已经不再有任何动作了……>"
D.Strings[14831]="凡人，感谢你让我摆脱了这个诅咒的束缚。请你收下这把剑。"
D.Strings[14832]="它带给我的只有痛苦与灾难。或许你可以找到那个能操控它的力量的人。"
D.Strings[14833]="我把夏日天空战袍弄丢了。"
D.Strings[14834]="我把夏日烈焰战袍弄丢了。"
D.Strings[14835]="真累呀。我要休息一会儿！"
D.Strings[14836]="%s的徽记暴露出来，正在泄漏能量。"
D.Strings[14837]="我们来玩吧！"
D.Strings[14838]="很高兴见到你，$c。$B$B抱歉……我不能和你长谈。我们这里还有一点战斗。"
D.Strings[14839]="如果你准备好带队出动，就告诉我。$B$B我这里还有一些预备队，所以，如果你还需要更多的人，就回来找我。"
D.Strings[14840]="不！不！不！不！不要这样！"
D.Strings[14841]="%s令地面震颤起来。"
D.Strings[14842]="%s开始施放烈焰喷射！"
D.Strings[14843]="史诗级紫色衬衫"
D.Strings[14844]="摇摇虎"
D.Strings[14845]="泡沫塑料剑架"
D.Strings[14846]="角斗士之血"
D.Strings[14847]="维扎克斯将军咆哮着，黑暗的力量在他体内奔涌！"
D.Strings[14848]="可怜的弱者。你的死期不远了！"
D.Strings[14849]="砸扁他们！打碎他们！为了部落的荣耀！"
D.Strings[14850]="我想要那家伙的命！那里的那个家伙看起来有些与众不同！"
D.Strings[14851]="弱小的暗夜精灵，轻易就能战胜！"
D.Strings[14852]="我……我终于从他的魔掌中……解脱了。"
D.Strings[14853]="检测到敌对实体。威胁评定协议启动。向主要目标发动攻击。30秒后重新评估。"
D.Strings[14854]="威胁重新评估结束。目标重新评定完成。改变行动计划。"
D.Strings[14855]="攻击目标修正。改变行动计划。"
D.Strings[14856]="预测到敌对实体的战略。正在变更作战功能。改变行动计划。"
D.Strings[14857]="启动轨道防御。"
D.Strings[14858]="警报：静态防卫系统故障。关闭轨道防御。"
D.Strings[14859]="已启动霍迪尔之怒。正在获取目标。"
D.Strings[14860]="已启动米米尔隆的烈焰。正在获取目标。"
D.Strings[14861]="已启动弗蕾亚的防御结界。正在获取目标。"
D.Strings[14862]="已启动托里姆之锤。正在获取目标。"
D.Strings[14863]="未经认证的实体正在尝试使回路过载。启动反步兵防御措施。"
D.Strings[14864]="%s开始追赶$n。"
D.Strings[14865]="系统故障。正在转换能量以支持系统运行。"
D.Strings[14866]="作战矩阵超载。正在关机……"
D.Strings[14867]="系统需要重启。正在解除武器系统。"
D.Strings[14868]="发生全面系统故障。防御协议已被破坏。正在关闭巨兽单位。"
D.Strings[14869]="已修改威胁评估程序。当前目标威胁级别：0。正在获取新的目标。"
D.Strings[14870]="新玩具？给我的吗？我保证这次不会把它们弄坏了！"
D.Strings[14871]="我……我好像把它弄坏了。"
D.Strings[14872]="好像不能这么用力折它。"
D.Strings[14873]="你们是坏玩具……很……坏。"
D.Strings[14874]="我不喜欢这些玩具了！我不想玩了！"
D.Strings[14875]="艾欧娜尔，您的仆人需要帮助！"
D.Strings[14876]="元素之潮会击垮你们！"
D.Strings[14877]="孩子们，帮帮我！"
D.Strings[14878]="长老们，将你们的力量赐予我！"
D.Strings[14879]="他对我的控制已经不复存在了。我又一次恢复了理智。谢谢你们，英雄们。"
D.Strings[14880]="已启动自动修复程序。"
D.Strings[14881]="现在，我要将圣光之力注入这块水晶，让它揭穿一切谎言与欺瞒的伪装。"
D.Strings[14882]="赐予我们洞悉真相的能力吧。如果凶手就在我们之中，请指引我们寻求正义的裁决。"
D.Strings[14883]="除非精灵滚蛋，否则我就不会工作！"
D.Strings[14884]="精灵在森林里杀了太多的人。我们要留在这个安全的地方。"
D.Strings[14885]="我可不会为一点木头丧命！"
D.Strings[14886]="一团萨隆邪铁蒸汽在附近聚集起来！"
D.Strings[14887]="快点儿，$r。"
D.Strings[14888]="快一点，$c！没时间磨蹭了！$b$b碎木岗哨绝不能失守。"
D.Strings[14889]="萨隆邪铁蒸汽剧烈地旋转着，汇集成一个畸体。"
D.Strings[14890]="你们漂泊得太远了，浪费了太多的时间……"
D.Strings[14891]="快一点！她马上就要挣脱了！"
D.Strings[14892]="保持警惕！钻探机即将冒出地表，讨厌的铁矮人就要来了！"
D.Strings[14893]="你的执着真是令人钦佩。"
D.Strings[14894]="我会毁灭你……就像我毁灭了他那样！"
D.Strings[14895]="啊啊啊！"
D.Strings[14896]="荣耀属于暴风城和乌瑞恩国王！"
D.Strings[14897]="被无情地杀戮……"
D.Strings[14898]="他会明白……没有谁可以永远坐在王位上，只有死亡才是永恒的！"
D.Strings[14899]="天哪，我从来没有想过能亲眼目睹泰坦之城奥杜尔。当布莱恩恳求我资助这支探险队时，我怎么能忍心拒绝呢？！"
D.Strings[14900]="我还以为我们没法逃出那片雾蒙蒙的丛林呢！现在，我是这支探险队的首席工程师啦。"
D.Strings[14901]="这些攻城器械有什么用处？"
D.Strings[14902]="这些宝贝儿看上去跟废铁似的，但是它们可以高速前进，猛烈地撞击敌人。器械前端的撞锤加载了可以施放电能震击的高压电容器。$B$B就连炮塔也升级成了防空火箭，使它比那些破烂攻城车更具优势。"
D.Strings[14903]="我们时间不多了，朋友们！来帮忙测试一下我所发明的最新型、最强大的机体吧。在你们改变主意之前，请允许我提醒一下，你们把XT-002搞得一团糟，应该算是欠我个人情吧。"
D.Strings[14904]="这里汇集了外域最丰富的藏书。即便是银月城的大图书馆也要相形见绌了。$B$B请……尽情享受阅读的乐趣吧。所有的书籍都已分门别类，整理得井井有条。"
D.Strings[14905]="太棒了！测试结果非常好！外壳完整率百分之九十八点九！几乎没有划伤！继续。"
D.Strings[14906]="看呀，VX-001反步兵突击炮，你们也许应该找掩护。"
D.Strings[14907]="一道萨隆邪铁屏障环绕着维扎克斯将军！"
D.Strings[14908]="能找到足够的零件让这些宝贝儿重新运转起来，还真是幸运！$B我能帮你什么忙吗？"
D.Strings[14909]="跟我讲讲攻城车的作用吧。"
D.Strings[14910]="这些宝贝儿能以与众不同的方式投掷弹药。除了副炮和抓升钩，它们还配备了手动燃油喷射系统。如果你从机械侏儒身上找到了液态燃铁，就可以用它发射高密度炸药，或者启动涡轮加速器来提高行进速度。\n\n让我们瞧瞧探险者协会的傻蛋们能不能造出更高档的器械来。"
D.Strings[14911]="你们总算来啦！铁矮人迫使我们撤退到了这里，形势愈发严峻，我们就快撑不住了。\n\n更糟糕的是，他们正在强化魔法防御力量。如果再不主动出击，铁矮人就会在转眼之间将我们杀得片甲不留！\n\n我们设法修复了联盟和部落的远征军留下的部分攻城载具。但是，所有的驾驶员在上一轮攻击中都牺牲了。\n\n你必须驾驶这些器械，攻破奥杜尔的大门！\n\n$n！你是我们最后的希望！"
D.Strings[14912]="我们准备好了。发动攻击吧！"
D.Strings[14913]="完成了。大家都付出了自己该付出的。现在，我将永远封印巨龙之魂。"
D.Strings[14914]="%s深深地吸了一口气……"
D.Strings[14915]="这可怕的光芒……难道是……？"
D.Strings[14916]="是的。必须这样。"
D.Strings[14917]="这是一件与众不同的武器。一件绝无仅有的武器。"
D.Strings[14918]="他的族群没用多久就得到了教训。你们也快了！"
D.Strings[14919]="坏消息，陛下。"
D.Strings[14920]="兽人氏族在黑手的统一指挥下发起了攻击。他们会一致作战，直到暴风城沦陷。"
D.Strings[14921]="古尔丹和他的术士们将在晚上抵达。在那之前，黑石氏族会集中火力攻打东面的城墙。"
D.Strings[14922]="部落的领袖同意你的看法。"
D.Strings[14923]="非常感谢，朋友们！你们的帮助使我获得了一些极其珍贵的数据！下面，我要让你们——咦，我把它放哪去了？哦！这里。"
D.Strings[14924]="是不是很漂亮？我把它称为华丽的空中指挥单位！"
D.Strings[14925]="我们要坚守阵地，等待援军到达。只要勇敢的将士仍在保卫城墙和王庭，暴风城就不会沦陷。"
D.Strings[14926]="老大，我能为你做什么吗？"
D.Strings[14927]="我听说过一两个关于奥达曼看门人的故事，和你的描述很像。你是否也有类似的用途呢？"
D.Strings[14928]="我的用途就是存储这座泰坦之城的重要信息。我的主要功能包括传达前沿防御系统的状况以及评估关押在这座庞大建筑物中的实体的状态。"
D.Strings[14929]="前沿防御系统？在布莱恩派人进入这座城市之前，我需要提醒他什么吗？"
D.Strings[14930]="目前，一切企图进入泰坦之城的行动都将遭到制约。主防御系统处于激活状态。次防御系统处于未激活状态。"
D.Strings[14931]="你能详细描述一下防御系统的性能吗？"
D.Strings[14932]="检测到威胁，已启动安全控制 － 允许查询。"
D.Strings[14933]="明白了。至少我们不用考虑那些轨道炮台。"
D.Strings[14934]="琳蒂安，请立即转告布莱恩和大法师伯塔鲁斯关于防御系统的事儿。"
D.Strings[14935]="被囚禁的实体？是什么实体？目前它处于什么样的状态？"
D.Strings[14936]="个体标识：尤格-萨隆。安全受到威胁。囚犯的行动状态未知。无法联络或通知到守护者。"
D.Strings[14937]="主防御系统包括铁铸像和风暴信标，后者将不断地催生更多的构造体。辅助防御系统包括轨道防御炮台。"
D.Strings[14938]="尤格-萨隆被关押在这里？看来我们有得忙了。"
D.Strings[14939]="%s低声对布莱恩说着什么。"
D.Strings[14940]="银色盟约欢迎你参加锦标赛。银色北伐军委托我们登记并训练那些对比赛感兴趣的选手。"
D.Strings[14941]="控制台显得非常陈旧，却没有一丝破损或是荒废的迹象。上面刻有一道插槽，似乎可以放入大型的圆盘。"
D.Strings[14942]="你做好和勇士战斗的准备了吗？"
D.Strings[14943]="别以为你可以轻而易举地战胜一位勇士。你确定自己已经准备好了吗？"
D.Strings[14944]="你做好与我交战的准备了吗？"
D.Strings[14945]="做好准备吧！"
D.Strings[14946]="小心了！"
D.Strings[14947]="预备！"
D.Strings[14948]="开始！"
D.Strings[14949]="双天赋专精可以让你保留两套职业专精、天赋和雕文方案，你可以在两套方案之间随意切换。\n\n每套专精方案都将拥有独立的雕文面板和动作条。\n\n战斗中不能切换专精，切换后会消耗你的各类可用资源。"
D.Strings[14950]="我该如何学习双天赋专精？"
D.Strings[14951]="看来你还需要多加练习。我们还是下次再打吧。"
D.Strings[14952]="我希望学习双天赋专精。"
D.Strings[14953]="我认输。"
D.Strings[14954]="看来我低估了你的本事。干得不错。"
D.Strings[14955]="胜利是属于我的！"
D.Strings[14956]="要想打败我，你恐怕还得多加练习。"
D.Strings[14957]="我赢了。祝你下次好运，朋友。"
D.Strings[14958]="刚才的战斗很精彩。我认输。"
D.Strings[14959]="等我们以银月城的名义赢下这场锦标赛时，荣耀将属于我们。"
D.Strings[14960]="你现在已经学会了双天赋专精。"
D.Strings[14961]="我们来到这里，为荣耀而战，为名誉而战，为获得与银色北伐军的兄弟们并肩作战的资格而战。"
D.Strings[14962]="麦格尼国王希望我们赢得锦标赛的胜利。我们绝不能失败。"
D.Strings[14963]="诺莫瑞根的精英来参加锦标赛啦。祝我们好运！"
D.Strings[14964]="达纳苏斯的精灵们希望在锦标赛中一展身手。"
D.Strings[14965]="锦标赛开始后，所有人都将见证被遗忘者的胜利。"
D.Strings[14966]="竞争会非常激烈，但是奥格瑞玛的勇士是所向披靡的。"
D.Strings[14967]="我们不仅为荣耀而战，还要为我们的先祖和人民赢得光荣。"
D.Strings[14968]="暗矛氏族已经做好了竞争的准备。"
D.Strings[14969]="我代表夺日者欢迎你参加锦标赛。银色北伐军委托我们登记并训练那些对比赛感兴趣的选手。"
D.Strings[14970]="你做好和银色北伐军勇士作战的准备了吗？"
D.Strings[14971]="当你准备好参加勇士的晋级测试后，我会召来一位银色北伐军的成员。"
D.Strings[14972]="这座竞技场专供冠军们互相切磋之用。我负责召唤骑兵来参加战斗练习。"
D.Strings[14973]="让加文召唤黑骑士。"
D.Strings[14974]="$n向黑骑士发起挑战！"
D.Strings[14975]="祝你好运，$n。"
D.Strings[14976]="生长吧，小家伙。"
D.Strings[14977]="瞧瞧。"
D.Strings[14978]="帮我们抵御这刺骨的寒风吧，小树苗。"
D.Strings[14979]="祝你好运。等广场清理干净后，我就到里面去跟你会合。"
D.Strings[14980]="开始行动，别让那些矮人妨碍我们！"
D.Strings[14981]="给我们一点时间，做好建筑炮台的准备。"
D.Strings[14982]="火灭了！准备重建炮台！"
D.Strings[14983]="你们击败了钢铁议会，打开了档案馆！干得好，伙计们！"
D.Strings[14984]="支持你最喜欢的冠军吧！下一回合时，穿上和他们的代表色一致的衣服，让大家都看看你喜欢谁！"
D.Strings[14985]="你是否已经厌倦了与野兽扭打，想要换个方式来展示自己的本事？无论你来自哪座城市，我都可以满足你的愿望！"
D.Strings[14986]="嘿！瞧瞧这些紧身衣！穿上它，既有了城市的代表色，又省去了宽松的战袍带来的麻烦事儿！"
D.Strings[14987]="本次锦标赛是数个世纪以来最盛大的赛事！买点纪念品回家送给家人和孩子吧！"
D.Strings[14988]="%s吞噬了一个废料机器人以进行自我修复！"
D.Strings[14989]="可以使用鱼叉炮台了！"
D.Strings[14990]="高墙内的秘密远远超越了我们的想象。"
D.Strings[14991]="科隆加恩施放了岩石之握！"
D.Strings[14992]="你做好与冠军作战的准备了吗？"
D.Strings[14993]="别以为你可以轻而易举地战胜一位冠军。你确定自己已经准备好了吗？"
D.Strings[14994]="结束这一切吧！"
D.Strings[14995]="开始分析守护者弗蕾亚的状态。"
D.Strings[14996]="古树仆从的存在增强了守护者的力量。"
D.Strings[14997]="正在分析明叶长老的强化效果……太阳能增效提供了永久的区域性防护力增强。"
D.Strings[14998]="石树长老的分析结果表明，他的声波防御能力足以干扰魔法的使用。"
D.Strings[14999]="铁枝长老的扫描结果显示，存在基于植物功能的移动阻碍机制。"
D.Strings[15000]="另外，我的分析表明，每位古树长老的存在都令弗蕾亚的魔法能力、物理攻击或召唤能力得到增强。"
D.Strings[15001]="摧毁古树仆从可以导致守护者弗蕾亚失去这些增强效果。但是也极可能对弗蕾亚自身及其携带的物品，包括她的守护者徽记，造成永久性的伤害。"
D.Strings[15002]="开始分析守护者托里姆的状态。"
D.Strings[15003]="检测到外部影响。其存在方式是伪装成托里姆已故的配偶西芙。"
D.Strings[15004]="这一外部影响所导致的心智干扰极可能触发局部的记忆损伤。"
D.Strings[15005]="开始分析守护者霍迪尔的状态。"
D.Strings[15006]="霍迪尔的徽记被放在一只用来保存神器的宝箱中。"
D.Strings[15007]="守护者霍迪尔的情绪和行为极度不稳定。如果战斗时间过长，极可能导致宝箱损毁。"
D.Strings[15008]="与盟军协同作战可以提高战斗力，使战斗时长降到最短。"
D.Strings[15009]="开始分析守护者米米尔隆的状态。"
D.Strings[15010]="守护者米米尔隆的徽记与一套自毁系统相关联，该系统又与发明回廊的完整性相关联。"
D.Strings[15011]="这套自毁系统的触发装置被称为“红色大按钮”，由米米尔隆自行制造。"
D.Strings[15012]="要获取米米尔隆的徽记，必须初始化自毁程序，并在流程执行完毕之前击败它。"
D.Strings[15013]="拒绝登录。权限级别不足。"
D.Strings[15014]="已获得档案馆访问权限。入侵保护机制暂停。"
D.Strings[15015]="正在初始化问询。奥尔加隆保险系统是一套在首席管理官死亡时触发的自动化紧急信号系统。"
D.Strings[15016]="正确。首席管理官洛肯被毁灭与信号被激活的时间戳相符。"
D.Strings[15017]="正在搜索……首席管理官的毁灭被判定为系统级行星故障的第一道报警信息。观察者奥尔加隆抵达之后所展开的行星分析，可能产生两种回复代码中的一种。回复代码阿尔法代表“一切正常”；回复代码欧米迦代表“行星结构重组”。"
D.Strings[15018]="行星自身与其所承载的生命体将解离为基础元素：金属、岩石和气体。随后，这些元素将按照最初的行星蓝图完成重组。"
D.Strings[15019]="请求被拒绝。回复代码内建于奥尔加隆的躯体中。他既是信使，也是信号本身。"
D.Strings[15020]="奥尔加隆检测到了侵入关键行星功能的系统级上古之神污染。正在计算产生欧米迦回复代码的几率……"
D.Strings[15021]="百分之九十九点九九。"
D.Strings[15022]="小数点后无限循环。"
D.Strings[15023]="看哪，这就是我们所说的重大发现！"
D.Strings[15024]="我叫你看看我的权限，你这烂机器。瞧好了：诺甘农的钥匙！"
D.Strings[15025]="看起来跟我们找到的其它泰坦档案库也没什么不同嘛，只不过旧了点……大了点。"
D.Strings[15026]="且慢。不对啊！这个一闪一闪的信号灯……奥尔加隆是啥玩意？"
D.Strings[15027]="首席管理官？我在哪里听过这名字来着？对了！洛肯就是艾泽拉斯的首席管理官啊。洛肯的死亡触发了这东西？"
D.Strings[15028]="然后呢？谁在监听这个信号？会发生什么事情吗？"
D.Strings[15029]="行星结构重组？把话说明白点，你这破烂！"
D.Strings[15030]="听到了吗，伙计们？我们的世界要完蛋了！你还等什么啊，破烂机器？快发送回复代码阿尔法。一切正常！尽在掌握中！"
D.Strings[15031]="啊，这个奥尔加隆分析出了什么结果来？我们有多大的几率不被毁灭？"
D.Strings[15032]="真要命啊，伙计们。看来我们有一场硬仗要打了。"
D.Strings[15033]="位移石板被激活并稳定下来了。"
D.Strings[15034]="传送到远征军营地。"
D.Strings[15035]="传送到练兵场。"
D.Strings[15036]="传送到巨人熔炉。"
D.Strings[15037]="传送到废料场。"
D.Strings[15038]="传送到奥杜尔的前厅。"
D.Strings[15039]="传送到破碎步道。"
D.Strings[15040]="传送到生命温室。"
D.Strings[15041]="传送到思想火花。"
D.Strings[15042]="传送到疯狂阶梯。"
D.Strings[15043]="我谨代表银色北伐军，欢迎你参加银色锦标赛。"
D.Strings[15044]="布拉斯波兄弟的建筑工程是速度最快，造价最低、质量最上乘的！"
D.Strings[15045]="%s被永久地禁锢在地面上！"
D.Strings[15046]="新的指令！打开天文馆的大门。"
D.Strings[15047]="四位守护者？徽记？你这废铜烂铁，说话能不能别这么拐弯抹角啊？"
D.Strings[15048]="那我们怎样才能搞到他们的徽记啊？走过去跟他们好声好气地借吗？"
D.Strings[15049]="那你倒是告诉我们怎样才能解除这种威胁啊？"
D.Strings[15050]="多少年来，我做梦都想在泰坦之城游览。没想到今天居然要跟他们创造的东西作战。"
D.Strings[15051]="请求被拒绝。需要四位守护者的徽记进行权限确认。"
D.Strings[15052]="奥杜尔的四位守护者是：弗蕾亚、托里姆、霍迪尔和米米尔隆。他们的徽记与其本体及心智的完整性密切相关。要进入天文台，就必须拥有全部四枚徽记。"
D.Strings[15053]="正在分析守护者的状态。请稍候。"
D.Strings[15054]="检测到腐蚀。外部影响已经控制了守护者。徽记受到威胁。"
D.Strings[15055]="足够的冲击力可以使守护者重启动，消除外部影响。"
D.Strings[15056]="为了在这一过程中不对徽记造成损伤，我可以分析每位守护者的状态，并根据计算结果给出具体建议。"
D.Strings[15057]="能协助布莱恩探索泰坦古城奥杜尔的秘密真是莫大的荣幸。"
D.Strings[15058]="我所知道的关于探险的知识，都是布莱恩教给我的。"
D.Strings[15059]="住手！我认输了！"
D.Strings[15060]="我觉得自己像是从一场噩梦中惊醒过来，但是这里的阴影仍然挥之不去。"
D.Strings[15061]="西芙……西芙在这里吗？不可能——她被我的兄弟杀死了。一场黑暗的噩梦……"
D.Strings[15062]="我需要一些时间仔细思考……如果你们需要我的帮助，请尽管开口。这是我欠你们的人情。保重。"
D.Strings[15063]="你！你这个恶魔，你不是我的爱人！滚开！"
D.Strings[15064]="看吧，这隐藏在一切罪恶幕后的黑手，它覆灭了奥杜尔，将我的王国夷为废墟，腐蚀了我的兄弟，杀害了我的妻子。"
D.Strings[15065]="现在，为我们复仇的重任落到了你们的肩膀上，勇士们。前方的路途依然无比艰险，但我会鼎力相助。你们必须取得胜利。"
D.Strings[15066]="站好了，凝视这耀眼的光芒吧！"
D.Strings[15067]="$c，很高兴见到你。$B$B我负责向候选者传授骑乘近身战的诀窍。"
D.Strings[15068]="教我如何与近战目标作战吧。"
D.Strings[15069]="这是什么，小凡人……$b$b嗯……是$r？我能为你做些什么？"
D.Strings[15070]="初步测试阶段完成。真正的测试开始啦！"
D.Strings[15071]="$c？这是什么？"
D.Strings[15072]="近战目标可以帮助候选者训练骑乘攻击与防御的技巧。$B$B你需要靠近并刺击近战目标。刺击的力量通常会令目标旋转起来，对你或你的坐骑造成伤害。因此，你需要巧妙地利用防御技能。$B$B在攻击目标之前，最好确保自己至少有一层防御效果。在接下来的战斗中，你还需要尽可能地堆叠并刷新防御效果。否则，你很快就会被打下坐骑。$B$B在骑乘实战中遵循着同样的原则：在攻击与防御之间寻求平衡，一有机会就发动刺击，并尽可能保持多层防御效果。"
D.Strings[15073]="嗨，你好！$B$B你是来学习冲锋技巧的吗，$c？"
D.Strings[15074]="教我如何与冲锋目标作战吧。"
D.Strings[15075]="好吧！骑乘冲锋可不仅仅是让你的坐骑高速冲刺，体验那种心飙到嗓子眼的快感……当然这的确是最有趣的部分，嘿嘿！但是冲锋目标可以帮助你掌握更多诀窍。$B$B冲锋的关键在于距离与时机。不能靠得太近，否则无法全力提速。也不能离得太远，否则坐骑就会进入疲惫状态！至于冲锋的时机……$B$B在冲锋之前，你最好确认一下冲锋目标身上是否有防御效果。如果有，你应该先使用碎盾然后再冲锋！$B$B实战中遵循着同样的原则：在冲锋前要尽可能地削弱对手的防御效果！"
D.Strings[15076]="哎呀。又一位$c，你是来学习碎盾的技巧的吗……？"
D.Strings[15077]="教我如何与远程目标作战吧。"
D.Strings[15078]="远程碎盾攻击上手容易精通难。碎盾攻击所能造成的伤害不高，但是配合刺击和冲锋使用就能发挥出完美的效果，令你在骑乘作战中所向披靡。$B$B选定一个远程目标，估算一下碎盾攻击的射程……你需要多远的距离以及你能将长枪掷多远。$B$B接下来，就开始投掷长枪吧，直到你破坏目标身上的所有防御效果。$B$B骑乘实战中遵循着同样的原则：彻底粉碎对手的防御……然后狠狠地揍他们！"
D.Strings[15079]="我们收到了布莱恩的消息，已经开始着手做准备了。"
D.Strings[15080]="达拉然的公民们！抬起你们的头，仰望天空吧！"
D.Strings[15081]="今天，我们所生活的这个世界，险些被它的缔造者毁灭！"
D.Strings[15082]="我们勇敢的伙伴们深入泰坦之城奥杜尔，击败了观察者奥尔加隆，泰坦派来的使者！"
D.Strings[15083]="奥尔加隆前来决定我们这个世界的命运。"
D.Strings[15084]="他发现，在这个世界中，人们并不接受泰坦设计的蓝图。在这个世界中，并非一切都按照计划完美运行。"
D.Strings[15085]="冷酷的逻辑推论出：我们的世界不值得拯救。但是，它并没有考虑到自由意志的力量。我们每一个人都有责任证明，这是一个值得拯救的世界。"
D.Strings[15086]="因为我们的生命……是值得延续的生命。"
D.Strings[15087]="弗蕾亚施放了|cFF00FF00强化钢铁根须！|r"
D.Strings[15088]="%s狂暴了，摧毁了所有生命体！"
D.Strings[15089]="看吧，这创世的神器！"
D.Strings[15090]="你们的行动不合逻辑。这场战斗所有可能产生的结果都已被计算在内。无论结果如何，万神殿都会收到观察者发出的信息。"
D.Strings[15091]="生命的凋零，不可避免。"
D.Strings[15092]="我必须这么做。"
D.Strings[15093]="通过我的双眼来观察你们的世界吧：一个广袤无垠的宇宙，即使是你们当中最睿智的人，也无法理解这一切。"
D.Strings[15094]="我曾见证过无数个世界被造物者的烈焰吞噬，那些世界中的人们甚至来不及发出一声悲鸣就永远消逝了。整个星球从诞生到毁灭，不过是弹指一挥间。但是从始至终，我都没有为之动容……我，毫无，感觉。千亿的生命被毁灭。他们是否都像你们一样坚强？他们是否都像你们一样热爱生命？"
D.Strings[15095]="你们没有时间了！"
D.Strings[15096]="高尔巴格带我游览了达卡莱帝国。我很乐意帮助你征服它！"
D.Strings[15097]="朋友，你来得正是时候。很快我就会给你安排更多的任务了……"
D.Strings[15098]="%s过载了！"
D.Strings[15099]="我狠狠地教训了那些荒芜恶鬼！"
D.Strings[15100]="分析完成。这个星球的生命支持系统受到了部分腐蚀，而防御机制则完全被腐蚀了。"
D.Strings[15101]="我看出来了。荒芜水晶的储量大增，很快就能满足需求了。"
D.Strings[15102]="我已经击败了达穆克！你还需要我做什么吗？"
D.Strings[15103]="达穆克这个饭桶再也不能惹麻烦了！耐心点，朋友。很快就会有更多的工作交给你做了……"
D.Strings[15104]="我已经俘获了达卡莱酋长！你还需要我做什么吗？"
D.Strings[15105]="也许正是这种不完美，才使你们获得了自由的意志，并因此有能力改变那些看起来不可避免的必然命运。泰坦所创造的许多完美生命体都遭遇了失败，而你们仍能继续前行。"
D.Strings[15106]="我已经修改了回复代码，你们的行星得救了。我不能再对自己的计算结果深信不疑了。"
D.Strings[15107]="启动上行通讯：回复代码“欧米迦”。请求启动行星组织重构。"
D.Strings[15108]="再会了，凡人们。你们是不完美的生命体，但你们的勇气值得钦佩。"
D.Strings[15109]="我没有足够的力气去发射信号。你们必须……尽快……找到一处发射场……要靠近天空。"
D.Strings[15110]="我知道该去哪里。你没事吧？"
D.Strings[15111]="不用担心我的命运，布隆赞。如果信号没有及时发射出去，行星结构重组仍然会自行启动。拯救……你们的世界……"
D.Strings[15112]="除掉那些酋长之后，我们就准备发动攻击了！用不了多久的，$n……"
D.Strings[15113]="达库鲁，我亲眼目睹了你精妙的部署。什么时候执行攻占达卡莱帝国的计划呢？"
D.Strings[15114]="朋友，眼下的形势你已经了如指掌了！做好准备吧……我们很快就要发动攻击了！"
D.Strings[15115]="%s张开了大嘴！"
D.Strings[15116]="%s分崩离析了。"
D.Strings[15117]="洛丹伦沦陷时，我正在这里拜访亲戚……唉。我大概再也不能回到西部荒野了。$B$B有时我会思念家人，也不知他们是否依然健在。但是更多的时候，我的内心平静地如同一滩死水，好像没有什么能让我牵挂的了。"
D.Strings[15118]="迁移完成。开始对艾泽拉斯展开行星分析。"
D.Strings[15119]="退后，凡人们。我不是来这里跟你们打架的。"
D.Strings[15120]="如果我的分析结果表明确实存在系统级的污染，对这颗行星进行结构重组无疑是最妥当的方案。不要插手。"
D.Strings[15121]="我这就回档案馆，看看能不能堵塞他的信号。在你们对付他的同时，我努力多争取一点时间。"
D.Strings[15122]="给自己加上防御。$B|TInterface\\Icons\\Ability_Warrior_ShieldMastery.blp:32|t$B然后对近战目标使用刺击。$B|TInterface\\Icons\\INV_Sword_65.blp:32|t"
D.Strings[15123]="庄严地注目它吧！沐浴在它的荣耀中吧！将要出场的是……V-07-TR-0N！"
D.Strings[15124]="对冲锋目标使用碎盾。$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t$B趁目标处于脆弱状态时立即冲锋。$B|TInterface\\Icons\\Ability_Mount_Charger.blp:32|t"
D.Strings[15125]="对远程目标使用碎盾。$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t$B趁目标毫无防御力时再次碎盾。$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t"
D.Strings[15126]="这只碗里散发出强烈的气味，闻起来好象是各种草药和燃烧的毛发混合在一起。"
D.Strings[15127]="通往%s思维的传送门打开了！"
D.Strings[15128]="守护者分析：弗蕾亚"
D.Strings[15129]="守护者分析：霍迪尔"
D.Strings[15130]="守护者分析：托里姆"
D.Strings[15131]="守护者分析：米米尔隆"
D.Strings[15132]="一只风暴爪牙冒出来帮助埃玛尔隆作战！"
D.Strings[15133]="你以为自己能跟不生不死的军团抗衡？"
D.Strings[15134]="反抗……凡人性的瑕疵。"
D.Strings[15135]="你们的失败是命中注定的。"
D.Strings[15136]="你们的毁灭预示着痛苦的新时代即将降临！"
D.Strings[15137]="哦，真正的恐惧还在前方……"
D.Strings[15138]="尤格-萨隆的黑血在我的体内奔涌！我，无坚不摧！"
D.Strings[15139]="看吧，绝对的恐怖！"
D.Strings[15140]="战术分析结果显示，最佳方案为从前方进入竞技场，同时派遣另一支分队通过位于底层的小路。要在外部影响完全控制托里姆的心智之前抵达他所在的高台，这是成功率最高的方案。"
D.Strings[15141]="正在进行碎片分析。"
D.Strings[15142]="目标确认：瓦兰奈尔，远古王者之锤。"
D.Strings[15143]="泰坦亲自铸造了瓦兰奈尔，并将其交给了第一位土灵之王，尤雷尔·石心。通过这柄圣锤，他可以制造新的土灵，并赐予他们生命。"
D.Strings[15144]="在土灵和铁矮人之间爆发的第一次战争中，瓦兰奈尔碎裂了。据信它的残片已在战争中遗失。"
D.Strings[15145]="通过这个世界上实际存在的常规手段修复瓦兰奈尔的可能性趋近于零。正在分析理论上可能存在的修复方式，请稍候。"
D.Strings[15146]="在名为尤格-萨隆的生物体内，理论上存在一种酸性极强的物质，可以将萨隆邪铁液化。泰坦铸成的合金可能通过浸没在此物质中重新熔合。"
D.Strings[15147]="来得正是时候。我们赶紧搞定这件事吧。"
D.Strings[15148]="看起来我的计算有一点小小的偏差。监狱中的恶魔侵蚀了我的思维，篡改了我的主要指令。所有系统都已恢复正常。完毕。"
D.Strings[15149]="你必须骑上锦标赛坐骑，我才能教你如何骑乘作战。$B$B拿上一支长枪，然后从你所在阵营的兽栏中挑选一匹坐骑吧。"
D.Strings[15150]="我想知道更多关于防御和刺击的技巧。"
D.Strings[15151]="我想知道更多关于碎盾的技巧。"
D.Strings[15152]="我想知道更多关于冲锋的技巧。"
D.Strings[15153]="想要坐骑吗？"
D.Strings[15154]="我能帮你做些什么？"
D.Strings[15155]="很高兴见到你。"
D.Strings[15156]="在找坐骑吗？"
D.Strings[15157]="你好，$c。"
D.Strings[15158]="有一点冷，你觉得呢？"
D.Strings[15159]="很高兴看到你平安无事。"
D.Strings[15160]="只有暴风城的勇士才有资格从我这里购买物品。"
D.Strings[15161]="你的死亡将是一个新生命的开端！"
D.Strings[15162]="主人，温室已经被攻破了！"
D.Strings[15163]="急什么呢，$r！$B$B只有铁炉堡的勇士才有资格从我这里购买物品。"
D.Strings[15164]="肥料。"
D.Strings[15165]="你的尸体将滋养这片土地。"
D.Strings[15166]="很抱歉，$r。只有雷霆崖的勇士才有资格从我这里购买物品。"
D.Strings[15167]="主人，我不行了！"
D.Strings[15168]="走吧，$r！$B$B只有幽暗城的勇士才有资格从我这里购买物品。"
D.Strings[15169]="凡人不许进入这里！"
D.Strings[15170]="从哪里来，就回哪里去！"
D.Strings[15171]="弗蕾亚！他们冲你来了。"
D.Strings[15172]="只有奥格瑞玛的勇士才有资格从我这里购买物品。"
D.Strings[15173]="只有埃索达的勇士才有资格从我这里购买物品。"
D.Strings[15174]="这里将成为你们的墓地。"
D.Strings[15175]="真是浪费……"
D.Strings[15176]="嗨，朋友！$B$B很抱歉，只有诺莫瑞根的勇士才有资格从我这里购买物品。"
D.Strings[15177]="主人，快逃！他们非常残忍！"
D.Strings[15178]="哎呀，只有达纳苏斯的勇士才有资格从我这里购买物品。"
D.Strings[15179]="萨玛巴认为你找错了军需官！$B$B只有森金村的勇士才有资格从她这里购买物品。"
D.Strings[15180]="我要把你彻底捏碎！"
D.Strings[15181]="哎呀，只有银月城的勇士才有资格从我这里购买物品。"
D.Strings[15182]="主人，他们来了……"
D.Strings[15183]="我是不可战胜的！"
D.Strings[15184]="不疼不痒！"
D.Strings[15185]="只是轻伤而已！"
D.Strings[15186]="我们成功了，伙计们！终于抢在奥尔加隆前面来到了这里。也许我们可以对系统做点手脚，改变他的分析结果——"
D.Strings[15187]="%s激活了野性防御者！"
D.Strings[15188]="你的血肉将不再属于你！"
D.Strings[15189]="我说过了，在你吃尸体前都先给我好好搜查一下！"
D.Strings[15190]="要把每块石头都翻一遍。执行我的命令，不许有半点折扣，烂家伙！如果有必要，就把这个地方翻个底朝天。"
D.Strings[15191]="下马来，敢不敢和我单挑！"
D.Strings[15192]="%s准备施放暗影强化！"
D.Strings[15193]="不行。我完全搞不明白这玩意儿是如何运作的。"
D.Strings[15194]="我不会让你失望的，主人！"
D.Strings[15195]="别灰心。如果这确实是传送器的话，那它对我们的进攻行动会很有帮助的。"
D.Strings[15196]="嗯，我知道……我会继续尝试的。不过你也别抱太大的希望，这种科技完全超越了我能理解的范围。"
D.Strings[15197]="你们微不足道的抵抗只能让我变得更加强大。"
D.Strings[15198]="感谢大家参加此次布道会。看到这么多熟悉的面孔真是令人欣慰！"
D.Strings[15199]="今天，我要谈谈圣光的三大美德。"
D.Strings[15200]="对我们来说，这是一个黑暗而艰苦的时代。天灾军团盘踞在南方。那些在战场上牺牲的勇士们，转瞬间就沦为了敌人的爪牙。"
D.Strings[15201]="柯尼拉，你能告诉我些什么？"
D.Strings[15202]="你们中的大多数都体会过被背叛的苦楚。"
D.Strings[15203]="但是你们坚持了下来，我们也必须这样做。在这个时代，人们不应该对坚韧这一美德感到陌生。面对绝望与仇恨，我们仍然要坚守自己的信仰并继续战斗。"
D.Strings[15204]="暂时这样就可以了。那座塔呢？奥萨拉克斯怎么样了？"
D.Strings[15205]="毫无疑问，你们拥有坚韧的意志……但是我们也不能忽略其它的美德。"
D.Strings[15206]="尊重，是所有踏上圣光之路的人们应该首先学习的美德。"
D.Strings[15207]="走廊对面，就是那些被你们视为敌人的家伙。尽管仇恨让彼此疏远，但是他们依然拥有值得你们尊重的品德。他们的勇气就值得钦佩。"
D.Strings[15208]="在场诸位都懂得荣誉之战的概念吧。对战时光明磊落是谓尊重，公平地对待敌人是谓尊重。"
D.Strings[15209]="在战场上，无论你的对手是兄弟还是宿敌，都要予以同样的尊重。即便你们的信仰不同，这种尊重依然能在你们之间建立某种联系……"
D.Strings[15210]="这就是你为我找到的？我要的是数量、地点还有目的——我们现在简直是两眼一抹黑。赶快去完成任务！"
D.Strings[15211]="……而认可这种联系，你们就会更接近圣光。"
D.Strings[15212]="要在圣光之路上更进一步，我们还必须学会同情。"
D.Strings[15213]="我们置身于竞争与对抗的年代。无论你们走到哪里，都能看见分歧与争执。"
D.Strings[15214]="如何看透本质并寻求共同点，是我们面临的挑战。唯有理解，才能让你们对他人所遭受的痛楚产生同情……"
D.Strings[15215]="……即使是对那些身处不同阵营的牺牲者。"
D.Strings[15216]="一旦感受并理解这种对敌对友一视同仁的同情，你们就重申了自己与世界的联系。"
D.Strings[15217]="只要我们奉行这些原则与美德，这个世界就会变成彼此向往的美好世界。荣耀而正义的世界。"
D.Strings[15218]="好好想想我的话吧，朋友们。黑暗笼罩着我们，人们更加需要圣光的指引。"
D.Strings[15219]="那些投石车仍然无法使用。我已经烧毁了几辆投石车，并破坏了其余的。"
D.Strings[15220]="我……我不知道。在那片废墟里有不寻常的动静。"
D.Strings[15221]="如果有谁想找我谈谈，我就在忏悔室的屏风后面等着你们。我很乐意为大家排解疑问、忧虑和彷徨。"
D.Strings[15222]="他们这群蠢货，竟然以为我们是软弱可欺的。这些巨魔已经没有希望了——今天将在我们手中结束。"
D.Strings[15223]="你成功地击败了那只金属怪物。看来面前的障碍已经不多啦。$B$B一旦除掉前厅尽头的机器人，我们就能进入奥杜尔了。$B$B我们还发现了一头巨型喷火始祖龙和一个熔化的巨人。不过他们并没有挡住我们的去路，如果你想避开它们也没有问题。"
D.Strings[15224]="你能不能使出点真本事来？"
D.Strings[15225]="不要退缩！干掉他们！"
D.Strings[15226]="欢迎你参加锦标赛，$n。"
D.Strings[15227]="很高兴能在这里见到你，$n。"
D.Strings[15228]="嘿，你们为什么要这么做啊？没看到上面写着“不要按这个按钮”吗？你们激活了自毁系统，还怎么完成测试呀？"
D.Strings[15229]="我想接受钓鱼训练。"
D.Strings[15230]="我估算了一下胜出的概率，发现这种可能性低得要命！"
D.Strings[15231]="在让长枪保持最精确的角度并让盾牌处于任何时候都能提供最佳保护的位置的同时我还怎么算得清该为机械陆行鸟加载多大的电荷！"
D.Strings[15232]="……而且有些坐骑可以把我踩扁！"
D.Strings[15233]="振作点。体型不是问题，关键在于你的作战技巧。"
D.Strings[15234]="体型上的劣势可以用信心和专注来弥补，小家伙。圣光与你同在。"
D.Strings[15235]="我在来这里的路上殴打了一只企鹅。"
D.Strings[15236]="哈哈，骗你的。我只是想看看你脸上的表情。"
D.Strings[15237]="天哪。你连一点怜悯之心都没有吗？"
D.Strings[15238]="姑娘，我要向你坦白一件事。"
D.Strings[15239]="我有一种……冲动。"
D.Strings[15240]="我在听你布道时，心中涌起了一股强烈的情感，我快疯掉了！"
D.Strings[15241]="……我想喝一杯！"
D.Strings[15242]="那就喝上几杯吧，我的矮人朋友。不过你最好先上缴你的长枪和缰绳。圣光与你同在。"
D.Strings[15243]="我的心情一天比一天沉重，神官。"
D.Strings[15244]="我被派来这里，以暴风城的名义作战。但是我所做的一切都毫无意义。"
D.Strings[15245]="在赛场之外，天灾军团仍在肆意破坏着我们的家园。那里才是真正的战场。而我，应该前往真正的战场。"
D.Strings[15246]="我怎么能留在这里，让那些需要我来保护的人们惨死呢？"
D.Strings[15247]="你有一副好心肠，我知道你想要侍奉圣光。但是战场上的厮杀难以撼动天灾军团的首脑。"
D.Strings[15248]="锦标赛的目的就是要建立一支强大而团结的军队，虽然这个目标看上去并不十分明确。待到一切准备就绪，北伐军以及麾下所有勇士的目光就会转向冰冠冰川了。"
D.Strings[15249]="我们将集结所有的力量向巫妖王发动攻击，而他，注定会失败。"
D.Strings[15250]="我知道你对此尚有疑惑，但是这会让你更加接近圣光。战斗吧，我的兄弟。"
D.Strings[15251]="初始化自毁程序。"
D.Strings[15252]="这根本不是荣耀之战。我渴望挥舞战斧，浴血沙场！"
D.Strings[15253]="他们都是我的敌人。在战场上，你也会是我的敌人！你们的国王已经向我族宣战了！"
D.Strings[15254]="我却不能像同胞们一样浴血奋战。我能做的，只是端着一根笨重的长枪，哄着座狼朝对手发起冲锋，根本就不是真正的攻击。"
D.Strings[15255]="这就不是兽人的作战方式！酋长的命令与个人的荣耀令我左右为难。我不信仰圣光，但是你看起来像是个不错的顾问，我想听听你的建议。"
D.Strings[15256]="本区域将在六分钟后自毁。"
D.Strings[15257]="本区域将在五分钟后自毁。"
D.Strings[15258]="本区域将在四分钟后自毁。"
D.Strings[15259]="本区域将在三分钟后自毁。"
D.Strings[15260]="本区域将在二分钟后自毁。"
D.Strings[15261]="本区域将在一分钟后自毁。"
D.Strings[15262]="自毁程序确认启动。祝你愉快！"
D.Strings[15263]="本区域将在七分钟后自毁。"
D.Strings[15264]="本区域将在八分钟后自毁。"
D.Strings[15265]="本区域将在九分钟后自毁。"
D.Strings[15266]="本区域将在十分钟后自毁。"
D.Strings[15267]="自毁程序已中断。过载代码A-9-0-5。"
D.Strings[15268]="我理解你沮丧的心情。兽人作战时都非常勇猛，你一定不习惯锦标赛的方式。"
D.Strings[15269]="但是这依然是另一种形式的荣耀之战。你或许并不认可，但是我相信大家都目睹了你所表现出来的强大力量。"
D.Strings[15270]="而且……战斧的确很有杀伤力，但是长枪也不赖啊。"
D.Strings[15271]="没完没了的战斗。我不知道自己还能坚持多久。"
D.Strings[15272]="赛场上这种装腔作势的打斗……根本毫无意义。有什么用呢？"
D.Strings[15273]="而且我的发型都被头盔压扁了。真是太滑稽了！"
D.Strings[15274]="这看起来可能毫无意义，但是你可以试着在战斗中找到尊严。你迟早会发现这些练习的价值的。"
D.Strings[15275]="而且你的发型看起来很棒。"
D.Strings[15276]="幻象消散，通往中央房间的道路开启了！"
D.Strings[15277]="训练并骑乘毒皮暴掠龙需要耗费大量精力。"
D.Strings[15278]="哦，天哪！我没想到有人要来！工作间里真是一片狼藉。真丢人啊。"
D.Strings[15279]="我可以修好它……也许不行！呀，真是一团糟……"
D.Strings[15280]="真棒。我想他们应该是把这个叫做“完美击杀”。"
D.Strings[15281]="我得记下来：火炮对血肉之躯非常有效。"
D.Strings[15282]="你败了！"
D.Strings[15283]="你的表现应该比这更好！"
D.Strings[15284]="哦，天哪！我们好像已经超时了，朋友们。"
D.Strings[15285]="大胆！今天就要以尔等的鲜血，为曾用来改造这个世界的武器淬火！"
D.Strings[15286]="觉醒吧，钢铁熔炉中的兵士！执行造物者的意志！"
D.Strings[15287]="我要烧尽尔等的杂质！"
D.Strings[15288]="让烈焰吞噬尔等的身躯！"
D.Strings[15289]="燃烧吧！在造物者的烈火中燃烧吧！"
D.Strings[15290]="废料堆上又多了些渣滓。"
D.Strings[15291]="尔等的骨骸可做燃料。"
D.Strings[15292]="我……失败了。"
D.Strings[15293]="任你是天下最厉害的恶棍，还是最强大的英雄，都只不过是凡人之躯。"
D.Strings[15294]="可怜的家伙！"
D.Strings[15295]="雷暴之云在空中聚结，降下死亡之雨吧！"
D.Strings[15296]="风暴的力量仍将长存。"
D.Strings[15297]="你们盲目地冲进了疯狂之喉！"
D.Strings[15298]="你们这些入侵者，休想轻易击败钢铁议会！"
D.Strings[15299]="真是不堪一击！"
D.Strings[15300]="血肉……碍事的东西。"
D.Strings[15301]="你们想要探寻奥杜尔的秘密？那就拿去吧！"
D.Strings[15302]="我的死只会加速你们的灭亡。"
D.Strings[15303]="只有把你们全部消灭才能解恨。"
D.Strings[15304]="又一个无关紧要的损失。"
D.Strings[15305]="傲慢的代价就是死亡。"
D.Strings[15306]="破译这个看看！"
D.Strings[15307]="面对猛烈的闪电吧！"
D.Strings[15308]="风暴的传统不容破坏。"
D.Strings[15309]="你们击败了我，又能得到什么呢？厄运依然会降临到你们这些凡人头上。"
D.Strings[15310]="钢铁议会的正事都被你们耽搁了！"
D.Strings[15311]="你要为你的罪行受到惩罚！"
D.Strings[15312]="悲剧。千辛万苦，功亏一篑。"
D.Strings[15313]="欢迎进入无尽的寒冬。"
D.Strings[15314]="北地的寒风会将你吞噬！"
D.Strings[15315]="够了！了结这一切吧！"
D.Strings[15316]="有些东西，最好永远都不去碰！"
D.Strings[15317]="救命啊！别让它们靠近我！"
D.Strings[15318]="你们想把我怎么样？别过来！"
D.Strings[15319]="对！没错！不要手下留情！不要停止攻击！"
D.Strings[15320]="让仇恨和愤怒指引你们战斗吧！"
D.Strings[15321]="攻击这头野兽要害的时刻即将来临！将你们的愤怒和仇恨倾泻到它的爪牙身上！"
D.Strings[15322]="被你们自己的仇恨吞噬吧！"
D.Strings[15323]="战栗吧，凡人们，末日就要来临了！"
D.Strings[15324]="毫无力量……"
D.Strings[15325]="他们没救了吗？"
D.Strings[15326]="我是清醒的梦境。"
D.Strings[15327]="你们噩梦中的怪物。"
D.Strings[15328]="千面的恶魔。"
D.Strings[15329]="死人是不会泄密的。"
D.Strings[15330]="在我的真正形态面前颤抖吧。"
D.Strings[15331]="在死亡之神的面前屈服吧！"
D.Strings[15332]="你们在浪费我的时间！"
D.Strings[15333]="意志薄弱的蠢货！"
D.Strings[15334]="凝视死亡的真正面孔吧，你们的末日就要来了！"
D.Strings[15335]="疯狂将把你彻底吞噬！"
D.Strings[15336]="永恒的痛苦在等待着你！"
D.Strings[15337]="你的意志不属于你自己。"
D.Strings[15338]="我的奴仆，快去毁灭他们！这是主人的命令！"
D.Strings[15339]="你们的命运早已注定。末日即将降临于这个可笑而渺小的世界，你们所有人都要灭亡。Uulwi ifis halahs gag erh'ongg w'ssh."
D.Strings[15340]="寒冬将会庇护你们，勇士们！"
D.Strings[15341]="艾欧娜尔，请祝福您的仆人！"
D.Strings[15342]="战斗矩阵已强化。全速突击！"
D.Strings[15343]="高戈奈斯，将您的威能赐予我！让我的战友们获得雷霆的力量！"
D.Strings[15344]="银色北伐军的骑兵是如何作战的？"
D.Strings[15345]="银色北伐军的骑兵将攻击和防御巧妙地结合起来，在作战中实现平衡与精准。$B$B但是，由于他们需要时刻与你保持距离，因此你可以伺机冲锋。$B$B你必须抢在他们之前发起冲锋，拉近彼此的距离，接下来在围绕他们跑动的过程中使用碎盾并看准机会使用刺击。"
D.Strings[15346]="欢迎来到这座圣光礼拜堂。请坐。愿你暂时远离痛苦的尘世，享受片刻的宁静。"
D.Strings[15347]="让我们开始吧，$r。$b$b我们的时间不多了，但还有很多事要做。"
D.Strings[15348]="今天你已经战胜了一位骑兵，我不能再接受你的挑战了。"
D.Strings[15349]="你是来听神官布道的吗？但愿你还能找到座位……"
D.Strings[15350]="联盟占领了东部火花车间！"
D.Strings[15351]="联盟占领了西部火花车间！"
D.Strings[15352]="部落占领了东部火花车间！"
D.Strings[15353]="部落占领了西部火花车间！"
D.Strings[15354]="联盟正在进攻东部火花车间！"
D.Strings[15355]="部落正在进攻东部火花车间！"
D.Strings[15356]="联盟正在进攻西部火花车间！"
D.Strings[15357]="部落正在进攻西部火花车间！"
D.Strings[15358]="我的女士。$b$b我没有能保护她。我又怎么能回到银月城……"
D.Strings[15359]="如你所愿，$n。"
D.Strings[15360]="激活辅助防御系统后，轨道炮台将消灭所有未经认证的生命体。$B$B你属于未经认证的生命体。请确认。"
D.Strings[15361]="激活辅助防御系统。"
D.Strings[15362]="已确认。"
D.Strings[15363]="允许安全控制。辅助防御系统已激活。$B$B可以通过广场上的独立能源塔关闭这些辅助系统。"
D.Strings[15364]="能在锦标赛中代表银色北伐军出场真是无上的荣耀。"
D.Strings[15365]="银色锦标赛在冰冠冰川的北部边界拉开了帷幕，$c。如果你不知道怎么去哪儿，我可以免费送你一程。$B$B我们积累的作战经验越多，在面对巫妖王时胜算也就更大。"
D.Strings[15366]="我要飞过去。"
D.Strings[15367]="手下留情？不行！"
D.Strings[15368]="这一下你就别想再站起来啦，朋友。"
D.Strings[15369]="%s开始施放恐吓尖啸。"
D.Strings[15370]="欢迎，孩子。"
D.Strings[15371]="我不应该期待这些肮脏的巨魔永远地安于和平。同情部落者绝不能信任。"
D.Strings[15372]="%s开始施放大爆炸！"
D.Strings[15373]="鲜血与雷鸣,$n!"
D.Strings[15374]="我们要面对许多危险，但我们不能因此而忽视自然。这样的话，自然将会在我们有所需要时舍我们而去。我们曾经有过这样的教训。"
D.Strings[15375]="阻挡自然者即是异端，即便在自然发挥它破坏之力时亦然如此。$B$B但如今要摧毁黑海岸的并非自然的力量。我不会让这片土地分崩离析。"
D.Strings[15376]="你好啊，我是盖瑞。相信一定是高尔博德派你来的。\n\n如果你要来帮忙，那么你要做的事情相当简单。我装配了一些诱饵机器人。我们可以把它们放在鱼人附近，然后开启它们的倒数计时系统。它们会闪动光芒，发出声音，引诱那些鱼人过来。几秒钟之后，它们就会爆炸，把那些鱼人一并炸飞。\n\n如果我们在那里放置足够多的诱饵机器人，我们就应该能再次进入船舱。希望这次我们的人员伤亡会少一些。当然，进入船舱的任务和你没有关系。先去炸飞那些小鱼人吧！"
D.Strings[15377]="当那些元素拼命要扯碎黑海岸的时候，我竭尽全力想要保护住剩下的自然生命。$B$B$c，我能得到你的帮助吗？"
D.Strings[15378]="不要乱动，小冒险者。我这里有你正在寻找的死亡。"
D.Strings[15379]="安静，小东西，这样你就能听到这片古老的土地在说话。它正在痛苦地呼号。"
D.Strings[15380]="嗯，这么年轻就拥有了如此强大的力量，这可真是惊人。你一定能以联盟的名义杀死无数敌人。但必须记住，在伟大的循环之中，生具有和死一样强大的力量。$B$B<安努缓缓地伸手到自己的头顶，摘下一颗不显眼的橡实，然后以从容不迫的姿态将手放在你面前>$B$B它有着特别的力量。$B$B……很抱歉，希望你不会认为我这是在自吹自擂。"
D.Strings[15381]="小$r，来看看我们是不是能把敌人冻住。"
D.Strings[15382]="我们的兄弟迷失了。他烧焦了大地，蒸发了水体，吞噬了太多空气。$B$B帮助我们让他回复平衡与和谐吧。"
D.Strings[15383]="%s开始施放宇宙重击！"
D.Strings[15384]="这里无路可逃！只有我的岩浆的热烈拥抱！"
D.Strings[15385]="死亡从下方升起，从上面爆发！无人可以逃脱！"
D.Strings[15386]="烧焦大地，蒸干流水，点燃天空！"
D.Strings[15387]="大地之环无法抵挡我的愤怒！"
D.Strings[15388]="我的奴仆们，毁灭他们！"
D.Strings[15389]="我已经挣脱了大地的束缚，我绝不会再回去！"
D.Strings[15390]="灰谷将陷入火海！"
D.Strings[15391]="就像飞蛾投火！"
D.Strings[15392]="<*轰隆*轰隆*轰隆*>"
D.Strings[15393]="%s使一个风暴爪牙超载了！"
D.Strings[15394]="感谢你帮助我们保护这里的自然生命。希望一切都还不至于太晚。"
D.Strings[15395]="感谢你的帮助，$n！这片森林中潜藏的邪恶从没有彻底消失过，但知道有你这样的英雄帮助我守护这里，我的感觉就好多了。"
D.Strings[15396]="希望能多告诉你一些这方面的事情。现在已经几乎没有人相信还有这种生物存在了。古久以前，泰坦将艾泽拉斯塑造成我们今天所看到的这个世界，生与死的循环于焉建立。但在此之前，统治这里的是上古之神和服从于他们的元素。为了实现邪恶的目的，他们腐蚀这里的一切造物。$B$B安努告诉我，上古之神最终被泰坦击败，被囚禁在大地之下。这样的怪物真的有可能死亡吗？我希望自己能知道得更多一些，尽管这些都已经是超越了历史的故事。为此，我做了相当长时间的研究。$B$B我知道现在存在着对上古之神的崇拜，无论这是多么难以相信的事情。那些崇拜者似乎正在祈求这个世界的毁灭。上古之神的确是能够让人们发狂！"
D.Strings[15397]="<这只幼崽死盯着你，仿佛想分辨出你是不是它的妈妈。>"
D.Strings[15398]="%s大口吞咽着食物。"
D.Strings[15399]="%s抓起食物，一口吞了下去。"
D.Strings[15400]="%s用它强壮的颚撕咬着食物。"
D.Strings[15401]="%s很快就把食物吃了个干净，它焦急地四处看着，好像还没吃饱。"
D.Strings[15402]="放弃挖掘？这太荒谬了！在我漫长而勤勉的一生中，我还从没有放弃过一个发掘点。也许我有勘探错误的时候，但从不曾有意放弃过任何值得挖掘的地方。你又是谁？我们在这里做什么？"
D.Strings[15403]="我们的挖掘计划已经不可能完成了——探险者协会要我们尽量收集一切有价值的物品，然后离开。说的容易，做起来可不容易。"
D.Strings[15404]="鱼人，呸！"
D.Strings[15405]="巫妖王的残酷统治让所有诺森德的居民们都饱受痛苦，尤其是那些孩子。如果你是索拉查盆地的狂心氏族或是神谕者的朋友，也许你会考虑抚养他们的一位孤儿，陪那个小家伙一周。"
D.Strings[15406]="能给我们点陈年蛋黄吃吗？"
D.Strings[15407]="难道连造物主的包包也满了吗？"
D.Strings[15408]="你觉得小狗狗人为什么总追问我们是否同情拉弗乌呢？拉弗乌的确很多话，但他是我们的好朋友。"
D.Strings[15409]="那么$n，你能给我们个哨子吗？这样我们想你的时候吹吹哨子就能见到你了，好吗？"
D.Strings[15410]="也许我们长大了会成为$r呢。是不是呀？"
D.Strings[15411]="你也是因为狗狗人才变成孤儿了吗？"
D.Strings[15412]="你得离海象人远点。他们会弄痛你。"
D.Strings[15413]="科科要带你去打猎。你是个不错的诱饵。"
D.Strings[15414]="兽人们总是嘲笑科科，科科迟早会让他们好看。"
D.Strings[15415]="你知道吗？要是科科闭上眼，你就看不到他了。"
D.Strings[15416]="抓三只小鸡来当午饭。不过我赌你连毛都碰不到。"
D.Strings[15417]="科科带来了大舌头怪幼崽最喜欢的玩具。也许它能让你晚上睡个好觉。"
D.Strings[15418]="询问那些孤儿的事情。"
D.Strings[15419]="我们接收的这些孤儿都来自于被战火焚毁的索拉查盆地。你可以选择照料一个神谕者或者是一个狂心氏族的孤儿。不管怎样，他们都会为了能结识一个新朋友而高兴。但你只能照顾他们之中的一个人。"
D.Strings[15420]="$r，我们的任务绝不止于守卫这棵树。部落不会善罢甘休。$B$B我们必须消灭他们！"
D.Strings[15421]="我们到了！如果这是世界之树，那他们把整个世界放进这里的时候，它不会被撑破吗？"
D.Strings[15422]="当大地被撕裂之后，我一直在帮助飞行管理员寻找逃散的角鹰兽。直到现在，我们的鸟还是无法真正安定下来。"
D.Strings[15423]="接受风之拥抱的祝福吧。愿你从奥达希尔开始的旅程因这祝福而更加顺利。"
D.Strings[15424]="你相信总有一天，科科会带领狂心氏族回家，就像熊人赢得最终的胜利夺回树城那样。科科想要自己的家，而不是遍布紫人的城市，更不是大舌头怪出没的丛林。"
D.Strings[15425]="看啊！那是我们吗？我们觉得那是我们。只是好像有一点老？"
D.Strings[15426]="我们也许真的得到了造物主的祝福！也许有一天，圣坛的魔法会把我们变成大神谕者？"
D.Strings[15427]="看啊！那一定是强大的战士科科！看到了吧？科科说什么来着。"
D.Strings[15428]="你能感觉到吗？$B$B灵魂世界在悼念日中距离我们更近了。所以我们要用鲜花和蜡烛装饰逝去亲友的坟墓，并告诉他们：欢迎回来，虽然只有片刻。$B$B所以，来吧！和我一起跳舞！让我们纪念那些已经和我们天人永隔的亲人。让逝者同我们一起享用美食，一起微笑。让他们知道，关爱永不逝去。"
D.Strings[15429]="在悼念日，人们会聚集在墓地，追忆、告慰那些逝者的亡魂。$B$B届时任何主城的墓地都会举行这个仪式，在那里有悼念日食品、舞蹈、化装聚会和其他活动。"
D.Strings[15430]="我们有了一个新朋友！"
D.Strings[15431]="想看看我能做些什么吗？"
D.Strings[15432]="我们也能跳舞！"
D.Strings[15433]="一起来跳舞吧！"
D.Strings[15434]="看！"
D.Strings[15435]="你的样子还不错！"
D.Strings[15436]="你回来啦！"
D.Strings[15437]="这场雪仗打得真精彩！"
D.Strings[15438]="最好小心一些！"
D.Strings[15439]="我要将这些物资运到十字路口，这事关我的荣誉。如果你不想帮忙，就站开一些。"
D.Strings[15440]="好吧，$n，准备好了吗？这可不容易啊！"
D.Strings[15441]="她就是红龙女王？嗯……我们一直以为她应该更大一些。"
D.Strings[15442]="她怎么和其他的龙一点也不像？她真的可以变成一头巨大的龙吗？"
D.Strings[15443]="嗯……尊贵的殿下，你愿意为我们变成一条龙吗？"
D.Strings[15444]="好啊……就现在吧？"
D.Strings[15445]="如果我变回红龙形态。这里就装不下其他人了，小家伙。"
D.Strings[15446]="嗯……那个科科已经非常老了。而狂心氏族的首领一定要更老一些。这很不错。作为战士和首领，科科有着美好的未来。科科很高兴你能带他参观这里。孤儿院的阿姨从不带科科来。"
D.Strings[15447]="艾露恩指引我们，$c。"
D.Strings[15448]="我们绝不能向敌人让出一寸土地。如果他们进攻黑海岸，我们就把他们打回去。我们要像保卫达纳苏斯一样保卫这里。"
D.Strings[15449]="筑巢符文在哪里？"
D.Strings[15450]="天蓝之石在哪里？"
D.Strings[15451]="黑色羽毛在哪里？"
D.Strings[15452]="鸦爪神符在哪里？"
D.Strings[15453]="奥本·怒爪在哪里？"
D.Strings[15454]="筑巢符文就在这座桥另一端，南边房间里的上层部分。"
D.Strings[15455]="天蓝之石就在北边房间里下层部分的小房间中。"
D.Strings[15456]="黑色羽毛就在南边房间里下层部分的坡道尽头。"
D.Strings[15457]="鸦爪神符就在北边房间里上层部分的露台上。"
D.Strings[15458]="奥本·怒爪就在双桥之一所通向的西边房间里，靠近离开兽穴的走廊。"
D.Strings[15459]="科科还以为我们会看到红龙女王。但那只是个长着可爱犄角的女精灵。"
D.Strings[15460]="但这到底该怎样解释？龙巨大而强猛。精灵女士却弱不禁风。科科想要看到红龙女王真正的样貌。"
D.Strings[15461]="放心吧，科科，她就是红龙女王。我们在和他们一同工作的时候，经常会变成更小的躯体。"
D.Strings[15462]="哦！现在科科明白了。科科不想被强大的女王捏扁。也许等这里不太挤的时候，科科还会回来。不管怎样，很高兴见到你，女王。"
D.Strings[15463]="薄雾会引领道路。"
D.Strings[15464]="出口在西北方……薄雾会引领道路。"
D.Strings[15465]="你能带我去出口吗？"
D.Strings[15466]="喔！真正的造物主？我们完全没有想到索乌塞遇到过一个真正的造物主！"
D.Strings[15467]="呃，你好，造物主。见到你是我们的荣幸。"
D.Strings[15468]="你睡着了吗，造物主？我们知道，为了收集我们留给你的所有好东西，一定费了很大力气。"
D.Strings[15469]="我们为你带来了一件礼物，造物主。也许你在醒来的时候会看到它。也许你会记得我们来看过你，是吗？"
D.Strings[15470]="该死的猪！你们的胖脑袋里只有一团肥肉！"
D.Strings[15471]="没错！死吧，害虫！部落将彻底消灭你们。"
D.Strings[15472]="能够再度和亲友一起欢庆，彼此分享旧日的故事，这种感觉实在太好了。"
D.Strings[15473]="喔！科科终于找到赫米特·奈辛瓦里了！"
D.Strings[15474]="在你来到索拉查以后，就连狂心氏族也知道了你的事情。也许你能教科科两招？"
D.Strings[15475]="好啊，小伙子，你可以从阅读《荆棘谷的青山》开始。然后，也许你能和我一同参加行动，你觉得如何？"
D.Strings[15476]="科科不知道阅读有什么用。科科不会阅读，但如果赫米特·奈辛瓦里要科科这样做，科科就会努力去做。"
D.Strings[15477]="也许你最终会彻底放弃，但现在，你还需要坚持。"
D.Strings[15478]="<喷鼻息>懦夫就是这么战斗的吗，$r！"
D.Strings[15479]="我们的一些女猎人已经去过班尼希尔兽穴。当你在那里的时候，她们会找到你。去和辛塔瑞谈谈，从她那里取得坐骑吧。"
D.Strings[15480]="那些野猪人总是在我们的营地边缘劫掠食物和供给物资。难道他们现在竟然直接对我们的农场和家园发动攻击了？他们这种疯狂的行为一定是有原因的。"
D.Strings[15481]="<这头野猪人用他黑珠子一样的眼睛紧盯着你。>"
D.Strings[15482]="<这头野猪人抽着鼻子，一边哼哼，一边嗅着你。>"
D.Strings[15483]="怎么样，$r？想干什么就干吧。"
D.Strings[15484]="我们是骄傲的战士，$n。<哼哼>数量还很多。"
D.Strings[15485]="嗨，你好！"
D.Strings[15486]="<熊怪闻闻你，哼了两声。>"
D.Strings[15487]="$c，在你的一生中，你肯定有过一段做学生的时光。从导师那里学习知识，并想要为导师争光，对不对？我不是指具体的某个人，但导师肯定是比你知道更多，而且愿意教导你的人。不过，要不是这样呢？想象一下……$b$b如果你发现，你的导师所知道的也许并不如你想象的那样多，你也许能找到更好的办法提升自己，你又会怎样做？"
D.Strings[15488]="这可真糟糕！我不应该无所事事地坐在这里。需要我去做的事情实在太多了！要不是我的胳膊在诺森德受了伤……但现在抱怨这种事是没用的！塔胡会帮我包扎好，并治好我。虽然有伤，但是我们还能帮上点忙。\n\n虽然不在前线，但这并不意味着我们就要混吃等死。"
D.Strings[15489]="又是一张新面孔？很高兴见到你，我是德林拉尔。"
D.Strings[15490]="哦，$n！我的兄弟巴尔格告诉我，你在科多兽背上的表现可谓是百发百中。这支运输队能从前沿哨所安全地来到这里，你可是立了一大功。$B$B听着，我知道你在格罗多姆还有很多工作要做……不过我更希望你能够继续护送运输队前往十字路口。$B$B做好准备以后再来找我吧！"
D.Strings[15491]="我曾经不断地将各种辎重和食物从奥格瑞玛拖送到十字路口，那可是件繁重的工作。现在我的脖子总会因为那时的劳累而隐隐作痛。"
D.Strings[15492]="自从海加尔山之战以来，我们的族人已经改变了许多。"
D.Strings[15493]="诺达希尔的力量曾经败过阿克蒙德，击退了燃烧军团的入侵，但它只剩下了一个苍白的影子。"
D.Strings[15494]="我们的不朽力量，我们的生命的精华——已经丢失了。"
D.Strings[15495]="那名叛徒已经离开了他的牢狱，大导师怒风则消失在翡翠梦境里。"
D.Strings[15496]="这是一个黑暗的时代。"
D.Strings[15497]="随着玛法里奥·怒风的离开，德鲁伊陷入混乱，迫切需要一名新的领导者。"
D.Strings[15498]="大德鲁伊范达尔·鹿盔唤醒了德鲁伊，并说服黑海岸的古树议会，让他们相信现在正是吾族重建之时。"
D.Strings[15499]="为了让我族重新获得不朽，在得到议会的同意之后，鹿盔率领最强大的德鲁伊们培育出泰达希尔。你正站在它的枝干上。"
D.Strings[15500]="虽然我们已经有了新的家园，我们不朽的生命却依然没有得到恢复。"
D.Strings[15501]="大德鲁伊造访了巨龙，祈望他们祝福新生的生命之树，就如同他们在上古时代祝福诺达希尔那样。"
D.Strings[15502]="时光之王诺兹多姆拒绝给予他的祝福，并谴责了德鲁伊的傲慢。"
D.Strings[15503]="但为了遵守上古的契约，阿莱克丝塔萨也拒绝了鹿盔。没有她的祝福，泰达希尔的成长出现了无可预期的瑕疵。"
D.Strings[15504]="鹿盔回到了他在达纳苏斯的领地里，开始寻找能够祝福泰达希尔，让我族恢复不朽的新方法。"
D.Strings[15505]="随着时光的推移，鹿盔只是同我们的族人变得越来越疏离。"
D.Strings[15506]="有些人认为他在责怪我们，责怪他的族人。因为他在很久以前的流沙之战中失去了儿子。"
D.Strings[15507]="还有谣言说，他和我族的光芒，达纳苏斯的领袖泰兰德·语风之间出现了越来越多的矛盾。"
D.Strings[15508]="但许多塞纳里奥议会的德鲁伊仍然坚信，范达尔在全心全意为卡多雷的福祉而努力。他们全都会不惜一切代价地效忠于他。"
D.Strings[15509]="范达尔·鹿盔独力担负了我们的原罪和愚行，因此，他应该得到我们全体暗夜精灵的尊敬。"
D.Strings[15510]="几周前，泰达希尔上的所有生灵都发现的自己记忆开始变得模糊，仿佛时间偷走了他们的一部分生命。"
D.Strings[15511]="迷雾终于散去之后，我们却发现范达尔·鹿盔和他的许多最亲近的追随者都在悄然间消失了。"
D.Strings[15512]="而大德鲁伊怒风已经从梦境中醒来，回到了他所钟爱的泰兰德·语风身边。"
D.Strings[15513]="当他回归时，阿莱克丝塔萨和伊瑟拉也一同到来，并最终将他们的祝福赐予泰达希尔。"
D.Strings[15514]="虽然还残留有少量急需清除的腐化物，但泰达希尔似乎已经开始萌生新枝了。新生已然开始。"
D.Strings[15515]="没有人知道以后会发生什么，但随着玛法里奥和泰兰德的重新结合，卡多雷又有了新的希望。"
D.Strings[15516]="你准备好了吗，$n？"
D.Strings[15517]="%s凝望着月亮井，似乎是迷失在遥远的记忆中。"
D.Strings[15518]="卡多雷的幻影闭上眼睛，渐渐消失了。"
D.Strings[15519]="随着你一步步靠近，%s变成一个具体的形态，并点头向你致意。"
D.Strings[15520]="%s在月亮井旁边，陷入了沉思。"
D.Strings[15521]="%s缓步靠近月亮井，一种熟悉的，若有所思的神情出现在它的脸上。"
D.Strings[15522]="随着它逐渐靠近，%s向你露出了胸有成竹的微笑。"
D.Strings[15523]="$n，小心！"
D.Strings[15524]="你好啊，$r。"
D.Strings[15525]="森林的拯救者！如果不是你的英勇行为，阿斯特兰纳和灰谷一定会落进燃烧军团的手中。$B$B希望你诸事顺利，$n！"
D.Strings[15526]="荣耀之地"
D.Strings[15527]="塞纳留斯之路"
D.Strings[15528]="食人魔皮纳塔"
D.Strings[15529]="魔法公鸡坐骑"
D.Strings[15530]="嘿，你是怎么找到我的？看来我要找一个更好的藏身地了。"
D.Strings[15531]="你的名字叫做$n？这对于熊怪来说可真是个奇怪的名字。$B$B看来你不是从灰谷来的。"
D.Strings[15532]="<奥塔·旺的眼睛本已经因为饱受奴役而变得灰暗。听到你的方案，它们重新闪烁出光芒。你感觉到达图尔魔棒的力量通过你传到了这只熊怪的身上。>$B$B你要反抗吗？"
D.Strings[15533]="<一道奇怪的光芒在奥塔·旺的眼中闪过。他挺起身子，向天空发出咆哮。>$B$B我们会奋起抗争！摧毁我们的枷锁！"
D.Strings[15534]="$c，深吸一口气。雷鸣峰顶的空气非常稀薄，不过这里毕竟没有下面那种呛鼻子的尘土。"
D.Strings[15535]="小朋友，能帮个忙吗？"
D.Strings[15536]="$c，请不要刺激格高。我们应该做的是观察和报告情况，而不是引起一场骚乱。"
D.Strings[15537]="偷偷摸摸，鬼鬼祟祟。让我告诉你关于格高的事：格高从来不会躲躲藏藏。"
D.Strings[15538]="嘿，头儿，我相信这次晋升一定让你很高兴吧？$B$B我们全都认为只有你能代替那个恶心的老加里维克斯，得到贸易$g大王:女王;的头衔。虽然你从没有听我这样说过！$B$B我们还有许多事要做，但时间却很少。希望你已经做好了准备。"
D.Strings[15539]="嗨，$r。最近有什么赚钱的买卖吗？"
D.Strings[15540]="这些猴子真让人头痛！"
D.Strings[15541]="什么？$n，你不是个术士。$B$B我不可能教导你这样的$c，$g先生:女士;。"
D.Strings[15542]="$n，很高兴你在这里。或许我能教你一两招。$B$B你觉得怎么样，$g先生:小姐;？"
D.Strings[15543]="不管怎样，我怀疑你不会想接受我的训练，$n。我不确定你的手指能不能控制好火焰箭。"
D.Strings[15544]="你能相信这些猴子吗，$n？"
D.Strings[15545]="哦，你来得正好……未来的元素大师！今天你想接受怎样的训练？"
D.Strings[15546]="即使不是牧师也可以缴纳什一税，你的金币一样受欢迎，$g先生:女士;。"
D.Strings[15547]="我很惊讶，$n，像你这样的$c竟然能看到我。我正在专心潜行呢！"
D.Strings[15548]="%s开始施放|cFFFFFFFF光明漩涡！|r切换到|cFFFFFFFF光明|r 精粹！"
D.Strings[15549]="%s开始施放|cFF9932CD黑暗漩涡！|r切换到|cFF9932CD黑暗|r 精粹！"
D.Strings[15550]="$R，我要你的脑袋。"
D.Strings[15551]="需要有人帮你找到路吗？我对这个地方可以说是了如指掌。"
D.Strings[15552]="你终于来了。喜欢这里的风景吗？"
D.Strings[15553]="看到那些熊怪的堕落，我感到非常伤心。他们曾经是我们的朋友。"
D.Strings[15554]="这个地方已经遭到了污染……我们需要带着那些圣物尽快离开这里。"
D.Strings[15555]="我还没有看到那些沉眠的德鲁伊。他们一定是已经被带走了。"
D.Strings[15556]="我应该预见到今天的景象。这种污染已经扩散了相当长的一段时间。"
D.Strings[15557]="如果熊怪会变成今天这种样子，那么泰达希尔其余的地方又会是怎样？"
D.Strings[15558]="一定有办法阻止这种污染将我们全部吞噬。"
D.Strings[15559]="诅咒你，范达尔！你怎么会培育出这种受诅咒的“世界之树”？"
D.Strings[15560]="$n？我听说你已经死了。"
D.Strings[15561]="<那个喝醉的工程师对你眨着惺忪的醉眼。>"
D.Strings[15562]="如果这只绿色的大怪物在五秒钟之内不安静下来，我就要聋掉了。我知道该如何操纵这家伙。我可不是白痴！"
D.Strings[15563]="呆子，如果不是我在这里，泽匹克会让我们直接撞上悬崖。"
D.Strings[15564]="如果你不介意这些沙尘，那这就是一次很不错的旅行。"
D.Strings[15565]="离这道悬崖远一点，我可不想看到你摔下去。"
D.Strings[15566]="我干活呢。"
D.Strings[15567]="<工程师一头栽倒在地。>"
D.Strings[15568]="嘿，我正在休息。"
D.Strings[15569]="欢迎登上西风号飞艇。搭乘它，你能以最快的速度穿越贫瘠之地。请坐下来，尽情享受飞行的乐趣吧。没有什么能比干燥的空气混合上汽油味更好闻的了。"
D.Strings[15570]="嘘！有人在这里。"
D.Strings[15571]="不要误会我的意思……我很高兴玛法里奥能回来，但这实在太令人怀疑了。范达尔出了什么事？"
D.Strings[15572]="我是图维。我的工作就是维护这里的和平，警惕敌人的入侵。所以我一直保持着最高度的警觉。"
D.Strings[15573]="那里有一只鸟！"
D.Strings[15574]="那团云看上去就像是个大酋长。"
D.Strings[15575]="小心那艘船！一个鹰身人！……等等，那只不过是一只鸟。"
D.Strings[15576]="那里有一只虫子。"
D.Strings[15577]="奥格瑞玛还是那么的巍峨和险峻。赶快休息一下吧，孩子，一会就要返回雷霆崖了！"
D.Strings[15578]="下一站，雷霆崖！"
D.Strings[15579]="小心！你应该不会想摔成一团肉酱吧。欢迎来到雷霆崖！"
D.Strings[15580]="好吧，孩子们，让我们飞越奥格瑞玛！"
D.Strings[15581]="小心。小心！我已经感到颤动了！你差一点就要把那座塔撞塌了，呆子！"
D.Strings[15582]="我们的进度已经落后了！转向东方！东方！"
D.Strings[15583]="我已经准备好前往班尼希尔兽穴了。"
D.Strings[15584]="别傻站着，泽匹克！我们可不能把一整天的时间都花在它上面！"
D.Strings[15585]="嗨，甜心。停泊在这里的飞艇会把你一直送到雷霆崖，而且是免费的。有我们地精在，又会有谁想去骑双足飞龙？"
D.Strings[15586]="前往雷霆崖的飞艇到达了！全体登船，我们要迅速飞越贫瘠之地！"
D.Strings[15587]="你相信吗？他们终于解除了这个地方的禁制，让我们的飞艇能够穿越这里的天空了！这里不再是飞行禁区了。毕竟，我们在测试飞行中只不过让一艘飞艇撞上了崖壁。我完全不明白他们到底在担心什么。"
D.Strings[15588]="做好准备！前往奥格瑞玛的飞艇已经到达！全体登船，目标杜隆塔尔！"
D.Strings[15589]="你在看什么，$r？想要折磨囚犯吗？"
D.Strings[15590]="<巴隆举起他的镣铐。>$B$B好吧，$c。你信任我吗？"
D.Strings[15591]="怎么样？你没有脑袋可以踢，没有宝藏可以挖吗？"
D.Strings[15592]="你好，$n。如果你想要接受烹饪训练，那你就找对地方了。当感恩节进行的时候，我经常会有很多新学生。"
D.Strings[15593]="如果你想对感恩节的节日传统有更多了解，就和那些女侍应们聊聊天吧。"
D.Strings[15594]="我需要接受训练。"
D.Strings[15595]="我们饿了！"
D.Strings[15596]="你来到这里是为了和我们一起庆祝感恩节吗？"
D.Strings[15597]="%s释放了一股吸血虫群来治疗自己！"
D.Strings[15598]="%s钻入了地下！"
D.Strings[15599]="别和我开玩笑，$r。"
D.Strings[15600]="欢迎，你是来和我们一起享受感恩节的吗？请坐到盛宴餐桌旁来。$B$B试试这里的每一样食品吧！我相信，这里一定会有你喜欢的东西。"
D.Strings[15601]="感恩节。嗯，我明白这些牛头人都渴望着向部落酋长表达他们的感激和情谊。但亡灵呢？$B$B我还以为他们早就丢弃了这种多愁善感的传统。"
D.Strings[15602]="有人告诉我，在感恩节之中，我们要做的就是纵情狂欢，并和周围的人们分享我们的快乐。$B$B我们幸运地找到了这个世界和这里勇敢的居民。我们应该全无保留地将我们的知识和力量与我们新的盟友分享。"
D.Strings[15603]="人类总是把身子裹在那种破烂的亚麻口袋里。不过他们的确知道该如何烹调美食。感恩节？那可是我的最爱！"
D.Strings[15604]="感恩节？倒不如说是“蠢猪节！”$B$B成千上百箱食物就这样被白白送出去了……居然一个子儿也不收！肯定是脑子进水了！$B$B不过呢，我想我应该将我的一部分家禽投资转移到火鸡上去……我无法相信那笔鸡肉投资竟然有这么大规模。那么多复活节蛋到底是从哪里来的？！"
D.Strings[15605]="感恩节是人们纵情狂欢，并与你周围的朋友分享快乐的节日。$B$B我们希望，在这个节日里，我们所有高贵的朋友们都能加入到庆祝的行列中来。"
D.Strings[15606]="这样的节日和人类的风格实在是有着巨大的反差。有谁会想到，贪婪无情的人类竟然会举办一个表达赠与和分享的节日？$B$B我很高兴看到这样欢乐的景象。达纳苏斯会不遗余力地支持这一活动。"
D.Strings[15607]="兽人和牛头人能够在这个世界上彼此找到，成为伙伴，这对他们来说实在是一件幸运的事。这两个种族有着不相上下的强猛力量。我们很高兴能和他们一起庆祝这个节日。$B$B就连被遗忘者一族也参加了这次节日庆典。虽然我并不确定他们要怎样庆祝这个节日……"
D.Strings[15608]="感恩节是人们纵情狂欢，并与你周围的朋友分享快乐的节日。$B$B在莫高雷和部落中间，我们都找到了家的感觉和亲密的朋友，来共同享用各种美好的果实。$B$B我们希望，在这个节日里，我们所有的朋友都能加入到庆祝的行列中来。"
D.Strings[15609]="那些牛头人真的很懂得什么叫美食！你有没有看见过他们做的那些菜？$B$B我要一直吃到把自己撑死……然后再从坟墓里爬出来，重新开始吃！"
D.Strings[15610]="盛宴餐桌是什么？能吃吗？"
D.Strings[15611]="一张盛宴餐桌上放着五种感恩节美食。每一份都放在一把座椅前面。$B$B坐进这些椅子里，你就能随心所欲地大吃面前的美食，并将这些美食传递给其它椅子中的朋友。能够和朋友共享的快乐才是真正的快乐！$B$B如果你吃足任何一种食物，你就能从这种食物中获得独特的好处。$B$B另外，如果你将每种食物都吃得足够多，你就能得到分享之魂！"
D.Strings[15612]="<你面前的这个巨魔从头到脚都是伤疤。一道新伤口横亘在他的脸上，豁开了他的嘴唇。>$B$B你好！$B$B巨魔把恐龙当坐骑。但与野生恐龙进行交流，并进一步训练它们是个难题！所以我会到这里来。我是一名恐龙训练师。"
D.Strings[15613]="小心那些恐龙，它们可能非常非常聪明。$B$B上个星期，两头恐龙吸引了我的注意力，而第三头恐龙却用一根棒子偷袭我。"
D.Strings[15614]="该死，被你逮到了！"
D.Strings[15615]="什么？好啊，好啊……我会把欠你的钱还给你，混蛋！"
D.Strings[15616]="%s哼哼着放弃了挣扎，显然是认输了。"
D.Strings[15617]="不要打脸，不要打脸！"
D.Strings[15618]="$n$G先生:女士;，很高兴看到你。$B$B希望你能喜欢卡亚可乐的营销战役。我们正在计划进行一系列大规模的爆破行动，为战役的下一个阶段铺平道路。这一招对我们的目标客户群总是很有效。"
D.Strings[15619]="你会在灵魂高地的西部边缘，飞艇停泊处附近找到克伦德尔。我可不喜欢看到那种地精机器从这里飞过去……但它的确能把你送到奥格瑞玛去，只要你在那上面没吐到晕过去。在奥格瑞玛，你可以搭乘一艘飞艇前往东部王国的幽暗城或者银月城，或者另一艘前往诺森德的战歌要塞。"
D.Strings[15620]="真正的十字军绝不仅仅是在战场上对抗邪恶……十字军是一个榜样，一面正义的旗帜，是大众心中一名坚不可摧的守护者。$B$B作为高阶十字军，我的责任就是向这样的战士们分派各种值得他们去完成的任务。"
D.Strings[15621]="银月城的血精灵为$n而欢呼。"
D.Strings[15622]="埃索达的德莱尼人为$n而欢呼。"
D.Strings[15623]="铁炉堡的矮人为$n而欢呼。"
D.Strings[15624]="诺莫瑞根的侏儒为$n而欢呼。"
D.Strings[15625]="暴风城的人类为$n而欢呼。"
D.Strings[15626]="达纳苏斯的暗夜精灵为$n而欢呼。"
D.Strings[15627]="奥格瑞玛的兽人为$n而欢呼。"
D.Strings[15628]="雷霆崖的牛头人为$n而欢呼。"
D.Strings[15629]="森金村的巨魔开始颂唱歌曲，为$n而庆祝。"
D.Strings[15630]="幽暗城的被遗忘者为$n而欢呼。"
D.Strings[15631]="别想……抓住我！"
D.Strings[15632]="不！"
D.Strings[15633]="“吼！”"
D.Strings[15634]="别杀我！"
D.Strings[15635]="丝网拦不住我！不……网把我拦住了。"
D.Strings[15636]="我们不害怕！"
D.Strings[15637]="有些奖励只会赠予那些赢得了银色北伐军及其盟友的崇拜，获得了十字军头衔的战士。$B$B提里奥亲自授命令我寻找这样的英雄，并赐予他们应得的奖章。"
D.Strings[15638]="联盟的成员们为$n而欢呼。"
D.Strings[15639]="部落的成员们为$n而欢呼。"
D.Strings[15640]="%s碰到$n后开始沸腾！"
D.Strings[15641]="大门被打破了！保卫要塞！"
D.Strings[15642]="欢迎，勇士！你是否已经做好准备，打算迎接十字军的试炼的挑战了？"
D.Strings[15643]="是的，我们已经准备好了迎接即将到来的挑战。"
D.Strings[15644]="那么，你是否准备好了接受第一个挑战？"
D.Strings[15645]="开始第一场挑战吧！"
D.Strings[15646]="他们正在屠杀囚犯！赶快行动，去援救其他人。"
D.Strings[15647]="我还以为自己再也无法活着离开这里了！"
D.Strings[15648]="我还以为我要死在那里了！"
D.Strings[15649]="我早就知道，我不应该到这场锦标赛来！"
D.Strings[15650]="%s创造出了一个虚空传送门！"
D.Strings[15651]="%s创造出了一个|cFF00FF00地狱火山！|r"
D.Strings[15652]="$n中了|cFFFF0000军团烈焰！|r"
D.Strings[15653]="$n受到了|cFF00FFFF血肉成灰|r效果的影响！"
D.Strings[15654]="那些猛兽实在是令人惊愕。被他们打败绝不是什么羞耻的事情。"
D.Strings[15655]="你干得真漂亮！等你再次准备好以后，就立刻通知我。"
D.Strings[15656]="你还不具备足够的力量来参与征服之岛的战斗。等你获得更多经验以后再回来吧。"
D.Strings[15657]="征服之岛上有许多非常重要的物资，我们绝不能让它落入部落的手中。你愿意加入我们的战斗吗？"
D.Strings[15658]="征服之岛上有许多非常重要的物资，我们绝不能让它落入联盟的手中。你愿意加入我们的战斗吗？"
D.Strings[15659]="我想要一副合成酿酒护目镜。"
D.Strings[15660]="我们希望所有人都会在美酒节中得到乐趣。如果能让人记住它就更好了。$b$b这副眼镜能够让每一个人都体验到喝醉时的感觉，却不必喝下许多烈酒。带上这副眼镜吧，这样你就喝醉了！只要摘下它，你就能立刻恢复清醒！$b$b你对这副眼镜有兴趣吗？"
D.Strings[15661]="你刚才说什么？"
D.Strings[15662]="想要踏入战场，你还没有足够的阅历。$c。等你获得更多经验以后再回来吧。"
D.Strings[15663]="你是否已经准备好了为部落而战，$c？"
D.Strings[15664]="你是否已经准备好了为联盟而战，$c？"
D.Strings[15665]="你竟敢挑战德罗丁·洛斯加尔，诸海之王？"
D.Strings[15666]="全体登上飞行战舰！做好开火准备！"
D.Strings[15667]="好，那么，让我们开始吧。"
D.Strings[15668]="只要敢于面对，即使是最黑暗的回忆也将不再可怕！"
D.Strings[15669]="真是精彩！"
D.Strings[15670]="请向骄傲而强壮的暴风城总冠军，雅克布·奥勒留斯元帅欢呼吧！"
D.Strings[15671]="今天，矮人的力量将在铁炉堡的总冠军，拉娜·硬锤的身上得以展现！"
D.Strings[15672]="从大门中走出来的是克罗索斯，埃索达强大的总冠军！"
D.Strings[15673]="现在出场的是矮小却极度致命的安布罗斯·雷钉，诺莫瑞根的总冠军！"
D.Strings[15674]="进入竞技场的是达纳苏斯的总冠军，战技非凡的娅琳·永歌！"
D.Strings[15675]="干得好！你竟然打败了所有这些猛兽，这简直太神奇了！不过，我听说下一个挑战将更加艰难！"
D.Strings[15676]="有什么新的挑战正等待着我们？"
D.Strings[15677]="现在我们暂时压制住了加拉克苏斯大王，但我们不可能压制住他太长时间。"
D.Strings[15678]="敌人将有多么强大，你很快就会知道了。现在，你是否已经准备好了迎接下一场挑战？"
D.Strings[15679]="嗨！我看起来如何？"
D.Strings[15680]="这太好了，一定及时给我信号，让我知道该在什么时候放下那些法术。"
D.Strings[15681]="银色盟约们很高兴地在此介绍他们的斗士，大领主。"
D.Strings[15682]="夺日者们自豪地介绍他们在这场竞赛中的代表。"
D.Strings[15683]="我可真喜欢你！你相信我？是吗？"
D.Strings[15684]="我真想念你！你到哪里去了？$B$B你真的不愿意理我吗？"
D.Strings[15685]="你喜欢我的这身打扮吗？这可是为聚会准备的。我用你的帐户买的。"
D.Strings[15686]="又有个家伙打了我。哦，这可真让人气恼！$B$B你愿意帮我打他一顿吗，甜心？谢谢，我真爱你！"
D.Strings[15687]="我全心全意地期待着你晋升到顶点的那一天。想一想，那时我就是贸易大王的太太。$B$B我还能去买下我一直想买的所有东西！！！"
D.Strings[15688]="小心。我听说这片海湾里有南海海盗。$B$B嗯，也许我应该亲自去查看一下……"
D.Strings[15689]="我们能在卡亚罗山的顶端渡过一个美好、浪漫的野餐日吗？$B$B一定要带我喜欢的香槟来！"
D.Strings[15690]="你的眼睛里有一种恶作剧的意味。你想要干什么？$B$B嗯？"
D.Strings[15691]="甜心，你去哪里了？你是否知道，当我无法联系到你的时候，是多么担心吗！"
D.Strings[15692]="你觉得我的腹肌如何，亲爱的？我刚刚从健身馆回来。$B$B现在我够健美了吧！"
D.Strings[15693]="其他那些女人只是普通朋友，亲爱的。"
D.Strings[15694]="我喜欢你的衣服！"
D.Strings[15695]="我知道，昨晚和前天晚上我都答应过你。等到明天晚上，我一定会带你去个好地方！"
D.Strings[15696]="听说早些时候南海海盗进入了港口。如果你要进城的话，一定要小心！$B$B那些海盗之中甚至还有女人！嗯，也许我应该亲自去查看一下？这只是为了保护你的安全，亲爱的。"
D.Strings[15697]="我热辣的公司总监女朋友今天过得如何？既然你已经在管理这么多事情。我想，我们随时都有可能会改称你为贸易女王$n了！我真期待那一天的到来！那样我就能随心所欲地在健身馆健身，在池塘边把皮肤晒成健美的褐色了。"
D.Strings[15698]="嗨，头儿。这批巨魔奴隶可是我见过的最糟糕的一批！$B$B幸运的是，卡亚矿石似乎并没有让他们的豆腐渣脑子变得更聪明一些，对不对？"
D.Strings[15699]="终于……现在我能够休息了。"
D.Strings[15700]="我的噩梦终于结束了？"
D.Strings[15701]="这真可怕……我梦见我正在和自己的朋友作战。"
D.Strings[15702]="我听不到那些尖叫声了。一切都结束了吗？"
D.Strings[15703]="我累坏了，让我先休息一下。"
D.Strings[15704]="%s一下撞到演武场的墙壁，晕了过去！"
D.Strings[15705]="%s爆发出狂烈的怒气，他面前的战士转眼间就被他踩在脚下！"
D.Strings[15706]="$c，是否已经准备好了迎接第一个挑战？"
D.Strings[15707]="欢迎，勇士们。今天，在你们的领袖与族人面前，你们将证明自己强大的实力。"
D.Strings[15708]="我对这些游戏可没什么兴趣，提里奥。不过……我相信它们一定很精彩。"
D.Strings[15709]="感觉如何？哈！我很喜欢看着你们这些弱小的勇士是怎样失败的，人类。"
D.Strings[15710]="加尔鲁什，够了。"
D.Strings[15711]="打得好，部落！Lok'tar Ogar！"
D.Strings[15712]="终于出现了一场值得一看的战斗。"
D.Strings[15713]="我到这里来不是为了看野兽们无意义地彼此撕扯，提里奥。"
D.Strings[15714]="你首先会与这场锦标赛的三名总冠军作战。这些强大的战士已经把他们的对手都一一击败了。"
D.Strings[15715]="你要学习如何驾驭坐骑？"
D.Strings[15716]="多年以来，我一直在这个被世界遗忘的角落里工作着，查看这里的地形，在无聊中打发时间。但我的时代终会到来的。奥格瑞玛正将全部力量转向艾萨拉，我们打开了通往灰谷的通道，并终将统治这片大陆。欢迎来到前线，$c。"
D.Strings[15717]="现在请注意，强大的奥格瑞姆总冠军，碎颅者莫克拉出场！"
D.Strings[15718]="进入竞技场的是削瘦却极度危险的祖尔托，森金村的总冠军！"
D.Strings[15719]="高高地骑坐在科多兽上的是雷霆崖的总冠军，令人敬畏的鲁诺克·蛮鬃！"
D.Strings[15720]="我们现在要介绍的是幽暗城的总冠军，强韧的亡灵，死亡猎手维赛里！"
D.Strings[15721]="从大门中走出来的是埃蕾希·晨歌，强大的法师！银月城总冠军！"
D.Strings[15722]="语法错误行14，序列：逃命。进入被动模式。*点击！*"
D.Strings[15723]="跨上角鹰兽，准备作战！"
D.Strings[15724]="<这头角鹰兽看上去已经急切地准备要走了！>"
D.Strings[15725]="你们准备好了吗？我会全力以赴。"
D.Strings[15726]="什么？你想要什么？"
D.Strings[15727]="快滚开，否则奇普·英代尔的老拳可就要砸在你脸上了！"
D.Strings[15728]="你好，$n$g先生:女士;。欢迎来到南海第一科赞贸易与商业银行。$B$B我能为你做些什么？"
D.Strings[15729]="呦！你看上去像是个有些品味的$g男人:女人; 。$B$B我能为你做些什么？"
D.Strings[15730]="这件首饰就像你的妈妈一样好！"
D.Strings[15731]="你已经来不及阻止我的计划了。"
D.Strings[15732]="注意不要让我被跟踪。"
D.Strings[15733]="非常荣幸。"
D.Strings[15734]="看看和我共事的都是什么人。苏扎博能弄出奇迹来吗？$B$B<苏扎博叹了口气>$B$B是的，是的，苏扎博认为他能为你做些事。"
D.Strings[15735]="苏扎博的服务不是你能负担得起的。我们可不提供免费服务，小家伙。$B$B还是先去银行吧。把你的杏仁币全都给苏扎博拿来。"
D.Strings[15736]="哦，看看苏扎博做了什么。真是杰作啊！$B$B说实话，你配不上这身行头，但苏扎博需要钱。<叹气>"
D.Strings[15737]="我这里有各种各样新款墨镜。你能叫出名字的，我都有的卖！"
D.Strings[15738]="什么？你看上去没有足够的钱能买我的东西。$B$B<米萨用嘴里的泡泡糖吹了个泡泡。>$B$B也许你忘记去银行了？"
D.Strings[15739]="好吧，我以优惠的价格把我最好的一副遮阳镜卖给你！$B$B它一定会让你爱不释手的！"
D.Strings[15740]="愚蠢的$c，你无法阻止克瓦迪尔！"
D.Strings[15741]="欢迎来到我的店铺。我们这里有你所需要的一切……如果你所需要的是炼金术材料……"
D.Strings[15742]="你真的有卖东西吗？"
D.Strings[15743]="不，我的脑子很不错，最好不要小看我。我能够用洗碗水和蒲公英配制出治疗药剂。不过这不是我要给你的东西！$b$b不管怎样，如果你想要买东西，就请和Patricia谈谈吧。"
D.Strings[15744]="要不要接受训练？"
D.Strings[15745]="%s用正义之锤对准了$n！"
D.Strings[15746]="%s开始向四周放射光芒！赶快遮住你的眼睛！"
D.Strings[15747]="一杯清新的香槟酒。这正是医生所叮嘱的，$n。"
D.Strings[15748]="感谢你给我斟酒，$g先生:女士;！"
D.Strings[15749]="这种发泡白酒真是美味！你是从哪里得到它的？"
D.Strings[15750]="我只能再喝这一杯了。聚会之后我还要开车回家。"
D.Strings[15751]="感谢！"
D.Strings[15752]="现在我觉得好多了……嗝！"
D.Strings[15753]="哦，我头痛得厉害。"
D.Strings[15754]="抱歉弄脏了你的鞋子。"
D.Strings[15755]="一场迪斯科舞会？！真棒！"
D.Strings[15756]="喜欢我的舞步吗，$n？"
D.Strings[15757]="我们应该痛快地跳一支舞！"
D.Strings[15758]="像地精巨星那样摇滚！"
D.Strings[15759]="喔！毫无疑问比我手上的小烟花精彩多了！"
D.Strings[15760]="你可真是大手笔$n！真令人惊叹！"
D.Strings[15761]="这是……最好的……聚会！"
D.Strings[15762]="喔，喔，焰火！再放一次，再放一次！"
D.Strings[15763]="谢谢，我几乎不行了。实在太饿了！"
D.Strings[15764]="这是我尝过的最好吃的开胃菜。$n，一定要告诉我你的厨艺秘方！"
D.Strings[15765]="啊，真是吮指回味！"
D.Strings[15766]="味道还不错！"
D.Strings[15767]="守卫大门！"
D.Strings[15768]="正义之锤！"
D.Strings[15769]="你的聚会客人一定会对你的穿着赞叹不已！使用下面的新能力来让你的聚会客人高兴吧！"
D.Strings[15770]="我还需要一个神谕者孤儿哨。"
D.Strings[15771]="让我们跳支舞吧！"
D.Strings[15772]="我们要向贸易大王表示礼貌。"
D.Strings[15773]="谁在这里管事？"
D.Strings[15774]="元素之灵是睿智的。在我们出现之前，他们早已经存在于此，在我们尽数消失之后，他们仍然会在这里长存不息。当他们对我们说话的时候，我们必须仔细倾听。"
D.Strings[15775]="元素之灵就在我们身边。我们必须时刻注意倾听他们的声音。我亲眼见到过当我们忽视他们的警告时，发生了怎样的灾难……"
D.Strings[15776]="塔伦迪斯古树痛苦地吼叫着！"
D.Strings[15777]="滚开，虫子。你不属于这个地方。不要激怒我。"
D.Strings[15778]="你怎么会来到这里，年轻的$r？请小心，我们的敌人正在从东边山脉中的一个窟窿里源源不断地涌出来。他们对这片土地造成了严重的伤害。"
D.Strings[15779]="再次感谢你能“帮助”那些懒家伙，老板。$B$B要我说，我们既然已经不再是那些巨魔的奴隶，就不应该对那些巨魔太仁慈。"
D.Strings[15780]="%s开始施放梦魇乍醒！"
D.Strings[15781]="我们会永远记住这次拜访。绝不要忘记你从新朋友那里学到了什么，小鲁鲁。远大的未来正在前方等着你。"
D.Strings[15782]="别担心，科科。你要长大，成为一名强壮的狂心者。你要率领族人返回旧日的家园。那里不会再有大舌头怪。"
D.Strings[15783]="我丢掉了紫罗兰要塞的钥匙。"
D.Strings[15784]="提里奥。"
D.Strings[15785]="瓦里安国王，吉安娜女士，欢迎你们的到来。我们恭候多时了。"
D.Strings[15786]="谢谢，这是我唯一能做的。我们需要同心协力。"
D.Strings[15787]="你说个不停，提里奥。要平心静气，要相信那些野人会管住自己。"
D.Strings[15788]="我的人在这里是为了确保比赛的井然有序。最好让你的部下知道你在看着他们。"
D.Strings[15789]="%s点点头，招手示意他的客人跟上。"
D.Strings[15790]="也许吧。我觉得这比赛没什么意义。我们现在就应该集结大军发动总攻。"
D.Strings[15791]="但如果我出席这些比赛能换来你在战争中的协助。那我暂时，会留下来。"
D.Strings[15792]="我相信萨尔会管住他的部下……"
D.Strings[15793]="的确会有人不再想获得经验。他们想永远停留在现有的水平，不再变得更强。$B$B我可以实现这一点……当然，我需要收取一些费用。$B$B但你要明白：一旦你把酬金支付给我，你就无法再获得经验了。是一直，而不是一段时间。$B$B如果你以后又改变主意，想要重新开始获取经验，也可以向我支付同样多的酬金，让我解除这一禁制。"
D.Strings[15794]="我已经不再想获得经验了。"
D.Strings[15795]="我希望能再次开始获取经验。"
D.Strings[15796]="这可真是令人惊叹。那么，你准备好迎接下一个挑战了么？"
D.Strings[15797]="今天，你在竞技场上的表现给所有人都留下了深刻的印象。现在，你将在万众瞩目下成为这次比武的冠军。"
D.Strings[15798]="我已经为下一个挑战做好了准备。"
D.Strings[15799]="干得漂亮！你的下一个挑战将来自于十字军的骑士们。他们将以强大的实力对你进行测试。"
D.Strings[15800]="正在走进竞技场的是一位对于战场和比武场都绝不陌生的圣骑士——银色十字军的总冠军，纯洁者耶德瑞克！"
D.Strings[15801]="接下来出场的是圣光最忠实的追随者！银色神官帕尔崔丝！"
D.Strings[15802]="干得好，今天，你证明了自己的实力。"
D.Strings[15803]="那些椽子旁边是什么？"
D.Strings[15804]="你搞砸了我的盛大登场，鼠辈。"
D.Strings[15805]="这是怎么回事？"
D.Strings[15806]="你们真以为，巫妖王的战士会败在你们那可怜的比武场上？"
D.Strings[15807]="我是来做个了断的。"
D.Strings[15808]="不要只是傻站在那里，干掉他！"
D.Strings[15809]="把他撕碎！"
D.Strings[15810]="加尔鲁什，我希望你能控制自己。我不想紫罗兰城堡的一幕再发生。"
D.Strings[15811]="哼！那只是领袖在展示他的力量。我真后悔没在那个法师插手前干掉那个人类。"
D.Strings[15812]="挥舞粗头棒子有什么荣誉可言？这是在浪费时间。"
D.Strings[15813]="别算上我，萨尔。"
